$c1pwHeld = [System.IO.File]::Open($c1pwGate, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try { $c1pwL2 = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-ARM' -Hook } finally { $c1pwHeld.Dispose(); $c1pwHeld = $null }
$c1pwL2Arm = Get-PwDetector -Text $c1pwL2.text -Type $pwType
