$c1pwHeld = New-Object System.IO.FileStream($c1pwPlaced, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
try { $c1pwL5 = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-ARM' } finally { $c1pwHeld.Dispose(); $c1pwHeld = $null }
Add-C1pwRow -Label '(l) the placement held by a writer that SHARES read access, its live gate readable: read, released, MET' `
