Write-Utf8 -Path (Join-Path $c1pwNoGit 'evidence\built.txt') -Text "built`n"
Write-PwGoal -Root $c1pwNoGit -GoalId 'G-ARM' -DetectorLines $c1pwArmGoal
$c1pwSavedCeiling = $env:GIT_CEILING_DIRECTORIES
$env:GIT_CEILING_DIRECTORIES = $c1pwM.base
try {
