    $c1pwL3 = Invoke-PwEval -Root $c1pwNoGit -GoalId 'G-ARM' -Hook
} finally {
    if ($null -ne $c1pwSavedCeiling) { $env:GIT_CEILING_DIRECTORIES = $c1pwSavedCeiling } else { Remove-Item Env:\GIT_CEILING_DIRECTORIES -ErrorAction SilentlyContinue }
}
$c1pwL3Arm = Get-PwDetector -Text $c1pwL3.text -Type $pwType
Add-C1pwRow -Label '(l) no repository (GIT_CEILING_DIRECTORIES bounds git''s search): ADMITTED, one UNDETERMINABLE line for the directory' `
    -Ok (($c1pwLProbe.exit -ne 0) -and $c1pwL3.admitted -and (@($c1pwL3.awaiting).Count -eq 1) -and (@($c1pwL3.awaiting)[0] -ceq ($pwPrefix + ' UNDETERMINABLE UNDETERMINABLE .mission/amendments/')) -and ($c1pwL3Arm.detail -match 'git could not list the tracked files')) `
    -Said ('probe rev-parse exit ' + $c1pwLProbe.exit + '; verdict ' + $c1pwL3.verdict + ', decision ' + $c1pwL3.decision + ', exit ' + $c1pwL3.exit + '; the arm: ' + $c1pwL3Arm.detail)
$c1pwDecoy = Join-Path $c1pwM.base 'decoy'
New-Item -ItemType Directory -Path $c1pwDecoy -Force | Out-Null
$null = Invoke-PwGit -Root $c1pwM.base -GitArgs @('init', '--quiet', $c1pwDecoy)
$c1pwDecoyGd = [System.IO.Path]::GetFullPath((Invoke-PwGit -Root $c1pwDecoy -GitArgs @('rev-parse', '--absolute-git-dir')).text.Trim().Replace('/', '\'))
$c1pwDecoyOk = ($c1pwDecoyGd -ieq [System.IO.Path]::GetFullPath((Join-Path $c1pwDecoy '.git')))
$c1pwSavedGitDir = $env:GIT_DIR
try {
    if ($c1pwDecoyOk) {
        $env:GIT_DIR = $c1pwDecoyGd
        $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
        try { $c1pwDecoyLs = @(& git -C $c1pwRoot ls-files -- .mission/amendments 2>&1); $c1pwDecoyLsExit = $LASTEXITCODE } finally { $ErrorActionPreference = $prevEap }
        $c1pwL4 = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-ARM' -Hook
    }
} finally {
    if ($null -ne $c1pwSavedGitDir) { $env:GIT_DIR = $c1pwSavedGitDir } else { Remove-Item Env:\GIT_DIR -ErrorAction SilentlyContinue }
}
Add-C1pwRow -Label '(l) GIT_DIR inherited, naming an EMPTY repository (where git lists 0 tracked amendments): the tracked two still admit nothing' `
    -Ok ($c1pwDecoyOk -and ($c1pwDecoyLsExit -eq 0) -and (@($c1pwDecoyLs | Where-Object { "$_".Trim() }).Count -eq 0) -and ($c1pwL4.verdict -ceq 'MET') -and ($c1pwL4.exit -eq 0)) `
    -Said ('decoy lists ' + @($c1pwDecoyLs | Where-Object { "$_".Trim() }).Count + '; verdict ' + $c1pwL4.verdict)
# ... and the other variables that would move the answer, each inherited alone.
$c1pwEnvCases = @(
    [pscustomobject]@{ name = 'GIT_INDEX_FILE'; value = (Join-Path $c1pwM.base 'no-such-index') },
    [pscustomobject]@{ name = 'GIT_WORK_TREE'; value = $c1pwDecoy },
