$c1pwCvGd = [System.IO.Path]::GetFullPath((Invoke-PwGit -Root $c1pwCv -GitArgs @('rev-parse', '--absolute-git-dir')).text.Trim().Replace('/', '\'))
if ($c1pwCvGd -ine [System.IO.Path]::GetFullPath((Join-Path $c1pwCv '.git'))) { throw ('FIXTURE REFUSED: the case fixture git dir is ' + $c1pwCvGd) }
Write-Utf8 -Path (Join-Path $c1pwCv '.mission\Amendments\AM-791-c1x.yaml') -Text "id: AM-791`n"
Write-Utf8 -Path (Join-Path $c1pwCv 'Sub\.mission\Amendments\AM-792-c1x.yaml') -Text "id: AM-792`n"
