$c1pwCvCommitArgs = @('-c', 'user.name=wp3-pw', '-c', 'user.email=wp3-pw@example.invalid', '-c', 'commit.gpgsign=false', 'commit', '--quiet', '-m', 'case')
$c1pwCvCommit = Invoke-PwGit -Root $c1pwCv -GitArgs $c1pwCvCommitArgs
Rename-Item -LiteralPath (Join-Path $c1pwCv '.mission\Amendments') -NewName 'amendments-tmp'
