$c1pwCvSub = Invoke-PwEval -Root (Join-Path $c1pwCv 'sub') -GoalId 'G-ARM'
Add-C1pwRow -Label '(l) FIXTURE the index spells .mission/Amendments and Sub/, the disk amendments and sub, and git reads them unchanged' `
    -Ok (($c1pwCvAdd.exit -eq 0) -and ($c1pwCvCommit.exit -eq 0) -and ($c1pwCvLs.text -cmatch '\.mission/Amendments/AM-791-c1x\.yaml') -and ($c1pwCvLs.text -cmatch 'Sub/\.mission/Amendments/AM-792-c1x\.yaml') -and (-not $c1pwCvDirty.text.Trim())) `
    -Said ($c1pwCvLs.text + ' | status: [' + $c1pwCvDirty.text.Trim() + ']')
Add-C1pwRow -Label '(l) at the repository root, the case-variant tracked amendment admits nothing: MET, 1 tracked' `
    -Ok (($c1pwCvTop.verdict -ceq 'MET') -and ((Get-PwDetector -Text $c1pwCvTop.text -Type $pwType).detail -match '1 tracked file\(s\)')) -Said ((Get-PwDetector -Text $c1pwCvTop.text -Type $pwType).detail)
Add-C1pwRow -Label '(l) at a mission root in the case-variant SUBDIRECTORY, likewise: MET, 1 tracked' `
    -Ok (($c1pwCvSub.verdict -ceq 'MET') -and ((Get-PwDetector -Text $c1pwCvSub.text -Type $pwType).detail -match '1 tracked file\(s\)')) -Said ((Get-PwDetector -Text $c1pwCvSub.text -Type $pwType).detail)

# (m) A GOAL WITHOUT THE TYPE behaves exactly as today: this tree's evaluator against the base
#     evaluator, each file pinned by its LF/blob sha256, over the same placement.
$c1pwBaseSha = '700e19e5-s13'
$c1pwPins = [ordered]@{
    'mission-goal-check.ps1'   = 'de4314a8e222130d9479e9598d7b4ddd3c2bf92016add66f40b254adb1d822ac'
    'lam-verify-admission.ps1' = 'ccd0d7d1656a0dba4187585d5e583d604e3c65882c094c7df704b800f4d4ba58'
    'lam-gate-class.ps1'       = 'bc7a3cd885709c5df5661f3a5cd308b878e7d63e89246a43e3d029278247e577'
    'lam-instrument-run.ps1'   = 'ecf28251ba9a98bf599513d85a5d6999874d13b09ea4ce62dbf7af47a8369245'
}
$c1pwBaseDir = Join-Path $c1pwM.base 'base-tools'
New-Item -ItemType Directory -Path $c1pwBaseDir -Force | Out-Null
$c1pwPinOk = $true
$c1pwPinSaid = New-Object System.Collections.Generic.List[string]
foreach ($c1pwPinName in @($c1pwPins.Keys)) {
    # Through Get-LamBaseBytes: the installed fixtures alone, no history -- the pin decides.
    $c1pwRead = Get-LamBaseBytes -Base $c1pwBaseSha -Path ('tools/lam/' + $c1pwPinName) -Pin $c1pwPins[$c1pwPinName]
    if (-not $c1pwRead.ok) { $c1pwPinOk = $false }
    $c1pwPinSaid.Add($c1pwPinName + ' ' + $c1pwRead.sha.Substring(0, 8) + ' (' + $c1pwRead.from + ')')
    [System.IO.File]::WriteAllBytes((Join-Path $c1pwBaseDir $c1pwPinName), $c1pwRead.bytes)
}
$c1pwBaseEval = Join-Path $c1pwBaseDir 'mission-goal-check.ps1'
Add-C1pwRow -Label 'FIXTURE the base evaluator and its three libraries, each at its pinned LF/blob sha256' -Ok $c1pwPinOk -Said ($c1pwPinSaid -join ', ')
Write-Utf8 -Path $c1pwPlaced -Text $c1pwPlacedText
$c1pwNoArmGoal = @('  - type: file_exists', '    path: evidence/built.txt', '  - type: halt_absent')
Write-PwGoal -Root $c1pwRoot -GoalId 'G-NOARM' -DetectorLines $c1pwNoArmGoal
$c1pwMaskAt = '(?m)^evaluated_at: .*$'
$c1pwTreeCli = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-NOARM'
$c1pwTreeCliText = Remove-WrProvenanceLine -Text (($c1pwTreeCli.text -replace $c1pwMaskAt, 'evaluated_at: MASKED') -replace $wjScanMask, '')
$c1pwBaseCli = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-NOARM' -Evaluator $c1pwBaseEval
$c1pwBaseCliText = $c1pwBaseCli.text -replace $c1pwMaskAt, 'evaluated_at: MASKED'
$c1pwTreeHook = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-NOARM' -Hook
$c1pwBaseHook = Invoke-PwEval -Root $c1pwRoot -GoalId 'G-NOARM' -Hook -Evaluator $c1pwBaseEval
Add-C1pwRow -Label '(m) CONTROL no type declared, the placement on disk: the tree and the base read MET, exit 0, the SAME artifact (evaluated_at masked)' `
    -Ok ($c1pwPinOk -and ($c1pwTreeCli.verdict -ceq 'MET') -and ($c1pwBaseCli.verdict -ceq 'MET') -and ($c1pwTreeCli.exit -eq 0) -and ($c1pwBaseCli.exit -eq 0) -and ($c1pwTreeCliText -ceq $c1pwBaseCliText) -and (-not $c1pwTreeCli.keyPresent)) `
    -Said ('tree ' + $c1pwTreeCli.verdict + '/' + $c1pwTreeCli.exit + ', base ' + $c1pwBaseCli.verdict + '/' + $c1pwBaseCli.exit + '; artifacts identical: ' + ($c1pwTreeCliText -ceq $c1pwBaseCliText) + '; awaiting key written: ' + $c1pwTreeCli.keyPresent)
Add-C1pwRow -Label '(m) CONTROL and the hook decision is the SAME JSON from both, both exiting 0' `
    -Ok ($c1pwPinOk -and ($c1pwTreeHook.decision -ceq 'approve') -and ($c1pwTreeHook.exit -eq 0) -and ($c1pwBaseHook.exit -eq 0) -and ($c1pwTreeHook.out.Trim() -ceq $c1pwBaseHook.out.Trim())) `
    -Said ('tree: ' + $c1pwTreeHook.out.Trim() + ' | base: ' + $c1pwBaseHook.out.Trim())
}
catch {
    $c1pwOk = $false
    $c1pwRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
