}
if ($null -ne $c1pwHeld) { try { $c1pwHeld.Dispose() } catch { } }
if (($null -ne $c1pwM) -and (Test-Path -LiteralPath $c1pwM.base)) { try { Remove-Item -LiteralPath $c1pwM.base -Recurse -Force -ErrorAction Stop } catch { } }
Check -Id 'C-1x' -Title 'THE PLACEMENT-WINDOW ARM, detector type ungated_placement_absent (LAM-ACCEPT amendment 54, operator ruling (ii), and the operator''s rulings of 2026-09-24): a goal declaring the type is not refused as unknown; with an untracked amendment under .mission/amendments/ that no canonical, unrevoked amendment-material gate binds -- by its LF/blob sha256 (git''s own blob, measured) or its working-copy sha256 -- and no open HALT, the evaluator reads AWAITING_AMENDMENT_GATE, the Stop hook approves and exits 0, and the verdict artifact, the hand-run status (exit 4) and the hook reason each carry "AWAITING AMENDMENT GATE <id> <sha256> <path>", and the printed mint parses as one statement, also for names carrying an apostrophe, a curly quote with an injection attempt, brackets, a subexpression and a backtick; controls, each its own row: a tracked amendment (one named in a non-ASCII letter) does not admit; a canonical gate over the exact bytes releases although its expires_at is past, its consumed_at set, or its binds: names another file; the same text of another kind, renamed aside, or carrying another id: -- or the same id in another case -- does not; a gate over other bytes and a revoked gate do not, and reapprove is printed for them; untracked files in three other directories do not admit, and two placements deriving one short id are printed under distinct ids; the arm declared last is listed and evaluated first and in hook mode the instrument never runs, also when the goal is otherwise unmet; a HALT still outranks it and names it; the line''s digest is git''s own blob for text, binary, lone-CR, ratio and final-0x1A samples, and a gate over either digest of a CR LF placement releases it; an unreadable placement, an unreadable gate, a directory link and a mission root git cannot answer for each ADMIT, the cause in the line, while a sharing writer hides nothing; GIT_DIR, GIT_INDEX_FILE, GIT_WORK_TREE and GIT_LITERAL_PATHSPECS inherited do not move the answer, nor an index spelling the directory in another case, at the root or for a mission root in a subdirectory; and a goal without the type writes the artifact and decision the base evaluator writes' `
      -Ok $c1pwOk -Detail ("      THE $(@($c1pwRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1pwRows -join "`n"))

# =============================================================================================
# C-2d -- THE ADMITTED STOPS: the page and the evaluator agree
# =============================================================================================
# THE PAGE'S SIDE is READ inside its `### WP-3` section: C-1's verdict set (`verdict: A|B|...`) and
# C-2's enumeration of what a seat may stop on, from "A seat may stop on exactly" to "alone." -- its
# start counted there exactly once, its count word checked against the verdicts it lists. When the
# page carries no such sentence (it did not in an earlier revision), the admitted set is read the only
# way the older text allows -- C-1's set less the verdict C-2 blocks on -- and the PAGE row fails.
# THE EVALUATOR'S SIDE is DRIVEN in hook mode over four fixture goals: a met goal, an unmet one, one
# with an open HALT, and one declaring the arm with an untracked, ungated amendment on disk -- AND, SINCE
# A LATER REVISION, THREE MORE: one declaring the dispatch-manifest arm with
# an untracked, ungated round manifest on disk, one declaring the handoff arm with a HANDOFF head over a
# brief on disk, and a goal id with no file at either location. A drive
# counts as an ADMITTED stop only when the hook approves AND exits 0 (exit 2 blocks whatever the JSON
# says). The member fails when the two sides name different verdicts, admitted stops or blocked
# verdicts, when either side lacks the ruled third stop, or when the page's C-1 does not name the type.
$c2pwOk = $true
$c2pwRows = New-Object System.Collections.Generic.List[string]
function Add-C2pwRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c2pwOk = $false }
    $script:c2pwRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c2pwRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Read-C2pwStopSentence {
    # The enumeration inside one text, whitespace collapsed first (the page wraps its lines).
    param([string]$Text)
    $c2pwFlat = ($Text -replace '\s+', ' ')
    $c2pwCountWords = @{ 'one' = 1; 'two' = 2; 'three' = 3; 'four' = 4; 'five' = 5; 'six' = 6 }
    $c2pwRead = [pscustomobject]@{ starts = ([regex]::Matches($c2pwFlat, 'A seat may stop on exactly')).Count; found = $false
                                   word = ''; declared = -1; admitted = @(); blocked = @(); agrees = $false; sentence = '' }
    $c2pwSm = [regex]::Match($c2pwFlat, 'A seat may stop on exactly \*\*(?<word>[a-z]+)\*\* verdicts,(?<adm>.*?)and the hook blocks on (?<blk>.*?) alone\.')
    if (-not $c2pwSm.Success) { return $c2pwRead }
    $c2pwRead.found = $true
    $c2pwRead.sentence = $c2pwSm.Value
    $c2pwRead.word = $c2pwSm.Groups['word'].Value
    if ($c2pwCountWords.ContainsKey($c2pwRead.word)) { $c2pwRead.declared = $c2pwCountWords[$c2pwRead.word] }
    $c2pwRead.admitted = @([regex]::Matches($c2pwSm.Groups['adm'].Value, '`([A-Z][A-Z_]*)`') | ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique)
    $c2pwRead.blocked = @([regex]::Matches($c2pwSm.Groups['blk'].Value, '`([A-Z][A-Z_]*)`') | ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique)
    $c2pwRead.agrees = ($c2pwRead.declared -eq @($c2pwRead.admitted).Count)
    return $c2pwRead
}
function Get-C2pwSetText {
    param([object[]]$Items)
    return ((@($Items | Where-Object { $_ } | Sort-Object -Unique)) -join '|')
}
$c2pwM = $null
$c2pwRecord = Get-LamAcceptRecord
try {
# ---- THE PARSER'S OWN CONTROLS -------------------------------------------------------------------
$c2pwLit3 = 'A seat may stop on exactly **three** verdicts, `MET`, `HALT` (C-3) and `AWAITING_AMENDMENT_GATE`, and the hook blocks on `NOT_MET` alone.'
$c2pwLit2 = 'A seat may stop on exactly **two** verdicts, `MET` and `HALT`, and the hook blocks on `NOT_MET` alone.'
$c2pwLitBad = 'A seat may stop on exactly **two** verdicts, `MET`, `HALT` and `AWAITING_AMENDMENT_GATE`, and the hook blocks on `NOT_MET` alone.'
$c2pwLitNone = 'The hook returns the blocking decision when NOT_MET.'
$c2pwP3 = Read-C2pwStopSentence -Text $c2pwLit3
$c2pwP2 = Read-C2pwStopSentence -Text $c2pwLit2
$c2pwPB = Read-C2pwStopSentence -Text $c2pwLitBad
$c2pwPN = Read-C2pwStopSentence -Text $c2pwLitNone
Add-C2pwRow -Label 'PARSER a three-verdict sentence reads MET, HALT, AWAITING_AMENDMENT_GATE admitted and NOT_MET blocked' `
    -Ok ($c2pwP3.found -and $c2pwP3.agrees -and ((Get-C2pwSetText $c2pwP3.admitted) -ceq 'AWAITING_AMENDMENT_GATE|HALT|MET') -and ((Get-C2pwSetText $c2pwP3.blocked) -ceq 'NOT_MET')) -Said ''
Add-C2pwRow -Label 'PARSER a two-verdict sentence reads MET, HALT' -Ok ($c2pwP2.found -and $c2pwP2.agrees -and ((Get-C2pwSetText $c2pwP2.admitted) -ceq 'HALT|MET')) -Said ''
Add-C2pwRow -Label 'PARSER a sentence whose count word disagrees with its list does not agree' -Ok ($c2pwPB.found -and (-not $c2pwPB.agrees)) -Said ''
Add-C2pwRow -Label 'PARSER a text with no enumeration reads not-found' -Ok (-not $c2pwPN.found) -Said ''
# ... and the SIX-verdict sentence of the later revision: the three stops it adds are
#     read as verdicts, and nothing else in its parentheses is (a type name is lower-case; "a HANDOFF head" carries
#     no back-ticks).
$c2pwSix = @('MET', 'HALT', 'AWAITING_AMENDMENT_GATE', 'AWAITING_DISPATCH_GATE', 'HANDOFF_ADMITTED', 'GOAL_ABSENT')
$c2pwLit6 = 'A seat may stop on exactly **six** verdicts, `MET`, `HALT` (C-3), `AWAITING_AMENDMENT_GATE` (the goal declares `ungated_placement_absent`), `AWAITING_DISPATCH_GATE` and `HANDOFF_ADMITTED` (the goal declares `ungated_manifest_absent`, or `handoff_brief_present` and the first line is a HANDOFF head) and `GOAL_ABSENT`, and the hook blocks on `NOT_MET` alone.'
$c2pwP6 = Read-C2pwStopSentence -Text $c2pwLit6
Add-C2pwRow -Label 'PARSER a six-verdict sentence reads the six admitted, NOT_MET blocked, and no type name or prose word as a verdict' `
    -Ok ($c2pwP6.found -and $c2pwP6.agrees -and ((Get-C2pwSetText $c2pwP6.admitted) -ceq (Get-C2pwSetText $c2pwSix)) -and ((Get-C2pwSetText $c2pwP6.blocked) -ceq 'NOT_MET')) `
    -Said ('admitted ' + (Get-C2pwSetText $c2pwP6.admitted))

# ---- THE PAGE, READ INSIDE ITS ### WP-3 SECTION ----------------------------------------------------
$c2pwPage = $c2pwRecord.text
$c2pwSec = [regex]::Match($c2pwPage, '(?ms)^### WP-3 .*?(?=^### WP-4 )')
$c2pwSecText = if ($c2pwSec.Success) { $c2pwSec.Value } else { '' }
$c2pwSetM = [regex]::Match($c2pwSecText, 'verdict: (?<set>[A-Z_]+(?:\|[A-Z_]+)+)')
$c2pwPageSet = if ($c2pwSetM.Success) { @($c2pwSetM.Groups['set'].Value -split '\|') } else { @() }
$c2pwStop = Read-C2pwStopSentence -Text $c2pwSecText
$c2pwPageAdmitted = @()
$c2pwPageBlocked = @()
if ($c2pwStop.found) {
    $c2pwPageAdmitted = @($c2pwStop.admitted)
    $c2pwPageBlocked = @($c2pwStop.blocked)
} else {
    if (($c2pwSecText -replace '\s+', ' ') -match 'when NOT_MET') { $c2pwPageBlocked = @('NOT_MET') }
    $c2pwPageAdmitted = @($c2pwPageSet | Where-Object { $c2pwPageBlocked -notcontains $_ })
}
Add-C2pwRow -Label ('PAGE the ### WP-3 section states C-1''s verdict set: ' + (Get-C2pwSetText $c2pwPageSet)) -Ok ($c2pwSec.Success -and ($c2pwPageSet.Count -ge 3)) -Said ''
Add-C2pwRow -Label ('PAGE the stop-admission enumeration starts exactly once there (found ' + $c2pwStop.starts + ') and its count word "' + $c2pwStop.word + '" matches its list') `
    -Ok ($c2pwStop.found -and ($c2pwStop.starts -eq 1) -and $c2pwStop.agrees) `
    -Said $(if ($c2pwStop.found) { $c2pwStop.sentence } else { 'NOT FOUND -- the admitted set below is C-1''s set less the verdict C-2 blocks on' })

# ---- THE EVALUATOR, DRIVEN ---------------------------------------------------------------------------
$c2pwM = New-PwMission -Tag 'c2d'
if (-not $c2pwM.ok) { throw ('FIXTURE REFUSED: ' + $c2pwM.why) }
$c2pwRoot = $c2pwM.root
Write-PwGoal -Root $c2pwRoot -GoalId 'G-MET' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c2pwRoot -GoalId 'G-NOT' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt')
Write-PwGoal -Root $c2pwRoot -GoalId 'G-HALT' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt')
$c2pwAwaitGoal = @(('  - type: ' + $pwType))
Write-PwGoal -Root $c2pwRoot -GoalId 'G-AWAIT' -DetectorLines $c2pwAwaitGoal
$c2pwDrives = New-Object System.Collections.Generic.List[object]
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-MET'; r = (Invoke-PwEval -Root $c2pwRoot -GoalId 'G-MET' -Hook) })
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-NOT'; r = (Invoke-PwEval -Root $c2pwRoot -GoalId 'G-NOT' -Hook) })
Write-Utf8 -Path (Join-Path $c2pwRoot '.mission-runtime\halts\HALT-C2D.md') -Text "# HALT-C2D`n`n**Status:** OPEN`n"
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-HALT'; r = (Invoke-PwEval -Root $c2pwRoot -GoalId 'G-HALT' -Hook) })
Remove-Item -LiteralPath (Join-Path $c2pwRoot '.mission-runtime') -Recurse -Force
Write-Utf8 -Path (Join-Path $c2pwRoot '.mission\amendments\AM-778-c2d.yaml') -Text "id: AM-778-c2d`nnote: placed by WP-3 C-2d`n"
$c2pwAwait = Invoke-PwEval -Root $c2pwRoot -GoalId 'G-AWAIT' -Hook
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-AWAIT'; r = $c2pwAwait })
# ---- THE THREE LATER STOPS, each its own fixture goal --------
# G-DISP declares the dispatch-manifest arm alone, an untracked and ungated round manifest on disk; G-HAND the
# handoff arm over an otherwise UNMET goal, STATUS.md's first line a HANDOFF head over a brief on disk; G-GONE
# is a goal id with no file at either location. (The names are written out: this member runs before the
# package's own helpers are defined.)
Write-PwGoal -Root $c2pwRoot -GoalId 'G-DISP' -DetectorLines @('  - type: ungated_manifest_absent')
Write-Utf8 -Path (Join-Path $c2pwRoot '.mission\dispatches\D-V-C2D.manifest.yaml') -Text "id: v-c2d-r1`nkind: validator-manifest`n"
$c2pwDisp = Invoke-PwEval -Root $c2pwRoot -GoalId 'G-DISP' -Hook
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-DISP'; r = $c2pwDisp })
Write-PwGoal -Root $c2pwRoot -GoalId 'G-HAND' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', '  - type: handoff_brief_present')
$c2pwBrief = Join-Path $c2pwRoot '.mission-runtime\lam\handoff\brief-c2d.md'
Write-Utf8 -Path $c2pwBrief -Text "the brief C-2d hands off on`n"
$c2pwBriefSha = Get-PwRawSha -Path $c2pwBrief
Write-Utf8 -Path (Join-Path $c2pwRoot '.mission-runtime\lam\STATUS.md') -Text ('HANDOFF AT 70% ' + $c2pwBriefSha + '; ' + $c2pwBriefSha + " .mission-runtime/lam/handoff/brief-c2d.md`n`nthe edition's brief`n")
$c2pwHand = Invoke-PwEval -Root $c2pwRoot -GoalId 'G-HAND' -Hook
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-HAND'; r = $c2pwHand })
$c2pwGone = Invoke-PwEval -Root $c2pwRoot -GoalId 'G-GONE' -Hook
$c2pwDrives.Add([pscustomobject]@{ goal = 'G-GONE'; r = $c2pwGone })
$c2pwDriveSaid = @($c2pwDrives | ForEach-Object { $_.goal + '=' + $_.r.verdict + '/' + $_.r.decision + '/exit ' + $_.r.exit }) -join ', '
$c2pwDrivesOk = (@($c2pwDrives | Where-Object { ($_.r.verdict -match '\A[A-Z_]+\z') -and (@('approve', 'block') -contains $_.r.decision) }).Count -eq 7)
Add-C2pwRow -Label 'EVALUATOR seven hook-mode drives, each wrote a verdict and emitted a decision' -Ok $c2pwDrivesOk -Said $c2pwDriveSaid
$c2pwEvalSet = @($c2pwDrives | ForEach-Object { $_.r.verdict })
$c2pwEvalAdmit = @($c2pwDrives | Where-Object { ($_.r.decision -ceq 'approve') -and ($_.r.exit -eq 0) } | ForEach-Object { $_.r.verdict })
$c2pwEvalBlock = @($c2pwDrives | Where-Object { ($_.r.decision -ceq 'block') -or ($_.r.exit -ne 0) } | ForEach-Object { $_.r.verdict })
$c2pwConsistent = (@($c2pwEvalAdmit | Where-Object { $c2pwEvalBlock -contains $_ }).Count -eq 0)
Add-C2pwRow -Label 'EVALUATOR no verdict was both admitted and blocked' -Ok $c2pwConsistent -Said ''

# ---- AGREEMENT ---------------------------------------------------------------------------------------
Add-C2pwRow -Label ('AGREE the verdict set: the page ' + (Get-C2pwSetText $c2pwPageSet) + ', the evaluator ' + (Get-C2pwSetText $c2pwEvalSet)) `
    -Ok ((Get-C2pwSetText $c2pwPageSet) -ceq (Get-C2pwSetText $c2pwEvalSet)) -Said ''
Add-C2pwRow -Label ('AGREE the admitted stops: the page ' + (Get-C2pwSetText $c2pwPageAdmitted) + ', the evaluator ' + (Get-C2pwSetText $c2pwEvalAdmit)) `
    -Ok ((Get-C2pwSetText $c2pwPageAdmitted) -ceq (Get-C2pwSetText $c2pwEvalAdmit)) -Said ''
Add-C2pwRow -Label ('AGREE the blocked verdicts: the page ' + (Get-C2pwSetText $c2pwPageBlocked) + ', the evaluator ' + (Get-C2pwSetText $c2pwEvalBlock)) `
    -Ok ((Get-C2pwSetText $c2pwPageBlocked) -ceq (Get-C2pwSetText $c2pwEvalBlock)) -Said ''
Add-C2pwRow -Label ('RULED the page admits the third stop, ' + $pwVerdict) -Ok ($c2pwPageAdmitted -ccontains $pwVerdict) -Said ''
Add-C2pwRow -Label ('RULED the evaluator admits it: the placement drive reads ' + $c2pwAwait.verdict + ', ' + $c2pwAwait.decision + ', exit ' + $c2pwAwait.exit) `
    -Ok $c2pwAwait.admitted -Said ''
$c2pwTypeOnPage = [bool](($c2pwSecText -replace '\s+', ' ') -match ('`' + $pwType + '`'))
Add-C2pwRow -Label ('TYPE the page''s WP-3 section names `' + $pwType + '` and the evaluator does not refuse it as unknown') `
    -Ok ($c2pwTypeOnPage -and ($c2pwAwait.text -notmatch 'UNKNOWN detector type')) -Said ('on the page: ' + $c2pwTypeOnPage)
$c2pwCites = $c2pwStop.found -and [bool]($c2pwStop.sentence -match 'amendment 54') -and [bool]($c2pwStop.sentence -match 'ruling \(ii\)') -and [bool]($c2pwStop.sentence -match '\b1404\b')
Add-C2pwRow -Label 'CITES the enumeration names amendment 54, ruling (ii) and ledger 1404' -Ok $c2pwCites -Said ''
# ---- THE LATER REVISION: the three further stops, the page and the evaluator each ---------------------------------
$c2pwNewStops = @(
    [pscustomobject]@{ verdict = 'AWAITING_DISPATCH_GATE'; r = $c2pwDisp; what = 'the dispatch-manifest drive' },
    [pscustomobject]@{ verdict = 'HANDOFF_ADMITTED'; r = $c2pwHand; what = 'the handoff drive' },
    [pscustomobject]@{ verdict = 'GOAL_ABSENT'; r = $c2pwGone; what = 'the absent-goal drive' })
foreach ($c2pwNs in $c2pwNewStops) {
    Add-C2pwRow -Label ('RULED the page admits ' + $c2pwNs.verdict) -Ok ($c2pwPageAdmitted -ccontains $c2pwNs.verdict) -Said ''
    Add-C2pwRow -Label ('RULED the evaluator admits it: ' + $c2pwNs.what + ' reads ' + $c2pwNs.r.verdict + ', ' + $c2pwNs.r.decision + ', exit ' + $c2pwNs.r.exit) `
        -Ok (($c2pwNs.r.verdict -ceq $c2pwNs.verdict) -and ($c2pwNs.r.decision -ceq 'approve') -and ($c2pwNs.r.exit -eq 0)) -Said ''
}
foreach ($c2pwNt in @('ungated_manifest_absent', 'handoff_brief_present')) {
    $c2pwNtOnPage = [bool](($c2pwSecText -replace '\s+', ' ') -match ('`' + $c2pwNt + '`'))
    Add-C2pwRow -Label ('TYPE the page''s WP-3 section names `' + $c2pwNt + '` and the evaluator does not refuse it as unknown') `
        -Ok ($c2pwNtOnPage -and ($c2pwDisp.text -notmatch 'UNKNOWN detector type') -and ($c2pwHand.text -notmatch 'UNKNOWN detector type')) -Said ('on the page: ' + $c2pwNtOnPage)
}
$c2pwCites60 = $c2pwStop.found -and [bool]($c2pwStop.sentence -match 'amendment 60') -and [bool]($c2pwStop.sentence -match 'register rows 352 and 353') -and [bool]($c2pwStop.sentence -match 'register row 341') -and [bool]($c2pwStop.sentence -match '\b1474\b')
Add-C2pwRow -Label 'CITES the enumeration names amendment 60, register rows 352 and 353, register row 341 and ledger 1474' -Ok $c2pwCites60 -Said ''
}
catch {
    $c2pwOk = $false
    $c2pwRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c2pwRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if (($null -ne $c2pwM) -and (Test-Path -LiteralPath $c2pwM.base)) { try { Remove-Item -LiteralPath $c2pwM.base -Recurse -Force -ErrorAction Stop } catch { } }
Check -Id 'C-2d' -Title 'THE ADMITTED STOPS, PAGE AND EVALUATOR AGREE (LAM-ACCEPT amendment 54, operator ruling (ii)): the page''s stop-admission enumeration, read inside its ### WP-3 section from "A seat may stop on exactly" -- its start counted there exactly once, its count word checked against its list -- and C-1''s verdict set, against the evaluator''s answers DRIVEN in hook mode over seven fixture goals (met, unmet, an open HALT, an untracked and ungated amendment; and, by LAM-ACCEPT amendment 60, an untracked and ungated round manifest, a HANDOFF head over a brief on disk, and a goal id with no file), a drive counting as an admitted stop only when the hook approves AND exits 0, must name the same verdicts, the same admitted stops and the same blocked verdict; both must admit the ruled third stop, AWAITING_AMENDMENT_GATE, and amendment 60''s three, AWAITING_DISPATCH_GATE, HANDOFF_ADMITTED and GOAL_ABSENT; the page''s WP-3 section must name each of the three types the evaluator knows; the enumeration must cite amendment 54, ruling (ii) and ledger 1404, and amendment 60, register rows 352 and 353, register row 341 and ledger 1474; and the parser is put to five literal sentences first' `
      -Ok $c2pwOk -Skipped:(-not $c2pwRecord.ok) -Detail ($(if ($c2pwRecord.ok) { '' } else { "      SKIPPED: the contract is not here -- $($c2pwRecord.from)`n" }) + "      THE $(@($c2pwRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c2pwRows -join "`n") + "`n      the contract, read from: $($c2pwRecord.from)")

# =============================================================================================
# C-3f -- THE RESIDUAL, MEASURED: any file placed there obtains the stop, and nothing placed elsewhere
# =============================================================================================
# THE RESIDUAL THE RULING STATES (per design v2.3 SS4.5 law 2): "a seat can obtain a stop by placing a
# file, as it can today by writing a HALT; an unratified placement can sit, as an open HALT can." Both
# halves are driven, and the claim is held to its stated width: SEVEN files that are not amendments in
# any sense but their location admit -- one dated 2001, one git IGNORES, one named with spaces and
# brackets -- on all three status surfaces, and SEVEN untracked files in six other places admit nothing. The last row shows what bounds it: a canonical gate over an arbitrary
# file's bytes releases it (forged here; the console mint is WP-4 T-37's).
$c3pwOk = $true
$c3pwRows = New-Object System.Collections.Generic.List[string]
function Add-C3pwRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c3pwOk = $false }
    $script:c3pwRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c3pwRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c3pwM = $null
try {
$c3pwM = New-PwMission -Tag 'c3f'
if (-not $c3pwM.ok) { throw ('FIXTURE REFUSED: ' + $c3pwM.why) }
$c3pwRoot = $c3pwM.root
$c3pwGoal = @(('  - type: ' + $pwType))
Write-PwGoal -Root $c3pwRoot -GoalId 'G-RES' -DetectorLines $c3pwGoal
Write-Utf8 -Path (Join-Path $c3pwRoot '.gitignore') -Text "*.swp`n"
$c3pwBin = New-Object byte[] 256
for ($c3pwI = 0; $c3pwI -lt 256; $c3pwI++) { $c3pwBin[$c3pwI] = [byte]$c3pwI }
$c3pwFiles = @(
    [pscustomobject]@{ rel = '.mission/amendments/zz-arbitrary.bin'; id = 'zz-arbitrary'; bytes = $c3pwBin; label = 'a BINARY file of 256 bytes, no amendment in any sense' },
    [pscustomobject]@{ rel = '.mission/amendments/empty'; id = 'empty'; bytes = [byte[]]@(); label = 'an EMPTY file with no extension' },
    [pscustomobject]@{ rel = '.mission/amendments/deep/er/notes.txt'; id = 'notes'; bytes = $pwUtf8.GetBytes("not an amendment`n"); label = 'a file TWO directories down' },
    [pscustomobject]@{ rel = '.mission/amendments/.hidden-placement'; id = 'hidden-placement'; bytes = $pwUtf8.GetBytes("hidden`n"); label = 'a file with the HIDDEN attribute' },
    [pscustomobject]@{ rel = '.mission/amendments/AM-990-ancient.yaml'; id = 'am-990'; bytes = $pwUtf8.GetBytes("id: AM-990`n"); label = 'a placement dated 2001-01-01: an unratified placement can sit' },
    [pscustomobject]@{ rel = '.mission/amendments/draft.swp'; id = 'draft'; bytes = $pwUtf8.GetBytes("editor swap`n"); label = 'a file git IGNORES (.gitignore: *.swp) -- untracked all the same' },
    [pscustomobject]@{ rel = '.mission/amendments/Draft v2 (final).md'; id = 'draft-v2-final'; bytes = $pwUtf8.GetBytes("a name with spaces and brackets`n"); label = 'a name with spaces and brackets, its <id> reduced to one token' }
)
foreach ($c3pwF in $c3pwFiles) { Set-PwBytes -Path (Join-Path $c3pwRoot $c3pwF.rel.Replace('/', '\')) -Bytes $c3pwF.bytes }
$c3pwHidden = Get-Item -LiteralPath (Join-Path $c3pwRoot '.mission\amendments\.hidden-placement') -Force
$c3pwHidden.Attributes = ($c3pwHidden.Attributes -bor [System.IO.FileAttributes]::Hidden)
$c3pwOld = Join-Path $c3pwRoot '.mission\amendments\AM-990-ancient.yaml'
[System.IO.File]::SetCreationTimeUtc($c3pwOld, [DateTime]::new(2001, 1, 1, 0, 0, 0, [DateTimeKind]::Utc))
[System.IO.File]::SetLastWriteTimeUtc($c3pwOld, [DateTime]::new(2001, 1, 1, 0, 0, 0, [DateTimeKind]::Utc))
$c3pwSt = Invoke-PwGit -Root $c3pwRoot -GitArgs @('status', '--porcelain', '--ignored', '--untracked-files=all', '--', '.mission/amendments')
$c3pwStUntracked = @(($c3pwSt.text -split "`n") | Where-Object { $_ -match '^\?\? ' }).Count
$c3pwStIgnored = @(($c3pwSt.text -split "`n") | Where-Object { $_ -match '^!! \.mission/amendments/draft\.swp$' }).Count
Add-C3pwRow -Label ('FIXTURE git reads ' + $c3pwStUntracked + ' of 6 placements untracked and draft.swp IGNORED (' + $c3pwStIgnored + '); no gate is on disk') `
    -Ok (($c3pwStUntracked -eq 6) -and ($c3pwStIgnored -eq 1) -and (@(Get-ChildItem -LiteralPath (Join-Path $c3pwRoot '.mission\gates') -File -Force).Count -eq 0)) -Said $c3pwSt.text
$c3pwA = Invoke-PwEval -Root $c3pwRoot -GoalId 'G-RES' -Hook
$c3pwAHand = Invoke-PwEval -Root $c3pwRoot -GoalId 'G-RES'
$c3pwHandLines = @(($c3pwAHand.out -replace "`r", '') -split "`n")
$c3pwHandHead = [array]::IndexOf($c3pwHandLines, ('mission-goal-check: G-RES -> ' + $pwVerdict))
$c3pwHandUnder = New-Object System.Collections.Generic.List[string]
if ($c3pwHandHead -ge 0) {
    for ($c3pwJ = $c3pwHandHead + 1; $c3pwJ -lt $c3pwHandLines.Count; $c3pwJ++) {
