$c1yGate1 = Join-Path $c1yGates 'amendment-material-am-001.yaml'
New-PwGate -Path $c1yGate1 -Id 'am-001' -BindsRel '.mission\amendments\AM-001-tracked.yaml' -Sha $c1yTrackedSha

