Set-PwBytesAsWritten -Path $c1yDotFull -Bytes $c1yDotBytes
$c1yDotSha = Get-PwBytesBlobSha -Root $c1yRoot -Bytes $c1yDotBytes
$c1yDotSt = Invoke-PwGit -Root $c1yRoot -GitArgs @('status', '--porcelain', '--untracked-files=all', '--', '.mission/amendments')
$c1yPlainRead = [System.IO.File]::ReadAllBytes($c1yDotFull)
