Set-PwBytesAsWritten -Path $c1ySpFull -Bytes $c1ySpBytes
$c1ySpSha = Get-PwBytesBlobSha -Root $c1yRoot -Bytes $c1ySpBytes
$c1yB = Invoke-PwEval -Root $c1yRoot -GoalId 'G-P2' -Hook
$c1yBArm = Get-PwDetector -Text $c1yB.text -Type $pwType
$c1yBLine = @(@($c1yB.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1ySpSha + ' ' + [regex]::Escape($c1ySpRel) + '\z') })
Add-C1yRow -Label '(b) FALSIFIER a name ending in a SPACE beside the same gated neighbour: ADMITTED under its OWN digest, no mint printed' `
