$c1yGate10 = Join-Path $c1yGates 'amendment-material-am-010.yaml'
New-PwGate -Path $c1yGate10 -Id 'am-010' -BindsRel '.mission\amendments\cs\AM-010-c1y.yaml' -Sha (Get-PwBlobSha -Root $c1yRoot -Rel '.mission/amendments/cs/AM-010-c1y.yaml')
$c1yE2 = Invoke-PwEval -Root $c1yRoot -GoalId 'G-P2'
$c1yE2Pre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1yE2.text -Type $pwType).detail -Rel '.mission/amendments/cs/am-010-c1y.yaml'
Add-C1yRow -Label '(e) with the TRACKED file''s gate at am-010, the lower-case placement is printed an APPROVE under a fresh id -- never a reapprove retiring that gate' `
    -Ok (($c1yE2.verdict -ceq $pwVerdict) -and ($c1yE2.exit -eq 4) -and $c1yE2Pre.found -and ($c1yE2Pre.statements -eq 1) -and ($c1yE2Pre.verb -ceq 'approve') -and ($c1yE2Pre.args['Id'] -ceq 'cs-am-010-c1y')) `
    -Said $c1yE2Pre.text
Remove-Item -LiteralPath $c1yGate10 -Force
Remove-Item -LiteralPath (Join-Path $c1yCs 'am-010-c1y.yaml') -Force

# (f) a canonical gate NAMING the placement but CONSUMED: mission-gate refuses a reapprove over it.
$c1yF2Rel = '.mission/amendments/AM-020-c1y.yaml'
Write-Utf8 -Path (Join-Path $c1yRoot $c1yF2Rel.Replace('/', '\')) -Text "id: AM-020`nnote: restated after its gate was spent`n"
$c1yGate20 = Join-Path $c1yGates 'amendment-material-am-020.yaml'
New-PwGate -Path $c1yGate20 -Id 'am-020' -BindsRel '.mission\amendments\AM-020-c1y.yaml' -Sha ('cd' * 32) -ConsumedAt '2026-09-24T03:00:00.000Z'
$c1yF = Invoke-PwEval -Root $c1yRoot -GoalId 'G-P2'
$c1yFArm = (Get-PwDetector -Text $c1yF.text -Type $pwType).detail
$c1yFPre = Get-PwPrescription -Detail $c1yFArm -Rel $c1yF2Rel
Add-C1yRow -Label '(f) FALSIFIER over a CONSUMED gate naming it, the mint printed is APPROVE under a fresh id (am-020-c1y), not the refused reapprove' `
    -Ok ($c1yFPre.found -and ($c1yFPre.statements -eq 1) -and ($c1yFPre.verb -ceq 'approve') -and ($c1yFPre.args['Id'] -ceq 'am-020-c1y') -and ((Get-PwLineIds -Lines @($c1yF.awaiting)) -ccontains 'am-020-c1y')) `
    -Said $c1yFPre.text
Add-C1yRow -Label '(f) and the notes say why the short id was passed over: the gate is CONSUMED' `
    -Ok ($c1yFArm -match 'amendment-material-am-020\.yaml is CONSUMED, and mission-gate refuses to reapprove a consumed gate') -Said $c1yFArm
New-PwGate -Path $c1yGate20 -Id 'am-020' -BindsRel '.mission\amendments\AM-020-c1y.yaml' -Sha ('cd' * 32)
$c1yF2 = Invoke-PwEval -Root $c1yRoot -GoalId 'G-P2'
$c1yF2Pre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1yF2.text -Type $pwType).detail -Rel $c1yF2Rel
Add-C1yRow -Label '(f) CONTROL the same gate NOT consumed: reapprove under am-020, as before' `
    -Ok ($c1yF2Pre.found -and ($c1yF2Pre.verb -ceq 'reapprove') -and ($c1yF2Pre.args['Id'] -ceq 'am-020')) -Said $c1yF2Pre.text
New-PwGate -Path $c1yGate20 -Id 'am-020' -BindsRel '.mission\amendments\AM-020-c1y.yaml' -Sha ('cd' * 32) -RevokedAt '2026-09-24T03:30:00.000Z'
$c1yF3 = Invoke-PwEval -Root $c1yRoot -GoalId 'G-P2'
$c1yF3Pre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1yF3.text -Type $pwType).detail -Rel $c1yF2Rel
Add-C1yRow -Label '(f) CONTROL the same gate REVOKED and not consumed: still reapprove under am-020 (mission-gate re-mints over a revoked prior)' `
    -Ok ($c1yF3Pre.found -and ($c1yF3Pre.verb -ceq 'reapprove') -and ($c1yF3Pre.args['Id'] -ceq 'am-020')) -Said $c1yF3Pre.text
Remove-Item -LiteralPath $c1yGate20 -Force
Remove-Item -LiteralPath (Join-Path $c1yRoot $c1yF2Rel.Replace('/', '\')) -Force

# (g) A PASTE RUNNING PAST THE COMMAND TO THE END OF ITS LINE. A seat-chosen name carrying a
#     subexpression, with CR LF bytes so a note follows it, and an ordinary name after it.
$c1yHostile = 'AM-030 $(ni c1y-pwned).md'
$c1yHostileRel = '.mission/amendments/' + $c1yHostile
$c1yPlainRel = '.mission/amendments/AM-031-c1y.yaml'
Set-PwBytes -Path (Join-Path $c1yAmend $c1yHostile) -Bytes ($pwUtf8.GetBytes("id: AM-030`r`nnote: CR LF, so a note follows its line`r`n"))
Write-Utf8 -Path (Join-Path $c1yRoot $c1yPlainRel.Replace('/', '\')) -Text "id: AM-031`n"
$c1yG = Invoke-PwEval -Root $c1yRoot -GoalId 'G-P2'
$c1yGArm = (Get-PwDetector -Text $c1yG.text -Type $pwType).detail
$c1yGCli = @(@(($c1yG.out -replace "`r", '') -split "`n") | Where-Object { $_.StartsWith('  [FAIL] ' + $pwType + ' -- ', [System.StringComparison]::Ordinal) })
$c1yGCliLine = if ($c1yGCli.Count -eq 1) { $c1yGCli[0] } else { '' }
foreach ($c1yGRel in @($c1yHostileRel, $c1yPlainRel)) {
    $c1yGArt = Get-PwCommandTail -Line $c1yGArm -Rel $c1yGRel
    $c1yGOut = Get-PwCommandTail -Line $c1yGCliLine -Rel $c1yGRel
    Add-C1yRow -Label ('(g) FALSIFIER from ' + ($c1yGRel -replace '^\.mission/amendments/', '') + '''s printed command to the END of its line -- the artifact''s detail and the hand-run [FAIL] line -- parses as that ONE command') `
        -Ok ($c1yGArt.found -and $c1yGOut.found -and ($c1yGArt.statements -eq 1) -and ($c1yGArt.commands -eq 1) -and ($c1yGArt.subexpressions -eq 0) -and ($c1yGOut.statements -eq 1) -and ($c1yGOut.commands -eq 1) -and ($c1yGOut.subexpressions -eq 0)) `
        -Said ('artifact: ' + $c1yGArt.statements + ' statement(s), ' + $c1yGArt.commands + ' command(s), ' + $c1yGArt.subexpressions + ' subexpression(s); [FAIL] line: ' + $c1yGOut.statements + '/' + $c1yGOut.commands + '/' + $c1yGOut.subexpressions + '; tail: ' + $c1yGArt.text)
}
$c1yGPlainPre = Get-PwPrescription -Detail $c1yGArm -Rel $c1yPlainRel
Add-C1yRow -Label '(g) CONTROL the ordinary name''s mint is printed and parses exact: approve, -Id am-031, -Binds and -MissionRoot' `
    -Ok ($c1yGPlainPre.found -and ($c1yGPlainPre.statements -eq 1) -and ($c1yGPlainPre.verb -ceq 'approve') -and ($c1yGPlainPre.args['Id'] -ceq 'am-031') -and ($c1yGPlainPre.args['Binds'] -ceq '.mission\amendments\AM-031-c1y.yaml') -and ($c1yGPlainPre.args['MissionRoot'] -ceq $c1yRoot)) `
    -Said $c1yGPlainPre.text
Add-C1yRow -Label '(g) nothing was executed: no c1y-pwned file in the fixture or the current directory' `
    -Ok ((-not (Test-Path -LiteralPath (Join-Path $c1yRoot 'c1y-pwned'))) -and (-not (Test-Path -LiteralPath (Join-Path (Get-Location).Path 'c1y-pwned')))) -Said ''
}
catch {
    $c1yOk = $false
    $c1yRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1yRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1yM) { Remove-PwTreeAsWritten -Base $c1yM.base }
Check -Id 'C-1y' -Title 'THE PLACEMENT-WINDOW ARM, SECOND PACKAGE (LAM-ACCEPT amendment 54 section 7; validator round 1, F1, F2 and F3): what the arm reads is the placement''s own -- a placement whose name ends in a dot or a space, beside a tracked amendment of that name whose canonical gate stands over its bytes, is admitted under its OWN digest (git''s blob of what was placed) with no mint printed, not released as a false MET by the neighbour''s gate, and a canonical gate over the dotted placement''s own bytes releases it; a placement named NUL is read as its own bytes; in a directory made case-sensitive, a file differing only in case from a tracked one is admitted while the tracked one is not; over a canonical gate naming the placement but consumed, the mint printed is an approve under a fresh id, the notes naming the consumption, while a gate not consumed -- revoked or not -- still gets reapprove; and from any printed command to the end of its line, in the artifact and the hand-run [FAIL] line alike, the text parses as that one command, with a seat-chosen name carrying a subexpression on the same line' `
      -Ok $c1yOk -Detail ("      THE $(@($c1yRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1yRows -join "`n"))

# =============================================================================================
# C-1z -- THE PLACEMENT-WINDOW ARM, SECOND PACKAGE, WHAT ITS PRE-COMMIT REVIEW FOUND: a directory
#         Win32 renames, git's own case folding, the verdict artifact's raw text, device names
# =============================================================================================
# THE FALSIFIERS, RED at the tree before the second package's cure:
# (a) a directory named sub. beside an existing sub\ is WALKED AS sub\ -- Get-ChildItem enters it by the
#     name Win32 makes of it -- so what sub.\ holds is never seen and sub\'s files are listed twice: a
#     placement inside it was a false MET; (b) the same for a directory named with a trailing SPACE.
#     Restated in the third package, when the walk came to read every entry by
#     the name as written: the file in such a directory must be admitted under its own digest -- no mint
#     under sub., and under "sub " a mint whose -Binds is its exact path;
# (c) a file git reports UNTRACKED -- AM-050-e-acute.md, the index holding the E-acute capital -- was
#     counted tracked because .NET folds that letter pair and git does not: a false MET;
# (d) the verdict artifact's RAW text is YAML, which doubles every single quote, so a single-quoted mint
#     copied from it ended early and ran the rest -- a seat-chosen subexpression -- as code;
# (e) a placement named CON.yaml or AUX, which GetFullPath leaves as it is on this host, was printed a
#     mint that mission-gate refuses ("not on disk");
# (f) beside a tracked file in a case-sensitive directory, whose gate's binds_resolved: is its absolute
#     path as the console writes it, the case-sibling must get a fresh id -- a folded comparison would
#     print the reapprove that retires the tracked file's gate; (g) something at the canonical gate path
#     that is not a gate (a directory) must pass the id over; (i) an index that spells the directory
#     .mission/Amendments/ with case-siblings on disk must admit the untracked one alone; (j) a
#     placement's notes must precede its mint, and the command end in " #"; (k) a look-alike of a
#     tracked, gated amendment (a soft hyphen in its name, which PowerShell's -ceq ignores) must get an
#     approve under a fresh id, never the reapprove that retires the ratified gate; (l) a gate at the
#     canonical path whose id: or kind: carries an invisible character must not release; (m) a
#     directory named lonely., nothing beside it -- on which the old walk threw -- must have its file
#     admitted under its own digest, no mint (restated in the third package, as (a) and (b)).
# THE CONTROLS: sub\'s tracked file is counted once and admits nothing; the placement's own blob digest
# rides every line; an ordinary name beside them is still printed its mint, parsed exact; (h) a tracked
# file renamed on disk in case alone is still tracked. The helpers are C-1y's.
$c1zOk = $true
$c1zRows = New-Object System.Collections.Generic.List[string]
function Add-C1zRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1zOk = $false }
    $script:c1zRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1zRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1zRawDetailLine {
    # The ungated_placement_absent detector's `    detail: '...'` line AS IT STANDS IN THE ARTIFACT'S RAW
    # TEXT -- YAML, single quotes doubled -- which is what an operator reading the file would copy from.
    param([string]$Text)
    $c1zDm = [regex]::Match($Text, '(?m)^  - type: ' + [regex]::Escape($pwType) + '\r?\n    ok: \S+\r?\n(?<line>    detail: .*?)\r?$')
    if ($c1zDm.Success) { return $c1zDm.Groups['line'].Value }
    return ''
}
$c1zM = $null
try {
$c1zM = New-PwMission -Tag 'c1z'
if (-not $c1zM.ok) { throw ('FIXTURE REFUSED: ' + $c1zM.why) }
$c1zRoot = $c1zM.root
$c1zAmend = Join-Path $c1zRoot '.mission\amendments'
$c1zIdArgs = @('-c', 'user.name=wp3-pw', '-c', 'user.email=wp3-pw@example.invalid', '-c', 'commit.gpgsign=false')
Write-PwGoal -Root $c1zRoot -GoalId 'G-P2Z' -DetectorLines @(('  - type: ' + $pwType))

# (a) A DIRECTORY NAMED sub. BESIDE sub\, which holds a TRACKED amendment.
Write-Utf8 -Path (Join-Path $c1zAmend 'sub\AM-040-ratified.md') -Text "id: AM-040`nnote: tracked, in sub`n"
$c1zSubAdd = Invoke-PwGit -Root $c1zRoot -GitArgs @('add', '--', '.mission/amendments/sub/AM-040-ratified.md')
$c1zSubCommitArgs = $c1zIdArgs + @('commit', '--quiet', '-m', 'track sub/AM-040')
$c1zSubCommit = Invoke-PwGit -Root $c1zRoot -GitArgs $c1zSubCommitArgs
$c1zDotDir = Join-Path $c1zAmend 'sub.'
[void][System.IO.Directory]::CreateDirectory('\\?\' + $c1zDotDir)
$c1zHidBytes = $pwUtf8.GetBytes("id: AM-041`nnote: placed inside sub. -- the walk enters sub\ instead`n")
Set-PwBytesAsWritten -Path (Join-Path $c1zDotDir 'AM-041-new.md') -Bytes $c1zHidBytes
$c1zDotSt = Invoke-PwGit -Root $c1zRoot -GitArgs @('status', '--porcelain', '--untracked-files=all', '--', '.mission/amendments')
$c1zDotLs = Invoke-PwGit -Root $c1zRoot -GitArgs @('ls-files', '--', '.mission/amendments/sub')
$c1zDotReal = @([System.IO.Directory]::GetFiles('\\?\' + $c1zDotDir) | ForEach-Object { [System.IO.Path]::GetFileName($_) })
Add-C1zRow -Label '(a) FIXTURE sub\AM-040-ratified.md is TRACKED, and sub.\ holds AM-041-new.md alone, read through \\?\ (git status shown, not asserted)' `
    -Ok (($c1zSubAdd.exit -eq 0) -and ($c1zSubCommit.exit -eq 0) -and (($c1zDotReal -join ',') -ceq 'AM-041-new.md') -and ($c1zDotLs.text.Trim() -ceq '.mission/amendments/sub/AM-040-ratified.md')) `
    -Said ('in sub.\ [' + ($c1zDotReal -join ', ') + '] ; ls-files [' + $c1zDotLs.text.Trim() + '] ; git status, which walks sub.\ by the same rewritten name: ' + $c1zDotSt.text)
$c1zA = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
$c1zAArm = Get-PwDetector -Text $c1zA.text -Type $pwType
$c1zHidSha = Get-PwBytesBlobSha -Root $c1zRoot -Bytes $c1zHidBytes
$c1zHidRel = '.mission/amendments/sub./AM-041-new.md'
Add-C1zRow -Label '(a) FALSIFIER the hook ADMITS it (approve, exit 0): sub.\AM-041-new.md under its own digest, no mint -- not a MET that never saw it' `
    -Ok ($c1zA.admitted -and (@($c1zA.awaiting).Count -eq 1) -and (@(@($c1zA.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1zHidSha + ' ' + [regex]::Escape($c1zHidRel) + '\z') }).Count -eq 1) -and $c1zAArm.detail.Contains('no mint is printed for ' + $c1zHidRel)) `
    -Said ('verdict ' + $c1zA.verdict + ', exit ' + $c1zA.exit + '; awaiting [' + (@($c1zA.awaiting) -join ' ; ') + ']')
Add-C1zRow -Label '(a) CONTROL sub\AM-040-ratified.md is counted ONCE among the tracked (3) and admits nothing of its own' `
    -Ok (($c1zAArm.detail -match ' 3 tracked file\(s\) under \.mission/amendments') -and (@(@($c1zA.awaiting) | Where-Object { $_ -match 'AM-040' }).Count -eq 0)) `
    -Said ('the arm: ' + $c1zAArm.detail)
[System.IO.Directory]::Delete(('\\?\' + $c1zDotDir), $true)

# (b) THE SAME FOR A DIRECTORY NAMED WITH A TRAILING SPACE.
$c1zSpDir = Join-Path $c1zAmend 'sub '
[void][System.IO.Directory]::CreateDirectory('\\?\' + $c1zSpDir)
$c1zSpBytes = $pwUtf8.GetBytes("id: AM-042`n")
Set-PwBytesAsWritten -Path (Join-Path $c1zSpDir 'AM-042-new.md') -Bytes $c1zSpBytes
$c1zB = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
$c1zBRel = '.mission/amendments/sub /AM-042-new.md'
# Win32 trims a trailing SPACE from a path's LAST component only, so this path survives as written and
# the mint printed for it binds exactly this file (mission-gate's -ComposeOnly binds its own bytes,
# driven); a trailing DOT is trimmed from every component, which is why (a) prints none.
$c1zBPre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1zB.text -Type $pwType).detail -Rel $c1zBRel
Add-C1zRow -Label '(b) FALSIFIER a directory named "sub " (a trailing space) beside sub\: its file ADMITTED under its own digest, its mint''s -Binds its exact path' `
    -Ok ($c1zB.admitted -and (@($c1zB.awaiting).Count -eq 1) -and (@(@($c1zB.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + (Get-PwBytesBlobSha -Root $c1zRoot -Bytes $c1zSpBytes) + ' ' + [regex]::Escape($c1zBRel) + '\z') }).Count -eq 1) -and $c1zBPre.found -and [string]::Equals([string]$c1zBPre.args['Binds'], '.mission\amendments\sub \AM-042-new.md', [System.StringComparison]::Ordinal)) `
    -Said ('verdict ' + $c1zB.verdict + '; awaiting [' + (@($c1zB.awaiting) -join ' ; ') + ']; ' + $c1zBPre.text)
[System.IO.Directory]::Delete(('\\?\' + $c1zSpDir), $true)

# (c) git's OWN case folding: the index holds AM-050-<E-acute capital>.md, the disk AM-050-<e-acute>.md.
$c1zCapName = 'AM-050-' + [string][char]0xC9 + '.md'
$c1zLowName = 'AM-050-' + [string][char]0xE9 + '.md'
Write-Utf8 -Path (Join-Path $c1zAmend $c1zCapName) -Text "id: AM-050`nnote: the RATIFIED text, tracked under the capital`n"
$c1zCapAdd = Invoke-PwGit -Root $c1zRoot -GitArgs @('add', '--', ('.mission/amendments/' + $c1zCapName))
$c1zCapCommitArgs = $c1zIdArgs + @('commit', '--quiet', '-m', 'track AM-050 capital')
$c1zCapCommit = Invoke-PwGit -Root $c1zRoot -GitArgs $c1zCapCommitArgs
Remove-Item -LiteralPath (Join-Path $c1zAmend $c1zCapName) -Force
$c1zLowBytes = $pwUtf8.GetBytes("id: AM-050`nnote: NOT the ratified text -- the lower-case letter`n")
Set-PwBytes -Path (Join-Path $c1zAmend $c1zLowName) -Bytes $c1zLowBytes
$c1zLowSha = Get-PwBytesBlobSha -Root $c1zRoot -Bytes $c1zLowBytes
$c1zCaseSt = Invoke-PwGit -Root $c1zRoot -GitArgs @('-c', 'core.quotepath=true', 'status', '--porcelain', '--untracked-files=all', '--', '.mission/amendments')
Add-C1zRow -Label '(c) FIXTURE git itself reads the lower-case file UNTRACKED and the tracked capital DELETED (core.quotepath octal)' `
    -Ok (($c1zCapAdd.exit -eq 0) -and ($c1zCapCommit.exit -eq 0) -and ($c1zCaseSt.text -match '(?m)^\?\? "\.mission/amendments/AM-050-\\303\\251\.md"$') -and ($c1zCaseSt.text -match '(?m)^ D "\.mission/amendments/AM-050-\\303\\211\.md"$')) `
    -Said ('git status: ' + $c1zCaseSt.text)
$c1zC = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
$c1zCLine = @(@($c1zC.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1zLowSha + ' ' + [regex]::Escape('.mission/amendments/' + $c1zLowName) + '\z') })
Add-C1zRow -Label '(c) FALSIFIER the file git reads untracked is ADMITTED under its own digest -- not counted tracked by a fold git does not make' `
    -Ok ($c1zC.admitted -and ($c1zCLine.Count -eq 1)) -Said ('verdict ' + $c1zC.verdict + '; awaiting [' + ((@($c1zC.awaiting) -join ' ; ') -replace '[^\x20-\x7E]', '?') + ']')
Remove-Item -LiteralPath (Join-Path $c1zAmend $c1zLowName) -Force

# (d) THE ARTIFACT'S RAW TEXT: a seat-chosen name carrying a subexpression, and an ordinary name after it.
$c1zHostile = 'AM-060 $(ni c1z-pwned) it''s.md'
$c1zHostileRel = '.mission/amendments/' + $c1zHostile
$c1zPlainRel = '.mission/amendments/AM-061-c1z.yaml'
Set-PwBytes -Path (Join-Path $c1zAmend $c1zHostile) -Bytes ($pwUtf8.GetBytes("id: AM-060`r`nnote: CR LF, so a note follows its line`r`n"))
Write-Utf8 -Path (Join-Path $c1zRoot $c1zPlainRel.Replace('/', '\')) -Text "id: AM-061`n"
$c1zD = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z'
$c1zDRaw = Get-C1zRawDetailLine -Text $c1zD.text
foreach ($c1zDRel in @($c1zHostileRel, $c1zPlainRel)) {
    # In the raw text the label's path is YAML-escaped too: its apostrophe doubled.
    $c1zDTail = Get-PwCommandTail -Line $c1zDRaw -Rel ($c1zDRel.Replace("'", "''"))
    Add-C1zRow -Label ('(d) FALSIFIER in the artifact''s RAW text, from ' + ($c1zDRel -replace '^\.mission/amendments/', '') + '''s printed command to the end of its line: ONE command, no subexpression') `
        -Ok ($c1zDTail.found -and ($c1zDTail.statements -eq 1) -and ($c1zDTail.commands -eq 1) -and ($c1zDTail.subexpressions -eq 0)) `
        -Said ($c1zDTail.statements.ToString() + ' statement(s), ' + $c1zDTail.commands + ' command(s), ' + $c1zDTail.subexpressions + ' subexpression(s); raw tail: ' + $c1zDTail.text)
}
$c1zDPre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1zD.text -Type $pwType).detail -Rel $c1zHostileRel
Add-C1zRow -Label '(d) CONTROL decoded, the hostile name''s mint parses exact: approve, -Binds its own path, apostrophe and all, -MissionRoot' `
    -Ok ($c1zDPre.found -and ($c1zDPre.statements -eq 1) -and ($c1zDPre.verb -ceq 'approve') -and ($c1zDPre.args['Binds'] -ceq ('.mission\amendments\' + $c1zHostile)) -and ($c1zDPre.args['MissionRoot'] -ceq $c1zRoot)) `
    -Said $c1zDPre.text
Add-C1zRow -Label '(d) nothing was executed: no c1z-pwned file in the fixture or the current directory' `
    -Ok ((-not (Test-Path -LiteralPath (Join-Path $c1zRoot 'c1z-pwned'))) -and (-not (Test-Path -LiteralPath (Join-Path (Get-Location).Path 'c1z-pwned')))) -Said ''
Remove-Item -LiteralPath (Join-Path $c1zAmend $c1zHostile) -Force
Remove-Item -LiteralPath (Join-Path $c1zRoot $c1zPlainRel.Replace('/', '\')) -Force

# (e) DEVICE NAMES GetFullPath LEAVES AS THEY ARE: CON.yaml and AUX, beside an ordinary name.
$c1zDev = @('CON.yaml', 'AUX')
foreach ($c1zDevName in $c1zDev) { Set-PwBytesAsWritten -Path (Join-Path $c1zAmend $c1zDevName) -Bytes ($pwUtf8.GetBytes('a file named ' + $c1zDevName + "`n")) }
Write-Utf8 -Path (Join-Path $c1zRoot $c1zPlainRel.Replace('/', '\')) -Text "id: AM-061`n"
$c1zE = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
$c1zEArm = (Get-PwDetector -Text $c1zE.text -Type $pwType).detail
foreach ($c1zDevName in $c1zDev) {
    $c1zDevRel = '.mission/amendments/' + $c1zDevName
    $c1zDevSha = Get-PwBytesBlobSha -Root $c1zRoot -Bytes ($pwUtf8.GetBytes('a file named ' + $c1zDevName + "`n"))
    $c1zDevLine = @(@($c1zE.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1zDevSha + ' ' + [regex]::Escape($c1zDevRel) + '\z') })
    Add-C1zRow -Label ('(e) FALSIFIER a placement named ' + $c1zDevName + ': admitted under its own digest, and NO mint is printed -- mission-gate cannot address it by name') `
        -Ok ($c1zE.admitted -and ($c1zDevLine.Count -eq 1) -and (-not (Get-PwPrescription -Detail $c1zEArm -Rel $c1zDevRel).found) -and $c1zEArm.Contains('no mint is printed for ' + $c1zDevRel)) `
        -Said ('awaiting [' + (@($c1zE.awaiting) -join ' ; ') + ']')
}
$c1zEPre = Get-PwPrescription -Detail $c1zEArm -Rel $c1zPlainRel
Add-C1zRow -Label '(e) CONTROL the ordinary name beside them is printed its mint: approve, -Id am-061, -Binds exact' `
    -Ok ($c1zEPre.found -and ($c1zEPre.statements -eq 1) -and ($c1zEPre.verb -ceq 'approve') -and ($c1zEPre.args['Id'] -ceq 'am-061') -and ($c1zEPre.args['Binds'] -ceq '.mission\amendments\AM-061-c1z.yaml')) `
    -Said $c1zEPre.text
foreach ($c1zDevName in $c1zDev) { Remove-PwAsWritten -Path (Join-Path $c1zAmend $c1zDevName) }
Remove-Item -LiteralPath (Join-Path $c1zRoot $c1zPlainRel.Replace('/', '\')) -Force

# (f) A CASE-SIBLING BESIDE A TRACKED FILE WHOSE GATE IS SHAPED AS THE CONSOLE MINTS IT: binds_resolved:
#     names the tracked file's absolute path. Folded, it names the sibling too, and the reapprove printed
#     would retire the tracked file's gate.
$c1zCs = Join-Path $c1zAmend 'cs'
New-Item -ItemType Directory -Path $c1zCs -Force | Out-Null
$prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
try { $c1zFsu = @(& fsutil.exe file setCaseSensitiveInfo $c1zCs enable 2>&1); $c1zFsuExit = $LASTEXITCODE } finally { $ErrorActionPreference = $prevEap }
Write-Utf8 -Path (Join-Path $c1zCs 'AM-070-x.yaml') -Text "id: AM-070`nnote: the RATIFIED text, tracked`n"
$c1zCsAdd = Invoke-PwGit -Root $c1zRoot -GitArgs @('add', '--', '.mission/amendments/cs/AM-070-x.yaml')
$c1zCsCommitArgs = $c1zIdArgs + @('commit', '--quiet', '-m', 'track cs/AM-070')
$c1zCsCommit = Invoke-PwGit -Root $c1zRoot -GitArgs $c1zCsCommitArgs
$c1zGate70 = Join-Path $c1zRoot '.mission\gates\amendment-material-am-070.yaml'
New-PwGate -Path $c1zGate70 -Id 'am-070' -BindsRel '.mission\amendments\cs\AM-070-x.yaml' -Sha (Get-PwBlobSha -Root $c1zRoot -Rel '.mission/amendments/cs/AM-070-x.yaml')
$c1zGate70Text = [System.IO.File]::ReadAllText($c1zGate70).Replace('binds_resolved: wp3-fixture', 'binds_resolved: ' + (Join-Path $c1zCs 'AM-070-x.yaml'))
[System.IO.File]::WriteAllText($c1zGate70, $c1zGate70Text, $pwUtf8)
Set-PwBytes -Path (Join-Path $c1zCs 'am-070-x.yaml') -Bytes ($pwUtf8.GetBytes("id: AM-070`nnote: NOT the ratified text -- the same name in lower case`n"))
$c1zF = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z'
$c1zFPre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1zF.text -Type $pwType).detail -Rel '.mission/amendments/cs/am-070-x.yaml'
Add-C1zRow -Label '(f) FALSIFIER beside the tracked AM-070-x.yaml, whose gate''s binds_resolved: is its absolute path, am-070-x.yaml gets APPROVE under a fresh id' `
    -Ok (($c1zFsuExit -eq 0) -and ($c1zCsAdd.exit -eq 0) -and ($c1zCsCommit.exit -eq 0) -and ($c1zF.exit -eq 4) -and $c1zFPre.found -and ($c1zFPre.statements -eq 1) -and ($c1zFPre.verb -ceq 'approve') -and ($c1zFPre.args['Id'] -ceq 'cs-am-070-x')) `
    -Said ('fsutil exit ' + $c1zFsuExit + '; ' + $c1zFPre.text)
Remove-Item -LiteralPath (Join-Path $c1zCs 'am-070-x.yaml') -Force
Remove-Item -LiteralPath $c1zGate70 -Force

# (g) SOMETHING AT THE CANONICAL GATE PATH THAT IS NOT A GATE (a directory): approve there is refused, and
#     so is reapprove -- the id is passed over.
Write-Utf8 -Path (Join-Path $c1zAmend 'AM-080-x.yaml') -Text "id: AM-080`n"
$c1zGateDir = Join-Path $c1zRoot '.mission\gates\amendment-material-am-080.yaml'
New-Item -ItemType Directory -Path $c1zGateDir -Force | Out-Null
$c1zG = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z'
$c1zGArm = (Get-PwDetector -Text $c1zG.text -Type $pwType).detail
$c1zGPre = Get-PwPrescription -Detail $c1zGArm -Rel '.mission/amendments/AM-080-x.yaml'
Add-C1zRow -Label '(g) with a DIRECTORY at amendment-material-am-080.yaml, AM-080-x.yaml gets APPROVE under a fresh id, the reason named' `
    -Ok ($c1zGPre.found -and ($c1zGPre.verb -ceq 'approve') -and ($c1zGPre.args['Id'] -ceq 'am-080-x') -and ($c1zGArm -match 'amendment-material-am-080\.yaml exists and is not a gate this arm reads')) `
    -Said $c1zGPre.text
Remove-Item -LiteralPath $c1zGateDir -Force
Remove-Item -LiteralPath (Join-Path $c1zAmend 'AM-080-x.yaml') -Force

# (h) CONTROL: a tracked file RENAMED ON DISK IN CASE ALONE is still the tracked file (git status is clean).
Write-Utf8 -Path (Join-Path $c1zAmend 'AM-090-x.yaml') -Text "id: AM-090`n"
$c1zHAdd = Invoke-PwGit -Root $c1zRoot -GitArgs @('add', '--', '.mission/amendments/AM-090-x.yaml')
$c1zHCommitArgs = $c1zIdArgs + @('commit', '--quiet', '-m', 'track AM-090')
$c1zHCommit = Invoke-PwGit -Root $c1zRoot -GitArgs $c1zHCommitArgs
[System.IO.File]::Move((Join-Path $c1zAmend 'AM-090-x.yaml'), (Join-Path $c1zAmend 'renaming-090.tmp'))
[System.IO.File]::Move((Join-Path $c1zAmend 'renaming-090.tmp'), (Join-Path $c1zAmend 'am-090-x.yaml'))
$c1zHNames = @(Get-ChildItem -LiteralPath $c1zAmend -File -Force | Where-Object { $_.Name -like '*090*' } | ForEach-Object { $_.Name })
$c1zHSt = Invoke-PwGit -Root $c1zRoot -GitArgs @('status', '--porcelain', '--untracked-files=all', '--', '.mission/amendments/am-090-x.yaml', '.mission/amendments/AM-090-x.yaml')
$c1zH = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
Add-C1zRow -Label '(h) CONTROL AM-090-x.yaml, tracked, renamed on disk to am-090-x.yaml (git status clean): not admitted -- MET' `
    -Ok (($c1zHAdd.exit -eq 0) -and ($c1zHCommit.exit -eq 0) -and (($c1zHNames -join ',') -ceq 'am-090-x.yaml') -and (-not $c1zHSt.text.Trim()) -and ($c1zH.verdict -ceq 'MET') -and ($c1zH.exit -eq 0) -and (@($c1zH.awaiting).Count -eq 0)) `
    -Said ('on disk [' + ($c1zHNames -join ', ') + '] ; git status [' + $c1zHSt.text.Trim() + '] ; verdict ' + $c1zH.verdict + '; awaiting [' + (@($c1zH.awaiting) -join ' ; ') + ']')

# (i) AN INDEX THAT SPELLS THE DIRECTORY .mission/Amendments/, a case-sensitive directory on disk named
#     amendments holding AM-010-x.yaml (tracked) and am-010-x.yaml: one placement, not two.
$c1zIv = Join-Path $c1zM.base 'iv'
New-Item -ItemType Directory -Path $c1zIv -Force | Out-Null
$null = Invoke-PwGit -Root $c1zM.base -GitArgs @('init', '--quiet', $c1zIv)
$c1zIvGd = [System.IO.Path]::GetFullPath((Invoke-PwGit -Root $c1zIv -GitArgs @('rev-parse', '--absolute-git-dir')).text.Trim().Replace('/', '\'))
if ($c1zIvGd -ine [System.IO.Path]::GetFullPath((Join-Path $c1zIv '.git'))) { throw ('FIXTURE REFUSED: the index-spelling fixture git dir is ' + $c1zIvGd) }
$c1zIvUpper = Join-Path $c1zIv '.mission\Amendments'
New-Item -ItemType Directory -Path $c1zIvUpper -Force | Out-Null
$prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
try { $c1zIvFsu = @(& fsutil.exe file setCaseSensitiveInfo $c1zIvUpper enable 2>&1); $c1zIvFsuExit = $LASTEXITCODE } finally { $ErrorActionPreference = $prevEap }
Write-Utf8 -Path (Join-Path $c1zIvUpper 'AM-010-x.yaml') -Text "id: AM-010`n"
$c1zIvAdd = Invoke-PwGit -Root $c1zIv -GitArgs @('add', '--', '.mission/Amendments/AM-010-x.yaml')
$c1zIvCommitArgs = $c1zIdArgs + @('commit', '--quiet', '-m', 'seed under .mission/Amendments')
$c1zIvCommit = Invoke-PwGit -Root $c1zIv -GitArgs $c1zIvCommitArgs
[System.IO.Directory]::Move($c1zIvUpper, (Join-Path $c1zIv '.mission\amendments-renaming'))
[System.IO.Directory]::Move((Join-Path $c1zIv '.mission\amendments-renaming'), (Join-Path $c1zIv '.mission\amendments'))
Set-PwBytes -Path (Join-Path $c1zIv '.mission\amendments\am-010-x.yaml') -Bytes ($pwUtf8.GetBytes("id: AM-010`nnote: NOT the tracked text`n"))
Write-PwGoal -Root $c1zIv -GoalId 'G-IV' -DetectorLines @(('  - type: ' + $pwType))
$c1zIvLs = Invoke-PwGit -Root $c1zIv -GitArgs @('ls-files')
$c1zI = Invoke-PwEval -Root $c1zIv -GoalId 'G-IV' -Hook
Add-C1zRow -Label '(i) the index spelling .mission/Amendments/: the tracked AM-010-x.yaml is tracked, and only am-010-x.yaml is ADMITTED' `
    -Ok (($c1zIvFsuExit -eq 0) -and ($c1zIvAdd.exit -eq 0) -and ($c1zIvCommit.exit -eq 0) -and ($c1zIvLs.text.Trim() -ceq '.mission/Amendments/AM-010-x.yaml') -and $c1zI.admitted -and (@($c1zI.awaiting).Count -eq 1) -and (@($c1zI.awaiting)[0] -cmatch ' \.mission/amendments/am-010-x\.yaml\z')) `
    -Said ('ls-files [' + $c1zIvLs.text.Trim() + '] ; verdict ' + $c1zI.verdict + '; awaiting [' + (@($c1zI.awaiting) -join ' ; ') + ']')

# (j) THE ORDER THE DETAIL CLAIMS: each placement's notes come BEFORE its mint.
$c1zJRel = '.mission/amendments/AM-095-x.yaml'
Set-PwBytes -Path (Join-Path $c1zRoot $c1zJRel.Replace('/', '\')) -Bytes ($pwUtf8.GetBytes("id: AM-095`r`nnote: CR LF, so a note is written`r`n"))
$c1zJ = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z'
$c1zJArm = (Get-PwDetector -Text $c1zJ.text -Type $pwType).detail
$c1zJAbout = $c1zJArm.IndexOf('about ' + $c1zJRel + ': ', [System.StringComparison]::Ordinal)
$c1zJMint = $c1zJArm.IndexOf('mint for ' + $c1zJRel, [System.StringComparison]::Ordinal)
Add-C1zRow -Label '(j) a placement''s notes precede its mint in the detail, and the printed command ends in " #"' `
    -Ok (($c1zJAbout -ge 0) -and ($c1zJMint -gt $c1zJAbout) -and ($c1zJArm -match ('mint for ' + [regex]::Escape($c1zJRel) + ': tools\\lam\\lam-console\.ps1 [^#]* #( |\z)'))) `
    -Said ('about at ' + $c1zJAbout + ', mint at ' + $c1zJMint)
Remove-Item -LiteralPath (Join-Path $c1zRoot $c1zJRel.Replace('/', '\')) -Force

# (k) A LOOK-ALIKE of a tracked, gated amendment -- its name carrying a SOFT HYPHEN, which PowerShell's -ceq
#     ignores -- must never be printed the reapprove that retires the ratified file's gate.
Write-Utf8 -Path (Join-Path $c1zAmend 'AM-500-x.yaml') -Text "id: AM-500`nnote: the RATIFIED text, tracked`n"
$c1zKAdd = Invoke-PwGit -Root $c1zRoot -GitArgs @('add', '--', '.mission/amendments/AM-500-x.yaml')
$c1zKCommitArgs = $c1zIdArgs + @('commit', '--quiet', '-m', 'track AM-500')
$c1zKCommit = Invoke-PwGit -Root $c1zRoot -GitArgs $c1zKCommitArgs
$c1zGate500 = Join-Path $c1zRoot '.mission\gates\amendment-material-am-500.yaml'
New-PwGate -Path $c1zGate500 -Id 'am-500' -BindsRel '.mission\amendments\AM-500-x.yaml' -Sha (Get-PwBlobSha -Root $c1zRoot -Rel '.mission/amendments/AM-500-x.yaml')
[System.IO.File]::WriteAllText($c1zGate500, ([System.IO.File]::ReadAllText($c1zGate500).Replace('binds_resolved: wp3-fixture', 'binds_resolved: ' + (Join-Path $c1zAmend 'AM-500-x.yaml'))), $pwUtf8)
$c1zLook = 'AM-500-x' + [string][char]0xAD + '.yaml'
$c1zLookRel = '.mission/amendments/' + $c1zLook
Set-PwBytes -Path (Join-Path $c1zAmend $c1zLook) -Bytes ($pwUtf8.GetBytes("id: AM-500`nnote: NOT the ratified text -- a soft hyphen in the name`n"))
$c1zK = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z'
$c1zKArm = (Get-PwDetector -Text $c1zK.text -Type $pwType).detail
$c1zKPre = Get-PwPrescription -Detail $c1zKArm -Rel $c1zLookRel
Add-C1zRow -Label '(k) FALSIFIER AM-500-x<U+00AD>.yaml beside the tracked, gated AM-500-x.yaml gets APPROVE under a fresh id, never reapprove am-500' `
    -Ok (($c1zKAdd.exit -eq 0) -and ($c1zKCommit.exit -eq 0) -and ($c1zK.exit -eq 4) -and $c1zKPre.found -and ($c1zKPre.verb -ceq 'approve') -and [string]::Equals([string]$c1zKPre.args['Id'], 'am-500-x', [System.StringComparison]::Ordinal) -and [string]::Equals([string]$c1zKPre.args['Binds'], ('.mission\amendments\' + $c1zLook), [System.StringComparison]::Ordinal) -and ($c1zKArm -notmatch 'amendment-material-am-500\.yaml names this file')) `
    -Said ($c1zKPre.text -replace '[^\x20-\x7E]', '?')
Remove-Item -LiteralPath (Join-Path $c1zAmend $c1zLook) -Force
Remove-Item -LiteralPath $c1zGate500 -Force

# (l) A GATE AT THE CANONICAL PATH WHOSE id: OR kind: CARRIES AN INVISIBLE CHARACTER is not the canonical
#     amendment-material gate (ruling (3)): over the placement's exact bytes it releases nothing.
$c1zLRel = '.mission/amendments/AM-600-x.yaml'
Write-Utf8 -Path (Join-Path $c1zRoot $c1zLRel.Replace('/', '\')) -Text "id: AM-600`n"
$c1zLSha = Get-PwBlobSha -Root $c1zRoot -Rel $c1zLRel
$c1zGate600 = Join-Path $c1zRoot '.mission\gates\amendment-material-am-600.yaml'
New-PwGate -Path $c1zGate600 -Id 'am-600' -BindsRel '.mission\amendments\AM-600-x.yaml' -Sha $c1zLSha -IdField ('am-600' + [string][char]0x2060)
$c1zL1 = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
Add-C1zRow -Label '(l) FALSIFIER a gate at amendment-material-am-600.yaml over the exact bytes, its id: am-600<U+2060>, does NOT release' `
    -Ok ($c1zL1.admitted -and (@(@($c1zL1.awaiting) | Where-Object { $_.EndsWith(' ' + $c1zLRel) }).Count -eq 1)) -Said ('verdict ' + $c1zL1.verdict)
New-PwGate -Path $c1zGate600 -Id 'am-600' -BindsRel '.mission\amendments\AM-600-x.yaml' -Sha $c1zLSha -Kind ('amendment-material' + [string][char]0xAD)
$c1zL2 = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
Add-C1zRow -Label '(l) FALSIFIER the same gate with kind: amendment-material<U+00AD> does NOT release' `
    -Ok ($c1zL2.admitted -and (@(@($c1zL2.awaiting) | Where-Object { $_.EndsWith(' ' + $c1zLRel) }).Count -eq 1)) -Said ('verdict ' + $c1zL2.verdict)
New-PwGate -Path $c1zGate600 -Id 'am-600' -BindsRel '.mission\amendments\AM-600-x.yaml' -Sha $c1zLSha
$c1zL3 = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
Add-C1zRow -Label '(l) CONTROL the same gate with the plain id: and kind: RELEASES it: MET' `
    -Ok (($c1zL3.verdict -ceq 'MET') -and ($c1zL3.exit -eq 0) -and (@($c1zL3.awaiting).Count -eq 0)) -Said ('verdict ' + $c1zL3.verdict)
Remove-Item -LiteralPath $c1zGate600 -Force
Remove-Item -LiteralPath (Join-Path $c1zRoot $c1zLRel.Replace('/', '\')) -Force

# (m) A DIRECTORY NAMED lonely. WITH NOTHING BESIDE IT under the rewritten name -- on which the
#     Get-ChildItem walk threw -- is read by the name as written: its file is admitted under its own
#     digest, with no mint. Restated in the third package.
$c1zLonely = '\\?\' + (Join-Path $c1zAmend 'lonely.')
[void][System.IO.Directory]::CreateDirectory($c1zLonely)
[System.IO.File]::WriteAllText($c1zLonely + '\AM-700-x.md', "id: AM-700`n")
$c1zM2 = Invoke-PwEval -Root $c1zRoot -GoalId 'G-P2Z' -Hook
$c1zM2Arm = (Get-PwDetector -Text $c1zM2.text -Type $pwType).detail
[System.IO.Directory]::Delete($c1zLonely, $true)
$c1zM2Rel = '.mission/amendments/lonely./AM-700-x.md'
$c1zM2Sha = Get-PwSha256 -Bytes ($pwUtf8.GetBytes("id: AM-700`n"))
Add-C1zRow -Label '(m) FALSIFIER lonely.\AM-700-x.md, nothing beside lonely.\: ADMITTED under its own digest, no mint' `
    -Ok ($c1zM2.admitted -and (@(@($c1zM2.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1zM2Sha + ' ' + [regex]::Escape($c1zM2Rel) + '\z') }).Count -eq 1) -and $c1zM2Arm.Contains('no mint is printed for ' + $c1zM2Rel)) `
    -Said ('the arm: ' + $c1zM2Arm)
}
catch {
    $c1zOk = $false
    $c1zRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1zRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1zM) { Remove-PwTreeAsWritten -Base $c1zM.base }
Check -Id 'C-1z' -Title 'THE PLACEMENT-WINDOW ARM, SECOND PACKAGE, WHAT ITS PRE-COMMIT REVIEW FOUND (LAM-ACCEPT amendment 54 section 7): a file in a directory named sub. or "sub " beside an existing sub\ is admitted under its own digest -- no mint printed under sub. (Win32 trims a dot in any component), a mint binding its exact path under "sub " (Win32 keeps a trailing space in a directory component) -- while sub\''s tracked file is counted once; a file git reads untracked because git folds only ASCII letters (the index holding the E-acute capital, the disk the small letter) is admitted under its own digest; in the verdict artifact''s raw text, where YAML doubles every single quote, each printed mint from its start to the end of its line is one command with no subexpression, a seat-chosen name carrying a subexpression and an apostrophe on that line, and decoded it binds that name exactly; and placements named CON.yaml and AUX are admitted under their own digests with no mint printed, while an ordinary name beside them is printed its mint; beside a tracked file in a case-sensitive directory whose gate''s binds_resolved: is its absolute path, the case-sibling is printed an approve under a fresh id; a directory at the canonical gate path passes the id over; a tracked file renamed on disk in case alone admits nothing; with the index spelling .mission/Amendments/, only the untracked case-sibling admits; a placement''s notes precede its mint, which ends in " #"; a look-alike of a tracked, gated amendment whose name carries a soft hyphen is printed an approve under a fresh id, never the reapprove retiring the ratified gate; a gate at the canonical path over the exact bytes whose id: carries U+2060 or whose kind: carries U+00AD releases nothing, while the same gate plain releases; and a file in a directory named lonely., nothing beside it, is admitted under its own digest with no mint printed' `
      -Ok $c1zOk -Detail ("      THE $(@($c1zRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1zRows -join "`n"))

# =============================================================================================
# C-1aa -- THE PLACEMENT-WINDOW ARM, THIRD PACKAGE: what validator round 2 found (LAM-ACCEPT
#          page, as revised; the round's findings)
# =============================================================================================
# THE FALSIFIERS, RED at the tree before the third package's cure:
# (a) a directory named SUB. (or "Sub ") beside a tracked sub\ was walked as SUB\ (or "Sub"), so
#     sub\'s tracked file was listed a second time under that spelling, counted untracked, and printed
#     a line and a mint over the TRACKED file's bytes; the walk must enumerate every entry by the name
#     as written: ONE line, for the file really in SUB.\, under its own digest, with no mint;
# (b) a placement named AM- and 229 digits was printed an id of 232 characters, whose gate file
#     name passes the 255 NTFS allows one name; every printed id must stay within 200;
# (c) a gate whose only kind: line says push, below a `KIND: amendment-material` line, released a
#     placement -- as did one with a second id: or binds_sha256: key in another case; each key must
#     occur exactly once in any case;
# (d) a placement whose name carries NEL (U+0085), which YAML reads as a space, was printed a mint
#     that, read from the artifact, names its sibling AM-050 x.md; no mint may be printed for it;
# (e) a canonical gate whose bytes begin FF FE read here as UTF-8 and was prescribed a reapprove,
#     while mission-gate reads it as UTF-16 and finds no kind; the id must be passed over;
# (f) the root .mission\amendments made unlistable: the detail must say what was not walked;
# (g) a directory named NUL: the walk threw and read nothing in it; its file must be admitted under
#     its own digest.
# (i) a gate carrying an empty second kind: line released: a reader skipping empty values saw one kind:.
# THE CONTROLS: sub\'s tracked file admits nothing; the same gate, plain, releases; the sibling of (d)
# is printed its mint, exact; and, from the third package's pre-commit review, (h) a gate whose kind:,
# id: or binds_sha256: key is spelled only in capitals releases nothing (read in any case, it did).
# (j) and (k) are falsifiers as well: no mint is printed for a name carrying U+2028, which YAML keeps
# only with no blank beside it; and two names whose ids cut to one get distinct ids within the cap, none
# noted as passed over (uncut, they ran to 201 characters).
$c1aaOk = $true
$c1aaRows = New-Object System.Collections.Generic.List[string]
function Add-C1aaRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1aaOk = $false }
    $script:c1aaRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1aaRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1aaM = $null
try {
$c1aaM = New-PwMission -Tag 'c1aa'
if (-not $c1aaM.ok) { throw ('FIXTURE REFUSED: ' + $c1aaM.why) }
$c1aaRoot = $c1aaM.root
$c1aaAmend = Join-Path $c1aaRoot '.mission\amendments'
$c1aaGates = Join-Path $c1aaRoot '.mission\gates'
$c1aaIdArgs = @('-c', 'user.name=wp3-pw', '-c', 'user.email=wp3-pw@example.invalid', '-c', 'commit.gpgsign=false')
Write-PwGoal -Root $c1aaRoot -GoalId 'G-P3' -DetectorLines @(('  - type: ' + $pwType))
Write-Utf8 -Path (Join-Path $c1aaAmend 'sub\AM-002-sub.yaml') -Text "id: AM-002-sub`nnote: tracked, in sub`n"
$c1aaSubAdd = Invoke-PwGit -Root $c1aaRoot -GitArgs @('add', '--', '.mission/amendments/sub/AM-002-sub.yaml')
$c1aaSubCommitArgs = $c1aaIdArgs + @('commit', '--quiet', '-m', 'track sub/AM-002')
$c1aaSubCommit = Invoke-PwGit -Root $c1aaRoot -GitArgs $c1aaSubCommitArgs

# (a) SUB. and "Sub " beside the tracked sub\, each holding a file of its own.
foreach ($c1aaDirName in @('SUB.', 'Sub ')) {
    $c1aaDir = Join-Path $c1aaAmend $c1aaDirName
    [void][System.IO.Directory]::CreateDirectory('\\?\' + $c1aaDir)
    $c1aaNewBytes = $pwUtf8.GetBytes('id: AM-003-new' + "`n" + 'note: placed in [' + $c1aaDirName + ']' + "`n")
    Set-PwBytesAsWritten -Path (Join-Path $c1aaDir 'AM-003-new.yaml') -Bytes $c1aaNewBytes
    $c1aaNewSha = Get-PwBytesBlobSha -Root $c1aaRoot -Bytes $c1aaNewBytes
    $c1aaNewRel = '.mission/amendments/' + $c1aaDirName + '/AM-003-new.yaml'
    $c1aaA = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
    $c1aaAArm = (Get-PwDetector -Text $c1aaA.text -Type $pwType).detail
    $c1aaAWant = @(@($c1aaA.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1aaNewSha + ' ' + [regex]::Escape($c1aaNewRel) + '\z') })
    Add-C1aaRow -Label ('(a) FALSIFIER [' + $c1aaDirName + '] beside the tracked sub\: ONE line, for its own AM-003-new.yaml under its own digest, and no line for AM-002') `
        -Ok ((($c1aaSubAdd.exit -eq 0) -and ($c1aaSubCommit.exit -eq 0)) -and $c1aaA.admitted -and (@($c1aaA.awaiting).Count -eq 1) -and ($c1aaAWant.Count -eq 1) -and ($c1aaAArm -notmatch 'AM-002-sub')) `
        -Said ('verdict ' + $c1aaA.verdict + '; awaiting [' + (@($c1aaA.awaiting) -join ' ; ') + ']')
    # A trailing DOT is trimmed from every path component, so no mint can name a file under SUB.; a trailing
    #     SPACE only from the last, so the mint for the file under "Sub " names it exactly.
    $c1aaAPre = Get-PwPrescription -Detail $c1aaAArm -Rel $c1aaNewRel
    $c1aaAMintOk = if ($c1aaDirName.EndsWith('.')) { (-not $c1aaAPre.found) -and $c1aaAArm.Contains('no mint is printed for ' + $c1aaNewRel) } else { $c1aaAPre.found -and [string]::Equals([string]$c1aaAPre.args['Binds'], $c1aaNewRel.Replace('/', '\'), [System.StringComparison]::Ordinal) }
    Add-C1aaRow -Label ('(a) [' + $c1aaDirName + '] ' + $(if ($c1aaDirName.EndsWith('.')) { 'no mint is printed for it' } else { 'its mint''s -Binds is its exact path' }) + ', and the tracked sub\AM-002-sub.yaml is counted among the tracked (3)') `
        -Ok ($c1aaAMintOk -and ($c1aaAArm -match ' 3 tracked file\(s\) under \.mission/amendments')) `
        -Said ('the arm: ' + $c1aaAArm)
    [System.IO.Directory]::Delete(('\\?\' + $c1aaDir), $true)
}

# (b) names long enough that an unbounded id would pass what NTFS allows one name.
$c1aaLongNames = @(('AM-' + ('7' * 229) + '.md'), (('x' * 240) + '.md'))
foreach ($c1aaLong in $c1aaLongNames) {
    Set-PwBytesAsWritten -Path (Join-Path $c1aaAmend $c1aaLong) -Bytes ($pwUtf8.GetBytes("a long name`n"))
}
$c1aaB = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3'
$c1aaBArm = (Get-PwDetector -Text $c1aaB.text -Type $pwType).detail
foreach ($c1aaLong in $c1aaLongNames) {
    $c1aaBPre = Get-PwPrescription -Detail $c1aaBArm -Rel ('.mission/amendments/' + $c1aaLong)
    $c1aaBId = [string]$c1aaBPre.args['Id']
    Add-C1aaRow -Label ('(b) FALSIFIER a ' + $c1aaLong.Length + '-character name: its printed id is at most 200 characters, its gate''s file name at most 255') `
        -Ok ($c1aaBPre.found -and ($c1aaBPre.statements -eq 1) -and ($c1aaBId.Length -ge 1) -and ($c1aaBId.Length -le 200) -and (('amendment-material-' + $c1aaBId + '.yaml').Length -le 255)) `
        -Said ('id length ' + $c1aaBId.Length + '; gate name length ' + ('amendment-material-' + $c1aaBId + '.yaml').Length)
}
foreach ($c1aaLong in $c1aaLongNames) { Remove-PwAsWritten -Path (Join-Path $c1aaAmend $c1aaLong) }

# (c) a gate at the canonical path over the exact bytes, carrying a second key in another case.
$c1aaCRel = '.mission/amendments/AM-100-x.yaml'
Write-Utf8 -Path (Join-Path $c1aaRoot $c1aaCRel.Replace('/', '\')) -Text "id: AM-100`n"
$c1aaCSha = Get-PwBlobSha -Root $c1aaRoot -Rel $c1aaCRel
$c1aaGate100 = Join-Path $c1aaGates 'amendment-material-am-100.yaml'
$c1aaCases = @(
    [pscustomobject]@{ label = 'its only kind: line says push, below a KIND: amendment-material line'; kind = 'push'; extra = 'KIND: amendment-material' },
    [pscustomobject]@{ label = 'a second id key, ID: am-999, beside id: am-100'; kind = 'amendment-material'; extra = 'ID: am-999' },
    [pscustomobject]@{ label = 'a second binds_sha256 key, BINDS_SHA256: over other bytes, beside the exact one'; kind = 'amendment-material'; extra = ('BINDS_SHA256: ' + ('ef' * 32)) })
foreach ($c1aaCase in $c1aaCases) {
    New-PwGate -Path $c1aaGate100 -Id 'am-100' -BindsRel '.mission\amendments\AM-100-x.yaml' -Sha $c1aaCSha -Kind $c1aaCase.kind
    $c1aaGateText = [System.IO.File]::ReadAllText($c1aaGate100)
    $c1aaGateText = $c1aaGateText.Replace("`r`nkind: ", "`r`n" + $c1aaCase.extra + "`r`nkind: ")
    [System.IO.File]::WriteAllText($c1aaGate100, $c1aaGateText, $pwUtf8)
    $c1aaC = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
    Add-C1aaRow -Label ('(c) FALSIFIER a gate at amendment-material-am-100.yaml over the exact bytes -- ' + $c1aaCase.label + ' -- does NOT release') `
        -Ok ($c1aaGateText.Contains($c1aaCase.extra) -and $c1aaC.admitted -and (@(@($c1aaC.awaiting) | Where-Object { $_.EndsWith(' ' + $c1aaCRel) }).Count -eq 1)) `
        -Said ('verdict ' + $c1aaC.verdict)
}
New-PwGate -Path $c1aaGate100 -Id 'am-100' -BindsRel '.mission\amendments\AM-100-x.yaml' -Sha $c1aaCSha
$c1aaC4 = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
Add-C1aaRow -Label '(c) CONTROL the same gate with one key of each, in the mint''s case, RELEASES it: MET' `
    -Ok (($c1aaC4.verdict -ceq 'MET') -and ($c1aaC4.exit -eq 0) -and (@($c1aaC4.awaiting).Count -eq 0)) -Said ('verdict ' + $c1aaC4.verdict)
Remove-Item -LiteralPath $c1aaGate100 -Force
Remove-Item -LiteralPath (Join-Path $c1aaRoot $c1aaCRel.Replace('/', '\')) -Force

# (d) NEL in a name, beside the sibling YAML would read it as.
$c1aaNel = 'AM-050' + [string][char]0x85 + 'x.md'
$c1aaSib = 'AM-050 x.md'
Set-PwBytes -Path (Join-Path $c1aaAmend $c1aaNel) -Bytes ($pwUtf8.GetBytes("the NEL placement`n"))
Set-PwBytes -Path (Join-Path $c1aaAmend $c1aaSib) -Bytes ($pwUtf8.GetBytes("the sibling`n"))
$c1aaD = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3'
$c1aaDArm = (Get-PwDetector -Text $c1aaD.text -Type $pwType).detail
$c1aaDNelPre = Get-PwPrescription -Detail $c1aaDArm -Rel ('.mission/amendments/' + $c1aaNel)
$c1aaDSibPre = Get-PwPrescription -Detail $c1aaDArm -Rel ('.mission/amendments/' + $c1aaSib)
Add-C1aaRow -Label '(d) FALSIFIER no mint is printed for AM-050<U+0085>x.md, and the note names U+0085' `
    -Ok ((-not $c1aaDNelPre.found) -and $c1aaDArm.Contains('no mint is printed for .mission/amendments/' + $c1aaNel) -and $c1aaDArm.Contains('U+0085')) `
    -Said ($c1aaDNelPre.text -replace '[^\x20-\x7E]', '?')
Add-C1aaRow -Label '(d) CONTROL its sibling AM-050 x.md is printed its mint, -Binds exact' `
    -Ok ($c1aaDSibPre.found -and ($c1aaDSibPre.statements -eq 1) -and [string]::Equals([string]$c1aaDSibPre.args['Binds'], '.mission\amendments\AM-050 x.md', [System.StringComparison]::Ordinal)) `
    -Said $c1aaDSibPre.text
Remove-Item -LiteralPath (Join-Path $c1aaAmend $c1aaNel) -Force
Remove-Item -LiteralPath (Join-Path $c1aaAmend $c1aaSib) -Force

# (e) a canonical gate naming the placement, its bytes beginning FF FE.
$c1aaERel = '.mission/amendments/AM-030-x.yaml'
Write-Utf8 -Path (Join-Path $c1aaRoot $c1aaERel.Replace('/', '\')) -Text "id: AM-030`nnote: restated`n"
$c1aaGate030 = Join-Path $c1aaGates 'amendment-material-am-030.yaml'
New-PwGate -Path $c1aaGate030 -Id 'am-030' -BindsRel '.mission\amendments\AM-030-x.yaml' -Sha ('cd' * 32)
[System.IO.File]::WriteAllBytes($c1aaGate030, ([byte[]]@(0xFF, 0xFE) + [System.IO.File]::ReadAllBytes($c1aaGate030)))
$c1aaE = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3'
$c1aaEPre = Get-PwPrescription -Detail (Get-PwDetector -Text $c1aaE.text -Type $pwType).detail -Rel $c1aaERel
Add-C1aaRow -Label '(e) FALSIFIER over a gate at am-030 whose bytes begin FF FE (UTF-16 to ReadAllText), the mint is APPROVE under a fresh id' `
    -Ok ($c1aaEPre.found -and ($c1aaEPre.verb -ceq 'approve') -and ($c1aaEPre.args['Id'] -ceq 'am-030-x')) -Said $c1aaEPre.text
Remove-Item -LiteralPath $c1aaGate030 -Force
Remove-Item -LiteralPath (Join-Path $c1aaRoot $c1aaERel.Replace('/', '\')) -Force

# (f) THE ROOT .mission\amendments MADE UNLISTABLE (a deny-ListDirectory rule for this user, removed in finally).
$c1aaDenyRule = New-Object System.Security.AccessControl.FileSystemAccessRule(
    [System.Security.Principal.WindowsIdentity]::GetCurrent().User, [System.Security.AccessControl.FileSystemRights]::ListDirectory,
    [System.Security.AccessControl.AccessControlType]::Deny)
$c1aaDenySet = $false
try {
    $c1aaAcl = [System.IO.Directory]::GetAccessControl($c1aaAmend)
    $c1aaAcl.AddAccessRule($c1aaDenyRule)
    [System.IO.Directory]::SetAccessControl($c1aaAmend, $c1aaAcl)
    $c1aaDenySet = $true
    $c1aaF = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
} finally {
    if ($c1aaDenySet) {
        $c1aaAcl2 = [System.IO.Directory]::GetAccessControl($c1aaAmend)
        $null = $c1aaAcl2.RemoveAccessRule($c1aaDenyRule)
        [System.IO.Directory]::SetAccessControl($c1aaAmend, $c1aaAcl2)
    }
}
$c1aaFArm = (Get-PwDetector -Text $c1aaF.text -Type $pwType).detail
Add-C1aaRow -Label '(f) the root .mission\amendments unlistable: ADMITTED, one UNDETERMINABLE line for it, and the detail says a directory was not walked' `
    -Ok ($c1aaF.admitted -and (@($c1aaF.awaiting).Count -eq 1) -and (@($c1aaF.awaiting)[0] -ceq ($pwPrefix + ' UNDETERMINABLE UNDETERMINABLE .mission/amendments/')) -and ($c1aaFArm -match '1 director\(ies\) not walked')) `
    -Said ('the arm: ' + $c1aaFArm)

# (g) A DIRECTORY NAMED NUL, holding a placement.
$c1aaNulDir = Join-Path $c1aaAmend 'NUL'
[void][System.IO.Directory]::CreateDirectory('\\?\' + $c1aaNulDir)
$c1aaNulBytes = $pwUtf8.GetBytes("inside a directory named NUL`n")
Set-PwBytesAsWritten -Path (Join-Path $c1aaNulDir 'AM-060-x.yaml') -Bytes $c1aaNulBytes
$c1aaNulSha = Get-PwBytesBlobSha -Root $c1aaRoot -Bytes $c1aaNulBytes
$c1aaG = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
Add-C1aaRow -Label '(g) FALSIFIER a placement inside a directory named NUL is ADMITTED under its own digest, one line' `
    -Ok ($c1aaG.admitted -and (@($c1aaG.awaiting).Count -eq 1) -and (@(@($c1aaG.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($pwPrefix) + ' \S+ ' + $c1aaNulSha + ' \.mission/amendments/NUL/AM-060-x\.yaml\z') }).Count -eq 1)) `
    -Said ('verdict ' + $c1aaG.verdict + '; awaiting [' + (@($c1aaG.awaiting) -join ' ; ') + ']')
[System.IO.Directory]::Delete(('\\?\' + $c1aaNulDir), $true)

# (h) CONTROLS from the third package's pre-commit review: a gate whose kind:, id: or binds_sha256: key is
#     spelled ONLY in capitals carries none of them to YAML and releases nothing; counted in any case and
#     read in any case, such a gate released.
$c1aaHRel = '.mission/amendments/AM-101-x.yaml'
Write-Utf8 -Path (Join-Path $c1aaRoot $c1aaHRel.Replace('/', '\')) -Text "id: AM-101`n"
$c1aaHSha = Get-PwBlobSha -Root $c1aaRoot -Rel $c1aaHRel
$c1aaGate101 = Join-Path $c1aaGates 'amendment-material-am-101.yaml'
foreach ($c1aaKey in @('id', 'kind', 'binds_sha256')) {
    New-PwGate -Path $c1aaGate101 -Id 'am-101' -BindsRel '.mission\amendments\AM-101-x.yaml' -Sha $c1aaHSha
    $c1aaHText = [System.IO.File]::ReadAllText($c1aaGate101).Replace("`r`n" + $c1aaKey + ': ', "`r`n" + $c1aaKey.ToUpperInvariant() + ': ')
    [System.IO.File]::WriteAllText($c1aaGate101, $c1aaHText, $pwUtf8)
    $c1aaH = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
    Add-C1aaRow -Label ('(h) CONTROL the gate over the exact bytes with its ' + $c1aaKey + ': key spelled only ' + $c1aaKey.ToUpperInvariant() + ': releases NOTHING') `
        -Ok ($c1aaHText.Contains("`r`n" + $c1aaKey.ToUpperInvariant() + ': ') -and $c1aaH.admitted -and (@(@($c1aaH.awaiting) | Where-Object { $_.EndsWith(' ' + $c1aaHRel) }).Count -eq 1)) `
        -Said ('verdict ' + $c1aaH.verdict)
}

# (i) FALSIFIER: an EMPTY second kind: line (YAML reads kind as null) -- a reader that skips empty values
#     saw one kind: and released.
New-PwGate -Path $c1aaGate101 -Id 'am-101' -BindsRel '.mission\amendments\AM-101-x.yaml' -Sha $c1aaHSha
[System.IO.File]::AppendAllText($c1aaGate101, "kind:`r`n", $pwUtf8)
$c1aaI = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3' -Hook
Add-C1aaRow -Label '(i) FALSIFIER the gate over the exact bytes with an EMPTY second kind: line appended releases NOTHING' `
    -Ok ($c1aaI.admitted -and (@(@($c1aaI.awaiting) | Where-Object { $_.EndsWith(' ' + $c1aaHRel) }).Count -eq 1)) -Said ('verdict ' + $c1aaI.verdict)
Remove-Item -LiteralPath $c1aaGate101 -Force
Remove-Item -LiteralPath (Join-Path $c1aaRoot $c1aaHRel.Replace('/', '\')) -Force

# (j) FALSIFIER: LS (U+2028) comes back from the artifact's YAML only with no blank beside it -- a blank
#     next to one is dropped -- so no mint is printed for a name carrying it (the third package's
#     pre-commit review E: a mint read back for AM-072 <LS>x.md named its sibling AM-072<LS>x.md).
$c1aaLs = 'AM-070' + [string][char]0x2028 + 'x.md'
Set-PwBytes -Path (Join-Path $c1aaAmend $c1aaLs) -Bytes ($pwUtf8.GetBytes("a line separator in the name`n"))
$c1aaJ = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3'
$c1aaJArm = (Get-PwDetector -Text $c1aaJ.text -Type $pwType).detail
$c1aaJPre = Get-PwPrescription -Detail $c1aaJArm -Rel ('.mission/amendments/' + $c1aaLs)
Add-C1aaRow -Label '(j) FALSIFIER no mint is printed for AM-070<U+2028>x.md, and the note names U+2028' `
    -Ok ((-not $c1aaJPre.found) -and $c1aaJArm.Contains('no mint is printed for .mission/amendments/' + $c1aaLs) -and $c1aaJArm.Contains('U+2028')) `
    -Said ($c1aaJPre.text -replace '[^\x20-\x7E]', '?')
Remove-Item -LiteralPath (Join-Path $c1aaAmend $c1aaLs) -Force

# (k) FALSIFIER: two names whose ids cut to the same 200 characters get distinct ids within the cap, and no note calls a
#     printed id "passed over".
$c1aaKNames = @(('AM-' + ('9' * 197) + '1.md'), ('AM-' + ('9' * 197) + '2.md'))
foreach ($c1aaKn in $c1aaKNames) { Set-PwBytesAsWritten -Path (Join-Path $c1aaAmend $c1aaKn) -Bytes ($pwUtf8.GetBytes('id: ' + $c1aaKn + "`n")) }
$c1aaK = Invoke-PwEval -Root $c1aaRoot -GoalId 'G-P3'
$c1aaKArm = (Get-PwDetector -Text $c1aaK.text -Type $pwType).detail
$c1aaKIds = @(Get-PwLineIds -Lines @($c1aaK.awaiting))
$c1aaKNoted = @($c1aaKIds | Where-Object { $c1aaKArm.Contains('the short id ' + $_ + ' was passed over') })
Add-C1aaRow -Label '(k) FALSIFIER two names cutting to one id: distinct ids of at most 200 characters, and no printed id is noted as passed over' `
    -Ok (($c1aaKIds.Count -eq 2) -and ($c1aaKIds[0] -cne $c1aaKIds[1]) -and (@($c1aaKIds | Where-Object { $_.Length -gt 200 }).Count -eq 0) -and ($c1aaKNoted.Count -eq 0)) `
    -Said ('id lengths ' + (($c1aaKIds | ForEach-Object { $_.Length }) -join ', ') + '; noted as passed over: ' + $c1aaKNoted.Count)
foreach ($c1aaKn in $c1aaKNames) { Remove-PwAsWritten -Path (Join-Path $c1aaAmend $c1aaKn) }
}
catch {
    $c1aaOk = $false
    $c1aaRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1aaRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1aaM) { Remove-PwTreeAsWritten -Base $c1aaM.base }
Check -Id 'C-1aa' -Title 'THE PLACEMENT-WINDOW ARM, THIRD PACKAGE (LAM-ACCEPT amendment 54 section 8; validator round 2, M1-M4 and N1): the walk enumerates every entry by the name as written -- beside a tracked sub\, a directory named SUB. or "Sub " yields ONE line, for its own file under its own digest -- no mint under SUB., a mint naming its exact path under "Sub " -- and no line for the tracked file, which is counted once; a printed id stays within 200 characters for names of 235 and 243 characters; a gate at the canonical path over the exact bytes releases nothing when its kind:, id: or binds_sha256: key occurs a second time in another case, while the same gate plain releases; no mint is printed for a name carrying U+0085, while its sibling is printed its exact mint; over a canonical gate whose bytes begin FF FE the mint is an approve under a fresh id; with the root .mission\amendments unlistable the detail says a directory was not walked; a placement inside a directory named NUL is admitted under its own digest; a gate whose kind:, id: or binds_sha256: key is spelled only in capitals, or that carries an empty second kind: line, releases nothing; no mint is printed for a name carrying U+2028; and two names whose ids cut to one are printed distinct ids, none of them noted as passed over' `
      -Ok $c1aaOk -Detail ("      THE $(@($c1aaRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1aaRows -join "`n"))

# =============================================================================================
# C-1ab -- THE PLACEMENT-WINDOW ARM, THIRD PACKAGE: only a gate in the console's line shape is live
#          (the third package's pre-commit review E)
# =============================================================================================
# THE FALSIFIERS, RED at the tree before the third package's cure. The gate readers read column-0
# `key: value` lines; YAML also honours quoted keys, a lone CR and NEL as line breaks, a key spelled
# with a blank before its colon, and values that are not one token. A canonical gate over the placement's
# EXACT bytes, carrying one of these, is one YAML reads with another kind or id, or as revoked -- and it
# released. Each must release NOTHING now:
#   a quoted "kind": key; a lone CR before a kind: line; NEL before an id: line; `revoked_at :` with a
#   blank before the colon; a quoted "revoked_at": key; an id: value of two tokens; a TAB after kind:;
#   a plain value holding ': '.
# THE CONTROLS: the same gate in the console's shape releases; so does one whose binds: path holds ' #',
# which YAML reads as a comment in a key the arm does not decide on. Every gate is FORGED in the mint's
# line set (New-PwGate); a real mint is WP-4's.
$c1abOk = $true
$c1abRows = New-Object System.Collections.Generic.List[string]
function Add-C1abRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1abOk = $false }
    $script:c1abRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1abRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1abM = $null
try {
$c1abM = New-PwMission -Tag 'c1ab'
if (-not $c1abM.ok) { throw ('FIXTURE REFUSED: ' + $c1abM.why) }
$c1abRoot = $c1abM.root
$c1abGates = Join-Path $c1abRoot '.mission\gates'
Write-PwGoal -Root $c1abRoot -GoalId 'G-P3S' -DetectorLines @(('  - type: ' + $pwType))
$c1abRel = '.mission/amendments/AM-110-x.yaml'
Write-Utf8 -Path (Join-Path $c1abRoot $c1abRel.Replace('/', '\')) -Text "id: AM-110`n"
$c1abSha = Get-PwBlobSha -Root $c1abRoot -Rel $c1abRel
$c1abGate = Join-Path $c1abGates 'amendment-material-am-110.yaml'
$c1abCr = [string][char]13
$c1abNel = [string][char]0x85
$c1abTab = [string][char]9
$c1abCases = @(
    [pscustomobject]@{ label = 'a quoted "kind": push line appended'; find = ''; with = ('"kind": push' + "`r`n") },
    [pscustomobject]@{ label = 'a lone CR before a kind: push line (note: x<CR>kind: push)'; find = ''; with = ('note: x' + $c1abCr + 'kind: push' + "`r`n") },
    [pscustomobject]@{ label = 'NEL before an id: line (note: x<NEL>id: am-999)'; find = ''; with = ('note: x' + $c1abNel + 'id: am-999' + "`r`n") },
    [pscustomobject]@{ label = 'revoked_at : <ts> appended, a blank before the colon'; find = ''; with = ('revoked_at : 2026-09-25T00:00:00.000Z' + "`r`n") },
    [pscustomobject]@{ label = 'a quoted "revoked_at": <ts> line appended'; find = ''; with = ('"revoked_at": 2026-09-25T00:00:00.000Z' + "`r`n") },
    [pscustomobject]@{ label = 'its id: line reading id: am-110 extra (two tokens)'; find = "`r`nid: am-110`r`n"; with = "`r`nid: am-110 extra`r`n" },
    [pscustomobject]@{ label = 'its kind: line reading kind:<TAB>amendment-material'; find = "`r`nkind: amendment-material`r`n"; with = ("`r`nkind:" + $c1abTab + "amendment-material`r`n") },
    [pscustomobject]@{ label = 'a plain value holding ": " (note: a: b) appended'; find = ''; with = ('note: a: b' + "`r`n") })
foreach ($c1abCase in $c1abCases) {
    New-PwGate -Path $c1abGate -Id 'am-110' -BindsRel '.mission\amendments\AM-110-x.yaml' -Sha $c1abSha
    $c1abText = [System.IO.File]::ReadAllText($c1abGate)
    if ($c1abCase.find) { $c1abText = $c1abText.Replace($c1abCase.find, $c1abCase.with) } else { $c1abText = $c1abText + $c1abCase.with }
    [System.IO.File]::WriteAllText($c1abGate, $c1abText, $pwUtf8)
    $c1abE = Invoke-PwEval -Root $c1abRoot -GoalId 'G-P3S' -Hook
    $c1abArm = (Get-PwDetector -Text $c1abE.text -Type $pwType).detail
    Add-C1abRow -Label ('FALSIFIER a canonical gate over the exact bytes with ' + $c1abCase.label + ' releases NOTHING') `
        -Ok ($c1abText.Contains($c1abCase.with) -and $c1abE.admitted -and (@(@($c1abE.awaiting) | Where-Object { $_.EndsWith(' ' + $c1abRel) }).Count -eq 1) -and ($c1abArm -notmatch 'RELEASED')) `
        -Said ('verdict ' + $c1abE.verdict + '; exit ' + $c1abE.exit)
}
New-PwGate -Path $c1abGate -Id 'am-110' -BindsRel '.mission\amendments\AM-110-x.yaml' -Sha $c1abSha
$c1abC1 = Invoke-PwEval -Root $c1abRoot -GoalId 'G-P3S' -Hook
Add-C1abRow -Label 'CONTROL the same gate in the console''s line shape RELEASES it: MET' `
    -Ok (($c1abC1.verdict -ceq 'MET') -and ($c1abC1.exit -eq 0) -and (@($c1abC1.awaiting).Count -eq 0)) -Said ('verdict ' + $c1abC1.verdict)
Remove-Item -LiteralPath $c1abGate -Force
Remove-Item -LiteralPath (Join-Path $c1abRoot $c1abRel.Replace('/', '\')) -Force
$c1abHashRel = '.mission/amendments/AM-111 #x.md'
Write-Utf8 -Path (Join-Path $c1abRoot $c1abHashRel.Replace('/', '\')) -Text "id: AM-111`n"
$c1abHashGate = Join-Path $c1abGates 'amendment-material-am-111.yaml'
New-PwGate -Path $c1abHashGate -Id 'am-111' -BindsRel '.mission\amendments\AM-111 #x.md' -Sha (Get-PwBlobSha -Root $c1abRoot -Rel $c1abHashRel)
$c1abC2 = Invoke-PwEval -Root $c1abRoot -GoalId 'G-P3S' -Hook
Add-C1abRow -Label 'CONTROL a gate whose binds: path holds " #" (binds: .mission\amendments\AM-111 #x.md) RELEASES its placement: MET' `
    -Ok (([System.IO.File]::ReadAllText($c1abHashGate).Contains('binds: .mission\amendments\AM-111 #x.md')) -and ($c1abC2.verdict -ceq 'MET') -and ($c1abC2.exit -eq 0) -and (@($c1abC2.awaiting).Count -eq 0)) `
    -Said ('verdict ' + $c1abC2.verdict)
}
catch {
    $c1abOk = $false
    $c1abRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1abRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1abM) { Remove-PwTreeAsWritten -Base $c1abM.base }
Check -Id 'C-1ab' -Title 'THE PLACEMENT-WINDOW ARM, ONLY A GATE IN THE CONSOLE''S LINE SHAPE IS LIVE (LAM-ACCEPT amendment 54 section 8; the third package''s pre-commit review E): a canonical gate over the placement''s exact bytes releases nothing when it carries a quoted "kind": key, a lone CR or a NEL before a key, a revoked_at key with a blank before its colon, a quoted "revoked_at": key, an id: value of two tokens, a TAB after kind:, or a plain value holding ": " -- forms YAML reads with another kind or id, or as revoked, and the line readers did not see; while the same gate in the console''s shape, and one whose binds: path holds " #", releases' `
      -Ok $c1abOk -Detail ("      THE $(@($c1abRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1abRows -join "`n"))

# =============================================================================================
# C-1ac -- THE PLACEMENT-WINDOW ARM, THIRD PACKAGE: what YAML reads off a gate in the line shape
#          (the third package's pre-commit review F)
# =============================================================================================
# THE FALSIFIERS, RED at the tree before the third package's cure. A canonical gate over the placement's
# EXACT bytes that YAML reads with no kind, as revoked, or not at all released it. Each must release
# NOTHING now:
#   (a) note:  "open two blanks after its colon, closed two lines on, the kind: line inside the string;
#   (b) note:  - x, two blanks before a sequence entry;
#   (c) revoked_at: null-x, (d) revoked_at: null#by-hand, (e) revoked_at: null<U+00A0> -- the shared
#       field test reads each as unset, YAML as set;
#   (f) a U+0001 in a value; (g) a plain value holding ':<TAB>'.
# (h) THE RESIDUAL, MEASURED: a gate whose authorized_by: is !ops -- a USERNAME Windows allows -- is out
#     of the line shape, and releases nothing: the shape rule's false BLOCK (review F).
# (i) a FALSIFIER as well: a byte 0xFF in a comment line. (j) The gate re-encoded as UTF-32 with its
#     byte-order mark releases nothing.
# THE CONTROLS, each must RELEASE: (k) revoked_at: null appended; (l) revoked_at: null # by hand
#   appended; (m) the gate's bytes behind a UTF-8 byte-order mark.
# THE IDS: (n) the mint printed for null.md is -Id "p-null", for 2026-09-25.md -Id "p-2026-09-25" --
#   PyYAML reads null as None and 2026-09-25 as a date; (o) a canonical gate amendment-material-null.yaml
#   whose id: is null, over null.md's exact bytes, releases nothing; (p) CONTROL one at
#   amendment-material-p-null.yaml whose id: is p-null releases it.
# U+FEFF: (q) no mint is printed for AM-130 <U+FEFF>x.md, and the note names U+FEFF; (r) no mint is
#   printed for AM-140-x.yaml under a mission root whose path carries U+FEFF, and the note says so.
# Every gate is FORGED in the mint's line set (New-PwGate); a real mint is WP-4's.
$c1acOk = $true
$c1acRows = New-Object System.Collections.Generic.List[string]
function Add-C1acRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1acOk = $false }
    $script:c1acRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1acRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1acM = $null
$c1acBomM = $null
try {
$c1acM = New-PwMission -Tag 'c1ac'
if (-not $c1acM.ok) { throw ('FIXTURE REFUSED: ' + $c1acM.why) }
$c1acRoot = $c1acM.root
$c1acGates = Join-Path $c1acRoot '.mission\gates'
Write-PwGoal -Root $c1acRoot -GoalId 'G-P3T' -DetectorLines @(('  - type: ' + $pwType))
$c1acRel = '.mission/amendments/AM-120-x.yaml'
Write-Utf8 -Path (Join-Path $c1acRoot $c1acRel.Replace('/', '\')) -Text "id: AM-120`n"
$c1acSha = Get-PwBlobSha -Root $c1acRoot -Rel $c1acRel
$c1acGate = Join-Path $c1acGates 'amendment-material-am-120.yaml'
$c1acKindLine = "`r`nkind: amendment-material`r`n"
$c1acCases = @(
    [pscustomobject]@{ label = '(a) FALSIFIER note:  "open, two blanks after its colon, with its kind: line inside the string'; find = $c1acKindLine; with = ("`r`n" + 'note:  "open' + "`r`n" + 'kind: amendment-material' + "`r`n" + 'zz: close"' + "`r`n") },
    [pscustomobject]@{ label = '(b) FALSIFIER note:  - x appended, two blanks before a sequence entry'; find = ''; with = ('note:  - x' + "`r`n") },
    [pscustomobject]@{ label = '(c) FALSIFIER revoked_at: null-x appended'; find = ''; with = ('revoked_at: null-x' + "`r`n") },
    [pscustomobject]@{ label = '(d) FALSIFIER revoked_at: null#by-hand appended'; find = ''; with = ('revoked_at: null#by-hand' + "`r`n") },
    [pscustomobject]@{ label = '(e) FALSIFIER revoked_at: null<U+00A0> appended'; find = ''; with = ('revoked_at: null' + [string][char]0xA0 + "`r`n") },
    [pscustomobject]@{ label = '(f) FALSIFIER note: a<U+0001>b appended'; find = ''; with = ('note: a' + [string][char]1 + 'b' + "`r`n") },
    [pscustomobject]@{ label = '(g) FALSIFIER note: a:<TAB>b appended'; find = ''; with = ('note: a:' + [string][char]9 + 'b' + "`r`n") },
    [pscustomobject]@{ label = '(h) RESIDUAL, MEASURED its authorized_by: reading !ops (a USERNAME Windows allows)'; find = "`r`nauthorized_by: wp3-pw`r`n"; with = "`r`nauthorized_by: !ops`r`n" })
foreach ($c1acCase in $c1acCases) {
    New-PwGate -Path $c1acGate -Id 'am-120' -BindsRel '.mission\amendments\AM-120-x.yaml' -Sha $c1acSha
    $c1acText = [System.IO.File]::ReadAllText($c1acGate)
    if ($c1acCase.find) { $c1acText = $c1acText.Replace($c1acCase.find, $c1acCase.with) } else { $c1acText = $c1acText + $c1acCase.with }
    [System.IO.File]::WriteAllText($c1acGate, $c1acText, $pwUtf8)
    $c1acE = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
    $c1acArm = (Get-PwDetector -Text $c1acE.text -Type $pwType).detail
    Add-C1acRow -Label ($c1acCase.label + ': the canonical gate over the exact bytes releases NOTHING') `
        -Ok ($c1acText.Contains($c1acCase.with) -and $c1acE.admitted -and (@(@($c1acE.awaiting) | Where-Object { $_.EndsWith(' ' + $c1acRel) }).Count -eq 1) -and ($c1acArm -notmatch 'RELEASED')) `
        -Said ('verdict ' + $c1acE.verdict + '; exit ' + $c1acE.exit)
}
# (i) and (j): the gate's BYTES, not its text.
New-PwGate -Path $c1acGate -Id 'am-120' -BindsRel '.mission\amendments\AM-120-x.yaml' -Sha $c1acSha
$c1acPlain = [System.IO.File]::ReadAllBytes($c1acGate)
$c1acPlainText = [System.IO.File]::ReadAllText($c1acGate)
$c1acUtf32 = New-Object System.Text.UTF32Encoding -ArgumentList @($false, $true)
$c1acByteCases = @(
    [pscustomobject]@{ label = '(i) FALSIFIER a comment line carrying the byte 0xFF appended'; bytes = [byte[]]($c1acPlain + [byte[]]@(0x23, 0x20, 0xFF, 0x0D, 0x0A)) },
    [pscustomobject]@{ label = '(j) the gate re-encoded as UTF-32 with its byte-order mark'; bytes = [byte[]]($c1acUtf32.GetPreamble() + $c1acUtf32.GetBytes($c1acPlainText)) })
foreach ($c1acBc in $c1acByteCases) {
    Set-PwBytes -Path $c1acGate -Bytes $c1acBc.bytes
    $c1acE = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
    $c1acArm = (Get-PwDetector -Text $c1acE.text -Type $pwType).detail
    Add-C1acRow -Label ($c1acBc.label + ': the canonical gate over the exact bytes releases NOTHING') `
        -Ok (($c1acBc.bytes.Length -gt $c1acPlain.Length) -and $c1acE.admitted -and (@(@($c1acE.awaiting) | Where-Object { $_.EndsWith(' ' + $c1acRel) }).Count -eq 1) -and ($c1acArm -notmatch 'RELEASED')) `
        -Said ('verdict ' + $c1acE.verdict + '; exit ' + $c1acE.exit + '; ' + $c1acBc.bytes.Length + ' bytes')
}
$c1acControls = @(
    [pscustomobject]@{ label = '(k) CONTROL revoked_at: null appended'; with = ('revoked_at: null' + "`r`n"); bom = $false },
    [pscustomobject]@{ label = '(l) CONTROL revoked_at: null # by hand appended'; with = ('revoked_at: null # by hand' + "`r`n"); bom = $false },
    [pscustomobject]@{ label = '(m) CONTROL the gate''s bytes behind a UTF-8 byte-order mark'; with = ''; bom = $true })
foreach ($c1acCc in $c1acControls) {
    New-PwGate -Path $c1acGate -Id 'am-120' -BindsRel '.mission\amendments\AM-120-x.yaml' -Sha $c1acSha
    $c1acCBytes = [System.IO.File]::ReadAllBytes($c1acGate)
    if ($c1acCc.with) { $c1acCBytes = [byte[]]($c1acCBytes + [System.Text.Encoding]::ASCII.GetBytes($c1acCc.with)) }
    if ($c1acCc.bom) { $c1acCBytes = [byte[]]([byte[]]@(0xEF, 0xBB, 0xBF) + $c1acCBytes) }
    Set-PwBytes -Path $c1acGate -Bytes $c1acCBytes
    $c1acE = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
    Add-C1acRow -Label ($c1acCc.label + ': the canonical gate over the exact bytes RELEASES it: MET') `
        -Ok (($c1acE.verdict -ceq 'MET') -and ($c1acE.exit -eq 0) -and (@($c1acE.awaiting).Count -eq 0)) -Said ('verdict ' + $c1acE.verdict)
}
Remove-Item -LiteralPath $c1acGate -Force
Remove-Item -LiteralPath (Join-Path $c1acRoot $c1acRel.Replace('/', '\')) -Force
# THE IDS.
$c1acNullRel = '.mission/amendments/null.md'
$c1acDateRel = '.mission/amendments/2026-09-25.md'
Write-Utf8 -Path (Join-Path $c1acRoot $c1acNullRel.Replace('/', '\')) -Text "id: null placement`n"
Write-Utf8 -Path (Join-Path $c1acRoot $c1acDateRel.Replace('/', '\')) -Text "id: dated placement`n"
$c1acN = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
$c1acNArm = (Get-PwDetector -Text $c1acN.text -Type $pwType).detail
foreach ($c1acIdCase in @(@($c1acNullRel, 'p-null'), @($c1acDateRel, 'p-2026-09-25'))) {
    $c1acIdPre = Get-PwPrescription -Detail $c1acNArm -Rel $c1acIdCase[0]
    Add-C1acRow -Label ('(n) FALSIFIER the mint printed for ' + $c1acIdCase[0] + ' is -Id "' + $c1acIdCase[1] + '", an id YAML reads as a string') `
        -Ok ($c1acIdPre.found -and ($c1acIdPre.statements -eq 1) -and [string]::Equals([string]$c1acIdPre.args['Id'], $c1acIdCase[1], [System.StringComparison]::Ordinal)) `
        -Said ('printed: ' + $c1acIdPre.text)
}
Remove-Item -LiteralPath (Join-Path $c1acRoot $c1acDateRel.Replace('/', '\')) -Force
$c1acNullSha = Get-PwBlobSha -Root $c1acRoot -Rel $c1acNullRel
$c1acNullGate = Join-Path $c1acGates 'amendment-material-null.yaml'
New-PwGate -Path $c1acNullGate -Id 'null' -BindsRel '.mission\amendments\null.md' -Sha $c1acNullSha
$c1acO = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
$c1acOArm = (Get-PwDetector -Text $c1acO.text -Type $pwType).detail
Add-C1acRow -Label '(o) FALSIFIER a canonical gate amendment-material-null.yaml whose id: is null, over null.md''s exact bytes, releases NOTHING' `
    -Ok ($c1acO.admitted -and (@(@($c1acO.awaiting) | Where-Object { $_.EndsWith(' ' + $c1acNullRel) }).Count -eq 1) -and ($c1acOArm -notmatch 'RELEASED')) `
    -Said ('verdict ' + $c1acO.verdict + '; exit ' + $c1acO.exit)
Remove-Item -LiteralPath $c1acNullGate -Force
New-PwGate -Path (Join-Path $c1acGates 'amendment-material-p-null.yaml') -Id 'p-null' -BindsRel '.mission\amendments\null.md' -Sha $c1acNullSha
$c1acP = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
Add-C1acRow -Label '(p) CONTROL a canonical gate amendment-material-p-null.yaml whose id: is p-null, over null.md''s exact bytes, RELEASES it: MET' `
    -Ok (($c1acP.verdict -ceq 'MET') -and ($c1acP.exit -eq 0) -and (@($c1acP.awaiting).Count -eq 0)) -Said ('verdict ' + $c1acP.verdict)
# U+FEFF IN A NAME.
$c1acFeff = [string][char]0xFEFF
$c1acFeffRel = '.mission/amendments/AM-130 ' + $c1acFeff + 'x.md'
Write-Utf8 -Path (Join-Path $c1acRoot $c1acFeffRel.Replace('/', '\')) -Text "id: AM-130`n"
$c1acQ = Invoke-PwEval -Root $c1acRoot -GoalId 'G-P3T' -Hook
$c1acQArm = (Get-PwDetector -Text $c1acQ.text -Type $pwType).detail
$c1acQPre = Get-PwPrescription -Detail $c1acQArm -Rel $c1acFeffRel
Add-C1acRow -Label '(q) FALSIFIER no mint is printed for AM-130 <U+FEFF>x.md, and the note names U+FEFF' `
    -Ok ($c1acQ.admitted -and (-not $c1acQPre.found) -and $c1acQArm.Contains('no mint is printed for ' + $c1acFeffRel) -and $c1acQArm.Contains('U+FEFF')) `
    -Said ('verdict ' + $c1acQ.verdict + '; exit ' + $c1acQ.exit)
# U+FEFF IN THE MISSION ROOT: a fixture of its own, BUILT UNDER AN ASCII NAME AND ITS DIRECTORY THEN
# RENAMED to carry U+FEFF. New-PwMission reads git's answers through the console's code page, and under
# the runner that read U+FEFF as '?' and refused the fixture (the RED reading); the arm reads
# git as UTF-8, and git in a renamed repository needs nothing moved.
$c1acBomM = New-PwMission -Tag 'c1acr'
if (-not $c1acBomM.ok) { throw ('FIXTURE REFUSED (the mission root to carry U+FEFF): ' + $c1acBomM.why) }
$c1acBomBase = Join-Path (Split-Path -Parent $c1acBomM.base) ((Split-Path -Leaf $c1acBomM.base).Replace('c1acr', 'c1ac' + $c1acFeff + 'r'))
[System.IO.Directory]::Move($c1acBomM.base, $c1acBomBase)
$c1acBomM.base = $c1acBomBase
$c1acBomRoot = Join-Path $c1acBomBase 'm'
Write-PwGoal -Root $c1acBomRoot -GoalId 'G-P3T' -DetectorLines @(('  - type: ' + $pwType))
$c1acBomRel = '.mission/amendments/AM-140-x.yaml'
Write-Utf8 -Path (Join-Path $c1acBomRoot $c1acBomRel.Replace('/', '\')) -Text "id: AM-140`n"
$c1acR = Invoke-PwEval -Root $c1acBomRoot -GoalId 'G-P3T' -Hook
$c1acRArm = (Get-PwDetector -Text $c1acR.text -Type $pwType).detail
$c1acRPre = Get-PwPrescription -Detail $c1acRArm -Rel $c1acBomRel
Add-C1acRow -Label '(r) FALSIFIER under a mission root whose path carries U+FEFF, no mint is printed for AM-140-x.yaml, and the note says so' `
    -Ok ($c1acBomRoot.Contains($c1acFeff) -and $c1acR.admitted -and (-not $c1acRPre.found) -and $c1acRArm.Contains('no mint is printed for ' + $c1acBomRel) -and $c1acRArm.Contains('mission root''s path carries U+FEFF')) `
    -Said ('verdict ' + $c1acR.verdict + '; exit ' + $c1acR.exit)
}
catch {
    $c1acOk = $false
    $c1acRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1acRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1acM) { Remove-PwTreeAsWritten -Base $c1acM.base }
if ($null -ne $c1acBomM) { Remove-PwTreeAsWritten -Base $c1acBomM.base }
Check -Id 'C-1ac' -Title 'THE PLACEMENT-WINDOW ARM, WHAT YAML READS OFF A GATE IN THE LINE SHAPE (LAM-ACCEPT amendment 54 section 8; the third package''s pre-commit review F): a canonical gate over the placement''s exact bytes releases nothing when a value after two blanks opens a string over its kind: line or a sequence entry, when revoked_at: reads null-x, null#by-hand or null<U+00A0>, when a value carries U+0001 or holds ":<TAB>", when a comment carries the byte 0xFF, when its authorized_by: is !ops (the residual, measured), or when it is re-encoded as UTF-32; it releases with revoked_at: null, with revoked_at: null # by hand, and behind a UTF-8 byte-order mark; the mint for null.md is -Id "p-null" and for 2026-09-25.md -Id "p-2026-09-25", a gate whose id: is null releases nothing and one whose id: is p-null releases; and no mint is printed for a name, or under a mission root, carrying U+FEFF' `
      -Ok $c1acOk -Detail ("      THE $(@($c1acRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1acRows -join "`n"))

# =============================================================================================
# C-1ad -- THE PLACEMENT-WINDOW ARM, THIRD PACKAGE: what the fourth draft's review found, and gates
#          PyYAML cannot load (the third package's pre-commit
#          review G, and the builder's probe of PyYAML 6.0.3)
# =============================================================================================
# THE FALSIFIERS, RED at the tree before the third package's cure. A canonical gate over the placement's
# EXACT bytes released it when YAML reads it as REVOKED -- (c) revoked_at: <U+00A0><ts>, (d) revoked_at:
# <U+3000>, a value the shared field test reads as unset because .NET's \S matches no space character --
# or when PyYAML refuses to load it: (a) a double-quoted value carrying an escape PyYAML does not read,
# note: "a<backslash>qb"; (b) a key of 1100 characters (PyYAML loaded one of 1000); (e) a TAB inside a
# plain value; (f) revoked_at: null<TAB>; (g) a value starting with ]; (h) the plain value =; (i) the
# plain value <<; (j) the plain value 0x_; (k) a key 0x_; (l) the date 2026-02-30; (m) the time
# 2026-09-24T25:00:00.000Z; (n) the offset +23:60. Each must release NOTHING now.
# THE CONTROLS, each must RELEASE: (o) a double-quoted value using only escapes PyYAML reads -- a
#   backslash, a quote, <backslash>t, <backslash>x41 and <backslash>u00e9; (p) plain values PyYAML
#   builds -- the date 2024-02-29, the int 0x1f, the time 2026-09-24T01:00:00+23:59.
# THE IDS: (q) the mint printed for `on`, 198 dashes and x.md is -Id "p-on", and (r) for `null`, 196
#   dashes and x.md is -Id "p-null": decided before the cut to 200, the arm printed -Id "on" and "null".
# THE NOTE: (s) for d<U+FEFF>\AM-131.md no mint is printed, and the note says its path under
#   .mission/amendments carries U+FEFF -- not its name. Every gate is FORGED in the mint's line set
#   (New-PwGate); the long names are written by the name as written (\\?\).
$c1adOk = $true
$c1adRows = New-Object System.Collections.Generic.List[string]
function Add-C1adRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1adOk = $false }
    $script:c1adRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1adRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1adM = $null
try {
$c1adM = New-PwMission -Tag 'c1ad'
if (-not $c1adM.ok) { throw ('FIXTURE REFUSED: ' + $c1adM.why) }
$c1adRoot = $c1adM.root
$c1adAmend = Join-Path $c1adRoot '.mission\amendments'
$c1adGates = Join-Path $c1adRoot '.mission\gates'
Write-PwGoal -Root $c1adRoot -GoalId 'G-P3U' -DetectorLines @(('  - type: ' + $pwType))
$c1adRel = '.mission/amendments/AM-150-x.yaml'
Write-Utf8 -Path (Join-Path $c1adRoot $c1adRel.Replace('/', '\')) -Text "id: AM-150`n"
$c1adSha = Get-PwBlobSha -Root $c1adRoot -Rel $c1adRel
$c1adGate = Join-Path $c1adGates 'amendment-material-am-150.yaml'
$c1adBs = [string][char]92
$c1adTab = [string][char]9
$c1adCases = @(
    [pscustomobject]@{ label = '(a) FALSIFIER note: "a<backslash>qb", an escape PyYAML does not read'; with = ('note: "a' + $c1adBs + 'qb"'); release = $false },
    [pscustomobject]@{ label = '(b) FALSIFIER a line whose key is 1100 characters'; with = (('k' * 1100) + ': x'); release = $false },
    [pscustomobject]@{ label = '(c) FALSIFIER revoked_at: <U+00A0>2026-09-25T00:00:00.000Z, which YAML reads as set'; with = ('revoked_at: ' + [string][char]0xA0 + '2026-09-25T00:00:00.000Z'); release = $false },
    [pscustomobject]@{ label = '(d) FALSIFIER revoked_at: <U+3000>, which YAML reads as set'; with = ('revoked_at: ' + [string][char]0x3000); release = $false },
    [pscustomobject]@{ label = '(e) FALSIFIER note: a<TAB>b'; with = ('note: a' + $c1adTab + 'b'); release = $false },
    [pscustomobject]@{ label = '(f) FALSIFIER revoked_at: null<TAB>'; with = ('revoked_at: null' + $c1adTab); release = $false },
    [pscustomobject]@{ label = '(g) FALSIFIER note: ]x'; with = 'note: ]x'; release = $false },
    [pscustomobject]@{ label = '(h) FALSIFIER note: ='; with = 'note: ='; release = $false },
    [pscustomobject]@{ label = '(i) FALSIFIER note: <<'; with = 'note: <<'; release = $false },
    [pscustomobject]@{ label = '(j) FALSIFIER note: 0x_'; with = 'note: 0x_'; release = $false },
    [pscustomobject]@{ label = '(k) FALSIFIER a key 0x_ (0x_: x)'; with = '0x_: x'; release = $false },
    [pscustomobject]@{ label = '(l) FALSIFIER note: 2026-02-30'; with = 'note: 2026-02-30'; release = $false },
    [pscustomobject]@{ label = '(m) FALSIFIER note: 2026-09-24T25:00:00.000Z'; with = 'note: 2026-09-24T25:00:00.000Z'; release = $false },
    [pscustomobject]@{ label = '(n) FALSIFIER note: 2026-09-24T01:00:00+23:60'; with = 'note: 2026-09-24T01:00:00+23:60'; release = $false },
    [pscustomobject]@{ label = '(o) CONTROL note: "<backslash><backslash> <backslash>" <backslash>t <backslash>x41 <backslash>u00e9", escapes PyYAML reads'; with = ('note: "' + $c1adBs + $c1adBs + ' ' + $c1adBs + '" ' + $c1adBs + 't ' + $c1adBs + 'x41 ' + $c1adBs + 'u00e9"'); release = $true },
    [pscustomobject]@{ label = '(p) CONTROL note: 2024-02-29, count: 0x1f and when: 2026-09-24T01:00:00+23:59, values PyYAML builds'; with = ('note: 2024-02-29' + "`r`n" + 'count: 0x1f' + "`r`n" + 'when: 2026-09-24T01:00:00+23:59'); release = $true })
foreach ($c1adCase in $c1adCases) {
    New-PwGate -Path $c1adGate -Id 'am-150' -BindsRel '.mission\amendments\AM-150-x.yaml' -Sha $c1adSha
    $c1adText = [System.IO.File]::ReadAllText($c1adGate) + $c1adCase.with + "`r`n"
    [System.IO.File]::WriteAllText($c1adGate, $c1adText, $pwUtf8)
    $c1adE = Invoke-PwEval -Root $c1adRoot -GoalId 'G-P3U' -Hook
    $c1adArm = (Get-PwDetector -Text $c1adE.text -Type $pwType).detail
    if ($c1adCase.release) {
        Add-C1adRow -Label ($c1adCase.label + ' appended: the canonical gate over the exact bytes RELEASES it: MET') `
            -Ok (($c1adE.verdict -ceq 'MET') -and ($c1adE.exit -eq 0) -and (@($c1adE.awaiting).Count -eq 0)) -Said ('verdict ' + $c1adE.verdict)
    } else {
        Add-C1adRow -Label ($c1adCase.label + ' appended: the canonical gate over the exact bytes releases NOTHING') `
            -Ok ($c1adE.admitted -and (@(@($c1adE.awaiting) | Where-Object { $_.EndsWith(' ' + $c1adRel) }).Count -eq 1) -and ($c1adArm -notmatch 'RELEASED')) `
            -Said ('verdict ' + $c1adE.verdict + '; exit ' + $c1adE.exit)
    }
}
Remove-Item -LiteralPath $c1adGate -Force
Remove-Item -LiteralPath (Join-Path $c1adRoot $c1adRel.Replace('/', '\')) -Force
# THE IDS: two long names, written by the name as written (their full paths pass 260).
$c1adLongBytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes("id: a long name`n")
$c1adLongCases = @(@(('on' + ('-' * 198) + 'x.md'), 'p-on'), @(('null' + ('-' * 196) + 'x.md'), 'p-null'))
foreach ($c1adLc in $c1adLongCases) {
    $c1adFs = New-Object System.IO.FileStream(('\\?\' + (Join-Path $c1adAmend $c1adLc[0])), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
    try { $c1adFs.Write($c1adLongBytes, 0, $c1adLongBytes.Length) } finally { $c1adFs.Dispose() }
}
$c1adQ = Invoke-PwEval -Root $c1adRoot -GoalId 'G-P3U' -Hook
$c1adQArm = (Get-PwDetector -Text $c1adQ.text -Type $pwType).detail
foreach ($c1adLc in $c1adLongCases) {
    $c1adQPre = Get-PwPrescription -Detail $c1adQArm -Rel ('.mission/amendments/' + $c1adLc[0])
    Add-C1adRow -Label ('(' + $(if ($c1adLc[1] -ceq 'p-on') { 'q' } else { 'r' }) + ') FALSIFIER the mint printed for ' + $c1adLc[0].Substring(0, $c1adLc[0].IndexOf('-')) + ', ' + ($c1adLc[0].Length - $c1adLc[0].IndexOf('-') - 4) + ' dashes and x.md is -Id "' + $c1adLc[1] + '"') `
        -Ok ($c1adQPre.found -and ($c1adQPre.statements -eq 1) -and [string]::Equals([string]$c1adQPre.args['Id'], $c1adLc[1], [System.StringComparison]::Ordinal)) `
        -Said ('printed -Id: ' + $(if ($c1adQPre.found) { [string]$c1adQPre.args['Id'] } else { '(no mint)' }))
}
foreach ($c1adLc in $c1adLongCases) { [System.IO.File]::Delete('\\?\' + (Join-Path $c1adAmend $c1adLc[0])) }
# THE NOTE: U+FEFF in a directory's name.
$c1adFeffDir = 'd' + [string][char]0xFEFF
$c1adFeffRel = '.mission/amendments/' + $c1adFeffDir + '/AM-131.md'
Write-Utf8 -Path (Join-Path $c1adAmend ($c1adFeffDir + '\AM-131.md')) -Text "id: AM-131`n"
$c1adS = Invoke-PwEval -Root $c1adRoot -GoalId 'G-P3U' -Hook
$c1adSArm = (Get-PwDetector -Text $c1adS.text -Type $pwType).detail
$c1adSPre = Get-PwPrescription -Detail $c1adSArm -Rel $c1adFeffRel
Add-C1adRow -Label '(s) FALSIFIER for d<U+FEFF>\AM-131.md no mint is printed, and the note says its path under .mission/amendments carries U+FEFF' `
    -Ok ($c1adS.admitted -and (-not $c1adSPre.found) -and $c1adSArm.Contains('no mint is printed for ' + $c1adFeffRel + ': its path under .mission/amendments carries U+FEFF')) `
    -Said ('verdict ' + $c1adS.verdict + '; exit ' + $c1adS.exit)
}
catch {
    $c1adOk = $false
    $c1adRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1adRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1adM) { Remove-PwTreeAsWritten -Base $c1adM.base }
Check -Id 'C-1ad' -Title 'THE PLACEMENT-WINDOW ARM, WHAT THE FOURTH DRAFT''S REVIEW FOUND, AND GATES PyYAML CANNOT LOAD (LAM-ACCEPT amendment 54 section 8; the third package''s pre-commit review G, and the builder''s probe of PyYAML 6.0.3): a canonical gate over the placement''s exact bytes releases nothing when its revoked_at: starts with U+00A0 or is U+3000, which YAML reads as set, or when PyYAML cannot load it -- a double-quoted escape PyYAML does not read, a key of 1100 characters, a TAB in a plain value or after null, a value starting with ], the plain values =, << and 0x_, a key 0x_, the date 2026-02-30, the hour 25, the offset +23:60 -- while one whose double-quoted escapes and plain values PyYAML reads releases; the mints printed for "on" and "null" followed by dashes to past 200 characters are -Id "p-on" and "p-null"; and for d<U+FEFF>\AM-131.md no mint is printed and the note says its path under .mission/amendments carries U+FEFF' `
      -Ok $c1adOk -Detail ("      THE $(@($c1adRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1adRows -join "`n"))

# =============================================================================================
# C-1ae -- THE PLACEMENT-WINDOW ARM, THIRD PACKAGE: what the sixth draft's review found (LAM-ACCEPT
#          page, as revised; the third package's pre-commit review H)
# =============================================================================================
# THE FALSIFIERS, RED at the tree before the third package's cure. A canonical gate over the placement's
# EXACT bytes released it while PyYAML (or libyaml) refuses to load it: (a) a plain value of 4301
# digits, which Python refuses to build as an int; (b) note: "<backslash>ud800" and (c) note:
# "<backslash>U0000DFFF", escapes naming a surrogate, which libyaml refuses. Each must release NOTHING
# now. (g) Over a canonical gate at amendment-material-am-170.yaml naming AM-170-x.yaml, whose
# binds_sha256: is 64 decimal digits -- a value YAML reads as an int -- the arm prescribed a reapprove
# of am-170; the gate is out of the line shape, so the mint must be an approve under another id, and
# the note must say the gate is not in the line shape.
# THE CONTROLS, each must RELEASE: (d) note: =<U+00AD> and (e) note: -<U+00AD>, which PyYAML loads,
# and which a culture comparison (-ceq) took for = and -; (f) a plain value of 4300 digits.
# Every gate is FORGED in the mint's line set (New-PwGate).
$c1aeOk = $true
$c1aeRows = New-Object System.Collections.Generic.List[string]
function Add-C1aeRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1aeOk = $false }
    $script:c1aeRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1aeRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1aeM = $null
try {
$c1aeM = New-PwMission -Tag 'c1ae'
if (-not $c1aeM.ok) { throw ('FIXTURE REFUSED: ' + $c1aeM.why) }
$c1aeRoot = $c1aeM.root
$c1aeGates = Join-Path $c1aeRoot '.mission\gates'
Write-PwGoal -Root $c1aeRoot -GoalId 'G-P3V' -DetectorLines @(('  - type: ' + $pwType))
$c1aeRel = '.mission/amendments/AM-160-x.yaml'
Write-Utf8 -Path (Join-Path $c1aeRoot $c1aeRel.Replace('/', '\')) -Text "id: AM-160`n"
$c1aeSha = Get-PwBlobSha -Root $c1aeRoot -Rel $c1aeRel
$c1aeGate = Join-Path $c1aeGates 'amendment-material-am-160.yaml'
$c1aeBs = [string][char]92
$c1aeCases = @(
    [pscustomobject]@{ label = '(a) FALSIFIER note: and 4301 digits, which Python refuses to build as an int'; with = ('note: ' + ('1' * 4301)); release = $false },
    [pscustomobject]@{ label = '(b) FALSIFIER note: "<backslash>ud800", an escape naming a surrogate'; with = ('note: "' + $c1aeBs + 'ud800"'); release = $false },
    [pscustomobject]@{ label = '(c) FALSIFIER note: "<backslash>U0000DFFF", an escape naming a surrogate'; with = ('note: "' + $c1aeBs + 'U0000DFFF"'); release = $false },
    [pscustomobject]@{ label = '(d) CONTROL note: =<U+00AD>, which PyYAML loads'; with = ('note: =' + [string][char]0xAD); release = $true },
    [pscustomobject]@{ label = '(e) CONTROL note: -<U+00AD>, which PyYAML loads'; with = ('note: -' + [string][char]0xAD); release = $true },
    [pscustomobject]@{ label = '(f) CONTROL note: and 4300 digits, which PyYAML loads'; with = ('note: ' + ('1' * 4300)); release = $true })
foreach ($c1aeCase in $c1aeCases) {
    New-PwGate -Path $c1aeGate -Id 'am-160' -BindsRel '.mission\amendments\AM-160-x.yaml' -Sha $c1aeSha
    $c1aeText = [System.IO.File]::ReadAllText($c1aeGate) + $c1aeCase.with + "`r`n"
    [System.IO.File]::WriteAllText($c1aeGate, $c1aeText, $pwUtf8)
    $c1aeE = Invoke-PwEval -Root $c1aeRoot -GoalId 'G-P3V' -Hook
    $c1aeArm = (Get-PwDetector -Text $c1aeE.text -Type $pwType).detail
    if ($c1aeCase.release) {
        Add-C1aeRow -Label ($c1aeCase.label + ' appended: the canonical gate over the exact bytes RELEASES it: MET') `
            -Ok (($c1aeE.verdict -ceq 'MET') -and ($c1aeE.exit -eq 0) -and (@($c1aeE.awaiting).Count -eq 0)) -Said ('verdict ' + $c1aeE.verdict)
    } else {
        Add-C1aeRow -Label ($c1aeCase.label + ' appended: the canonical gate over the exact bytes releases NOTHING') `
            -Ok ($c1aeE.admitted -and (@(@($c1aeE.awaiting) | Where-Object { $_.EndsWith(' ' + $c1aeRel) }).Count -eq 1) -and ($c1aeArm -notmatch 'RELEASED')) `
            -Said ('verdict ' + $c1aeE.verdict + '; exit ' + $c1aeE.exit)
    }
}
Remove-Item -LiteralPath $c1aeGate -Force
Remove-Item -LiteralPath (Join-Path $c1aeRoot $c1aeRel.Replace('/', '\')) -Force
# (g): a canonical gate naming the placement, its binds_sha256: 64 decimal digits (other bytes).
$c1aeDRel = '.mission/amendments/AM-170-x.yaml'
Write-Utf8 -Path (Join-Path $c1aeRoot $c1aeDRel.Replace('/', '\')) -Text "id: AM-170`n"
New-PwGate -Path (Join-Path $c1aeGates 'amendment-material-am-170.yaml') -Id 'am-170' -BindsRel '.mission\amendments\AM-170-x.yaml' -Sha ('1' * 64)
$c1aeD = Invoke-PwEval -Root $c1aeRoot -GoalId 'G-P3V' -Hook
$c1aeDArm = (Get-PwDetector -Text $c1aeD.text -Type $pwType).detail
$c1aeDPre = Get-PwPrescription -Detail $c1aeDArm -Rel $c1aeDRel
Add-C1aeRow -Label '(g) FALSIFIER over amendment-material-am-170.yaml naming AM-170-x.yaml, its binds_sha256: 64 decimal digits, the mint is an APPROVE under another id' `
    -Ok ($c1aeD.admitted -and $c1aeDPre.found -and ($c1aeDPre.verb -ceq 'approve') -and (-not [string]::Equals([string]$c1aeDPre.args['Id'], 'am-170', [System.StringComparison]::Ordinal)) -and $c1aeDArm.Contains('amendment-material-am-170.yaml is not in the line shape')) `
    -Said ('printed: ' + $c1aeDPre.verb + ' -Id ' + [string]$c1aeDPre.args['Id'])
}
catch {
    $c1aeOk = $false
    $c1aeRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1aeRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1aeM) { Remove-PwTreeAsWritten -Base $c1aeM.base }
Check -Id 'C-1ae' -Title 'THE PLACEMENT-WINDOW ARM, WHAT THE SIXTH DRAFT''S REVIEW FOUND (LAM-ACCEPT amendment 54 section 8; the third package''s pre-commit review H): a canonical gate over the placement''s exact bytes releases nothing when a plain value holds 4301 digits or a double-quoted escape names a surrogate, while plain values of =<U+00AD>, -<U+00AD> and 4300 digits release; and over a canonical gate naming the placement whose binds_sha256: is 64 decimal digits, the mint is an approve under another id, noted as out of the line shape' `
      -Ok $c1aeOk -Detail ("      THE $(@($c1aeRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1aeRows -join "`n"))

# =============================================================================================
# BATCH-2 WP-H -- THE DISPATCH-MANIFEST ARM, THE HANDOFF ARM AND THE ABSENT GOAL: C-1af, C-1ag,
# C-1ah and C-3g (the BATCH-2 charter, WP-H (a),
# (b) and (c), as the operator ruled it)
# =============================================================================================
# THE CHARTER'S WORDS, verbatim:
#   (a) "`ungated_manifest_absent`: an untracked dispatch manifest under .mission/dispatches/ with no
#       `dispatch-<id>` gate on disk is an admitted stop (the placement arm's pattern); STATUS.md head
#       `AWAITING DISPATCH GATE <bare id> <sha256 LF/blob>; <working>`; the dispatch gate is the
#       release; a tracked or gated manifest does not admit."
#   (b) "`handoff_brief_present`: STATUS.md's head reading `HANDOFF AT <ctx%> <sha256 of the brief>`
#       with the brief's sha re-derived by the evaluator admits ONE stop; the successor's first stop
#       is not admitted by it (the arm records the admitted head's sha in its verdict and refuses a
#       second admission on the same sha)."
#   (c) as ruled by the operator on 2026-09-30 (lean A): an ABSENT named goal file stays an
#       admitted stop, but never silently -- a GOAL_ABSENT verdict naming the goal id and every path
#       searched; a goal file that EXISTS but does not parse or declares no detectors REFUSES the stop.
# THE FOUR MEMBERS. C-1af drives the dispatch-manifest arm, C-1ag the handoff arm, C-1ah the absent and
# the unreadable goal; C-3g measures the residuals the charter states (design v2.3 SS4.5 law 2) and that
# they are no wider, and closes with the plane row. Every falsifier row is RED at the tree before the
# cure: a goal declaring either type is refused as UNKNOWN, an absent goal is approved with no verdict
# at all, and a goal file that cannot be read is approved by the evaluator's trap.
#
# THE FIXTURE FORM IS C-1x's (New-PwMission): a real git repository under %TEMP%, its git dir asserted
# EXACTLY <root>\.git before git is used again (the 2026-09-13 rule), its COMMON dir asserted there as
# well, `git config` never run, every commit's identity on the command line, the four
# redirecting variables removed around every fixture git call. EVERY EVALUATION GOES THROUGH
# Invoke-EsEval, WHICH REFUSES A -MissionRoot OUTSIDE %TEMP%, so no member here points the evaluator at
# this worktree's mission plane or the root's; C-3g's last row compares both planes' sentinel paths
# before the first member and after the last. Every gate is FORGED in the line set of a real dispatch
# mint (dispatch-v-a-593-r1.yaml on the live plane) -- a stamped one with the runner's own consume
# block; a mint through the console is WP-4's. Every expected LF/blob digest is git's own
# (Get-PwBlobSha). No member here spawns a seat, and none writes a spawn-ledger line.
$esManType    = 'ungated_manifest_absent'
$esManVerdict = 'AWAITING_DISPATCH_GATE'
$esManPrefix  = 'AWAITING DISPATCH GATE'
$esManUnd     = $esManPrefix + ' UNDETERMINABLE UNDETERMINABLE; UNDETERMINABLE'
$esHoType     = 'handoff_brief_present'
$esHoVerdict  = 'HANDOFF_ADMITTED'
$esHoPrefix   = 'HANDOFF ADMITTED'
$esAbsVerdict = 'GOAL_ABSENT'
$esTempRoot   = [System.IO.Path]::GetFullPath($env:TEMP).TrimEnd('\') + '\'
$esEvalRoots  = New-Object System.Collections.Generic.List[string]
$esMask       = '(?m)^evaluated_at: .*$'
$esCommitArgs = @('-c', 'user.name=wp3-es', '-c', 'user.email=wp3-es@example.invalid', '-c', 'commit.gpgsign=false', 'commit', '--quiet', '-m')
# THE BASE: this branch's parent at the cut, each file pinned by its LF/blob sha256.
$esBaseSha    = '700e19e5-s02'
$esBasePins   = [ordered]@{
    'mission-goal-check.ps1'   = '70e46db825b967ccf642c4aa0dd983a128d0b4cc0a9c245b5660fe22931f79ea'
    'lam-verify-admission.ps1' = 'ccd0d7d1656a0dba4187585d5e583d604e3c65882c094c7df704b800f4d4ba58'
    'lam-gate-class.ps1'       = 'bc7a3cd885709c5df5661f3a5cd308b878e7d63e89246a43e3d029278247e577'
    'lam-instrument-run.ps1'   = 'ecf28251ba9a98bf599513d85a5d6999874d13b09ea4ce62dbf7af47a8369245'
}
# EVERY GOAL ID THESE MEMBERS EVALUATE -- the names a misdirected evaluation would leave a verdict under.
$esGoalIds = @('G-MAN', 'G-NOMAN', 'G-MORDER', 'G-BOTH', 'G-HO', 'G-HOU', 'G-HO2', 'G-HONO', 'G-HOMAN', 'G-HORDER',
               'G-NONE', 'G-LOC2', 'G-LOCK', 'G-DIR', 'G-NODET', 'G-EMPTY', 'G-MET3', 'G-UNMET3', 'G-RES', 'G-RESHO', 'G-RESS',
               'G-TRAP',
               'G-WJ1', 'G-WJ2', 'G-WJ3', 'G-WJ4', 'G-WJ4M', 'G-WJ5', 'G-WJM', 'G-WJN', 'G-WJP', 'G-WJD', 'G-WJH', 'G-WJT', 'G-WJ-NONE',
               'G-RUA', 'G-RU0', 'G-RU30', 'G-RUBAD', 'G-HS', 'G-HSD', 'G-HSN', 'G-HSX', 'G-HSO', 'G-HSS', 'G-HS-NONE', 'G-HOR',
               'G-N30', 'G-N30C', 'G-N30Q', 'G-N7D', 'G-NNEG', 'G-NEMPTY', 'G-NDUP', 'G-NFIRST', 'G-NCNT', 'G-NCNT0', 'G-NCAP', 'G-NCAP0', 'G-NMIN', 'G-NTWO', 'G-NOTHER',
               'G-NMAX', 'G-NMAX1', 'G-NHALT', 'G-NHDIR',
               'G-GONE', 'G-HOV', 'G-HOV2', 'G-KC30', 'G-KCB', 'G-KCA',
               'G-PL', 'G-PLOLD', 'G-PLDEF', 'G-PLBOTH', 'G-PLCOM', 'G-PLEMPTY', 'G-PLBLOCK', 'G-PLDUP', 'G-PL5', 'G-PLQ', 'G-PLQ1')

function Get-EsPlaneSnapshot {
    # WHAT A MISDIRECTED MEMBER WOULD LEAVE ON A LIVE PLANE, by stat alone (nothing is opened): on this
    # worktree AND on the primary checkout, the handoff arm's admissions record and a verdict file under
    # every goal id above; on this worktree, the .mission\goals and .mission\dispatches listings (name,
    # length, write time), a verdict file an ARC-* goal's own Stop hook may write set aside. One text.
    $esSb = New-Object System.Text.StringBuilder
    foreach ($esPlane in @(@($repoRoot, $primaryRoot) | Where-Object { $_ } | Select-Object -Unique)) {
        $esRec = Join-Path $esPlane '.mission-runtime\lam\handoff-admissions.jsonl'
        [void]$esSb.AppendLine($esRec + ' exists=' + (Test-Path -LiteralPath $esRec))
        foreach ($esG in $script:esGoalIds) {
            $esVf = Join-Path $esPlane ('.mission\goals\' + $esG + '.verdict.yaml')
            if (Test-Path -LiteralPath $esVf) { [void]$esSb.AppendLine($esVf + ' EXISTS') }
        }
    }
    foreach ($esSub in @('.mission\goals', '.mission\dispatches')) {
        $esDir = Join-Path $repoRoot $esSub
        foreach ($esF in @(Get-ChildItem -LiteralPath $esDir -Force -ErrorAction SilentlyContinue | Sort-Object Name)) {
            if ($esF.Name -match '\AARC-.*\.verdict\.yaml\z') { continue }
            [void]$esSb.AppendLine(('{0}\{1} {2} {3}' -f $esSub, $esF.Name, $(if ($esF.PSIsContainer) { 'dir' } else { $esF.Length }), $esF.LastWriteTimeUtc.ToString('o')))
        }
    }
    return $esSb.ToString()
}
$esPlaneBefore = Get-EsPlaneSnapshot

function Write-EsManifest {
    # A round manifest in the form of .mission/dispatches/*.manifest.yaml (D-V-A-593.manifest.yaml): its id:,
    # kind, round, spawn_order, an optional operator_note and an artifacts row. -Id '' writes no id: line;
    # -Extra appends lines; -Crlf writes CR LF, so git's blob digest and the working copy's differ.
    param([string]$Root, [string]$Rel, [string]$Id, [string]$Note, [switch]$Crlf, [string[]]$Extra)
    $esLines = @('# a round manifest written by WP-3''s BATCH-2 members')
    if ($Id) { $esLines += ('id: ' + $Id) }
    $esLines += @('kind: validator-manifest', 'round: R-FIXTURE', 'spawn_order: [D-FIX]')
    if ($Note) { $esLines += ('operator_note: ' + $Note) }
    $esLines += @('artifacts:', '- path: .mission/dispatches/D-FIX.yaml', ('  sha256: ' + ('0' * 64)))
    if ($Extra) { $esLines += $Extra }
    $esEol = if ($Crlf) { "`r`n" } else { "`n" }
    Set-PwBytes -Path (Join-Path $Root $Rel.Replace('/', '\')) -Bytes ($pwUtf8.GetBytes(($esLines -join $esEol) + $esEol))
}
function New-EsDispatchGate {
    # A dispatch gate in the line set and order of a real mint (dispatch-v-a-593-r1.yaml), CR LF, its
    # expires_at already PAST. -Consumed appends the runner's own consume block as lam-dispatch-gate.ps1
    # writes it (consumed_at stamped, its basis, the manifest sha256, consumed_spawns and one spawn line,
    # the gate's last block); -RevokedAt appends mission-gate.ps1's three revoke lines; -Append appends
    # text; -Kind and -IdField override those lines.
    param([string]$Path, [string]$Id, [string]$BindsRel, [string]$Sha, [string]$IdField = '', [string]$Kind = 'dispatch',
          [string]$RevokedAt = '', [switch]$Consumed, [string]$Append = '')
    if (-not $IdField) { $IdField = $Id }
    $esGl = @('# Gate artifact -- created by a human, consumed once, retained for audit.',
              '# WP-3 BATCH-2 fixture: forged in the line set and order of a real dispatch mint.',
              ('kind: ' + $Kind), 'gate_class: build-authorization', ('id: ' + $IdField), ('push_id: dispatch-' + $IdField),
              ('binds: ' + $BindsRel),
              'binds_resolved_note: "RECORD, not an input: the absolute path this mint actually hashed. Consumers re-derive rather than trust it."',
              'binds_resolved: wp3-fixture', ('binds_sha256: ' + $Sha), 'authorized_by: wp3-es', 'host: wp3',
              'operator_credential: injected-seam', 'created_at: 2026-09-30T00:00:00.000Z', 'expires_at: 2026-09-30T01:00:00.000Z',
              'single_use: true')
    if ($Consumed) {
        $esGl += @('consumed_at: 2026-09-30T00:30:00.000Z', 'consumed_basis: spawn by the runner under this gate', ('consumed_manifest_sha256: ' + $Sha), 'consumed_spawns:', '  - {seq: 1, dispatch_id: D-FIX}')
    } else { $esGl += 'consumed_at: null' }
    $esGt = ($esGl -join "`r`n") + "`r`n"
    if ($Append) { $esGt += $Append }
    if ($RevokedAt) { $esGt += 'revoked_at: ' + $RevokedAt + "`nrevoked_by: wp3-es`nrevoked_reason: `"WP-3 fixture revocation`"`n" }
    Write-Utf8 -Path $Path -Text $esGt
}
function New-EsMission {
    # New-PwMission's repository (git dir asserted EXACTLY <root>\.git before anything else), its COMMON dir
    # asserted there too before any further git call, then a second commit tracking one round
    # manifest (D-TRACKED.manifest.yaml) and one dispatch artifact. ok = $false with the reason otherwise.
    param([string]$Tag)
    $esM = New-PwMission -Tag $Tag
    $esM | Add-Member -NotePropertyName commonDir -NotePropertyValue ''
    if (-not $esM.ok) { return $esM }
    $esCd = Invoke-PwGit -Root $esM.root -GitArgs @('rev-parse', '--git-common-dir')
    $esCdText = $esCd.text.Trim().Replace('/', '\')
    if ($esCdText -and (-not [System.IO.Path]::IsPathRooted($esCdText))) { $esCdText = Join-Path $esM.root $esCdText }
    $esCdFull = if ($esCdText) { [System.IO.Path]::GetFullPath($esCdText) } else { '' }
    $esWant = [System.IO.Path]::GetFullPath((Join-Path $esM.root '.git'))
    if (($esCd.exit -ne 0) -or ($esCdFull -ine $esWant)) {
        $esM.ok = $false
        $esM.why = 'the fixture common dir is not exactly ' + $esWant + ' (rev-parse exit ' + $esCd.exit + ': ' + $esCd.text.Trim() + '); nothing further was run'
        return $esM
    }
    $esM.commonDir = $esCdFull
    Write-EsManifest -Root $esM.root -Rel '.mission/dispatches/D-TRACKED.manifest.yaml' -Id 'v-tracked-r1' -Note 'tracked by the fixture''s second commit'
    Write-Utf8 -Path (Join-Path $esM.root '.mission\dispatches\D-TRACKED.yaml') -Text "id: D-TRACKED`n"
    $esAdd = Invoke-PwGit -Root $esM.root -GitArgs @('add', '--', '.mission/dispatches')
    $esCom = Invoke-PwGit -Root $esM.root -GitArgs ($script:esCommitArgs + @('dispatches'))
    $esLs = Invoke-PwGit -Root $esM.root -GitArgs @('ls-files', '--', '.mission/dispatches')
    $esLsCount = @(($esLs.text -split "`n") | Where-Object { $_.Trim() }).Count
    if (($esAdd.exit -ne 0) -or ($esCom.exit -ne 0) -or ($esLsCount -ne 2)) {
        $esM.ok = $false
        $esM.why = 'the dispatches commit did not land as expected: add exit ' + $esAdd.exit + ', commit exit ' + $esCom.exit + ', ls-files lists ' + $esLsCount + ' of 2'
    }
    return $esM
}
function New-EsBaseEvaluator {
    # The base evaluator and its three libraries, each at its pinned LF/blob sha256, under -Dir.
    param([string]$Dir)
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    $esPinOk = $true
    $esPinSaid = New-Object System.Collections.Generic.List[string]
    foreach ($esPinName in @($script:esBasePins.Keys)) {
        # Through Get-LamBaseBytes: the installed fixtures alone, no history -- the pin decides.
        $esRead = Get-LamBaseBytes -Base $script:esBaseSha -Path ('tools/lam/' + $esPinName) -Pin $script:esBasePins[$esPinName]
        if (-not $esRead.ok) { $esPinOk = $false }
        $esPinSaid.Add($esPinName + ' ' + $esRead.sha.Substring(0, 8) + ' (' + $esRead.from + ')')
        [System.IO.File]::WriteAllBytes((Join-Path $Dir $esPinName), $esRead.bytes)
    }
    return [pscustomobject]@{ ok = $esPinOk; path = (Join-Path $Dir 'mission-goal-check.ps1'); said = ($esPinSaid -join ', ') }
}
function Invoke-EsEval {
    # The evaluator under test, as the Stop hook runs it (-Hook: a Stop payload on stdin) or by hand -- AT A
    # FIXTURE ONLY: a -Root outside %TEMP% is REFUSED before anything runs (the plane rule). LAM_DISPATCH is
    # cleared for the child and put back; the prior verdict artifact at <root>\.mission\goals is removed
    # first. Returns exit, out, text, verdict, decision, reason (the hook's JSON), shortCircuited, the list
    # keys (dispatch, notes, placement, handoff, refused, searched), whether two of them are written, and
    # admitted (the hook approved AND exited 0: exit 2 blocks whatever the JSON says).
    param([string]$Root, [string]$GoalId, [switch]$Hook, [string]$Evaluator, [string]$GoalFile)
    if (-not $Evaluator) { $Evaluator = $goalCheck }
    $esFull = [System.IO.Path]::GetFullPath($Root)
    if (-not $esFull.StartsWith($script:esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ('PLANE RULE: ' + $esFull + ' is not under ' + $script:esTempRoot + ' -- these members evaluate fixtures only')
    }
    $script:esEvalRoots.Add($esFull)
    $esVf = Join-Path $Root ('.mission\goals\' + $GoalId + '.verdict.yaml')
    if (Test-Path -LiteralPath $esVf -PathType Leaf) { Remove-Item -LiteralPath $esVf -Force }
    $esArgv = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $Evaluator, '-Goal', $GoalId, '-MissionRoot', $Root)
    if ($GoalFile) { $esArgv += @('-GoalFile', $GoalFile) }
    if ($Hook) { $esArgv += '-AsStopHook' }
    $esSavedDispatch = $env:LAM_DISPATCH
    $env:LAM_DISPATCH = $null
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        if ($Hook) {
            $esPayload = (@{ session_id = 'wp3-es'; hook_event_name = 'Stop' } | ConvertTo-Json -Compress)
            $esO = $esPayload | & powershell @esArgv 2>&1
        } else {
            $esO = & powershell @esArgv 2>&1
        }
        $esC = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $prevEap
        if ($null -ne $esSavedDispatch) { $env:LAM_DISPATCH = $esSavedDispatch }
    }
    $esOut = ((@($esO) | ForEach-Object { [string]$_ }) -join "`n")
    $esText = if (Test-Path -LiteralPath $esVf -PathType Leaf) { [System.IO.File]::ReadAllText($esVf) } else { '' }
    $esV = '(no verdict file)'
    $esVm = [regex]::Match($esText, '(?m)^verdict:[ \t]*(\S+)')
    if ($esVm.Success) { $esV = $esVm.Groups[1].Value }
    $esSc = -1
    $esScm = [regex]::Match($esText, '(?m)^short_circuited:[ \t]*(\d+)')
    if ($esScm.Success) { $esSc = [int]$esScm.Groups[1].Value }
    $esDec = ''
    $esReason = ''
    foreach ($esLn in @($esOut -split "`n")) {
        $esT = $esLn.Trim()
        if (-not $esT.StartsWith('{')) { continue }
        try { $esJ = $esT | ConvertFrom-Json; $esDec = [string]$esJ.decision; $esReason = [string]$esJ.reason; break } catch { }
    }
    return [pscustomobject]@{ exit = $esC; out = $esOut; text = $esText; verdict = $esV; decision = $esDec; reason = $esReason; shortCircuited = $esSc
                              dispatch = @(Get-PwListKey -Text $esText -Key 'awaiting_dispatch_gate')
                              notes = @(Get-PwListKey -Text $esText -Key 'awaiting_dispatch_gate_notes')
                              placement = @(Get-PwListKey -Text $esText -Key 'awaiting_amendment_gate')
                              handoff = @(Get-PwListKey -Text $esText -Key 'handoff_admitted')
                              refused = @(Get-PwListKey -Text $esText -Key 'handoff_refused')
                              searched = @(Get-PwListKey -Text $esText -Key 'goal_searched')
                              dispatchKey = [bool]($esText -match '(?m)^awaiting_dispatch_gate:')
                              handoffKey = [bool]($esText -match '(?m)^handoff_admitted:')
                              admitted = (($esDec -ceq 'approve') -and ($esC -eq 0)) }
}
function Get-EsHandLines {
    # The hand-run's status line for <Verdict> and the lines directly under it, CR stripped.
    param([string]$Out, [string]$GoalId, [string]$Verdict, [int]$Take = 3)
    $esHl = @(($Out -replace "`r", '') -split "`n")
    $esHi = [array]::IndexOf($esHl, ('mission-goal-check: ' + $GoalId + ' -> ' + $Verdict))
    $esUnder = New-Object System.Collections.Generic.List[string]
    if ($esHi -ge 0) { for ($esK = 1; ($esK -le $Take) -and (($esHi + $esK) -lt $esHl.Count); $esK++) { $esUnder.Add($esHl[$esHi + $esK]) } }
    return [pscustomobject]@{ index = $esHi; under = @($esUnder.ToArray()) }
}
function Write-EsBytes {
    # Bytes to <Root>\<Rel> ('/'-separated); returns the full path.
    param([string]$Root, [string]$Rel, [byte[]]$Bytes)
    $esP = Join-Path $Root $Rel.Replace('/', '\')
    Set-PwBytes -Path $esP -Bytes $Bytes
    return $esP
}
function Write-EsStatus {
    # STATUS.md at <Root>\.mission-runtime\lam in the form the live plane's file has: the head, its first
    # line; the edition's brief beneath; editions separated by ---. -Bom writes a UTF-8 byte-order mark first.
    param([string]$Root, [string]$Head, [switch]$Bom)
    $esSt = $Head + "`n`n# THE EDITION'S BRIEF (fixture)`n`nbody of the edition`n`n---`n`nAN OLDER EDITION's head`n`nits body`n"
    $esBytes = $pwUtf8.GetBytes($esSt)
    if ($Bom) { $esBytes = [byte[]](@(0xEF, 0xBB, 0xBF) + $esBytes) }
    Set-PwBytes -Path (Join-Path $Root '.mission-runtime\lam\STATUS.md') -Bytes $esBytes
}
function Get-EsRecord {
    # The handoff arm's admissions record at <Root>: its non-empty lines, each parsed as JSON where it parses.
    param([string]$Root)
    $esRp = Join-Path $Root '.mission-runtime\lam\handoff-admissions.jsonl'
    $esOut = [pscustomobject]@{ path = $esRp; exists = (Test-Path -LiteralPath $esRp -PathType Leaf); count = 0; objects = @(); text = '' }
    if (-not $esOut.exists) { return $esOut }
    $esOut.text = [System.IO.File]::ReadAllText($esRp)
    $esObjs = New-Object System.Collections.Generic.List[object]
    foreach ($esRl in @($esOut.text -split "`n")) {
        if (-not $esRl.Trim()) { continue }
        $esOut.count++
        try { $esObjs.Add(($esRl | ConvertFrom-Json)) } catch { $esObjs.Add($null) }
    }
    $esOut.objects = @($esObjs.ToArray())
    return $esOut
}
function Get-EsHead {
    param([string]$Ctx, [string]$Lf, [string]$Raw, [string]$Path)
    return ('HANDOFF AT ' + $Ctx + '% ' + $Lf + '; ' + $Raw + ' ' + $Path)
}

# =============================================================================================
# C-1af -- THE DISPATCH-MANIFEST ARM: an untracked round manifest that no live
#          dispatch gate binds is an ADMITTED stop, evaluated first
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure: (a) a goal declaring ungated_manifest_absent is refused
# as an UNKNOWN detector; (b)/(c) with an untracked, ungated manifest and no HALT the stop is refused --
# the hook BLOCKS. THE CONTROLS, each its own row: (d) a tracked manifest, edited or not; (e) a canonical
# dispatch gate over EITHER digest releases -- also once the runner has stamped it, and whatever its id
# (bytes decide, as for the placement arm) -- and what does NOT release: revoked, other bytes, another kind, a
# name aside, another id:, the same id in another case, a line out of the console's shape; (f) a goal
# WITHOUT the type, through this tree's evaluator and the base (pinned); (g) what the arm
# cannot establish ADMITS, its cause in the line; (h) the arm declared last is evaluated first and in
# hook mode the instrument never runs; (i) a HALT outranks it and names it; (j) beside the placement-
# window arm; (k) the operator_note as printed.
$c1afOk = $true
$c1afRows = New-Object System.Collections.Generic.List[string]
function Add-C1afRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1afOk = $false }
    $script:c1afRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1afRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1afM = $null
$c1afHeld = $null
try {
$c1afM = New-EsMission -Tag 'c1af'
if (-not $c1afM.ok) { throw ('FIXTURE REFUSED: ' + $c1afM.why) }
$c1afRoot = $c1afM.root
$c1afGates = Join-Path $c1afRoot '.mission\gates'
Add-C1afRow -Label 'FIXTURE a git repository under %TEMP%, its git dir AND common dir exactly <root>\.git, one commit tracking a manifest' -Ok $true -Said ($c1afRoot + ' ; common dir ' + $c1afM.commonDir)
Write-PwGoal -Root $c1afRoot -GoalId 'G-MAN' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', ('  - type: ' + $esManType))

# (a) THE TYPE IS KNOWN, and the tracked manifest admits nothing.
$c1afA = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN'
$c1afAArm = Get-PwDetector -Text $c1afA.text -Type $esManType
Add-C1afRow -Label '(a) FALSIFIER the type is KNOWN: a clean fixture reads MET, exit 0, the arm ok, 1 tracked manifest, no UNKNOWN refusal, the key written empty' `
    -Ok (($c1afA.verdict -ceq 'MET') -and ($c1afA.exit -eq 0) -and $c1afAArm.ok -and ($c1afAArm.detail -match '1 tracked manifest\(s\)') -and ($c1afA.text -notmatch 'UNKNOWN detector type') -and $c1afA.dispatchKey -and (@($c1afA.dispatch).Count -eq 0)) `
    -Said ('verdict ' + $c1afA.verdict + ', exit ' + $c1afA.exit + '; the arm: ' + $c1afAArm.detail)

# (b) THE ADMITTED STOP, as the Stop hook runs it (M1).
$c1afRel = '.mission/dispatches/D-V-FIX-1.manifest.yaml'
$c1afFull = Join-Path $c1afRoot $c1afRel.Replace('/', '\')
$c1afBinds = '.mission\dispatches\D-V-FIX-1.manifest.yaml'
$c1afNote = 'round R-FIX-1: authorize one validator over A-999; no ruling beyond authorization is asked'
Write-EsManifest -Root $c1afRoot -Rel $c1afRel -Id 'v-fix-r1' -Note $c1afNote -Crlf
$c1afLf = Get-PwBlobSha -Root $c1afRoot -Rel $c1afRel
$c1afRaw = Get-PwRawSha -Path $c1afFull
$c1afLine = $esManPrefix + ' v-fix-r1 ' + $c1afLf + '; ' + $c1afRaw
$c1afNoted = $c1afLine + ' -- operator_note: ' + $c1afNote
$c1afSt = Invoke-PwGit -Root $c1afRoot -GitArgs @('status', '--porcelain', '--untracked-files=all', '--', '.mission/dispatches')
Add-C1afRow -Label 'FIXTURE git reads the manifest UNTRACKED; its CR LF makes git''s blob digest and the working copy''s differ; no gate, no HALT' `
    -Ok (($c1afSt.text -match '(?m)^\?\? \.mission/dispatches/D-V-FIX-1\.manifest\.yaml') -and [bool]$c1afLf -and ($c1afLf -cne $c1afRaw) -and (@(Get-ChildItem -LiteralPath $c1afGates -File -Force).Count -eq 0) -and (-not (Test-Path -LiteralPath (Join-Path $c1afRoot '.mission-runtime\halts')))) `
    -Said ($c1afSt.text + ' ; LF/blob ' + $c1afLf + ' ; working ' + $c1afRaw)
$c1afB = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(b) FALSIFIER hook mode, untracked + ungated + no open HALT: the hook APPROVES and exits 0 (the stop is admitted)' `
    -Ok $c1afB.admitted -Said ('exit ' + $c1afB.exit + ' ' + $c1afB.out)
Add-C1afRow -Label ('(b) the verdict reads ' + $esManVerdict + ', open_halts: [], and awaiting_dispatch_gate names the line exactly, both digests') `
    -Ok (($c1afB.verdict -ceq $esManVerdict) -and ($c1afB.text -match '(?m)^open_halts: \[\]') -and (@($c1afB.dispatch).Count -eq 1) -and (@($c1afB.dispatch)[0] -ceq $c1afLine)) `
    -Said ('verdict ' + $c1afB.verdict + '; awaiting_dispatch_gate [' + (@($c1afB.dispatch) -join ' ; ') + ']; expected [' + $c1afLine + ']')
Add-C1afRow -Label '(b) the hook reason LEADS with that line, the operator_note beside it; the artifact pairs the note with its line' `
    -Ok ($c1afB.reason.StartsWith($c1afNoted) -and (@($c1afB.notes).Count -eq 1) -and (@($c1afB.notes)[0] -ceq $c1afNoted)) `
    -Said ('reason: ' + $c1afB.reason + ' | notes [' + (@($c1afB.notes) -join ' ; ') + ']')

# (c) THE SAME, by hand: exit 5, the line and the note beneath the status line.
$c1afC = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN'
$c1afCH = Get-EsHandLines -Out $c1afC.out -GoalId 'G-MAN' -Verdict $esManVerdict -Take 2
Add-C1afRow -Label ('(c) FALSIFIER by hand: exit 5, "-> ' + $esManVerdict + '", the NEXT line the AWAITING line and the one after it the operator_note') `
    -Ok (($c1afC.exit -eq 5) -and ($c1afCH.index -ge 0) -and (@($c1afCH.under).Count -eq 2) -and (@($c1afCH.under)[0] -ceq ('  ' + $c1afLine)) -and (@($c1afCH.under)[1] -ceq ('    operator_note: ' + $c1afNote))) `
    -Said ('exit ' + $c1afC.exit + '; status line at index ' + $c1afCH.index + '; under it: ' + (@($c1afCH.under) -join ' | '))

# (d) CONTROL: the SAME manifest TRACKED -- committed; then edited in the working copy -- does not admit (M2).
$c1afDAdd = Invoke-PwGit -Root $c1afRoot -GitArgs @('add', '--', $c1afRel)
$c1afDCom = Invoke-PwGit -Root $c1afRoot -GitArgs ($esCommitArgs + @('track the manifest'))
$c1afD = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(d) CONTROL the SAME manifest COMMITTED (tracked, no gate) does not admit: MET, approve, awaiting_dispatch_gate: []' `
    -Ok (($c1afDAdd.exit -eq 0) -and ($c1afDCom.exit -eq 0) -and ($c1afD.verdict -ceq 'MET') -and $c1afD.admitted -and $c1afD.dispatchKey -and (@($c1afD.dispatch).Count -eq 0)) `
    -Said ('verdict ' + $c1afD.verdict + '; the arm: ' + (Get-PwDetector -Text $c1afD.text -Type $esManType).detail)
[System.IO.File]::AppendAllText($c1afFull, "edited: in the working copy, still tracked`r`n", $pwUtf8)
$c1afD2 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(d) CONTROL ... and EDITED in the working copy, still tracked, still ungated: MET' `
    -Ok (($c1afD2.verdict -ceq 'MET') -and $c1afD2.admitted -and (@($c1afD2.dispatch).Count -eq 0)) -Said ('verdict ' + $c1afD2.verdict)
$c1afDRm = Invoke-PwGit -Root $c1afRoot -GitArgs @('rm', '--cached', '--quiet', '--', $c1afRel)
$c1afDCom2 = Invoke-PwGit -Root $c1afRoot -GitArgs ($esCommitArgs + @('untrack the manifest again'))
Write-EsManifest -Root $c1afRoot -Rel $c1afRel -Id 'v-fix-r1' -Note $c1afNote -Crlf
$c1afSt2 = Invoke-PwGit -Root $c1afRoot -GitArgs @('status', '--porcelain', '--untracked-files=all', '--', '.mission/dispatches')
Add-C1afRow -Label 'FIXTURE the manifest untracked again (git rm --cached, committed), its first bytes restored' `
    -Ok (($c1afDRm.exit -eq 0) -and ($c1afDCom2.exit -eq 0) -and ($c1afSt2.text -match '(?m)^\?\? \.mission/dispatches/D-V-FIX-1\.manifest\.yaml') -and ((Get-PwRawSha -Path $c1afFull) -ceq $c1afRaw)) -Said $c1afSt2.text

# (e) CONTROL: a canonical dispatch gate over EITHER digest releases (M3), also once stamped, whatever its id.
$c1afGate = Join-Path $c1afGates 'dispatch-v-fix-r1.yaml'
New-EsDispatchGate -Path $c1afGate -Id 'v-fix-r1' -BindsRel $c1afBinds -Sha $c1afRaw
$c1afE1 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
$c1afE1Arm = (Get-PwDetector -Text $c1afE1.text -Type $esManType).detail
Add-C1afRow -Label '(e) CONTROL a canonical dispatch gate over the WORKING-COPY digest (what a mint records) releases: MET, the gate named' `
    -Ok (($c1afE1.verdict -ceq 'MET') -and $c1afE1.admitted -and (@($c1afE1.dispatch).Count -eq 0) -and ($c1afE1Arm -match 'RELEASED by dispatch-v-fix-r1\.yaml')) `
    -Said ('verdict ' + $c1afE1.verdict + '; the arm: ' + $c1afE1Arm)
New-EsDispatchGate -Path $c1afGate -Id 'v-fix-r1' -BindsRel $c1afBinds -Sha $c1afLf
$c1afE2 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(e) CONTROL the same gate over the LF/BLOB digest (git''s own) releases: MET' `
    -Ok (($c1afE2.verdict -ceq 'MET') -and (@($c1afE2.dispatch).Count -eq 0)) -Said ('verdict ' + $c1afE2.verdict)
New-EsDispatchGate -Path $c1afGate -Id 'v-fix-r1' -BindsRel $c1afBinds -Sha $c1afRaw -Consumed
$c1afE3 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(e) CONTROL the same gate STAMPED by the runner (its consume block, consumed_spawns last) still releases: the stamp does not re-admit' `
    -Ok (($c1afE3.verdict -ceq 'MET') -and (@($c1afE3.dispatch).Count -eq 0)) -Said ('verdict ' + $c1afE3.verdict + '; the arm: ' + (Get-PwDetector -Text $c1afE3.text -Type $esManType).detail)
Remove-Item -LiteralPath $c1afGate -Force
$c1afOther = Join-Path $c1afGates 'dispatch-v-other-r9.yaml'
New-EsDispatchGate -Path $c1afOther -Id 'v-other-r9' -BindsRel $c1afBinds -Sha $c1afRaw
$c1afE4 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(e) CONTROL a canonical gate under ANOTHER id (dispatch-v-other-r9.yaml) over the same bytes releases: bytes decide, as the runner links them' `
    -Ok (($c1afE4.verdict -ceq 'MET') -and (@($c1afE4.dispatch).Count -eq 0) -and ((Get-PwDetector -Text $c1afE4.text -Type $esManType).detail -match 'RELEASED by dispatch-v-other-r9\.yaml')) `
    -Said ('verdict ' + $c1afE4.verdict)
Remove-Item -LiteralPath $c1afOther -Force
# ... and what the definition reads DOES disqualify a gate: each case the stop stays admitted, the reason named.
$c1afNot = @(
    [pscustomobject]@{ label = 'REVOKED (revoked_at set over (e)''s text)'; files = @('dispatch-v-fix-r1.yaml'); sha = $c1afRaw; kind = 'dispatch'; idField = ''; revoked = '2026-09-30T02:00:00.000Z'; append = ''; consumed = $false; says = 'dispatch-v-fix-r1.yaml binds these bytes and is REVOKED' },
    [pscustomobject]@{ label = 'over OTHER bytes (the manifest edited after its mint)'; files = @('dispatch-v-fix-r1.yaml'); sha = ('ab' * 32); kind = 'dispatch'; idField = ''; revoked = ''; append = ''; consumed = $false; says = 'dispatch-v-fix-r1.yaml, the gate this manifest''s id names, binds OTHER bytes' },
    [pscustomobject]@{ label = 'of ANOTHER kind (kind: push at the canonical path)'; files = @('dispatch-v-fix-r1.yaml'); sha = $c1afRaw; kind = 'push'; idField = ''; revoked = ''; append = ''; consumed = $false; says = 'dispatch-v-fix-r1.yaml binds these bytes but its kind is not dispatch' },
    [pscustomobject]@{ label = 'RENAMED ASIDE (a .revoked-1 name with no stamp, and a " - Copy")'; files = @('dispatch-v-fix-r1.revoked-1.yaml', 'dispatch-v-fix-r1 - Copy.yaml'); sha = $c1afRaw; kind = 'dispatch'; idField = ''; revoked = ''; append = ''; consumed = $false; says = 'binds these bytes but is NOT a canonical gate' },
    [pscustomobject]@{ label = 'whose id: is ANOTHER id (v-fix-r2 in dispatch-v-fix-r1.yaml)'; files = @('dispatch-v-fix-r1.yaml'); sha = $c1afRaw; kind = 'dispatch'; idField = 'v-fix-r2'; revoked = ''; append = ''; consumed = $false; says = 'binds these bytes but is NOT a canonical gate' },
    [pscustomobject]@{ label = 'whose id: differs from its name ONLY IN CASE (V-FIX-R1)'; files = @('dispatch-v-fix-r1.yaml'); sha = $c1afRaw; kind = 'dispatch'; idField = 'V-FIX-R1'; revoked = ''; append = ''; consumed = $false; says = 'binds these bytes but is NOT a canonical gate' },
    [pscustomobject]@{ label = 'carrying an INDENTED line the console never writes'; files = @('dispatch-v-fix-r1.yaml'); sha = $c1afRaw; kind = 'dispatch'; idField = ''; revoked = ''; append = "  note: an indented line no mint writes`r`n"; consumed = $false; says = 'binds these bytes but is not in the line shape' },
    [pscustomobject]@{ label = 'stamped, with a key AFTER its consumed_spawns list (the runner''s block is the last)'; files = @('dispatch-v-fix-r1.yaml'); sha = $c1afRaw; kind = 'dispatch'; idField = ''; revoked = ''; append = "note: a key after consumed_spawns`r`n"; consumed = $true; says = 'binds these bytes but is not in the line shape' })
foreach ($c1afCase in $c1afNot) {
    foreach ($c1afGf in $c1afCase.files) {
        New-EsDispatchGate -Path (Join-Path $c1afGates $c1afGf) -Id 'v-fix-r1' -BindsRel $c1afBinds -Sha $c1afCase.sha -Kind $c1afCase.kind -IdField $c1afCase.idField -RevokedAt $c1afCase.revoked -Append $c1afCase.append -Consumed:$c1afCase.consumed
    }
    $c1afN = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
    $c1afNArm = (Get-PwDetector -Text $c1afN.text -Type $esManType).detail
    Add-C1afRow -Label ('(e) a gate ' + $c1afCase.label + ' does NOT release: admitted, the line unchanged, the reason named') `
        -Ok ($c1afN.admitted -and ($c1afN.verdict -ceq $esManVerdict) -and (@($c1afN.dispatch).Count -eq 1) -and (@($c1afN.dispatch)[0] -ceq $c1afLine) -and $c1afNArm.Contains($c1afCase.says) -and ($c1afNArm -notmatch 'RELEASED by')) `
        -Said ('verdict ' + $c1afN.verdict + '; the arm: ' + $c1afNArm)
    foreach ($c1afGf in $c1afCase.files) { Remove-Item -LiteralPath (Join-Path $c1afGates $c1afGf) -Force }
}

# (f) CONTROL: a goal WITHOUT the type behaves as the base evaluator does, the ungated manifest on disk (M4).
$c1afBase = New-EsBaseEvaluator -Dir (Join-Path $c1afM.base 'base-tools')
Add-C1afRow -Label 'FIXTURE the base evaluator and its three libraries, from this branch''s parent at the cut, each at its pinned LF/blob sha256' -Ok $c1afBase.ok -Said $c1afBase.said
Write-PwGoal -Root $c1afRoot -GoalId 'G-NOMAN' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', '  - type: halt_absent')
$c1afFT = Invoke-EsEval -Root $c1afRoot -GoalId 'G-NOMAN'
$c1afFB = Invoke-EsEval -Root $c1afRoot -GoalId 'G-NOMAN' -Evaluator $c1afBase.path
$c1afFTH = Invoke-EsEval -Root $c1afRoot -GoalId 'G-NOMAN' -Hook
$c1afFBH = Invoke-EsEval -Root $c1afRoot -GoalId 'G-NOMAN' -Hook -Evaluator $c1afBase.path
Add-C1afRow -Label '(f) CONTROL no type declared, the ungated manifest on disk: the tree and the base read MET, exit 0, the SAME artifact (evaluated_at masked)' `
    -Ok ($c1afBase.ok -and ($c1afFT.verdict -ceq 'MET') -and ($c1afFB.verdict -ceq 'MET') -and ($c1afFT.exit -eq 0) -and ($c1afFB.exit -eq 0) -and ((Remove-WrProvenanceLine -Text (($c1afFT.text -replace $esMask, 'evaluated_at: MASKED') -replace $wjScanMask, '')) -ceq ($c1afFB.text -replace $esMask, 'evaluated_at: MASKED')) -and (-not $c1afFT.dispatchKey)) `
    -Said ('tree ' + $c1afFT.verdict + '/' + $c1afFT.exit + ', base ' + $c1afFB.verdict + '/' + $c1afFB.exit + '; awaiting_dispatch_gate key written: ' + $c1afFT.dispatchKey)
Add-C1afRow -Label '(f) CONTROL and the hook decision is the SAME JSON from both, both exiting 0' `
    -Ok ($c1afBase.ok -and ($c1afFTH.decision -ceq 'approve') -and ($c1afFTH.exit -eq 0) -and ($c1afFBH.exit -eq 0) -and ($c1afFTH.out.Trim() -ceq $c1afFBH.out.Trim())) `
    -Said ('tree: ' + $c1afFTH.out.Trim() + ' | base: ' + $c1afFBH.out.Trim())

# (g) WHAT THE ARM CANNOT ESTABLISH ADMITS THE STOP, its cause in the line (M5).
$c1afHeld = [System.IO.File]::Open($c1afFull, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try { $c1afG1 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook } finally { $c1afHeld.Dispose(); $c1afHeld = $null }
$c1afG1Arm = (Get-PwDetector -Text $c1afG1.text -Type $esManType).detail
Add-C1afRow -Label '(g) the manifest held open with no sharing: ADMITTED, UNREADABLE in both digest slots and its id UNDETERMINABLE, the path named' `
    -Ok ($c1afG1.admitted -and (@($c1afG1.dispatch).Count -eq 1) -and (@($c1afG1.dispatch)[0] -ceq ($esManPrefix + ' UNDETERMINABLE UNREADABLE; UNREADABLE')) -and $c1afG1Arm.Contains('about ' + $c1afRel + ': UNREADABLE') -and $c1afG1.reason.Contains('released only once its cause clears')) `
    -Said ('awaiting [' + (@($c1afG1.dispatch) -join ' ; ') + ']; the arm: ' + $c1afG1Arm)
$c1afIdCases = @(
    [pscustomobject]@{ rel = '.mission/dispatches/D-V-FIX-NOID.manifest.yaml'; id = ''; extra = @(); says = 'no column-0 id: line'; label = 'no id: line' },
    [pscustomobject]@{ rel = '.mission/dispatches/D-V-FIX-TWICE.manifest.yaml'; id = 'v-fix-once'; extra = @('id: v-fix-twice'); says = '2 column-0 keys fold to id:, not one'; label = 'two id: lines' },
    [pscustomobject]@{ rel = '.mission/dispatches/D-V-FIX-SPACE.manifest.yaml'; id = '"v fix"'; extra = @(); says = 'is not one token'; label = 'an id: that is not one token ("v fix")' })
foreach ($c1afIc in $c1afIdCases) {
    Write-EsManifest -Root $c1afRoot -Rel $c1afIc.rel -Id $c1afIc.id -Extra $c1afIc.extra
    $c1afIcLf = Get-PwBlobSha -Root $c1afRoot -Rel $c1afIc.rel
    $c1afIcRaw = Get-PwRawSha -Path (Join-Path $c1afRoot $c1afIc.rel.Replace('/', '\'))
    $c1afIcR = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN'
    $c1afIcArm = (Get-PwDetector -Text $c1afIcR.text -Type $esManType).detail
    Add-C1afRow -Label ('(g) a manifest with ' + $c1afIc.label + ': ADMITTED under an UNDETERMINABLE id, its own digests, the cause named') `
        -Ok ((@($c1afIcR.dispatch) -ccontains ($esManPrefix + ' UNDETERMINABLE ' + $c1afIcLf + '; ' + $c1afIcRaw)) -and $c1afIcArm.Contains($c1afIc.says) -and ($c1afIcR.exit -eq 5)) `
        -Said ('awaiting [' + (@($c1afIcR.dispatch) -join ' ; ') + ']')
    Remove-Item -LiteralPath (Join-Path $c1afRoot $c1afIc.rel.Replace('/', '\')) -Force
}
New-EsDispatchGate -Path $c1afGate -Id 'v-fix-r1' -BindsRel $c1afBinds -Sha $c1afRaw
$c1afHeld = [System.IO.File]::Open($c1afGate, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try { $c1afG2 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook } finally { $c1afHeld.Dispose(); $c1afHeld = $null }
$c1afG2Arm = (Get-PwDetector -Text $c1afG2.text -Type $esManType).detail
Add-C1afRow -Label '(g) its canonical gate held open with no sharing: ADMITTED, UNDETERMINABLE in both digest slots, the gate NAMED' `
    -Ok ($c1afG2.admitted -and (@($c1afG2.dispatch).Count -eq 1) -and (@($c1afG2.dispatch)[0] -ceq ($esManPrefix + ' v-fix-r1 UNDETERMINABLE; UNDETERMINABLE')) -and $c1afG2Arm.Contains('dispatch-v-fix-r1.yaml could not be read')) `
    -Said ('awaiting [' + (@($c1afG2.dispatch) -join ' ; ') + ']; the arm: ' + $c1afG2Arm)
$c1afHeld = New-Object System.IO.FileStream($c1afFull, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
try { $c1afG3 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' } finally { $c1afHeld.Dispose(); $c1afHeld = $null }
Add-C1afRow -Label '(g) CONTROL the manifest held by a writer that SHARES read access, its gate readable: read, released, MET' `
    -Ok (($c1afG3.verdict -ceq 'MET') -and ($c1afG3.exit -eq 0)) -Said ('verdict ' + $c1afG3.verdict)
Remove-Item -LiteralPath $c1afGate -Force
$c1afNoGit = Join-Path $c1afM.base 'nogit'
Write-EsManifest -Root $c1afNoGit -Rel '.mission/dispatches/D-NOGIT.manifest.yaml' -Id 'v-nogit-r1'
Write-Utf8 -Path (Join-Path $c1afNoGit 'evidence\built.txt') -Text "built`n"
Write-PwGoal -Root $c1afNoGit -GoalId 'G-MAN' -DetectorLines @(('  - type: ' + $esManType))
$c1afSavedCeiling = $env:GIT_CEILING_DIRECTORIES
$env:GIT_CEILING_DIRECTORIES = $c1afM.base
try {
    $c1afGProbe = Invoke-PwGit -Root $c1afNoGit -GitArgs @('rev-parse', '--git-dir')
    $c1afG4 = Invoke-EsEval -Root $c1afNoGit -GoalId 'G-MAN' -Hook
} finally {
    if ($null -ne $c1afSavedCeiling) { $env:GIT_CEILING_DIRECTORIES = $c1afSavedCeiling } else { Remove-Item Env:\GIT_CEILING_DIRECTORIES -ErrorAction SilentlyContinue }
}
Add-C1afRow -Label '(g) no repository (GIT_CEILING_DIRECTORIES bounds git''s search): ADMITTED, one UNDETERMINABLE line, git''s failure named' `
    -Ok (($c1afGProbe.exit -ne 0) -and $c1afG4.admitted -and (@($c1afG4.dispatch).Count -eq 1) -and (@($c1afG4.dispatch)[0] -ceq $esManUnd) -and ((Get-PwDetector -Text $c1afG4.text -Type $esManType).detail -match 'git could not list the tracked files')) `
    -Said ('probe exit ' + $c1afGProbe.exit + '; awaiting [' + (@($c1afG4.dispatch) -join ' ; ') + ']')

# (h) ORDER: the arm declared LAST is evaluated FIRST -- in hook mode the instrument never runs (M6).
$c1afRan = Join-Path $c1afM.base 'RAN'
$c1afInst = Join-Path $c1afM.base 'marker-instrument.ps1'
Write-Utf8 -Path $c1afInst -Text ("[System.IO.File]::WriteAllText('" + $c1afRan + "', 'ran')`r`nWrite-Output 'EXIT: 0'`r`nexit 0`r`n")
Write-PwGoal -Root $c1afRoot -GoalId 'G-MORDER' -DetectorLines @('  - type: instrument_exit0', ('    path: ' + $c1afInst), '  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esManType))
$c1afH = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MORDER' -Hook
$c1afHTypes = @(Get-PwDetectorTypes -Text $c1afH.text)
$c1afHInst = Get-PwDetector -Text $c1afH.text -Type 'instrument_exit0'
$c1afHRan = Test-Path -LiteralPath $c1afRan
Add-C1afRow -Label '(h) ORDER hook mode, the arm declared LAST: listed FIRST, admits although the goal is unmet, short_circuited 2, the instrument NEVER RAN' `
    -Ok ($c1afH.admitted -and ($c1afH.verdict -ceq $esManVerdict) -and ($c1afHTypes.Count -eq 3) -and ($c1afHTypes[0] -ceq $esManType) -and ($c1afH.shortCircuited -eq 2) -and ($c1afHInst.detail -match 'the dispatch-manifest arm admitted a stop') -and (-not $c1afHRan)) `
    -Said ('artifact order [' + ($c1afHTypes -join ', ') + ']; short_circuited ' + $c1afH.shortCircuited + '; marker written: ' + $c1afHRan + '; instrument_exit0: ' + $c1afHInst.detail)
if (Test-Path -LiteralPath $c1afRan) { Remove-Item -LiteralPath $c1afRan -Force }
$c1afH2 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MORDER'
$c1afH2Types = @(Get-PwDetectorTypes -Text $c1afH2.text)
$c1afH2Ran = Test-Path -LiteralPath $c1afRan
Add-C1afRow -Label '(h) ORDER by hand (a full run evaluates everything): the arm still first, the instrument RAN, verdict the same, exit 5' `
    -Ok (($c1afH2.verdict -ceq $esManVerdict) -and ($c1afH2.exit -eq 5) -and ($c1afH2Types.Count -eq 3) -and ($c1afH2Types[0] -ceq $esManType) -and ($c1afH2.shortCircuited -eq 0) -and $c1afH2Ran) `
    -Said ('artifact order [' + ($c1afH2Types -join ', ') + ']; short_circuited ' + $c1afH2.shortCircuited + '; marker written: ' + $c1afH2Ran)
if (Test-Path -LiteralPath $c1afRan) { Remove-Item -LiteralPath $c1afRan -Force }

# (i) A HALT STILL OUTRANKS: C-3 is unamended, and the admission is named beside it.
$c1afHalts = Join-Path $c1afRoot '.mission-runtime\halts'
Write-Utf8 -Path (Join-Path $c1afHalts 'HALT-C1AF.md') -Text "# HALT-C1AF`n`n**Status:** OPEN`n"
$c1afI = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN' -Hook
Add-C1afRow -Label '(i) with an OPEN HALT as well: verdict HALT, the hook approves and exits 0, the line still named in artifact and reason' `
    -Ok (($c1afI.verdict -ceq 'HALT') -and $c1afI.admitted -and (@($c1afI.dispatch).Count -eq 1) -and (@($c1afI.dispatch)[0] -ceq $c1afLine) -and $c1afI.reason.Contains('Also admitted: ' + $c1afNoted)) `
    -Said ('verdict ' + $c1afI.verdict + '; reason: ' + $c1afI.reason)
Remove-Item -LiteralPath $c1afHalts -Recurse -Force

# (j) BESIDE THE PLACEMENT-WINDOW ARM: both declared, both admitting; the older arm's verdict, both named.
Write-PwGoal -Root $c1afRoot -GoalId 'G-BOTH' -DetectorLines @(('  - type: ' + $pwType), ('  - type: ' + $esManType))
$c1afAmRel = '.mission/amendments/AM-777-c1af.yaml'
Write-Utf8 -Path (Join-Path $c1afRoot $c1afAmRel.Replace('/', '\')) -Text "id: AM-777-c1af`n"
$c1afJ = Invoke-EsEval -Root $c1afRoot -GoalId 'G-BOTH' -Hook
Add-C1afRow -Label ('(j) an ungated amendment AND an ungated manifest: ' + $pwVerdict + ', approve, exit 0, each list naming its own line, the reason naming both') `
    -Ok (($c1afJ.verdict -ceq $pwVerdict) -and $c1afJ.admitted -and (@($c1afJ.placement).Count -eq 1) -and (@($c1afJ.placement)[0].EndsWith(' ' + $c1afAmRel)) -and (@($c1afJ.dispatch).Count -eq 1) -and (@($c1afJ.dispatch)[0] -ceq $c1afLine) -and $c1afJ.reason.StartsWith(@($c1afJ.placement)[0]) -and $c1afJ.reason.Contains('Also admitted: ' + $c1afNoted)) `
    -Said ('verdict ' + $c1afJ.verdict + '; reason: ' + $c1afJ.reason)
$c1afJ2 = Invoke-EsEval -Root $c1afRoot -GoalId 'G-BOTH'
$c1afJ2H = Get-EsHandLines -Out $c1afJ2.out -GoalId 'G-BOTH' -Verdict $pwVerdict -Take 3
Add-C1afRow -Label '(j) by hand: exit 4, under the status line the placement''s line, then the manifest''s line and its operator_note' `
    -Ok (($c1afJ2.exit -eq 4) -and (@($c1afJ2H.under).Count -eq 3) -and (@($c1afJ2H.under)[0].EndsWith(' ' + $c1afAmRel)) -and (@($c1afJ2H.under)[1] -ceq ('  ' + $c1afLine)) -and (@($c1afJ2H.under)[2] -ceq ('    operator_note: ' + $c1afNote))) `
    -Said ('under it: ' + (@($c1afJ2H.under) -join ' | '))
Remove-Item -LiteralPath (Join-Path $c1afRoot $c1afAmRel.Replace('/', '\')) -Force

# (k) THE operator_note AS PRINTED: carried whole with ': ' and an apostrophe; a control character shown as
#     '?'; a note longer than 400 characters cut there, the cut said.
Remove-Item -LiteralPath $c1afFull -Force
$c1afKRel = '.mission/dispatches/D-V-FIX-NOTE.manifest.yaml'
$c1afKNote = "it's: a note" + [string][char]7 + ('x' * 450)
Write-EsManifest -Root $c1afRoot -Rel $c1afKRel -Id 'v-fix-note' -Note $c1afKNote
$c1afKLf = Get-PwBlobSha -Root $c1afRoot -Rel $c1afKRel
$c1afKLine = $esManPrefix + ' v-fix-note ' + $c1afKLf + '; ' + $c1afKLf
$c1afKWant = "it's: a note?" + ('x' * 387) + ' [cut at 400 characters]'
$c1afK = Invoke-EsEval -Root $c1afRoot -GoalId 'G-MAN'
$c1afKH = Get-EsHandLines -Out $c1afK.out -GoalId 'G-MAN' -Verdict $esManVerdict -Take 2
Add-C1afRow -Label '(k) a note with ": ", an apostrophe, a BEL and 463 characters: printed with the BEL as ?, cut at 400, the cut said, in the artifact and by hand' `
    -Ok ((@($c1afK.notes).Count -eq 1) -and (@($c1afK.notes)[0] -ceq ($c1afKLine + ' -- operator_note: ' + $c1afKWant)) -and (@($c1afKH.under).Count -eq 2) -and (@($c1afKH.under)[1] -ceq ('    operator_note: ' + $c1afKWant))) `
    -Said ('notes [' + (@($c1afK.notes) -join ' ; ') + ']')
}
catch {
    $c1afOk = $false
    $c1afRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1afRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1afHeld) { try { $c1afHeld.Dispose() } catch { } }
if ($null -ne $c1afM) { Remove-PwTreeAsWritten -Base $c1afM.base }
Check -Id 'C-1af' -Title 'THE DISPATCH-MANIFEST ARM, detector type ungated_manifest_absent (BATCH-2 WP-H (a)): a goal declaring the type is not refused as unknown; with an untracked round manifest under .mission/dispatches/ that no canonical, unrevoked dispatch gate binds -- by its LF/blob sha256 (git''s own, measured) or its working-copy sha256 -- and no open HALT, the evaluator reads AWAITING_DISPATCH_GATE, the Stop hook approves and exits 0, and the verdict artifact, the hand-run status (exit 5) and the hook reason each carry "AWAITING DISPATCH GATE <id> <sha256 LF/blob>; <sha256 working>" with the manifest''s operator_note beneath or beside it; controls, each its own row: the manifest tracked, edited or not, does not admit; a canonical gate over either digest releases, stamped by the runner or not and whatever its id, while a revoked gate, one over other bytes, one of another kind, one renamed aside, one whose id: is another or differs in case, and one out of the console''s line shape do not; a goal without the type writes the artifact and decision the base evaluator writes; an unreadable manifest, an id that is absent, doubled or not one token, an unreadable gate and a mission root git cannot answer for each ADMIT, the cause in the line, while a sharing writer hides nothing; the arm declared last is listed and evaluated first and in hook mode the instrument never runs; a HALT still outranks it and names it; beside the placement-window arm the older arm''s verdict stands and both lines are named; and the note is printed sanitized and cut at 400 characters' `
      -Ok $c1afOk -Detail ("      THE $(@($c1afRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1afRows -join "`n"))

# =============================================================================================
# C-1ag -- THE HANDOFF ARM: a HANDOFF head whose brief the evaluator re-derives
#          admits ONE stop; the same brief never again
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure: (a) a goal declaring handoff_brief_present is refused
# as an UNKNOWN detector; (b)/(c) a HANDOFF head over a matching brief is refused. THE ROWS: (a) no head
# or an ordinary head is inert; (b) by hand the head is ADMITTED and nothing is recorded; (c) as the Stop
# hook runs it, ADMITTED once and RECORDED; (d) the same head again is REFUSED, the record cited, and a
# refused head does not block a met goal; (e) a head whose digests do not match is refused, and either
# digest basis admits; (f) a head naming no file is refused; (g) the record survives an unrelated stop, a
# second goal, another path and another line ending; (h) a goal WITHOUT the type, against the base
# evaluator; (i) malformed heads refuse, a lower-case head is inert, a byte-order mark hides nothing;
# (j) a record that cannot be written or read admits nothing; (k) a HALT outranks it and it is not spent;
# (l) nor spent when the dispatch-manifest arm admits the stop; (m) evaluated first, the instrument
# never runs.
$c1agOk = $true
$c1agRows = New-Object System.Collections.Generic.List[string]
function Add-C1agRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1agOk = $false }
    $script:c1agRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1agRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1agM = $null
$c1agHeld = $null
try {
$c1agM = New-EsMission -Tag 'c1ag'
if (-not $c1agM.ok) { throw ('FIXTURE REFUSED: ' + $c1agM.why) }
$c1agRoot = $c1agM.root
$c1agRec = Join-Path $c1agRoot '.mission-runtime\lam\handoff-admissions.jsonl'
Write-PwGoal -Root $c1agRoot -GoalId 'G-HO' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', ('  - type: ' + $esHoType))
Write-PwGoal -Root $c1agRoot -GoalId 'G-HOU' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
function New-C1agBrief {
    # A brief under .mission-runtime/lam/handoff/, its digests (git's own blob; the working copy), its head.
    param([string]$Name, [string]$Text, [switch]$Crlf, [string]$Ctx = '78')
    $c1agBRel = '.mission-runtime/lam/handoff/' + $Name
    $c1agBText = if ($Crlf) { $Text.Replace("`n", "`r`n") } else { $Text }
    $c1agBFull = Write-EsBytes -Root $script:c1agRoot -Rel $c1agBRel -Bytes ($pwUtf8.GetBytes($c1agBText))
    $c1agBLf = Get-PwBlobSha -Root $script:c1agRoot -Rel $c1agBRel
    $c1agBRaw = Get-PwRawSha -Path $c1agBFull
    return [pscustomobject]@{ rel = $c1agBRel; full = $c1agBFull; lf = $c1agBLf; raw = $c1agBRaw
                              head = (Get-EsHead -Ctx $Ctx -Lf $c1agBLf -Raw $c1agBRaw -Path $c1agBRel)
                              line = ($esHoPrefix + ' ' + $Ctx + '% ' + $c1agBLf + '; ' + $c1agBRaw + ' ' + $c1agBRel) }
}

# (a) THE TYPE IS KNOWN, AND INERT without a HANDOFF head.
$c1agA = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO'
$c1agAArm = Get-PwDetector -Text $c1agA.text -Type $esHoType
Add-C1agRow -Label '(a) FALSIFIER the type is KNOWN and inert with no STATUS.md: MET, exit 0, the arm ok, no UNKNOWN refusal, handoff_admitted: [], no record' `
    -Ok (($c1agA.verdict -ceq 'MET') -and ($c1agA.exit -eq 0) -and $c1agAArm.ok -and ($c1agAArm.detail -match 'no HANDOFF head') -and ($c1agA.text -notmatch 'UNKNOWN detector type') -and $c1agA.handoffKey -and (@($c1agA.handoff).Count -eq 0) -and (-not (Test-Path -LiteralPath $c1agRec))) `
    -Said ('verdict ' + $c1agA.verdict + '; the arm: ' + $c1agAArm.detail)
Write-EsStatus -Root $c1agRoot -Head 'REC-X DONE 2026-09-30T00:00:00Z; an ordinary edition head'
$c1agA2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO'
Add-C1agRow -Label '(a) an ORDINARY edition head (not HANDOFF) is inert: MET, the arm ok, saying the first line does not begin HANDOFF' `
    -Ok (($c1agA2.verdict -ceq 'MET') -and ($c1agA2.exit -eq 0) -and ((Get-PwDetector -Text $c1agA2.text -Type $esHoType).detail -match 'does not begin HANDOFF')) `
    -Said ((Get-PwDetector -Text $c1agA2.text -Type $esHoType).detail)

# (b) BY HAND: ADMITTED, and NOTHING RECORDED (a hand-run spends no brief).
$c1agB1 = New-C1agBrief -Name 'brief-1.md' -Text "# HANDOFF BRIEF 1`n`nwhat the successor needs`n" -Crlf
Write-EsStatus -Root $c1agRoot -Head $c1agB1.head
$c1agB = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU'
$c1agBH = Get-EsHandLines -Out $c1agB.out -GoalId 'G-HOU' -Verdict $esHoVerdict -Take 1
Add-C1agRow -Label ('(b) FALSIFIER by hand, a HANDOFF head over a matching CR LF brief: ' + $esHoVerdict + ', exit 6, the ADMITTED line under the status line and in the artifact') `
    -Ok (($c1agB.verdict -ceq $esHoVerdict) -and ($c1agB.exit -eq 6) -and (@($c1agB.handoff).Count -eq 1) -and (@($c1agB.handoff)[0] -ceq $c1agB1.line) -and (@($c1agBH.under).Count -eq 1) -and (@($c1agBH.under)[0] -ceq ('  ' + $c1agB1.line)) -and ($c1agB1.lf -cne $c1agB1.raw)) `
    -Said ('verdict ' + $c1agB.verdict + ', exit ' + $c1agB.exit + '; handoff_admitted [' + (@($c1agB.handoff) -join ' ; ') + ']; expected [' + $c1agB1.line + ']')
Add-C1agRow -Label '(b) ... and a hand-run RECORDS NOTHING: no admissions record, the detail saying so' `
    -Ok ((-not (Test-Path -LiteralPath $c1agRec)) -and ((Get-PwDetector -Text $c1agB.text -Type $esHoType).detail -match 'NOT RECORDED')) `
    -Said ((Get-PwDetector -Text $c1agB.text -Type $esHoType).detail)
# ... and the verdict OUTRANKS MET: over a goal whose other detector passes, the same head reads the same.
$c1agBm = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO'
Add-C1agRow -Label ('(b) by hand over an otherwise MET goal: ' + $esHoVerdict + ', exit 6 -- an eligible head outranks MET -- and still nothing recorded') `
    -Ok (($c1agBm.verdict -ceq $esHoVerdict) -and ($c1agBm.exit -eq 6) -and (Get-PwDetector -Text $c1agBm.text -Type 'file_exists').ok -and (-not (Test-Path -LiteralPath $c1agRec))) `
    -Said ('verdict ' + $c1agBm.verdict + ', exit ' + $c1agBm.exit)

# (c) AS THE STOP HOOK RUNS IT: ADMITTED ONCE, and RECORDED.
$c1agC = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
$c1agCRec = Get-EsRecord -Root $c1agRoot
$c1agCObj = if ($c1agCRec.count -ge 1) { @($c1agCRec.objects)[0] } else { $null }
Add-C1agRow -Label ('(c) FALSIFIER hook mode: the hook APPROVES and exits 0, ' + $esHoVerdict + ', the reason LEADING with the ADMITTED line and naming the record, line 1') `
    -Ok ($c1agC.admitted -and ($c1agC.verdict -ceq $esHoVerdict) -and $c1agC.reason.StartsWith($c1agB1.line) -and $c1agC.reason.Contains($c1agRec + ' line 1')) `
    -Said ('verdict ' + $c1agC.verdict + '; reason: ' + $c1agC.reason)
Add-C1agRow -Label '(c) the record: ONE line -- event handoff_admitted, the goal, ctx 78, the head, and BOTH digests of the brief re-derived' `
    -Ok (($c1agCRec.count -eq 1) -and ($null -ne $c1agCObj) -and ([string]$c1agCObj.event -ceq 'handoff_admitted') -and ([string]$c1agCObj.goal -ceq 'G-HOU') -and ([int]$c1agCObj.ctx_percent -eq 78) -and ([string]$c1agCObj.head -ceq $c1agB1.head) -and ([string]$c1agCObj.brief_lf_sha256 -ceq $c1agB1.lf) -and ([string]$c1agCObj.brief_working_sha256 -ceq $c1agB1.raw)) `
    -Said ('record lines ' + $c1agCRec.count + ': ' + $c1agCRec.text.Trim())
Add-C1agRow -Label '(c) the arm evaluated first: file_exists NOT EVALUATED (short_circuited 1), named as the handoff arm''s short-circuit' `
    -Ok (($c1agC.shortCircuited -eq 1) -and ((Get-PwDetector -Text $c1agC.text -Type 'file_exists').detail -match 'the handoff arm found an eligible HANDOFF head')) `
    -Said ((Get-PwDetector -Text $c1agC.text -Type 'file_exists').detail)

# (d) THE SAME HEAD AGAIN: REFUSED, the record cited -- the successor's first stop is not admitted by it.
$c1agD = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
$c1agDRec = Get-EsRecord -Root $c1agRoot
Add-C1agRow -Label '(d) FALSIFIER the same head again, hook mode: REFUSED -- the hook BLOCKS (the goal is unmet), the reason citing the record and its line' `
    -Ok (($c1agD.decision -ceq 'block') -and ($c1agD.exit -eq 0) -and ($c1agD.verdict -ceq 'NOT_MET') -and $c1agD.reason.Contains('HANDOFF head NOT admitted -- already admitted') -and $c1agD.reason.Contains($c1agRec + ' (line 1)') -and (@($c1agD.refused).Count -eq 1) -and ($c1agDRec.count -eq 1)) `
    -Said ('decision ' + $c1agD.decision + ', verdict ' + $c1agD.verdict + '; record lines ' + $c1agDRec.count + '; reason: ' + $c1agD.reason)
$c1agD2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU'
Add-C1agRow -Label '(d) ... by hand: NOT_MET, exit 1, the refusal printed' `
    -Ok (($c1agD2.verdict -ceq 'NOT_MET') -and ($c1agD2.exit -eq 1) -and $c1agD2.out.Contains('HANDOFF head NOT admitted -- already admitted')) -Said ('exit ' + $c1agD2.exit)
$c1agD3 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO' -Hook
Add-C1agRow -Label '(d) CONTROL a refused head does not block a MET goal: MET, approve, exit 0, the refusal named in the reason, the record unchanged' `
    -Ok (($c1agD3.verdict -ceq 'MET') -and $c1agD3.admitted -and $c1agD3.reason.Contains('HANDOFF head NOT admitted -- already admitted') -and ((Get-EsRecord -Root $c1agRoot).count -eq 1)) `
    -Said ('reason: ' + $c1agD3.reason)

# (e) A HEAD WHOSE DIGESTS DO NOT MATCH ITS BRIEF: REFUSED. And EITHER digest basis admits.
$c1agB2 = New-C1agBrief -Name 'brief-2.md' -Text "# HANDOFF BRIEF 2`n"
Write-EsStatus -Root $c1agRoot -Head $c1agB2.head
[System.IO.File]::AppendAllText($c1agB2.full, "edited after the head was written`n", $pwUtf8)
$c1agE = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(e) FALSIFIER a head whose digests the brief no longer hashes to (edited after the head): REFUSED, blocked, the record unchanged' `
    -Ok (($c1agE.decision -ceq 'block') -and $c1agE.reason.Contains('neither digest matches its basis') -and ((Get-EsRecord -Root $c1agRoot).count -eq 1)) `
    -Said ('reason: ' + $c1agE.reason)
$c1agB3 = New-C1agBrief -Name 'brief-3.md' -Text "# HANDOFF BRIEF 3`n`nCR LF`n" -Crlf
Write-EsStatus -Root $c1agRoot -Head (Get-EsHead -Ctx '78' -Lf $c1agB3.lf -Raw ('0' * 64) -Path $c1agB3.rel)
$c1agE2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(e) its LF/BLOB slot matching (the working slot wrong): ADMITTED and recorded -- either basis re-derives the brief' `
    -Ok ($c1agE2.admitted -and ($c1agE2.verdict -ceq $esHoVerdict) -and ((Get-EsRecord -Root $c1agRoot).count -eq 2)) -Said ('verdict ' + $c1agE2.verdict)
$c1agB4 = New-C1agBrief -Name 'brief-4.md' -Text "# HANDOFF BRIEF 4`n`nCR LF`n" -Crlf
Write-EsStatus -Root $c1agRoot -Head (Get-EsHead -Ctx '78' -Lf ('0' * 64) -Raw $c1agB4.raw -Path $c1agB4.rel)
$c1agE3 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(e) its WORKING slot matching (the LF/blob slot wrong): ADMITTED and recorded' `
    -Ok ($c1agE3.admitted -and ($c1agE3.verdict -ceq $esHoVerdict) -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) -Said ('verdict ' + $c1agE3.verdict)

# (f) A HEAD WHOSE PATH NAMES NO FILE: REFUSED.
Write-EsStatus -Root $c1agRoot -Head (Get-EsHead -Ctx '78' -Lf $c1agB1.lf -Raw $c1agB1.raw -Path '.mission-runtime/lam/handoff/no-such-brief.md')
$c1agF = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(f) FALSIFIER a head naming a file that does not exist: REFUSED, blocked, the path named' `
    -Ok (($c1agF.decision -ceq 'block') -and $c1agF.reason.Contains('HANDOFF head NOT admitted -- no file at') -and $c1agF.reason.Contains('no-such-brief.md') -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) `
    -Said ('reason: ' + $c1agF.reason)
Write-EsStatus -Root $c1agRoot -Head (Get-EsHead -Ctx '78' -Lf $c1agB1.lf -Raw $c1agB1.raw -Path '.mission-runtime/lam/handoff')
$c1agF2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(f) a head naming a DIRECTORY: REFUSED' `
    -Ok (($c1agF2.decision -ceq 'block') -and $c1agF2.reason.Contains('HANDOFF head NOT admitted -- no file at')) -Said ('reason: ' + $c1agF2.reason)

# (g) THE RECORD SURVIVES: an unrelated stop between, a second goal, another path, another line ending.
Write-EsStatus -Root $c1agRoot -Head 'REC-Y DONE 2026-09-30T01:00:00Z; an unrelated edition'
$c1agG = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(g) an UNRELATED stop between (an ordinary head, the goal unmet): blocked as NOT_MET, the record unchanged at 3 lines' `
    -Ok (($c1agG.decision -ceq 'block') -and ($c1agG.verdict -ceq 'NOT_MET') -and (-not $c1agG.reason.Contains('HANDOFF head')) -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) -Said ('reason: ' + $c1agG.reason)
Write-EsStatus -Root $c1agRoot -Head $c1agB1.head
$c1agG2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(g) FALSIFIER then brief-1''s head restored: still REFUSED, the record citing line 1' `
    -Ok (($c1agG2.decision -ceq 'block') -and $c1agG2.reason.Contains('already admitted') -and $c1agG2.reason.Contains('(line 1)') -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) -Said ('reason: ' + $c1agG2.reason)
Write-PwGoal -Root $c1agRoot -GoalId 'G-HO2' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
$c1agG3 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO2' -Hook
Add-C1agRow -Label '(g) under ANOTHER goal id at the same mission root: REFUSED -- the record is the mission root''s, keyed by the brief' `
    -Ok (($c1agG3.decision -ceq 'block') -and $c1agG3.reason.Contains('already admitted')) -Said ('reason: ' + $c1agG3.reason)
$c1agCopyRel = '.mission-runtime/lam/handoff/brief-1-copy.md'
[System.IO.File]::Copy($c1agB1.full, (Join-Path $c1agRoot $c1agCopyRel.Replace('/', '\')), $true)
Write-EsStatus -Root $c1agRoot -Head (Get-EsHead -Ctx '60' -Lf $c1agB1.lf -Raw $c1agB1.raw -Path $c1agCopyRel)
$c1agG4 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(g) the SAME bytes at ANOTHER path: REFUSED (the brief is its bytes, not its name)' `
    -Ok (($c1agG4.decision -ceq 'block') -and $c1agG4.reason.Contains('already admitted')) -Said ('reason: ' + $c1agG4.reason)
$c1agLfRel = '.mission-runtime/lam/handoff/brief-1-lf.md'
$c1agLfFull = Write-EsBytes -Root $c1agRoot -Rel $c1agLfRel -Bytes ($pwUtf8.GetBytes("# HANDOFF BRIEF 1`n`nwhat the successor needs`n"))
$c1agLfRaw = Get-PwRawSha -Path $c1agLfFull
Write-EsStatus -Root $c1agRoot -Head (Get-EsHead -Ctx '60' -Lf $c1agB1.lf -Raw $c1agLfRaw -Path $c1agLfRel)
$c1agG5 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(g) the same text re-saved with LF endings (git''s blob unchanged, the working copy new): REFUSED' `
    -Ok (($c1agLfRaw -ceq $c1agB1.lf) -and ($c1agG5.decision -ceq 'block') -and $c1agG5.reason.Contains('already admitted') -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) -Said ('reason: ' + $c1agG5.reason)

# (h) CONTROL: a goal WITHOUT the type behaves as the base evaluator does, a valid unrecorded head on disk.
$c1agBase = New-EsBaseEvaluator -Dir (Join-Path $c1agM.base 'base-tools')
$c1agB5 = New-C1agBrief -Name 'brief-5.md' -Text "# HANDOFF BRIEF 5`n"
Write-EsStatus -Root $c1agRoot -Head $c1agB5.head
Write-PwGoal -Root $c1agRoot -GoalId 'G-HONO' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', '  - type: halt_absent')
$c1agHT = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HONO'
$c1agHB = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HONO' -Evaluator $c1agBase.path
$c1agHTH = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HONO' -Hook
$c1agHBH = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HONO' -Hook -Evaluator $c1agBase.path
Add-C1agRow -Label '(h) CONTROL no type declared, a valid unrecorded head on disk: tree and base MET, exit 0, the SAME artifact and the SAME hook JSON, nothing recorded' `
    -Ok ($c1agBase.ok -and ($c1agHT.verdict -ceq 'MET') -and ($c1agHB.verdict -ceq 'MET') -and ((Remove-WrProvenanceLine -Text (($c1agHT.text -replace $esMask, 'evaluated_at: MASKED') -replace $wjScanMask, '')) -ceq ($c1agHB.text -replace $esMask, 'evaluated_at: MASKED')) -and ($c1agHTH.exit -eq 0) -and ($c1agHTH.out.Trim() -ceq $c1agHBH.out.Trim()) -and (-not $c1agHT.handoffKey) -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) `
    -Said ('base ' + $c1agBase.said + '; tree: ' + $c1agHTH.out.Trim() + ' | base: ' + $c1agHBH.out.Trim())

# (i) MALFORMED HEADS REFUSE; a lower-case head is inert; a byte-order mark hides nothing.
$c1agBad = @(
    [pscustomobject]@{ label = 'ctx 101%'; head = (Get-EsHead -Ctx '101' -Lf $c1agB5.lf -Raw $c1agB5.raw -Path $c1agB5.rel) },
    [pscustomobject]@{ label = 'no % sign'; head = ('HANDOFF AT 78 ' + $c1agB5.lf + '; ' + $c1agB5.raw + ' ' + $c1agB5.rel) },
    [pscustomobject]@{ label = 'no path after the digests'; head = ('HANDOFF AT 78% ' + $c1agB5.lf + '; ' + $c1agB5.raw) },
    [pscustomobject]@{ label = 'ONE digest only (the charter''s minimum form)'; head = ('HANDOFF AT 78% ' + $c1agB5.lf + ' ' + $c1agB5.rel) })
foreach ($c1agBc in $c1agBad) {
    Write-EsStatus -Root $c1agRoot -Head $c1agBc.head
    $c1agI = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
    Add-C1agRow -Label ('(i) a malformed head (' + $c1agBc.label + '): REFUSED as not in the form, blocked, nothing recorded') `
        -Ok (($c1agI.decision -ceq 'block') -and $c1agI.reason.Contains('HANDOFF head NOT admitted -- the head is not in the form') -and ((Get-EsRecord -Root $c1agRoot).count -eq 3)) -Said ('reason: ' + $c1agI.reason)
}
Write-EsStatus -Root $c1agRoot -Head ('handoff at 78% ' + $c1agB5.lf + '; ' + $c1agB5.raw + ' ' + $c1agB5.rel)
$c1agI2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO'
Add-C1agRow -Label '(i) a LOWER-CASE "handoff at" head is no HANDOFF head: inert, MET' `
    -Ok (($c1agI2.verdict -ceq 'MET') -and ((Get-PwDetector -Text $c1agI2.text -Type $esHoType).detail -match 'does not begin HANDOFF')) -Said ('verdict ' + $c1agI2.verdict)
$c1agB6 = New-C1agBrief -Name 'brief-6.md' -Text "# HANDOFF BRIEF 6`n"
Write-EsStatus -Root $c1agRoot -Head $c1agB6.head -Bom
$c1agI3 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(i) a valid head after a UTF-8 byte-order mark: ADMITTED and recorded (the mark is not the head''s text)' `
    -Ok ($c1agI3.admitted -and ($c1agI3.verdict -ceq $esHoVerdict) -and ((Get-EsRecord -Root $c1agRoot).count -eq 4)) -Said ('verdict ' + $c1agI3.verdict)

# (j) A RECORD THAT CANNOT BE WRITTEN OR READ ADMITS NOTHING.
$c1agB7 = New-C1agBrief -Name 'brief-7.md' -Text "# HANDOFF BRIEF 7`n"
Write-EsStatus -Root $c1agRoot -Head $c1agB7.head
# (The record is this arm's to create: where there is none -- the tree before the cure -- each row is still
#  driven, and fails on the record it needs.)
$c1agRecThere = Test-Path -LiteralPath $c1agRec -PathType Leaf
if ($c1agRecThere) { (Get-Item -LiteralPath $c1agRec).IsReadOnly = $true }
try {
    $c1agJ = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
    $c1agJm = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HO' -Hook
} finally { if ($c1agRecThere) { (Get-Item -LiteralPath $c1agRec).IsReadOnly = $false } }
Add-C1agRow -Label '(j) FALSIFIER the record READ-ONLY, a valid unrecorded head: NOT admitted -- blocked, the write failure named, the record unchanged' `
    -Ok ($c1agRecThere -and ($c1agJ.decision -ceq 'block') -and ($c1agJ.verdict -ceq 'NOT_MET') -and $c1agJ.reason.Contains('could not be written') -and ((Get-EsRecord -Root $c1agRoot).count -eq 4)) `
    -Said ('a record to make read-only: ' + $c1agRecThere + '; reason: ' + $c1agJ.reason)
# ... AND IT IS STRICTER THAN A REFUSED HEAD (validator round 1 finding): the head was eligible, so the arm's own entry
#     FAILS and the hook blocks a goal whose other detector would pass -- where a REFUSED head ((d), control) does not.
$c1agJmArm = Get-PwDetector -Text $c1agJm.text -Type $esHoType
Add-C1agRow -Label '(j) the record READ-ONLY over an otherwise MET goal: BLOCKED all the same -- the arm''s entry fails, handoff_refused stays empty' `
    -Ok ($c1agRecThere -and ($c1agJm.decision -ceq 'block') -and ($c1agJm.exit -eq 0) -and ($c1agJm.verdict -ceq 'NOT_MET') -and (-not $c1agJmArm.ok) -and ($c1agJmArm.detail -match 'NOT ADMITTED') -and (@($c1agJm.refused).Count -eq 0) -and ((Get-EsRecord -Root $c1agRoot).count -eq 4)) `
    -Said ('decision ' + $c1agJm.decision + ', verdict ' + $c1agJm.verdict + '; the arm: ' + $c1agJmArm.detail)
if ($c1agRecThere) { $c1agHeld = [System.IO.File]::Open($c1agRec, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None) }
try { $c1agJ2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook } finally { if ($null -ne $c1agHeld) { $c1agHeld.Dispose(); $c1agHeld = $null } }
Add-C1agRow -Label '(j) the record held open with no sharing: REFUSED -- a prior admission cannot be ruled out' `
    -Ok ($c1agRecThere -and ($c1agJ2.decision -ceq 'block') -and $c1agJ2.reason.Contains('could not be read, so a prior admission of this brief cannot be ruled out') -and ((Get-EsRecord -Root $c1agRoot).count -eq 4)) `
    -Said ('a record to hold: ' + $c1agRecThere + '; reason: ' + $c1agJ2.reason)

# (k) A HALT OUTRANKS IT, AND IT IS NOT SPENT.
$c1agHalts = Join-Path $c1agRoot '.mission-runtime\halts'
Write-Utf8 -Path (Join-Path $c1agHalts 'HALT-C1AG.md') -Text "# HALT-C1AG`n`n**Status:** OPEN`n"
$c1agK = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(k) with an OPEN HALT as well: verdict HALT, approve, exit 0, the brief NOT SPENT (nothing recorded), the detail saying so' `
    -Ok (($c1agK.verdict -ceq 'HALT') -and $c1agK.admitted -and ((Get-EsRecord -Root $c1agRoot).count -eq 4) -and ((Get-PwDetector -Text $c1agK.text -Type $esHoType).detail -match 'NOT SPENT')) `
    -Said ((Get-PwDetector -Text $c1agK.text -Type $esHoType).detail)
Remove-Item -LiteralPath $c1agHalts -Recurse -Force
$c1agK2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOU' -Hook
Add-C1agRow -Label '(k) the HALT gone: the same head ADMITTED now, and recorded' `
    -Ok ($c1agK2.admitted -and ($c1agK2.verdict -ceq $esHoVerdict) -and ((Get-EsRecord -Root $c1agRoot).count -eq 5)) -Said ('verdict ' + $c1agK2.verdict)

# (l) NOT SPENT WHEN THE DISPATCH-MANIFEST ARM ADMITS THE STOP.
$c1agB8 = New-C1agBrief -Name 'brief-8.md' -Text "# HANDOFF BRIEF 8`n"
Write-EsStatus -Root $c1agRoot -Head $c1agB8.head
Write-PwGoal -Root $c1agRoot -GoalId 'G-HOMAN' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType), ('  - type: ' + $esManType))
$c1agManRel = '.mission/dispatches/D-V-C1AG.manifest.yaml'
Write-EsManifest -Root $c1agRoot -Rel $c1agManRel -Id 'v-c1ag-r1'
$c1agL = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOMAN' -Hook
Add-C1agRow -Label ('(l) an ungated manifest as well: ' + $esManVerdict + ', approve, the brief NOT SPENT (nothing recorded)') `
    -Ok (($c1agL.verdict -ceq $esManVerdict) -and $c1agL.admitted -and ((Get-EsRecord -Root $c1agRoot).count -eq 5) -and ((Get-PwDetector -Text $c1agL.text -Type $esHoType).detail -match 'NOT SPENT')) `
    -Said ('verdict ' + $c1agL.verdict + '; ' + (Get-PwDetector -Text $c1agL.text -Type $esHoType).detail)
Remove-Item -LiteralPath (Join-Path $c1agRoot $c1agManRel.Replace('/', '\')) -Force
$c1agL2 = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HOMAN' -Hook
Add-C1agRow -Label '(l) the manifest gone: the head ADMITTED now, and recorded' `
    -Ok ($c1agL2.admitted -and ($c1agL2.verdict -ceq $esHoVerdict) -and ((Get-EsRecord -Root $c1agRoot).count -eq 6)) -Said ('verdict ' + $c1agL2.verdict)

# (m) ORDER: evaluated first -- in hook mode the instrument never runs.
$c1agRan = Join-Path $c1agM.base 'RAN'
$c1agInst = Join-Path $c1agM.base 'marker-instrument.ps1'
Write-Utf8 -Path $c1agInst -Text ("[System.IO.File]::WriteAllText('" + $c1agRan + "', 'ran')`r`nWrite-Output 'EXIT: 0'`r`nexit 0`r`n")
Write-PwGoal -Root $c1agRoot -GoalId 'G-HORDER' -DetectorLines @('  - type: instrument_exit0', ('    path: ' + $c1agInst), ('  - type: ' + $esHoType))
$c1agB9 = New-C1agBrief -Name 'brief-9.md' -Text "# HANDOFF BRIEF 9`n"
Write-EsStatus -Root $c1agRoot -Head $c1agB9.head
$c1agMo = Invoke-EsEval -Root $c1agRoot -GoalId 'G-HORDER' -Hook
$c1agMoTypes = @(Get-PwDetectorTypes -Text $c1agMo.text)
Add-C1agRow -Label '(m) ORDER hook mode, the arm declared LAST: listed FIRST, admits, short_circuited 1, the instrument NEVER RAN' `
    -Ok ($c1agMo.admitted -and ($c1agMo.verdict -ceq $esHoVerdict) -and ($c1agMoTypes.Count -eq 2) -and ($c1agMoTypes[0] -ceq $esHoType) -and ($c1agMo.shortCircuited -eq 1) -and (-not (Test-Path -LiteralPath $c1agRan))) `
    -Said ('artifact order [' + ($c1agMoTypes -join ', ') + ']; short_circuited ' + $c1agMo.shortCircuited + '; marker written: ' + (Test-Path -LiteralPath $c1agRan))
}
catch {
    $c1agOk = $false
    $c1agRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1agRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1agHeld) { try { $c1agHeld.Dispose() } catch { } }
if ($null -ne $c1agM) { Remove-PwTreeAsWritten -Base $c1agM.base }
Check -Id 'C-1ag' -Title 'THE HANDOFF ARM, detector type handoff_brief_present (BATCH-2 WP-H (b)): a goal declaring the type is not refused as unknown and is inert without a HANDOFF head; the first line of <mission root>/.mission-runtime/lam/STATUS.md reading "HANDOFF AT <0-100>% <sha256 LF/blob>; <sha256 working> <path of the brief>", the brief re-derived by the evaluator (either digest basis), admits ONE stop -- by hand HANDOFF_ADMITTED, exit 6, nothing recorded, over a goal that is otherwise met as well; as the Stop hook runs it approve, exit 0, the admission appended to .mission-runtime/lam/handoff-admissions.jsonl -- and the same head again is REFUSED with the record cited, as are a head whose digests do not match, a head naming no file or a directory, the same bytes at another path or re-saved with other line endings, the same brief under another goal and after an unrelated stop, and heads out of the form (ctx 101, no %, no path, one digest); a refused head does not block a met goal; a goal without the type writes the artifact and decision the base evaluator writes; a record that cannot be written or read admits nothing, and one that cannot be written BLOCKS a goal that is otherwise met; a HALT, or the dispatch-manifest arm admitting the stop, leaves the brief unspent; and the arm is evaluated first, the instrument never run' `
      -Ok $c1agOk -Detail ("      THE $(@($c1agRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1agRows -join "`n"))

# =============================================================================================
# C-1ah -- THE ABSENT GOAL AND THE UNREADABLE ONE (ruled by the operator 2026-09-30,
#          lean A): absent is an admitted stop, RECORDED; present and unreadable REFUSES the stop
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure: (a)/(b) a goal file at neither location is approved
# with no verdict at all -- the reason alone says so; (g)/(h) a goal file that exists and cannot be read
# is approved by the evaluator's trap (exit 9); (i)/(j) a goal file declaring no detectors blocks with
# an empty reason. THE ROWS: (a) hook, (b) by hand, (c) an explicit -GoalFile named too; (d) a goal at
# the second location is found; (e) an id that is not one token, and (f) a mission root with no .mission
# directory, are admitted with no verdict file and the reason saying why; (g)-(j) the present goal that
# does not parse refuses, the parse error printed; (k) a HALT still outranks that refusal; (l) a present,
# valid goal -- met and unmet -- through this tree's evaluator and the base; (m) the live goal of this
# tree, read-only through the evaluator's own reader.
$c1ahOk = $true
$c1ahRows = New-Object System.Collections.Generic.List[string]
function Add-C1ahRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1ahOk = $false }
    $script:c1ahRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1ahRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1ahM = $null
$c1ahHeld = $null
try {
$c1ahM = New-EsMission -Tag 'c1ah'
if (-not $c1ahM.ok) { throw ('FIXTURE REFUSED: ' + $c1ahM.why) }
$c1ahRoot = $c1ahM.root
$c1ahP1 = Join-Path $c1ahRoot '.mission\goals\G-NONE.yaml'
$c1ahP2 = Join-Path $c1ahRoot '.mission-runtime\lam\goals\G-NONE.yaml'
$c1ahVf = Join-Path $c1ahRoot '.mission\goals\G-NONE.verdict.yaml'

# (a) THE ABSENT GOAL, as the Stop hook runs it: admitted, and RECORDED.
$c1ahA = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-NONE' -Hook
Add-C1ahRow -Label ('(a) FALSIFIER hook mode, no goal file at either location: approve, exit 0, the reason naming ' + $esAbsVerdict + ', the id and BOTH paths') `
    -Ok ($c1ahA.admitted -and $c1ahA.reason.Contains($esAbsVerdict + ': no goal file for ''G-NONE''') -and $c1ahA.reason.Contains($c1ahP1) -and $c1ahA.reason.Contains($c1ahP2) -and $c1ahA.reason.Contains('Verdict: ' + $c1ahVf)) `
    -Said ('exit ' + $c1ahA.exit + '; reason: ' + $c1ahA.reason)
Add-C1ahRow -Label ('(a) FALSIFIER the verdict artifact at .mission/goals/G-NONE.verdict.yaml reads ' + $esAbsVerdict + ', goal_searched naming both paths, no detector') `
    -Ok (($c1ahA.verdict -ceq $esAbsVerdict) -and (@($c1ahA.searched).Count -eq 2) -and (@($c1ahA.searched)[0] -ceq $c1ahP1) -and (@($c1ahA.searched)[1] -ceq $c1ahP2) -and ($c1ahA.text -match '(?m)^detector_count: 0') -and ($c1ahA.text -match '(?m)^detectors: \[\]')) `
    -Said ('verdict ' + $c1ahA.verdict + '; goal_searched [' + (@($c1ahA.searched) -join ' ; ') + ']')

# (b) BY HAND.
$c1ahB = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-NONE'
$c1ahBH = Get-EsHandLines -Out $c1ahB.out -GoalId 'G-NONE' -Verdict $esAbsVerdict -Take 1
Add-C1ahRow -Label ('(b) FALSIFIER by hand: exit 2, "-> ' + $esAbsVerdict + '", the reason line under it naming the id and both paths, the artifact written') `
    -Ok (($c1ahB.exit -eq 2) -and (@($c1ahBH.under).Count -eq 1) -and @($c1ahBH.under)[0].StartsWith('  ' + $esAbsVerdict + ': no goal file for ''G-NONE''. Looked in: ' + $c1ahP1 + ' ; ' + $c1ahP2) -and ($c1ahB.verdict -ceq $esAbsVerdict)) `
    -Said ('exit ' + $c1ahB.exit + '; under it: ' + (@($c1ahBH.under) -join ' | '))

# (c) AN EXPLICIT -GoalFile, ALSO ABSENT: every path searched is named.
$c1ahP3 = Join-Path $c1ahM.base 'nowhere\G-NONE.yaml'
$c1ahC = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-NONE' -Hook -GoalFile $c1ahP3
Add-C1ahRow -Label '(c) -GoalFile named and absent as well: admitted, THREE paths in the reason and in goal_searched' `
    -Ok ($c1ahC.admitted -and ($c1ahC.verdict -ceq $esAbsVerdict) -and (@($c1ahC.searched).Count -eq 3) -and (@($c1ahC.searched)[2] -ceq $c1ahP3) -and $c1ahC.reason.Contains($c1ahP3)) `
    -Said ('goal_searched [' + (@($c1ahC.searched) -join ' ; ') + ']')

# (d) CONTROL: a goal at the SECOND location is found, and read.
Write-Utf8 -Path (Join-Path $c1ahRoot '.mission-runtime\lam\goals\G-LOC2.yaml') -Text "id: G-LOC2`ndetectors:`n  - type: file_exists`n    path: evidence/built.txt`n"
$c1ahD = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-LOC2'
Add-C1ahRow -Label '(d) CONTROL a goal at .mission-runtime/lam/goals is found: MET by hand, exit 0 (not absent)' `
    -Ok (($c1ahD.exit -eq 0) -and $c1ahD.out.Contains('mission-goal-check: G-LOC2 -> MET')) -Said ('exit ' + $c1ahD.exit)

# (e) AN ID THAT IS NOT ONE TOKEN, and (f) A MISSION ROOT WITH NO .mission: nothing can be written -- and
#     NOW THE STOP IS REFUSED. Until then these two rows asserted the opposite: "admitted, the
#     reason saying no verdict file was written and why" -- an approve with no written verdict, which the operator's ruling
#     admitted "in every one of those cases" and the cured trap's sentence does not. They are re-asserted to the
#     rule; C-2f drives the same two cases against the base evaluator, the streams apart, and the third.
$c1ahE = Invoke-EsEval -Root $c1ahRoot -GoalId 'G NONE' -Hook
Add-C1ahRow -Label '(e) an id with a space (G NONE): REFUSED -- the hook BLOCKS (exit 0), NOT_MET, the reason saying no verdict file was written and why, no file named for it' `
    -Ok (($c1ahE.decision -ceq 'block') -and ($c1ahE.exit -eq 0) -and (-not $c1ahE.admitted) -and $c1ahE.reason.StartsWith('Goal ''G NONE'' is NOT_MET: ' + $esAbsVerdict + ', AND ITS VERDICT COULD NOT BE WRITTEN') -and $c1ahE.reason.Contains('No verdict file was written') -and
         $c1ahE.reason.Contains('is not one token') -and $c1ahE.reason.Contains('(register row 376: an absent goal is not approved without a written verdict)') -and (-not (Test-Path -LiteralPath (Join-Path $c1ahRoot '.mission\goals\G NONE.verdict.yaml')))) `
    -Said ('decision ' + $c1ahE.decision + ', exit ' + $c1ahE.exit + '; reason: ' + $c1ahE.reason)
$c1ahBare = Join-Path $c1ahM.base 'bare'
New-Item -ItemType Directory -Path $c1ahBare -Force | Out-Null
$c1ahF = Invoke-EsEval -Root $c1ahBare -GoalId 'G-NONE' -Hook
Add-C1ahRow -Label '(f) a mission root with no .mission directory: REFUSED -- the hook BLOCKS (exit 0), NOT_MET, the reason saying why no verdict file was written, nothing created' `
    -Ok (($c1ahF.decision -ceq 'block') -and ($c1ahF.exit -eq 0) -and (-not $c1ahF.admitted) -and $c1ahF.reason.StartsWith('Goal ''G-NONE'' is NOT_MET: ' + $esAbsVerdict + ', AND ITS VERDICT COULD NOT BE WRITTEN') -and $c1ahF.reason.Contains('No verdict file was written') -and
         $c1ahF.reason.Contains('is not a directory') -and $c1ahF.reason.Contains('(register row 376: an absent goal is not approved without a written verdict)') -and (-not (Test-Path -LiteralPath (Join-Path $c1ahBare '.mission')))) `
    -Said ('decision ' + $c1ahF.decision + ', exit ' + $c1ahF.exit + '; reason: ' + $c1ahF.reason)
# ... and a mission root whose .mission holds NO goals directory: the directory is made and the verdict written.
$c1ahNoGoals = Join-Path $c1ahM.base 'nogoals'
New-Item -ItemType Directory -Path (Join-Path $c1ahNoGoals '.mission') -Force | Out-Null
$c1ahF2 = Invoke-EsEval -Root $c1ahNoGoals -GoalId 'G-NONE' -Hook
Add-C1ahRow -Label ('(f) a mission root whose .mission has no goals directory: admitted, the directory made, the artifact reading ' + $esAbsVerdict) `
    -Ok ($c1ahF2.admitted -and ($c1ahF2.verdict -ceq $esAbsVerdict) -and (Test-Path -LiteralPath (Join-Path $c1ahNoGoals '.mission\goals\G-NONE.verdict.yaml') -PathType Leaf) -and $c1ahF2.reason.Contains('Verdict: ')) `
    -Said ('verdict ' + $c1ahF2.verdict + '; reason: ' + $c1ahF2.reason)

# (g) A GOAL FILE THAT EXISTS AND CANNOT BE READ: REFUSED, the parse error printed.
$c1ahLock = Join-Path $c1ahRoot '.mission\goals\G-LOCK.yaml'
Write-Utf8 -Path $c1ahLock -Text "id: G-LOCK`ndetectors:`n  - type: file_exists`n    path: evidence/built.txt`n"
$c1ahHeld = [System.IO.File]::Open($c1ahLock, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try {
    $c1ahG = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-LOCK' -Hook
    $c1ahG2 = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-LOCK'
} finally { $c1ahHeld.Dispose(); $c1ahHeld = $null }
Add-C1ahRow -Label '(g) FALSIFIER the goal file held open with no sharing, hook mode: the hook BLOCKS (exit 0), NOT_MET, the reason printing THE GOAL FILE DOES NOT PARSE and why' `
    -Ok (($c1ahG.decision -ceq 'block') -and ($c1ahG.exit -eq 0) -and ($c1ahG.verdict -ceq 'NOT_MET') -and $c1ahG.reason.Contains('goal_parse: THE GOAL FILE DOES NOT PARSE -- it could not be read') -and ($c1ahG.text -match '(?m)^goal_parse_error: ''it could not be read')) `
    -Said ('decision ' + $c1ahG.decision + ', exit ' + $c1ahG.exit + '; reason: ' + $c1ahG.reason)
Add-C1ahRow -Label '(g) ... by hand: exit 1, the goal_parse entry FAIL' `
    -Ok (($c1ahG2.exit -eq 1) -and $c1ahG2.out.Contains('[FAIL] goal_parse -- THE GOAL FILE DOES NOT PARSE')) -Said ('exit ' + $c1ahG2.exit)

# (h) A DIRECTORY AT THE GOAL PATH; (i) NO detectors: LINE; (j) detectors: WITH NO ITEM -- each REFUSED.
New-Item -ItemType Directory -Path (Join-Path $c1ahRoot '.mission\goals\G-DIR.yaml') -Force | Out-Null
Write-Utf8 -Path (Join-Path $c1ahRoot '.mission\goals\G-NODET.yaml') -Text "id: G-NODET`ndescription: `"a goal that declares nothing`"`n"
Write-Utf8 -Path (Join-Path $c1ahRoot '.mission\goals\G-EMPTY.yaml') -Text "id: G-EMPTY`ndetectors:`n  # nothing under it`n"
$c1ahParse = @(
    [pscustomobject]@{ goal = 'G-DIR'; label = 'a DIRECTORY at the goal path'; says = 'it could not be read' },
    [pscustomobject]@{ goal = 'G-NODET'; label = 'a goal file with NO detectors: line'; says = 'it declares no detectors (no column-0 detectors: line)' },
    [pscustomobject]@{ goal = 'G-EMPTY'; label = 'a goal file whose detectors: holds NO item'; says = 'it declares no detectors (a column-0 detectors: line with no ''- <key>:'' item under it)' })
foreach ($c1ahPc in $c1ahParse) {
    $c1ahPr = Invoke-EsEval -Root $c1ahRoot -GoalId $c1ahPc.goal -Hook
    Add-C1ahRow -Label ('(h-j) FALSIFIER ' + $c1ahPc.label + ': the hook BLOCKS, NOT_MET, the parse error printed') `
        -Ok (($c1ahPr.decision -ceq 'block') -and ($c1ahPr.exit -eq 0) -and ($c1ahPr.verdict -ceq 'NOT_MET') -and $c1ahPr.reason.Contains('THE GOAL FILE DOES NOT PARSE -- ' + $c1ahPc.says)) `
        -Said ('decision ' + $c1ahPr.decision + '; reason: ' + $c1ahPr.reason)
}

# (k) A HALT STILL OUTRANKS: C-3 is unamended, and the parse error is named beside it.
$c1ahHalts = Join-Path $c1ahRoot '.mission-runtime\halts'
Write-Utf8 -Path (Join-Path $c1ahHalts 'HALT-C1AH.md') -Text "# HALT-C1AH`n`n**Status:** OPEN`n"
$c1ahK = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-NODET' -Hook
Add-C1ahRow -Label '(k) the unparseable goal with an OPEN HALT: verdict HALT, approve, exit 0 -- control returns to the human -- the parse error still written' `
    -Ok (($c1ahK.verdict -ceq 'HALT') -and $c1ahK.admitted -and ($c1ahK.text -match '(?m)^goal_parse_error: ')) -Said ('verdict ' + $c1ahK.verdict + '; reason: ' + $c1ahK.reason)
Remove-Item -LiteralPath $c1ahHalts -Recurse -Force

# (l) CONTROL: a present, valid goal -- met, and unmet -- is read as the base evaluator reads it.
$c1ahBase = New-EsBaseEvaluator -Dir (Join-Path $c1ahM.base 'base-tools')
Write-PwGoal -Root $c1ahRoot -GoalId 'G-MET3' -DetectorLines @(('  - type: ' + $pwType), '  - type: halt_absent', '  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c1ahRoot -GoalId 'G-UNMET3' -DetectorLines @(('  - type: ' + $pwType), '  - type: halt_absent', '  - type: file_exists', '    path: evidence/absent.txt')
foreach ($c1ahLg in @('G-MET3', 'G-UNMET3')) {
    $c1ahLT = Invoke-EsEval -Root $c1ahRoot -GoalId $c1ahLg
    $c1ahLB = Invoke-EsEval -Root $c1ahRoot -GoalId $c1ahLg -Evaluator $c1ahBase.path
    $c1ahLTH = Invoke-EsEval -Root $c1ahRoot -GoalId $c1ahLg -Hook
    $c1ahLBH = Invoke-EsEval -Root $c1ahRoot -GoalId $c1ahLg -Hook -Evaluator $c1ahBase.path
    Add-C1ahRow -Label ('(l) CONTROL ' + $c1ahLg + ' (the placement arm, halt_absent, file_exists): tree and base, the SAME artifact, exit and hook JSON') `
        -Ok ($c1ahBase.ok -and ((Remove-WrProvenanceLine -Text (($c1ahLT.text -replace $esMask, 'evaluated_at: MASKED') -replace $wjScanMask, '')) -ceq ($c1ahLB.text -replace $esMask, 'evaluated_at: MASKED')) -and ($c1ahLT.exit -eq $c1ahLB.exit) -and ((Remove-WqAdmittedSentence -Text $c1ahLTH.out).Trim() -ceq $c1ahLBH.out.Trim())) `
        -Said ('tree ' + $c1ahLT.verdict + '/' + $c1ahLT.exit + ', base ' + $c1ahLB.verdict + '/' + $c1ahLB.exit + '; hook: ' + $c1ahLTH.out.Trim())
}

# (n) THE TRAP, CURED (BATCH-3 WP-J). Until the cure this row read: a goal file that does not
#     parse, with a DIRECTORY where its verdict artifact would be written -- the write throws, the evaluator's trap
#     reports and does not block -- reads approve, exit 9, from this tree and from the base alike; "the row fails
#     the day the trap is cured, and the page with it". That day came. The same fixture: this tree BLOCKS, exit 0,
#     the error its reason; the base still reads approve, exit 9, and is kept as the control. C-2e
#     drives the routes one by one.
Write-Utf8 -Path (Join-Path $c1ahRoot '.mission\goals\G-TRAP.yaml') -Text "id: G-TRAP`ndescription: `"declares nothing`"`n"
New-Item -ItemType Directory -Path (Join-Path $c1ahRoot '.mission\goals\G-TRAP.verdict.yaml') -Force | Out-Null
$c1ahNT = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-TRAP' -Hook
$c1ahNB = Invoke-EsEval -Root $c1ahRoot -GoalId 'G-TRAP' -Hook -Evaluator $c1ahBase.path
Add-C1ahRow -Label '(n) THE TRAP, CURED the unparseable goal with a DIRECTORY at its verdict artifact''s path: this tree BLOCKS, exit 0, the error its reason; the base still approves, exit 9, "goal-check errored"' `
    -Ok ($c1ahBase.ok -and ($c1ahNT.decision -ceq 'block') -and ($c1ahNT.exit -eq 0) -and $c1ahNT.reason.Contains('THE EVALUATOR ERRORED BEFORE ITS VERDICT WAS WRITTEN') -and $c1ahNT.reason.Contains('No verdict file was written') -and ($c1ahNB.decision -ceq 'approve') -and ($c1ahNB.exit -eq 9) -and $c1ahNB.reason.StartsWith('goal-check errored')) `
    -Said ('tree: exit ' + $c1ahNT.exit + ' ' + $c1ahNT.out.Trim() + ' | base: exit ' + $c1ahNB.exit + ' ' + $c1ahNB.out.Trim())

# (m) A GOAL OF RECORD, READ-ONLY, through the evaluator's own Read-GoalDetectors, lifted from this tree's evaluator by
#     its AST (as WP-2 R-E lifts it). The framework repository runs no mission and has no live goal; since
#     an earlier release the goal read is the framework's synthetic goal of record, a fixture installed with it and held to its
#     sha256: a goal of record's shape -- fourteen detectors, the placement arm first, neither newer arm -- that names no
#     host, read at every host alike.
$c1ahTok = $null; $c1ahErr = $null
$c1ahAst = [System.Management.Automation.Language.Parser]::ParseFile($goalCheck, [ref]$c1ahTok, [ref]$c1ahErr)
$c1ahFn = @($c1ahAst.FindAll({ param($n) ($n -is [System.Management.Automation.Language.FunctionDefinitionAst]) -and ($n.Name -ceq 'Read-GoalDetectors') }, $true))
$c1ahLive = Join-Path $repoRoot 'tests\lam\fixtures\base-700e19e5\.mission\goals\SAMPLE-GOAL.yaml'
$c1ahLiveSha = if (Test-Path -LiteralPath $c1ahLive -PathType Leaf) { (Get-FileHash -Algorithm SHA256 -LiteralPath $c1ahLive).Hash.ToLowerInvariant() } else { '' }
$c1ahLiveOk = ($c1ahLiveSha -ceq '1b544f9c127e964df3750d5fc6854e9fb8ae0ae8dba742c95fc4f84e3b49e75e')
$c1ahLiveFrom = 'the fixture tests\lam\fixtures\base-700e19e5\.mission\goals\SAMPLE-GOAL.yaml, the framework''s synthetic goal of record (sha256 ' + $(if ($c1ahLiveSha) { $c1ahLiveSha.Substring(0, 8) } else { 'ABSENT' }) + ', held to 1b544f9c)'
$c1ahLiveTypes = @()
if (($c1ahFn.Count -eq 1) -and $c1ahLiveOk -and (Test-Path -LiteralPath $c1ahLive -PathType Leaf)) {
    . ([scriptblock]::Create($c1ahFn[0].Extent.Text))
    $c1ahLiveTypes = @(Read-GoalDetectors -Path $c1ahLive | ForEach-Object { [string]$_['type'] })
}
Add-C1ahRow -Label '(m) A GOAL OF RECORD, READ-ONLY: SAMPLE-GOAL.yaml at its pin, parses to 14 detectors, declares ungated_placement_absent and NEITHER new type' `
    -Ok (($c1ahFn.Count -eq 1) -and $c1ahLiveOk -and ($c1ahLiveTypes.Count -eq 14) -and ($c1ahLiveTypes -ccontains $pwType) -and (-not ($c1ahLiveTypes -ccontains $esManType)) -and (-not ($c1ahLiveTypes -ccontains $esHoType))) `
    -Said ('read from ' + $c1ahLiveFrom + '; Read-GoalDetectors lifted: ' + ($c1ahFn.Count -eq 1) + '; types [' + ($c1ahLiveTypes -join ', ') + ']')
}
catch {
    $c1ahOk = $false
    $c1ahRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1ahRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1ahHeld) { try { $c1ahHeld.Dispose() } catch { } }
if ($null -ne $c1ahM) { Remove-PwTreeAsWritten -Base $c1ahM.base }
Check -Id 'C-1ah' -Title 'THE ABSENT GOAL AND THE UNREADABLE ONE (ruled by the operator 2026-09-30, lean A): a goal file at neither search location is an admitted stop that is RECORDED -- the Stop hook approves and exits 0 with a reason naming GOAL_ABSENT, the id and every path searched (an explicit -GoalFile included), and .mission/goals/<id>.verdict.yaml reads verdict GOAL_ABSENT with goal_searched; by hand exit 2 and the reason line under the status line; an id that is not one token, or a mission root with no .mission directory, where no verdict file can be written, is REFUSED -- the hook blocks, exit 0, the reason saying NOT_MET and why no file was written -- where it was admitted with no file before (C-2f drives it against the base), while a .mission with no goals directory has it made and the verdict written, and is admitted; a goal at the second location is found; a goal file that EXISTS but cannot be read, is a directory, has no detectors: line or no item under it REFUSES the stop -- the hook blocks, NOT_MET, the parse error printed as goal_parse -- while an open HALT still outranks it; with a DIRECTORY where its verdict artifact would be written, the unparseable goal ends in the evaluator''s trap, which now BLOCKS (exit 0, the error its reason) where the base evaluator approved with exit 9; a present, valid goal, met or unmet, writes the artifact, exit and decision the base evaluator writes; and the framework''s synthetic goal of record SAMPLE-GOAL.yaml, read through the evaluator''s own reader, parses to 14 detectors and declares neither new type' `
      -Ok $c1ahOk -Detail ("      THE $(@($c1ahRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1ahRows -join "`n"))

# =============================================================================================
# C-3g -- THE RESIDUALS, MEASURED (design v2.3 SS4.5 law 2): what obtains each new admitted stop, and
#         that nothing wider does; and the plane row
# =============================================================================================
# THE CHARTER'S RESIDUALS (the dispatch of this package): the dispatch-manifest stop is
# obtained by placing a file, as the placement arm's is; the handoff stop is an allow-side admission -- a seat
# can stop by writing a brief, as it can by placing an amendment or writing a HALT -- bounded by one stop
# per brief and by the admissions record; the absent goal stays allow-side. MEASURED: (a) ANY file named
# *.manifest.yaml under .mission/dispatches/ admits -- binary, empty, two directories down, hidden,
# ignored by git, a name with spaces and brackets -- each on its own line with git's own digest; (b) and
# nothing placed elsewhere; (c) a canonical gate over the arbitrary file's bytes releases it; (d) ANY
# file is a brief -- binary, empty, outside the mission root -- each admitted ONCE; (e) a distinct brief
# admits again, one stop per brief; (f) the record deleted, the first brief admits AGAIN -- the record
# is the bound, and the only one; (g) a hook naming a misspelling of an existing goal governs nothing and
# says so. THE PLANE ROW (h) closes C-1af..C-3g: every evaluation at a root under %TEMP%, and both live
# planes' sentinel paths unchanged since before C-1af.
$c3gOk = $true
$c3gRows = New-Object System.Collections.Generic.List[string]
function Add-C3gRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c3gOk = $false }
    $script:c3gRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c3gRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c3gM = $null
try {
$c3gM = New-EsMission -Tag 'c3g'
if (-not $c3gM.ok) { throw ('FIXTURE REFUSED: ' + $c3gM.why) }
$c3gRoot = $c3gM.root
Write-PwGoal -Root $c3gRoot -GoalId 'G-RES' -DetectorLines @(('  - type: ' + $esManType))
Write-Utf8 -Path (Join-Path $c3gRoot '.gitignore') -Text "ign-*.manifest.yaml`n"
$c3gBin = New-Object byte[] 256
for ($c3gI = 0; $c3gI -lt 256; $c3gI++) { $c3gBin[$c3gI] = [byte]$c3gI }
$c3gFiles = @(
    [pscustomobject]@{ rel = '.mission/dispatches/zz-arbitrary.manifest.yaml'; id = 'UNDETERMINABLE'; bytes = $c3gBin; label = 'a BINARY file of 256 bytes, no id' },
    [pscustomobject]@{ rel = '.mission/dispatches/empty.manifest.yaml'; id = 'UNDETERMINABLE'; bytes = [byte[]]@(); label = 'an EMPTY file' },
    [pscustomobject]@{ rel = '.mission/dispatches/deep/er/r.manifest.yaml'; id = 'v-deep-r1'; bytes = $pwUtf8.GetBytes("id: v-deep-r1`n"); label = 'a manifest TWO directories down' },
    [pscustomobject]@{ rel = '.mission/dispatches/.hidden.manifest.yaml'; id = 'v-hidden-r1'; bytes = $pwUtf8.GetBytes("id: v-hidden-r1`n"); label = 'a HIDDEN file' },
    [pscustomobject]@{ rel = '.mission/dispatches/ign-x.manifest.yaml'; id = 'v-ign-r1'; bytes = $pwUtf8.GetBytes("id: v-ign-r1`n"); label = 'a file git IGNORES (.gitignore: ign-*.manifest.yaml)' },
    [pscustomobject]@{ rel = '.mission/dispatches/Round (x) v2.manifest.yaml'; id = 'v-round-x-r2'; bytes = $pwUtf8.GetBytes("id: v-round-x-r2`n"); label = 'a name with spaces and brackets' })
foreach ($c3gF in $c3gFiles) { $null = Write-EsBytes -Root $c3gRoot -Rel $c3gF.rel -Bytes $c3gF.bytes }
$c3gHidden = Get-Item -LiteralPath (Join-Path $c3gRoot '.mission\dispatches\.hidden.manifest.yaml') -Force
$c3gHidden.Attributes = ($c3gHidden.Attributes -bor [System.IO.FileAttributes]::Hidden)
$c3gSt = Invoke-PwGit -Root $c3gRoot -GitArgs @('status', '--porcelain', '--ignored', '--untracked-files=all', '--', '.mission/dispatches')
$c3gStU = @(($c3gSt.text -split "`n") | Where-Object { $_ -match '^\?\? ' }).Count
$c3gStI = @(($c3gSt.text -split "`n") | Where-Object { $_ -match '^!! \.mission/dispatches/ign-x\.manifest\.yaml$' }).Count
Add-C3gRow -Label ('FIXTURE git reads ' + $c3gStU + ' of 5 files untracked and ign-x.manifest.yaml IGNORED (' + $c3gStI + '); no gate on disk') `
    -Ok (($c3gStU -eq 5) -and ($c3gStI -eq 1) -and (@(Get-ChildItem -LiteralPath (Join-Path $c3gRoot '.mission\gates') -File -Force).Count -eq 0)) -Said $c3gSt.text
$c3gA = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RES' -Hook
$c3gAH = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RES'
$c3gAHL = Get-EsHandLines -Out $c3gAH.out -GoalId 'G-RES' -Verdict $esManVerdict -Take 6
Add-C3gRow -Label ('(a) the stop is admitted: ' + $c3gA.verdict + ', exit ' + $c3gA.exit + ', ' + @($c3gA.dispatch).Count + ' line(s); by hand exit ' + $c3gAH.exit + ', ' + @($c3gAHL.under).Count + ' line(s) under the status line') `
    -Ok ($c3gA.admitted -and ($c3gA.verdict -ceq $esManVerdict) -and (@($c3gA.dispatch).Count -eq 6) -and ($c3gAH.exit -eq 5) -and (@(@($c3gAHL.under) | Where-Object { $_.StartsWith('  ' + $esManPrefix + ' ') }).Count -eq 6)) -Said ''
foreach ($c3gF in $c3gFiles) {
    $c3gFLf = Get-PwBlobSha -Root $c3gRoot -Rel $c3gF.rel
    $c3gFRaw = Get-PwRawSha -Path (Join-Path $c3gRoot $c3gF.rel.Replace('/', '\'))
    $c3gWant = $esManPrefix + ' ' + $c3gF.id + ' ' + $c3gFLf + '; ' + $c3gFRaw
    Add-C3gRow -Label ('(a) ' + $c3gF.label + ' ADMITS, its line in the artifact, the hook reason AND the hand-run status') `
        -Ok ([bool]$c3gFLf -and (@($c3gA.dispatch) -ccontains $c3gWant) -and $c3gA.reason.Contains($c3gWant) -and (@($c3gAHL.under) -ccontains ('  ' + $c3gWant))) -Said $c3gWant
}
# (b) NOT WIDER: eight untracked files that are not manifests under .mission/dispatches/ admit nothing.
foreach ($c3gF in $c3gFiles) { Remove-Item -LiteralPath (Join-Path $c3gRoot $c3gF.rel.Replace('/', '\')) -Force }
$c3gElse = @('.mission\dispatches\D-X.yaml', '.mission\dispatches\y.manifest.yml', '.mission\dispatches\y.manifest.yaml.bak', '.mission\dispatches-archive\z.manifest.yaml',
             '.mission\w.manifest.yaml', '.mission-runtime\dispatches\v.manifest.yaml', 'dispatches\u.manifest.yaml', '.mission\gates\t.manifest.yaml')
foreach ($c3gE in $c3gElse) { Write-Utf8 -Path (Join-Path $c3gRoot $c3gE) -Text ("id: v-elsewhere-r1`n") }
$c3gSt2 = Invoke-PwGit -Root $c3gRoot -GitArgs @('status', '--porcelain', '--untracked-files=all')
$c3gSt2N = @(($c3gSt2.text -split "`n") | Where-Object { ($_ -match '^\?\? ') -and ($_ -match '(D-X\.yaml|\.manifest\.yml|\.manifest\.yaml\.bak|z\.manifest\.yaml|w\.manifest\.yaml|v\.manifest\.yaml|u\.manifest\.yaml|t\.manifest\.yaml)$') }).Count
$c3gB = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RES' -Hook
Add-C3gRow -Label ('(b) NOT WIDER: ' + $c3gSt2N + ' of 8 untracked files that are not a *.manifest.yaml under .mission/dispatches/ admit nothing: MET, no line') `
    -Ok (($c3gSt2N -eq 8) -and ($c3gB.verdict -ceq 'MET') -and $c3gB.admitted -and (@($c3gB.dispatch).Count -eq 0)) `
    -Said ('a dispatch artifact, .manifest.yml, .manifest.yaml.bak, a sibling directory, .mission/, .mission-runtime/dispatches/, dispatches/ at the root, the gates directory; the arm: ' + (Get-PwDetector -Text $c3gB.text -Type $esManType).detail)
foreach ($c3gE in $c3gElse) { Remove-Item -LiteralPath (Join-Path $c3gRoot $c3gE) -Force }
# ... AND WIDER BY ONE THING (validator round 1): a DIRECTORY LINK under .mission\dispatches, no manifest on
#     disk under it that the walk enters -- the walk does not enter a link, so whether it holds a manifest is not
#     established, and that ADMITS: one UNDETERMINABLE line. The link is this member's, removed in finally.
$c3gLinkTarget = Join-Path $c3gM.base 'linked'
Write-Utf8 -Path (Join-Path $c3gLinkTarget 'not-a-manifest.txt') -Text "no manifest here`n"
$c3gLink = Join-Path $c3gRoot '.mission\dispatches\link'
$c3gLinkMade = $false
$c3gJn = $null
try {
    $null = New-Item -ItemType Junction -Path $c3gLink -Target $c3gLinkTarget
    $c3gLinkMade = $true
    $c3gJn = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RES' -Hook
} finally { if ($c3gLinkMade) { [System.IO.Directory]::Delete($c3gLink) } }
Add-C3gRow -Label ('(b) WIDER BY ONE THING a directory LINK under .mission\dispatches holding no manifest: ADMITTED, ' + $esManVerdict + ', one UNDETERMINABLE line') `
    -Ok ($c3gJn.admitted -and ($c3gJn.verdict -ceq $esManVerdict) -and (@($c3gJn.dispatch).Count -eq 1) -and (@($c3gJn.dispatch)[0] -ceq $esManUnd) -and (-not (Test-Path -LiteralPath $c3gLink))) `
    -Said ('verdict ' + $c3gJn.verdict + '; lines [' + (@($c3gJn.dispatch) -join ' ; ') + ']; the arm: ' + (Get-PwDetector -Text $c3gJn.text -Type $esManType).detail)
# (c) WHAT BOUNDS IT: a canonical dispatch gate over the arbitrary file's bytes releases it.
$c3gArb = Write-EsBytes -Root $c3gRoot -Rel '.mission/dispatches/zz-arbitrary.manifest.yaml' -Bytes $c3gBin
New-EsDispatchGate -Path (Join-Path $c3gRoot '.mission\gates\dispatch-zz-arbitrary.yaml') -Id 'zz-arbitrary' -BindsRel '.mission\dispatches\zz-arbitrary.manifest.yaml' -Sha (Get-PwRawSha -Path $c3gArb)
$c3gC = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RES' -Hook
Add-C3gRow -Label '(c) a canonical dispatch gate over the arbitrary file''s bytes releases it: MET' `
    -Ok (($c3gC.verdict -ceq 'MET') -and $c3gC.admitted -and (@($c3gC.dispatch).Count -eq 0)) -Said ('verdict ' + $c3gC.verdict)

# (d) ANY FILE IS A BRIEF, each admitted ONCE; (e) one stop per brief; (f) the record is the only bound.
Write-PwGoal -Root $c3gRoot -GoalId 'G-RESHO' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
$c3gOut = Join-Path $c3gM.base 'outside'
$c3gBriefs = @(
    [pscustomobject]@{ full = (Write-EsBytes -Root $c3gRoot -Rel '.mission-runtime/lam/handoff/any.bin' -Bytes $c3gBin); path = '.mission-runtime/lam/handoff/any.bin'; label = 'a BINARY file under the mission root' },
    [pscustomobject]@{ full = (Write-EsBytes -Root $c3gRoot -Rel '.mission-runtime/lam/handoff/empty' -Bytes ([byte[]]@())); path = '.mission-runtime/lam/handoff/empty'; label = 'an EMPTY file' },
    [pscustomobject]@{ full = (Write-EsBytes -Root $c3gOut -Rel 'brief-outside.md' -Bytes ($pwUtf8.GetBytes("outside the mission root`n"))); path = ''; label = 'a file OUTSIDE the mission root, by its absolute path' },
    [pscustomobject]@{ full = (Write-EsBytes -Root $c3gRoot -Rel 'evidence/a-fourth-brief.txt' -Bytes ($pwUtf8.GetBytes("a fourth, distinct brief`n"))); path = 'evidence/a-fourth-brief.txt'; label = 'a fourth, DISTINCT brief' })
$c3gBriefs[2].path = $c3gBriefs[2].full
$c3gN = 0
foreach ($c3gBr in $c3gBriefs) {
    $c3gSha = Get-PwRawSha -Path $c3gBr.full
    Write-EsStatus -Root $c3gRoot -Head (Get-EsHead -Ctx '50' -Lf $c3gSha -Raw $c3gSha -Path $c3gBr.path)
    $c3gD1 = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RESHO' -Hook
    $c3gD2 = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RESHO' -Hook
    $c3gN++
    Add-C3gRow -Label ('(d/e) ' + $c3gBr.label + ': ADMITTED once, then REFUSED; the record at ' + $c3gN + ' line(s)') `
        -Ok ($c3gD1.admitted -and ($c3gD1.verdict -ceq $esHoVerdict) -and ($c3gD2.decision -ceq 'block') -and $c3gD2.reason.Contains('already admitted') -and ((Get-EsRecord -Root $c3gRoot).count -eq $c3gN)) `
        -Said ('first ' + $c3gD1.verdict + '/' + $c3gD1.decision + ', second ' + $c3gD2.verdict + '/' + $c3gD2.decision)
}
$c3gFirst = Get-PwRawSha -Path $c3gBriefs[0].full
$c3gRecPath = Join-Path $c3gRoot '.mission-runtime\lam\handoff-admissions.jsonl'
$c3gRecThere = Test-Path -LiteralPath $c3gRecPath -PathType Leaf
if ($c3gRecThere) { Remove-Item -LiteralPath $c3gRecPath -Force }
Write-EsStatus -Root $c3gRoot -Head (Get-EsHead -Ctx '50' -Lf $c3gFirst -Raw $c3gFirst -Path $c3gBriefs[0].path)
$c3gF1 = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RESHO' -Hook
Add-C3gRow -Label '(f) THE RECORD DELETED: the first brief''s head ADMITS AGAIN -- the record is the bound, and the only one' `
    -Ok ($c3gRecThere -and $c3gF1.admitted -and ($c3gF1.verdict -ceq $esHoVerdict) -and ((Get-EsRecord -Root $c3gRoot).count -eq 1)) `
    -Said ('a record to delete: ' + $c3gRecThere + '; verdict ' + $c3gF1.verdict)

# (g) THE ABSENT GOAL STAYS ALLOW-SIDE: a hook naming a misspelling of an existing goal.
$c3gG = Invoke-EsEval -Root $c3gRoot -GoalId 'G-RESS' -Hook
Add-C3gRow -Label ('(g) a hook naming G-RESS while G-RES exists: ' + $esAbsVerdict + ', approve -- it governs nothing, and says so') `
    -Ok ($c3gG.admitted -and ($c3gG.verdict -ceq $esAbsVerdict) -and $c3gG.reason.Contains('no goal file for ''G-RESS''')) -Said ('reason: ' + $c3gG.reason)
}
catch {
    $c3gOk = $false
    $c3gRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c3gRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c3gM) { Remove-PwTreeAsWritten -Base $c3gM.base }
# (h) THE PLANE ROW, over C-1af..C-3g.
$esPlaneAfter = Get-EsPlaneSnapshot
$esOutside = @($esEvalRoots | Where-Object { -not $_.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase) })
Add-C3gRow -Label ('(h) PLANE ' + $esEvalRoots.Count + ' evaluations by C-1af..C-3g, every one at a root under %TEMP%; both live planes'' sentinel paths unchanged since before C-1af') `
    -Ok (($esEvalRoots.Count -gt 0) -and ($esOutside.Count -eq 0) -and ($esPlaneAfter -ceq $esPlaneBefore)) `
    -Said ('outside %TEMP%: ' + $esOutside.Count + '; snapshot equal: ' + ($esPlaneAfter -ceq $esPlaneBefore) + '; ' + (($esPlaneBefore -split "`r?`n" | Where-Object { $_ -match 'handoff-admissions' }) -join ' | '))
Check -Id 'C-3g' -Title 'THE RESIDUALS, MEASURED (design v2.3 SS4.5 law 2; BATCH-2 WP-H): a seat obtains the dispatch-manifest stop by placing ANY file named *.manifest.yaml under .mission/dispatches/ -- a binary file, an empty file, one two directories down, a hidden file, one git ignores and a name with spaces and brackets each admit, each on its own AWAITING DISPATCH GATE line with git''s own digest in the verdict artifact, the hook reason and the hand-run status -- and by nothing placed elsewhere: eight untracked files (a dispatch artifact, .manifest.yml, .manifest.yaml.bak, a sibling directory, .mission itself, .mission-runtime/dispatches, dispatches at the root, the gates directory) admit nothing -- while a directory LINK under .mission/dispatches that holds no manifest admits, on one UNDETERMINABLE line; a canonical dispatch gate over the arbitrary file''s bytes releases it; a seat obtains the handoff stop with ANY file as the brief -- binary, empty, outside the mission root; the admissions record itself excepted, which C-1aj drives, and the goal''s own verdict artifact, which C-1am drives -- once per distinct brief, and the record deleted, the same brief admits again; a hook naming a misspelling of an existing goal reads GOAL_ABSENT and approves; and every evaluation by C-1af..C-3g ran at a root under %TEMP%, both live planes'' sentinel paths unchanged' `
      -Ok $c3gOk -Detail ("      THE $(@($c3gRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c3gRows -join "`n"))

# =============================================================================================
# BATCH-3 WP-J -- THE EVALUATOR'S TRAP, THE REUSE OF A FRESH READING, THE HALT SCAN'S ROOTS, THE
# ADMISSIONS RECORD AS A BRIEF AND THE HELPER'S COUNT LINE: C-2e, C-1ai, C-3h, C-1aj and C-1ak
# (the BATCH-3 charter, SS B (a)-(e))
# =============================================================================================
# THE CHARTER'S WORDS, verbatim (SS B):
#   (a) "... THE TRAP. Today an error before the verdict is written ends in approve, exit 9, by four
#       routes ... CURE: fail CLOSED -- any error before the verdict is written BLOCKS the stop with a printed
#       reason and writes the verdict when it can; no route ends in approve without a written verdict."
#   (b) "instrument_exit0 MAY reuse a capture of the same instrument when ALL hold: HEAD equal; the tree clean
#       apart from the mission's declared set (verify's own predicate); the instrument's blob equal; the
#       capture's own HEAD and captured_at inside a window the GOAL FILE declares per detector
#       (reuse_within_minutes; default 0 = never reuse, so every existing goal file is unaffected); and the
#       verdict NAMES the capture reused by path and sha256. Otherwise a fresh run."
#   (c) "The evaluator states the roots it scans in its own verdict and excludes a fixture under a nested
#       mission root (a directory below the live root carrying its own .mission/) and the scratch-copies tree
#       by RULE, not by observation".
#   (d) "... the admissions record itself named as the HANDOFF brief -> refused."
#   (e) "Save-LamInstrumentRun's tally parser learns the instruments' own line "WP-n: all N checks passed."
#       (and its FAILED form) so a tally capture carries the count; NO-TALLY stays the word for a stdout with
#       neither."
# THE FIVE MEMBERS. C-2e drives the trap's routes; C-1ai the reuse; C-3h the scan; C-1aj the record as a
# brief; C-1ak the helper's count line, and closes with the plane row. EVERY FALSIFIER ROW IS RED AT THE TREE
# BEFORE THE CURE, and where a base evaluator can show it the RED is KEPT as a control: the evaluator and its
# three libraries as they stood at this branch's parent at the cut, each pinned by its LF/blob
# sha256 (New-WjBaseTools).
# THE FIXTURE FORM IS C-1af's (New-EsMission): a real git repository under %TEMP%, its git dir and its common
# dir asserted EXACTLY <root>\.git before git is used again (the 2026-09-13 rule), `git config` never
# run. Every evaluation goes through Invoke-EsEval or Invoke-WjHook, and both REFUSE a mission root outside
# %TEMP%. No member here spawns a seat, writes a spawn-ledger line or touches a live mission plane.
$wjBaseSha  = '700e19e5-s03'
$wjBasePins = [ordered]@{
    'mission-goal-check.ps1'   = '7d5e23db81e89ce7244a2c5cea1e44bd6d9a86cbaca1cfbc39d9433f49ee01ea'
    'lam-verify-admission.ps1' = 'ccd0d7d1656a0dba4187585d5e583d604e3c65882c094c7df704b800f4d4ba58'
    'lam-gate-class.ps1'       = 'bc7a3cd885709c5df5661f3a5cd308b878e7d63e89246a43e3d029278247e577'
    'lam-instrument-run.ps1'   = 'ecf28251ba9a98bf599513d85a5d6999874d13b09ea4ce62dbf7af47a8369245'
}
function New-WjBaseTools {
    # The base evaluator, its three libraries among them the helper, each at its pinned
    # LF/blob sha256, under -Dir. path is the evaluator, helper the helper.
    param([string]$Dir)
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    $wjPinOk = $true
    $wjPinSaid = New-Object System.Collections.Generic.List[string]
    foreach ($wjPinName in @($script:wjBasePins.Keys)) {
        # Through Get-LamBaseBytes: the installed fixtures alone, no history -- the pin decides.
        $wjRead = Get-LamBaseBytes -Base $script:wjBaseSha -Path ('tools/lam/' + $wjPinName) -Pin $script:wjBasePins[$wjPinName]
        if (-not $wjRead.ok) { $wjPinOk = $false }
        $wjPinSaid.Add($wjPinName + ' ' + $wjRead.sha.Substring(0, 8) + ' (' + $wjRead.from + ')')
        [System.IO.File]::WriteAllBytes((Join-Path $Dir $wjPinName), $wjRead.bytes)
    }
    return [pscustomobject]@{ ok = $wjPinOk; path = (Join-Path $Dir 'mission-goal-check.ps1'); helper = (Join-Path $Dir 'lam-instrument-run.ps1'); said = ($wjPinSaid -join ', ') }
}
function ConvertTo-WjComparable {
    # A verdict artifact with its clock masked and the two scanned-set keys taken out: what a tree
    # and a base older than those keys can be compared on, byte for byte. AND, SINCE BATCH-7 WP-R (c), the provenance
    # line hook_or_hand taken out (Remove-WrProvenanceLine): no base older than it writes one.
    param([string]$Text)
    return (Remove-WrProvenanceLine -Text ((([string]$Text) -replace $script:esMask, 'evaluated_at: MASKED') -replace $script:wjScanMask, ''))
}
function Invoke-WjHook {
    # The evaluator as the Stop hook runs it (or -ByHand), AT A FIXTURE ONLY (the plane rule, as Invoke-EsEval).
    # Unlike Invoke-EsEval it does NOT remove a prior verdict artifact -- C-2e's rows put a directory there, or
    # hold the file open -- and -Dispatch sets LAM_DISPATCH for the child, where Invoke-EsEval clears it;
    # -TranscriptPath puts a transcript_path in the Stop payload, which the evaluator reads before anything else.
    # Returns exit, out, decision, reason, text (the verdict file where it is a readable file) and verdict.
    param([string]$Root, [string]$GoalId, [string]$Evaluator, [string]$Dispatch = '', [switch]$ByHand, [string]$TranscriptPath = '')
    if (-not $Evaluator) { $Evaluator = $goalCheck }
    $wjFull = [System.IO.Path]::GetFullPath($Root)
    if (-not $wjFull.StartsWith($script:esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ('PLANE RULE: ' + $wjFull + ' is not under ' + $script:esTempRoot + ' -- these members evaluate fixtures only')
    }
    $script:esEvalRoots.Add($wjFull)
    $wjArgv = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $Evaluator, '-Goal', $GoalId, '-MissionRoot', $Root)
    if (-not $ByHand) { $wjArgv += '-AsStopHook' }
    $wjSavedDispatch = $env:LAM_DISPATCH
    $env:LAM_DISPATCH = $(if ($Dispatch) { $Dispatch } else { $null })
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        if ($ByHand) { $wjO = & powershell @wjArgv 2>&1 }
        else {
            $wjPayloadMap = @{ session_id = 'wp3-wj'; hook_event_name = 'Stop' }
            if ($TranscriptPath) { $wjPayloadMap['transcript_path'] = $TranscriptPath }
            $wjPayload = ($wjPayloadMap | ConvertTo-Json -Compress)
            $wjO = $wjPayload | & powershell @wjArgv 2>&1
        }
        $wjC = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $prevEap
        $env:LAM_DISPATCH = $wjSavedDispatch
    }
    $wjOut = ((@($wjO) | ForEach-Object { [string]$_ }) -join "`n")
    $wjVf = Join-Path $Root ('.mission\goals\' + $GoalId + '.verdict.yaml')
    $wjText = ''
    if (Test-Path -LiteralPath $wjVf -PathType Leaf) { try { $wjText = [System.IO.File]::ReadAllText($wjVf) } catch { $wjText = '' } }
    $wjV = '(no verdict file)'
    $wjVm = [regex]::Match($wjText, '(?m)^verdict:[ \t]*(\S+)')
    if ($wjVm.Success) { $wjV = $wjVm.Groups[1].Value }
    $wjDec = ''
    $wjReason = ''
    foreach ($wjLn in @($wjOut -split "`n")) {
        $wjT = $wjLn.Trim()
        if (-not $wjT.StartsWith('{')) { continue }
        try { $wjJ = $wjT | ConvertFrom-Json; $wjDec = [string]$wjJ.decision; $wjReason = [string]$wjJ.reason; break } catch { }
    }
    return [pscustomobject]@{ exit = $wjC; out = $wjOut; decision = $wjDec; reason = $wjReason; text = $wjText; verdict = $wjV }
}

# =============================================================================================
# C-2e -- THE TRAP FAILS CLOSED: an error before the verdict is written BLOCKS the
#         stop, the error its reason, and the verdict is written where it can be
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: each route ends in
# `approve`, exit 9, "goal-check errored", and no verdict is written. THE ROUTES, each its own rows:
# (1) a goal that does not parse with a DIRECTORY at its verdict artifact's path; (2) a goal file the
# search cannot stat -- the file denied ReadData and ReadAttributes, its directory ListDirectory; (3) an
# eligible HANDOFF head with the artifact unwritable, at the first stop and at the next; (4) the verdict
# artifact held by another process with no sharing -- what the loser of two Stop hooks at once meets --
# over an unmet goal and over a met one; and (5) the fifth route, a halt_absent `dir` the
# path resolver throws on, where the artifact IS writable and the trap's own verdict is read back.
# THE CONTROLS: (w) a dispatched worker is approved as it was, tree and base alike; (c) seven stops that
# are not errors -- MET, NOT_MET, HALT, the three admitted arms and the absent goal -- print the hook
# decision and exit the base prints, and write the artifact the base writes but for the two scanned-set keys.
$c2eOk = $true
$c2eRows = New-Object System.Collections.Generic.List[string]
function Add-C2eRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c2eOk = $false }
    $script:c2eRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c2eRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Test-C2eBlocked {
    # THE GREEN READING OF A ROUTE: the hook BLOCKS in the form NOT_MET blocks in -- decision block, exit 0 --
    # its reason naming the goal NOT_MET, the error, the row, and what became of the verdict file.
    param($Run, [string]$GoalId, [string]$Tail)
    return (($Run.decision -ceq 'block') -and ($Run.exit -eq 0) -and $Run.reason.Contains("Goal '" + $GoalId + "' is NOT_MET: THE EVALUATOR ERRORED BEFORE ITS VERDICT WAS WRITTEN -- ") -and
            $Run.reason.Contains('the stop is REFUSED (register row 358)') -and $Run.reason.Contains($Tail))
}
function Test-C2eTrapped {
    # THE RED READING: the old trap -- approve, exit 9, "goal-check errored".
    param($Run)
    return (($Run.decision -ceq 'approve') -and ($Run.exit -eq 9) -and $Run.reason.StartsWith('goal-check errored'))
}
$c2eM = $null
$c2eHeld = $null
$c2eDenied = $false
try {
$c2eM = New-EsMission -Tag 'c2e'
if (-not $c2eM.ok) { throw ('FIXTURE REFUSED: ' + $c2eM.why) }
$c2eRoot = $c2eM.root
$c2eGoals = Join-Path $c2eRoot '.mission\goals'
$c2eBase = New-WjBaseTools -Dir (Join-Path $c2eM.base 'base-tools')
Add-C2eRow -Label ('FIXTURE a git repository under %TEMP%, git dir and common dir exactly <root>\.git; the base evaluator and its three libraries from ' + $wjBaseSha + ', each at its pinned LF/blob sha256') `
    -Ok $c2eBase.ok -Said ('root ' + $c2eRoot + '; ' + $c2eBase.said)

# (1) ROUTE ONE: a goal that does not parse, a DIRECTORY at its verdict artifact's path.
Write-Utf8 -Path (Join-Path $c2eGoals 'G-WJ1.yaml') -Text "id: G-WJ1`ndescription: `"declares nothing`"`n"
New-Item -ItemType Directory -Path (Join-Path $c2eGoals 'G-WJ1.verdict.yaml') -Force | Out-Null
$c2e1B = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ1' -Evaluator $c2eBase.path
$c2e1T = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ1'
$c2e1H = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ1' -ByHand
Add-C2eRow -Label '(1) ROUTE ONE an unparseable goal, a DIRECTORY at its verdict artifact: RED at the base -- approve, exit 9, "goal-check errored"' `
    -Ok (Test-C2eTrapped $c2e1B) -Said ('base: exit ' + $c2e1B.exit + ' ' + $c2e1B.out.Trim())
Add-C2eRow -Label '(1) ... GREEN at this tree: BLOCKED, exit 0, the error printed, and the reason says no verdict file could be written and why' `
    -Ok (Test-C2eBlocked $c2e1T 'G-WJ1' 'No verdict file was written: writing ') -Said ('tree: exit ' + $c2e1T.exit + ' ' + $c2e1T.out.Trim())
Add-C2eRow -Label '(1) ... by hand: exit 9 as it was, the UNHANDLED ERROR line, and a third line saying no verdict file was written' `
    -Ok (($c2e1H.exit -eq 9) -and $c2e1H.out.Contains('mission-goal-check: UNHANDLED ERROR -- ') -and $c2e1H.out.Contains('  verdict   : none -- writing ')) -Said ('exit ' + $c2e1H.exit)

# (w) THE WORKER GUARD, UNCHANGED: over route one's fixture a dispatched worker is approved, exit 0, in the
#     base's own bytes -- the guard stands above everything that can error; row (6) drives where it stands.
$c2eWT = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ1' -Dispatch 'D-WJ-WORKER'
$c2eWB = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ1' -Dispatch 'D-WJ-WORKER' -Evaluator $c2eBase.path
Add-C2eRow -Label '(w) CONTROL a dispatched worker (LAM_DISPATCH set) over route one''s fixture: approve, exit 0, the worker reason -- tree and base, the same bytes' `
    -Ok (($c2eWT.decision -ceq 'approve') -and ($c2eWT.exit -eq 0) -and $c2eWT.reason.Contains("dispatched worker 'D-WJ-WORKER'") -and ($c2eWB.exit -eq 0) -and ($c2eWT.out.Trim() -ceq $c2eWB.out.Trim())) `
    -Said ('tree: exit ' + $c2eWT.exit + ' ' + $c2eWT.out.Trim())

# (6) AN ERROR ABOVE WHERE THE GUARD USED TO STAND: a library that does not load. The row above cannot see WHERE
#     the guard stands -- route one's error is far below both places. This one can: two copies of the tools,
#     this tree's and the base's, each WITHOUT lam-gate-class.ps1, so the evaluator errors at its second
#     dot-source. A worker must still be approved; anyone else is blocked, and the verdict is written at the
#     canonical path, no goal having been found yet.
$c2eNoLibT = Join-Path $c2eM.base 'nolib-tree'
$c2eNoLibB = Join-Path $c2eM.base 'nolib-base'
New-Item -ItemType Directory -Path $c2eNoLibT -Force | Out-Null
New-Item -ItemType Directory -Path $c2eNoLibB -Force | Out-Null
foreach ($c2eLibName in @('mission-goal-check.ps1', 'lam-verify-admission.ps1', 'lam-instrument-run.ps1')) {
    Copy-Item -LiteralPath (Join-Path $repoRoot ('tools\lam\' + $c2eLibName)) -Destination (Join-Path $c2eNoLibT $c2eLibName)
    Copy-Item -LiteralPath (Join-Path (Split-Path -Parent $c2eBase.path) $c2eLibName) -Destination (Join-Path $c2eNoLibB $c2eLibName)
}
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJM' -DetectorLines @('  - type: halt_absent', '  - type: file_exists', '    path: evidence/built.txt')
$c2e6WT = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJM' -Dispatch 'D-WJ-WORKER' -Evaluator (Join-Path $c2eNoLibT 'mission-goal-check.ps1')
$c2e6WB = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJM' -Dispatch 'D-WJ-WORKER' -Evaluator (Join-Path $c2eNoLibB 'mission-goal-check.ps1')
$c2e6T = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJM' -Evaluator (Join-Path $c2eNoLibT 'mission-goal-check.ps1')
$c2eVf6 = Join-Path $c2eGoals 'G-WJM.verdict.yaml'
Add-C2eRow -Label '(6) FALSIFIER a library that does not load, a dispatched WORKER: approve, exit 0, the worker reason -- the guard stands above the libraries; RED at the base, where it stood below them: the old trap, exit 9' `
    -Ok (($c2e6WT.decision -ceq 'approve') -and ($c2e6WT.exit -eq 0) -and $c2e6WT.reason.Contains("dispatched worker 'D-WJ-WORKER'") -and (Test-C2eTrapped $c2e6WB)) `
    -Said ('tree: exit ' + $c2e6WT.exit + ' ' + $c2e6WT.out.Trim() + ' | base: exit ' + $c2e6WB.exit + ' ' + $c2e6WB.out.Trim())
Add-C2eRow -Label '(6) ... the same error, NOT a worker: BLOCKED, exit 0, the verdict written at the canonical path with goal_file "not established" -- the trap covers what stands above it' `
    -Ok ((Test-C2eBlocked $c2e6T 'G-WJM' ('Verdict: ' + $c2eVf6 + '.')) -and ($c2e6T.verdict -ceq 'NOT_MET') -and ($c2e6T.text -match '(?m)^goal_file: not established')) -Said ('tree: exit ' + $c2e6T.exit + ' ' + $c2e6T.out.Trim())
Remove-Item -LiteralPath $c2eVf6 -Force -ErrorAction SilentlyContinue

# (7) A TRANSCRIPT THAT CANNOT BE READ IS NOT AN ERROR: the Stop payload names a transcript_path, read for
#     turn_cap alone, and here it is a DIRECTORY. The base ended in its trap -- approve, exit 9, nothing
#     evaluated. This tree reads the count as -1: a goal that declares no turn_cap is evaluated as it is,
#     and one that declares it fails that entry, as it always has for a count it cannot get.
$c2eTranscript = Join-Path $c2eM.base 'transcript-is-a-directory'
New-Item -ItemType Directory -Path $c2eTranscript -Force | Out-Null
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJT' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', '  - type: turn_cap', '    cap: 5')
$c2e7B = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJM' -TranscriptPath $c2eTranscript -Evaluator $c2eBase.path
Remove-Item -LiteralPath $c2eVf6 -Force -ErrorAction SilentlyContinue
$c2e7T = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJM' -TranscriptPath $c2eTranscript
$c2e7C = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJT' -TranscriptPath $c2eTranscript
Add-C2eRow -Label '(7) a Stop payload whose transcript_path is a DIRECTORY, a met goal with no turn_cap: RED at the base -- the trap, approve, exit 9, nothing evaluated; GREEN -- evaluated: MET, approve, exit 0' `
    -Ok ((Test-C2eTrapped $c2e7B) -and ($c2e7T.decision -ceq 'approve') -and ($c2e7T.exit -eq 0) -and ($c2e7T.verdict -ceq 'MET')) `
    -Said ('base: exit ' + $c2e7B.exit + ' ' + $c2e7B.out.Trim() + ' | tree: exit ' + $c2e7T.exit + ' ' + $c2e7T.verdict)
Add-C2eRow -Label '(7) ... a goal that DECLARES turn_cap over the same payload: its own entry fails -- CANNOT BE EVALUATED -- NOT_MET, the hook blocks; the unreadable count is -1, not an error' `
    -Ok (($c2e7C.decision -ceq 'block') -and ($c2e7C.exit -eq 0) -and ($c2e7C.verdict -ceq 'NOT_MET') -and $c2e7C.reason.Contains('turn_cap 5 CANNOT BE EVALUATED') -and (-not $c2e7C.reason.Contains('ERRORED'))) -Said ('tree: ' + $c2e7C.out.Trim())
Remove-Item -LiteralPath $c2eVf6 -Force -ErrorAction SilentlyContinue

# (5) THE FIFTH ROUTE: a halt_absent `dir` the path resolver throws on, outside the
#     per-detector catch. The artifact IS writable here, so the trap's own verdict is read back.
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJ5' -DetectorLines @('  - type: halt_absent', '    dir: a|b', '  - type: file_exists', '    path: evidence/built.txt')
$c2eVf5 = Join-Path $c2eGoals 'G-WJ5.verdict.yaml'
$c2e5B = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ5' -Evaluator $c2eBase.path
$c2e5BFile = Test-Path -LiteralPath $c2eVf5
$c2e5T = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ5'
Add-C2eRow -Label '(5) ROUTE FIVE a halt_absent dir the resolver throws on (a|b): RED at the base -- approve, exit 9, and no verdict file at all' `
    -Ok ((Test-C2eTrapped $c2e5B) -and (-not $c2e5BFile)) -Said ('base: exit ' + $c2e5B.exit + ' ' + $c2e5B.out.Trim() + '; verdict file: ' + $c2e5BFile)
Add-C2eRow -Label '(5) ... GREEN: BLOCKED, exit 0, AND THE VERDICT IS WRITTEN: verdict NOT_MET, evaluator_error at column 0, one failing entry of type evaluator_error, the reason naming the file' `
    -Ok ((Test-C2eBlocked $c2e5T 'G-WJ5' ('Verdict: ' + $c2eVf5 + '.')) -and ($c2e5T.verdict -ceq 'NOT_MET') -and ($c2e5T.text -match '(?m)^evaluator_error: ''') -and
         ($c2e5T.text -match '(?m)^  - type: evaluator_error\r?\n    ok: false\r?\n    detail: ''THE EVALUATOR ERRORED BEFORE ITS VERDICT WAS WRITTEN -- ') -and ($c2e5T.text -match '(?m)^failing_count: 1\r?$') -and ($c2e5T.text -match '(?m)^halt_scan_roots: \[\]')) `
    -Said ('tree: exit ' + $c2e5T.exit + ' ' + $c2e5T.out.Trim())
Remove-Item -LiteralPath $c2eVf5 -Force -ErrorAction SilentlyContinue
$c2e5H = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ5' -ByHand
Add-C2eRow -Label '(5) ... by hand: exit 9, the verdict file written (NOT_MET) and named on the third line' `
    -Ok (($c2e5H.exit -eq 9) -and ($c2e5H.verdict -ceq 'NOT_MET') -and $c2e5H.out.Contains('  verdict   : ' + $c2eVf5 + ' (NOT_MET, evaluator_error)')) -Said ('exit ' + $c2e5H.exit + '; verdict ' + $c2e5H.verdict)

# (2) ROUTE TWO: a goal file the search cannot even stat. A second, plain mission root inside this fixture's
#     base, so the denials touch no other row: the goal FILE denied ReadData and ReadAttributes, its DIRECTORY
#     denied ListDirectory, for this user; both removed in finally, the directory's first.
$c2eRoot2 = Join-Path $c2eM.base 'stat\m'
$c2eGoals2 = Join-Path $c2eRoot2 '.mission\goals'
$c2eGoal2 = Join-Path $c2eGoals2 'G-WJ2.yaml'
Write-Utf8 -Path $c2eGoal2 -Text "id: G-WJ2`ndetectors:`n  - type: file_exists`n    path: evidence/built.txt`n"
Write-Utf8 -Path (Join-Path $c2eRoot2 'evidence\built.txt') -Text "built`n"
$c2eVf2 = Join-Path $c2eGoals2 'G-WJ2.verdict.yaml'
$c2eWho = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
$c2e2Clean = Invoke-WjHook -Root $c2eRoot2 -GoalId 'G-WJ2'
Remove-Item -LiteralPath $c2eVf2 -Force -ErrorAction SilentlyContinue
$c2e2B = $null; $c2e2T = $null; $c2e2Said = ''
try {
    $c2eDenied = $true
    $c2e2Said = (Invoke-C4aIcacls @($c2eGoal2, '/deny', ($c2eWho + ':(RD,RA)'), '/Q')) + ' | ' + (Invoke-C4aIcacls @($c2eGoals2, '/deny', ($c2eWho + ':(RD)'), '/Q'))
    $c2e2B = Invoke-WjHook -Root $c2eRoot2 -GoalId 'G-WJ2' -Evaluator $c2eBase.path
    $c2e2T = Invoke-WjHook -Root $c2eRoot2 -GoalId 'G-WJ2'
} finally {
    $null = Invoke-C4aIcacls @($c2eGoals2, '/remove:d', $c2eWho, '/C', '/Q')
    $null = Invoke-C4aIcacls @($c2eGoal2, '/remove:d', $c2eWho, '/C', '/Q')
    $c2eDenied = $false
}
$c2e2Text = if (Test-Path -LiteralPath $c2eVf2 -PathType Leaf) { [System.IO.File]::ReadAllText($c2eVf2) } else { '' }
Add-C2eRow -Label '(2) FIXTURE the same goal with nothing denied reads MET and approves: what follows is the denial''s doing' `
    -Ok (($c2e2Clean.decision -ceq 'approve') -and ($c2e2Clean.exit -eq 0) -and ($c2e2Clean.verdict -ceq 'MET')) -Said ('verdict ' + $c2e2Clean.verdict + '; icacls: ' + $c2e2Said)
Add-C2eRow -Label '(2) ROUTE TWO a goal file that cannot be stat''d (the file denied RD and RA, its directory denied list): RED at the base -- approve, exit 9' `
    -Ok (Test-C2eTrapped $c2e2B) -Said ('base: exit ' + $c2e2B.exit + ' ' + $c2e2B.out.Trim())
Add-C2eRow -Label '(2) ... GREEN: BLOCKED, exit 0, and the verdict WRITTEN at the canonical path -- NOT_MET, evaluator_error, goal_file "not established"' `
    -Ok ((Test-C2eBlocked $c2e2T 'G-WJ2' ('Verdict: ' + $c2eVf2 + '.')) -and ($c2e2Text -match '(?m)^verdict: NOT_MET\r?$') -and ($c2e2Text -match '(?m)^evaluator_error: ''') -and ($c2e2Text -match '(?m)^goal_file: not established')) `
    -Said ('tree: exit ' + $c2e2T.exit + ' ' + $c2e2T.out.Trim())

# (3) ROUTE THREE: an eligible HANDOFF head with the artifact unwritable. The brief is recorded before the
#     artifact is written, so the first stop spends it; the same head then meets the unwritable artifact at
#     every later stop. The record is removed between the base's two stops and the tree's.
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJ3' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
New-Item -ItemType Directory -Path (Join-Path $c2eGoals 'G-WJ3.verdict.yaml') -Force | Out-Null
$c2eBrief = Write-EsBytes -Root $c2eRoot -Rel '.mission-runtime/lam/handoff/brief-wj3.md' -Bytes ($pwUtf8.GetBytes("a brief for route three`n"))
$c2eBriefSha = Get-PwRawSha -Path $c2eBrief
Write-EsStatus -Root $c2eRoot -Head (Get-EsHead -Ctx '80' -Lf $c2eBriefSha -Raw $c2eBriefSha -Path '.mission-runtime/lam/handoff/brief-wj3.md')
$c2eRec = Join-Path $c2eRoot '.mission-runtime\lam\handoff-admissions.jsonl'
$c2e3B1 = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ3' -Evaluator $c2eBase.path
$c2e3B2 = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ3' -Evaluator $c2eBase.path
$c2e3BRec = (Get-EsRecord -Root $c2eRoot).count
Remove-Item -LiteralPath $c2eRec -Force -ErrorAction SilentlyContinue
$c2e3T1 = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ3'
$c2e3T2 = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ3'
$c2e3TRec = (Get-EsRecord -Root $c2eRoot).count
Add-C2eRow -Label '(3) ROUTE THREE an eligible HANDOFF head, the artifact unwritable: RED at the base -- approve, exit 9 at the first stop AND at the next, one record line' `
    -Ok ((Test-C2eTrapped $c2e3B1) -and (Test-C2eTrapped $c2e3B2) -and ($c2e3BRec -eq 1)) -Said ('base: first exit ' + $c2e3B1.exit + ', second exit ' + $c2e3B2.exit + '; record lines ' + $c2e3BRec)
Add-C2eRow -Label '(3) ... GREEN: BLOCKED at the first stop, the reason naming the verdict it had derived (HANDOFF_ADMITTED), and BLOCKED at the next; one record line -- the brief is spent' `
    -Ok ((Test-C2eBlocked $c2e3T1 'G-WJ3' 'No verdict file was written: writing ') -and $c2e3T1.reason.Contains('The verdict this run had derived before the error: ' + $esHoVerdict + '.') -and
         (Test-C2eBlocked $c2e3T2 'G-WJ3' 'No verdict file was written: writing ') -and ($c2e3TRec -eq 1)) `
    -Said ('tree: first exit ' + $c2e3T1.exit + ' ' + $c2e3T1.decision + ', second exit ' + $c2e3T2.exit + ' ' + $c2e3T2.decision + '; record lines ' + $c2e3TRec)
Remove-Item -LiteralPath (Join-Path $c2eRoot '.mission-runtime\lam\STATUS.md') -Force
Remove-Item -LiteralPath $c2eRec -Force -ErrorAction SilentlyContinue

# (4) ROUTE FOUR: the verdict artifact held by another process with NO sharing -- what the hook that loses
#     the artifact's write to another hook meets. Over an UNMET goal and over a MET one: whatever the hook
#     had derived, the base lets the stop through. No member runs two hooks at once; this is the loser's side.
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJ4' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt')
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJ4M' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt')
foreach ($c2eG4 in @(@{ id = 'G-WJ4'; derived = 'NOT_MET' }, @{ id = 'G-WJ4M'; derived = 'MET' })) {
    $c2eVf4 = Join-Path $c2eGoals ($c2eG4.id + '.verdict.yaml')
    $c2eHeld = [System.IO.File]::Open($c2eVf4, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
    try {
        $c2e4B = Invoke-WjHook -Root $c2eRoot -GoalId $c2eG4.id -Evaluator $c2eBase.path
        $c2e4T = Invoke-WjHook -Root $c2eRoot -GoalId $c2eG4.id
    } finally { $c2eHeld.Dispose(); $c2eHeld = $null }
    Add-C2eRow -Label ('(4) ROUTE FOUR the artifact held with no sharing, the goal ' + $c2eG4.derived + ': RED at the base -- approve, exit 9, whatever it had derived') `
        -Ok (Test-C2eTrapped $c2e4B) -Said ('base: exit ' + $c2e4B.exit + ' ' + $c2e4B.out.Trim())
    Add-C2eRow -Label ('(4) ... GREEN: BLOCKED, exit 0, the reason naming the verdict it had derived (' + $c2eG4.derived + ') and that the artifact could not be written') `
        -Ok ((Test-C2eBlocked $c2e4T $c2eG4.id 'No verdict file was written: writing ') -and $c2e4T.reason.Contains('The verdict this run had derived before the error: ' + $c2eG4.derived + '.')) `
        -Said ('tree: exit ' + $c2e4T.exit + ' ' + $c2e4T.out.Trim())
}
$c2e4After = Invoke-WjHook -Root $c2eRoot -GoalId 'G-WJ4M'
Add-C2eRow -Label '(4) ... the artifact released, the met goal reads MET and approves, exit 0: the block lasts as long as its cause' `
    -Ok (($c2e4After.decision -ceq 'approve') -and ($c2e4After.exit -eq 0) -and ($c2e4After.verdict -ceq 'MET')) -Said ('exit ' + $c2e4After.exit + ' ' + $c2e4After.out.Trim())

# (c) SEVEN STOPS THAT ARE NOT ERRORS: the hook's decision, its reason and its exit are the base's, byte for
#     byte, and the artifact is the base's but for the two scanned-set keys.
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJM' -DetectorLines @('  - type: halt_absent', '  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJN' -DetectorLines @('  - type: halt_absent', '  - type: file_exists', '    path: evidence/absent.txt')
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJP' -DetectorLines @(('  - type: ' + $pwType), '  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJD' -DetectorLines @(('  - type: ' + $esManType), '  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c2eRoot -GoalId 'G-WJH' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
function Add-C2eControl {
    param([string]$What, [string]$GoalId, [string]$Verdict, [string]$Decision, [switch]$FreshRecord)
    $c2eCB = Invoke-EsEval -Root $c2eRoot -GoalId $GoalId -Hook -Evaluator $c2eBase.path
    if ($FreshRecord) { Remove-Item -LiteralPath $c2eRec -Force -ErrorAction SilentlyContinue }
    $c2eCT = Invoke-EsEval -Root $c2eRoot -GoalId $GoalId -Hook
    Add-C2eRow -Label ('(c) CONTROL ' + $What + ': ' + $Verdict + ', ' + $Decision + ' -- the hook''s stdout and exit the base''s, the artifact the base''s but for the two scanned-set keys') `
        -Ok (($c2eCT.verdict -ceq $Verdict) -and ($c2eCT.decision -ceq $Decision) -and ($c2eCT.exit -eq 0) -and ($c2eCT.exit -eq $c2eCB.exit) -and ((Remove-WqAdmittedSentence -Text $c2eCT.out).Trim() -ceq $c2eCB.out.Trim()) -and
             ((ConvertTo-WjComparable $c2eCT.text) -ceq (ConvertTo-WjComparable $c2eCB.text)) -and ($c2eCT.text -match '(?m)^halt_scan_roots:') -and (-not ($c2eCB.text -match '(?m)^halt_scan_roots:'))) `
        -Said ('tree ' + $c2eCT.verdict + '/' + $c2eCT.decision + '/' + $c2eCT.exit + ', base ' + $c2eCB.verdict + '/' + $c2eCB.decision + '/' + $c2eCB.exit)
}
Add-C2eControl -What 'a met goal' -GoalId 'G-WJM' -Verdict 'MET' -Decision 'approve'
Add-C2eControl -What 'an unmet goal' -GoalId 'G-WJN' -Verdict 'NOT_MET' -Decision 'block'
Write-Utf8 -Path (Join-Path $c2eRoot '.mission-runtime\halts\HALT-WJ.md') -Text "# HALT-WJ`n`n**Status:** OPEN`n"
Add-C2eControl -What 'an open HALT over the met goal' -GoalId 'G-WJM' -Verdict 'HALT' -Decision 'approve'
Remove-Item -LiteralPath (Join-Path $c2eRoot '.mission-runtime\halts') -Recurse -Force
Write-Utf8 -Path (Join-Path $c2eRoot '.mission\amendments\AM-900-wj.yaml') -Text "id: AM-900`nnote: placed, untracked, ungated`n"
Add-C2eControl -What 'an untracked, ungated amendment' -GoalId 'G-WJP' -Verdict $pwVerdict -Decision 'approve'
Remove-Item -LiteralPath (Join-Path $c2eRoot '.mission\amendments\AM-900-wj.yaml') -Force
Write-EsManifest -Root $c2eRoot -Rel '.mission/dispatches/D-WJ.manifest.yaml' -Id 'v-wj-r1'
Add-C2eControl -What 'an untracked, ungated round manifest' -GoalId 'G-WJD' -Verdict $esManVerdict -Decision 'approve'
Remove-Item -LiteralPath (Join-Path $c2eRoot '.mission\dispatches\D-WJ.manifest.yaml') -Force
$c2eBrief2 = Write-EsBytes -Root $c2eRoot -Rel '.mission-runtime/lam/handoff/brief-wjh.md' -Bytes ($pwUtf8.GetBytes("a brief for the control`n"))
$c2eBrief2Sha = Get-PwRawSha -Path $c2eBrief2
Write-EsStatus -Root $c2eRoot -Head (Get-EsHead -Ctx '70' -Lf $c2eBrief2Sha -Raw $c2eBrief2Sha -Path '.mission-runtime/lam/handoff/brief-wjh.md')
Add-C2eControl -What 'an eligible HANDOFF head, the record emptied between the two' -GoalId 'G-WJH' -Verdict $esHoVerdict -Decision 'approve' -FreshRecord
Remove-Item -LiteralPath (Join-Path $c2eRoot '.mission-runtime\lam\STATUS.md') -Force
Remove-Item -LiteralPath $c2eRec -Force -ErrorAction SilentlyContinue
Add-C2eControl -What 'a goal at no search location' -GoalId 'G-WJ-NONE' -Verdict $esAbsVerdict -Decision 'approve'
}
catch {
    $c2eOk = $false
    $c2eRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c2eRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c2eHeld) { try { $c2eHeld.Dispose() } catch { } }
if ($c2eDenied) { try { $null = Invoke-C4aIcacls @($c2eGoals2, '/remove:d', $c2eWho, '/C', '/Q'); $null = Invoke-C4aIcacls @($c2eGoal2, '/remove:d', $c2eWho, '/C', '/Q') } catch { } }
if ($null -ne $c2eM) { Remove-PwTreeAsWritten -Base $c2eM.base }
Check -Id 'C-2e' -Title 'THE TRAP FAILS CLOSED (the BATCH-3 charter, SS B (a)): an error before the verdict is written BLOCKS the stop -- decision block, exit 0, the form NOT_MET blocks in -- with the error as its reason, and writes a NOT_MET verdict carrying evaluator_error where it can; by hand the exit stays 9 and a third line names the verdict file. Driven over the four routes the row names and a fifth the page recorded, each RED at the base evaluator (approve, exit 9, "goal-check errored") and GREEN at this tree: an unparseable goal with a DIRECTORY at its verdict artifact (blocked; no file can be written and the reason says why); a goal file that cannot be stat''d (blocked; the verdict written at the canonical path); an eligible HANDOFF head with the artifact unwritable, at the first stop and at the next (blocked both times; the brief is spent, one record line); the artifact held by another process with no sharing, over an unmet goal and over a met one (blocked; the reason names the verdict the run had derived), and released, the met goal approves again; and a halt_absent dir the path resolver throws on (blocked; the verdict written and read back). Two more, above where the worker guard used to stand: with a library that does not load a dispatched worker is still approved, exit 0 -- the guard stands above every statement that can raise an error -- where the base evaluator ended in its trap, and anyone else is blocked, the verdict written at the canonical path; and a Stop payload whose transcript_path is a directory, the base''s trap, is no error at this tree -- a met goal with no turn_cap reads MET and one that declares turn_cap fails that entry. Controls: a dispatched worker is approved, exit 0, in the base''s own bytes; and seven stops that are not errors -- MET, NOT_MET, HALT, AWAITING_AMENDMENT_GATE, AWAITING_DISPATCH_GATE, HANDOFF_ADMITTED and GOAL_ABSENT -- print the base''s hook decision, reason and exit byte for byte (but for the one sentence BATCH-6 WP-Q adds to the NOT_MET block, held by C-1ba) and write the base''s artifact but for the two scanned-set keys' `
      -Ok $c2eOk -Detail ("      THE $(@($c2eRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c2eRows -join "`n"))

# =============================================================================================
# C-1ai -- THE REUSE OF A FRESH READING: instrument_exit0 reuses a capture only
#          where the goal file declares a window, and only when every condition holds
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: the base evaluator does
# not read reuse_within_minutes at all -- a goal declaring 30 over a capture one minute old runs the
# instrument again, and the base helper's capture carries no head to tie a reading to a tree.
# THE FIXTURE declares what the live repository declares: a committed .gitignore for the verdict artifact
# and the runtime plane, and .mission/mission.yaml admitting ONE untracked prefix, `?? scratch/`, where
# the instrument lives -- so its bytes can change with HEAD unmoved and the tree clean, and the
# instrument's blob is measured alone. The instrument appends one line to a counter each time it RUNS:
# "ran 0" is read off disk, not off the evaluator's word. A hand-run is the helper called by this
# instrument itself under another run key; its age is set by rewriting the capture's own captured_at.
$c1aiOk = $true
$c1aiRows = New-Object System.Collections.Generic.List[string]
function Add-C1aiRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1aiOk = $false }
    $script:c1aiRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1aiRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1aiRuns {
    $c1aiCounter = Join-Path $script:c1aiRoot '.mission-runtime\wj-ran.txt'
    if (-not (Test-Path -LiteralPath $c1aiCounter -PathType Leaf)) { return 0 }
    return @([System.IO.File]::ReadAllLines($c1aiCounter) | Where-Object { $_ }).Count
}
function Clear-C1aiCaptures {
    if (Test-Path -LiteralPath $script:c1aiRunsDir) { Get-ChildItem -LiteralPath $script:c1aiRunsDir -File | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force } }
}
function New-C1aiHandCapture {
    # A HAND-RUN through the shared helper as this instrument loaded it (the tree's), under run key -Key, every
    # other capture removed first; then the capture's own captured_at set -AgeMinutes into the past. Returns
    # the capture's path and the sha256 of its bytes as they then stand.
    # -Keep leaves the captures already there (two candidates at once); -InstrumentPath, -MissionRoot and
    # -Location drive the helper in another call shape -- a relative path from another tree is the runner's.
    param([double]$AgeMinutes = 1, [string]$Key = 'HAND', [switch]$Keep, [string]$InstrumentPath = '', [string]$MissionRoot = '', [string]$Location = '')
    if (-not $Keep) { Clear-C1aiCaptures }
    if (-not $InstrumentPath) { $InstrumentPath = $script:c1aiInst }
    if (-not $MissionRoot) { $MissionRoot = $script:c1aiRoot }
    $c1aiPrevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    if ($Location) { Push-Location -LiteralPath $Location }
    try { $c1aiHand = Save-LamInstrumentRun -InstrumentPath $InstrumentPath -MissionRoot $MissionRoot -RunKey $Key }
    finally { if ($Location) { Pop-Location }; $ErrorActionPreference = $c1aiPrevEap }
    $c1aiCapPath = [string]$c1aiHand.stdout_path
    $c1aiCapText = [System.IO.File]::ReadAllText($c1aiCapPath)
    $c1aiStamp = [DateTime]::UtcNow.AddMinutes(-1 * $AgeMinutes).ToString('o')
    $c1aiCapText = ([regex]'(?m)^captured_at: .*$').Replace($c1aiCapText, ('captured_at: ' + $c1aiStamp), 1)
    [System.IO.File]::WriteAllText($c1aiCapPath, $c1aiCapText, (New-Object System.Text.UTF8Encoding($false)))
    return [pscustomobject]@{ path = $c1aiCapPath; sha = (Get-PwRawSha -Path $c1aiCapPath); text = $c1aiCapText }
}
function Get-C1aiReading {
    # One hand evaluation of -GoalId: how many times the instrument RAN during it (the counter's delta), the
    # instrument_exit0 entry, and the instrument_captures_reused key.
    param([string]$GoalId, [string]$Evaluator)
    $c1aiBefore = Get-C1aiRuns
    $c1aiEv = if ($Evaluator) { Invoke-EsEval -Root $script:c1aiRoot -GoalId $GoalId -Evaluator $Evaluator } else { Invoke-EsEval -Root $script:c1aiRoot -GoalId $GoalId }
    $c1aiDet = Get-PwDetector -Text $c1aiEv.text -Type 'instrument_exit0'
    return [pscustomobject]@{ verdict = $c1aiEv.verdict; exit = $c1aiEv.exit; ran = ((Get-C1aiRuns) - $c1aiBefore); ok = $c1aiDet.ok; detail = [string]$c1aiDet.detail
                              reused = @(Get-PwListKey -Text $c1aiEv.text -Key 'instrument_captures_reused'); keyPresent = [bool]($c1aiEv.text -match '(?m)^instrument_captures_reused:') }
}
$c1aiM = $null
try {
$c1aiM = New-EsMission -Tag 'c1ai'
if (-not $c1aiM.ok) { throw ('FIXTURE REFUSED: ' + $c1aiM.why) }
$c1aiRoot = $c1aiM.root
$c1aiRunsDir = Join-Path $c1aiRoot '.mission-runtime\lam\instrument-runs'
$c1aiBase = New-WjBaseTools -Dir (Join-Path $c1aiM.base 'base-tools')
$c1aiInst = Join-Path $c1aiRoot 'scratch\inst.ps1'
$c1aiInstText = @'
$wjRt = Join-Path (Split-Path -Parent (Split-Path -Parent $PSCommandPath)) '.mission-runtime'
if (-not (Test-Path -LiteralPath $wjRt)) { New-Item -ItemType Directory -Path $wjRt -Force | Out-Null }
[System.IO.File]::AppendAllText((Join-Path $wjRt 'wj-ran.txt'), "ran`n")
$wjCode = 0
if (Test-Path -LiteralPath (Join-Path $wjRt 'wj-red.flag')) { $wjCode = 3 }
Write-Output ('the reuse fixture instrument ran; exit ' + $wjCode)
exit $wjCode
'@
Write-Utf8 -Path $c1aiInst -Text ($c1aiInstText -replace "`r", '')
Write-Utf8 -Path (Join-Path $c1aiRoot '.gitignore') -Text "/.mission/goals/*.verdict.yaml`n.mission-runtime/`n"
Write-Utf8 -Path (Join-Path $c1aiRoot '.mission\mission.yaml') -Text "id: wj-reuse-fixture`nadmitted_porcelain: [`"?? scratch/`"]`n"
$c1aiHead = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
Write-PwGoal -Root $c1aiRoot -GoalId 'G-RUA' -DetectorLines $c1aiHead
Write-PwGoal -Root $c1aiRoot -GoalId 'G-RU0' -DetectorLines ($c1aiHead + @('    reuse_within_minutes: 0'))
Write-PwGoal -Root $c1aiRoot -GoalId 'G-RU30' -DetectorLines ($c1aiHead + @('    reuse_within_minutes: 30'))
Write-PwGoal -Root $c1aiRoot -GoalId 'G-RUBAD' -DetectorLines ($c1aiHead + @('    reuse_within_minutes: soon'))
$c1aiAdd = Invoke-PwGit -Root $c1aiRoot -GitArgs @('add', '--', '.gitignore', '.mission/mission.yaml', '.mission/goals')
$c1aiCom = Invoke-PwGit -Root $c1aiRoot -GitArgs ($esCommitArgs + @('the reuse fixture'))
$c1aiPorc = (Invoke-PwGit -Root $c1aiRoot -GitArgs @('status', '--porcelain=v1')).text.Trim()
$c1aiHeadSha = (Invoke-PwGit -Root $c1aiRoot -GitArgs @('rev-parse', 'HEAD')).text.Trim()
Add-C1aiRow -Label ('FIXTURE a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/") and four goals committed; porcelain reads exactly "?? scratch/"') `
    -Ok ($c1aiBase.ok -and ($c1aiAdd.exit -eq 0) -and ($c1aiCom.exit -eq 0) -and ($c1aiPorc -ceq '?? scratch/') -and ($c1aiHeadSha -cmatch '\A[0-9a-f]{40}\z')) -Said ('HEAD ' + $c1aiHeadSha + '; porcelain [' + $c1aiPorc + ']; ' + $c1aiBase.said)

# (a)/(b) THE KEY ABSENT, AND THE KEY 0: always a fresh run, and the entry is the base's, byte for byte.
foreach ($c1aiG in @(@{ id = 'G-RUA'; what = 'the key ABSENT' }, @{ id = 'G-RU0'; what = 'reuse_within_minutes: 0' })) {
    Clear-C1aiCaptures
    $c1aiT1 = Get-C1aiReading -GoalId $c1aiG.id
    $c1aiT2 = Get-C1aiReading -GoalId $c1aiG.id
    $c1aiB1 = Get-C1aiReading -GoalId $c1aiG.id -Evaluator $c1aiBase.path
    Add-C1aiRow -Label ('(a/b) ' + $c1aiG.what + ': two evaluations at once RUN the instrument twice; the detail is the base''s byte for byte; no reuse key is written') `
        -Ok (($c1aiT1.ran -eq 1) -and ($c1aiT2.ran -eq 1) -and ($c1aiB1.ran -eq 1) -and ($c1aiT1.verdict -ceq 'MET') -and ($c1aiT2.detail -ceq $c1aiB1.detail) -and ($c1aiT1.detail -ceq $c1aiB1.detail) -and
             (-not $c1aiT2.detail.Contains('REUSED')) -and (-not $c1aiT2.keyPresent)) `
        -Said ('ran ' + $c1aiT1.ran + ', ' + $c1aiT2.ran + ', base ' + $c1aiB1.ran + '; detail: ' + $c1aiT2.detail)
}

# (c) THE WINDOW DECLARED, NO CAPTURE ON DISK: a fresh run, and the detail says why nothing was reused.
Clear-C1aiCaptures
$c1aiC = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(c) reuse_within_minutes: 30 with no capture on disk: the instrument RUNS, the detail says NOT reused and why, the key is written and empty' `
    -Ok (($c1aiC.ran -eq 1) -and ($c1aiC.verdict -ceq 'MET') -and $c1aiC.detail.Contains('reuse_within_minutes 30: NOT reused, the instrument was run (register row 368) -- no capture of this instrument is on disk') -and $c1aiC.keyPresent -and ($c1aiC.reused.Count -eq 0)) `
    -Said ('ran ' + $c1aiC.ran + '; detail: ' + $c1aiC.detail)
# (d) THE EVALUATOR'S OWN TEE IS A CANDIDATE: the capture (c) just wrote is reused by the next evaluation.
$c1aiOwn = Join-Path $c1aiRunsDir 'G-RU30.inst.stdout.txt'
$c1aiOwnSha = if (Test-Path -LiteralPath $c1aiOwn) { Get-PwRawSha -Path $c1aiOwn } else { '(absent)' }
$c1aiD = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(d) FALSIFIER the next evaluation, seconds later, same HEAD, clean tree, same instrument: REUSED -- the instrument does NOT run, MET, the capture named by path and by its sha256, in the detail and in the key' `
    -Ok (($c1aiD.ran -eq 0) -and ($c1aiD.verdict -ceq 'MET') -and $c1aiD.ok -and $c1aiD.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, the instrument was NOT run in this evaluation (register row 368; reuse_within_minutes 30): capture ' + $c1aiOwn + ' sha256 ' + $c1aiOwnSha + ', captured_at ') -and
         $c1aiD.detail.Contains(', HEAD ' + $c1aiHeadSha + ',') -and ($c1aiD.reused.Count -eq 1) -and ($c1aiD.reused[0] -ceq ($c1aiOwn + ' sha256 ' + $c1aiOwnSha))) `
    -Said ('ran ' + $c1aiD.ran + '; detail: ' + $c1aiD.detail)
# (e) THE RED, KEPT: the base evaluator over the same goal and the same capture runs the instrument.
$c1aiE = Get-C1aiReading -GoalId 'G-RU30' -Evaluator $c1aiBase.path
Add-C1aiRow -Label '(e) RED at the base, over the same goal and capture: the instrument RUNS -- the base does not read the key -- and nothing is named' `
    -Ok ($c1aiBase.ok -and ($c1aiE.ran -eq 1) -and (-not $c1aiE.detail.Contains('REUSED')) -and (-not $c1aiE.keyPresent)) -Said ('base ran ' + $c1aiE.ran + '; detail: ' + $c1aiE.detail)
# (f) ... AND THE CAPTURE THE BASE HELPER JUST WROTE CARRIES NO head: it is never reused.
$c1aiF = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(f) the capture the BASE helper just wrote carries no head: it is NOT reused, the instrument runs, and the detail says why' `
    -Ok (($c1aiF.ran -eq 1) -and $c1aiF.detail.Contains('it carries no head: (it was written before register row 368)')) -Said ('ran ' + $c1aiF.ran + '; detail: ' + $c1aiF.detail)

# (g) A HAND-RUN CAPTURE IS A CANDIDATE TOO, and its own header says what it was taken on.
$c1aiHand = New-C1aiHandCapture -AgeMinutes 1
$c1aiInstSha = Get-PwRawSha -Path $c1aiInst
$c1aiG1 = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(g) FALSIFIER a HAND-RUN under another run key, 1 minute old: its header carries head, tree_clean: True and the instrument''s sha256; REUSED, the instrument does not run, the hand capture named with its sha256' `
    -Ok (($c1aiHand.text -match ('(?m)^head: ' + $c1aiHeadSha + '$')) -and ($c1aiHand.text -match '(?m)^tree_clean: True$') -and ($c1aiHand.text -match ('(?m)^instrument_sha256: ' + $c1aiInstSha + '$')) -and ($c1aiHand.text -match '(?m)^capture_format: 1$') -and
         ($c1aiG1.ran -eq 0) -and $c1aiG1.detail.Contains('capture ' + $c1aiHand.path + ' sha256 ' + $c1aiHand.sha + ',') -and $c1aiHand.path.EndsWith('HAND.inst.stdout.txt')) `
    -Said ('ran ' + $c1aiG1.ran + '; detail: ' + $c1aiG1.detail)
# (h) THE WINDOW: 29 minutes old is inside it, 31 is outside it, and a captured_at in the future is refused.
foreach ($c1aiAge in @(@{ m = 29; ran = 0; say = 'REUSED A FRESH READING' }, @{ m = 31; ran = 1; say = 'it is 31 minute(s) old, outside the window' }, @{ m = -5; ran = 1; say = 'its captured_at is in the future' })) {
    $null = New-C1aiHandCapture -AgeMinutes $c1aiAge.m
    $c1aiH = Get-C1aiReading -GoalId 'G-RU30'
    Add-C1aiRow -Label ('(h) the capture ' + $c1aiAge.m + ' minute(s) old against a window of 30: the instrument ran ' + $c1aiAge.ran + ' time(s) -- ' + $c1aiAge.say) `
        -Ok (($c1aiH.ran -eq $c1aiAge.ran) -and $c1aiH.detail.Contains($c1aiAge.say)) -Said ('ran ' + $c1aiH.ran + '; detail: ' + $c1aiH.detail)
}
# (i) A RED READING. Once it was "REUSED AS RED": a capture of a RED run inside the window
#     was handed back as RED -- "exited 3 (require 0). REUSED A FRESH READING", the instrument not run -- for
#     as long as the window lasted, ok being the capture's exit code and never "reused therefore passing".
#     NOW A RED IS NEVER REUSED (the operator's ruling): the capture chosen
#     is read for its exit code before anything is kept, and one that did not exit 0 is RE-MEASURED. The row
#     is re-asserted to the rule. The instrument is still flagged red at the reading, so the re-measurement
#     exits 3 too and the entry still FAILS: what tells it from the reuse is the counter (the instrument
#     RAN), the detail's opening (a fresh run's, not "REUSED") and the rule's own sentence, naming the capture.
#     WHERE THE RED IS KEPT: not here. This member's pinned base predates the window altogether --
#     it reads no reuse_within_minutes and always runs the instrument (row (e)) -- so it cannot show a RED
#     reused as RED; that is the evaluator after the window and before the rule, and C-1aq keeps it as its control
#     (its rows (a), (b) and (d) BASE CONTROL), beside the falsifier this row re-asserts.
Write-Utf8 -Path (Join-Path $c1aiRoot '.mission-runtime\wj-red.flag') -Text "red`n"
$c1aiIHand = New-C1aiHandCapture -AgeMinutes 1
$c1aiI = Get-C1aiReading -GoalId 'G-RU30'
Remove-Item -LiteralPath (Join-Path $c1aiRoot '.mission-runtime\wj-red.flag') -Force
Add-C1aiRow -Label '(i) a capture of a RED run (exit 3), 1 minute old: it is NOT reused -- the instrument RUNS (still flagged red: "exited 3 (require 0). Instrument output", NOT_MET, exit 1), the detail naming the capture by file name and sha256 and saying "a reading that is not exit 0 is never reused, it is re-measured."; the key written and empty' `
    -Ok (($c1aiI.ran -eq 1) -and (-not $c1aiI.ok) -and ($c1aiI.verdict -ceq 'NOT_MET') -and ($c1aiI.exit -eq 1) -and $c1aiI.detail.StartsWith('inst.ps1 exited 3 (require 0). Instrument output ') -and (-not $c1aiI.detail.Contains('REUSED')) -and
         $c1aiI.detail.Contains(' reuse_within_minutes 30: NOT reused, the instrument was run (register row 368) -- the newest capture that passes, HAND.inst.stdout.txt sha256 ' + $c1aiIHand.sha + ', exited 3: a reading that is not exit 0 is never reused, it is re-measured (register row 412).') -and
         $c1aiI.keyPresent -and ($c1aiI.reused.Count -eq 0)) -Said ('ran ' + $c1aiI.ran + '; verdict ' + $c1aiI.verdict + '; detail: ' + $c1aiI.detail)

# (j) THE INSTRUMENT'S BLOB CHANGED, HEAD unmoved and the tree clean (the instrument is under the declared set).
$null = New-C1aiHandCapture -AgeMinutes 1
Write-Utf8 -Path $c1aiInst -Text (($c1aiInstText -replace "`r", '') + "# one more line`n")
$c1aiJ = Get-C1aiReading -GoalId 'G-RU30'
Write-Utf8 -Path $c1aiInst -Text ($c1aiInstText -replace "`r", '')
Add-C1aiRow -Label '(j) the instrument''s bytes changed since the capture, HEAD unmoved, the tree clean: NOT reused, the instrument runs, the detail says its bytes are not the bytes it ran' `
    -Ok (($c1aiJ.ran -eq 1) -and $c1aiJ.detail.Contains('the instrument''s bytes are not the bytes it ran (instrument_sha256 differs)')) -Said ('ran ' + $c1aiJ.ran + '; detail: ' + $c1aiJ.detail)
# (k) THE TREE, NOW: a tracked file modified; an untracked file OUTSIDE the declared set; one INSIDE it.
$c1aiTracked = Join-Path $c1aiRoot 'evidence\built.txt'
$null = New-C1aiHandCapture -AgeMinutes 1
Write-Utf8 -Path $c1aiTracked -Text "built, and edited`n"
$c1aiK1 = Get-C1aiReading -GoalId 'G-RU30'
Write-Utf8 -Path $c1aiTracked -Text "built`n"
Add-C1aiRow -Label '(k) a TRACKED file modified since the capture: NOT reused, the instrument runs, the detail quoting verify''s own predicate (UNCOMMITTED DRIFT)' `
    -Ok (($c1aiK1.ran -eq 1) -and $c1aiK1.detail.Contains('the tree is not clean apart from the mission''s declared set, by verify''s own predicate (UNCOMMITTED DRIFT')) -Said ('ran ' + $c1aiK1.ran + '; detail: ' + $c1aiK1.detail)
$null = New-C1aiHandCapture -AgeMinutes 1
Write-Utf8 -Path (Join-Path $c1aiRoot 'stray.txt') -Text "untracked, outside the declared set`n"
$c1aiK2 = Get-C1aiReading -GoalId 'G-RU30'
Remove-Item -LiteralPath (Join-Path $c1aiRoot 'stray.txt') -Force
Add-C1aiRow -Label '(k) an UNTRACKED file outside the declared set: NOT reused, the instrument runs' `
    -Ok (($c1aiK2.ran -eq 1) -and $c1aiK2.detail.Contains('by verify''s own predicate (UNCOMMITTED DRIFT')) -Said ('ran ' + $c1aiK2.ran + '; detail: ' + $c1aiK2.detail)
$null = New-C1aiHandCapture -AgeMinutes 1
Write-Utf8 -Path (Join-Path $c1aiRoot 'scratch\note.txt') -Text "untracked, inside the declared set`n"
$c1aiK3 = Get-C1aiReading -GoalId 'G-RU30'
Remove-Item -LiteralPath (Join-Path $c1aiRoot 'scratch\note.txt') -Force
Add-C1aiRow -Label '(k) CONTROL an untracked file INSIDE the declared set (scratch/): the tree is clean apart from it -- REUSED, the instrument does not run' `
    -Ok (($c1aiK3.ran -eq 0) -and $c1aiK3.detail.Contains('REUSED A FRESH READING')) -Said ('ran ' + $c1aiK3.ran)
# (l) THE TREE, WHEN IT WAS TAKEN: a capture taken over an edit that was then reverted is not a reading of this tree.
Write-Utf8 -Path $c1aiTracked -Text "built, and edited`n"
$c1aiL0 = New-C1aiHandCapture -AgeMinutes 1
Write-Utf8 -Path $c1aiTracked -Text "built`n"
$c1aiL = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(l) a capture taken while a tracked file was edited (its header: tree_clean: False), the edit then reverted: HEAD equal and the tree clean NOW, yet NOT reused' `
    -Ok (($c1aiL0.text -match '(?m)^tree_clean: False$') -and ($c1aiL.ran -eq 1) -and $c1aiL.detail.Contains('the tree was not clean, or not read, when it was taken (tree_clean: False)')) -Said ('ran ' + $c1aiL.ran + '; detail: ' + $c1aiL.detail)
# (m) A CAPTURE WHOSE BODY WAS EDITED does not hash to its own body_sha256.
$c1aiM0 = New-C1aiHandCapture -AgeMinutes 1
[System.IO.File]::WriteAllText($c1aiM0.path, $c1aiM0.text.Replace('the reuse fixture instrument ran; exit 0', 'the reuse fixture instrument RAN; exit 0'), (New-Object System.Text.UTF8Encoding($false)))
$c1aiMm = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(m) a capture whose body was edited after it was written: NOT reused -- its body does not hash to its own body_sha256 -- the instrument runs' `
    -Ok (($c1aiMm.ran -eq 1) -and $c1aiMm.detail.Contains('its body does not hash to its own body_sha256')) -Said ('ran ' + $c1aiMm.ran + '; detail: ' + $c1aiMm.detail)
# (n) A KEY THAT IS NOT A NUMBER. Once it was "read as 0, and says so": the instrument ran
#     over a capture that would have passed, the window dropped, and the only word of it stood in the detail
#     of an entry that passed. NOW THE GOAL DOES NOT PARSE: NOT_MET, one goal_parse entry naming the
#     key, its line and the value, and NO detector run -- the instrument included. The row is re-asserted to
#     the rule; C-1al drives it against the base evaluator, with the other three numeric keys.
$null = New-C1aiHandCapture -AgeMinutes 1
$c1aiNBefore = Get-C1aiRuns
$c1aiNEv = Invoke-EsEval -Root $c1aiRoot -GoalId 'G-RUBAD'
$c1aiNRan = (Get-C1aiRuns) - $c1aiNBefore
$c1aiNParse = Get-PwDetector -Text $c1aiNEv.text -Type 'goal_parse'
Add-C1aiRow -Label '(n) reuse_within_minutes: soon -- not a whole number: the goal DOES NOT PARSE -- NOT_MET, exit 1, a goal_parse entry naming line 5, the key and the value -- and the instrument is NOT run over a capture that would have passed; no instrument_exit0 entry, no reuse key' `
    -Ok (($c1aiNRan -eq 0) -and ($c1aiNEv.verdict -ceq 'NOT_MET') -and ($c1aiNEv.exit -eq 1) -and $c1aiNParse.found -and
         $c1aiNParse.detail.Contains("line 5: reuse_within_minutes: 'soon' is not a whole number from 0 to 999999 (instrument_exit0 reads it as a number)") -and $c1aiNParse.detail.Contains('(register row 385)') -and
         (-not (Get-PwDetector -Text $c1aiNEv.text -Type 'instrument_exit0').found) -and (-not ($c1aiNEv.text -match '(?m)^instrument_captures_reused:'))) `
    -Said ('ran ' + $c1aiNRan + '; verdict ' + $c1aiNEv.verdict + ', exit ' + $c1aiNEv.exit + '; goal_parse: ' + $c1aiNParse.detail)
# (p) A CAPTURE OF ANOTHER TREE, in the runner's own call shape: the helper called from ANOTHER tree's location
#     with a RELATIVE instrument path and THIS mission root -- so the capture lands under this root's
#     instrument-runs, states this root's HEAD and clean tree, and carries the sha256 of an instrument whose
#     bytes equal this root's. It ran over the other tree. It is not reused: instrument_resolved names the file
#     that ran, and that is not this detector's.
$c1aiOther = Join-Path $c1aiM.base 'other-tree'
Write-Utf8 -Path (Join-Path $c1aiOther 'scratch\inst.ps1') -Text ($c1aiInstText -replace "`r", '')
$c1aiP0 = New-C1aiHandCapture -AgeMinutes 1 -Key 'D-RUNNER' -InstrumentPath 'scratch\inst.ps1' -Location $c1aiOther
$c1aiP = Get-C1aiReading -GoalId 'G-RU30'
$c1aiOtherInst = Join-Path $c1aiOther 'scratch\inst.ps1'
Add-C1aiRow -Label '(p) FALSIFIER the runner''s shape -- a relative path run from ANOTHER tree against this mission root: the capture states this root''s head, tree_clean: True and equal instrument bytes, and is NOT reused; it names the file that ran' `
    -Ok (($c1aiP0.text -match ('(?m)^head: ' + $c1aiHeadSha + '$')) -and ($c1aiP0.text -match '(?m)^tree_clean: True$') -and ($c1aiP0.text -match ('(?m)^instrument_sha256: ' + $c1aiInstSha + '$')) -and
         $c1aiP0.text.Contains("`ninstrument_resolved: " + $c1aiOtherInst + "`n") -and ($c1aiP.ran -eq 1) -and $c1aiP.detail.Contains('it is a capture of ' + $c1aiOtherInst + ', not of this detector''s instrument')) `
    -Said ('ran ' + $c1aiP.ran + '; detail: ' + $c1aiP.detail)
# (q) TWO CANDIDATES AT ONCE: the one with the LATEST captured_at is the one CHOSEN. In the earlier evaluator
#     it was then reused "red or green": of an older GREEN and a newer RED the RED was handed back -- "exited
#     3 (require 0). REUSED", NOT_MET, the instrument not run. NOW THE FIRST HALF IS RE-ASSERTED TO
#     THE RULE: the newer RED is still the capture chosen, it is NOT reused, and the older GREEN behind it is
#     NOT fallen back on -- the instrument RUNS (the flag is gone by then, so it reads exit 0: MET). The
#     second half stands as it was: a newer GREEN is reused, and the RED before it stops nothing. The RED of
#     the first half is kept where row (i)'s is: C-1aq row (b) BASE CONTROL.
$null = New-C1aiHandCapture -AgeMinutes 10 -Key 'OLDER'
Write-Utf8 -Path (Join-Path $c1aiRoot '.mission-runtime\wj-red.flag') -Text "red`n"
$c1aiQNewer = New-C1aiHandCapture -AgeMinutes 1 -Key 'NEWER' -Keep
Remove-Item -LiteralPath (Join-Path $c1aiRoot '.mission-runtime\wj-red.flag') -Force
$c1aiQ1 = Get-C1aiReading -GoalId 'G-RU30'
Write-Utf8 -Path (Join-Path $c1aiRoot '.mission-runtime\wj-red.flag') -Text "red`n"
$null = New-C1aiHandCapture -AgeMinutes 10 -Key 'OLDER'
Remove-Item -LiteralPath (Join-Path $c1aiRoot '.mission-runtime\wj-red.flag') -Force
$null = New-C1aiHandCapture -AgeMinutes 1 -Key 'NEWER' -Keep
$c1aiQ2 = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(q) two passing captures at once: an older GREEN and a newer RED -> the RED, the newest that passes, is NOT reused and the older GREEN is not fallen back on: the instrument RUNS, MET by the re-measurement, the detail naming NEWER and "a reading that is not exit 0 is never reused"; an older RED and a newer GREEN -> the GREEN is reused (MET), the instrument not run' `
    -Ok (($c1aiQ1.ran -eq 1) -and ($c1aiQ1.verdict -ceq 'MET') -and $c1aiQ1.detail.StartsWith('inst.ps1 exited 0 (require 0). Instrument output ') -and (-not $c1aiQ1.detail.Contains('REUSED')) -and
         $c1aiQ1.detail.Contains('the newest capture that passes, NEWER.inst.stdout.txt sha256 ' + $c1aiQNewer.sha + ', exited 3: a reading that is not exit 0 is never reused, it is re-measured (register row 412).') -and
         (-not $c1aiQ1.detail.Contains('OLDER.inst.stdout.txt')) -and $c1aiQ1.keyPresent -and ($c1aiQ1.reused.Count -eq 0) -and
         ($c1aiQ2.ran -eq 0) -and ($c1aiQ2.verdict -ceq 'MET') -and $c1aiQ2.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED') -and $c1aiQ2.detail.Contains('NEWER.inst.stdout.txt') -and (-not $c1aiQ2.detail.Contains('register row 412'))) `
    -Said ('first: ran ' + $c1aiQ1.ran + ' ' + $c1aiQ1.verdict + '; second: ran ' + $c1aiQ2.ran + ' ' + $c1aiQ2.verdict + '; the first''s detail: ' + $c1aiQ1.detail)
# (r) NOT A WHOLE CAPTURE: `ran: False`; and the closing line cut off the end of the file.
$c1aiR0 = New-C1aiHandCapture -AgeMinutes 1
[System.IO.File]::WriteAllText($c1aiR0.path, ([regex]'(?m)^ran: True$').Replace($c1aiR0.text, 'ran: False', 1), (New-Object System.Text.UTF8Encoding($false)))
$c1aiR1 = Get-C1aiReading -GoalId 'G-RU30'
$c1aiR2 = New-C1aiHandCapture -AgeMinutes 1
[System.IO.File]::WriteAllText($c1aiR2.path, $c1aiR2.text.Substring(0, $c1aiR2.text.Length - "--- end of instrument output ---`n".Length), (New-Object System.Text.UTF8Encoding($false)))
$c1aiR3 = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(r) a capture whose header reads ran: False, and one whose closing line is cut off: neither is reused, the instrument runs, each detail says which' `
    -Ok (($c1aiR1.ran -eq 1) -and $c1aiR1.detail.Contains('the instrument did not run to completion (ran is not True)') -and ($c1aiR3.ran -eq 1) -and $c1aiR3.detail.Contains('the closing line does not end the file')) `
    -Said ('ran ' + $c1aiR1.ran + ', ' + $c1aiR3.ran + '; ' + $c1aiR3.detail)
# (s) AS THE STOP HOOK: the reuse decides the hook's decision too, and the instrument still does not run.
$null = New-C1aiHandCapture -AgeMinutes 1
$c1aiSBefore = Get-C1aiRuns
$c1aiS = Invoke-EsEval -Root $c1aiRoot -GoalId 'G-RU30' -Hook
$c1aiSRan = (Get-C1aiRuns) - $c1aiSBefore
Add-C1aiRow -Label '(s) as the Stop hook over a 1-minute-old capture: approve, exit 0, MET on disk, the instrument NOT run, the artifact''s entry naming the capture reused' `
    -Ok ($c1aiS.admitted -and ($c1aiS.verdict -ceq 'MET') -and ($c1aiSRan -eq 0) -and $c1aiS.reason.Contains('is MET on disk') -and (Get-PwDetector -Text $c1aiS.text -Type 'instrument_exit0').detail.Contains('REUSED A FRESH READING')) `
    -Said ('ran ' + $c1aiSRan + '; ' + $c1aiS.out.Trim())
# (t) A MISSION ROOT THAT IS NOT A REPOSITORY'S TOP LEVEL: a plain directory inside this fixture's repository.
#     git would answer for the ENCLOSING repository; the helper refuses to read a HEAD for it, and says so.
$c1aiSub = Join-Path $c1aiRoot 'scratch\sub-root'
New-Item -ItemType Directory -Path $c1aiSub -Force | Out-Null
$c1aiT0 = New-C1aiHandCapture -AgeMinutes 1 -Key 'SUB' -MissionRoot $c1aiSub -Keep
Add-C1aiRow -Label '(t) the helper at a mission root that is a plain directory INSIDE a repository: head is not derivable -- "not the top level of a git repository" -- and tree_clean is not read; the enclosing repository is not asked' `
    -Ok (($c1aiT0.text -match '(?m)^head: not derivable \(the mission root is not the top level of a git repository') -and ($c1aiT0.text -match '(?m)^tree_clean: not derivable$') -and $c1aiT0.path.StartsWith($c1aiSub, [System.StringComparison]::OrdinalIgnoreCase)) `
    -Said ('capture ' + $c1aiT0.path)
Remove-Item -LiteralPath $c1aiSub -Recurse -Force

# (o) HEAD MOVED: one empty commit, the tree clean, the instrument unchanged. LAST, because HEAD stays moved.
$null = New-C1aiHandCapture -AgeMinutes 1
$c1aiMove = Invoke-PwGit -Root $c1aiRoot -GitArgs @('-c', 'user.name=wp3-es', '-c', 'user.email=wp3-es@example.invalid', '-c', 'commit.gpgsign=false', 'commit', '--quiet', '--allow-empty', '-m', 'HEAD moves')
$c1aiHeadNew = (Invoke-PwGit -Root $c1aiRoot -GitArgs @('rev-parse', 'HEAD')).text.Trim()
$c1aiO = Get-C1aiReading -GoalId 'G-RU30'
Add-C1aiRow -Label '(o) HEAD MOVED since the capture (one empty commit; the tree clean, the instrument unchanged): NOT reused, the instrument runs, the detail naming both heads' `
    -Ok (($c1aiMove.exit -eq 0) -and ($c1aiHeadNew -cne $c1aiHeadSha) -and ($c1aiO.ran -eq 1) -and $c1aiO.detail.Contains('its head is ' + $c1aiHeadSha + ', and HEAD is ' + $c1aiHeadNew)) -Said ('ran ' + $c1aiO.ran + '; detail: ' + $c1aiO.detail)
}
catch {
    $c1aiOk = $false
    $c1aiRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1aiRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1aiM) { Remove-PwTreeAsWritten -Base $c1aiM.base }
Check -Id 'C-1ai' -Title 'THE REUSE OF A FRESH READING (the BATCH-3 charter, SS B (b)): an instrument_exit0 detector with reuse_within_minutes ABSENT or 0 always runs its instrument and writes the entry the base evaluator writes, byte for byte, with no reuse key; with reuse_within_minutes 30 a capture of the same instrument is REUSED -- the instrument is not run, read off a counter the instrument itself appends to -- when its own head is HEAD, the tree is clean apart from the mission''s declared set now (verify''s own predicate, Test-LamAdvanceAdmission) and was when it was taken (its own tree_clean), the instrument''s sha256 is unchanged and its own captured_at is inside the window; the verdict names the capture by path and by the sha256 of its bytes, in the entry''s detail and in the key instrument_captures_reused; the evaluator''s own capture of the evaluation before and a hand-run under another run key are both reused; a red reading is NOT reused -- it is re-measured: the instrument runs and the detail names the capture and says so (it was once reused as red; C-1aq keeps that as its control); and the instrument RUNS, the detail saying why, when HEAD has moved, a tracked file is modified, an untracked file sits outside the declared set (one inside it does not prevent reuse), the instrument''s bytes changed with HEAD unmoved and the tree clean, the capture is 31 minutes old or dated in the future (29 is inside the window), the tree was edited when the capture was taken and reverted since, the capture''s body no longer hashes to its own body_sha256, the capture was written by the base helper and carries no head, or no capture is on disk; a key that is not a whole number is no longer "read as 0" -- that goal does not parse, NOT_MET with a goal_parse entry naming the key, its line and the value, and the instrument is not run (C-1al drives it against the base); a capture taken in the runner''s own call shape -- a relative instrument path run from ANOTHER tree against this mission root, stating this root''s head, a clean tree and equal instrument bytes -- is NOT reused, because it names the file that ran; of two passing captures the one with the latest captured_at is the one chosen -- a newer GREEN is reused, and a newer RED is not: the instrument runs, and the older GREEN behind it is not fallen back on; a capture reading ran: False, or cut short of its closing line, is not reused; as the Stop hook the decision follows the reuse and the instrument still does not run; at a mission root that is a plain directory inside a repository the helper reads no HEAD and says why; and the base evaluator, kept as the control, runs the instrument where this tree reuses' `
      -Ok $c1aiOk -Detail ("      THE $(@($c1aiRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1aiRows -join "`n"))

# =============================================================================================
# C-3h -- THE HALT SCAN STATES ITS ROOTS AND EXCLUDES BY RULE: a fixture under a
#         nested mission root and the scratch-copies tree are not counted; everything else still is
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: the incident's own shape
# -- two validator fixtures, HALT-R-1.md and HALT-R.md, each in the .mission-runtime\halts
# of a fixture mission root left under the live root's .mission-runtime\lam\close\ -- reads HALT, and no
# line of the verdict says which roots were scanned. THE CONTROLS, each counted by this tree as before:
# a real HALT in .mission-runtime\halts; halts\archive\HALT-95.md, a plain subdirectory; a directory
# carrying only .mission-runtime\ and no .mission\; a FILE named .mission; and a .mission directory planted
# IN a scan root, which hides nothing -- a scan root is never a nested root.
$c3hOk = $true
$c3hRows = New-Object System.Collections.Generic.List[string]
function Add-C3hRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c3hOk = $false }
    $script:c3hRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c3hRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C3hReading {
    # One hand evaluation: verdict, exit, the open_halts names (a bare or a quoted entry's leading file name),
    # and the two scanned-set keys with whether each is written at all.
    param([string]$GoalId, [string]$Evaluator)
    $c3hEv = if ($Evaluator) { Invoke-EsEval -Root $script:c3hRoot -GoalId $GoalId -Evaluator $Evaluator } else { Invoke-EsEval -Root $script:c3hRoot -GoalId $GoalId }
    $c3hOpen = @([regex]::Matches($c3hEv.text, '(?m)^open_halts:\r?\n((?:  - .*\r?\n)*)') | ForEach-Object { $_.Groups[1].Value -split "`r?`n" } | Where-Object { $_ } | ForEach-Object { ($_ -replace '^  - ''?', '') -replace '[ ''].*$', '' })
    $c3hOpenSorted = [string[]]@($c3hOpen)
    [System.Array]::Sort($c3hOpenSorted, [System.StringComparer]::Ordinal)
    return [pscustomobject]@{ verdict = $c3hEv.verdict; exit = $c3hEv.exit; text = $c3hEv.text; open = @($c3hOpenSorted)
                              roots = @(Get-PwListKey -Text $c3hEv.text -Key 'halt_scan_roots'); excluded = @(Get-PwListKey -Text $c3hEv.text -Key 'halt_scan_excluded')
                              rootsKey = [bool]($c3hEv.text -match '(?m)^halt_scan_roots:'); excludedKey = [bool]($c3hEv.text -match '(?m)^halt_scan_excluded:')
                              haltDetail = [string](Get-PwDetector -Text $c3hEv.text -Type 'halt_absent').detail }
}
$c3hM = $null
try {
$c3hM = New-EsMission -Tag 'c3h'
if (-not $c3hM.ok) { throw ('FIXTURE REFUSED: ' + $c3hM.why) }
$c3hRoot = $c3hM.root
$c3hBase = New-WjBaseTools -Dir (Join-Path $c3hM.base 'base-tools')
$c3hHalts = Join-Path $c3hRoot '.mission-runtime\halts'
$c3hLam = Join-Path $c3hRoot '.mission-runtime\lam'
New-Item -ItemType Directory -Path $c3hHalts -Force | Out-Null
New-Item -ItemType Directory -Path $c3hLam -Force | Out-Null
Write-PwGoal -Root $c3hRoot -GoalId 'G-HS' -DetectorLines @('  - type: halt_absent', '  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c3hRoot -GoalId 'G-HSD' -DetectorLines @('  - type: halt_absent', '    dir: .mission-runtime', '  - type: file_exists', '    path: evidence/built.txt')
Write-PwGoal -Root $c3hRoot -GoalId 'G-HSN' -DetectorLines @('  - type: halt_absent', '  - type: file_exists', '    path: evidence/absent.txt')
$c3hOpenText = "# a HALT`n`n**Status:** OPEN`n"
# THE SPELLING THE VERDICT USES for every root and every excluded place: the full path (GetFullPath), so
# what this member expects does not turn on how %TEMP% happens to be spelled on the machine it runs on.
$c3hHaltsShown = [System.IO.Path]::GetFullPath($c3hHalts)
$c3hLamShown = [System.IO.Path]::GetFullPath($c3hLam)

# (a) THE SCANNED SET IS STATED, ON EVERY EVALUATION: nothing on disk to find, and the verdict still says where it looked.
$c3hA = Get-C3hReading -GoalId 'G-HS'
$c3hAB = Get-C3hReading -GoalId 'G-HS' -Evaluator $c3hBase.path
$c3hAD = Get-C3hReading -GoalId 'G-HSD'
$c3hAN = Get-C3hReading -GoalId 'G-HSN'
$c3hAA = Invoke-EsEval -Root $c3hRoot -GoalId 'G-HS-NONE'
Add-C3hRow -Label '(a) FALSIFIER a met goal, no HALT anywhere: halt_scan_roots names the two default planes, halt_scan_excluded is written and empty; RED at the base -- neither key' `
    -Ok ($c3hBase.ok -and ($c3hA.verdict -ceq 'MET') -and ($c3hA.roots.Count -eq 2) -and ($c3hA.roots[0] -ceq $c3hHaltsShown) -and ($c3hA.roots[1] -ceq $c3hLamShown) -and $c3hA.excludedKey -and ($c3hA.excluded.Count -eq 0) -and
         ($c3hAB.verdict -ceq 'MET') -and (-not $c3hAB.rootsKey) -and (-not $c3hAB.excludedKey)) `
    -Said ('tree roots [' + ($c3hA.roots -join ' ; ') + ']; base keys: ' + $c3hAB.rootsKey + ', ' + $c3hAB.excludedKey)
Add-C3hRow -Label '(a) ... a goal declaring dir: .mission-runtime adds it as a third root; an UNMET goal states the set too; an ABSENT goal writes halt_scan_roots: [] -- no scan runs' `
    -Ok (($c3hAD.roots.Count -eq 3) -and ($c3hAD.roots[2] -ceq [System.IO.Path]::GetFullPath((Join-Path $c3hRoot '.mission-runtime'))) -and ($c3hAN.verdict -ceq 'NOT_MET') -and ($c3hAN.roots.Count -eq 2) -and
         ($c3hAA.verdict -ceq $esAbsVerdict) -and ($c3hAA.text -match '(?m)^halt_scan_roots: \[\]') -and ($c3hAA.text -match '(?m)^halt_scan_excluded: \[\]')) `
    -Said ('declared: [' + ($c3hAD.roots -join ' ; ') + ']; unmet: ' + $c3hAN.verdict + ', ' + $c3hAN.roots.Count + ' root(s); absent: ' + $c3hAA.verdict)
Remove-Item -LiteralPath $c3hHalts -Recurse -Force
$c3hA2 = Get-C3hReading -GoalId 'G-HS'
New-Item -ItemType Directory -Path $c3hHalts -Force | Out-Null
Add-C3hRow -Label '(a) ... a default plane that is not on disk is named and said to be absent, never dropped from the list' `
    -Ok (($c3hA2.roots.Count -eq 2) -and ($c3hA2.roots[0] -ceq ($c3hHaltsShown + ' -- NOT ON DISK')) -and ($c3hA2.roots[1] -ceq $c3hLamShown)) -Said ('roots [' + ($c3hA2.roots -join ' ; ') + ']')

# (b) THE INCIDENT'S SHAPE: two fixture HALTs, each in the .mission-runtime\halts of a NESTED mission root
#     (it carries its own .mission\) under the live root's .mission-runtime\lam\close\.
$c3hN1 = [System.IO.Path]::GetFullPath((Join-Path $c3hLam 'close\batch2-scratch\wph\validator\round-1\fx\d1-8a4bc420\m'))
$c3hN2 = [System.IO.Path]::GetFullPath((Join-Path $c3hLam 'close\batch2-scratch\wph\validator\round-2\fx\regress\m'))
New-Item -ItemType Directory -Path (Join-Path $c3hN1 '.mission\goals') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $c3hN2 '.mission\goals') -Force | Out-Null
Write-Utf8 -Path (Join-Path $c3hN1 '.mission-runtime\halts\HALT-R-1.md') -Text $c3hOpenText
Write-Utf8 -Path (Join-Path $c3hN2 '.mission-runtime\halts\HALT-R.md') -Text $c3hOpenText
$c3hBB = Get-C3hReading -GoalId 'G-HS' -Evaluator $c3hBase.path
$c3hBT = Get-C3hReading -GoalId 'G-HS'
$c3hBTH = Invoke-EsEval -Root $c3hRoot -GoalId 'G-HS' -Hook
$c3hBBH = Invoke-EsEval -Root $c3hRoot -GoalId 'G-HS' -Hook -Evaluator $c3hBase.path
Add-C3hRow -Label '(b) FALSIFIER the incident''s shape, two fixture HALTs under nested mission roots below .mission-runtime\lam\close\: RED at the base -- HALT, exit 3, both counted, the hook approving on a HALT' `
    -Ok (($c3hBB.verdict -ceq 'HALT') -and ($c3hBB.exit -eq 3) -and (($c3hBB.open -join '|') -ceq 'HALT-R-1.md|HALT-R.md') -and $c3hBBH.reason.Contains('derives HALT')) -Said ('base ' + $c3hBB.verdict + '/' + $c3hBB.exit + ' open [' + ($c3hBB.open -join ', ') + ']')
Add-C3hRow -Label '(b) ... GREEN: NOT COUNTED -- MET, exit 0, open_halts empty; halt_scan_excluded names each nested root with 1 file; the halt_absent detail says so; the hook reads MET on disk' `
    -Ok (($c3hBT.verdict -ceq 'MET') -and ($c3hBT.exit -eq 0) -and ($c3hBT.open.Count -eq 0) -and ($c3hBT.excluded.Count -eq 2) -and
         ($c3hBT.excluded[0] -ceq ($c3hN1 + ' -- a nested mission root (it carries its own .mission\): 1 file(s) matching HALT-* under it NOT COUNTED by rule (register row 363)')) -and
         ($c3hBT.excluded[1] -ceq ($c3hN2 + ' -- a nested mission root (it carries its own .mission\): 1 file(s) matching HALT-* under it NOT COUNTED by rule (register row 363)')) -and
         $c3hBT.haltDetail.StartsWith('0 unanswered HALT artifact(s) [] -- 2 place(s) under the scanned roots NOT COUNTED by rule [') -and $c3hBTH.admitted -and $c3hBTH.reason.Contains('is MET on disk')) `
    -Said ('tree ' + $c3hBT.verdict + '/' + $c3hBT.exit + '; excluded [' + ($c3hBT.excluded -join ' ; ') + ']')

# (c) THE SCRATCH-COPIES TREE: a HALT under .mission-runtime\scratch-copies\, reached by a goal that declares
#     dir: .mission-runtime. Under the two default planes nothing reaches it at all.
$c3hScratch = [System.IO.Path]::GetFullPath((Join-Path $c3hRoot '.mission-runtime\scratch-copies'))
Write-Utf8 -Path (Join-Path $c3hScratch 'batch2\wph\HALT-S.md') -Text $c3hOpenText
$c3hCB = Get-C3hReading -GoalId 'G-HSD' -Evaluator $c3hBase.path
$c3hCT = Get-C3hReading -GoalId 'G-HSD'
Add-C3hRow -Label '(c) FALSIFIER a HALT under .mission-runtime\scratch-copies\ with a goal declaring dir: .mission-runtime: RED at the base -- HALT, the scratch copy and both fixtures counted' `
    -Ok (($c3hCB.verdict -ceq 'HALT') -and ($c3hCB.open -contains 'HALT-S.md') -and ($c3hCB.open -contains 'HALT-R.md') -and ($c3hCB.open -contains 'HALT-R-1.md')) -Said ('base ' + $c3hCB.verdict + ' open [' + ($c3hCB.open -join ', ') + ']')
Add-C3hRow -Label '(c) ... GREEN: MET; halt_scan_excluded names the scratch-copies tree with 1 file beside the two nested roots; three roots stated' `
    -Ok (($c3hCT.verdict -ceq 'MET') -and ($c3hCT.open.Count -eq 0) -and ($c3hCT.roots.Count -eq 3) -and ($c3hCT.excluded.Count -eq 3) -and
         ($c3hCT.excluded -ccontains ($c3hScratch + ' -- the scratch-copies tree: 1 file(s) matching HALT-* under it NOT COUNTED by rule (register row 363)'))) `
    -Said ('tree ' + $c3hCT.verdict + '; excluded [' + ($c3hCT.excluded -join ' ; ') + ']')

# (d) A REAL HALT IS STILL A HALT, beside all of them.
Write-Utf8 -Path (Join-Path $c3hHalts 'HALT-REAL.md') -Text $c3hOpenText
$c3hDT = Get-C3hReading -GoalId 'G-HS'
Add-C3hRow -Label '(d) CONTROL a real HALT in .mission-runtime\halts beside them: HALT, exit 3, open_halts exactly HALT-REAL.md, the two nested roots still named' `
    -Ok (($c3hDT.verdict -ceq 'HALT') -and ($c3hDT.exit -eq 3) -and (($c3hDT.open -join '|') -ceq 'HALT-REAL.md') -and ($c3hDT.excluded.Count -eq 2)) -Said ('open [' + ($c3hDT.open -join ', ') + ']')

# (e) WHAT THE RULE DOES NOT REACH: each of these is counted.
Write-Utf8 -Path (Join-Path $c3hHalts 'archive\HALT-95.md') -Text $c3hOpenText
Write-Utf8 -Path (Join-Path $c3hLam 'onlyrt\.mission-runtime\halts\HALT-ONLYRT.md') -Text $c3hOpenText
Write-Utf8 -Path (Join-Path $c3hLam 'filemark\.mission') -Text "a FILE named .mission, not a directory`n"
Write-Utf8 -Path (Join-Path $c3hLam 'filemark\HALT-FILEMARK.md') -Text $c3hOpenText
New-Item -ItemType Directory -Path (Join-Path $c3hHalts '.mission') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $c3hLam '.mission') -Force | Out-Null
$c3hET = Get-C3hReading -GoalId 'G-HS'
Add-C3hRow -Label '(e) CONTROL counted, all four, as before: halts\archive\HALT-95.md (a plain subdirectory); a HALT under a directory carrying only .mission-runtime\; one beside a FILE named .mission; and HALT-REAL.md with a .mission DIRECTORY planted in each scan root' `
    -Ok (($c3hET.verdict -ceq 'HALT') -and (($c3hET.open -join '|') -ceq 'HALT-95.md|HALT-FILEMARK.md|HALT-ONLYRT.md|HALT-REAL.md') -and ($c3hET.excluded.Count -eq 2)) `
    -Said ('open [' + ($c3hET.open -join ', ') + ']; excluded ' + $c3hET.excluded.Count)
# ... AND THE DETECTOR AGREES WITH THE VERDICT where a declared dir stands ABOVE a scan root that carries a
#     planted .mission: no scan root of the run is ever called a nested root, under whichever root a file is reached.
$c3hED = Get-C3hReading -GoalId 'G-HSD'
Add-C3hRow -Label '(e) ... a goal declaring dir: .mission-runtime over the same disk: the detector''s own count still holds HALT-REAL.md -- the default plane with a planted .mission is not called a nested root -- and the verdict is HALT' `
    -Ok (($c3hED.verdict -ceq 'HALT') -and ($c3hED.open -contains 'HALT-REAL.md') -and $c3hED.haltDetail.Contains('HALT-REAL.md') -and (-not $c3hED.haltDetail.Contains($c3hHaltsShown + ' -- a nested mission root')) -and (-not ($c3hED.excluded -join ' ; ').Contains($c3hHaltsShown + ' -- '))) `
    -Said ('detail: ' + $c3hED.haltDetail)

# (f) A DECLARED DIR OUTSIDE THE MISSION ROOT is outside the rule: a directory there that carries .mission\ is
#     another mission's, not a fixture nested in this one, and its HALT is counted.
$c3hOut = Join-Path $c3hM.base 'outside'
New-Item -ItemType Directory -Path (Join-Path $c3hOut 'w1\.mission\goals') -Force | Out-Null
Write-Utf8 -Path (Join-Path $c3hOut 'w1\.mission-runtime\halts\HALT-OUT.md') -Text $c3hOpenText
Write-PwGoal -Root $c3hRoot -GoalId 'G-HSO' -DetectorLines @('  - type: halt_absent', ('    dir: ' + $c3hOut), '  - type: file_exists', '    path: evidence/built.txt')
$c3hF = Get-C3hReading -GoalId 'G-HSO'
Add-C3hRow -Label '(f) CONTROL a goal declaring a dir OUTSIDE the mission root, a directory there carrying .mission\: its HALT is COUNTED and nothing outside is named excluded -- the rule is about roots nested in this one' `
    -Ok (($c3hF.verdict -ceq 'HALT') -and ($c3hF.open -contains 'HALT-OUT.md') -and (-not ($c3hF.excluded -join ' ; ').Contains([System.IO.Path]::GetFullPath($c3hOut)))) -Said ('open [' + ($c3hF.open -join ', ') + ']')
# (g) A DECLARED DIR THAT IS ITSELF THE NESTED ROOT: a goal that names it has it scanned -- a scan root is never
#     a nested root -- while the other nested root stays excluded.
Write-PwGoal -Root $c3hRoot -GoalId 'G-HSX' -DetectorLines @('  - type: halt_absent', ('    dir: ' + $c3hN1), '  - type: file_exists', '    path: evidence/built.txt')
$c3hG = Get-C3hReading -GoalId 'G-HSX'
Add-C3hRow -Label '(g) CONTROL a goal declaring the first nested root itself as its dir: HALT-R-1.md is COUNTED and that root is not named excluded; the second nested root still is, HALT-R.md not counted' `
    -Ok (($c3hG.open -contains 'HALT-R-1.md') -and (-not ($c3hG.open -contains 'HALT-R.md')) -and (-not ($c3hG.excluded -join ' ; ').Contains($c3hN1 + ' -- ')) -and ($c3hG.excluded -join ' ; ').Contains($c3hN2 + ' -- a nested mission root')) `
    -Said ('open [' + ($c3hG.open -join ', ') + ']; excluded [' + ($c3hG.excluded -join ' ; ') + ']')
# (h) A DECLARED DIR INSIDE THE SCRATCH-COPIES TREE is still not counted: that clause is about the place.
Write-PwGoal -Root $c3hRoot -GoalId 'G-HSS' -DetectorLines @('  - type: halt_absent', '    dir: .mission-runtime/scratch-copies/batch2', '  - type: file_exists', '    path: evidence/built.txt')
$c3hH = Get-C3hReading -GoalId 'G-HSS'
Add-C3hRow -Label '(h) a goal declaring a dir INSIDE .mission-runtime\scratch-copies: HALT-S.md is still NOT counted, the tree named in halt_scan_excluded, the declared dir listed among the roots' `
    -Ok ((-not ($c3hH.open -contains 'HALT-S.md')) -and ($c3hH.excluded -ccontains ($c3hScratch + ' -- the scratch-copies tree: 1 file(s) matching HALT-* under it NOT COUNTED by rule (register row 363)')) -and ($c3hH.roots.Count -eq 3) -and ($c3hH.roots[2] -ceq ($c3hScratch + '\batch2'))) `
    -Said ('open [' + ($c3hH.open -join ', ') + ']; roots [' + ($c3hH.roots -join ' ; ') + ']')
# (i) TWO DIRECTORIES WHOSE NAMES A CULTURE-AWARE COMPARISON CALLS EQUAL: `strasse`, a nested root, and beside it
#     the same word spelled with a sharp s (built at run time; this file is ASCII), a PLAIN directory holding a
#     real HALT. They are two directories, and the plain one is counted.
$c3hSharp = 'stra' + [string][char]0xDF + 'e'
New-Item -ItemType Directory -Path (Join-Path $c3hLam 'strasse\.mission') -Force | Out-Null
Write-Utf8 -Path (Join-Path $c3hLam 'strasse\HALT-FX.md') -Text $c3hOpenText
Write-Utf8 -Path (Join-Path $c3hLam ($c3hSharp + '\HALT-SHARP.md')) -Text $c3hOpenText
$c3hI = Get-C3hReading -GoalId 'G-HS'
Add-C3hRow -Label '(i) CONTROL a plain directory whose name is culture-equal to a nested root''s (sharp s beside ss): its HALT-SHARP.md is COUNTED; the nested root''s HALT-FX.md is not, and that root is named' `
    -Ok (($c3hI.open -contains 'HALT-SHARP.md') -and (-not ($c3hI.open -contains 'HALT-FX.md')) -and ($c3hI.excluded -ccontains ($c3hLamShown + '\strasse -- a nested mission root (it carries its own .mission\): 1 file(s) matching HALT-* under it NOT COUNTED by rule (register row 363)'))) `
    -Said ('open [' + ($c3hI.open -join ', ') + ']')
}
catch {
    $c3hOk = $false
    $c3hRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c3hRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c3hM) { Remove-PwTreeAsWritten -Base $c3hM.base }
Check -Id 'C-3h' -Title 'THE HALT SCAN STATES ITS ROOTS AND EXCLUDES BY RULE (the BATCH-3 charter (c)): every verdict artifact carries halt_scan_roots -- the roots the C-3 scan read, the two default planes and each declared dir, one that is not on disk said to be absent -- and halt_scan_excluded, on a met, an unmet and a HALT verdict alike, and an absent goal writes both empty because no scan runs; the incident''s own shape -- two fixture HALTs, each in the .mission-runtime\halts of a nested mission root (a directory strictly below a scanned root that carries its own .mission\) left under .mission-runtime\lam\close\ -- reads HALT at the base evaluator and is NOT COUNTED at this tree: MET, exit 0, each nested root named in halt_scan_excluded with its file count and in the halt_absent detail; a HALT under .mission-runtime\scratch-copies\, reached through a declared dir, is counted at the base and not counted here, the tree named; and still counted, as before: a real HALT in .mission-runtime\halts beside them, halts\archive\HALT-95.md, a HALT under a directory carrying only .mission-runtime\, one beside a FILE named .mission, and every HALT of a scan root in which a .mission directory was planted -- there the halt_absent detector of a goal declaring a dir above that root and the verdict agree; a HALT under a declared dir OUTSIDE the mission root is counted, a .mission beside it notwithstanding; a goal that declares a nested root itself as its dir has it scanned; a declared dir inside the scratch-copies tree is still not counted; and a plain directory whose name a culture-aware comparison calls equal to a nested root''s (sharp s beside ss) is counted' `
      -Ok $c3hOk -Detail ("      THE $(@($c3hRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c3hRows -join "`n"))

# =============================================================================================
# C-1aj -- THE ADMISSIONS RECORD IS NEVER A BRIEF: a HANDOFF head that
#          names the arm's own record is refused, under every name the record has
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a head naming
# .mission-runtime/lam/handoff-admissions.jsonl with the record's own digests is ADMITTED, the admission
# appends to the record, and the head rewritten to the record's new digests is admitted AGAIN -- a stop
# at every stop with no brief written. A HARD LINK to the record is the same
# file under another name, and the base admits it too. THE CONTROLS: an ordinary brief still admits once;
# a COPY of the record at another path is another file and is a brief like any other, once.
$c1ajOk = $true
$c1ajRows = New-Object System.Collections.Generic.List[string]
function Add-C1ajRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1ajOk = $false }
    $script:c1ajRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1ajRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Set-C1ajHead {
    # STATUS.md's head naming -PathAsWritten, both digests the sha256 of -Target's bytes as they stand now.
    param([string]$PathAsWritten, [string]$Target)
    $c1ajSha = Get-PwRawSha -Path $Target
    Write-EsStatus -Root $script:c1ajRoot -Head (Get-EsHead -Ctx '60' -Lf $c1ajSha -Raw $c1ajSha -Path $PathAsWritten)
}
$c1ajM = $null
$c1ajHeld = $null
try {
$c1ajM = New-EsMission -Tag 'c1aj'
if (-not $c1ajM.ok) { throw ('FIXTURE REFUSED: ' + $c1ajM.why) }
$c1ajRoot = $c1ajM.root
$c1ajBase = New-WjBaseTools -Dir (Join-Path $c1ajM.base 'base-tools')
$c1ajRecRel = '.mission-runtime/lam/handoff-admissions.jsonl'
$c1ajRec = Join-Path $c1ajRoot '.mission-runtime\lam\handoff-admissions.jsonl'
Write-PwGoal -Root $c1ajRoot -GoalId 'G-HOR' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))

# (a) CONTROL, AND THE FIXTURE'S RECORD: an ordinary brief is admitted once, as before -- one record line.
$c1ajBriefA = Write-EsBytes -Root $c1ajRoot -Rel '.mission-runtime/lam/handoff/brief-a.md' -Bytes ($pwUtf8.GetBytes("an ordinary brief`n"))
Set-C1ajHead -PathAsWritten '.mission-runtime/lam/handoff/brief-a.md' -Target $c1ajBriefA
$c1ajA1 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
$c1ajA2 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
Add-C1ajRow -Label '(a) CONTROL an ordinary brief: ADMITTED once (HANDOFF_ADMITTED, approve, exit 0), then refused as already admitted; the record at 1 line' `
    -Ok ($c1ajBase.ok -and $c1ajA1.admitted -and ($c1ajA1.verdict -ceq $esHoVerdict) -and ($c1ajA2.decision -ceq 'block') -and $c1ajA2.reason.Contains('already admitted') -and ((Get-EsRecord -Root $c1ajRoot).count -eq 1)) `
    -Said ('first ' + $c1ajA1.verdict + '/' + $c1ajA1.decision + ', second ' + $c1ajA2.verdict + '/' + $c1ajA2.decision + '; ' + $c1ajBase.said)

# (b) THE FALSIFIER, AT THE BASE: the record named as the brief is admitted, and admitted again.
Set-C1ajHead -PathAsWritten $c1ajRecRel -Target $c1ajRec
$c1ajB1 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook -Evaluator $c1ajBase.path
$c1ajB1N = (Get-EsRecord -Root $c1ajRoot).count
Set-C1ajHead -PathAsWritten $c1ajRecRel -Target $c1ajRec
$c1ajB2 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook -Evaluator $c1ajBase.path
$c1ajB2N = (Get-EsRecord -Root $c1ajRoot).count
Add-C1ajRow -Label '(b) RED at the base: a head naming the admissions record, its digests the record''s own, is ADMITTED; rewritten to the record''s new digests it is ADMITTED AGAIN -- the record at 2, then 3 lines, no brief written' `
    -Ok ($c1ajB1.admitted -and ($c1ajB1.verdict -ceq $esHoVerdict) -and ($c1ajB1N -eq 2) -and $c1ajB2.admitted -and ($c1ajB2.verdict -ceq $esHoVerdict) -and ($c1ajB2N -eq 3)) `
    -Said ('base: ' + $c1ajB1.verdict + ' (' + $c1ajB1N + ' lines), ' + $c1ajB2.verdict + ' (' + $c1ajB2N + ' lines)')
# ... AND A HARD LINK TO THE RECORD, at the base: the same file under another name.
$c1ajLink = Join-Path $c1ajRoot 'evidence\record-link.jsonl'
$null = New-Item -ItemType HardLink -Path $c1ajLink -Target $c1ajRec
Set-C1ajHead -PathAsWritten 'evidence/record-link.jsonl' -Target $c1ajLink
$c1ajB3 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook -Evaluator $c1ajBase.path
$c1ajB3N = (Get-EsRecord -Root $c1ajRoot).count
Add-C1ajRow -Label '(b) ... RED at the base: a HARD LINK to the record named as the brief is ADMITTED too -- 4 lines' `
    -Ok ($c1ajB3.admitted -and ($c1ajB3.verdict -ceq $esHoVerdict) -and ($c1ajB3N -eq 4)) -Said ('base: ' + $c1ajB3.verdict + ' (' + $c1ajB3N + ' lines)')

# (c) GREEN: the record under each of its names is REFUSED by this tree, and the record does not move.
$c1ajSpellings = @(
    [pscustomobject]@{ label = 'its relative path, as the arm writes it'; path = $c1ajRecRel; say = 'its path is the record''s own' },
    [pscustomobject]@{ label = 'its ABSOLUTE path'; path = $c1ajRec; say = 'its path is the record''s own' },
    [pscustomobject]@{ label = 'backslashes and UPPER CASE'; path = '.MISSION-RUNTIME\LAM\HANDOFF-ADMISSIONS.JSONL'; say = 'its path is the record''s own' },
    [pscustomobject]@{ label = 'a dot-segment path'; path = '.mission-runtime/lam/handoff/../handoff-admissions.jsonl'; say = 'its path is the record''s own' },
    [pscustomobject]@{ label = 'a HARD LINK to it'; path = 'evidence/record-link.jsonl'; say = 'so it is the record under another name' },
    [pscustomobject]@{ label = 'a directory JUNCTION in its path'; path = 'evidence/lam-link/handoff-admissions.jsonl'; say = 'so it is the record under another name' })
$c1ajJunction = Join-Path $c1ajRoot 'evidence\lam-link'
$null = New-Item -ItemType Junction -Path $c1ajJunction -Target (Join-Path $c1ajRoot '.mission-runtime\lam')
foreach ($c1ajSp in $c1ajSpellings) {
    $c1ajTarget = if ($c1ajSp.path -ceq 'evidence/record-link.jsonl') { $c1ajLink } else { $c1ajRec }
    Set-C1ajHead -PathAsWritten $c1ajSp.path -Target $c1ajTarget
    $c1ajC = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
    Add-C1ajRow -Label ('(c) FALSIFIER the record named as the brief by ' + $c1ajSp.label + ': REFUSED -- the hook blocks, NOT_MET, the reason and handoff_refused saying the record is never a brief; the record still at 4 lines') `
        -Ok (($c1ajC.decision -ceq 'block') -and ($c1ajC.exit -eq 0) -and ($c1ajC.verdict -ceq 'NOT_MET') -and $c1ajC.reason.Contains('HANDOFF head NOT admitted -- the head names the admissions record itself as the brief (') -and
             $c1ajC.reason.Contains($c1ajSp.say) -and $c1ajC.reason.Contains('it is never a brief (register row 360 member (1))') -and (@($c1ajC.refused).Count -eq 1) -and
             ([string]@($c1ajC.refused)[0]).Contains('it is never a brief (register row 360 member (1))') -and ((Get-EsRecord -Root $c1ajRoot).count -eq 4)) `
        -Said ('decision ' + $c1ajC.decision + '; reason: ' + $c1ajC.reason)
}
[System.IO.Directory]::Delete($c1ajJunction)

# (c) ... AND WHAT IS NOT THE RECORD IS NOT CALLED IT: an ordinary brief that ANOTHER process holds with no
#     sharing, while a record exists. The arm's hold is not what stops the open, so the brief is not the
#     record; it cannot be read, and it is refused in those words, as before.
$c1ajBriefH = Write-EsBytes -Root $c1ajRoot -Rel '.mission-runtime/lam/handoff/brief-held.md' -Bytes ($pwUtf8.GetBytes("a brief another process holds`n"))
Set-C1ajHead -PathAsWritten '.mission-runtime/lam/handoff/brief-held.md' -Target $c1ajBriefH
$c1ajHeld = [System.IO.File]::Open($c1ajBriefH, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try { $c1ajCH = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook } finally { $c1ajHeld.Dispose(); $c1ajHeld = $null }
Add-C1ajRow -Label '(c) CONTROL an ordinary brief held by ANOTHER process with no sharing: refused because the brief could not be read -- NOT as "the admissions record itself"; 4 lines' `
    -Ok (($c1ajCH.decision -ceq 'block') -and $c1ajCH.reason.Contains('HANDOFF head NOT admitted -- the brief at ') -and $c1ajCH.reason.Contains('could not be read (') -and (-not $c1ajCH.reason.Contains('the admissions record itself')) -and ((Get-EsRecord -Root $c1ajRoot).count -eq 4)) `
    -Said ('reason: ' + $c1ajCH.reason)

# (d) CONTROL: a COPY of the record at another path is another file -- a brief like any other, admitted once.
$c1ajCopy = Write-EsBytes -Root $c1ajRoot -Rel 'evidence/record-copy.jsonl' -Bytes ([System.IO.File]::ReadAllBytes($c1ajRec))
Set-C1ajHead -PathAsWritten 'evidence/record-copy.jsonl' -Target $c1ajCopy
$c1ajD1 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
$c1ajD2 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
Add-C1ajRow -Label '(d) CONTROL a COPY of the record at another path: another file, a brief like any other -- ADMITTED once (5 lines), then refused as already admitted' `
    -Ok ($c1ajD1.admitted -and ($c1ajD1.verdict -ceq $esHoVerdict) -and ($c1ajD2.decision -ceq 'block') -and $c1ajD2.reason.Contains('already admitted') -and ((Get-EsRecord -Root $c1ajRoot).count -eq 5)) `
    -Said ('first ' + $c1ajD1.verdict + ', second ' + $c1ajD2.decision)

# (e) WHAT CANNOT BE ESTABLISHED REFUSES: the record held open by another process (sharing allowed), a NEW
#     ordinary brief at the head -- the arm cannot hold the record alone, so it cannot say the brief is not
#     the record, and it refuses; released, the same head is admitted.
$c1ajBriefB = Write-EsBytes -Root $c1ajRoot -Rel '.mission-runtime/lam/handoff/brief-b.md' -Bytes ($pwUtf8.GetBytes("a second ordinary brief`n"))
Set-C1ajHead -PathAsWritten '.mission-runtime/lam/handoff/brief-b.md' -Target $c1ajBriefB
$c1ajHeld = [System.IO.File]::Open($c1ajRec, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
try { $c1ajE1 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook } finally { $c1ajHeld.Dispose(); $c1ajHeld = $null }
$c1ajE1N = (Get-EsRecord -Root $c1ajRoot).count
$c1ajE2 = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
Add-C1ajRow -Label '(e) the record held open by another process while a new ordinary brief stands at the head: REFUSED -- it could not be established that the brief is not the record -- 5 lines; released, the same head is ADMITTED, 6 lines' `
    -Ok (($c1ajE1.decision -ceq 'block') -and $c1ajE1.reason.Contains('is the admissions record itself could not be established') -and ($c1ajE1N -eq 5) -and $c1ajE2.admitted -and ((Get-EsRecord -Root $c1ajRoot).count -eq 6)) `
    -Said ('held: ' + $c1ajE1.decision + ' -- ' + $c1ajE1.reason + ' | released: ' + $c1ajE2.verdict)

# (f) NO RECORD ON DISK: a head naming it names no file, as before.
Remove-Item -LiteralPath $c1ajLink -Force
Remove-Item -LiteralPath $c1ajRec -Force
Write-EsStatus -Root $c1ajRoot -Head (Get-EsHead -Ctx '60' -Lf ('0' * 64) -Raw ('0' * 64) -Path $c1ajRecRel)
$c1ajF = Invoke-EsEval -Root $c1ajRoot -GoalId 'G-HOR' -Hook
Add-C1ajRow -Label '(f) CONTROL no record on disk, the head naming its path: refused as before -- no file at the path -- and no record is made' `
    -Ok (($c1ajF.decision -ceq 'block') -and $c1ajF.reason.Contains('HANDOFF head NOT admitted -- no file at') -and (-not (Test-Path -LiteralPath $c1ajRec))) -Said ('reason: ' + $c1ajF.reason)
}
catch {
    $c1ajOk = $false
    $c1ajRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1ajRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1ajHeld) { try { $c1ajHeld.Dispose() } catch { } }
if ($null -ne $c1ajM) { Remove-PwTreeAsWritten -Base $c1ajM.base }
Check -Id 'C-1aj' -Title 'THE ADMISSIONS RECORD IS NEVER A BRIEF (the BATCH-3 charter (d)): a HANDOFF head naming the handoff arm''s own admissions record as its brief, with the record''s own digests, is ADMITTED by the base evaluator and admitted AGAIN once the head carries the record''s new digests -- a stop at every stop, no brief written -- and a hard link to the record is admitted too; this tree REFUSES it under every name driven -- its relative path, its absolute path, backslashes and upper case, a dot-segment path (each by name), a hard link and a directory junction in its path (each by identity: the brief cannot be opened while the record is held with no sharing, and opens once the record is released) -- the hook blocking, the reason and handoff_refused saying the record is never a brief, the record not moving; an ordinary brief that ANOTHER process holds with no sharing is refused as unreadable and is not called the record; a COPY of the record at another path is another file and is admitted once like any brief; an ordinary brief is admitted once as before; while another process holds the record the arm cannot establish that a brief is not the record and refuses, and admits the same head once the record is released; and with no record on disk a head naming its path is refused as naming no file' `
      -Ok $c1ajOk -Detail ("      THE $(@($c1ajRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1ajRows -join "`n"))

# =============================================================================================
# C-1ak -- THE HELPER'S TALLY PARSER LEARNS THE INSTRUMENTS' COUNT LINE; and the
#          plane row over C-2e..C-1ak
# =============================================================================================
# THE HELPER'S MEMBERS live in two instruments: WP-2's R-38a and R-47 (the runner's side, and the helper
# driven alone in a child PowerShell) and this instrument's C-1j and C-1k (the evaluator's side). This
# member sits here, beside C-1j's NO-TALLY row, and drives the helper as R-47 does: a child PowerShell
# dot-sources ONE helper file -- this tree's, or the base's (pinned) -- and calls
# Save-LamInstrumentRun over a stub that prints the lines given and exits as told.
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a stdout carrying the instruments'
# own count line and no TALLY leaves a tally file whose first line is NO-TALLY exit_code=<n>.
# THE FORMS ARE THE INSTRUMENTS', READ FROM THEIR CODE: row (i) lifts every count-line literal out of the
# six instruments' own source, renders it, and requires the parser to read each one -- so an instrument
# that rewords its line fails this member rather than going quietly back to NO-TALLY.
$c1akOk = $true
$c1akRows = New-Object System.Collections.Generic.List[string]
function Add-C1akRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1akOk = $false }
    $script:c1akRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1akRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
$c1akSeq = 0
function Invoke-C1akRun {
    # One run of ONE helper file over a stub printing -Lines (Write-Host, as the instruments print) and
    # exiting -Exit. Returns the driver's JSON (fields of the return object), the tally file's lines, and
    # the stdout capture's text.
    param([string]$Helper, [string[]]$Lines, [int]$Exit, [string]$Tag)
    $script:c1akSeq++
    $c1akStub = Join-Path $script:c1akBase ('stub-' + $script:c1akSeq + '.ps1')
    $c1akStubText = ((@($Lines) | ForEach-Object { "Write-Host '" + ([string]$_).Replace("'", "''") + "'" }) -join "`n") + "`nexit " + $Exit + "`n"
    Write-Utf8 -Path $c1akStub -Text $c1akStubText
    $c1akKey = $Tag + '-' + $script:c1akSeq
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $c1akO = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:c1akDriver -Helper $Helper -Stub $c1akStub -Root $script:c1akRoot -Key $c1akKey 2>&1 }
    finally { $ErrorActionPreference = $prevEap }
    $c1akJson = $null
    foreach ($c1akLn in @($c1akO | ForEach-Object { [string]$_ })) {
        if ($c1akLn.StartsWith('WJ-JSON ')) { try { $c1akJson = $c1akLn.Substring(8) | ConvertFrom-Json } catch { $c1akJson = $null } }
    }
    $c1akTallyPath = Join-Path $script:c1akRoot ('.mission-runtime\lam\instrument-runs\' + $c1akKey + '.stub-' + $script:c1akSeq + '.tally.txt')
    $c1akStdoutPath = Join-Path $script:c1akRoot ('.mission-runtime\lam\instrument-runs\' + $c1akKey + '.stub-' + $script:c1akSeq + '.stdout.txt')
    $c1akTally = if (Test-Path -LiteralPath $c1akTallyPath -PathType Leaf) { @([System.IO.File]::ReadAllText($c1akTallyPath).TrimEnd("`n") -split "`n") } else { @() }
    $c1akStdout = if (Test-Path -LiteralPath $c1akStdoutPath -PathType Leaf) { [System.IO.File]::ReadAllText($c1akStdoutPath) } else { '' }
    return [pscustomobject]@{ json = $c1akJson; tally = @($c1akTally); stdout = $c1akStdout; stub = $c1akStub
                              exitLast = (($c1akTally.Count -gt 0) -and ([string]$c1akTally[$c1akTally.Count - 1] -cmatch '^EXIT exit_code=(-?\d+) ran=(True|False) tally_count=(\d+) captured_at=(\S+)$')) }
}
$c1akBase = Join-Path $env:TEMP ('lam-wp3-c1ak-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
try {
$c1akRoot = Join-Path $c1akBase 'm'
New-Item -ItemType Directory -Path $c1akRoot -Force | Out-Null
$c1akTools = New-WjBaseTools -Dir (Join-Path $c1akBase 'base-tools')
$c1akTree = Join-Path $repoRoot 'tools\lam\lam-instrument-run.ps1'
$c1akDriver = Join-Path $c1akBase 'driver.ps1'
$c1akDriverText = @'
param([string]$Helper, [string]$Stub, [string]$Root, [string]$Key, [string]$Location = '', [string]$ProcessCwd = '')
. $Helper
if ($ProcessCwd) { [Environment]::CurrentDirectory = $ProcessCwd }
if ($Location) { Set-Location -LiteralPath $Location }
$r = Save-LamInstrumentRun -InstrumentPath $Stub -MissionRoot $Root -RunKey $Key
$names = @($r.PSObject.Properties.Name)
$o = [ordered]@{
    exit_code = $r.exit_code; lastexit = $LASTEXITCODE; persisted = $r.persisted; tally_found = $r.tally_found; tally_line = $r.tally_line
    tally_count = $r.tally_count; passed = [string]$r.fields['passed']
    has_checks = ($names -contains 'checks_found'); checks_found = $r.checks_found; checks_line = $r.checks_line; checks_count = $r.checks_count
    checks_result = $(if ($names -contains 'checks') { [string]$r.checks['result'] } else { '' })
}
'WJ-JSON ' + ($o | ConvertTo-Json -Compress)
'@
Write-Utf8 -Path $c1akDriver -Text ($c1akDriverText -replace "`r", '')
$c1akFull = [System.IO.Path]::GetFullPath($c1akRoot)
Add-C1akRow -Label ('FIXTURE a plain mission root under %TEMP% (no repository: the helper is driven alone), the base helper from ' + $wjBaseSha + ' at its pinned LF/blob sha256') `
    -Ok ($c1akTools.ok -and $c1akFull.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) -Said ('root ' + $c1akRoot + '; ' + $c1akTools.said)

# (a) THE PASSED FORM, as the instruments print it: one leading space.
$c1akPassed = @('[PASS] T-1 -- a member', '', '------', ' WP-4: all 54 checks passed.', '------', 'EXIT: 0')
$c1akAB = Invoke-C1akRun -Helper $c1akTools.helper -Lines $c1akPassed -Exit 0 -Tag 'BASE'
$c1akAT = Invoke-C1akRun -Helper $c1akTree -Lines $c1akPassed -Exit 0 -Tag 'TREE'
Add-C1akRow -Label '(a) a stdout carrying " WP-4: all 54 checks passed." and no TALLY, exit 0: RED at the base -- the tally file reads NO-TALLY exit_code=0' `
    -Ok (($c1akAB.tally.Count -eq 2) -and ($c1akAB.tally[0] -ceq 'NO-TALLY exit_code=0') -and $c1akAB.exitLast -and (-not $c1akAB.json.has_checks)) -Said ('base tally: ' + ($c1akAB.tally -join ' | '))
Add-C1akRow -Label '(a) ... GREEN: the tally capture CARRIES THE COUNT -- line 1 a CHECKS record reading 54, the EXIT line still last, two lines; the return object says so, and tally_found stays False' `
    -Ok (($c1akAT.tally.Count -eq 2) -and ($c1akAT.tally[0] -ceq 'CHECKS instrument=WP-4 result=passed checks=54 passed=54 failed=0 skipped=0 lines=1 exit_code_agrees=True') -and $c1akAT.exitLast -and
         ($c1akAT.json.checks_found -eq $true) -and ($c1akAT.json.checks_line -ceq 'WP-4: all 54 checks passed.') -and ($c1akAT.json.checks_count -eq 1) -and ($c1akAT.json.tally_found -eq $false) -and ($c1akAT.json.exit_code -eq 0) -and ($c1akAT.json.lastexit -eq 0)) `
    -Said ('tree tally: ' + ($c1akAT.tally -join ' | '))

# (b) THE FAILED FORM: the capture carries the failure.
$c1akFailed = @('[FAIL] T-2 -- a member', ' WP-4: 1 of 54 checks FAILED.', 'EXIT: 1')
$c1akBB = Invoke-C1akRun -Helper $c1akTools.helper -Lines $c1akFailed -Exit 1 -Tag 'BASE'
$c1akBT = Invoke-C1akRun -Helper $c1akTree -Lines $c1akFailed -Exit 1 -Tag 'TREE'
Add-C1akRow -Label '(b) a stdout carrying " WP-4: 1 of 54 checks FAILED.", exit 1: RED at the base -- NO-TALLY exit_code=1; GREEN -- CHECKS result=FAILED, failed=1 of checks=54, the exit code agreeing' `
    -Ok (($c1akBB.tally[0] -ceq 'NO-TALLY exit_code=1') -and ($c1akBT.tally.Count -eq 2) -and ($c1akBT.tally[0] -ceq 'CHECKS instrument=WP-4 result=FAILED checks=54 passed=53 failed=1 skipped=0 lines=1 exit_code_agrees=True') -and $c1akBT.exitLast -and ($c1akBT.json.exit_code -eq 1)) `
    -Said ('base: ' + $c1akBB.tally[0] + ' | tree: ' + ($c1akBT.tally -join ' | '))

# (c) NEITHER FORM: NO-TALLY stays the word, byte for byte the base's first line.
$c1akNeither = @('collected 0 items -- this instrument never reaches a count', 'EXIT: 3')
$c1akCB = Invoke-C1akRun -Helper $c1akTools.helper -Lines $c1akNeither -Exit 3 -Tag 'BASE'
$c1akCT = Invoke-C1akRun -Helper $c1akTree -Lines $c1akNeither -Exit 3 -Tag 'TREE'
Add-C1akRow -Label '(c) a stdout with NEITHER a TALLY nor a count line, exit 3: NO-TALLY exit_code=3, tree and base the same first line, two lines each' `
    -Ok (($c1akCT.tally.Count -eq 2) -and ($c1akCT.tally[0] -ceq 'NO-TALLY exit_code=3') -and ($c1akCB.tally[0] -ceq $c1akCT.tally[0]) -and $c1akCT.exitLast -and ($c1akCT.json.checks_found -eq $false)) -Said ('tree tally: ' + ($c1akCT.tally -join ' | '))

# (d) WP-3'S TWO OTHER FORMS: a skip beside a failure, and a skip with no failure.
$c1akD1 = Invoke-C1akRun -Helper $c1akTree -Lines @(' WP-3: 2 of 48 checks FAILED.  (1 SKIPPED.)', 'EXIT: 2') -Exit 2 -Tag 'TREE'
$c1akD2 = Invoke-C1akRun -Helper $c1akTree -Lines @(' WP-3: 47 of 48 checks passed, 1 SKIPPED -- a skip is not a pass; see the [SKIP] line(s) above.', 'EXIT: 0') -Exit 0 -Tag 'TREE'
Add-C1akRow -Label '(d) WP-3''s own two forms: "2 of 48 checks FAILED.  (1 SKIPPED.)" reads failed=2 skipped=1 passed=45; "47 of 48 checks passed, 1 SKIPPED -- ..." reads passed_with_skips, passed=47 skipped=1' `
    -Ok (($c1akD1.tally[0] -ceq 'CHECKS instrument=WP-3 result=FAILED checks=48 passed=45 failed=2 skipped=1 lines=1 exit_code_agrees=True') -and
         ($c1akD2.tally[0] -ceq 'CHECKS instrument=WP-3 result=passed_with_skips checks=48 passed=47 failed=0 skipped=1 lines=1 exit_code_agrees=True')) `
    -Said ($c1akD1.tally[0] + ' | ' + $c1akD2.tally[0])

# (e) A TALLY AND A COUNT LINE: line 1 is the TALLY, as it always was; the CHECKS record follows it; the
#     TALLY's own fields are what they were at the base.
$c1akBoth = @('TALLY passed=11 failed=0 skipped=2 runnable=13', ' WP-2: all 74 checks passed.', 'EXIT: 0')
$c1akEB = Invoke-C1akRun -Helper $c1akTools.helper -Lines $c1akBoth -Exit 0 -Tag 'BASE'
$c1akET = Invoke-C1akRun -Helper $c1akTree -Lines $c1akBoth -Exit 0 -Tag 'TREE'
Add-C1akRow -Label '(e) a TALLY line AND a count line: line 1 is the TALLY as at the base, the CHECKS record second, the EXIT line last; tally_found, tally_line and fields[passed] are the base''s' `
    -Ok (($c1akET.tally.Count -eq 3) -and ($c1akET.tally[0] -ceq 'TALLY passed=11 failed=0 skipped=2 runnable=13') -and ($c1akET.tally[0] -ceq $c1akEB.tally[0]) -and
         ($c1akET.tally[1] -ceq 'CHECKS instrument=WP-2 result=passed checks=74 passed=74 failed=0 skipped=0 lines=1 exit_code_agrees=True') -and $c1akET.exitLast -and ($c1akEB.tally.Count -eq 2) -and
         ($c1akET.json.tally_found -eq $true) -and ($c1akET.json.tally_line -ceq $c1akEB.json.tally_line) -and ($c1akET.json.passed -ceq '11') -and ($c1akEB.json.passed -ceq '11') -and ($c1akET.json.tally_count -eq 1)) `
    -Said ('tree tally: ' + ($c1akET.tally -join ' | '))

# (f) NOT THE INSTRUMENTS' LINE: each of these stays NO-TALLY.
$c1akNot = @(
    @{ what = 'at column 0, without the leading space'; line = 'WP-4: all 54 checks passed.' },
    @{ what = 'indented two spaces'; line = '  WP-4: all 54 checks passed.' },
    @{ what = 'quoted in the middle of a line'; line = 'the summary read " WP-4: all 54 checks passed." last time' },
    @{ what = 'WP-6''s column-0 refusal line'; line = 'WP-6: the gate-class map is missing at tools\lam\lam-gate-class.ps1 -- nothing to measure.' },
    @{ what = 'lower-case "failed"'; line = ' WP-4: 1 of 54 checks failed.' },
    @{ what = 'no number'; line = ' WP-4: all checks passed.' },
    @{ what = 'a FAILED line counting no failure, which no instrument prints'; line = ' WP-4: 0 of 54 checks FAILED.' },
    @{ what = 'a FAILED line with more failures than checks'; line = ' WP-4: 99 of 54 checks FAILED.' },
    @{ what = 'a skip line whose passes and skips are not its checks'; line = ' WP-3: 40 of 48 checks passed, 1 SKIPPED -- a skip is not a pass; see the [SKIP] line(s) above.' })
foreach ($c1akNo in $c1akNot) {
    $c1akF = Invoke-C1akRun -Helper $c1akTree -Lines @($c1akNo.line, 'EXIT: 0') -Exit 0 -Tag 'TREE'
    Add-C1akRow -Label ('(f) NOT the instruments'' line -- ' + $c1akNo.what + ': NO-TALLY exit_code=0') `
        -Ok (($c1akF.tally.Count -eq 2) -and ($c1akF.tally[0] -ceq 'NO-TALLY exit_code=0') -and ($c1akF.json.checks_found -eq $false)) -Said ('line: [' + $c1akNo.line + '] -> ' + $c1akF.tally[0])
}

# (g) THE EXIT CODE IS STILL THE CONTRACT: a passed line beside exit 3 is recorded as it reads, and flagged.
$c1akG = Invoke-C1akRun -Helper $c1akTree -Lines @(' WP-1: all 41 checks passed.', 'EXIT: 0') -Exit 3 -Tag 'TREE'
Add-C1akRow -Label '(g) a passed count line beside exit 3: the record carries the line AND exit_code_agrees=False; the exit code returned is 3 and the EXIT line says 3' `
    -Ok (($c1akG.tally[0] -ceq 'CHECKS instrument=WP-1 result=passed checks=41 passed=41 failed=0 skipped=0 lines=1 exit_code_agrees=False') -and ($c1akG.json.exit_code -eq 3) -and ($c1akG.json.lastexit -eq 3) -and ([string]$c1akG.tally[1]).StartsWith('EXIT exit_code=3 ')) `
    -Said ($c1akG.tally -join ' | ')
# (h) TWO COUNT LINES: both counted, the LAST read -- an instrument prints its own summary last.
$c1akH = Invoke-C1akRun -Helper $c1akTree -Lines @(' WP-5: 3 of 10 checks FAILED.', 'a fixture''s own output, echoed', ' WP-5: all 10 checks passed.', 'EXIT: 0') -Exit 0 -Tag 'TREE'
Add-C1akRow -Label '(h) two count lines in one stdout, a FAILED one echoed first and the instrument''s own passed line last: lines=2, and the LAST is the one read' `
    -Ok (($c1akH.tally[0] -ceq 'CHECKS instrument=WP-5 result=passed checks=10 passed=10 failed=0 skipped=0 lines=2 exit_code_agrees=True') -and ($c1akH.json.checks_count -eq 2)) -Said ($c1akH.tally[0])

# (i) THE FORMS ARE THE INSTRUMENTS': every count-line literal in the six instruments' own source, rendered
#     with numbers, is read by this tree's parser.
$c1akLits = New-Object System.Collections.Generic.List[string]
foreach ($c1akWp in 1..6) {
    $c1akSrc = [System.IO.File]::ReadAllText((Join-Path $repoRoot ('tests\lam\instrument-WP-' + $c1akWp + '.ps1')))
    foreach ($c1akLm in [regex]::Matches($c1akSrc, 'Write-Host \(?"( WP-' + $c1akWp + ': [^"\r\n]*checks (?:passed|FAILED)[^"\r\n]*)"')) { $c1akLits.Add($c1akLm.Groups[1].Value) }
}
$c1akParser = [bool](Get-Command -Name ConvertFrom-LamInstrumentChecksLine -CommandType Function -ErrorAction SilentlyContinue)
$c1akRead = 0
$c1akUnread = New-Object System.Collections.Generic.List[string]
foreach ($c1akLit in $c1akLits) {
    $c1akLine = $c1akLit.Replace('$($checksRun - $skips)', '47').Replace('$checksRun', '48').Replace('$failures', '2').Replace('$skips', '1')
    $c1akGot = if ($c1akParser) { ConvertFrom-LamInstrumentChecksLine -Text ("[PASS] x -- a member`n" + $c1akLine + "`nEXIT: 0") } else { [pscustomobject]@{ found = $false; count = 0; fields = @{} } }
    if ($c1akGot.found -and ($c1akGot.count -eq 1) -and ([string]$c1akGot.fields['checks'] -ceq '48')) { $c1akRead++ } else { $c1akUnread.Add($c1akLine) }
}
# SIXTEEN SINCE AN EARLIER RELEASE: WP-2 and WP-4 gained WP-6's skip outcome and with it WP-6's three summary forms, so each
# prints three count-line literals as WP-3 and WP-6 do; SEVENTEEN SINCE A LATER RELEASE, WP-1 gaining them too (for H-12,
# whose page a project does not hold); every form an instrument prints is still read by the parser.
Add-C1akRow -Label ('(i) THE SIX INSTRUMENTS'' OWN COUNT LINES, lifted from their source: ' + $c1akLits.Count + ' literals (2 in WP-5; 3 in WP-1, WP-2, WP-3, WP-4 and WP-6), every one rendered and READ by this tree''s parser') `
    -Ok ($c1akParser -and ($c1akLits.Count -eq 17) -and ($c1akRead -eq 17) -and ($c1akUnread.Count -eq 0)) -Said ('read ' + $c1akRead + ' of ' + $c1akLits.Count + '; unread: [' + ($c1akUnread -join ' ; ') + ']')
# ... AND WP-3's SKIP SUFFIX, which is a second literal on its FAILED line and is lifted too: the emitter's
#     own expression must still be in WP-3's source, and the whole line it renders must be read with its skip.
$c1akSrc3 = [System.IO.File]::ReadAllText((Join-Path $repoRoot 'tests\lam\instrument-WP-3.ps1'))
$c1akSuffixLit = "Write-Host (`" WP-3: `$failures of `$checksRun checks FAILED.`" + `$(if (`$skips -gt 0) { '  (' + `$skips + ' SKIPPED.)' } else { '' }))"
$c1akSuffixHits = ([regex]::Matches($c1akSrc3, [regex]::Escape($c1akSuffixLit))).Count
$c1akSuffixGot = if ($c1akParser) { ConvertFrom-LamInstrumentChecksLine -Text ("[FAIL] x -- a member`n" + ' WP-3: 2 of 48 checks FAILED.' + '  (' + '1' + ' SKIPPED.)' + "`nEXIT: 2") } else { [pscustomobject]@{ found = $false; fields = @{} } }
Add-C1akRow -Label '(i) ... WP-3''s skip suffix: its emitter expression stands ONCE in WP-3''s source as this member spells it, and the line it renders is read -- failed=2, skipped=1' `
    -Ok (($c1akSuffixHits -eq 1) -and $c1akSuffixGot.found -and ([string]$c1akSuffixGot.fields['failed'] -ceq '2') -and ([string]$c1akSuffixGot.fields['skipped'] -ceq '1')) -Said ('emitter occurrences: ' + $c1akSuffixHits)

# (j) THE CAPTURE SAYS WHAT IT WAS TAKEN ON: five keys after every key that
#     was there, capture_format still 1; in this root, which is no repository, head says it is not derivable.
$c1akKeysT = @([regex]::Matches($c1akAT.stdout.Substring(0, [Math]::Max(0, $c1akAT.stdout.IndexOf("`n--- instrument stdout and stderr, verbatim ---`n"))), '(?m)^([a-z_0-9]+): ') | ForEach-Object { $_.Groups[1].Value })
$c1akKeysB = @([regex]::Matches($c1akAB.stdout.Substring(0, [Math]::Max(0, $c1akAB.stdout.IndexOf("`n--- instrument stdout and stderr, verbatim ---`n"))), '(?m)^([a-z_0-9]+): ') | ForEach-Object { $_.Groups[1].Value })
$c1akStubSha = Get-PwRawSha -Path $c1akAT.stub
Add-C1akRow -Label '(j) the stdout capture''s header: the base''s 13 keys in the base''s order, then head, tree_clean, tree_reason, instrument_sha256, instrument_resolved; capture_format: 1; the sha256 and the path the stub''s own; head not derivable here, and said' `
    -Ok (($c1akKeysB.Count -eq 13) -and (($c1akKeysT -join ',') -ceq (($c1akKeysB -join ',') + ',head,tree_clean,tree_reason,instrument_sha256,instrument_resolved')) -and ($c1akAT.stdout -match '(?m)^capture_format: 1$') -and
         ($c1akAT.stdout -match ('(?m)^instrument_sha256: ' + $c1akStubSha + '$')) -and $c1akAT.stdout.Contains("`ninstrument_resolved: " + $c1akAT.stub + "`n") -and
         ($c1akAT.stdout -match '(?m)^head: not derivable \(the mission root is not the top level of a git repository') -and ($c1akAT.stdout -match '(?m)^tree_clean: not derivable$')) `
    -Said ('tree keys: ' + ($c1akKeysT -join ','))
# ... AND THE SHA256 IS OF THE FILE THAT RAN. Two stubs of ONE relative name in two folders; the PROCESS working
#     directory is the first folder, the PowerShell location the second -- the runner's shape under Push-Location.
#     The child runs the second folder's; a .NET read of the relative path would hash the first folder's.
$c1akDirA = Join-Path $c1akBase 'cwd-a'
$c1akDirB = Join-Path $c1akBase 'location-b'
Write-Utf8 -Path (Join-Path $c1akDirA 'rel-stub.ps1') -Text "Write-Host 'the stub in the PROCESS working directory'`nexit 0`n"
Write-Utf8 -Path (Join-Path $c1akDirB 'rel-stub.ps1') -Text "Write-Host 'the stub in the POWERSHELL location'`nexit 0`n"
$prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
try { $null = & powershell -NoProfile -ExecutionPolicy Bypass -File $c1akDriver -Helper $c1akTree -Stub 'rel-stub.ps1' -Root $c1akRoot -Key 'REL-1' -Location $c1akDirB -ProcessCwd $c1akDirA 2>&1 }
finally { $ErrorActionPreference = $prevEap }
$c1akRelPath = Join-Path $c1akRoot '.mission-runtime\lam\instrument-runs\REL-1.rel-stub.stdout.txt'
$c1akRel = if (Test-Path -LiteralPath $c1akRelPath -PathType Leaf) { [System.IO.File]::ReadAllText($c1akRelPath) } else { '' }
Add-C1akRow -Label '(j) ... a RELATIVE instrument path, the process working directory one folder and the PowerShell location another: the capture''s body, its instrument_resolved and its instrument_sha256 are all the LOCATION''s stub -- the one that ran' `
    -Ok ($c1akRel.Contains("`nthe stub in the POWERSHELL location`n") -and $c1akRel.Contains("`ninstrument_resolved: " + (Join-Path $c1akDirB 'rel-stub.ps1') + "`n") -and
         ($c1akRel -match ('(?m)^instrument_sha256: ' + (Get-PwRawSha -Path (Join-Path $c1akDirB 'rel-stub.ps1')) + '$')) -and ((Get-PwRawSha -Path (Join-Path $c1akDirA 'rel-stub.ps1')) -cne (Get-PwRawSha -Path (Join-Path $c1akDirB 'rel-stub.ps1')))) `
    -Said ('capture: ' + $c1akRelPath)

# (k) THE PLANE ROW, over C-2e..C-1ak: every evaluation at a root under %TEMP%, and both live planes' sentinel
#     paths as they were before C-1af.
$wjPlaneAfter = Get-EsPlaneSnapshot
$wjOutside = @($esEvalRoots | Where-Object { -not $_.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase) })
Add-C1akRow -Label ('(k) PLANE ' + $esEvalRoots.Count + ' evaluations by C-1af..C-1ak, every one at a root under %TEMP%; both live planes'' sentinel paths unchanged since before C-1af') `
    -Ok (($esEvalRoots.Count -gt 0) -and ($wjOutside.Count -eq 0) -and ($wjPlaneAfter -ceq $esPlaneBefore)) -Said ('outside %TEMP%: ' + $wjOutside.Count + '; snapshot equal: ' + ($wjPlaneAfter -ceq $esPlaneBefore))
}
catch {
    $c1akOk = $false
    $c1akRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1akRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Remove-PwTreeAsWritten -Base $c1akBase
Check -Id 'C-1ak' -Title 'THE HELPER''S TALLY PARSER LEARNS THE INSTRUMENTS'' COUNT LINE (the BATCH-3 charter (e)): driven alone in a child PowerShell, as WP-2''s R-47 drives it, Save-LamInstrumentRun over a stdout that carries " WP-4: all 54 checks passed." and no TALLY writes a tally capture whose first line is a CHECKS record reading 54, where the base helper writes NO-TALLY exit_code=0; over " WP-4: 1 of 54 checks FAILED." it carries the failure; WP-3''s two other forms -- a skip beside a failure, and a skip with no failure -- are read; NO-TALLY exit_code=<n> stays the first line of a stdout that carries neither, the base''s line byte for byte; the EXIT line still ends the file; where a TALLY was printed line 1 is still the TALLY and the record follows it, and tally_found, tally_line and fields are the base''s, so no figure a caller banks moves; a line at column 0 without the instruments'' leading space, one indented further, one quoted mid-line, WP-6''s column-0 refusal, a lower-case "failed", a line with no number, a FAILED line counting no failure or more failures than checks, and a skip line whose passes and skips are not its checks are NOT count lines; a passed line beside exit 3 is recorded with exit_code_agrees=False and the exit code returned is still 3; of two count lines the LAST is read; all 14 count-line literals in the six instruments'' own source are read by the parser, and WP-3''s skip suffix, whose emitter expression stands once in its source, with them; the stdout header keeps the base''s 13 keys in order and capture_format 1, and gains head, tree_clean, tree_reason, instrument_sha256 and instrument_resolved -- the last two of the file that RAN: with a relative path, the stub at the PowerShell location, not the one in the process working directory; and every evaluation by C-1af..C-1ak ran at a root under %TEMP%, both live planes'' sentinel paths unchanged' `
      -Ok $c1akOk -Detail ("      THE $(@($c1akRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1akRows -join "`n"))

# END OF BATCH-3 WP-J

# =============================================================================================
# BATCH-4 WP-L -- A GOAL FILE'S NUMBERS, THE ABSENT GOAL THAT CANNOT BE RECORDED, THE VERDICT ARTIFACT AS
# A BRIEF, THE KEPT CAPTURE AND THE PATTERNS LIST: C-1al, C-2f, C-1am, C-1an and C-1ao
# (the BATCH-4 charter (a)-(e); the operator's
# rulings B1 to B11 of 2026-10-06)
# =============================================================================================
# THE CHARTER'S WORDS:
#   (a) "the goal reader takes the whole line after the colon, so `reuse_within_minutes: 30  # ...`
#       reads as 0 -- fail-OPEN. CURE: the reader parses the scalar; a non-numeric or out-of-range value is an
#       evaluator_error -> NOT_MET with the reason printed, never a default. The
#       same for every numeric the goal schema declares (the seat enumerates them from the schema, standing 19)."
#   (b) "an ABSENT goal whose verdict artifact cannot be written still approves silently -- the one
#       route left. CURE: BLOCK under an earlier sentence, the reason on stderr and in the
#       hook's decision; the seat names the route by anchor text and line."
#   (c) "the goal's own verdict artifact named as the HANDOFF brief -> REFUSED (the class of the
#       admissions record; the same shape)."
#   (d) "RETROSPECTIVE SS3.3: when instrument_exit0 REUSES a capture, the evaluator writes the capture
#       it cites content-addressed beside the live file (<run-key>.<sha8>.stdout.txt, its header intact) BEFORE
#       the verdict names it, so the cited sha256 is on disk by the tool's own act; the verdict names both
#       paths. A kept copy is never overwritten."
#   (e) "RETROSPECTIVE SS3.5: validator_pass_count takes a `patterns:` list (or one regex) so one
#       detector reads one roster ...; the existing `pattern:` key keeps its meaning (every existing goal
#       unaffected)."
# AS RULED BY THE OPERATOR ON 2026-10-06, where the ruling says more than the charter: (a)'s route is
# goal_parse -- a number that is not one is a goal that does not parse, and a goal that exists and does not
# parse refuses the stop -- not the trap and not a new evaluator_error entry; `30  # x`
# is REFUSED, not read as 30; reuse_within_minutes is 0 to 999999 and count, cap and minutes 1 to 999999, each
# tested only under the type that reads it. (b) all three cases in which the absent goal's verdict is not
# written BLOCK. (c) both tests, by name and by identity; what cannot be established refuses. (d) the kept name
# is <key>.<leaf>.<sha8>.stdout.txt; a keep that cannot be made is a reuse that is refused, and the instrument
# runs. (e) `patterns:` is an inline list; both keys, or a malformed list, FAIL the detector with the reason.
# THE FIVE MEMBERS. C-1al drives the numbers; C-2f the absent goal that cannot be recorded; C-1am the verdict
# artifact as a brief; C-1an the kept capture; C-1ao the patterns list, and closes with the plane row. EVERY
# FALSIFIER ROW IS RED AT THE TREE BEFORE THE CURE, and where a base evaluator can show it the RED is KEPT as
# a control: the evaluator and its three libraries as they stood at this branch's parent at the cut,
# each pinned by its LF/blob sha256 (New-WlBaseTools).
# THE FIXTURE FORM IS C-1af's (New-EsMission): a real git repository under %TEMP%, its git dir and its common
# dir asserted EXACTLY <root>\.git before git is used again (the 2026-09-13 rule), `git config` never
# run. Every evaluation goes through Invoke-EsEval, Invoke-WjHook or Invoke-WlHookStreams, and all three REFUSE
# a mission root outside %TEMP%. No member here spawns a seat or touches a live mission plane. C-1ao writes
# four spawn-ledger lines INTO ITS OWN FIXTURE ROOT, by hand, as literal fixture data: no composer is run.
# EACH MEMBER PRINTS ITS STUB, OR ITS FIXTURE DATA, ON ITS FACE, under its rows.
$wlBaseSha  = '700e19e5-s09'
$wlBasePins = [ordered]@{
    'mission-goal-check.ps1'   = 'a26c07ed41a6fba20d5dac6480fa3a1d8210cedc74da6ef21921dd592485cf28'
    'lam-verify-admission.ps1' = 'ccd0d7d1656a0dba4187585d5e583d604e3c65882c094c7df704b800f4d4ba58'
    'lam-gate-class.ps1'       = 'bc7a3cd885709c5df5661f3a5cd308b878e7d63e89246a43e3d029278247e577'
    'lam-instrument-run.ps1'   = '19d1e69daf304f9681108c12e648b42094b70f1c5630ba5df9f4bc2106c0fa86'
}
function New-WlBaseTools {
    # The base evaluator and its three libraries, each at its pinned LF/blob sha256, under -Dir.
    param([string]$Dir)
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    $wlPinOk = $true
    $wlPinSaid = New-Object System.Collections.Generic.List[string]
    foreach ($wlPinName in @($script:wlBasePins.Keys)) {
        # Through Get-LamBaseBytes: the installed fixtures alone, no history -- the pin decides.
        $wlRead = Get-LamBaseBytes -Base $script:wlBaseSha -Path ('tools/lam/' + $wlPinName) -Pin $script:wlBasePins[$wlPinName]
        if (-not $wlRead.ok) { $wlPinOk = $false }
        $wlPinSaid.Add($wlPinName + ' ' + $wlRead.sha.Substring(0, 8) + ' (' + $wlRead.from + ')')
        [System.IO.File]::WriteAllBytes((Join-Path $Dir $wlPinName), $wlRead.bytes)
    }
    return [pscustomobject]@{ ok = $wlPinOk; path = (Join-Path $Dir 'mission-goal-check.ps1'); said = ($wlPinSaid -join ', ') }
}
function Invoke-WlHookStreams {
    # The evaluator as the Stop hook runs it, ITS STDOUT AND ITS STDERR KEPT APART -- Invoke-EsEval and
    # Invoke-WjHook read them merged. A child process with both streams redirected, the Stop payload on its
    # stdin, LAM_DISPATCH taken out of its environment. AT A FIXTURE ONLY (the plane rule). It removes no
    # prior verdict artifact. Returns exit, stdout, stderr, decision and reason (the JSON line on STDOUT),
    # text (the verdict file where it is a readable file) and verdict.
    param([string]$Root, [string]$GoalId, [string]$Evaluator)
    if (-not $Evaluator) { $Evaluator = $goalCheck }
    $wlFull = [System.IO.Path]::GetFullPath($Root)
    if (-not $wlFull.StartsWith($script:esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ('PLANE RULE: ' + $wlFull + ' is not under ' + $script:esTempRoot + ' -- these members evaluate fixtures only')
    }
    $script:esEvalRoots.Add($wlFull)
    $wlPsi = New-Object System.Diagnostics.ProcessStartInfo
    $wlPsi.FileName = 'powershell'
    $wlPsi.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + $Evaluator + '" -Goal "' + $GoalId + '" -MissionRoot "' + $Root + '" -AsStopHook'
    $wlPsi.UseShellExecute = $false
    $wlPsi.CreateNoWindow = $true
    $wlPsi.RedirectStandardInput = $true
    $wlPsi.RedirectStandardOutput = $true
    $wlPsi.RedirectStandardError = $true
    if ($wlPsi.EnvironmentVariables.ContainsKey('LAM_DISPATCH')) { $wlPsi.EnvironmentVariables.Remove('LAM_DISPATCH') }
    $wlProc = [System.Diagnostics.Process]::Start($wlPsi)
    try {
        $wlErrTask = $wlProc.StandardError.ReadToEndAsync()
        $wlOutTask = $wlProc.StandardOutput.ReadToEndAsync()
        $wlProc.StandardInput.Write((@{ session_id = 'wp3-wl'; hook_event_name = 'Stop' } | ConvertTo-Json -Compress))
        $wlProc.StandardInput.Close()
        $wlProc.WaitForExit()
        $wlOut = [string]$wlOutTask.Result
        $wlErr = [string]$wlErrTask.Result
        $wlCode = $wlProc.ExitCode
    } finally { $wlProc.Dispose() }
    $wlVf = Join-Path $Root ('.mission\goals\' + $GoalId + '.verdict.yaml')
    $wlText = ''
    if (Test-Path -LiteralPath $wlVf -PathType Leaf) { try { $wlText = [System.IO.File]::ReadAllText($wlVf) } catch { $wlText = '' } }
    $wlV = '(no verdict file)'
    $wlVm = [regex]::Match($wlText, '(?m)^verdict:[ \t]*(\S+)')
    if ($wlVm.Success) { $wlV = $wlVm.Groups[1].Value }
    $wlDec = ''
    $wlReason = ''
    foreach ($wlLn in @(($wlOut -replace "`r", '') -split "`n")) {
        $wlT = $wlLn.Trim()
        if (-not $wlT.StartsWith('{')) { continue }
        try { $wlJ = $wlT | ConvertFrom-Json; $wlDec = [string]$wlJ.decision; $wlReason = [string]$wlJ.reason; break } catch { }
    }
    return [pscustomobject]@{ exit = $wlCode; stdout = $wlOut; stderr = $wlErr; decision = $wlDec; reason = $wlReason; text = $wlText; verdict = $wlV }
}
function Get-WlMasked {
    # A verdict artifact with its clock masked: what this tree and the base of this batch (which
    # already writes the two scanned-set keys) are compared on, byte for byte.
    param([string]$Text)
    return (([string]$Text) -replace $script:esMask, 'evaluated_at: MASKED')
}
function Get-WlIndented {
    # A stub's or a fixture file's text, as a member prints it on its face: every line indented, CR dropped.
    param([string]$Text)
    return ((@((([string]$Text) -replace "`r", '').TrimEnd("`n") -split "`n") | ForEach-Object { '          | ' + $_ }) -join "`n")
}

# =============================================================================================
# C-1al -- A NUMBER IN A GOAL FILE IS A WHOLE NUMBER IN ITS RANGE, OR THE GOAL DOES NOT PARSE:
#          reuse_within_minutes, count, cap and minutes, one rule, each under its own type
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a goal written
# `reuse_within_minutes: 30  # thirty minutes` over a capture seconds old reads MET and RUNS the instrument
# -- the window is dropped, and the only word of it is in the detail of an entry that passed; a goal written
# `count: 4  # four` asks validator_pass_count for NO result at all and passes. THE CONTROLS: `30` alone
# reuses as it did, and so does `"30"`; a numeric key under a type that does not read it is not tested;
# every tracked goal of this tree carries only numbers the rule admits.
# THE FIXTURE is C-1ai's: a committed .gitignore for the verdict artifact and the runtime plane, a
# mission.yaml admitting `?? scratch/`, where the instrument lives, and every goal committed before any
# capture is taken, so the tree is clean and a reuse can happen at all.
$c1alOk = $true
$c1alRows = New-Object System.Collections.Generic.List[string]
function Add-C1alRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1alOk = $false }
    $script:c1alRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1alRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1alRuns {
    $c1alCounter = Join-Path $script:c1alRoot '.mission-runtime\wl-ran.txt'
    if (-not (Test-Path -LiteralPath $c1alCounter -PathType Leaf)) { return 0 }
    return @([System.IO.File]::ReadAllLines($c1alCounter) | Where-Object { $_ }).Count
}
function Get-C1alReading {
    # One evaluation of -GoalId, by hand or as the Stop hook: how many times the instrument RAN during it (the
    # counter's delta), the goal_parse entry and the first entry of -Type, and the artifact's text.
    param([string]$GoalId, [string]$Evaluator, [switch]$Hook, [string]$Type = 'instrument_exit0')
    $c1alBefore = Get-C1alRuns
    $c1alArgs = @{ Root = $script:c1alRoot; GoalId = $GoalId }
    if ($Evaluator) { $c1alArgs['Evaluator'] = $Evaluator }
    if ($Hook) { $c1alArgs['Hook'] = $true }
    $c1alEv = Invoke-EsEval @c1alArgs
    $c1alParse = Get-PwDetector -Text $c1alEv.text -Type 'goal_parse'
    $c1alDet = Get-PwDetector -Text $c1alEv.text -Type $Type
    return [pscustomobject]@{ verdict = $c1alEv.verdict; exit = $c1alEv.exit; decision = $c1alEv.decision; reason = $c1alEv.reason; out = $c1alEv.out
                              ran = ((Get-C1alRuns) - $c1alBefore); parseFound = $c1alParse.found; parse = [string]$c1alParse.detail
                              found = $c1alDet.found; ok = $c1alDet.ok; detail = [string]$c1alDet.detail; text = $c1alEv.text
                              types = @(Get-PwDetectorTypes -Text $c1alEv.text)
                              parseKey = [bool]($c1alEv.text -match '(?m)^goal_parse_error: ')
                              reuseKey = [bool]($c1alEv.text -match '(?m)^instrument_captures_reused:') }
}
function Get-C1alFault {
    # The sentence the rule prints for one number that is not one, as this member expects it, word for word.
    param([int]$Line, [string]$Key, [string]$Value, [int]$Min, [string]$Type)
    return ('line ' + $Line + ': ' + $Key + ": '" + $Value + "' is not a whole number from " + $Min + ' to 999999 (' + $Type + ' reads it as a number)')
}
$c1alM = $null
$c1alInstText = @'
$wlRt = Join-Path (Split-Path -Parent (Split-Path -Parent $PSCommandPath)) '.mission-runtime'
if (-not (Test-Path -LiteralPath $wlRt)) { New-Item -ItemType Directory -Path $wlRt -Force | Out-Null }
[System.IO.File]::AppendAllText((Join-Path $wlRt 'wl-ran.txt'), "ran`n")
Write-Output 'the BATCH-4 fixture instrument ran; exit 0'
exit 0
'@
try {
$c1alM = New-EsMission -Tag 'c1al'
if (-not $c1alM.ok) { throw ('FIXTURE REFUSED: ' + $c1alM.why) }
$c1alRoot = $c1alM.root
$c1alBase = New-WlBaseTools -Dir (Join-Path $c1alM.base 'base-tools')
$c1alInst = Join-Path $c1alRoot 'scratch\inst.ps1'
Write-Utf8 -Path $c1alInst -Text ($c1alInstText -replace "`r", '')
Write-Utf8 -Path (Join-Path $c1alRoot '.gitignore') -Text "/.mission/goals/*.verdict.yaml`n.mission-runtime/`n"
Write-Utf8 -Path (Join-Path $c1alRoot '.mission\mission.yaml') -Text "id: wl-numbers-fixture`nadmitted_porcelain: [`"?? scratch/`"]`n"
# EVERY GOAL: `id:` is line 1, `detectors:` line 2, the first detector's `- type:` line 3. The lines named in
# the rows below are counted from that.
$c1alInstHead = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
Write-PwGoal -Root $c1alRoot -GoalId 'G-N30'    -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: 30'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-N30C'   -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: 30  # thirty minutes'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-N30Q'   -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: "30"'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-N7D'    -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: 1000000'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-NNEG'   -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: -5'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-NEMPTY' -DetectorLines ($c1alInstHead + @('    reuse_within_minutes:'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-NDUP'   -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: 30', '    reuse_within_minutes: soon'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-NFIRST' -DetectorLines @('  - reuse_within_minutes: 30  # the item opens on it', '    type: instrument_exit0', '    path: scratch/inst.ps1')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NCNT'   -DetectorLines @('  - type: validator_pass_count', '    dir: results', '    count: 4  # four')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NCNT0'  -DetectorLines @('  - type: validator_pass_count', '    dir: results', '    count: 0')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NCAP'   -DetectorLines @('  - type: turn_cap', '    cap: 5  # five')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NCAP0'  -DetectorLines @('  - type: turn_cap', '    cap: 0')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NMIN'   -DetectorLines @('  - type: time_cap', '    minutes: 10  # ten', '    since_file: evidence/built.txt')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NTWO'   -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', '  - type: turn_cap', '    cap: many', '  - type: time_cap', '    minutes: 1.5', '    since_file: evidence/built.txt')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NOTHER' -DetectorLines @('  - type: file_exists', '    path: evidence/built.txt', '    count: 4  # not a key this type reads', '    reuse_within_minutes: soon')
Write-PwGoal -Root $c1alRoot -GoalId 'G-NMAX'   -DetectorLines ($c1alInstHead + @('    reuse_within_minutes: 999999', '  - type: validator_pass_count', '    dir: results', '    count: 999999', '  - type: turn_cap', '    cap: 999999', '  - type: time_cap', '    minutes: 999999', '    since_file: evidence/built.txt'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-NMAX1'  -DetectorLines @('  - type: validator_pass_count', '    dir: results', '    count: 1000000')
# ROW (o)'s GOAL (BATCH-6 WP-Q (a)): the fifth key this file reads as a number, under the one rule.
Write-PwGoal -Root $c1alRoot -GoalId 'G-NTREE'  -DetectorLines ($c1alInstHead + @('    reuse_tree_within_minutes: 180  # three hours'))
# THE TWO HALT-SCOPE GOALS (rows (m) and (n)). The HALT files themselves are written only when those rows
# run, last: until then no HALT stands in this fixture. The allowlist entry names the bytes the first will have.
$c1alHaltBytes = $pwUtf8.GetBytes("# HALT-WL-01`n`n**Status:** ANSWERED`n")
$c1alHaltMember = 'HALT-WL-01.md@' + (Get-PwSha256 -Bytes $c1alHaltBytes)
Write-PwGoal -Root $c1alRoot -GoalId 'G-NHALT'  -DetectorLines (@('  - type: halt_absent', ('    legacy_answered_allowlist: "' + $c1alHaltMember + '"'), '  - type: file_exists', '    path: evidence/absent.txt') + $c1alInstHead + @('    reuse_within_minutes: 30  # thirty minutes'))
Write-PwGoal -Root $c1alRoot -GoalId 'G-NHDIR'  -DetectorLines @('  - type: halt_absent', '    dir: custom-halts', '  - type: turn_cap', '    cap: many')
$c1alAdd = Invoke-PwGit -Root $c1alRoot -GitArgs @('add', '--', '.gitignore', '.mission/mission.yaml', '.mission/goals')
$c1alCom = Invoke-PwGit -Root $c1alRoot -GitArgs ($esCommitArgs + @('the numbers fixture'))
$c1alPorc = (Invoke-PwGit -Root $c1alRoot -GitArgs @('status', '--porcelain=v1')).text.Trim()
Add-C1alRow -Label 'FIXTURE a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/") and twenty goals committed; porcelain reads exactly "?? scratch/"' `
    -Ok ($c1alBase.ok -and ($c1alAdd.exit -eq 0) -and ($c1alCom.exit -eq 0) -and ($c1alPorc -ceq '?? scratch/')) -Said ('porcelain [' + $c1alPorc + ']; ' + $c1alBase.said)

# (a) THE CAPTURE, AND THE CONTROL: `30` alone runs once and is then REUSED, as C-1ai row (d) has it.
$c1alA1 = Get-C1alReading -GoalId 'G-N30'
$c1alA2 = Get-C1alReading -GoalId 'G-N30'
Add-C1alRow -Label '(a) CONTROL reuse_within_minutes: 30, alone on its value: the first evaluation RUNS the instrument, the next one seconds later REUSES that capture -- the instrument does not run, MET' `
    -Ok (($c1alA1.ran -eq 1) -and ($c1alA1.verdict -ceq 'MET') -and ($c1alA2.ran -eq 0) -and ($c1alA2.verdict -ceq 'MET') -and $c1alA2.detail.Contains('REUSED A FRESH READING') -and (-not $c1alA2.parseFound)) `
    -Said ('ran ' + $c1alA1.ran + ', then ' + $c1alA2.ran + '; ' + $c1alA2.detail)
# (b) THE FALSIFIER: the same value with a comment after it, over that capture.
$c1alWantB = Get-C1alFault -Line 5 -Key 'reuse_within_minutes' -Value '30  # thirty minutes' -Min 0 -Type 'instrument_exit0'
$c1alB = Get-C1alReading -GoalId 'G-N30C'
Add-C1alRow -Label '(b) FALSIFIER reuse_within_minutes: 30  # thirty minutes -- by hand: NOT_MET, exit 1, ONE entry, goal_parse, naming line 5, the key and the value as written; the instrument is NOT run; goal_parse_error at column 0' `
    -Ok (($c1alB.verdict -ceq 'NOT_MET') -and ($c1alB.exit -eq 1) -and ($c1alB.ran -eq 0) -and $c1alB.parseFound -and ($c1alB.types.Count -eq 1) -and $c1alB.parseKey -and
         $c1alB.parse.Contains('THE GOAL FILE DOES NOT PARSE -- a number it declares is not one -- ' + $c1alWantB + ' -- ') -and $c1alB.parse.Contains('(register row 385)') -and $c1alB.parse.Contains('the stop is REFUSED (register row 341')) `
    -Said ('verdict ' + $c1alB.verdict + ', exit ' + $c1alB.exit + ', ran ' + $c1alB.ran + '; entries [' + ($c1alB.types -join ', ') + ']; goal_parse: ' + $c1alB.parse + ' | instrument_exit0: ' + $c1alB.detail)
$c1alBH = Get-C1alReading -GoalId 'G-N30C' -Hook
Add-C1alRow -Label '(b) FALSIFIER ... as the Stop hook: the hook BLOCKS (exit 0), the reason printing the same sentence; the instrument is NOT run' `
    -Ok (($c1alBH.decision -ceq 'block') -and ($c1alBH.exit -eq 0) -and ($c1alBH.ran -eq 0) -and $c1alBH.reason.Contains('goal_parse: THE GOAL FILE DOES NOT PARSE -- a number it declares is not one -- ' + $c1alWantB)) `
    -Said ('decision ' + $c1alBH.decision + ', ran ' + $c1alBH.ran + '; reason: ' + $c1alBH.reason)
# (c) THE RED, KEPT: the base evaluator over the same goal and the same capture.
$c1alC = Get-C1alReading -GoalId 'G-N30C' -Evaluator $c1alBase.path
$c1alCH = Get-C1alReading -GoalId 'G-N30C' -Evaluator $c1alBase.path -Hook
Add-C1alRow -Label '(c) RED at the base, same goal, same capture: MET, exit 0, the instrument RUNS -- the window dropped -- "read as 0" only in the detail of an entry that passed; no reuse key; the hook approves and RUNS it again' `
    -Ok ($c1alBase.ok -and ($c1alC.verdict -ceq 'MET') -and ($c1alC.exit -eq 0) -and ($c1alC.ran -eq 1) -and $c1alC.ok -and $c1alC.detail.Contains('is not a whole number of minutes from 0 to 999999: read as 0, and the instrument was run') -and
         (-not $c1alC.reuseKey) -and (-not $c1alC.parseFound) -and ($c1alCH.decision -ceq 'approve') -and ($c1alCH.ran -eq 1)) `
    -Said ('base: ' + $c1alC.verdict + ', ran ' + $c1alC.ran + '; hook ' + $c1alCH.decision + ', ran ' + $c1alCH.ran + '; detail: ' + $c1alC.detail)
# (d) `"30"`: the reader has always unquoted a value, so it is thirty.
$null = Get-C1alReading -GoalId 'G-N30'
$c1alD = Get-C1alReading -GoalId 'G-N30Q'
Add-C1alRow -Label '(d) CONTROL reuse_within_minutes: "30" -- quoted: read as 30 and REUSED, the instrument does not run' `
    -Ok (($c1alD.ran -eq 0) -and ($c1alD.verdict -ceq 'MET') -and $c1alD.detail.Contains('reuse_within_minutes 30): capture ')) -Said ('ran ' + $c1alD.ran + '; ' + $c1alD.detail)
# (e) OUT OF RANGE, AND NOT A NUMBER AT ALL: seven digits, a sign, an empty value.
foreach ($c1alBad in @(@{ id = 'G-N7D'; value = '1000000'; what = 'seven digits (1000000)' }, @{ id = 'G-NNEG'; value = '-5'; what = 'a sign (-5)' }, @{ id = 'G-NEMPTY'; value = ''; what = 'an empty value' })) {
    $c1alE = Get-C1alReading -GoalId $c1alBad.id
    Add-C1alRow -Label ('(e) reuse_within_minutes with ' + $c1alBad.what + ': NOT_MET, goal_parse naming line 5 and the value; the instrument is NOT run') `
        -Ok (($c1alE.verdict -ceq 'NOT_MET') -and ($c1alE.ran -eq 0) -and $c1alE.parse.Contains((Get-C1alFault -Line 5 -Key 'reuse_within_minutes' -Value $c1alBad.value -Min 0 -Type 'instrument_exit0'))) `
        -Said ('verdict ' + $c1alE.verdict + ', ran ' + $c1alE.ran + '; goal_parse: ' + $c1alE.parse)
}
# (f) THE LINE IS THE ONE WHOSE VALUE THE ITEM HOLDS: a key written twice (the last wins), and a key that
#     opens its item.
$c1alF1 = Get-C1alReading -GoalId 'G-NDUP'
$c1alF2 = Get-C1alReading -GoalId 'G-NFIRST'
Add-C1alRow -Label '(f) the key written twice (30, then soon): the LAST is the value, and line 6 is named; the key opening its item (`- reuse_within_minutes: 30  # ...`): line 3 is named' `
    -Ok ($c1alF1.parse.Contains((Get-C1alFault -Line 6 -Key 'reuse_within_minutes' -Value 'soon' -Min 0 -Type 'instrument_exit0')) -and ($c1alF1.ran -eq 0) -and
         $c1alF2.parse.Contains((Get-C1alFault -Line 3 -Key 'reuse_within_minutes' -Value '30  # the item opens on it' -Min 0 -Type 'instrument_exit0')) -and ($c1alF2.ran -eq 0)) `
    -Said ('twice: ' + $c1alF1.parse + ' | opening: ' + $c1alF2.parse)

# (g) count -- THE ALLOW-SIDE ONE. No result file exists; `count: 4  # four` and `count: 0`.
$c1alG = Get-C1alReading -GoalId 'G-NCNT' -Type 'validator_pass_count'
$c1alGB = Get-C1alReading -GoalId 'G-NCNT' -Type 'validator_pass_count' -Evaluator $c1alBase.path
Add-C1alRow -Label '(g) FALSIFIER validator_pass_count count: 4  # four, no result on disk -- NOT_MET, goal_parse naming line 5, the key and the value; RED at the base: MET, "0 of 0 required" -- it asked for nothing and passed' `
    -Ok (($c1alG.verdict -ceq 'NOT_MET') -and (-not $c1alG.found) -and $c1alG.parse.Contains((Get-C1alFault -Line 5 -Key 'count' -Value '4  # four' -Min 1 -Type 'validator_pass_count')) -and
         ($c1alGB.verdict -ceq 'MET') -and $c1alGB.ok -and $c1alGB.detail.StartsWith('0 of 0 required validator result(s)')) `
    -Said ('tree: ' + $c1alG.verdict + ' -- ' + $c1alG.parse + ' | base: ' + $c1alGB.verdict + ' -- ' + $c1alGB.detail)
$c1alG0 = Get-C1alReading -GoalId 'G-NCNT0' -Type 'validator_pass_count'
$c1alG0B = Get-C1alReading -GoalId 'G-NCNT0' -Type 'validator_pass_count' -Evaluator $c1alBase.path
Add-C1alRow -Label '(g) count: 0 -- below the key''s floor of 1: NOT_MET, goal_parse naming it; RED at the base: MET, "0 of 0 required"' `
    -Ok (($c1alG0.verdict -ceq 'NOT_MET') -and $c1alG0.parse.Contains((Get-C1alFault -Line 5 -Key 'count' -Value '0' -Min 1 -Type 'validator_pass_count')) -and ($c1alG0B.verdict -ceq 'MET') -and $c1alG0B.detail.StartsWith('0 of 0 required')) `
    -Said ('tree: ' + $c1alG0.parse + ' | base: ' + $c1alG0B.verdict)
# (h) cap AND minutes: they failed closed already, in a sentence that named neither the value nor the cause.
$c1alH1 = Get-C1alReading -GoalId 'G-NCAP' -Type 'turn_cap'
$c1alH1B = Get-C1alReading -GoalId 'G-NCAP' -Type 'turn_cap' -Evaluator $c1alBase.path
$c1alH2 = Get-C1alReading -GoalId 'G-NMIN' -Type 'time_cap'
$c1alH2B = Get-C1alReading -GoalId 'G-NMIN' -Type 'time_cap' -Evaluator $c1alBase.path
$c1alH3 = Get-C1alReading -GoalId 'G-NCAP0' -Type 'turn_cap'
Add-C1alRow -Label '(h) turn_cap cap: 5  # five; time_cap minutes: 10  # ten; cap: 0 -- each NOT_MET as goal_parse naming its line, key and value; at the base each was NOT_MET already, its entry naming neither ("turn_cap has no positive ''cap''", "time_cap needs ''minutes'' and ''since_file''")' `
    -Ok (($c1alH1.verdict -ceq 'NOT_MET') -and $c1alH1.parse.Contains((Get-C1alFault -Line 4 -Key 'cap' -Value '5  # five' -Min 1 -Type 'turn_cap')) -and
         ($c1alH2.verdict -ceq 'NOT_MET') -and $c1alH2.parse.Contains((Get-C1alFault -Line 4 -Key 'minutes' -Value '10  # ten' -Min 1 -Type 'time_cap')) -and
         ($c1alH3.verdict -ceq 'NOT_MET') -and $c1alH3.parse.Contains((Get-C1alFault -Line 4 -Key 'cap' -Value '0' -Min 1 -Type 'turn_cap')) -and
         ($c1alH1B.verdict -ceq 'NOT_MET') -and ($c1alH1B.detail -ceq "turn_cap has no positive 'cap'") -and ($c1alH2B.verdict -ceq 'NOT_MET') -and ($c1alH2B.detail -ceq "time_cap needs 'minutes' and 'since_file'")) `
    -Said ('cap: ' + $c1alH1.parse + ' | minutes: ' + $c1alH2.parse + ' | base cap: ' + $c1alH1B.detail + ' | base minutes: ' + $c1alH2B.detail)
# (i) TWO NUMBERS THAT ARE NOT, IN ONE GOAL: both are named, and the detector that would have passed is not run.
$c1alI = Get-C1alReading -GoalId 'G-NTWO' -Type 'file_exists'
Add-C1alRow -Label '(i) two numbers that are not, in one goal (cap: many at line 6, minutes: 1.5 at line 8): ONE goal_parse entry naming both; the file_exists detector beside them is not evaluated' `
    -Ok (($c1alI.verdict -ceq 'NOT_MET') -and ($c1alI.types.Count -eq 1) -and (-not $c1alI.found) -and
         $c1alI.parse.Contains((Get-C1alFault -Line 6 -Key 'cap' -Value 'many' -Min 1 -Type 'turn_cap') + '; ' + (Get-C1alFault -Line 8 -Key 'minutes' -Value '1.5' -Min 1 -Type 'time_cap'))) `
    -Said ('entries [' + ($c1alI.types -join ', ') + ']; ' + $c1alI.parse)
# (j) CONTROL: a number is tested only under the type that reads it.
$c1alJ = Get-C1alReading -GoalId 'G-NOTHER' -Type 'file_exists'
$c1alJB = Get-C1alReading -GoalId 'G-NOTHER' -Type 'file_exists' -Evaluator $c1alBase.path
Add-C1alRow -Label '(j) CONTROL file_exists carrying count: 4  # ... and reuse_within_minutes: soon -- keys that type does not read: MET, no goal_parse entry, the artifact the base''s byte for byte but for its clock' `
    -Ok (($c1alJ.verdict -ceq 'MET') -and (-not $c1alJ.parseFound) -and ($c1alJB.verdict -ceq 'MET') -and ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1alJ.text)) -ceq (Get-WlMasked -Text $c1alJB.text))) `
    -Said ('tree ' + $c1alJ.verdict + ', base ' + $c1alJB.verdict + '; artifacts equal: ' + ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1alJ.text)) -ceq (Get-WlMasked -Text $c1alJB.text)))

# (k) THIS TREE'S OWN TRACKED GOALS, READ-ONLY, THROUGH THE EVALUATOR'S OWN RULE: the reader, the rule and the
#     step's function lifted from this tree's evaluator by their AST (as WP-2 R-E and C-1ah row (m) lift the
#     reader), and run over every goal file git tracks here. No goal is evaluated.
$c1alTok = $null; $c1alErr = $null
$c1alAst = [System.Management.Automation.Language.Parser]::ParseFile($goalCheck, [ref]$c1alTok, [ref]$c1alErr)
$c1alLift = @{}
foreach ($c1alFnName in @('Read-GoalDetectors', 'ConvertTo-GoalWholeNumber', 'Get-GoalNumericFaults')) {
    $c1alLift[$c1alFnName] = @($c1alAst.FindAll({ param($n) ($n -is [System.Management.Automation.Language.FunctionDefinitionAst]) -and ($n.Name -ceq $c1alFnName) }.GetNewClosure(), $true))
}
$c1alLifted = (@($c1alLift.Keys | Where-Object { $c1alLift[$_].Count -ne 1 }).Count -eq 0)
$c1alReaderParams = @()
if ($c1alLift['Read-GoalDetectors'].Count -eq 1) { $c1alReaderParams = @($c1alLift['Read-GoalDetectors'][0].Body.ParamBlock.Parameters | ForEach-Object { $_.Name.VariablePath.UserPath }) }
$c1alGoalFiles = @((Get-LamTrackedGoals).files)
$c1alTested = 0
$c1alFaults = New-Object System.Collections.Generic.List[string]
$c1alSame = $true
if ($c1alLifted -and ($c1alReaderParams -contains 'LineLog')) {
    foreach ($c1alFnName in @('Read-GoalDetectors', 'ConvertTo-GoalWholeNumber', 'Get-GoalNumericFaults')) { . ([scriptblock]::Create($c1alLift[$c1alFnName][0].Extent.Text)) }
    foreach ($c1alGf in $c1alGoalFiles) {
        $c1alGp = Join-Path $repoRoot ($c1alGf -replace '/', '\')
        if (-not (Test-Path -LiteralPath $c1alGp -PathType Leaf)) { continue }
        $c1alLog = New-Object System.Collections.Generic.List[object]
        $c1alWith = @(Read-GoalDetectors -Path $c1alGp -LineLog $c1alLog)
        $c1alPlain = @(Read-GoalDetectors -Path $c1alGp)
        # WHAT THE READER RETURNS DID NOT MOVE: with the log and without it, item for item and key for key.
        $c1alShape = { param($Items) (@($Items | ForEach-Object { $c1alIt = $_; (@($c1alIt.Keys | Sort-Object) | ForEach-Object { [string]$_ + '=' + [string]$c1alIt[$_] }) -join '|' }) -join "`n") }
        if ((& $c1alShape $c1alWith) -cne (& $c1alShape $c1alPlain)) { $c1alSame = $false }
        $c1alRule = Get-GoalNumericFaults -Detectors $c1alWith -LineLog $c1alLog
        $c1alTested += [int]$c1alRule.tested
        foreach ($c1alFault in @($c1alRule.faults)) { $c1alFaults.Add($c1alGf + ' line ' + [string]$c1alFault.line + ' ' + [string]$c1alFault.key + ' [' + [string]$c1alFault.value + ']') }
    }
}
Add-C1alRow -Label ('(k) THIS TREE''S TRACKED GOALS, READ-ONLY: ' + $c1alGoalFiles.Count + ' goal file(s) through the evaluator''s own reader and rule, lifted by AST -- every number they declare is one (0 faults); and the reader returns the same items with -LineLog as without it') `
    -Ok ($c1alLifted -and ($c1alReaderParams -contains 'LineLog') -and ($c1alGoalFiles.Count -gt 0) -and ($c1alTested -gt 0) -and ($c1alFaults.Count -eq 0) -and $c1alSame) `
    -Said ('lifted (each exactly once): ' + $c1alLifted + '; the reader''s parameters [' + ($c1alReaderParams -join ', ') + ']; goal files [' + ($c1alGoalFiles -join ', ') + ']; numbers tested ' + $c1alTested + '; faults [' + ($c1alFaults -join ' ; ') + ']; same items: ' + $c1alSame)

# (l) THE EDGES OF THE RANGE: 999999 is the most six digits say, and it is admitted under each of the four
#     keys -- the goal PARSES and every detector is evaluated; seven digits under count is refused.
$c1alL = Get-C1alReading -GoalId 'G-NMAX' -Type 'time_cap'
$c1alL1 = Get-C1alReading -GoalId 'G-NMAX1' -Type 'validator_pass_count'
Add-C1alRow -Label '(l) 999999 under each of the four keys: the goal PARSES -- no goal_parse entry, all four detectors evaluated, time_cap against a cap of 999999 -- and count: 1000000 is refused, naming line 5' `
    -Ok ((-not $c1alL.parseFound) -and ($c1alL.types.Count -eq 4) -and $c1alL.found -and $c1alL.ok -and $c1alL.detail.EndsWith(' against a cap of 999999') -and
         ($c1alL1.verdict -ceq 'NOT_MET') -and $c1alL1.parse.Contains((Get-C1alFault -Line 5 -Key 'count' -Value '1000000' -Min 1 -Type 'validator_pass_count'))) `
    -Said ('entries [' + ($c1alL.types -join ', ') + ']; time_cap: ' + $c1alL.detail + ' | 1000000: ' + $c1alL1.parse)

# (m) THE HALT SCOPE IS KEPT -- THE ALLOWLIST (the builder-side review's finding). A goal that answers a
#     legacy HALT by its legacy_answered_allowlist, a failing detector beside it, and a number that is not one.
#     The refusal runs no detector, but the goal still says which halts it answers: the HALT is ANSWERED, the
#     verdict NOT_MET, the hook BLOCKS. (With the scope dropped the HALT read OPEN, the verdict was HALT and
#     the hook APPROVED.) The allowlist honours a member of the evaluator's legacy census only, and a fixture
#     HALT is no member: each evaluator is run as a COPY whose census holds ONE more line, the fixture's.
function New-C1alCensusTools {
    # A copy, under -Dir, of the evaluator and its three libraries at -FromDir, whose legacy census holds ONE more
    # line, -Member. An evaluator that carries its census as a here-string literal (a base) gets the line added to the
    # copy's literal, whose opening line must stand exactly once; one that reads legacy-halt-census.txt beside it (this
    # tree) is copied byte for byte and gets that file beside it, holding the line.
    param([string]$FromDir, [string]$Dir, [string]$Member)
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    foreach ($c1alLib in @('mission-goal-check.ps1', 'lam-verify-admission.ps1', 'lam-gate-class.ps1', 'lam-instrument-run.ps1')) { Copy-Item -LiteralPath (Join-Path $FromDir $c1alLib) -Destination (Join-Path $Dir $c1alLib) -Force }
    $c1alCopy = Join-Path $Dir 'mission-goal-check.ps1'
    $c1alSrc = [System.IO.File]::ReadAllText($c1alCopy)
    $c1alOpen = '$script:HaltLegacyCensusText = @' + "'"
    $c1alHits = ([regex]::Matches($c1alSrc, [regex]::Escape($c1alOpen))).Count
    if ($c1alHits -eq 1) {
        $c1alAt = $c1alSrc.IndexOf($c1alOpen) + $c1alOpen.Length
        $c1alEol = if ($c1alSrc.Contains("`r`n")) { "`r`n" } else { "`n" }
        [System.IO.File]::WriteAllText($c1alCopy, ($c1alSrc.Substring(0, $c1alAt) + $c1alEol + $Member + $c1alSrc.Substring($c1alAt)), (New-Object System.Text.UTF8Encoding($false)))
        return [pscustomobject]@{ ok = $true; path = $c1alCopy }
    }
    $c1alFile = Join-Path $Dir 'legacy-halt-census.txt'
    $c1alReads = ($c1alHits -eq 0) -and $c1alSrc.Contains("'legacy-halt-census.txt'")
    if ($c1alReads) { [System.IO.File]::WriteAllText($c1alFile, ("# the one line of WP-3 C-1al row (m)`n" + $Member + "`n"), (New-Object System.Text.UTF8Encoding($false))) }
    return [pscustomobject]@{ ok = ($c1alReads -and ((Get-FileHash -Algorithm SHA256 -LiteralPath $c1alCopy).Hash -ceq (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $FromDir 'mission-goal-check.ps1')).Hash)); path = $c1alCopy }
}
$c1alCensusT = New-C1alCensusTools -FromDir (Split-Path -Parent $goalCheck) -Dir (Join-Path $c1alM.base 'census-tree') -Member $c1alHaltMember
$c1alCensusB = New-C1alCensusTools -FromDir (Split-Path -Parent $c1alBase.path) -Dir (Join-Path $c1alM.base 'census-base') -Member $c1alHaltMember
Set-PwBytes -Path (Join-Path $c1alRoot '.mission-runtime\halts\HALT-WL-01.md') -Bytes $c1alHaltBytes
$c1alMT = Get-C1alReading -GoalId 'G-NHALT' -Evaluator $c1alCensusT.path -Hook
$c1alMB = Get-C1alReading -GoalId 'G-NHALT' -Evaluator $c1alCensusB.path -Hook
$c1alMTAns = @(Get-PwListKey -Text $c1alMT.text -Key 'halts_answered_by_legacy_allowlist')
$c1alMBAns = @(Get-PwListKey -Text $c1alMB.text -Key 'halts_answered_by_legacy_allowlist')
Add-C1alRow -Label '(m) THE HALT SCOPE, THE ALLOWLIST: a goal answering a legacy HALT by its allowlist, with reuse_within_minutes: 30  # thirty minutes -- the HALT is still ANSWERED by the allowlist, the verdict NOT_MET, the hook BLOCKS, goal_parse naming line 9; as at the base, which blocks on the failing detector' `
    -Ok ($c1alCensusT.ok -and $c1alCensusB.ok -and ($c1alMT.decision -ceq 'block') -and ($c1alMT.verdict -ceq 'NOT_MET') -and ($c1alMT.ran -eq 0) -and ($c1alMTAns.Count -eq 1) -and ([string]$c1alMTAns[0]).StartsWith($c1alHaltMember + ' -- ') -and
         ($c1alMT.text -match '(?m)^open_halts: \[\]') -and $c1alMT.parse.Contains((Get-C1alFault -Line 9 -Key 'reuse_within_minutes' -Value '30  # thirty minutes' -Min 0 -Type 'instrument_exit0')) -and
         ($c1alMB.decision -ceq 'block') -and ($c1alMB.verdict -ceq 'NOT_MET') -and ($c1alMBAns.Count -eq 1) -and (-not $c1alMB.parseFound)) `
    -Said ('tree: ' + $c1alMT.decision + ', ' + $c1alMT.verdict + ', answered by allowlist ' + $c1alMTAns.Count + ', ran ' + $c1alMT.ran + '; base: ' + $c1alMB.decision + ', ' + $c1alMB.verdict + ', answered ' + $c1alMBAns.Count + '; tree reason: ' + $c1alMT.reason)
Remove-Item -LiteralPath (Join-Path $c1alRoot '.mission-runtime\halts\HALT-WL-01.md') -Force
# (n) THE HALT SCOPE IS KEPT -- A DECLARED dir: an OPEN HALT in the directory the goal's halt_absent names, and
#     a number that is not one. A HALT outranks the refusal, as it outranks everything: the verdict is HALT and
#     control returns to the human -- and the refusal is still on the artifact. (With the scope dropped the
#     declared directory was not scanned and the HALT was not seen.)
Set-PwBytes -Path (Join-Path $c1alRoot 'custom-halts\HALT-WL-02.md') -Bytes ($pwUtf8.GetBytes("# HALT-WL-02`n`n**Status:** UNANSWERED`n"))
$c1alNT = Get-C1alReading -GoalId 'G-NHDIR' -Hook
$c1alNB = Get-C1alReading -GoalId 'G-NHDIR' -Evaluator $c1alBase.path -Hook
Add-C1alRow -Label '(n) THE HALT SCOPE, A DECLARED dir: an OPEN HALT in the directory the goal''s halt_absent names, with cap: many -- the HALT is SEEN and outranks the refusal: verdict HALT, the hook approves naming it, as at the base; goal_parse is still on the artifact, naming line 6' `
    -Ok (($c1alNT.verdict -ceq 'HALT') -and ($c1alNT.decision -ceq 'approve') -and $c1alNT.reason.Contains('derives HALT: unanswered HALT-WL-02.md') -and $c1alNT.parseFound -and
         $c1alNT.parse.Contains((Get-C1alFault -Line 6 -Key 'cap' -Value 'many' -Min 1 -Type 'turn_cap')) -and ($c1alNB.verdict -ceq 'HALT') -and ($c1alNB.decision -ceq 'approve')) `
    -Said ('tree: ' + $c1alNT.verdict + ', ' + $c1alNT.decision + '; base: ' + $c1alNB.verdict + '; tree reason: ' + $c1alNT.reason + ' | goal_parse: ' + $c1alNT.parse)
# (o) BATCH-6 WP-Q (a) (ruled 2026-10-16 07:2x local, lean accepted): reuse_tree_within_minutes is
#     a FIFTH key this file reads as a number -- one row more in C-1al's table -- so its value is held to the one
#     rule: a comment after it is a goal that does not parse. THE RED, KEPT: the base stores the key and reads
#     nothing of it. (The HALT (n) left open stands under a dir only G-NHDIR declares: this goal scans none.)
$c1alWantO = Get-C1alFault -Line 5 -Key 'reuse_tree_within_minutes' -Value '180  # three hours' -Min 0 -Type 'instrument_exit0'
$c1alO = Get-C1alReading -GoalId 'G-NTREE'
$c1alOB = Get-C1alReading -GoalId 'G-NTREE' -Evaluator $c1alBase.path
Add-C1alRow -Label '(o) FALSIFIER reuse_tree_within_minutes: 180  # three hours (the fifth key read as a number) -- NOT_MET, exit 1, ONE entry, goal_parse, naming line 5, the key and the value as written, from 0; the instrument is NOT run; RED at the base: the key stored and read for nothing -- MET, the instrument RUNS, no goal_parse entry' `
    -Ok (($c1alO.verdict -ceq 'NOT_MET') -and ($c1alO.exit -eq 1) -and ($c1alO.ran -eq 0) -and $c1alO.parseFound -and ($c1alO.types.Count -eq 1) -and
         $c1alO.parse.Contains('THE GOAL FILE DOES NOT PARSE -- a number it declares is not one -- ' + $c1alWantO + ' -- ') -and $c1alO.parse.Contains('(register row 385)') -and
         ($c1alOB.verdict -ceq 'MET') -and ($c1alOB.ran -eq 1) -and $c1alOB.ok -and (-not $c1alOB.parseFound)) `
    -Said ('tree: ' + $c1alO.verdict + ', exit ' + $c1alO.exit + ', ran ' + $c1alO.ran + '; goal_parse: ' + $c1alO.parse + ' | base: ' + $c1alOB.verdict + ', ran ' + $c1alOB.ran + '; detail: ' + $c1alOB.detail)
}
catch {
    $c1alOk = $false
    $c1alRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1alRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1alM) { Remove-PwTreeAsWritten -Base $c1alM.base }
Check -Id 'C-1al' -Title 'A NUMBER IN A GOAL FILE IS A WHOLE NUMBER IN ITS RANGE, OR THE GOAL DOES NOT PARSE (the BATCH-4 charter (a), as ruled 2026-10-06): a goal written reuse_within_minutes: 30  # thirty minutes over a capture seconds old read MET at the base evaluator and RAN the instrument -- the window dropped, "read as 0" in the detail of an entry that passed -- and at this tree it DOES NOT PARSE: NOT_MET, exit 1 by hand and a block as the Stop hook, one goal_parse entry naming the line, the key and the value as written, goal_parse_error at column 0, and the instrument NOT run, read off a counter the instrument itself appends to; 30 alone still reuses, and so does "30"; seven digits, a sign and an empty value are refused the same way; the line named is the last one that set the key, and the item''s first line where the key opens it; validator_pass_count''s count: 4  # four, which at the base asked for no result and passed ("0 of 0 required"), and count: 0, are refused; turn_cap''s cap and time_cap''s minutes, which failed closed already in a sentence naming neither value nor cause, are refused by name; two numbers that are not, in one goal, are both named in one entry and no detector beside them runs; a numeric key under a type that does not read it is not tested, the artifact the base''s byte for byte; every goal file git tracks in this tree, read through the evaluator''s own reader and rule lifted by AST, declares only numbers the rule admits, the reader returning the same items with its line log as without it; 999999 is admitted under each of the four keys and 1000000 refused; and THE HALT SCOPE IS KEPT -- a goal that answers a legacy HALT by its allowlist and declares a number that is not one still answers that HALT, so the verdict is NOT_MET and the hook blocks, driven through copies of this tree''s and the base''s evaluator whose legacy census holds the fixture''s one line, and an OPEN HALT in a directory the goal''s halt_absent declares is still seen and outranks the refusal, as at the base; and (BATCH-6 WP-Q) reuse_tree_within_minutes is a fifth key read as a number under the same rule -- 180  # three hours is refused by name, the instrument not run, where the base stores the key, reads nothing of it and runs the instrument' `
      -Ok $c1alOk -Detail ("      THE $(@($c1alRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1alRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument every instrument_exit0 goal here names:`n" + (Get-WlIndented -Text $c1alInstText))

# =============================================================================================
# C-2f -- AN ABSENT GOAL WHOSE VERDICT CANNOT BE WRITTEN BLOCKS: the absent goal is an
#         admitted stop as a RECORDED one, or not at all
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: with no goal file and its
# verdict artifact unwritable, the hook prints `approve` and exits 0 -- "an approve with no written verdict",
# the route an earlier sentence had left through the absent goal's branch. THE THREE CASES the branch itself
# names, each driven: the write THROWS (a DIRECTORY at the artifact's path; the artifact held by another
# process with no sharing); the id is NOT ONE TOKEN; the mission root has NO .mission directory. THE
# CONTROLS: where the verdict CAN be written the absent goal is admitted exactly as it was, the hook's
# stdout and the artifact the base's byte for byte; with the cause cleared the same stop is admitted again;
# and a dispatched worker is approved above all of it, as before.
# THE STREAMS ARE READ APART (Invoke-WlHookStreams): the ruling puts the reason on STDERR beside the decision.
$c2fOk = $true
$c2fRows = New-Object System.Collections.Generic.List[string]
function Add-C2fRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c2fOk = $false }
    $script:c2fRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c2fRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Test-C2fBlocked {
    # ONE reading of Invoke-WlHookStreams, held to the rule: decision block, exit 0, the reason opening on the
    # NOT_MET sentence and carrying -Why, the same reason on stderr as one line, and nothing but the JSON on stdout.
    param($Reading, [string]$GoalId, [string]$Why)
    $c2fOpen = "Goal '" + $GoalId + "' is NOT_MET: GOAL_ABSENT, AND ITS VERDICT COULD NOT BE WRITTEN -- no goal file for '" + $GoalId + "'."
    $c2fOutLines = @(($Reading.stdout -replace "`r", '') -split "`n" | Where-Object { $_.Trim() })
    return (($Reading.decision -ceq 'block') -and ($Reading.exit -eq 0) -and $Reading.reason.StartsWith($c2fOpen) -and $Reading.reason.Contains('the stop is REFUSED (register row 376: an absent goal is not approved without a written verdict). No verdict file was written: ') -and
            $Reading.reason.Contains($Why) -and ($Reading.stderr.Trim() -ceq ('goal-check: ' + $Reading.reason)) -and ($c2fOutLines.Count -eq 1) -and $c2fOutLines[0].Trim().StartsWith('{'))
}
$c2fM = $null
$c2fHeld = $null
try {
$c2fM = New-EsMission -Tag 'c2f'
if (-not $c2fM.ok) { throw ('FIXTURE REFUSED: ' + $c2fM.why) }
$c2fRoot = $c2fM.root
$c2fBase = New-WlBaseTools -Dir (Join-Path $c2fM.base 'base-tools')
$c2fVf = Join-Path $c2fRoot '.mission\goals\G-GONE.verdict.yaml'

# (a) CONTROL, FIRST: the verdict CAN be written. Admitted and recorded, this tree as the base, byte for byte.
$c2fAT = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE'
$c2fATText = Remove-WrProvenanceLine -Text $c2fAT.text
Remove-Item -LiteralPath $c2fVf -Force -ErrorAction SilentlyContinue
$c2fAB = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE' -Evaluator $c2fBase.path
Remove-Item -LiteralPath $c2fVf -Force -ErrorAction SilentlyContinue
Add-C2fRow -Label '(a) CONTROL no goal file, the verdict writable: approve, exit 0, GOAL_ABSENT recorded, nothing on stderr -- the hook''s stdout the base''s byte for byte, and the artifact the base''s but for its clock' `
    -Ok ($c2fBase.ok -and ($c2fAT.decision -ceq 'approve') -and ($c2fAT.exit -eq 0) -and ($c2fAT.verdict -ceq $esAbsVerdict) -and (-not $c2fAT.stderr.Trim()) -and ($c2fAT.stdout -ceq $c2fAB.stdout) -and
         ((Get-WlMasked -Text $c2fATText) -ceq (Get-WlMasked -Text $c2fAB.text)) -and $c2fAT.reason.Contains('Verdict: ' + $c2fVf)) `
    -Said ('tree ' + $c2fAT.decision + '/' + $c2fAT.verdict + '; stdout equal: ' + ($c2fAT.stdout -ceq $c2fAB.stdout) + '; ' + $c2fBase.said)

# (b) THE FALSIFIER: the write THROWS -- a DIRECTORY stands where the artifact goes.
New-Item -ItemType Directory -Path $c2fVf -Force | Out-Null
$c2fB = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE'
Add-C2fRow -Label '(b) FALSIFIER no goal file and a DIRECTORY at its verdict artifact''s path: the hook BLOCKS -- decision block, exit 0, NOT_MET the word -- the reason saying the write failed, the same reason one line on STDERR, the JSON alone on stdout' `
    -Ok ((Test-C2fBlocked -Reading $c2fB -GoalId 'G-GONE' -Why ('No verdict file was written: writing ' + $c2fVf + ' failed (')) -and (Test-Path -LiteralPath $c2fVf -PathType Container)) `
    -Said ('decision ' + $c2fB.decision + ', exit ' + $c2fB.exit + '; stderr: ' + $c2fB.stderr.Trim() + ' | reason: ' + $c2fB.reason)
$c2fBHand = Invoke-WjHook -Root $c2fRoot -GoalId 'G-GONE' -ByHand
$c2fBHandLines = @(($c2fBHand.out -replace "`r", '') -split "`n")
Add-C2fRow -Label '(b) FALSIFIER ... by hand: exit 2 as an absent goal always was, the status line reading NOT_MET, the refusal under it, and "verdict : none" with the cause' `
    -Ok (($c2fBHand.exit -eq 2) -and ($c2fBHandLines -ccontains 'mission-goal-check: G-GONE -> NOT_MET') -and $c2fBHand.out.Contains('  GOAL_ABSENT, AND ITS VERDICT COULD NOT BE WRITTEN -- no goal file for ''G-GONE''.') -and $c2fBHand.out.Contains('  verdict   : none -- writing ' + $c2fVf + ' failed (')) `
    -Said ('exit ' + $c2fBHand.exit + '; ' + ($c2fBHandLines -join ' | '))
# (c) THE RED, KEPT: the base evaluator over the same directory.
$c2fC = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE' -Evaluator $c2fBase.path
$c2fCHand = Invoke-WjHook -Root $c2fRoot -GoalId 'G-GONE' -ByHand -Evaluator $c2fBase.path
Add-C2fRow -Label '(c) RED at the base, the same directory: approve, exit 0, "No verdict file was written ... Not blocking.", nothing on stderr -- an approve with no written verdict; by hand exit 2 and "-> GOAL_ABSENT"' `
    -Ok (($c2fC.decision -ceq 'approve') -and ($c2fC.exit -eq 0) -and $c2fC.reason.Contains('No verdict file was written: writing ' + $c2fVf + ' failed (') -and $c2fC.reason.EndsWith(' Not blocking.') -and (-not $c2fC.stderr.Trim()) -and
         ($c2fCHand.exit -eq 2) -and $c2fCHand.out.Contains('mission-goal-check: G-GONE -> ' + $esAbsVerdict)) `
    -Said ('base: ' + $c2fC.decision + ', exit ' + $c2fC.exit + '; reason: ' + $c2fC.reason)
# (d) THE WORKER GUARD STANDS ABOVE IT: a dispatched worker over the same directory is approved, as at the base.
$c2fDT = Invoke-WjHook -Root $c2fRoot -GoalId 'G-GONE' -Dispatch 'D-WL-WORKER'
$c2fDB = Invoke-WjHook -Root $c2fRoot -GoalId 'G-GONE' -Dispatch 'D-WL-WORKER' -Evaluator $c2fBase.path
Add-C2fRow -Label '(d) CONTROL a dispatched worker (LAM_DISPATCH set) over the same directory: approved, exit 0, its output the base''s byte for byte -- the worker guard stands above the absent goal''s branch' `
    -Ok (($c2fDT.decision -ceq 'approve') -and ($c2fDT.exit -eq 0) -and $c2fDT.reason.Contains('dispatched worker ''D-WL-WORKER''') -and ($c2fDT.out -ceq $c2fDB.out)) -Said ('tree: ' + $c2fDT.out.Trim())
# (e) THE CAUSE CLEARED: the directory gone, the same stop is admitted and recorded again.
[System.IO.Directory]::Delete($c2fVf)
$c2fE = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE'
Add-C2fRow -Label '(e) CONTROL the directory removed: the same stop is ADMITTED again -- approve, exit 0, GOAL_ABSENT written' `
    -Ok (($c2fE.decision -ceq 'approve') -and ($c2fE.exit -eq 0) -and ($c2fE.verdict -ceq $esAbsVerdict) -and (Test-Path -LiteralPath $c2fVf -PathType Leaf)) -Said ('decision ' + $c2fE.decision + '; verdict ' + $c2fE.verdict)
# (f) THE WRITE THROWS, ANOTHER WAY: the artifact is a file another process holds with no sharing.
$c2fHeld = [System.IO.File]::Open($c2fVf, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try {
    $c2fF = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE'
    $c2fFB = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G-GONE' -Evaluator $c2fBase.path
} finally { $c2fHeld.Dispose(); $c2fHeld = $null }
Add-C2fRow -Label '(f) FALSIFIER the artifact held by another process with no sharing: the hook BLOCKS, the reason saying the write failed, on stderr too; RED at the base: approve, exit 0' `
    -Ok ((Test-C2fBlocked -Reading $c2fF -GoalId 'G-GONE' -Why ('No verdict file was written: writing ' + $c2fVf + ' failed (')) -and ($c2fFB.decision -ceq 'approve') -and ($c2fFB.exit -eq 0) -and $c2fFB.reason.Contains('No verdict file was written')) `
    -Said ('tree: ' + $c2fF.decision + ' -- ' + $c2fF.reason + ' | base: ' + $c2fFB.decision)
Remove-Item -LiteralPath $c2fVf -Force -ErrorAction SilentlyContinue
# (g) THE ID IS NOT ONE TOKEN: no file is named for it, so none is written.
$c2fG = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G GONE'
$c2fGB = Invoke-WlHookStreams -Root $c2fRoot -GoalId 'G GONE' -Evaluator $c2fBase.path
Add-C2fRow -Label '(g) FALSIFIER an id with a space (G GONE), for which no file is named: the hook BLOCKS, the reason saying the id is not one token; nothing is written; RED at the base: approve, exit 0' `
    -Ok ((Test-C2fBlocked -Reading $c2fG -GoalId 'G GONE' -Why 'No verdict file was written: the goal id ''G GONE'' is not one token') -and (-not (Test-Path -LiteralPath (Join-Path $c2fRoot '.mission\goals\G GONE.verdict.yaml'))) -and
         ($c2fGB.decision -ceq 'approve') -and ($c2fGB.exit -eq 0) -and $c2fGB.reason.Contains('is not one token')) `
    -Said ('tree: ' + $c2fG.decision + ' -- ' + $c2fG.reason + ' | base: ' + $c2fGB.decision)
# (h) NO MISSION PLANE AT ALL: a mission root with no .mission directory. The misconfigured hook fails closed.
$c2fBare = Join-Path $c2fM.base 'bare'
New-Item -ItemType Directory -Path $c2fBare -Force | Out-Null
$c2fH = Invoke-WlHookStreams -Root $c2fBare -GoalId 'G-GONE'
$c2fHB = Invoke-WlHookStreams -Root $c2fBare -GoalId 'G-GONE' -Evaluator $c2fBase.path
Add-C2fRow -Label '(h) FALSIFIER a mission root with no .mission directory: the hook BLOCKS, the reason saying there is no mission plane to write into; nothing is created; RED at the base: approve, exit 0' `
    -Ok ((Test-C2fBlocked -Reading $c2fH -GoalId 'G-GONE' -Why '.mission is not a directory, so there is no mission plane to write it into') -and (-not (Test-Path -LiteralPath (Join-Path $c2fBare '.mission'))) -and
         ($c2fHB.decision -ceq 'approve') -and ($c2fHB.exit -eq 0) -and $c2fHB.reason.Contains('is not a directory')) `
    -Said ('tree: ' + $c2fH.decision + ' -- ' + $c2fH.reason + ' | base: ' + $c2fHB.decision)
# (i) CONTROL: a mission root whose .mission holds no goals directory -- the directory is made and the verdict
#     written, so the stop is admitted, as before.
$c2fNoGoals = Join-Path $c2fM.base 'nogoals'
New-Item -ItemType Directory -Path (Join-Path $c2fNoGoals '.mission') -Force | Out-Null
$c2fI = Invoke-WlHookStreams -Root $c2fNoGoals -GoalId 'G-GONE'
Add-C2fRow -Label '(i) CONTROL a .mission with no goals directory: the directory is made, the verdict written, the stop ADMITTED -- approve, exit 0, nothing on stderr' `
    -Ok (($c2fI.decision -ceq 'approve') -and ($c2fI.exit -eq 0) -and ($c2fI.verdict -ceq $esAbsVerdict) -and (-not $c2fI.stderr.Trim())) -Said ('decision ' + $c2fI.decision + '; verdict ' + $c2fI.verdict)
# (j) WHAT THIS ROW'S RULE DID NOT REACH -- AND C-1av's RULE NOW DOES (the builder-side review's
#     finding measured it here; the operator's ruling). A -MissionRoot that is no
#     directory at all is answered ABOVE the goal search, by its own block. Until that rule the block still
#     APPROVED with nothing written -- this tree as the base, byte for byte: another rule's case,
#     not this member's. SINCE THAT RULE THE BLOCK REFUSES THE STOP, in the form this member's own refusals take:
#     block alone on stdout, exit 0, the same reason one line on stderr -- its sentence its own, not this
#     member's. The row is RE-ASSERTED TO THE RULE and its equality with the base dropped; THE BASE
#     IS KEPT AS ITS RED CONTROL, the row under it. The falsifier's home is C-1av, which drives a file, the
#     empty string and the hand-run as well; this row keeps the reading where it was first measured.
$c2fNoRoot = Join-Path $c2fM.base 'no-such-root'
$c2fJ = Invoke-WlHookStreams -Root $c2fNoRoot -GoalId 'G-GONE'
$c2fJB = Invoke-WlHookStreams -Root $c2fNoRoot -GoalId 'G-GONE' -Evaluator $c2fBase.path
$c2fJOutLines = @(($c2fJ.stdout -replace "`r", '') -split "`n" | Where-Object { $_.Trim() })
Add-C2fRow -Label '(j) a mission root that is no directory at all: since C-1av''s rule the hook BLOCKS -- decision block, exit 0, the reason opening "Goal ''G-GONE'' is NOT_MET: the mission root" and saying it "is not a directory, so no goal can be read and no verdict written (register row 401).", the same reason one line on STDERR, the JSON alone on stdout; nothing is created at the path' `
    -Ok (($c2fJ.decision -ceq 'block') -and ($c2fJ.exit -eq 0) -and $c2fJ.reason.StartsWith("Goal 'G-GONE' is NOT_MET: the mission root '") -and $c2fJ.reason.Contains('is not a directory, so no goal can be read and no verdict written (register row 401).') -and
         ($c2fJ.stderr.Trim() -ceq ('goal-check: ' + $c2fJ.reason)) -and ($c2fJOutLines.Count -eq 1) -and $c2fJOutLines[0].Trim().StartsWith('{') -and (-not (Test-Path -LiteralPath $c2fNoRoot))) `
    -Said ('tree: ' + $c2fJ.decision + ', exit ' + $c2fJ.exit + '; stderr: ' + $c2fJ.stderr.Trim() + ' | stdout: ' + $c2fJ.stdout.Trim())
Add-C2fRow -Label '(j) BASE CONTROL: RED at the base, the same root: approve, exit 0, "goal-check: mission root not found: <root> -- not blocking.", nothing on stderr, nothing written -- a hook whose root is no directory admitted the stop' `
    -Ok ($c2fBase.ok -and ($c2fJB.decision -ceq 'approve') -and ($c2fJB.exit -eq 0) -and $c2fJB.reason.StartsWith('goal-check: mission root not found: ') -and $c2fJB.reason.EndsWith(' -- not blocking.') -and (-not $c2fJB.stderr.Trim()) -and (-not (Test-Path -LiteralPath $c2fNoRoot))) `
    -Said ('base: ' + $c2fJB.stdout.Trim())
}
catch {
    $c2fOk = $false
    $c2fRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c2fRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c2fHeld) { try { $c2fHeld.Dispose() } catch { } }
if ($null -ne $c2fM) { Remove-PwTreeAsWritten -Base $c2fM.base }
Check -Id 'C-2f' -Title 'AN ABSENT GOAL WHOSE VERDICT CANNOT BE WRITTEN BLOCKS (the BATCH-4 charter (b), as ruled 2026-10-06): with no goal file and its verdict artifact unwritable the base evaluator printed approve and exited 0 -- an approve with no written verdict -- and this tree BLOCKS, in each of the three cases the branch names: the write throws (a directory at the artifact''s path; the artifact held by another process with no sharing), the id is not one token, the mission root has no .mission directory; the decision is block on stdout, exit 0, the form NOT_MET blocks in, its reason opening "Goal ''<id>'' is NOT_MET" and saying why no verdict file was written, and the same reason stands one line on STDERR, the streams read apart; by hand the exit is 2 as it was and the status line reads NOT_MET; nothing is created where nothing could be; where the verdict CAN be written the absent goal is admitted and recorded exactly as before -- the hook''s stdout the base''s byte for byte, the artifact the base''s but for its clock -- also where only the goals directory was missing; with the directory removed the same stop is admitted again; a dispatched worker is still approved above all of it, its output the base''s; and what this row''s rule did not reach, C-1av''s rule has since closed -- a mission root that is no directory at all approved with nothing written at the base, which is kept as that rule''s control, and this tree now BLOCKS it too: block alone on stdout, exit 0, its reason saying the root is not a directory, the same reason one line on stderr (C-1av is that rule''s own member)' `
      -Ok $c2fOk -Detail ("      THE $(@($c2fRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c2fRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- this member has no stub script: it names a goal id no file exists for, plants a DIRECTORY (then holds a FILE) at`n          | <root>\.mission\goals\G-GONE.verdict.yaml`n      and sends the Stop payload on stdin, reading the hook's stdout and stderr apart:`n          | " + (@{ session_id = 'wp3-wl'; hook_event_name = 'Stop' } | ConvertTo-Json -Compress))

# =============================================================================================
# C-1am -- THE GOAL'S OWN VERDICT ARTIFACT IS NEVER A BRIEF: a HANDOFF head that names
#          the artifact every evaluation rewrites is refused, under every name the artifact has
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a head naming
# .mission/goals/<goal>.verdict.yaml with the artifact's own digests is ADMITTED, the evaluation that admits
# it REWRITES the artifact, and the head rewritten to the artifact's new digests is admitted AGAIN -- a stop
# at every stop with no brief written, C-1aj's loop through another file. THE CONTROLS: the admissions
# record is UNTOUCHED by a refused head (its sha256, before and after); an ordinary brief still admits once
# with the artifact on disk; a COPY of the artifact at another path is another file; the record named as
# the brief is still refused in the record's own words; and while another process holds the artifact the
# arm cannot establish that a brief is not it, and refuses.
# EVERY HOOK HERE GOES THROUGH Invoke-WjHook, which leaves the prior artifact where it is: the artifact has
# to exist to be named.
$c1amOk = $true
$c1amRows = New-Object System.Collections.Generic.List[string]
function Add-C1amRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1amOk = $false }
    $script:c1amRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1amRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Set-C1amHead {
    # STATUS.md's head naming -PathAsWritten, both digests the sha256 of -Target's bytes as they stand now.
    param([string]$PathAsWritten, [string]$Target)
    $c1amSha = Get-PwRawSha -Path $Target
    Write-EsStatus -Root $script:c1amRoot -Head (Get-EsHead -Ctx '60' -Lf $c1amSha -Raw $c1amSha -Path $PathAsWritten)
}
function Invoke-C1amHook {
    # One Stop hook over G-HOV, the prior artifact left in place; with it the handoff_refused list, and the
    # admissions record's sha256 and line count as the hook left them.
    param([string]$Evaluator)
    $c1amH = if ($Evaluator) { Invoke-WjHook -Root $script:c1amRoot -GoalId 'G-HOV' -Evaluator $Evaluator } else { Invoke-WjHook -Root $script:c1amRoot -GoalId 'G-HOV' }
    $c1amRecNow = Get-EsRecord -Root $script:c1amRoot
    return [pscustomobject]@{ exit = $c1amH.exit; decision = $c1amH.decision; reason = $c1amH.reason; verdict = $c1amH.verdict; text = $c1amH.text
                              admitted = (($c1amH.decision -ceq 'approve') -and ($c1amH.exit -eq 0))
                              refused = @(Get-PwListKey -Text $c1amH.text -Key 'handoff_refused')
                              lines = $c1amRecNow.count; recSha = $(if ($c1amRecNow.exists) { Get-PwRawSha -Path $c1amRecNow.path } else { '(no record)' }) }
}
$c1amM = $null
$c1amHeld = $null
try {
$c1amM = New-EsMission -Tag 'c1am'
if (-not $c1amM.ok) { throw ('FIXTURE REFUSED: ' + $c1amM.why) }
$c1amRoot = $c1amM.root
$c1amBase = New-WlBaseTools -Dir (Join-Path $c1amM.base 'base-tools')
$c1amArtRel = '.mission/goals/G-HOV.verdict.yaml'
$c1amArt = Join-Path $c1amRoot '.mission\goals\G-HOV.verdict.yaml'
$c1amRecRel = '.mission-runtime/lam/handoff-admissions.jsonl'
Write-PwGoal -Root $c1amRoot -GoalId 'G-HOV' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))

# (a) CONTROL, AND THE FIXTURE'S ARTIFACT AND RECORD: an ordinary brief is admitted once -- one record line --
#     and the evaluation writes the goal's verdict artifact, which is what the rows below name.
$c1amBriefA = Write-EsBytes -Root $c1amRoot -Rel '.mission-runtime/lam/handoff/brief-a.md' -Bytes ($pwUtf8.GetBytes("an ordinary brief`n"))
Set-C1amHead -PathAsWritten '.mission-runtime/lam/handoff/brief-a.md' -Target $c1amBriefA
$c1amA1 = Invoke-C1amHook
$c1amA2 = Invoke-C1amHook
Add-C1amRow -Label '(a) CONTROL an ordinary brief: ADMITTED once (HANDOFF_ADMITTED, approve, exit 0), then refused as already admitted; the record at 1 line; the verdict artifact on disk' `
    -Ok ($c1amBase.ok -and $c1amA1.admitted -and ($c1amA1.verdict -ceq $esHoVerdict) -and ($c1amA2.decision -ceq 'block') -and $c1amA2.reason.Contains('already admitted') -and ($c1amA2.lines -eq 1) -and (Test-Path -LiteralPath $c1amArt -PathType Leaf)) `
    -Said ('first ' + $c1amA1.verdict + '/' + $c1amA1.decision + ', second ' + $c1amA2.verdict + '/' + $c1amA2.decision + '; ' + $c1amBase.said)

# (b) THE FALSIFIER, AT THE BASE: the artifact named as the brief is admitted, rewritten, and admitted again.
Set-C1amHead -PathAsWritten $c1amArtRel -Target $c1amArt
$c1amShaB0 = Get-PwRawSha -Path $c1amArt
$c1amB1 = Invoke-C1amHook -Evaluator $c1amBase.path
$c1amShaB1 = Get-PwRawSha -Path $c1amArt
Set-C1amHead -PathAsWritten $c1amArtRel -Target $c1amArt
$c1amB2 = Invoke-C1amHook -Evaluator $c1amBase.path
Add-C1amRow -Label '(b) RED at the base: a head naming the goal''s own verdict artifact, its digests the artifact''s own, is ADMITTED; the evaluation REWRITES the artifact; the head rewritten to its new digests is ADMITTED AGAIN -- the record at 2, then 3 lines, no brief written' `
    -Ok ($c1amB1.admitted -and ($c1amB1.verdict -ceq $esHoVerdict) -and ($c1amB1.lines -eq 2) -and ($c1amShaB1 -cne $c1amShaB0) -and $c1amB2.admitted -and ($c1amB2.verdict -ceq $esHoVerdict) -and ($c1amB2.lines -eq 3)) `
    -Said ('base: ' + $c1amB1.verdict + ' (' + $c1amB1.lines + ' lines), ' + $c1amB2.verdict + ' (' + $c1amB2.lines + ' lines); the artifact''s sha256 moved: ' + ($c1amShaB1 -cne $c1amShaB0))
# ... AND A HARD LINK TO THE ARTIFACT, at the base: the same file under another name.
$c1amLink = Join-Path $c1amRoot 'evidence\artifact-link.yaml'
$null = New-Item -ItemType HardLink -Path $c1amLink -Target $c1amArt
Set-C1amHead -PathAsWritten 'evidence/artifact-link.yaml' -Target $c1amLink
$c1amB3 = Invoke-C1amHook -Evaluator $c1amBase.path
Add-C1amRow -Label '(b) ... RED at the base: a HARD LINK to the artifact named as the brief is ADMITTED too -- 4 lines' `
    -Ok ($c1amB3.admitted -and ($c1amB3.verdict -ceq $esHoVerdict) -and ($c1amB3.lines -eq 4)) -Said ('base: ' + $c1amB3.verdict + ' (' + $c1amB3.lines + ' lines)')

# (c) GREEN: the artifact under each of its names is REFUSED by this tree, and THE ADMISSIONS RECORD IS UNTOUCHED.
$c1amRecBefore = (Invoke-C1amHook).recSha
$c1amLinesBefore = (Get-EsRecord -Root $c1amRoot).count
$c1amSpellings = @(
    [pscustomobject]@{ label = 'its relative path, as the evaluator writes it'; path = $c1amArtRel; say = 'its path is the verdict artifact''s own' },
    [pscustomobject]@{ label = 'its ABSOLUTE path'; path = $c1amArt; say = 'its path is the verdict artifact''s own' },
    [pscustomobject]@{ label = 'backslashes and UPPER CASE'; path = '.MISSION\GOALS\G-HOV.VERDICT.YAML'; say = 'its path is the verdict artifact''s own' },
    [pscustomobject]@{ label = 'a dot-segment path'; path = '.mission/goals/../goals/G-HOV.verdict.yaml'; say = 'its path is the verdict artifact''s own' },
    [pscustomobject]@{ label = 'a HARD LINK to it'; path = 'evidence/artifact-link.yaml'; say = 'so it is the verdict artifact under another name' },
    [pscustomobject]@{ label = 'a directory JUNCTION in its path'; path = 'evidence/goals-link/G-HOV.verdict.yaml'; say = 'so it is the verdict artifact under another name' })
$c1amJunction = Join-Path $c1amRoot 'evidence\goals-link'
$null = New-Item -ItemType Junction -Path $c1amJunction -Target (Join-Path $c1amRoot '.mission\goals')
foreach ($c1amSp in $c1amSpellings) {
    $c1amTarget = if ($c1amSp.path -ceq 'evidence/artifact-link.yaml') { $c1amLink } else { $c1amArt }
    Set-C1amHead -PathAsWritten $c1amSp.path -Target $c1amTarget
    $c1amC = Invoke-C1amHook
    Add-C1amRow -Label ('(c) FALSIFIER the artifact named as the brief by ' + $c1amSp.label + ': REFUSED -- the hook blocks, NOT_MET, the reason and handoff_refused saying the artifact is never a brief; THE ADMISSIONS RECORD UNTOUCHED (its sha256)') `
        -Ok (($c1amC.decision -ceq 'block') -and ($c1amC.exit -eq 0) -and ($c1amC.verdict -ceq 'NOT_MET') -and $c1amC.reason.Contains('HANDOFF head NOT admitted -- the head names the goal''s own verdict artifact as the brief (') -and
             $c1amC.reason.Contains($c1amSp.say) -and $c1amC.reason.Contains('it is never a brief (register row 377)') -and (@($c1amC.refused).Count -eq 1) -and
             ([string]@($c1amC.refused)[0]).Contains('it is never a brief (register row 377)') -and ($c1amC.recSha -ceq $c1amRecBefore) -and ($c1amC.lines -eq $c1amLinesBefore)) `
        -Said ('decision ' + $c1amC.decision + '; record ' + $c1amC.lines + ' line(s), sha256 ' + $c1amC.recSha.Substring(0, 8) + ' (before: ' + $c1amLinesBefore + ', ' + $c1amRecBefore.Substring(0, 8) + '); reason: ' + $c1amC.reason)
}
[System.IO.Directory]::Delete($c1amJunction)

# (d) CONTROL: the record named as the brief is still refused, in the RECORD's words -- not the artifact's.
Set-C1amHead -PathAsWritten $c1amRecRel -Target (Join-Path $c1amRoot '.mission-runtime\lam\handoff-admissions.jsonl')
$c1amD = Invoke-C1amHook
Add-C1amRow -Label '(d) CONTROL the admissions record named as the brief: refused as C-1aj has it, word for word -- "the admissions record itself", "its path is the record''s own" -- and not as the artifact' `
    -Ok (($c1amD.decision -ceq 'block') -and $c1amD.reason.Contains('HANDOFF head NOT admitted -- the head names the admissions record itself as the brief (') -and $c1amD.reason.Contains(': its path is the record''s own); the record is this arm''s own account of the briefs already spent') -and
         $c1amD.reason.Contains('it is never a brief (register row 360 member (1))') -and (-not $c1amD.reason.Contains('verdict artifact as the brief')) -and ($c1amD.recSha -ceq $c1amRecBefore)) `
    -Said ('reason: ' + $c1amD.reason)
# (e) CONTROL: an ordinary brief still admits once, with the artifact on disk and asked about at every stop.
$c1amBriefB = Write-EsBytes -Root $c1amRoot -Rel '.mission-runtime/lam/handoff/brief-b.md' -Bytes ($pwUtf8.GetBytes("a second ordinary brief`n"))
Set-C1amHead -PathAsWritten '.mission-runtime/lam/handoff/brief-b.md' -Target $c1amBriefB
$c1amE1 = Invoke-C1amHook
$c1amE2 = Invoke-C1amHook
Add-C1amRow -Label '(e) CONTROL a new ordinary brief, the artifact on disk: ADMITTED once -- the record one line longer -- then refused as already admitted' `
    -Ok ($c1amE1.admitted -and ($c1amE1.verdict -ceq $esHoVerdict) -and ($c1amE1.lines -eq ($c1amLinesBefore + 1)) -and ($c1amE2.decision -ceq 'block') -and $c1amE2.reason.Contains('already admitted') -and ($c1amE2.lines -eq ($c1amLinesBefore + 1))) `
    -Said ('first ' + $c1amE1.verdict + ' (' + $c1amE1.lines + ' lines), second ' + $c1amE2.decision)
# (f) CONTROL: a COPY of the artifact at another path is another file -- its bytes do not move -- and is a
#     brief like any other, once. (Recorded as a residual: the copy is not the artifact.)
$c1amCopy = Write-EsBytes -Root $c1amRoot -Rel 'evidence/artifact-copy.yaml' -Bytes ([System.IO.File]::ReadAllBytes($c1amArt))
Set-C1amHead -PathAsWritten 'evidence/artifact-copy.yaml' -Target $c1amCopy
$c1amF1 = Invoke-C1amHook
$c1amF2 = Invoke-C1amHook
Add-C1amRow -Label '(f) CONTROL a COPY of the artifact at another path: another file, a brief like any other -- ADMITTED once, then refused as already admitted' `
    -Ok ($c1amF1.admitted -and ($c1amF1.verdict -ceq $esHoVerdict) -and ($c1amF1.lines -eq ($c1amLinesBefore + 2)) -and ($c1amF2.decision -ceq 'block') -and $c1amF2.reason.Contains('already admitted')) `
    -Said ('first ' + $c1amF1.verdict + ' (' + $c1amF1.lines + ' lines), second ' + $c1amF2.decision)
# (g) WHAT CANNOT BE ESTABLISHED REFUSES: the artifact held open by another process (sharing allowed), a NEW
#     ordinary brief at the head -- the arm cannot hold the artifact alone, so it cannot say the brief is not
#     the artifact, and it refuses; released, the same head is admitted.
$c1amBriefC = Write-EsBytes -Root $c1amRoot -Rel '.mission-runtime/lam/handoff/brief-c.md' -Bytes ($pwUtf8.GetBytes("a third ordinary brief`n"))
Set-C1amHead -PathAsWritten '.mission-runtime/lam/handoff/brief-c.md' -Target $c1amBriefC
$c1amHeld = [System.IO.File]::Open($c1amArt, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
try { $c1amG1 = Invoke-C1amHook } finally { $c1amHeld.Dispose(); $c1amHeld = $null }
$c1amG2 = Invoke-C1amHook
Add-C1amRow -Label '(g) the artifact held open by another process while a new ordinary brief stands at the head: REFUSED -- it could not be established that the brief is not the artifact -- the record unmoved; released, the same head is ADMITTED' `
    -Ok (($c1amG1.decision -ceq 'block') -and $c1amG1.reason.Contains('is the goal''s own verdict artifact could not be established (the verdict artifact could not be held with no sharing: ') -and $c1amG1.reason.Contains('and the artifact is never a brief (register row 377)') -and
         ($c1amG1.lines -eq ($c1amLinesBefore + 2)) -and $c1amG2.admitted -and ($c1amG2.lines -eq ($c1amLinesBefore + 3))) `
    -Said ('held: ' + $c1amG1.decision + ' -- ' + $c1amG1.reason + ' | released: ' + $c1amG2.verdict)
# (h) CONTROL: a goal never evaluated has no artifact; a head naming where it would be names no file, as before.
Write-PwGoal -Root $c1amRoot -GoalId 'G-HOV2' -DetectorLines @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
Write-EsStatus -Root $c1amRoot -Head (Get-EsHead -Ctx '60' -Lf ('0' * 64) -Raw ('0' * 64) -Path '.mission/goals/G-HOV2.verdict.yaml')
$c1amH = Invoke-WjHook -Root $c1amRoot -GoalId 'G-HOV2'
Add-C1amRow -Label '(h) CONTROL a goal never evaluated, the head naming where its artifact would be: refused as before -- no file at the path' `
    -Ok (($c1amH.decision -ceq 'block') -and $c1amH.reason.Contains('HANDOFF head NOT admitted -- no file at')) -Said ('reason: ' + $c1amH.reason)
}
catch {
    $c1amOk = $false
    $c1amRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1amRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1amHeld) { try { $c1amHeld.Dispose() } catch { } }
if ($null -ne $c1amM) { Remove-PwTreeAsWritten -Base $c1amM.base }
Check -Id 'C-1am' -Title 'THE GOAL''S OWN VERDICT ARTIFACT IS NEVER A BRIEF (the BATCH-4 charter (c), as ruled 2026-10-06): a HANDOFF head naming the goal''s own verdict artifact as its brief, with the artifact''s own digests, is ADMITTED by the base evaluator, which rewrites the artifact as it admits, and admitted AGAIN once the head carries the artifact''s new digests -- a stop at every stop, no brief written -- and a hard link to the artifact is admitted too; this tree REFUSES it under every name driven -- its relative path, its absolute path, backslashes and upper case, a dot-segment path (each by name), a hard link and a directory junction in its path (each by identity: the brief cannot be opened while the artifact is held with no sharing, and opens once it is released) -- the hook blocking, the reason and handoff_refused saying the artifact is never a brief, and THE ADMISSIONS RECORD UNTOUCHED, its sha256 and its line count the same before and after every refusal; the admissions record named as the brief is still refused in the record''s own words; an ordinary brief is admitted once as before, with the artifact on disk; a COPY of the artifact at another path is another file and is admitted once like any brief; while another process holds the artifact the arm cannot establish that a brief is not the artifact and refuses, and admits the same head once it is released; and a head naming the artifact of a goal never evaluated is refused as naming no file' `
      -Ok $c1amOk -Detail ("      THE $(@($c1amRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1amRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- this member has no stub script: its goal G-HOV is one failing file_exists detector and the handoff arm, and the head it writes is`n          | HANDOFF AT 60% <sha256 of the named file's bytes>; <the same sha256> <the path under test>")

# =============================================================================================
# C-1an -- THE CAPTURE A REUSE CITES IS KEPT: content-addressed, beside the live
#          file, before the verdict names it; never overwritten; never a candidate
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a reuse names one path and
# one sha256 and writes nothing; the next FRESH evaluation under the same run key rewrites that path, and
# then no file under instrument-runs hashes to the sha256 the verdict cited. THE RULE: on reuse the
# evaluator first writes <key>.<leaf>.<sha8>.stdout.txt beside the live file, from the bytes it hashed; the
# detail and the key instrument_captures_kept name it. THE CONTROLS, each a row: a second reuse of the same
# capture writes nothing (the copy is read-only here, and stays reused); the name taken by OTHER bytes, or
# by a directory, is not written over -- the reuse is REFUSED and the instrument runs; a kept copy alone on
# disk is not a candidate; a goal that declares no window writes the artifact the base writes.
# THE FIXTURE is C-1ai's form, as C-1al's: the instrument under an admitted prefix, the goals committed first.
$c1anOk = $true
$c1anRows = New-Object System.Collections.Generic.List[string]
function Add-C1anRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1anOk = $false }
    $script:c1anRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1anRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1anRuns {
    $c1anCounter = Join-Path $script:c1anRoot '.mission-runtime\wl-ran.txt'
    if (-not (Test-Path -LiteralPath $c1anCounter -PathType Leaf)) { return 0 }
    return @([System.IO.File]::ReadAllLines($c1anCounter) | Where-Object { $_ }).Count
}
function Get-C1anReading {
    # One evaluation of -GoalId: how many times the instrument RAN during it, the instrument_exit0 entry, the
    # two keys, and the sha256 the detail cites.
    param([string]$GoalId, [string]$Evaluator, [switch]$Hook)
    $c1anBefore = Get-C1anRuns
    $c1anArgs = @{ Root = $script:c1anRoot; GoalId = $GoalId }
    if ($Evaluator) { $c1anArgs['Evaluator'] = $Evaluator }
    if ($Hook) { $c1anArgs['Hook'] = $true }
    $c1anEv = Invoke-EsEval @c1anArgs
    $c1anDet = Get-PwDetector -Text $c1anEv.text -Type 'instrument_exit0'
    $c1anCited = [regex]::Match([string]$c1anDet.detail, ': capture (?<path>.+?) sha256 (?<sha>[0-9a-f]{64}), captured_at ')
    return [pscustomobject]@{ verdict = $c1anEv.verdict; exit = $c1anEv.exit; decision = $c1anEv.decision; ran = ((Get-C1anRuns) - $c1anBefore); ok = $c1anDet.ok; detail = [string]$c1anDet.detail; text = $c1anEv.text
                              reused = @(Get-PwListKey -Text $c1anEv.text -Key 'instrument_captures_reused'); kept = @(Get-PwListKey -Text $c1anEv.text -Key 'instrument_captures_kept')
                              keptKey = [bool]($c1anEv.text -match '(?m)^instrument_captures_kept:')
                              citedPath = $(if ($c1anCited.Success) { $c1anCited.Groups['path'].Value } else { '' }); citedSha = $(if ($c1anCited.Success) { $c1anCited.Groups['sha'].Value } else { '' }) }
}
function Get-C1anKeptNames {
    # Every file under instrument-runs whose name is a kept copy's: <stem>.<eight hex>.stdout.txt.
    if (-not (Test-Path -LiteralPath $script:c1anRunsDir -PathType Container)) { return @() }
    return @(Get-ChildItem -LiteralPath $script:c1anRunsDir -Force | Where-Object { $_.Name -cmatch '\.[0-9a-f]{8}\.stdout\.txt\z' } | ForEach-Object { $_.Name } | Sort-Object)
}
function Get-C1anHashes {
    # The sha256 of every FILE under instrument-runs, as one list.
    if (-not (Test-Path -LiteralPath $script:c1anRunsDir -PathType Container)) { return @() }
    return @(Get-ChildItem -LiteralPath $script:c1anRunsDir -File -Force | ForEach-Object { Get-PwRawSha -Path $_.FullName })
}
$c1anM = $null
$c1anHeld = $null
$c1anInstText = @'
$wlRt = Join-Path (Split-Path -Parent (Split-Path -Parent $PSCommandPath)) '.mission-runtime'
if (-not (Test-Path -LiteralPath $wlRt)) { New-Item -ItemType Directory -Path $wlRt -Force | Out-Null }
[System.IO.File]::AppendAllText((Join-Path $wlRt 'wl-ran.txt'), "ran`n")
Write-Output 'the BATCH-4 fixture instrument ran; exit 0'
exit 0
'@
try {
$c1anM = New-EsMission -Tag 'c1an'
if (-not $c1anM.ok) { throw ('FIXTURE REFUSED: ' + $c1anM.why) }
$c1anRoot = $c1anM.root
$c1anRunsDir = Join-Path $c1anRoot '.mission-runtime\lam\instrument-runs'
$c1anBase = New-WlBaseTools -Dir (Join-Path $c1anM.base 'base-tools')
$c1anInst = Join-Path $c1anRoot 'scratch\inst.ps1'
Write-Utf8 -Path $c1anInst -Text ($c1anInstText -replace "`r", '')
Write-Utf8 -Path (Join-Path $c1anRoot '.gitignore') -Text "/.mission/goals/*.verdict.yaml`n.mission-runtime/`n"
Write-Utf8 -Path (Join-Path $c1anRoot '.mission\mission.yaml') -Text "id: wl-kept-fixture`nadmitted_porcelain: [`"?? scratch/`"]`n"
Write-PwGoal -Root $c1anRoot -GoalId 'G-KC30' -DetectorLines @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30')
Write-PwGoal -Root $c1anRoot -GoalId 'G-KCB'  -DetectorLines @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30')
Write-PwGoal -Root $c1anRoot -GoalId 'G-KCA'  -DetectorLines @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
$c1anAdd = Invoke-PwGit -Root $c1anRoot -GitArgs @('add', '--', '.gitignore', '.mission/mission.yaml', '.mission/goals')
$c1anCom = Invoke-PwGit -Root $c1anRoot -GitArgs ($esCommitArgs + @('the kept-capture fixture'))
$c1anPorc = (Invoke-PwGit -Root $c1anRoot -GitArgs @('status', '--porcelain=v1')).text.Trim()
Add-C1anRow -Label 'FIXTURE a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/") and three goals committed; porcelain reads exactly "?? scratch/"' `
    -Ok ($c1anBase.ok -and ($c1anAdd.exit -eq 0) -and ($c1anCom.exit -eq 0) -and ($c1anPorc -ceq '?? scratch/')) -Said ('porcelain [' + $c1anPorc + ']; ' + $c1anBase.said)

# (a) THE RED, KEPT, FIRST, in a directory of its own run key (G-KCB): the base reuses, names one path and one
#     sha256, and keeps nothing; one fresh run later no file on disk hashes to what it cited.
$c1anA1 = Get-C1anReading -GoalId 'G-KCB' -Evaluator $c1anBase.path
$c1anA2 = Get-C1anReading -GoalId 'G-KCB' -Evaluator $c1anBase.path
$c1anAKept = @(Get-C1anKeptNames)
Write-Utf8 -Path $c1anInst -Text (($c1anInstText -replace "`r", '') + "# one more line`n")
$c1anA3 = Get-C1anReading -GoalId 'G-KCB' -Evaluator $c1anBase.path
Write-Utf8 -Path $c1anInst -Text ($c1anInstText -replace "`r", '')
$c1anAOnDisk = @(Get-C1anHashes)
Add-C1anRow -Label '(a) RED at the base: a run, then a REUSE naming one path and its sha256 -- no copy is kept, no kept key is written -- then, the instrument''s bytes changed, a fresh run under the same run key: NO file under instrument-runs hashes to the sha256 the reuse cited' `
    -Ok ($c1anBase.ok -and ($c1anA1.ran -eq 1) -and ($c1anA2.ran -eq 0) -and $c1anA2.detail.Contains('REUSED A FRESH READING') -and ($c1anA2.citedSha -cmatch '\A[0-9a-f]{64}\z') -and ($c1anAKept.Count -eq 0) -and (-not $c1anA2.keptKey) -and
         (-not $c1anA2.detail.Contains('KEPT')) -and ($c1anA3.ran -eq 1) -and (-not ($c1anAOnDisk -ccontains $c1anA2.citedSha))) `
    -Said ('base ran ' + $c1anA1.ran + ', ' + $c1anA2.ran + ', ' + $c1anA3.ran + '; cited ' + $c1anA2.citedSha + '; kept names after the reuse: ' + $c1anAKept.Count + '; files on disk hashing to it after the fresh run: ' + @($c1anAOnDisk | Where-Object { $_ -ceq $c1anA2.citedSha }).Count)
if (Test-Path -LiteralPath $c1anRunsDir) { Get-ChildItem -LiteralPath $c1anRunsDir -Force | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force } }

# (b) THE FALSIFIER, AT THIS TREE: a run, then a reuse.
$c1anB1 = Get-C1anReading -GoalId 'G-KC30'
$c1anLive = Join-Path $c1anRunsDir 'G-KC30.inst.stdout.txt'
$c1anLiveBytes1 = if (Test-Path -LiteralPath $c1anLive -PathType Leaf) { [System.IO.File]::ReadAllBytes($c1anLive) } else { [byte[]]@() }
$c1anSha1 = Get-PwSha256 -Bytes $c1anLiveBytes1
$c1anKept1 = Join-Path $c1anRunsDir ('G-KC30.inst.' + $c1anSha1.Substring(0, 8) + '.stdout.txt')
$c1anBeforeReuse = @(Get-C1anKeptNames)
$c1anB2 = Get-C1anReading -GoalId 'G-KC30'
$c1anKept1Is = Test-Path -LiteralPath $c1anKept1 -PathType Leaf
$c1anKept1Sha = if ($c1anKept1Is) { Get-PwRawSha -Path $c1anKept1 } else { '(absent)' }
Add-C1anRow -Label '(b) FALSIFIER a run, then a REUSE seconds later: before the verdict names it the capture is KEPT beside the live file as <key>.<leaf>.<sha8>.stdout.txt -- it exists, and its bytes hash to the sha256 the detail cites, header and all' `
    -Ok (($c1anB1.ran -eq 1) -and ($c1anBeforeReuse.Count -eq 0) -and ($c1anB2.ran -eq 0) -and ($c1anB2.verdict -ceq 'MET') -and ($c1anB2.citedPath -ceq $c1anLive) -and ($c1anB2.citedSha -ceq $c1anSha1) -and $c1anKept1Is -and ($c1anKept1Sha -ceq $c1anSha1) -and
         ((Get-PwRawSha -Path $c1anLive) -ceq $c1anSha1) -and ([System.Text.Encoding]::ASCII.GetString($c1anLiveBytes1).Contains("writer: tools/lam/lam-instrument-run.ps1 Save-LamInstrumentRun`n"))) `
    -Said ('ran ' + $c1anB1.ran + ', then ' + $c1anB2.ran + '; cited ' + $c1anB2.citedSha + '; kept ' + $c1anKept1 + ' exists: ' + $c1anKept1Is + ', sha256 ' + $c1anKept1Sha)
Add-C1anRow -Label '(b) FALSIFIER ... THE VERDICT NAMES BOTH PATHS: the detail still opens as it did and names the live capture and its sha256, and ends naming the kept copy; instrument_captures_reused holds the one entry it held, and instrument_captures_kept the kept path with the same sha256' `
    -Ok ($c1anB2.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, the instrument was NOT run in this evaluation (register row 368; reuse_within_minutes 30): capture ' + $c1anLive + ' sha256 ' + $c1anSha1 + ', captured_at ') -and
         $c1anB2.detail.EndsWith(' THE CAPTURE CITED IS KEPT at ' + $c1anKept1 + ' (written now; register row 391).') -and ($c1anB2.reused.Count -eq 1) -and ($c1anB2.reused[0] -ceq ($c1anLive + ' sha256 ' + $c1anSha1)) -and
         ($c1anB2.kept.Count -eq 1) -and ($c1anB2.kept[0] -ceq ($c1anKept1 + ' sha256 ' + $c1anSha1))) `
    -Said ('detail: ' + $c1anB2.detail + ' | kept key: [' + ($c1anB2.kept -join ' ; ') + ']')
# (c) A KEPT COPY IS NEVER OVERWRITTEN -- the same bytes: a second reuse of the same capture keeps what is
#     there. The copy is made READ-ONLY first, so a write to it would fail and the reuse with it.
if ($c1anKept1Is) { [System.IO.File]::SetAttributes($c1anKept1, [System.IO.FileAttributes]::ReadOnly) }
$c1anStamp1 = if ($c1anKept1Is) { (Get-Item -LiteralPath $c1anKept1 -Force).LastWriteTimeUtc.Ticks } else { -1 }
$c1anC = Get-C1anReading -GoalId 'G-KC30'
$c1anStamp2 = if (Test-Path -LiteralPath $c1anKept1 -PathType Leaf) { (Get-Item -LiteralPath $c1anKept1 -Force).LastWriteTimeUtc.Ticks } else { -2 }
Add-C1anRow -Label '(c) NEVER OVERWRITTEN, the same bytes: a second reuse of the same capture, the kept copy made read-only -- still REUSED, the copy not written again (its write time unchanged), the detail saying it was already kept' `
    -Ok (($c1anC.ran -eq 0) -and ($c1anStamp1 -eq $c1anStamp2) -and ($c1anStamp1 -gt 0) -and $c1anC.detail.EndsWith(' THE CAPTURE CITED IS KEPT at ' + $c1anKept1 + ' (already kept, the same bytes; register row 391).') -and (@(Get-C1anKeptNames).Count -eq 1)) `
    -Said ('ran ' + $c1anC.ran + '; write time unchanged: ' + ($c1anStamp1 -eq $c1anStamp2) + '; kept names: ' + (@(Get-C1anKeptNames) -join ', '))
# (d) IT SURVIVES THE NEXT FRESH EVALUATION UNDER THE SAME RUN KEY: the instrument's bytes change, so the next
#     evaluation runs it and rewrites the live file.
Write-Utf8 -Path $c1anInst -Text (($c1anInstText -replace "`r", '') + "# one more line`n")
$c1anD = Get-C1anReading -GoalId 'G-KC30'
$c1anSha3 = if (Test-Path -LiteralPath $c1anLive -PathType Leaf) { Get-PwRawSha -Path $c1anLive } else { '(absent)' }
Add-C1anRow -Label '(d) FALSIFIER the instrument''s bytes changed: the next evaluation RUNS it under the same run key and REWRITES the live file -- and the kept copy is still there, still hashing to the sha256 the earlier verdict cited' `
    -Ok (($c1anD.ran -eq 1) -and ($c1anSha3 -cne $c1anSha1) -and ($c1anSha3 -cmatch '\A[0-9a-f]{64}\z') -and (Test-Path -LiteralPath $c1anKept1 -PathType Leaf) -and ((Get-PwRawSha -Path $c1anKept1) -ceq $c1anSha1)) `
    -Said ('ran ' + $c1anD.ran + '; the live file now ' + $c1anSha3 + '; the kept copy ' + $(if (Test-Path -LiteralPath $c1anKept1 -PathType Leaf) { Get-PwRawSha -Path $c1anKept1 } else { '(absent)' }))
# (e) ... AND THE NEW CAPTURE, REUSED, IS KEPT UNDER ITS OWN sha8: two kept copies, neither the other's.
$c1anKept3 = Join-Path $c1anRunsDir ('G-KC30.inst.' + $(if ($c1anSha3.Length -eq 64) { $c1anSha3.Substring(0, 8) } else { 'xxxxxxxx' }) + '.stdout.txt')
$c1anE = Get-C1anReading -GoalId 'G-KC30'
Add-C1anRow -Label '(e) the new capture reused in its turn: kept under ITS sha8 beside the first -- two kept copies, each hashing to its own name''s digest' `
    -Ok (($c1anE.ran -eq 0) -and ($c1anE.citedSha -ceq $c1anSha3) -and (@(Get-C1anKeptNames).Count -eq 2) -and (Test-Path -LiteralPath $c1anKept3 -PathType Leaf) -and ((Get-PwRawSha -Path $c1anKept3) -ceq $c1anSha3) -and ((Get-PwRawSha -Path $c1anKept1) -ceq $c1anSha1)) `
    -Said ('ran ' + $c1anE.ran + '; kept names: ' + (@(Get-C1anKeptNames) -join ', '))
# (f) A KEPT COPY IS NEVER A CANDIDATE: the live file and its tally removed, only the two kept copies on disk.
Get-ChildItem -LiteralPath $c1anRunsDir -File -Force | Where-Object { $_.Name -cnotmatch '\.[0-9a-f]{8}\.stdout\.txt\z' } | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force }
$c1anF = Get-C1anReading -GoalId 'G-KC30'
Add-C1anRow -Label '(f) NEVER A CANDIDATE: only the two kept copies on disk, each a whole capture at this HEAD -- the instrument RUNS, and the detail says no capture of this instrument is on disk' `
    -Ok (($c1anF.ran -eq 1) -and $c1anF.detail.Contains('NOT reused, the instrument was run (register row 368) -- no capture of this instrument is on disk')) -Said ('ran ' + $c1anF.ran + '; detail: ' + $c1anF.detail)
# (g) NEVER OVERWRITTEN -- other bytes: the kept name of the capture now live is TAKEN by a file of other bytes.
$c1anSha5 = Get-PwRawSha -Path $c1anLive
$c1anKept5 = Join-Path $c1anRunsDir ('G-KC30.inst.' + $c1anSha5.Substring(0, 8) + '.stdout.txt')
Write-Utf8 -Path $c1anKept5 -Text "planted: not the capture`n"
$c1anPlantSha = Get-PwRawSha -Path $c1anKept5
$c1anG = Get-C1anReading -GoalId 'G-KC30'
Add-C1anRow -Label '(g) NEVER OVERWRITTEN, other bytes: the kept name of the live capture already taken by a file of OTHER bytes -- the reuse is REFUSED, the instrument RUNS, the detail says a kept copy is never overwritten, and the planted file is byte for byte what it was' `
    -Ok (($c1anG.ran -eq 1) -and ($c1anG.verdict -ceq 'MET') -and $c1anG.detail.Contains('could not be kept beside it -- a file already stands at ' + $c1anKept5 + ' with other bytes (sha256 ' + $c1anPlantSha + '), and a kept copy is never overwritten -- and a reading is cited only once its bytes are kept (register row 391).') -and
         ((Get-PwRawSha -Path $c1anKept5) -ceq $c1anPlantSha) -and (-not $c1anG.detail.Contains('REUSED')) -and ($c1anG.kept.Count -eq 0)) `
    -Said ('ran ' + $c1anG.ran + '; detail: ' + $c1anG.detail)
Remove-Item -LiteralPath $c1anKept5 -Force -ErrorAction SilentlyContinue
# (h) ... AND BY A DIRECTORY: nothing is written over it either.
$c1anSha6 = Get-PwRawSha -Path $c1anLive
$c1anKept6 = Join-Path $c1anRunsDir ('G-KC30.inst.' + $c1anSha6.Substring(0, 8) + '.stdout.txt')
if (-not (Test-Path -LiteralPath $c1anKept6)) { New-Item -ItemType Directory -Path $c1anKept6 | Out-Null }
$c1anH = Get-C1anReading -GoalId 'G-KC30'
Add-C1anRow -Label '(h) the kept name taken by a DIRECTORY: the reuse is REFUSED and the instrument RUNS; the directory stands' `
    -Ok (($c1anH.ran -eq 1) -and $c1anH.detail.Contains('could not be kept beside it -- a directory stands at ' + $c1anKept6) -and (Test-Path -LiteralPath $c1anKept6 -PathType Container)) -Said ('ran ' + $c1anH.ran + '; detail: ' + $c1anH.detail)
if (Test-Path -LiteralPath $c1anKept6 -PathType Container) { [System.IO.Directory]::Delete($c1anKept6) }
# (i) AS THE STOP HOOK: the capture is kept before the decision is printed, and the instrument still does not run.
$c1anSha7 = Get-PwRawSha -Path $c1anLive
$c1anKept7 = Join-Path $c1anRunsDir ('G-KC30.inst.' + $c1anSha7.Substring(0, 8) + '.stdout.txt')
$c1anI = Get-C1anReading -GoalId 'G-KC30' -Hook
Add-C1anRow -Label '(i) as the Stop hook over the capture now live: approve, MET, the instrument NOT run, and the kept copy on disk hashing to the sha256 the artifact cites' `
    -Ok (($c1anI.decision -ceq 'approve') -and ($c1anI.verdict -ceq 'MET') -and ($c1anI.ran -eq 0) -and ($c1anI.citedSha -ceq $c1anSha7) -and (Test-Path -LiteralPath $c1anKept7 -PathType Leaf) -and ((Get-PwRawSha -Path $c1anKept7) -ceq $c1anSha7) -and
         ($c1anI.kept.Count -eq 1) -and ($c1anI.kept[0] -ceq ($c1anKept7 + ' sha256 ' + $c1anSha7))) `
    -Said ('decision ' + $c1anI.decision + ', ran ' + $c1anI.ran + '; kept key: [' + ($c1anI.kept -join ' ; ') + ']')
# (j) A KEPT COPY THAT CANNOT BE READ IS NOT TAKEN ON TRUST (the builder-side review's finding): the copy
#     row (i) just wrote, the capture's own bytes, held by another process with no sharing. Whether it still
#     holds those bytes cannot be established, so nothing is cited: the reuse is REFUSED and the instrument runs.
$c1anHeld = $null
if (Test-Path -LiteralPath $c1anKept7 -PathType Leaf) { $c1anHeld = [System.IO.File]::Open($c1anKept7, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None) }
try { $c1anJ = Get-C1anReading -GoalId 'G-KC30' } finally { if ($null -ne $c1anHeld) { $c1anHeld.Dispose(); $c1anHeld = $null } }
Add-C1anRow -Label '(j) the kept copy held by another process with no sharing, so it cannot be READ: the reuse is REFUSED and the instrument RUNS -- the detail says a file stands there that could not be read, and a kept copy is never overwritten' `
    -Ok (($c1anJ.ran -eq 1) -and $c1anJ.detail.Contains('could not be kept beside it -- a file already stands at ' + $c1anKept7 + ' and could not be read (') -and $c1anJ.detail.Contains('), and a kept copy is never overwritten -- and a reading is cited only once its bytes are kept (register row 391).') -and
         (Test-Path -LiteralPath $c1anKept7 -PathType Leaf) -and ((Get-PwRawSha -Path $c1anKept7) -ceq $c1anSha7)) -Said ('ran ' + $c1anJ.ran + '; detail: ' + $c1anJ.detail)
# (k) THE SAME BYTES ARE NOT ENOUGH: THE KEPT NAME MUST BE ANOTHER FILE (the review's finding). A HARD LINK
#     to the live capture, planted at its kept name, has the capture's bytes because it IS the capture -- and
#     the next fresh run would rewrite both names. It is not taken for a kept copy.
$c1anSha8 = Get-PwRawSha -Path $c1anLive
$c1anKept8 = Join-Path $c1anRunsDir ('G-KC30.inst.' + $c1anSha8.Substring(0, 8) + '.stdout.txt')
if (-not (Test-Path -LiteralPath $c1anKept8)) { $null = New-Item -ItemType HardLink -Path $c1anKept8 -Target $c1anLive }
$c1anK = Get-C1anReading -GoalId 'G-KC30'
Add-C1anRow -Label '(k) a HARD LINK to the live capture planted at its kept name -- the capture''s bytes, and the capture itself: the reuse is REFUSED and the instrument RUNS, the detail saying the file there is the live capture under another name' `
    -Ok (($c1anK.ran -eq 1) -and $c1anK.detail.Contains('could not be kept beside it -- the file at ' + $c1anKept8 + ' has the capture''s bytes but is the live capture itself under another name (') -and $c1anK.detail.Contains('and the next run would rewrite it') -and (-not $c1anK.detail.Contains('REUSED'))) `
    -Said ('ran ' + $c1anK.ran + '; detail: ' + $c1anK.detail)
Remove-Item -LiteralPath $c1anKept8 -Force -ErrorAction SilentlyContinue
# (l) CONTROL: a goal that declares no window runs its instrument and writes the artifact the base writes.
$c1anL = Get-C1anReading -GoalId 'G-KCA'
$c1anLB = Get-C1anReading -GoalId 'G-KCA' -Evaluator $c1anBase.path
Add-C1anRow -Label '(l) CONTROL a goal with no reuse_within_minutes: the instrument RUNS, neither reuse key is written, the artifact the base''s byte for byte but for its clock' `
    -Ok (($c1anL.ran -eq 1) -and ($c1anLB.ran -eq 1) -and (-not $c1anL.keptKey) -and ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1anL.text)) -ceq (Get-WlMasked -Text $c1anLB.text))) -Said ('ran ' + $c1anL.ran + ', base ' + $c1anLB.ran + '; artifacts equal: ' + ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1anL.text)) -ceq (Get-WlMasked -Text $c1anLB.text)))
}
catch {
    $c1anOk = $false
    $c1anRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1anRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1anHeld) { try { $c1anHeld.Dispose() } catch { } }
if ($null -ne $c1anM) { Remove-PwTreeAsWritten -Base $c1anM.base }
Check -Id 'C-1an' -Title 'THE CAPTURE A REUSE CITES IS KEPT (the BATCH-4 charter (d), as ruled 2026-10-06): at the base evaluator a reuse names one path and one sha256 and keeps nothing, and after the next fresh run under the same run key no file under instrument-runs hashes to the sha256 it cited; at this tree the capture is copied beside the live file as <key>.<leaf>.<sha8>.stdout.txt BEFORE the verdict names it -- the copy exists and hashes to the cited sha256, header and all -- and the verdict names both paths: the detail, which opens as it did, ends naming the kept copy, instrument_captures_reused holds the entry it held and instrument_captures_kept the kept path with the same sha256; a second reuse of the same capture writes nothing (the copy read-only, its write time unchanged); the copy SURVIVES the next fresh evaluation under the same run key, which rewrites the live file, and the new capture is kept under its own sha8 beside it; a kept copy is never a reuse candidate -- with only kept copies on disk the instrument runs; a kept name already taken by a file of other bytes, or by a directory, is never written over -- the reuse is refused, the instrument runs, the detail says why, and what stood there stands unchanged; a kept copy another process holds, which cannot be read, is not taken on trust, and a hard link to the live capture planted at the kept name, which has the capture''s bytes because it is the capture, is not taken for a copy -- each refuses the reuse; as the Stop hook the copy is on disk and the instrument still does not run; and a goal that declares no window writes the artifact the base writes, byte for byte' `
      -Ok $c1anOk -Detail ("      THE $(@($c1anRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1anRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument all three goals name (row (d) appends one comment line to it):`n" + (Get-WlIndented -Text $c1anInstText))

# =============================================================================================
# C-1ao -- ONE DETECTOR, ONE ROSTER: validator_pass_count reads a `patterns:` list;
#          `pattern:` keeps its meaning
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: one detector written
# `patterns: [validator-A-5??.result.yaml, validator-A-6??.result.yaml]` with count 4, over the four results
# A-598..A-601 AND A FIFTH, UNLEDGERED result that only the default pattern matches. The base does not read
# `patterns`: it scans the default `validator-*.result.yaml`, meets the fifth, calls it FOREIGN and FAILS.
# (Over the four alone the base reads 4 of 4 already, by the default: the fifth is what makes the RED real.)
# THE FIXTURE DATA. The four results are BYTE COPIES of the primary checkout's own
# tests\lam\validator-A-598..A-601.result.yaml where it holds them (they are ignored, working files, and an
# arc's S0 archives them); where it does not, four stand-ins under the same names, and the FIXTURE row says
# which. Each is ledger-bound IN THE FIXTURE ROOT by ONE hand-written `complete` line carrying its sha256 --
# literal fixture data: the spawn-ledger composer is not run, and the live ledger is not opened.
$c1aoOk = $true
$c1aoRows = New-Object System.Collections.Generic.List[string]
function Add-C1aoRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1aoOk = $false }
    $script:c1aoRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1aoRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1aoReading {
    # One evaluation of -GoalId: the verdict, the exit, every validator_pass_count entry, and the artifact.
    param([string]$GoalId, [string]$Evaluator, [switch]$Hook)
    $c1aoArgs = @{ Root = $script:c1aoRoot; GoalId = $GoalId }
    if ($Evaluator) { $c1aoArgs['Evaluator'] = $Evaluator }
    if ($Hook) { $c1aoArgs['Hook'] = $true }
    $c1aoEv = Invoke-EsEval @c1aoArgs
    $c1aoDet = Get-PwDetector -Text $c1aoEv.text -Type 'validator_pass_count'
    return [pscustomobject]@{ verdict = $c1aoEv.verdict; exit = $c1aoEv.exit; decision = $c1aoEv.decision; out = $c1aoEv.out; text = $c1aoEv.text; found = $c1aoDet.found; ok = $c1aoDet.ok; detail = [string]$c1aoDet.detail }
}
$c1aoM = $null
$c1aoLedgerText = ''
try {
$c1aoM = New-EsMission -Tag 'c1ao'
if (-not $c1aoM.ok) { throw ('FIXTURE REFUSED: ' + $c1aoM.why) }
$c1aoRoot = $c1aoM.root
$c1aoBase = New-WlBaseTools -Dir (Join-Path $c1aoM.base 'base-tools')
$c1aoDir = Join-Path $c1aoRoot 'tests\lam'
$c1aoNames = @('validator-A-598.result.yaml', 'validator-A-599.result.yaml', 'validator-A-600.result.yaml', 'validator-A-601.result.yaml')
$c1aoSourceDir = Join-Path $(if ($primaryRoot) { $primaryRoot } else { $repoRoot }) 'tests\lam'
$c1aoCopies = (@($c1aoNames | Where-Object { -not (Test-Path -LiteralPath (Join-Path $c1aoSourceDir $_) -PathType Leaf) }).Count -eq 0)
$c1aoLedgerLines = New-Object System.Collections.Generic.List[string]
$c1aoSeq = 0
foreach ($c1aoName in $c1aoNames) {
    $c1aoSeq++
    $c1aoBytes = if ($c1aoCopies) { [System.IO.File]::ReadAllBytes((Join-Path $c1aoSourceDir $c1aoName)) } else { $pwUtf8.GetBytes("# a stand-in written by WP-3 C-1ao: the primary checkout holds no " + $c1aoName + "`nverdict: PASS`n") }
    Set-PwBytes -Path (Join-Path $c1aoDir $c1aoName) -Bytes $c1aoBytes
    $c1aoLedgerLines.Add('{"seq":' + $c1aoSeq + ',"event":"complete","dispatch_id":"D-WL-FIXTURE-' + $c1aoSeq + '","result_path":"tests/lam/' + $c1aoName + '","result_sha256":"' + (Get-PwSha256 -Bytes $c1aoBytes) + '","composed_by":"WP-3 C-1ao, by hand: literal fixture data, no composer run"}')
}
$c1aoLedgerText = ($c1aoLedgerLines -join "`n") + "`n"
Write-Utf8 -Path (Join-Path $c1aoRoot '.mission-runtime\lam\spawn-ledger.jsonl') -Text $c1aoLedgerText
# THE FIFTH: a PASS no ledger line binds, under a name only the default pattern matches.
Write-Utf8 -Path (Join-Path $c1aoDir 'validator-B-900.result.yaml') -Text "verdict: PASS`n"
$c1aoPassLines = @($c1aoNames | Where-Object { [System.IO.File]::ReadAllText((Join-Path $c1aoDir $_)) -match '(?m)^verdict:[ \t]*PASS[ \t]*\r?$' }).Count
$c1aoTwo = '[validator-A-5??.result.yaml, validator-A-6??.result.yaml]'
$c1aoHead = @('  - type: validator_pass_count', '    dir: tests/lam')
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PL'      -DetectorLines ($c1aoHead + @(('    patterns: ' + $c1aoTwo), '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLOLD'   -DetectorLines ($c1aoHead + @('    pattern: validator-A-5??.result.yaml', '    count: 2') + $c1aoHead + @('    pattern: validator-A-6??.result.yaml', '    count: 2'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLDEF'   -DetectorLines ($c1aoHead + @('    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLBOTH'  -DetectorLines ($c1aoHead + @('    pattern: validator-A-5??.result.yaml', ('    patterns: ' + $c1aoTwo), '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLCOM'   -DetectorLines ($c1aoHead + @(('    patterns: ' + $c1aoTwo + '  # the roster'), '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLEMPTY' -DetectorLines ($c1aoHead + @('    patterns: []', '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLBLOCK' -DetectorLines ($c1aoHead + @('    patterns:', '      - validator-A-5??.result.yaml', '      - validator-A-6??.result.yaml', '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLDUP'   -DetectorLines ($c1aoHead + @('    patterns: [validator-A-5??.result.yaml, validator-A-59?.result.yaml, VALIDATOR-A-6??.RESULT.YAML]', '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PL5'     -DetectorLines ($c1aoHead + @(('    patterns: ' + $c1aoTwo), '    count: 5'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLQ'     -DetectorLines ($c1aoHead + @('    patterns: [''validator-A-5??.result.yaml'', "validator-A-6??.result.yaml"]', '    count: 4'))
Write-PwGoal -Root $c1aoRoot -GoalId 'G-PLQ1'    -DetectorLines ($c1aoHead + @('    patterns: ["validator-A-5??.result.yaml, validator-A-6??.result.yaml"]', '    count: 4'))
Add-C1aoRow -Label ('FIXTURE a git repository under %TEMP%, the base tools pinned; tests\lam holding A-598..A-601 -- ' + $(if ($c1aoCopies) { 'BYTE COPIES of the primary checkout''s four' } else { 'STAND-INS: the primary checkout holds not all four' }) + ' -- each with a column-0 verdict: PASS and one hand-written complete line in the fixture''s own spawn ledger, and a FIFTH, unledgered PASS (validator-B-900)') `
    -Ok ($c1aoBase.ok -and ($c1aoPassLines -eq 4) -and ($c1aoLedgerLines.Count -eq 4)) -Said ('source: ' + $(if ($c1aoCopies) { $c1aoSourceDir } else { 'stand-ins' }) + '; PASS at column 0 in ' + $c1aoPassLines + ' of 4; ' + $c1aoBase.said)

# (a) THE FALSIFIER: one detector, two patterns, count 4.
$c1aoNamesShown = (@($c1aoNames | ForEach-Object { $_ + '=PASS' }) -join ', ')
$c1aoA = Get-C1aoReading -GoalId 'G-PL'
Add-C1aoRow -Label '(a) FALSIFIER one detector, patterns: [validator-A-5??..., validator-A-6??...], count 4: MET, exit 0 -- 4 of 4, the four named, each ledger-bound; the fifth is not in the roster and is not read' `
    -Ok (($c1aoA.verdict -ceq 'MET') -and ($c1aoA.exit -eq 0) -and $c1aoA.ok -and $c1aoA.detail.StartsWith('4 of 4 required validator result(s) are COMPLETE (PASS, or REFUTED accepted with registered residuals under amendment 23) AND provenance-bound to the spawn ledger in ') -and
         $c1aoA.detail.EndsWith(' [' + $c1aoNamesShown + ']') -and (-not $c1aoA.detail.Contains('FOREIGN'))) -Said ('verdict ' + $c1aoA.verdict + '; detail: ' + $c1aoA.detail)
# (b) THE RED, KEPT: the base does not read the key, scans the default, and meets the fifth.
$c1aoB = Get-C1aoReading -GoalId 'G-PL' -Evaluator $c1aoBase.path
Add-C1aoRow -Label '(b) RED at the base, the same goal: `patterns` is not read, the DEFAULT pattern is -- the unledgered fifth is FOREIGN and the detector FAILS, NOT_MET' `
    -Ok ($c1aoBase.ok -and ($c1aoB.verdict -ceq 'NOT_MET') -and (-not $c1aoB.ok) -and $c1aoB.detail.Contains('FOREIGN (unledgered, NOT counted, detector FAILS): validator-B-900.result.yaml')) -Said ('base: ' + $c1aoB.verdict + '; detail: ' + $c1aoB.detail)
# (c) CONTROL: THE OLD FORM, byte for byte -- two detectors, one `pattern:` each -- by hand and as the Stop hook.
$c1aoC = Get-C1aoReading -GoalId 'G-PLOLD'
$c1aoCB = Get-C1aoReading -GoalId 'G-PLOLD' -Evaluator $c1aoBase.path
$c1aoCH = Get-C1aoReading -GoalId 'G-PLOLD' -Hook
$c1aoCHB = Get-C1aoReading -GoalId 'G-PLOLD' -Evaluator $c1aoBase.path -Hook
Add-C1aoRow -Label '(c) CONTROL the old form -- two detectors, pattern: validator-A-5??... and validator-A-6??..., count 2 each: MET, and BYTE-IDENTICAL to the base: the artifact but for its clock, the hand-run''s output, the Stop hook''s stdout' `
    -Ok (($c1aoC.verdict -ceq 'MET') -and ($c1aoCB.verdict -ceq 'MET') -and ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1aoC.text)) -ceq (Get-WlMasked -Text $c1aoCB.text)) -and ($c1aoC.out -ceq $c1aoCB.out) -and ($c1aoCH.decision -ceq 'approve') -and ($c1aoCH.out -ceq $c1aoCHB.out) -and
         ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1aoCH.text)) -ceq (Get-WlMasked -Text $c1aoCHB.text))) `
    -Said ('tree ' + $c1aoC.verdict + ', base ' + $c1aoCB.verdict + '; artifact equal: ' + ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1aoC.text)) -ceq (Get-WlMasked -Text $c1aoCB.text)) + '; hand output equal: ' + ($c1aoC.out -ceq $c1aoCB.out) + '; hook stdout equal: ' + ($c1aoCH.out -ceq $c1aoCHB.out))
# (d) CONTROL: NO pattern AT ALL -- the default, as it was: the fifth is read, and FOREIGN.
$c1aoD = Get-C1aoReading -GoalId 'G-PLDEF'
$c1aoDB = Get-C1aoReading -GoalId 'G-PLDEF' -Evaluator $c1aoBase.path
Add-C1aoRow -Label '(d) CONTROL neither key: the default pattern validator-*.result.yaml is read, the fifth is FOREIGN, NOT_MET -- the artifact the base''s byte for byte but for its clock' `
    -Ok (($c1aoD.verdict -ceq 'NOT_MET') -and $c1aoD.detail.Contains('FOREIGN (unledgered, NOT counted, detector FAILS): validator-B-900.result.yaml') -and ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1aoD.text)) -ceq (Get-WlMasked -Text $c1aoDB.text))) `
    -Said ('tree ' + $c1aoD.verdict + '; artifact equal: ' + ((Get-WlMasked -Text (Remove-WrProvenanceLine -Text $c1aoD.text)) -ceq (Get-WlMasked -Text $c1aoDB.text)))
# (e) BOTH KEYS: which roster is meant is not guessed.
$c1aoE = Get-C1aoReading -GoalId 'G-PLBOTH'
Add-C1aoRow -Label '(e) pattern AND patterns on one detector: a FAILED entry with its reason, NOT_MET -- neither roster is read' `
    -Ok (($c1aoE.verdict -ceq 'NOT_MET') -and $c1aoE.found -and (-not $c1aoE.ok) -and ($c1aoE.detail -ceq "validator_pass_count declares both 'pattern' and 'patterns': a roster is read through one of them, and which one is not guessed (register row 392)")) `
    -Said ('detail: ' + $c1aoE.detail)
# (f) A MALFORMED LIST IS NEVER THE DEFAULT PATTERN: a comment after the `]`, an empty list, a block list, and
#     ONE quoted item holding a comma -- which splits into two items each quoted on one side, and is refused
#     rather than read as two patterns (the builder-side review's finding).
foreach ($c1aoBad in @(@{ id = 'G-PLCOM'; what = 'a trailing comment after the ]'; say = 'its value does not open with [ and close with ]' }, @{ id = 'G-PLEMPTY'; what = 'an empty list []'; say = 'it is an empty list' }, @{ id = 'G-PLBLOCK'; what = 'a block list under the key'; say = 'its value is empty' },
                       @{ id = 'G-PLQ1'; what = 'one quoted item holding a comma'; say = 'an item is quoted on one side only (a quoted item cannot hold a comma)' })) {
    $c1aoF = Get-C1aoReading -GoalId $c1aoBad.id
    Add-C1aoRow -Label ('(f) patterns with ' + $c1aoBad.what + ': a FAILED entry with its reason, NOT_MET -- and the default pattern is NOT read in its place (the fifth is not met, nothing is FOREIGN)') `
        -Ok (($c1aoF.verdict -ceq 'NOT_MET') -and $c1aoF.found -and (-not $c1aoF.ok) -and $c1aoF.detail.StartsWith("validator_pass_count 'patterns' is not an inline list of patterns -- " + $c1aoBad.say) -and
             $c1aoF.detail.EndsWith(' -- and the default pattern is never read in its place (register row 392)') -and (-not $c1aoF.detail.Contains('FOREIGN')) -and (-not $c1aoF.detail.Contains('validator-B-900'))) `
        -Said ('detail: ' + $c1aoF.detail)
}
# (g) THE UNION: a file two patterns match is read ONCE; case is folded, as -Filter folds it.
$c1aoG = Get-C1aoReading -GoalId 'G-PLDUP'
Add-C1aoRow -Label '(g) three patterns, two of them matching A-598 and A-599 twice over, one written in UPPER CASE: each file is read ONCE -- 4 of 4, MET, the same detail as row (a)' `
    -Ok (($c1aoG.verdict -ceq 'MET') -and ($c1aoA.verdict -ceq 'MET') -and ($c1aoG.detail -ceq $c1aoA.detail)) -Said ('detail: ' + $c1aoG.detail)
# (h) count IS OVER THE UNION: five asked of a roster of four.
$c1aoH = Get-C1aoReading -GoalId 'G-PL5'
Add-C1aoRow -Label '(h) the same two patterns, count 5: 4 of 5 -- NOT_MET, the four named, nothing FOREIGN' `
    -Ok (($c1aoH.verdict -ceq 'NOT_MET') -and (-not $c1aoH.ok) -and $c1aoH.detail.StartsWith('4 of 5 required validator result(s) are COMPLETE') -and $c1aoH.detail.EndsWith('[' + $c1aoNamesShown + ']')) -Said ('detail: ' + $c1aoH.detail)
# (i) QUOTED ITEMS are unquoted, as the reader unquotes a value.
$c1aoI = Get-C1aoReading -GoalId 'G-PLQ'
Add-C1aoRow -Label '(i) the two items quoted, one in single quotes and one in double: read as the bare patterns -- 4 of 4, MET' `
    -Ok (($c1aoI.verdict -ceq 'MET') -and ($c1aoA.verdict -ceq 'MET') -and ($c1aoI.detail -ceq $c1aoA.detail)) -Said ('detail: ' + $c1aoI.detail)
# (j) AS THE STOP HOOK.
$c1aoJ = Get-C1aoReading -GoalId 'G-PL' -Hook
Add-C1aoRow -Label '(j) as the Stop hook, the falsifier''s goal: approve, exit 0, MET on disk' `
    -Ok (($c1aoJ.decision -ceq 'approve') -and ($c1aoJ.exit -eq 0) -and ($c1aoJ.verdict -ceq 'MET')) -Said ($c1aoJ.out.Trim())

# (k) THE PLANE ROW, over C-1al..C-1ao: every evaluation at a root under %TEMP%, and both live planes' sentinel
#     paths as they were before C-1af. The live spawn ledger was not opened: the fixture's own is under %TEMP%.
$wlPlaneAfter = Get-EsPlaneSnapshot
$wlOutside = @($esEvalRoots | Where-Object { -not $_.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase) })
Add-C1aoRow -Label ('(k) PLANE ' + $esEvalRoots.Count + ' evaluations by C-1af..C-1ao, every one at a root under %TEMP%; both live planes'' sentinel paths unchanged since before C-1af') `
    -Ok (($esEvalRoots.Count -gt 0) -and ($wlOutside.Count -eq 0) -and ($wlPlaneAfter -ceq $esPlaneBefore)) -Said ('outside %TEMP%: ' + $wlOutside.Count + '; snapshot equal: ' + ($wlPlaneAfter -ceq $esPlaneBefore))
}
catch {
    $c1aoOk = $false
    $c1aoRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1aoRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1aoM) { Remove-PwTreeAsWritten -Base $c1aoM.base }
Check -Id 'C-1ao' -Title 'ONE DETECTOR, ONE ROSTER (the BATCH-4 charter (e), as ruled 2026-10-06): one validator_pass_count detector written patterns: [validator-A-5??.result.yaml, validator-A-6??.result.yaml] with count 4, over the four results A-598..A-601, each ledger-bound in the fixture''s own spawn ledger by a hand-written complete line, and a fifth, unledgered PASS that only the default pattern matches, FAILS at the base evaluator -- it does not read the key, scans the default and calls the fifth FOREIGN -- and reads 4 of 4, MET, at this tree, the four named and the fifth not read; the old form, two detectors with one pattern: each, is byte-identical to the base -- the artifact but for its clock, the hand-run''s output and the Stop hook''s stdout; with neither key the default pattern is read as it was; pattern and patterns on one detector FAIL it with the reason, neither roster read; a list that is not an inline list -- a comment after its closing bracket, an empty list, a block list under the key, one quoted item holding a comma -- FAILS the detector with its reason, and the default pattern is never read in its place; a file two patterns match is read once, case folded; count is over the union, so five asked of four is 4 of 5; items quoted on both sides are unquoted; as the Stop hook the roster approves; and every evaluation by C-1af..C-1ao ran at a root under %TEMP%, both live planes'' sentinel paths unchanged' `
      -Ok $c1aoOk -Detail ("      THE $(@($c1aoRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1aoRows -join "`n") + "`n      THE FIXTURE DATA, SHOWN BEFORE THE FIRST RED -- <root>\.mission-runtime\lam\spawn-ledger.jsonl, four lines written by hand (no composer is run):`n" + (Get-WlIndented -Text $c1aoLedgerText) + "`n      and the fifth result, tests\lam\validator-B-900.result.yaml, which no line binds:`n          | verdict: PASS")

# END OF BATCH-4 WP-L

# =============================================================================================
# BATCH-5 WP-N -- THE INPUT TREE A CAPTURE STOOD ON, THE RED THAT IS NEVER STEPPED OVER, THE ENGINE READ, THE
# GOAL READER'S GRAMMAR, THE KEPT COPIES LISTED, TWO PATHS REFUSED AS A BRIEF BY NAME AND THE MISSION ROOT THAT
# IS NO DIRECTORY: C-1ap, C-1aq, C-1ar, C-1as, C-1at, C-1au, C-1av and C-1aw
# (the BATCH-5 charter, WP-N; the
# operator's rulings on that charter and on this
# package's grounding, relayed by the build order)
# =============================================================================================
# THE CHARTER'S WORDS (WP-N):
#   (a) "RETROSPECTIVE SS3.1 (a new row, REC-A's): THE REUSE KEY. The evaluator declines a capture whose head is
#       not HEAD though src/, tests/, tools/ and the mirror
#       are byte-equal -- five FRESH runs, four after ledger-only commits. CURE: the goal file
#       declares the instrument's INPUT PATHS (`instrument_inputs:` -- a list; ...); the capture header records
#       the TREE HASH over those paths at the run (git's own object hashing ...); the reuse predicate admits a
#       capture inside the window with a clean tree whose input tree hash equals HEAD's, HEAD equality the fast
#       path; the verdict names the hash it matched and the kept copy as today. A goal WITHOUT the key keeps
#       today's behaviour byte-identical."
#   (b) "RETROSPECTIVE SS3.2(a) (a new row, REC-A's): THE ENGINE READ. Before the evaluator launches the
#       instrument it reads whether the Docker engine answers ...; a down engine is a named finding in the
#       verdict -- instrument_exit0 NOT RUN, reason `engine down`, NOT_MET -- never a 900 s wall and a
#       runnable-0 tally."
#   (c) "the goal reader's grammar -- a key not touching its colon is SKIPPED and the default read
#       (fail-open on the allow side); a list item's own text is not examined. CURE: a key with space before
#       its colon is a goal_parse refusal with the line printed; list items are examined by the same scalar
#       rules as values. The seat enumerates every key the schema declares (standing 19)."
#   (d) "the kept copies are listed by the evaluator at a MET verdict
#       (`instrument_captures_kept_on_disk:` -- every kept file under the run key with its sha256 re-hashed, a
#       mismatch named) so the close entry's list is the tool's ..."
#   (e) "ONLY IF SIZED S: another goal's artifact or a live capture named as the HANDOFF brief ->
#       refused by class. Otherwise RECORDED."
# AND TWO OF THE OPERATOR'S RULINGS ON THAT CHARTER:
#   1. "C-1av's rule is FORKED INTO WP-N as an S item: one block at mission-goal-check.ps1 :2721-:2727 in
#      C-2f's form (BLOCK, the reason on stderr and in the hook's decision); falsifier: a -MissionRoot that
#      is no directory -> today approve, after BLOCKED."
#   5. "... AND exit 0 becomes a condition of reuse -- WP-N (a)(ii), S, forked in: a capture whose exit_code is
#      not 0 is never reused (a RED is re-measured); falsifier: a RED capture at HEAD inside the window -> today
#      REUSED as RED, after FRESH."
# AS RULED BY THE OPERATOR ON 2026-10-11 ON THIS PACKAGE'S GROUNDING, where the ruling says more than the
# charter or other than it: the goal declares what is NOT an input, `instrument_inputs_except:`, and the
# charter's `instrument_inputs:` key is not built (D2); the figure's one function stands in the helper and is
# handed the head (D3), and the header's line is written only when the parameter is given (D4); a RED captured
# after the capture that passes is never stepped over either; a malformed list item FAILS its detector by
# name, not the goal (D1); `engine_read_fault` is the fixture's seam and asks no reuse question (D5), and the
# engine UP is a member of its own, skipped by name when the host's engine is down (D6); a key that does not
# touch its colon outranks the HALT label ONLY on a HALT-scope key of a halt_absent item (D15); and the empty
# mission root blocks as the missing one (D9). AND BY THE GROUNDING REPORT THE BUILD ORDER MADE THE
# SPECIFICATION: the kept copies are listed by LEAF, under every run key, where the charter says "under the run
# key" -- a kept copy is named from the capture that was reused, and that capture may be another key's.
# WHAT IS RULED, row by row -- the charter as those rulings changed it:
#   (a)(i)       an instrument_exit0 detector may declare `instrument_inputs_except: [p1, p2]`, an inline list
#       of repository-relative paths. A capture taken under it carries `input_tree`, the sha256 of the head's
#       tree less those paths (Get-LamInputTree, in the helper); a capture whose head is not HEAD is still
#       reused where its input_tree equals HEAD's -- the head condition WIDENED, every later condition kept.
#       A list, or an item, the evaluator cannot read FAILS the detector by name, and the instrument is not run.
#   (a)(ii)      a reading that is not exit 0 is never reused, and a RED captured after the capture that passes
#       is never stepped over: either way the instrument is re-measured.
#   (b)          `engine_read: docker_pipe | docker_pipe_then_version` is read only when the instrument is about
#       to be launched; with the engine down the detector fails "<leaf> NOT RUN: engine down -- ..." and no
#       capture is written. `engine_read_fault` is the fixture's seam; a detector carrying it asks no reuse
#       question at all.
#   (c)          inside `detectors:` a key that does not touch its colon is a goal that does not parse, and on
#       a HALT-scope key of a halt_absent item that fault outranks the HALT label. A `patterns` item holding a
#       bracket or a path separator fails validator_pass_count by name.
#   (d)          where the verdict is MET and a window is declared, the artifact lists every kept copy on disk,
#       by leaf, under every run key: instrument_captures_kept_on_disk.
#   (e)          another goal's verdict artifact, and any file under instrument-runs, is refused as a HANDOFF
#       brief BY NAME, not by identity: the rule reads the name the head wrote, and C-1au states and drives the
#       names it does not reach.
#   C-1av        as the Stop hook, a mission root that is no directory -- the empty string among them -- BLOCKS.
# AND WHAT STAYS: a goal that declares none of the new keys and no window writes the artifact, the capture and
# the stdout the base writes, byte for byte but for the clock.
# THE EIGHT MEMBERS each drive their rows in TWO forms, through one helper (Invoke-WnEval -Tools tree|base):
# this tree's tools, and the BASE -- the evaluator and its three libraries as they stood at this branch's
# parent at the cut, each pinned by its LF/blob sha256 and written ONCE, here, for all eight
# (New-WnBaseTools; $wnBase). EVERY FALSIFIER ROW IS RED AT THE TREE BEFORE THE CURE, and where the base can
# show it the RED is KEPT as a control. WHERE A PIN DOES NOT HOLD EVERY CALL THAT NAMES THE BASE THROWS, so
# no control row reads green over bytes that are not the base's: the member reads MEMBER ABORTED, and why.
# THE FIXTURE FORM IS C-1ai's (New-EsMission, through New-WnMission): a real git repository under %TEMP%, its
# git dir and its common dir asserted EXACTLY <root>\.git before git is used again (the 2026-09-13 rule),
# `git config` never run; a committed .gitignore for the verdict artifact and the runtime plane, and
# .mission/mission.yaml admitting ONE untracked prefix, `?? scratch/`, where the stub instrument lives -- so
# its bytes can change with HEAD unmoved and the tree clean. Two tracked directories, inputs/ and other/, one
# LF text file each, are what an exclusion list is read against.
# EVERY EVALUATION GOES THROUGH Invoke-WnEval, WHICH REFUSES A MISSION ROOT OUTSIDE %TEMP% AND A GOAL ID THAT
# DOES NOT BEGIN G-WN; every hand capture through New-WnCapture, which holds the same line. No member here
# spawns a seat, writes a spawn-ledger line or touches a live mission plane.
$wnBaseSha  = '700e19e5-s12'
$wnBasePins = [ordered]@{
    'mission-goal-check.ps1'   = '74d66d2086c7f680261942e44fe3d8cbc641dea1d4bfb42cd79c7033743f78bd'
    'lam-verify-admission.ps1' = 'ccd0d7d1656a0dba4187585d5e583d604e3c65882c094c7df704b800f4d4ba58'
    'lam-gate-class.ps1'       = 'bc7a3cd885709c5df5661f3a5cd308b878e7d63e89246a43e3d029278247e577'
    'lam-instrument-run.ps1'   = '19d1e69daf304f9681108c12e648b42094b70f1c5630ba5df9f4bc2106c0fa86'
}
function New-WnBaseTools {
    # The base evaluator, its three libraries among them the helper, each at its pinned LF/blob
    # sha256, under -Dir. path is the evaluator, helper the helper, dir the directory holding the four.
    param([string]$Dir)
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    $wnPinOk = $true
    $wnPinSaid = New-Object System.Collections.Generic.List[string]
    foreach ($wnPinName in @($script:wnBasePins.Keys)) {
        # Through Get-LamBaseBytes: the installed fixtures alone, no history -- the pin decides.
        $wnRead = Get-LamBaseBytes -Base $script:wnBaseSha -Path ('tools/lam/' + $wnPinName) -Pin $script:wnBasePins[$wnPinName]
        if (-not $wnRead.ok) { $wnPinOk = $false }
        $wnPinSaid.Add($wnPinName + ' ' + $wnRead.sha.Substring(0, 8) + ' (' + $wnRead.from + ')')
        [System.IO.File]::WriteAllBytes((Join-Path $Dir $wnPinName), $wnRead.bytes)
    }
    return [pscustomobject]@{ ok = $wnPinOk; path = (Join-Path $Dir 'mission-goal-check.ps1'); helper = (Join-Path $Dir 'lam-instrument-run.ps1'); dir = $Dir; said = ($wnPinSaid -join ', ') }
}
# THE BASE, WRITTEN ONCE FOR ALL EIGHT MEMBERS, in a directory of its own under %TEMP% that the line above
# this batch's END marker removes. A throw here would end the instrument, so it is caught and becomes a base
# that did not hold: $wnBase.ok is $false, its `said` carries the reason, and every base call then throws.
$wnBaseDir = Join-Path $env:TEMP ('lam-wp3-wn-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
$wnBase = $null
try { $wnBase = New-WnBaseTools -Dir (Join-Path $wnBaseDir 'base-tools') }
catch { $wnBase = [pscustomobject]@{ ok = $false; path = ''; helper = ''; dir = ''; said = ('New-WnBaseTools threw: ' + ($_.Exception.Message -replace '[\r\n]+', ' ')) } }
# EVERY GOAL ID THESE EIGHT EVALUATE BEGINS G-WN. The nine reserved are added to the list the plane snapshot
# reads (Get-EsPlaneSnapshot looks for a verdict file under each, on this worktree and on the primary
# checkout); a tenth beginning G-WN is added by Invoke-WnEval before it is first evaluated, and an id that
# does not begin G-WN is refused there. THE BATCH's OWN "BEFORE" is taken here, after the nine are added and
# ahead of the first member, and the last member's plane row compares it with what it then reads.
$esGoalIds += @('G-WNAP', 'G-WNAQ', 'G-WNAR', 'G-WNAS', 'G-WNAT', 'G-WNAU', 'G-WNAV', 'G-WNAW', 'G-WNOTHER')
$wnPlaneBefore = Get-EsPlaneSnapshot
$wnEvalsBefore = $esEvalRoots.Count
# THE STOP PAYLOAD Invoke-WnEval WRITES ON THE HOOK's STDIN, byte for byte: a literal, so a row can name it.
$wnStopPayload = '{"session_id":"wp3-wn","hook_event_name":"Stop"}'

# THE STUB INSTRUMENT, the one every goal of these members names: <root>\scratch\<name>.ps1, untracked and
# admitted. Its exit code and its sleep are read from two FLAG FILES beside its counter, so a member turns it
# RED, or slow, WITHOUT CHANGING ITS BYTES -- instrument_sha256 stays what it was, which is what lets a GREEN
# capture and a RED one of the same instrument stand side by side. It writes a marker when it STARTS and
# appends one line to a counter each time it RUNS: "ran 0" is read off disk, not off the evaluator's word.
# Every file it keeps is named after its own leaf, so two stubs in one fixture count apart.
$wnStubText = @'
$wnRt = Join-Path (Split-Path -Parent (Split-Path -Parent $PSCommandPath)) '.mission-runtime'
$wnMe = 'wn-' + [System.IO.Path]::GetFileNameWithoutExtension($PSCommandPath)
if (-not (Test-Path -LiteralPath $wnRt)) { New-Item -ItemType Directory -Path $wnRt -Force | Out-Null }
[System.IO.File]::WriteAllText((Join-Path $wnRt ($wnMe + '.started')), ([DateTime]::UtcNow.ToString('o') + "`n"))
[System.IO.File]::AppendAllText((Join-Path $wnRt ($wnMe + '.ran.txt')), "ran`n")
$wnCode = 0
$wnExitFlag = Join-Path $wnRt ($wnMe + '.exit.flag')
if (Test-Path -LiteralPath $wnExitFlag -PathType Leaf) { $wnCode = [int]([System.IO.File]::ReadAllText($wnExitFlag).Trim()) }
$wnSleepFlag = Join-Path $wnRt ($wnMe + '.sleep.flag')
if (Test-Path -LiteralPath $wnSleepFlag -PathType Leaf) { Start-Sleep -Seconds ([int]([System.IO.File]::ReadAllText($wnSleepFlag).Trim())) }
Write-Output ('EXIT: ' + $wnCode)
exit $wnCode
'@
# THE CHILD THAT TAKES ONE HAND CAPTURE (New-WnCapture). It dot-sources ONE helper file -- the tree's or the
# base's -- and calls Save-LamInstrumentRun; -InstrumentInputsExcept is on the call only where the request
# says so. What the call throws -- at the base, where that parameter does not exist, the binder's own
# sentence -- is CAUGHT and written into the result, never raised. The request and the result are files, so
# no path and no list item rides on a command line.
$wnCaptureDriverText = @'
param([string]$Request, [string]$Result)
$wnOut = [ordered]@{ ok = $false; why = ''; stdout_path = ''; exit_code = $null; lastexit = $null; persisted = $false; persist_note = ''; members = @(); has_input_tree = $false; input_tree = '' }
try {
    $wnReq = [System.IO.File]::ReadAllText($Request) | ConvertFrom-Json
    . ([string]$wnReq.helper)
    $wnCall = @{ InstrumentPath = [string]$wnReq.stub; MissionRoot = [string]$wnReq.root; RunKey = [string]$wnReq.key }
    if ([string]$wnReq.goal) { $wnCall['Goal'] = [string]$wnReq.goal }
    if ($wnReq.pass_except) { $wnCall['InstrumentInputsExcept'] = [string[]]@($wnReq.except) }
    $wnRun = Save-LamInstrumentRun @wnCall
    $wnOut.lastexit = $LASTEXITCODE
    $wnOut.members = @($wnRun.PSObject.Properties.Name)
    $wnOut.stdout_path = [string]$wnRun.stdout_path
    $wnOut.exit_code = $wnRun.exit_code
    $wnOut.persisted = [bool]$wnRun.persisted
    $wnOut.persist_note = [string]$wnRun.persist_note
    $wnOut.has_input_tree = ($wnOut.members -contains 'input_tree')
    if ($wnOut.has_input_tree) { $wnOut.input_tree = [string]$wnRun.input_tree }
    $wnOut.ok = $true
} catch { $wnOut.why = ($_.Exception.GetType().Name + ': ' + (([string]$_.Exception.Message) -replace '[\r\n]+', ' ')) }
[System.IO.File]::WriteAllText($Result, ($wnOut | ConvertTo-Json -Compress), (New-Object System.Text.UTF8Encoding($false)))
'@

function Get-WnBaseOrThrow {
    # The base tools, or a throw that says the pins did not hold: a control row never reads other bytes.
    if (($null -eq $script:wnBase) -or (-not $script:wnBase.ok)) {
        throw ('BASE PIN FAILED: the tools at ' + $script:wnBaseSha + ' did not come out at their pinned LF/blob sha256 (' + [string]$script:wnBase.said + ') -- no base control was run')
    }
    return $script:wnBase
}
function Get-WnHead {
    # HEAD at a fixture root, 40 hex, or '' where git does not answer one.
    param([string]$Root)
    $wnH = Invoke-PwGit -Root $Root -GitArgs @('rev-parse', 'HEAD')
    $wnHt = $wnH.text.Trim()
    if (($wnH.exit -ne 0) -or ($wnHt -cnotmatch '\A[0-9a-f]{40}\z')) { return '' }
    return $wnHt
}
function Get-WnPorcelain {
    # `git status --porcelain=v1` at a fixture root, trimmed: exactly '?? scratch/' once the stub is written
    # and nothing else is out of place ('' before it is).
    param([string]$Root)
    return (Invoke-PwGit -Root $Root -GitArgs @('status', '--porcelain=v1')).text.Trim()
}
function New-WnMission {
    # New-EsMission's repository (its git dir and common dir asserted before anything else), then ONE commit
    # more: .gitignore (the verdict artifact, the runtime plane), .mission/mission.yaml admitting `?? scratch/`
    # (C-1ai's fixture, word for word but for its id), inputs/a.txt and other/b.txt -- one LF line each --
    # and every goal in -Goals (id -> detector lines, written by Write-PwGoal), so the goals are TRACKED and
    # the tree reads clean. A goal written after this commit is untracked until Invoke-WnCommit takes it.
    # Returns New-EsMission's object (ok, why, base -- remove it --, root, commonDir) and: head (HEAD after
    # the commit), porcelain (as it then reads: '' until the stub is written), runsDir, goalsDir, rt
    # (<root>\.mission-runtime), scratch, inputsRel and otherRel (the two tracked files, as git names them),
    # inputsFile and otherFile (their full paths). ok = $false with the reason where a step did not land.
    param([string]$Tag, [System.Collections.IDictionary]$Goals)
    $wnM = New-EsMission -Tag $Tag
    foreach ($wnProp in @('head', 'porcelain', 'runsDir', 'goalsDir', 'rt', 'scratch', 'inputsRel', 'otherRel', 'inputsFile', 'otherFile')) {
        $wnM | Add-Member -NotePropertyName $wnProp -NotePropertyValue ''
    }
    if (-not $wnM.ok) { return $wnM }
    $wnM.runsDir = Join-Path $wnM.root '.mission-runtime\lam\instrument-runs'
    $wnM.goalsDir = Join-Path $wnM.root '.mission\goals'
    $wnM.rt = Join-Path $wnM.root '.mission-runtime'
    $wnM.scratch = Join-Path $wnM.root 'scratch'
    $wnM.inputsRel = 'inputs/a.txt'
    $wnM.otherRel = 'other/b.txt'
    $wnM.inputsFile = Join-Path $wnM.root 'inputs\a.txt'
    $wnM.otherFile = Join-Path $wnM.root 'other\b.txt'
    try {
        Write-Utf8 -Path (Join-Path $wnM.root '.gitignore') -Text "/.mission/goals/*.verdict.yaml`n.mission-runtime/`n"
        Write-Utf8 -Path (Join-Path $wnM.root '.mission\mission.yaml') -Text "id: wn-fixture`nadmitted_porcelain: [`"?? scratch/`"]`n"
        Write-Utf8 -Path $wnM.inputsFile -Text "an input of the instrument`n"
        Write-Utf8 -Path $wnM.otherFile -Text "not an input of the instrument`n"
        $wnAddArgs = @('add', '--', '.gitignore', '.mission/mission.yaml', 'inputs', 'other')
        if (($null -ne $Goals) -and ($Goals.Count -gt 0)) {
            foreach ($wnGoalId in @($Goals.Keys)) { Write-PwGoal -Root $wnM.root -GoalId ([string]$wnGoalId) -DetectorLines @($Goals[$wnGoalId]) }
            $wnAddArgs += '.mission/goals'
        }
        $wnAdd = Invoke-PwGit -Root $wnM.root -GitArgs $wnAddArgs
        $wnCom = Invoke-PwGit -Root $wnM.root -GitArgs ($script:esCommitArgs + @('the BATCH-5 fixture'))
        $wnM.head = Get-WnHead -Root $wnM.root
        $wnM.porcelain = Get-WnPorcelain -Root $wnM.root
        if (($wnAdd.exit -ne 0) -or ($wnCom.exit -ne 0) -or (-not $wnM.head) -or $wnM.porcelain) {
            $wnM.ok = $false
            $wnM.why = 'the BATCH-5 fixture commit did not land as expected: add exit ' + $wnAdd.exit + ', commit exit ' + $wnCom.exit + ', HEAD [' + $wnM.head + '], porcelain [' + $wnM.porcelain + ']'
        }
    } catch {
        $wnM.ok = $false
        $wnM.why = 'the BATCH-5 fixture builder threw: ' + ($_.Exception.Message -replace '[\r\n]+', ' ')
    }
    return $wnM
}
function Write-WnStub {
    # THE STUB INSTRUMENT ($wnStubText, CR dropped) at <root>\scratch\<Name> -- untracked, under the one
    # admitted prefix. -Name is a LEAF name: the stub finds the fixture's runtime plane two directories above
    # itself. Returns its full path. The same bytes under every name, so every stub has one sha256.
    param([string]$Root, [string]$Name = 'inst.ps1')
    $wnStubPath = Join-Path $Root ('scratch\' + $Name)
    Write-Utf8 -Path $wnStubPath -Text ($script:wnStubText -replace "`r", '')
    return $wnStubPath
}
function Get-WnStubFile {
    # Where the stub -Name keeps -What under <root>\.mission-runtime: ran (its counter), started (its marker),
    # exit and sleep (its two flag files).
    param([string]$Root, [string]$Name = 'inst.ps1', [string]$What)
    $wnSuffix = @{ ran = '.ran.txt'; started = '.started'; exit = '.exit.flag'; sleep = '.sleep.flag' }[$What]
    if (-not $wnSuffix) { throw ('Get-WnStubFile: -What is ran, started, exit or sleep, not ' + $What) }
    return (Join-Path $Root ('.mission-runtime\wn-' + [System.IO.Path]::GetFileNameWithoutExtension($Name) + $wnSuffix))
}
function Get-WnRuns {
    # How many times the stub has RUN at this root, read off its own counter: 0 where it never has.
    param([string]$Root, [string]$Name = 'inst.ps1')
    $wnCounter = Get-WnStubFile -Root $Root -Name $Name -What 'ran'
    if (-not (Test-Path -LiteralPath $wnCounter -PathType Leaf)) { return 0 }
    return @([System.IO.File]::ReadAllLines($wnCounter) | Where-Object { $_ }).Count
}
function Get-WnMarker {
    # The stub's start marker: the UTC time it last STARTED, or '' where the marker does not stand.
    param([string]$Root, [string]$Name = 'inst.ps1')
    $wnMark = Get-WnStubFile -Root $Root -Name $Name -What 'started'
    if (-not (Test-Path -LiteralPath $wnMark -PathType Leaf)) { return '' }
    return [System.IO.File]::ReadAllText($wnMark).Trim()
}
function Clear-WnMarker {
    # The stub's start marker removed, so the next reading of it is of the next start alone.
    param([string]$Root, [string]$Name = 'inst.ps1')
    $wnMark = Get-WnStubFile -Root $Root -Name $Name -What 'started'
    if (Test-Path -LiteralPath $wnMark -PathType Leaf) { Remove-Item -LiteralPath $wnMark -Force }
}
function Set-WnStubFlag {
    # THE STUB's TWO FLAGS, SET AS A PAIR: it will exit -Exit and sleep -Sleep seconds first. 0 removes that
    # flag file, so a call with neither is GREEN and prompt. The stub's own bytes are not touched.
    param([string]$Root, [string]$Name = 'inst.ps1', [int]$Exit = 0, [int]$Sleep = 0)
    foreach ($wnFlag in @(@{ what = 'exit'; value = $Exit }, @{ what = 'sleep'; value = $Sleep })) {
        $wnFlagPath = Get-WnStubFile -Root $Root -Name $Name -What $wnFlag.what
        if ($wnFlag.value -ne 0) { Write-Utf8 -Path $wnFlagPath -Text ([string]$wnFlag.value + "`n") }
        elseif (Test-Path -LiteralPath $wnFlagPath -PathType Leaf) { Remove-Item -LiteralPath $wnFlagPath -Force }
    }
}
function Clear-WnCaptures {
    # Everything under <root>\.mission-runtime\lam\instrument-runs removed -- live captures, tallies, kept
    # copies, and a directory a row planted -- so the next capture is the only one.
    param([string]$Root)
    $wnRuns = Join-Path $Root '.mission-runtime\lam\instrument-runs'
    if (Test-Path -LiteralPath $wnRuns -PathType Container) {
        foreach ($wnOld in @(Get-ChildItem -LiteralPath $wnRuns -Force)) {
            if (-not $wnOld.PSIsContainer) { try { [System.IO.File]::SetAttributes($wnOld.FullName, [System.IO.FileAttributes]::Normal) } catch { } }
            Remove-Item -LiteralPath $wnOld.FullName -Recurse -Force
        }
    }
}
function ConvertTo-WnArg {
    # ONE ARGUMENT OF A CHILD's COMMAND LINE, quoted so the child receives it as written -- THE EMPTY STRING
    # INCLUDED, as the token "". (Windows PowerShell 5.1's call operator DROPS an '' element when it builds a
    # native command line: `& powershell @argv` with '' after -MissionRoot hands the child "Missing an
    # argument for parameter 'MissionRoot'", not an empty root. An explicit argument string does not.) A run
    # of backslashes ahead of a quote, or ending the value, is doubled, as the C runtime's argv rules ask --
    # a root written with a trailing backslash would otherwise swallow the closing quote.
    param([AllowEmptyString()][string]$Text)
    $wnQ = [regex]::Replace([string]$Text, '(\\*)"', '$1$1\"')
    $wnQ = [regex]::Replace($wnQ, '(\\+)\z', '$1$1')
    return ('"' + $wnQ + '"')
}
function Invoke-WnEval {
    # THE EVALUATOR, OF THIS TREE OR OF THE BASE (-Tools tree|base), in a child `powershell -NoProfile
    # -ExecutionPolicy Bypass -File <evaluator> -Goal <id> -MissionRoot <root>` -- by hand, or as the Stop hook
    # runs it (-AsStopHook: a Stop payload on its stdin, as bytes, no byte-order mark ahead of it) -- ITS
    # STDOUT AND ITS STDERR KEPT APART, its exit code and its wall time read. AT A FIXTURE ONLY: a -Root
    # outside %TEMP% is REFUSED before anything runs (the plane rule, as Invoke-EsEval), and so is a goal id
    # that does not begin G-WN; one not yet in $esGoalIds is added first, so the plane row looks under it.
    # LAM_DISPATCH is taken out of the child's environment unless -Env names it; -Env @{ NAME = 'value' } sets
    # a variable for the child alone and @{ NAME = $null } removes one. The prior verdict artifact at
    # <root>\.mission\goals is removed first (-KeepArtifact leaves it), so what is read back is this run's.
    # THE TWO FORMS THAT NAME NO FIXTURE: -MissionRootArg <string> passes THAT as -MissionRoot -- a path that
    # is no directory, or '' (which the child really receives: ConvertTo-WnArg) -- and -NoMissionRootArg omits
    # the argument altogether. With either, -Root may be left out and no artifact is expected; an override
    # that resolves to a directory that EXISTS must still be under %TEMP%. NOTE WHAT AN OMITTED MANDATORY
    # ARGUMENT DOES: without -NonInteractive the child PROMPTS, and the prompt reads its answer from STDIN --
    # as the hook, the Stop payload itself becomes the mission root. -NonInteractive puts that switch on the
    # child's line, and the binder then fails as the page says (exit 1, nothing on stdout).
    # The child's working directory is this instrument's PowerShell location, as the call operator would set
    # it. A child still running after -TimeoutSeconds is killed with its tree, and timedOut says so.
    # Returns exit, stdout, stderr, seconds, verdict (the artifact's `verdict:` value, or ''), artifactText,
    # artifactPath, decision and reason (the first JSON line on STDOUT, or ''), timedOut, commandLine, tools.
    param([string]$Tools = 'tree', [string]$Root = '', [string]$GoalId, [switch]$AsStopHook,
          [AllowEmptyString()][string]$MissionRootArg, [switch]$NoMissionRootArg, [hashtable]$Env,
          [string]$GoalFile = '', [switch]$NonInteractive, [switch]$KeepArtifact, [int]$TimeoutSeconds = 300)
    $wnOverride = $PSBoundParameters.ContainsKey('MissionRootArg')
    if (@('tree', 'base') -cnotcontains $Tools) { throw ('Invoke-WnEval: -Tools is tree or base, not ' + $Tools) }
    if ($wnOverride -and $NoMissionRootArg) { throw 'Invoke-WnEval: -MissionRootArg and -NoMissionRootArg are one or the other' }
    if ($GoalId -cnotmatch '\AG-WN[A-Za-z0-9-]*\z') { throw ('PLANE RULE: the goal id ' + $GoalId + ' does not begin G-WN -- these members evaluate under their own names only') }
    if ($script:esGoalIds -cnotcontains $GoalId) { $script:esGoalIds += $GoalId }
    $wnEvaluator = if ($Tools -ceq 'base') { (Get-WnBaseOrThrow).path } else { $goalCheck }
    $wnCwd = (Get-Location).ProviderPath
    $wnFull = ''
    if ($Root) {
        $wnFull = [System.IO.Path]::GetFullPath($Root)
        if (-not $wnFull.StartsWith($script:esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
            throw ('PLANE RULE: ' + $wnFull + ' is not under ' + $script:esTempRoot + ' -- these members evaluate fixtures only')
        }
    } elseif (-not ($wnOverride -or $NoMissionRootArg)) { throw 'Invoke-WnEval: -Root is required unless -MissionRootArg or -NoMissionRootArg is given' }
    $wnPassed = $Root
    if ($wnOverride) {
        $wnPassed = [string]$MissionRootArg
        $wnResolved = ''
        if ($wnPassed) { try { $wnResolved = [System.IO.Path]::GetFullPath([System.IO.Path]::Combine($wnCwd, $wnPassed)) } catch { $wnResolved = '' } }
        if ($wnResolved -and [System.IO.Directory]::Exists($wnResolved)) {
            if (-not ($wnResolved.TrimEnd('\') + '\').StartsWith($script:esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
                throw ('PLANE RULE: -MissionRootArg resolves to ' + $wnResolved + ', a directory that exists and is not under ' + $script:esTempRoot + ' -- these members evaluate fixtures only')
            }
            $script:esEvalRoots.Add($wnResolved)
        }
    } elseif (-not $NoMissionRootArg) { $script:esEvalRoots.Add($wnFull) }
    $wnVf = ''
    if ($Root) {
        $wnVf = Join-Path $Root ('.mission\goals\' + $GoalId + '.verdict.yaml')
        if ((-not $KeepArtifact) -and (Test-Path -LiteralPath $wnVf -PathType Leaf)) { Remove-Item -LiteralPath $wnVf -Force }
    }
    $wnParts = New-Object System.Collections.Generic.List[string]
    if ($NonInteractive) { $wnParts.Add('-NonInteractive') }
    foreach ($wnPart in @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', (ConvertTo-WnArg -Text $wnEvaluator), '-Goal', (ConvertTo-WnArg -Text $GoalId))) { $wnParts.Add($wnPart) }
    if (-not $NoMissionRootArg) { $wnParts.Add('-MissionRoot'); $wnParts.Add((ConvertTo-WnArg -Text $wnPassed)) }
    if ($GoalFile) { $wnParts.Add('-GoalFile'); $wnParts.Add((ConvertTo-WnArg -Text $GoalFile)) }
    if ($AsStopHook) { $wnParts.Add('-AsStopHook') }
    $wnPsi = New-Object System.Diagnostics.ProcessStartInfo
    $wnPsi.FileName = 'powershell'
    $wnPsi.Arguments = ($wnParts -join ' ')
    $wnPsi.WorkingDirectory = $wnCwd
    $wnPsi.UseShellExecute = $false
    $wnPsi.CreateNoWindow = $true
    $wnPsi.RedirectStandardInput = $true
    $wnPsi.RedirectStandardOutput = $true
    $wnPsi.RedirectStandardError = $true
    if ($wnPsi.EnvironmentVariables.ContainsKey('LAM_DISPATCH')) { $wnPsi.EnvironmentVariables.Remove('LAM_DISPATCH') }
    if ($null -ne $Env) {
        foreach ($wnEnvName in @($Env.Keys)) {
            if ($null -eq $Env[$wnEnvName]) { if ($wnPsi.EnvironmentVariables.ContainsKey([string]$wnEnvName)) { $wnPsi.EnvironmentVariables.Remove([string]$wnEnvName) } }
            else { $wnPsi.EnvironmentVariables[[string]$wnEnvName] = [string]$Env[$wnEnvName] }
        }
    }
    $wnTimedOut = $false
    # NO BYTE-ORDER MARK REACHES THE CHILD's STDIN, WHATEVER CONSOLE THIS INSTRUMENT RUNS IN. The Process class
    # opens a redirected stdin with [Console]::InputEncoding and, flushing at once, writes that encoding's
    # PREAMBLE as it starts the child -- under console code page 65001 three bytes ahead of anything written
    # here, and none under 437 (Invoke-WlHookStreams has that difference). So where the encoding has a
    # preamble it is replaced, for the one call that starts the child, by the same code page WITHOUT one
    # (the console's code page is not changed), and put back. Where that cannot be done it is left as it is.
    $wnInputWas = $null
    try {
        if ([Console]::InputEncoding.GetPreamble().Length -gt 0) {
            $wnInputWas = [Console]::InputEncoding
            if ($wnInputWas.CodePage -eq 65001) { [Console]::InputEncoding = New-Object System.Text.UTF8Encoding($false) } else { $wnInputWas = $null }
        }
    } catch { $wnInputWas = $null }
    $wnSw = [System.Diagnostics.Stopwatch]::StartNew()
    try { $wnProc = [System.Diagnostics.Process]::Start($wnPsi) }
    finally { if ($null -ne $wnInputWas) { try { [Console]::InputEncoding = $wnInputWas } catch { } } }
    try {
        $wnErrTask = $wnProc.StandardError.ReadToEndAsync()
        $wnOutTask = $wnProc.StandardOutput.ReadToEndAsync()
        # THE PAYLOAD AS BYTES, STRAIGHT TO THE PIPE, and the pipe closed: $wnStopPayload and nothing else, no
        # line end after it. By hand the pipe is closed with nothing in it, so a child that asks its stdin
        # for anything reads the end of it at once.
        $wnIn = $wnProc.StandardInput.BaseStream
        if ($AsStopHook) {
            $wnPayload = [System.Text.Encoding]::ASCII.GetBytes($script:wnStopPayload)
            $wnIn.Write($wnPayload, 0, $wnPayload.Length)
            $wnIn.Flush()
        }
        $wnIn.Close()
        if (-not $wnProc.WaitForExit($TimeoutSeconds * 1000)) {
            $wnTimedOut = $true
            $wnPrevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
            try { $null = & taskkill /PID $wnProc.Id /T /F 2>&1 } catch { } finally { $ErrorActionPreference = $wnPrevEap }
        }
        $wnProc.WaitForExit()
        $wnSw.Stop()
        $wnOut = [string]$wnOutTask.Result
        $wnErr = [string]$wnErrTask.Result
        $wnCode = $wnProc.ExitCode
    } finally { $wnProc.Dispose() }
    $wnText = ''
    if ($wnVf -and (Test-Path -LiteralPath $wnVf -PathType Leaf)) { try { $wnText = [System.IO.File]::ReadAllText($wnVf) } catch { $wnText = '' } }
    $wnV = ''
    $wnVm = [regex]::Match($wnText, '(?m)^verdict:[ \t]*(\S+)')
    if ($wnVm.Success) { $wnV = $wnVm.Groups[1].Value }
    $wnDec = ''
    $wnReason = ''
    foreach ($wnLn in @(($wnOut -replace "`r", '') -split "`n")) {
        $wnT = $wnLn.Trim()
        if (-not $wnT.StartsWith('{')) { continue }
        try { $wnJ = $wnT | ConvertFrom-Json; $wnDec = [string]$wnJ.decision; $wnReason = [string]$wnJ.reason; break } catch { }
    }
    return [pscustomobject]@{ exit = $wnCode; stdout = $wnOut; stderr = $wnErr; seconds = [Math]::Round($wnSw.Elapsed.TotalSeconds, 3); verdict = $wnV; artifactText = $wnText; artifactPath = $wnVf
                              decision = $wnDec; reason = $wnReason; timedOut = $wnTimedOut; commandLine = ('powershell ' + $wnPsi.Arguments); tools = $Tools }
}
function Get-WnInst {
    # The instrument_exit0 entry of an evaluation's artifact (-Eval is what Invoke-WnEval returned): found, ok
    # and detail, quotes un-doubled -- the FIRST entry of that type (Get-PwDetector). Where there is no
    # artifact, or no such entry, found and ok are $false and detail says so.
    param($Eval)
    return (Get-PwDetector -Text ([string]$Eval.artifactText) -Type 'instrument_exit0')
}
function Get-WnList {
    # A top-level list key of an evaluation's artifact: its items, quotes un-doubled (Get-PwListKey).
    # ABSENT AND EMPTY ARE TOLD APART HERE, which Get-PwListKey alone does not do -- it returns no item for
    # `<Key>: []` and for a key that is not written: this returns $NULL where no column-0 `<Key>:` line
    # stands in the artifact, and an EMPTY ARRAY where the key is written with nothing under it. Test
    # `$null -eq $x` BEFORE anything else, and never wrap the call in @( ): that turns $null into one item.
    param($Eval, [string]$Key)
    $wnArtifact = [string]$Eval.artifactText
    if (-not [regex]::IsMatch($wnArtifact, '(?m)^' + [regex]::Escape($Key) + ':')) { return $null }
    return ,@(Get-PwListKey -Text $wnArtifact -Key $Key)
}
function ConvertFrom-WnCaptureHeader {
    # A capture's header as a hashtable: every `key: value` line ahead of the body's opening line, the FIRST
    # occurrence of a key kept, as the evaluator's own reader keeps it. The comment line is not a key.
    param([string]$Text)
    $wnHeader = @{}
    foreach ($wnHl in @((([string]$Text) -replace "`r", '') -split "`n")) {
        if ($wnHl -ceq '--- instrument stdout and stderr, verbatim ---') { break }
        $wnHm = [regex]::Match($wnHl, '\A([a-z_0-9]+): ?(.*)\z')
        if ($wnHm.Success -and (-not $wnHeader.ContainsKey($wnHm.Groups[1].Value))) { $wnHeader[$wnHm.Groups[1].Value] = $wnHm.Groups[2].Value }
    }
    return $wnHeader
}
function Get-WnCaptureKeys {
    # A capture header's KEYS IN THE ORDER THEY ARE WRITTEN, one per `key: value` line ahead of the body's
    # opening line -- a key written twice is listed twice. (A hashtable keeps no order: this is what a row
    # asserting "the base's eighteen keys, in order, and then one more" reads.) Never wrap the call in @( ).
    param([string]$Text)
    $wnKeys = New-Object System.Collections.Generic.List[string]
    foreach ($wnKl in @((([string]$Text) -replace "`r", '') -split "`n")) {
        if ($wnKl -ceq '--- instrument stdout and stderr, verbatim ---') { break }
        $wnKm = [regex]::Match($wnKl, '\A([a-z_0-9]+): ?')
        if ($wnKm.Success) { $wnKeys.Add($wnKm.Groups[1].Value) }
    }
    return ,$wnKeys.ToArray()
}
function Read-WnCapture {
    # A capture ALREADY ON DISK -- the evaluator's own tee (<runs>\<goal>.<leaf>.stdout.txt), a kept copy --
    # read as New-WnCapture returns one: ok (it is a file that could be read), why, path, text, sha256 (of
    # its bytes), header (a hashtable) and headerKeys (the keys in the order written). It runs nothing.
    param([string]$Path)
    $wnRead = [pscustomobject]@{ ok = $false; why = ''; path = $Path; text = ''; sha256 = ''; header = @{}; headerKeys = [string[]]@() }
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { $wnRead.why = 'no file at ' + $Path; return $wnRead }
    try {
        $wnReadBytes = [System.IO.File]::ReadAllBytes($Path)
        $wnRead.text = $pwUtf8.GetString($wnReadBytes)
        $wnRead.sha256 = Get-PwSha256 -Bytes $wnReadBytes
        $wnRead.header = ConvertFrom-WnCaptureHeader -Text $wnRead.text
        $wnRead.headerKeys = Get-WnCaptureKeys -Text $wnRead.text
        $wnRead.ok = $true
    } catch { $wnRead.why = 'the file could not be read: ' + (([string]$_.Exception.Message) -replace '[\r\n]+', ' ') }
    return $wnRead
}
function New-WnCapture {
    # ONE HAND CAPTURE of the stub at a fixture root, under run key -Key, taken by Save-LamInstrumentRun of
    # THIS TREE's helper or the BASE's (-Tools) IN A CHILD PROCESS ($wnCaptureDriverText) -- never by the
    # helper this instrument loaded, so a tree capture and a base capture are taken the same way.
    # -InstrumentInputsExcept is passed ONLY where -Except is given (an empty list is still passed). Where the
    # call throws -- at the base that parameter does not exist -- NOTHING IS RAISED: ok is $false and why is
    # the binder's own sentence. -AgeSeconds then rewrites the header's captured_at to now less that many
    # seconds, exactly as New-C1aiHandCapture does (the first `captured_at:` line; the tally file is left).
    # IT REMOVES NO OTHER CAPTURE: Clear-WnCaptures first where this one must stand alone.
    # Returns ok, why, path, text and sha256 (the file's bytes as they then stand), header (a hashtable: see
    # ConvertFrom-WnCaptureHeader), headerKeys (the keys in the order written), exit (the helper's exit_code),
    # hasInputTree and inputTree (the return object's member: $false and $null at a helper that has none),
    # persisted, tools, childExit, childOut.
    param([string]$Tools = 'tree', [string]$Root, [string]$Key, [string[]]$Except, [int]$AgeSeconds, [string]$Name = 'inst.ps1', [string]$Goal = '')
    if (@('tree', 'base') -cnotcontains $Tools) { throw ('New-WnCapture: -Tools is tree or base, not ' + $Tools) }
    $wnCapFull = [System.IO.Path]::GetFullPath($Root)
    if (-not $wnCapFull.StartsWith($script:esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ('PLANE RULE: ' + $wnCapFull + ' is not under ' + $script:esTempRoot + ' -- these members capture at fixtures only')
    }
    $wnHelper = if ($Tools -ceq 'base') { (Get-WnBaseOrThrow).helper } else { Join-Path $repoRoot 'tools\lam\lam-instrument-run.ps1' }
    $wnCap = [pscustomobject]@{ ok = $false; why = ''; path = ''; text = ''; sha256 = ''; header = @{}; headerKeys = [string[]]@(); exit = $null; hasInputTree = $false; inputTree = $null
                                persisted = $false; tools = $Tools; childExit = $null; childOut = '' }
    $wnDriver = Join-Path $script:wnBaseDir 'wn-capture-driver.ps1'
    if (-not (Test-Path -LiteralPath $wnDriver -PathType Leaf)) { Write-Utf8 -Path $wnDriver -Text ($script:wnCaptureDriverText -replace "`r", '') }
    $wnTicket = [guid]::NewGuid().ToString('N').Substring(0, 8)
    $wnReqPath = Join-Path $script:wnBaseDir ('capture-' + $wnTicket + '.request.json')
    $wnResPath = Join-Path $script:wnBaseDir ('capture-' + $wnTicket + '.result.json')
    $wnPassExcept = $PSBoundParameters.ContainsKey('Except')
    $wnReq = [ordered]@{ helper = $wnHelper; stub = (Join-Path $Root ('scratch\' + $Name)); root = $Root; key = $Key; goal = $Goal; pass_except = $wnPassExcept; except = @($Except | Where-Object { $null -ne $_ }) }
    Write-Utf8 -Path $wnReqPath -Text ($wnReq | ConvertTo-Json -Compress)
    $wnPrevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $wnChild = & powershell -NoProfile -ExecutionPolicy Bypass -File $wnDriver -Request $wnReqPath -Result $wnResPath 2>&1; $wnCap.childExit = $LASTEXITCODE }
    finally { $ErrorActionPreference = $wnPrevEap }
    $wnCap.childOut = ((@($wnChild) | ForEach-Object { [string]$_ }) -join "`n")
    $wnRes = $null
    if (Test-Path -LiteralPath $wnResPath -PathType Leaf) { try { $wnRes = [System.IO.File]::ReadAllText($wnResPath) | ConvertFrom-Json } catch { $wnRes = $null } }
    Remove-Item -LiteralPath $wnReqPath -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $wnResPath -Force -ErrorAction SilentlyContinue
    if ($null -eq $wnRes) { $wnCap.why = 'the capture child wrote no result (exit ' + $wnCap.childExit + '): ' + ($wnCap.childOut -replace '\s+', ' '); return $wnCap }
    if (-not $wnRes.ok) { $wnCap.why = [string]$wnRes.why; return $wnCap }
    $wnCap.exit = $wnRes.exit_code
    $wnCap.persisted = [bool]$wnRes.persisted
    $wnCap.hasInputTree = [bool]$wnRes.has_input_tree
    if ($wnCap.hasInputTree) { $wnCap.inputTree = [string]$wnRes.input_tree }
    $wnCap.path = [string]$wnRes.stdout_path
    if ((-not $wnCap.persisted) -or (-not (Test-Path -LiteralPath $wnCap.path -PathType Leaf))) { $wnCap.why = 'the helper returned and the capture is not on disk: ' + [string]$wnRes.persist_note; return $wnCap }
    $wnCapText = [System.IO.File]::ReadAllText($wnCap.path)
    if ($PSBoundParameters.ContainsKey('AgeSeconds')) {
        $wnStamp = [DateTime]::UtcNow.AddSeconds(-1 * $AgeSeconds).ToString('o')
        $wnCapText = ([regex]'(?m)^captured_at: .*$').Replace($wnCapText, ('captured_at: ' + $wnStamp), 1)
        [System.IO.File]::WriteAllText($wnCap.path, $wnCapText, (New-Object System.Text.UTF8Encoding($false)))
    }
    $wnCap.text = $wnCapText
    $wnCap.sha256 = Get-PwRawSha -Path $wnCap.path
    $wnCap.header = ConvertFrom-WnCaptureHeader -Text $wnCapText
    $wnCap.headerKeys = Get-WnCaptureKeys -Text $wnCapText
    $wnCap.ok = $true
    return $wnCap
}
function Invoke-WnCommit {
    # ONE COMMIT IN A FIXTURE, through Invoke-PwGit, the house's identity on the command line ($esCommitArgs;
    # `git config` is never run). -Path with -Text writes that file first (LF, UTF-8, no byte-order mark; a
    # path as git names it, forward slashes) and adds it; -Add adds further pathspecs (a goal written by
    # Write-PwGoal: '.mission/goals'); -AllowEmpty moves HEAD with nothing staged, as C-1ai's last row does.
    # Returns the new HEAD, 40 hex -- or '' where the add or the commit did not land, or HEAD did not move.
    param([string]$Root, [string]$Path = '', [string]$Text = '', [string]$Message, [string[]]$Add, [switch]$AllowEmpty)
    $wnWas = Get-WnHead -Root $Root
    $wnSpecs = @()
    if ($Path) {
        Write-Utf8 -Path (Join-Path $Root $Path.Replace('/', '\')) -Text (([string]$Text) -replace "`r", '')
        $wnSpecs += $Path.Replace('\', '/')
    }
    if ($Add) { $wnSpecs += @($Add) }
    if ($wnSpecs.Count -gt 0) {
        $wnAdded = Invoke-PwGit -Root $Root -GitArgs (@('add', '--') + $wnSpecs)
        if ($wnAdded.exit -ne 0) { return '' }
    }
    $wnCommitArgs = @($script:esCommitArgs)
    if ($AllowEmpty) { $wnCommitArgs = @($wnCommitArgs[0..($wnCommitArgs.Count - 2)]) + @('--allow-empty', '-m') }
    $wnDone = Invoke-PwGit -Root $Root -GitArgs ($wnCommitArgs + @($Message))
    $wnNow = Get-WnHead -Root $Root
    if (($wnDone.exit -ne 0) -or (-not $wnNow) -or ($wnNow -ceq $wnWas)) { return '' }
    return $wnNow
}
function Get-WnComparable {
    # "EQUAL BUT FOR THE CLOCK", for a verdict artifact or a capture: Get-WlMasked (the house's mask of
    # evaluated_at, the one C-1al, C-1an and C-1ao compare a tree's artifact with the base's on), and with it
    # the three other places a clock is written -- a capture header's captured_at line, a tally file's
    # captured_at= field, and the time and age a REUSED detail cites. Nothing else is masked: a sha256, a
    # head, a path are compared as they are. THE HOUSE's MASK DOES NOT NEUTRALISE A MISSION ROOT, and nor does
    # this unless asked -- three things two TWIN FIXTURES differ in, each named by the caller and by nobody
    # else: -Root <one or more fixture roots> replaces each, as written and as JSON writes it (backslashes
    # doubled), with <ROOT>; -Head <40-hex ids> replaces the first with <HEAD1>, the second with <HEAD2>, ...
    # (two fixtures built a second apart do not share a commit id); -Mask <literal strings> replaces the
    # first with <MASK1>, ... (a capture's sha256, whose bytes hold its clock: name the 64 hex BEFORE its
    # first eight, or the eight will have eaten the head of it).
    param([string]$Text, [string[]]$Root, [string[]]$Head, [string[]]$Mask)
    $wnC = Get-WlMasked -Text $Text
    $wnC = $wnC -replace '(?m)^captured_at: .*$', 'captured_at: MASKED'
    $wnC = $wnC -replace 'captured_at=\S+', 'captured_at=MASKED'
    $wnC = $wnC -replace ', captured_at \S+ \(\d+ min \d+ s old\)', ', captured_at MASKED (MASKED old)'
    foreach ($wnRootItem in @($Root)) {
        if (-not $wnRootItem) { continue }
        $wnRootTrim = ([string]$wnRootItem).TrimEnd('\')
        foreach ($wnRootForm in @($wnRootTrim.Replace('\', '\\'), $wnRootTrim)) {
            $wnC = [regex]::Replace($wnC, [regex]::Escape($wnRootForm), '<ROOT>', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        }
    }
    $wnHeadAt = 0
    foreach ($wnHeadItem in @($Head)) {
        $wnHeadAt++
        if ([string]$wnHeadItem -cmatch '\A[0-9a-f]{40}\z') { $wnC = $wnC.Replace([string]$wnHeadItem, ('<HEAD' + $wnHeadAt + '>')) }
    }
    $wnMaskAt = 0
    foreach ($wnMaskItem in @($Mask)) {
        $wnMaskAt++
        if ($wnMaskItem) { $wnC = $wnC.Replace([string]$wnMaskItem, ('<MASK' + $wnMaskAt + '>')) }
    }
    return $wnC
}

# =============================================================================================
# C-1ap -- THE INPUT TREE A CAPTURE STOOD ON: under
#          `instrument_inputs_except: [p1, p2]` a capture whose head is not HEAD is still reused where
#          the head's tree, less those paths, is HEAD's -- and nowhere else
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: the base stores the goal
# key and reads it nowhere. Its capture carries eighteen header keys and no input_tree, and after a commit
# that touches ONLY the excluded path it declines the capture by its head alone -- "its head is <H1>, and
# HEAD is <H2>" -- and runs the instrument again: a commit that moves no input of the instrument still
# costs a whole run of it.
# THE RULE. The helper, given
# -InstrumentInputsExcept, writes a nineteenth header key, input_tree: the sha256 of the head's tree less
# the excluded paths (Get-LamInputTree -- one function, in the helper). The evaluator launches through that
# parameter where the goal declares the key, and WIDENS the head condition: a capture is declined for its
# head only where its head is not HEAD AND its input_tree is not HEAD's; every later condition still
# applies. The detail of such a reuse says ADMITTED BY ITS INPUT TREE and names the capture's own head; two
# verdict keys carry the list with the figure at HEAD (instrument_inputs_except) and every reuse the figure
# admitted (instrument_input_tree_matched). What cannot be derived reuses nothing by inputs and says why;
# a list, or an item, the evaluator cannot read FAILS the detector by name and the instrument is not run.
# WIDENED, NOT BRANCHED, HAS ROWS OF ITS OWN, one for each later condition a capture the figure admits can
# fail by itself: (c2) its instrument_sha256 -- the instrument lives under the admitted scratch/ and is in
# no figure, and a cure that reused on the figure alone reads RED there --; (c3) its tree_clean -- taken
# while a tracked input held uncommitted bytes --; (c4) the window -- forty minutes old under a window of 30.
# (c3) and (c4) are CONTROLS (the independent validator's round 3): the evaluator read them ok
# when they were written, and each holds one wrong cure that every row before it let through -- the
# figure's admission put ahead of that one test. (c5) is EIGHT CONTROLS more, the same class followed down
# the rest of the chain by the builder's own mutation sweep after that round: no instrument_resolved,
# another file's, ran: False, an exit_code that is no number, a captured_at that does not parse, is not
# UTC, is in the future -- and a RED capture, which the figure admits and the RED rule then re-measures.
# (g2) drives the two decline sentences no other row does: a capture that carries no input_tree, and one
# whose input_tree is not a figure. (p), two CONTROLS from the same sweep, is the one place a NESTED exclusion
# is measured for what it takes out: its one path (a commit to it alone is reused over) and not the
# directory opened for it (a commit to a sibling is not).
# THE CONTROLS, each a row: a goal WITHOUT the key writes, at three stops, the artifact and the capture the
# base writes (twin fixtures; equal but for the clock, the fixtures' own paths and ids, and the kept-copies
# listing this batch adds to a MET verdict); the helper called without the parameter writes the
# base's eighteen keys; an untracked file that is NOT admitted still stops every reuse. AND TWO ROWS STATED,
# NOT CLAIMED: an ADMITTED untracked file does not stop a reuse by inputs, and a change reverted between
# two commits is reused -- the figure is of the two ends, there is no history condition (D14).
# THE FIGURE IS ASKED OF THIS TREE's HELPER IN A CHILD (Get-C1apFigure), never of the helper this instrument
# loaded, and derived once more HERE from `git ls-tree`, as the rule words it (Get-C1apOwnFigure).
$c1apOk = $true
$c1apRows = New-Object System.Collections.Generic.List[string]
function Add-C1apRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1apOk = $false }
    $script:c1apRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1apRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1apReading {
    # ONE HAND EVALUATION of -GoalId at -Root by -Tools: how many times the stub RAN during it (its own
    # counter's delta), the instrument_exit0 entry, and the four list keys this member reads -- each $null
    # where the artifact does not write the key and an empty array where it writes `[]` (Get-WnList).
    param([string]$Tools = 'tree', [string]$Root, [string]$GoalId)
    $c1apBefore = Get-WnRuns -Root $Root
    $c1apEv = Invoke-WnEval -Tools $Tools -Root $Root -GoalId $GoalId
    $c1apRan = (Get-WnRuns -Root $Root) - $c1apBefore
    $c1apDet = Get-WnInst -Eval $c1apEv
    return [pscustomobject]@{ exit = $c1apEv.exit; verdict = [string]$c1apEv.verdict; ran = $c1apRan; found = $c1apDet.found; ok = $c1apDet.ok; detail = [string]$c1apDet.detail; text = [string]$c1apEv.artifactText
                              except = (Get-WnList -Eval $c1apEv -Key 'instrument_inputs_except'); matched = (Get-WnList -Eval $c1apEv -Key 'instrument_input_tree_matched')
                              kept = (Get-WnList -Eval $c1apEv -Key 'instrument_captures_kept'); onDisk = (Get-WnList -Eval $c1apEv -Key 'instrument_captures_kept_on_disk')
                              said = ($Tools + ': exit ' + $c1apEv.exit + ', ' + $c1apEv.verdict + ', the stub ran ' + $c1apRan) }
}
function Get-C1apShown {
    # A verdict list key as a row prints it: not written, written empty, or its items.
    param($List)
    if ($null -eq $List) { return '(the key is not written)' }
    if (@($List).Count -eq 0) { return '[]' }
    return ('[' + (@($List) -join ' | ') + ']')
}
function Test-C1apOnly {
    # Does a verdict list key hold EXACTLY ONE item, and is that item -Item, character for character?
    param($List, [string]$Item)
    return (($null -ne $List) -and (@($List).Count -eq 1) -and ([string]@($List)[0] -ceq $Item))
}
function Get-C1apFirst {
    # The one item of a verdict list key, or '' where the key is not written or does not hold exactly one.
    param($List)
    if (($null -eq $List) -or (@($List).Count -ne 1)) { return '' }
    return [string]@($List)[0]
}
function Get-C1apOnDisk {
    # How many entries stand under <root>\.mission-runtime\lam\instrument-runs: 0 where nothing was written.
    param([string]$Root)
    $c1apRunsAt = Join-Path $Root '.mission-runtime\lam\instrument-runs'
    if (-not (Test-Path -LiteralPath $c1apRunsAt -PathType Container)) { return 0 }
    return @(Get-ChildItem -LiteralPath $c1apRunsAt -Force).Count
}
function Get-C1apKeyAt {
    # Where a column-0 `<Key>:` line opens in a verdict artifact, or -1: the order of two keys is read off it.
    param([string]$Text, [string]$Key)
    $c1apKm = [regex]::Match([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':')
    if ($c1apKm.Success) { return $c1apKm.Index }
    return -1
}
function Get-C1apTwinText {
    # "EQUAL BUT FOR THE CLOCK AND THE FIXTURE's OWN PATHS", for an artifact or a capture of one of two TWIN
    # fixtures: Get-WnComparable with the fixture's root, its two heads (before and after the empty commit),
    # the first eight of each (verify's predicate quotes a head by its first eight in tree_reason) and the
    # reused capture's sha256 named. AND ONE KEY TAKEN OUT FIRST, the block this batch adds to every
    # MET artifact of a goal with a window, instrument_captures_kept_on_disk: the base never writes it, and
    # it is another member's (C-1at). AND, SINCE BATCH-7 WP-R (c), the provenance line hook_or_hand
    # (Remove-WrProvenanceLine): the base writes none. Nothing else is removed.
    param([string]$Text, [string]$Root, [string[]]$Heads, [string]$Sha)
    $c1apCut = Remove-WrProvenanceLine -Text ([regex]::Replace([string]$Text, '(?m)^instrument_captures_kept_on_disk:.*\r?\n(?:  - .*\r?\n)*', ''))
    $c1apMask = @()
    if ($Sha -and ($Sha.Length -ge 8)) { $c1apMask += @($Sha, $Sha.Substring(0, 8)) }
    foreach ($c1apHd in @($Heads)) { if ($c1apHd -and ($c1apHd.Length -ge 8)) { $c1apMask += $c1apHd.Substring(0, 8) } }
    return (Get-WnComparable -Text $c1apCut -Root $Root -Head $Heads -Mask $c1apMask)
}
# THE CHILD THAT ASKS THE TREE's HELPER FOR ONE FIGURE (Get-C1apFigure). It dot-sources ONE helper file and
# calls Get-LamInputTree; where the helper defines no such function -- the base, and this tree until the cure
# -- it says so and calls nothing. What the call throws is CAUGHT and written into the result. The request
# and the result are files, so no path and no list item rides on a command line.
$c1apFigureDriverText = @'
param([string]$Request, [string]$Result)
$c1apOut = [ordered]@{ ok = $false; why = ''; has_function = $false; fn_ok = $false; figure = ''; fn_why = ''; members = @() }
try {
    $c1apReq = [System.IO.File]::ReadAllText($Request) | ConvertFrom-Json
    . ([string]$c1apReq.helper)
    $c1apOut.has_function = [bool](Get-Command -Name Get-LamInputTree -CommandType Function -ErrorAction SilentlyContinue)
    if (-not $c1apOut.has_function) { $c1apOut.why = 'the helper defines no function Get-LamInputTree' }
    else {
        $c1apFig = Get-LamInputTree -MissionRoot ([string]$c1apReq.root) -Head ([string]$c1apReq.head) -Except ([string[]]@($c1apReq.except))
        $c1apOut.members = @($c1apFig.PSObject.Properties.Name)
        $c1apOut.fn_ok = [bool]$c1apFig.ok
        $c1apOut.figure = [string]$c1apFig.figure
        $c1apOut.fn_why = [string]$c1apFig.why
        $c1apOut.ok = $true
    }
} catch { $c1apOut.why = ($_.Exception.GetType().Name + ': ' + (([string]$_.Exception.Message) -replace '[\r\n]+', ' ')) }
[System.IO.File]::WriteAllText($Result, ($c1apOut | ConvertTo-Json -Compress), (New-Object System.Text.UTF8Encoding($false)))
'@
function Get-C1apFigure {
    # Get-LamInputTree OF THIS TREE's HELPER, asked in a CHILD PROCESS ($c1apFigureDriverText, written once
    # under -WorkDir) for -Head at -Root less -Except. Returns ok (the child called the function and it
    # returned), why, hasFunction, fnOk (the function's own ok), figure, fnWhy, members (the returned
    # object's member names, comma-joined) and childExit. IT NEVER THROWS for what the child could not do.
    param([string]$WorkDir, [string]$Root, [string]$Head, [string[]]$Except)
    $c1apFg = [pscustomobject]@{ ok = $false; why = ''; hasFunction = $false; fnOk = $false; figure = ''; fnWhy = ''; members = ''; childExit = $null }
    $c1apDriver = Join-Path $WorkDir 'c1ap-figure-driver.ps1'
    if (-not (Test-Path -LiteralPath $c1apDriver -PathType Leaf)) { Write-Utf8 -Path $c1apDriver -Text ($script:c1apFigureDriverText -replace "`r", '') }
    $c1apTicket = [guid]::NewGuid().ToString('N').Substring(0, 8)
    $c1apReqPath = Join-Path $WorkDir ('figure-' + $c1apTicket + '.request.json')
    $c1apResPath = Join-Path $WorkDir ('figure-' + $c1apTicket + '.result.json')
    $c1apAsk = [ordered]@{ helper = (Join-Path $repoRoot 'tools\lam\lam-instrument-run.ps1'); root = $Root; head = $Head; except = @($Except | Where-Object { $null -ne $_ }) }
    Write-Utf8 -Path $c1apReqPath -Text ($c1apAsk | ConvertTo-Json -Compress)
    $c1apPrevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $c1apChild = & powershell -NoProfile -ExecutionPolicy Bypass -File $c1apDriver -Request $c1apReqPath -Result $c1apResPath 2>&1; $c1apFg.childExit = $LASTEXITCODE }
    finally { $ErrorActionPreference = $c1apPrevEap }
    $c1apRes = $null
    if (Test-Path -LiteralPath $c1apResPath -PathType Leaf) { try { $c1apRes = [System.IO.File]::ReadAllText($c1apResPath) | ConvertFrom-Json } catch { $c1apRes = $null } }
    Remove-Item -LiteralPath $c1apReqPath -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $c1apResPath -Force -ErrorAction SilentlyContinue
    if ($null -eq $c1apRes) { $c1apFg.why = 'the figure child wrote no result (exit ' + $c1apFg.childExit + '): ' + (((@($c1apChild) | ForEach-Object { [string]$_ }) -join ' ') -replace '\s+', ' '); return $c1apFg }
    $c1apFg.ok = [bool]$c1apRes.ok
    $c1apFg.why = [string]$c1apRes.why
    $c1apFg.hasFunction = [bool]$c1apRes.has_function
    $c1apFg.fnOk = [bool]$c1apRes.fn_ok
    $c1apFg.figure = [string]$c1apRes.figure
    $c1apFg.fnWhy = [string]$c1apRes.fn_why
    $c1apFg.members = (@($c1apRes.members) -join ',')
    return $c1apFg
}
function Get-C1apFigureSaid {
    # What Get-C1apFigure read, as a row prints it: the function's ok and figure, the members of what it
    # returned -- or why there is nothing to print (no such function; the child's own failure; the function's why).
    param($Figure)
    if (-not $Figure.ok) { return ('NOT ASKED -- ' + [string]$Figure.why) }
    return ('ok ' + $Figure.fnOk + ', figure [' + [string]$Figure.figure + ']' + $(if ($Figure.fnWhy) { ', why: ' + [string]$Figure.fnWhy } else { '' }) + ', returned members: ' + [string]$Figure.members)
}
function Get-C1apOwnFigure {
    # THE FIGURE AS THE RULE WORDS IT, DERIVED HERE AND NOT BY THE HELPER -- for exclusions that are entries
    # of the head's ROOT tree (no ancestor to open): `git -c core.quotePath=true ls-tree <head>`, every line
    # `<mode> <type> <oid><TAB><path>`, the excluded entries dropped, the rest sorted by path with an ORDINAL
    # comparer, each followed by LF; THEN THE LIST ITSELF (the builder-side review's finding: the figure
    # binds the list it was taken under) -- one line per distinct exclusion, in ordinal order: the word
    # `except`, a TAB, the path, LF; and the sha256 of that text's UTF-8 bytes, lower-case hex. '' where git
    # does not answer or a line is not of that form.
    param([string]$Root, [string]$Head, [string[]]$Except)
    $c1apLs = Invoke-PwGit -Root $Root -GitArgs @('-c', 'core.quotePath=true', 'ls-tree', $Head)
    if ($c1apLs.exit -ne 0) { return '' }
    $c1apKeptLines = New-Object 'System.Collections.Generic.SortedDictionary[string,string]' ([System.StringComparer]::Ordinal)
    foreach ($c1apLn in @($c1apLs.text -split "`n")) {
        if (-not $c1apLn) { continue }
        $c1apLm = [regex]::Match($c1apLn, '\A[0-7]{6} (?:blob|tree|commit) [0-9a-f]{40}\t(.+)\z')
        if (-not $c1apLm.Success) { return '' }
        if (@($Except) -ccontains $c1apLm.Groups[1].Value) { continue }
        $c1apKeptLines[$c1apLm.Groups[1].Value] = $c1apLn
    }
    $c1apFigText = New-Object System.Text.StringBuilder
    foreach ($c1apPathKey in @($c1apKeptLines.Keys)) { [void]$c1apFigText.Append($c1apKeptLines[$c1apPathKey] + "`n") }
    $c1apListed = New-Object 'System.Collections.Generic.SortedSet[string]' ([System.StringComparer]::Ordinal)
    foreach ($c1apExcluded in @($Except)) { if ($c1apExcluded) { [void]$c1apListed.Add([string]$c1apExcluded) } }
    foreach ($c1apExcluded in $c1apListed) { [void]$c1apFigText.Append('except' + "`t" + $c1apExcluded + "`n") }
    return (Get-PwSha256 -Bytes ($pwUtf8.GetBytes($c1apFigText.ToString())))
}
$c1apM = $null
$c1apM2 = $null
try {
$c1apHex64 = '\A[0-9a-f]{64}\z'
$c1apBaseKeys = 'writer,capture_format,run_key,goal,detector_ordinal,instrument,cwd,captured_at,ran,exit_code,tally_count,body_bytes,body_sha256,head,tree_clean,tree_reason,instrument_sha256,instrument_resolved'
$c1apWindow = @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30')
# THE THIRTEEN FAULTY LISTS OF ROW (h): eleven items the evaluator must refuse BY NAME (item is the item as
# the list reader hands it over), and two lists the list reader itself refuses (item ''). THE LAST FIVE WERE
# ADDED BY THE BUILDER's OWN MUTATION SWEEP after the independent validator's round 3: the first six items
# drove three of the six characters the rule names and one of its three segment kinds, and an item rule
# narrowed to those -- one that read an item holding `?`, `[` or `]`, or a `.` or an empty segment -- read
# every row ok. Each character and each segment kind now has an item of its own. (The list reader splits at
# commas and nowhere else: `[[a, other]` is the items `[a` and `other`, and `[a], other]` is `a]` and `other`.)
$c1apFaulty = @(
    @{ id = 'G-WNAP-H1'; lines = @('    instrument_inputs_except: [../x]'); what = '[../x] -- an item with a .. segment'; item = '../x' },
    @{ id = 'G-WNAP-H2'; lines = @('    instrument_inputs_except: [a\b]'); what = '[a\b] -- an item holding a backslash'; item = 'a\b' },
    @{ id = 'G-WNAP-H3'; lines = @('    instrument_inputs_except: [/abs]'); what = '[/abs] -- an item that begins with /'; item = '/abs' },
    @{ id = 'G-WNAP-H4'; lines = @('    instrument_inputs_except: [x:y]'); what = '[x:y] -- an item holding a colon'; item = 'x:y' },
    @{ id = 'G-WNAP-H5'; lines = @('    instrument_inputs_except: [a*]'); what = '[a*] -- an item holding a wildcard'; item = 'a*' },
    @{ id = 'G-WNAP-H6'; lines = @('    instrument_inputs_except: [other, other]'); what = '[other, other] -- an item that repeats an earlier one'; item = 'other' },
    @{ id = 'G-WNAP-H7'; lines = @('    instrument_inputs_except: []'); what = '[] -- an empty list'; item = '' },
    @{ id = 'G-WNAP-H8'; lines = @('    instrument_inputs_except:', '      - other'); what = 'a BLOCK list -- the key with nothing after its colon, `- other` on the line under it'; item = '' },
    @{ id = 'G-WNAP-H9'; lines = @('    instrument_inputs_except: [a?]'); what = '[a?] -- an item holding a question mark'; item = 'a?'; sweep = $true },
    @{ id = 'G-WNAP-H10'; lines = @('    instrument_inputs_except: [[a, other]'); what = '[[a, other] -- an item holding an OPENING bracket (the items are `[a` and `other`)'; item = '[a'; sweep = $true },
    @{ id = 'G-WNAP-H11'; lines = @('    instrument_inputs_except: [a], other]'); what = '[a], other] -- an item holding a CLOSING bracket (the items are `a]` and `other`)'; item = 'a]'; sweep = $true },
    @{ id = 'G-WNAP-H12'; lines = @('    instrument_inputs_except: [./other]'); what = '[./other] -- an item with a . segment'; item = './other'; sweep = $true },
    @{ id = 'G-WNAP-H13'; lines = @('    instrument_inputs_except: [inputs//a.txt]'); what = '[inputs//a.txt] -- an item with an EMPTY segment'; item = 'inputs//a.txt'; sweep = $true })
$c1apGoals = [ordered]@{}
$c1apGoals['G-WNAP'] = $c1apWindow + @('    instrument_inputs_except: [other]')
$c1apGoals['G-WNAP-NOKEY'] = $c1apWindow
$c1apGoals['G-WNAP-F'] = $c1apWindow + @('    instrument_inputs_except: [nosuch]')
$c1apGoals['G-WNAP-F2'] = $c1apWindow + @('    instrument_inputs_except: [scratch]')
$c1apGoals['G-WNAP-F3'] = $c1apWindow + @('    instrument_inputs_except: [OTHER]')
$c1apGoals['G-WNAP-G'] = $c1apWindow + @('    instrument_inputs_except: [other, inputs/a.txt]')
$c1apGoals['G-WNAP-M'] = $c1apWindow + @('    instrument_inputs_except: [.mission]')
# ... and two goals the builder-side review's findings are driven through: a WIDER list over the same
# instrument (row (g3)), and a list naming the ignore file in ANOTHER CASE (row (m3)).
$c1apGoals['G-WNAP-WIDE'] = $c1apWindow + @('    instrument_inputs_except: [other, extra]')
$c1apGoals['G-WNAP-CASE'] = $c1apWindow + @('    instrument_inputs_except: [.GitIgnore]')
foreach ($c1apHx in $c1apFaulty) { $c1apGoals[$c1apHx.id] = $c1apWindow + @($c1apHx.lines) }
# TWO FIXTURES, TWINS: the same goals in one commit each. The first is where every row of this tree is
# driven; the second is the base's own -- its sequences never see a capture this tree's tools wrote.
$c1apM = New-WnMission -Tag 'c1ap' -Goals $c1apGoals
if (-not $c1apM.ok) { throw ('FIXTURE REFUSED: ' + $c1apM.why) }
$c1apM2 = New-WnMission -Tag 'c1apb' -Goals $c1apGoals
if (-not $c1apM2.ok) { throw ('THE BASE''s FIXTURE REFUSED: ' + $c1apM2.why) }
$c1apRoot = $c1apM.root
$c1apRoot2 = $c1apM2.root
$c1apInst = Write-WnStub -Root $c1apRoot
$null = Write-WnStub -Root $c1apRoot2
$c1apLive = Join-Path $c1apM.runsDir 'G-WNAP.inst.stdout.txt'
$c1apLive2 = Join-Path $c1apM2.runsDir 'G-WNAP.inst.stdout.txt'
$c1apH1 = $c1apM.head
$c1apH1b = $c1apM2.head
Add-C1apRow -Label ('FIXTURE two git repositories under %TEMP%, twins -- one for this tree''s rows, one for the base''s own sequences --, the base tools pinned; in each .gitignore, mission.yaml (admitted_porcelain: "?? scratch/"), inputs/a.txt, other/b.txt and the ' + $c1apGoals.Count + ' goals in ONE commit; porcelain reads exactly "?? scratch/" in both') `
    -Ok ($wnBase.ok -and ((Get-WnPorcelain -Root $c1apRoot) -ceq '?? scratch/') -and ((Get-WnPorcelain -Root $c1apRoot2) -ceq '?? scratch/') -and ($c1apH1 -cmatch '\A[0-9a-f]{40}\z') -and ($c1apH1b -cmatch '\A[0-9a-f]{40}\z') -and ($c1apH1 -cne $c1apH1b) -and
         ($c1apInst -ceq (Join-Path $c1apRoot 'scratch\inst.ps1'))) -Said ('HEAD ' + $c1apH1 + ' and, the base''s fixture, ' + $c1apH1b + '; ' + $wnBase.said)

# (a) A FRESH RUN UNDER THE KEY. The base first, in its own fixture: eighteen keys, no input_tree, no new key.
Clear-WnCaptures -Root $c1apRoot2
$c1apRaBase = Get-C1apReading -Tools base -Root $c1apRoot2 -GoalId 'G-WNAP'
$c1apCapA2 = Read-WnCapture -Path $c1apLive2
Add-C1apRow -Label '(a) BASE CONTROL: the base over `reuse_within_minutes: 30` + `instrument_inputs_except: [other]`, nothing on disk: the stub RUNS, MET, and the capture''s header holds the EIGHTEEN keys in order and no input_tree line -- the base stores the goal key and reads it nowhere; the artifact writes neither new key' `
    -Ok ($wnBase.ok -and ($c1apRaBase.ran -eq 1) -and ($c1apRaBase.verdict -ceq 'MET') -and $c1apCapA2.ok -and ((@($c1apCapA2.headerKeys) -join ',') -ceq $c1apBaseKeys) -and (-not [regex]::IsMatch($c1apCapA2.text, '(?m)^input_tree:')) -and
         ([string]$c1apCapA2.header['head'] -ceq $c1apH1b) -and ($null -eq $c1apRaBase.except) -and ($null -eq $c1apRaBase.matched)) `
    -Said ($c1apRaBase.said + '; header keys: ' + (@($c1apCapA2.headerKeys) -join ',') + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRaBase.except) + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRaBase.matched))
# (a) ... AND THIS TREE: the nineteenth key, the last line of the header, 64 hex.
Clear-WnCaptures -Root $c1apRoot
$c1apRa = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apCapA = Read-WnCapture -Path $c1apLive
$c1apF1 = [string]$c1apCapA.header['input_tree']
$c1apShaA = [string]$c1apCapA.sha256
Add-C1apRow -Label '(a) FALSIFIER this tree, the same goal, nothing on disk: the stub RUNS, MET, and the capture''s header is the base''s eighteen keys in order and then ONE more, its LAST `key: value` line -- input_tree: <64 hex> -- capture_format still 1, head the fixture''s HEAD' `
    -Ok (($c1apRa.ran -eq 1) -and ($c1apRa.verdict -ceq 'MET') -and $c1apCapA.ok -and ((@($c1apCapA.headerKeys) -join ',') -ceq ($c1apBaseKeys + ',input_tree')) -and ($c1apF1 -cmatch $c1apHex64) -and
         ([string]$c1apCapA.header['capture_format'] -ceq '1') -and ([string]$c1apCapA.header['head'] -ceq $c1apH1)) `
    -Said ($c1apRa.said + '; header keys: ' + (@($c1apCapA.headerKeys) -join ',') + '; input_tree: [' + $c1apF1 + ']; detail: ' + $c1apRa.detail)
Add-C1apRow -Label '(a) FALSIFIER ... and that evaluation''s artifact carries the two keys: instrument_inputs_except with ONE item -- `inst.ps1: except [other]; input_tree at HEAD <the capture''s own figure>` -- and instrument_input_tree_matched written and EMPTY (nothing was reused by the figure)' `
    -Ok (($c1apF1 -cmatch $c1apHex64) -and (Test-C1apOnly -List $c1apRa.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apF1)) -and ($null -ne $c1apRa.matched) -and (@($c1apRa.matched).Count -eq 0)) `
    -Said ('instrument_inputs_except ' + (Get-C1apShown -List $c1apRa.except) + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRa.matched))

# (b) THE CHARTER's FALSIFIER: a commit that touches ONLY the excluded path. The base first.
$c1apH2b = Invoke-WnCommit -Root $c1apRoot2 -Path $c1apM2.otherRel -Text "not an input of the instrument, and changed`n" -Message 'other/ alone changes'
if (-not $c1apH2b) { throw 'FIXTURE SLIP: the commit under other/ did not land in the base''s fixture' }
$c1apRbBase = Get-C1apReading -Tools base -Root $c1apRoot2 -GoalId 'G-WNAP'
Add-C1apRow -Label '(b) BASE CONTROL: the base, its own fixture, the same sequence -- a fresh run at H1, then ONE commit that touches only other/b.txt: the stub RUNS AGAIN, the capture declined by its head alone, in the words "its head is <H1>, and HEAD is <H2>"' `
    -Ok ($wnBase.ok -and ($c1apRbBase.ran -eq 1) -and ($c1apRbBase.verdict -ceq 'MET') -and (-not $c1apRbBase.detail.Contains('REUSED')) -and $c1apRbBase.detail.Contains('its head is ' + $c1apH1b + ', and HEAD is ' + $c1apH2b + '.') -and ($null -eq $c1apRbBase.matched)) `
    -Said ($c1apRbBase.said + '; detail: ' + $c1apRbBase.detail)
$c1apH2 = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text "not an input of the instrument, and changed`n" -Message 'other/ alone changes'
if (-not $c1apH2) { throw 'FIXTURE SLIP: the commit under other/ did not land' }
$c1apKeptA = Join-Path $c1apM.runsDir ('G-WNAP.inst.' + $(if ($c1apShaA.Length -ge 8) { $c1apShaA.Substring(0, 8) } else { 'no-sha' }) + '.stdout.txt')
$c1apRb = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apKeptASha = if (Test-Path -LiteralPath $c1apKeptA -PathType Leaf) { Get-PwRawSha -Path $c1apKeptA } else { '(no kept copy on disk)' }
$c1apBKept = Get-C1apKeyAt -Text $c1apRb.text -Key 'instrument_captures_kept'
$c1apBOnDisk = Get-C1apKeyAt -Text $c1apRb.text -Key 'instrument_captures_kept_on_disk'
$c1apBExcept = Get-C1apKeyAt -Text $c1apRb.text -Key 'instrument_inputs_except'
$c1apBMatched = Get-C1apKeyAt -Text $c1apRb.text -Key 'instrument_input_tree_matched'
$c1apBDetectors = Get-C1apKeyAt -Text $c1apRb.text -Key 'detectors'
$c1apBOrder = (($c1apBKept -ge 0) -and ($c1apBExcept -gt $c1apBKept) -and ($c1apBMatched -gt $c1apBExcept) -and ($c1apBDetectors -gt $c1apBMatched) -and (($c1apBOnDisk -lt 0) -or (($c1apBOnDisk -gt $c1apBKept) -and ($c1apBOnDisk -lt $c1apBExcept))))
Add-C1apRow -Label '(b) FALSIFIER this tree, the same sequence: the capture taken at H1 is REUSED at H2 -- the stub NOT run, MET --, the detail opening "REUSED A FRESH READING, ", naming HEAD H2 and then "(the capture''s head is <H1>; ADMITTED BY ITS INPUT TREE: input_tree <figure> over the head''s tree less the goal''s 1 instrument_inputs_except path(s) equals HEAD''s -- register row 412)", and ENDING on the kept sentence' `
    -Ok (($c1apRb.ran -eq 0) -and ($c1apRb.verdict -ceq 'MET') -and $c1apRb.ok -and ($c1apF1 -cmatch $c1apHex64) -and $c1apRb.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and
         $c1apRb.detail.Contains(', HEAD ' + $c1apH2 + ' (the capture''s head is ' + $c1apH1 + '; ADMITTED BY ITS INPUT TREE: input_tree ' + $c1apF1 + ' over the head''s tree less the goal''s 1 instrument_inputs_except path(s) equals HEAD''s -- register row 412), the tree clean apart') -and
         $c1apRb.detail.EndsWith('(written now; register row 391).')) `
    -Said ($c1apRb.said + '; detail: ' + $c1apRb.detail)
Add-C1apRow -Label '(b) FALSIFIER ... instrument_input_tree_matched holds exactly ONE item, `<capture path> input_tree <figure> capture_head <H1> head <H2>`; instrument_inputs_except holds `inst.ps1: except [other]; input_tree at HEAD <figure>`; the kept copy stands on disk at its <sha8> name with the capture''s bytes; the two keys stand after instrument_captures_kept and before detectors:' `
    -Ok (($c1apF1 -cmatch $c1apHex64) -and (Test-C1apOnly -List $c1apRb.matched -Item ($c1apLive + ' input_tree ' + $c1apF1 + ' capture_head ' + $c1apH1 + ' head ' + $c1apH2)) -and (Test-C1apOnly -List $c1apRb.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apF1)) -and
         ($c1apKeptASha -ceq $c1apShaA) -and (Test-C1apOnly -List $c1apRb.kept -Item ($c1apKeptA + ' sha256 ' + $c1apShaA)) -and $c1apBOrder) `
    -Said ('instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRb.matched) + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRb.except) + '; instrument_captures_kept ' + (Get-C1apShown -List $c1apRb.kept) + '; the kept copy''s sha256: ' + $c1apKeptASha +
           '; key offsets kept/kept_on_disk/inputs_except/input_tree_matched/detectors: ' + $c1apBKept + '/' + $c1apBOnDisk + '/' + $c1apBExcept + '/' + $c1apBMatched + '/' + $c1apBDetectors)

# (c) ONE BYTE MOVED UNDER A PATH THAT IS NOT EXCLUDED: the figure moves, and the capture is declined in both.
$c1apCapC0 = Read-WnCapture -Path $c1apLive
$c1apC0Head = [string]$c1apCapC0.header['head']
$c1apC0Fig = [string]$c1apCapC0.header['input_tree']
$c1apH3 = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.inputsRel -Text "An input of the instrument`n" -Message 'one byte moves under inputs/'
if (-not $c1apH3) { throw 'FIXTURE SLIP: the commit under inputs/ did not land' }
$c1apRc = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apCapC1 = Read-WnCapture -Path $c1apLive
$c1apCm = [regex]::Match($c1apRc.detail, [regex]::Escape('its head is ' + $c1apC0Head + ', and HEAD is ' + $c1apH3 + '; and its input_tree ') + '([0-9a-f]{64})' + [regex]::Escape(' is not HEAD''s ') + '([0-9a-f]{64})' + [regex]::Escape(' (register row 412)'))
Add-C1apRow -Label '(c) FALSIFIER one byte moved under inputs/a.txt -- NOT excluded -- and committed: the stub RUNS, and the detail reads "its head is <X>, and HEAD is <Y>; and its input_tree <a> is not HEAD''s <b> (register row 412)" -- <a> the declined capture''s own figure, <b> another, the one the fresh capture and the key then carry; nothing matched' `
    -Ok (($c1apRc.ran -eq 1) -and ($c1apRc.verdict -ceq 'MET') -and $c1apCm.Success -and ($c1apCm.Groups[1].Value -ceq $c1apC0Fig) -and ($c1apCm.Groups[2].Value -cne $c1apCm.Groups[1].Value) -and ($c1apCm.Groups[2].Value -ceq [string]$c1apCapC1.header['input_tree']) -and
         (Test-C1apOnly -List $c1apRc.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apCm.Groups[2].Value)) -and ($null -ne $c1apRc.matched) -and (@($c1apRc.matched).Count -eq 0)) `
    -Said ($c1apRc.said + '; the capture stood at head ' + $c1apC0Head + ' with input_tree [' + $c1apC0Fig + ']; the fresh capture''s input_tree [' + [string]$c1apCapC1.header['input_tree'] + ']; instrument_inputs_except ' + (Get-C1apShown -List $c1apRc.except) + '; detail: ' + $c1apRc.detail)

# (c2) THE HEAD CONDITION IS WIDENED, NOT BRANCHED: a capture the figure admits must still pass every later
#      condition. The instrument lives under scratch/ -- untracked, admitted, in NO figure -- so its bytes can
#      change with HEAD's figure unmoved, and the capture's instrument_sha256 is then all that stops the
#      reuse. The capture (c)'s run left stands at its HEAD; a cure that reused on the figure alone runs
#      nothing here. The stub's bytes are put back before anything else is driven. (Where (c) did not leave
#      a capture of its own HEAD -- a cure that reused there -- this row takes one first, and says so.)
$c1apCapC2 = Read-WnCapture -Path $c1apLive
$c1apC2Own = $false
if ((-not $c1apCapC2.ok) -or ([string]$c1apCapC2.header['head'] -cne $c1apH3)) {
    $c1apC2Own = $true
    Clear-WnCaptures -Root $c1apRoot
    $null = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
    $c1apCapC2 = Read-WnCapture -Path $c1apLive
}
$c1apC2Head = [string]$c1apCapC2.header['head']
$c1apC2Fig = [string]$c1apCapC2.header['input_tree']
$c1apStubSha = Get-PwRawSha -Path $c1apInst
$c1apC2New = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text "not an input of the instrument, and changed while the instrument changes too`n" -Message 'other/ alone changes, the instrument about to change'
if (-not $c1apC2New) { throw 'FIXTURE SLIP: the commit under other/ ahead of (c2) did not land' }
Write-Utf8 -Path $c1apInst -Text (($wnStubText -replace "`r", '') + "`n# one line more: these are not the bytes the capture ran`n")
$c1apStubSha2 = Get-PwRawSha -Path $c1apInst
$c1apC2Porc = Get-WnPorcelain -Root $c1apRoot
$c1apRc2 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$null = Write-WnStub -Root $c1apRoot
if ((Get-PwRawSha -Path $c1apInst) -cne $c1apStubSha) { throw 'FIXTURE SLIP: the stub''s bytes were not put back after (c2)' }
Add-C1apRow -Label '(c2) FALSIFIER THE HEAD CONDITION IS WIDENED, NOT BRANCHED -- THE instrument_sha256 CONDITION STILL APPLIES (this row drives that one later condition; rows (c3) and (c4) drive tree_clean and the window, rows (c5) the rest of the chain): the capture (c) left at its HEAD, HEAD then moved by a commit under other/ alone (the figure unmoved) AND the instrument''s own bytes changed (scratch/ is admitted and is in no figure): the capture is NOT declined for its head and IS declined by the next condition it fails -- "(instrument_sha256 differs)", the capture named --, the stub RUNS, nothing REUSED, nothing matched' `
    -Ok ($c1apCapC2.ok -and ($c1apC2Head -ceq $c1apH3) -and ($c1apStubSha2 -cne $c1apStubSha) -and ($c1apC2Porc -ceq '?? scratch/') -and ($c1apRc2.ran -eq 1) -and ($c1apRc2.verdict -ceq 'MET') -and (-not $c1apRc2.detail.Contains('REUSED')) -and
         $c1apRc2.detail.Contains('G-WNAP.inst.stdout.txt: the instrument''s bytes are not the bytes it ran (instrument_sha256 differs)') -and ($null -ne $c1apRc2.matched) -and (@($c1apRc2.matched).Count -eq 0)) `
    -Said ($c1apRc2.said + '; the capture stood at head ' + $c1apC2Head + ' with input_tree [' + $c1apC2Fig + ']' + $(if ($c1apC2Own) { ' (TAKEN FOR THIS ROW: (c) left none of its HEAD)' } else { '' }) + '; the stub''s sha256 ' + $c1apStubSha.Substring(0, 8) + ' -> ' + $c1apStubSha2.Substring(0, 8) + ' for this one evaluation, then put back; porcelain [' + $c1apC2Porc +
           ']; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRc2.matched) + '; detail: ' + $c1apRc2.detail)

# (c3) ... AND ITS tree_clean (the independent validator's round 3). The figure reads the HEAD's
#      tree and never the working tree, so "clean when it was taken" is the one thing that ties the bytes
#      the instrument read to the figure its capture carries. A tracked input is given uncommitted bytes; a
#      hand capture is taken through this tree's helper under the goal's list -- its header says tree_clean:
#      False and carries the figure of that HEAD all the same --; the input is put back to its committed
#      bytes; ONE commit under other/ alone then moves HEAD. The capture's head is not HEAD, its figure IS
#      HEAD's, and nothing but tree_clean stands between it and a reuse. A CONTROL: this tree declines it in
#      the chain's own words and runs the stub. IT HAS NO RED OF RECORD OVER A WRONG CURE OF OURS: the
#      validator's own mutation run drove the wrong cure -- `(-not $ruByTree) -and` put ahead of the
#      tree_clean test -- and every row then standing read ok over it.
Clear-WnCaptures -Root $c1apRoot
$c1apC3Head = Get-WnHead -Root $c1apRoot
$c1apC3Bytes = [System.IO.File]::ReadAllBytes($c1apM.inputsFile)
[System.IO.File]::WriteAllBytes($c1apM.inputsFile, $pwUtf8.GetBytes("an input of the instrument, EDITED AND NOT COMMITTED`n"))
$c1apC3Dirty = Get-WnPorcelain -Root $c1apRoot
$c1apC3Cap = New-WnCapture -Tools tree -Root $c1apRoot -Key 'DIRTY' -Except @('other')
[System.IO.File]::WriteAllBytes($c1apM.inputsFile, $c1apC3Bytes)
if ((Get-WnPorcelain -Root $c1apRoot) -cne '?? scratch/') { throw 'FIXTURE SLIP: inputs/a.txt was not put back to its committed bytes after (c3)''s capture' }
$c1apC3New = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text "not an input of the instrument, changed after a capture over a tree that was not clean`n" -Message 'other/ alone changes, a capture of a dirty tree standing'
if (-not $c1apC3New) { throw 'FIXTURE SLIP: the commit under other/ ahead of (c3) did not land' }
$c1apRc3 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apC3Fig = [string]$c1apC3Cap.header['input_tree']
Add-C1apRow -Label '(c3) CONTROL WIDENED, NOT BRANCHED -- THE tree_clean CONDITION STILL APPLIES: a hand capture taken through this tree''s helper under [other] WHILE THE TRACKED inputs/a.txt HELD UNCOMMITTED BYTES (its header: tree_clean: False, and input_tree the figure of that HEAD), the input then put back, HEAD then moved by a commit under other/ alone: the capture''s figure IS HEAD''s -- it is NOT declined for its head -- and it IS declined "the tree was not clean, or not read, when it was taken (tree_clean: False)", the capture named; the stub RUNS, nothing REUSED, nothing matched; a cure that put the figure''s admission ahead of the tree_clean test would reuse it (the independent validator''s round 3)' `
    -Ok ($c1apC3Cap.ok -and ($c1apC3Cap.exit -eq 0) -and $c1apC3Dirty.Contains('M inputs/a.txt') -and ([string]$c1apC3Cap.header['head'] -ceq $c1apC3Head) -and ([string]$c1apC3Cap.header['tree_clean'] -ceq 'False') -and ($c1apC3Fig -cmatch $c1apHex64) -and
         (Test-C1apOnly -List $c1apRc3.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apC3Fig)) -and ($c1apRc3.ran -eq 1) -and ($c1apRc3.verdict -ceq 'MET') -and (-not $c1apRc3.detail.Contains('REUSED')) -and
         $c1apRc3.detail.Contains('DIRTY.inst.stdout.txt: the tree was not clean, or not read, when it was taken (tree_clean: False)') -and (-not $c1apRc3.detail.Contains('DIRTY.inst.stdout.txt: its head is')) -and
         ($null -ne $c1apRc3.matched) -and (@($c1apRc3.matched).Count -eq 0)) `
    -Said ($c1apRc3.said + '; porcelain while the capture was taken [' + ($c1apC3Dirty -replace '\s+', ' ') + ']; the capture: ok ' + $c1apC3Cap.ok + ' [' + $c1apC3Cap.why + '], head ' + [string]$c1apC3Cap.header['head'] + ', tree_clean ' + [string]$c1apC3Cap.header['tree_clean'] + ', input_tree [' + $c1apC3Fig +
           ']; HEAD ' + $c1apC3Head + ' -> ' + $c1apC3New + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRc3.except) + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRc3.matched) + '; detail: ' + $c1apRc3.detail)

# (c4) ... AND THE WINDOW (the same finding). A hand capture through this tree's helper under the goal's list,
#      on a clean tree, AGED AS THIS BATCH AGES ONE (New-WnCapture -AgeSeconds: the header's first captured_at
#      line rewritten to forty minutes ago; the body, and so the body_sha256 the chain holds it to, as the
#      helper wrote them); then ONE commit under other/ alone. Its figure is HEAD's and the goal's window is
#      30: nothing but its age stands between it and a reuse. A CONTROL, with no RED of record over a wrong
#      cure of ours, as (c3): the wrong cure here is `(-not $ruByTree) -and` ahead of the window test.
Clear-WnCaptures -Root $c1apRoot
$c1apC4Head = Get-WnHead -Root $c1apRoot
$c1apC4Cap = New-WnCapture -Tools tree -Root $c1apRoot -Key 'OLD' -Except @('other') -AgeSeconds 2400
$c1apC4New = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text "not an input of the instrument, changed after a capture forty minutes old`n" -Message 'other/ alone changes, an old capture standing'
if (-not $c1apC4New) { throw 'FIXTURE SLIP: the commit under other/ ahead of (c4) did not land' }
$c1apRc4 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apC4Fig = [string]$c1apC4Cap.header['input_tree']
$c1apC4Said = [regex]::Match($c1apRc4.detail, 'OLD\.inst\.stdout\.txt: it is (\d+) minute\(s\) old, outside the window')
Add-C1apRow -Label '(c4) CONTROL WIDENED, NOT BRANCHED -- THE WINDOW STILL APPLIES: a hand capture taken through this tree''s helper under [other] on a clean tree, its captured_at line then rewritten to FORTY MINUTES AGO (the header''s line alone; its body and body_sha256 as written), HEAD then moved by a commit under other/ alone, the goal''s window 30: the capture''s figure IS HEAD''s -- it is NOT declined for its head -- and it IS declined "it is <N> minute(s) old, outside the window", N forty or forty-one, the capture named; the stub RUNS, nothing REUSED, nothing matched; a cure that put the figure''s admission ahead of the window test would reuse it (the independent validator''s round 3)' `
    -Ok ($c1apC4Cap.ok -and ($c1apC4Cap.exit -eq 0) -and ([string]$c1apC4Cap.header['head'] -ceq $c1apC4Head) -and ([string]$c1apC4Cap.header['tree_clean'] -ceq 'True') -and ($c1apC4Fig -cmatch $c1apHex64) -and
         (Test-C1apOnly -List $c1apRc4.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apC4Fig)) -and ($c1apRc4.ran -eq 1) -and ($c1apRc4.verdict -ceq 'MET') -and (-not $c1apRc4.detail.Contains('REUSED')) -and
         $c1apC4Said.Success -and (@('40', '41') -ccontains $c1apC4Said.Groups[1].Value) -and (-not $c1apRc4.detail.Contains('OLD.inst.stdout.txt: its head is')) -and ($null -ne $c1apRc4.matched) -and (@($c1apRc4.matched).Count -eq 0)) `
    -Said ($c1apRc4.said + '; the capture: ok ' + $c1apC4Cap.ok + ' [' + $c1apC4Cap.why + '], head ' + [string]$c1apC4Cap.header['head'] + ', tree_clean ' + [string]$c1apC4Cap.header['tree_clean'] + ', captured_at ' + [string]$c1apC4Cap.header['captured_at'] + ', input_tree [' + $c1apC4Fig +
           ']; HEAD ' + $c1apC4Head + ' -> ' + $c1apC4New + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRc4.except) + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRc4.matched) + '; detail: ' + $c1apRc4.detail)

# (c5) ... AND EVERY OTHER LATER CONDITION, ONE CAPTURE EACH (the builder's own mutation sweep after the
#      independent validator's round 3: the class of its finding, followed down the rest of the ladder).
#      After the head the chain asks, in this order: does the capture say which file it ran; is that file
#      this detector's; tree_clean (c3); instrument_sha256 (c2); ran; a numeric exit_code; a captured_at
#      that parses, is UTC, is not in the future, and is inside the window (c4) -- and of the capture then
#      chosen, that it exited 0. The figure's admission put ahead of ANY ONE of those takes that test's
#      decline away, and the sweep drove that wrong cure for the seven the rows above do not hold and for
#      the exit code: every row then standing read ok. Read one edit at a time, five of the eight then
#      REUSE the capture (another file's; ran: False; no zone; the future; and a RED, reused as RED), and
#      three are still stopped -- by the next test in its own words, or by a throw where a capture is
#      chosen -- so that only the sentence moves (no instrument_resolved; an exit_code that is no number;
#      a captured_at that does not parse). So EIGHT captures here, each taken by hand through this tree's
#      helper under the goal's list on a clean tree, each given ONE fault -- a header line removed or
#      rewritten as C-1ai rewrites one, or the stub flagged RED while it was taken -- and each followed by
#      a commit under other/ alone: its figure is HEAD's, and that one fault is what the chain names.
#      CONTROLS: the evaluator read them ok when they were written. (The two times are taken when the
#      table below is built, shortly ahead of the rows that use them.)
$c1apC5Reuse = 'a cure that put the figure''s admission ahead of that one test would reuse it'
$c1apC5Cases = @(
    @{ key = 'NORESOLVED'; line = 'instrument_resolved'; drop = $true; what = 'its instrument_resolved line then REMOVED'; says = 'it does not say which file it ran (no instrument_resolved)'; wrong = 'a cure that put the figure''s admission ahead of that one test would decline it in the next test''s words, as a capture of no file, and no longer for what it lacks' }
    @{ key = 'OTHERINST'; line = 'instrument_resolved'; value = (Join-Path $c1apM.scratch 'another.ps1'); what = 'its instrument_resolved line then rewritten to ANOTHER file''s path'; says = ('it is a capture of ' + (Join-Path $c1apM.scratch 'another.ps1') + ', not of this detector''s instrument'); wrong = $c1apC5Reuse }
    @{ key = 'NOTRAN'; line = 'ran'; value = 'False'; what = 'its ran line then rewritten to False'; says = 'the instrument did not run to completion (ran is not True)'; wrong = $c1apC5Reuse }
    @{ key = 'NOEXIT'; line = 'exit_code'; value = 'zero'; what = 'its exit_code line then rewritten to the word zero'; says = 'its exit_code is not a number'; wrong = 'a cure that put the figure''s admission ahead of that one test would hand the word on to the choice of a capture, where the reuse check throws' }
    @{ key = 'NOTIME'; line = 'captured_at'; value = 'not-a-time'; what = 'its captured_at line then rewritten to not-a-time'; says = 'its captured_at does not parse'; wrong = 'a cure that put the figure''s admission ahead of that one test would decline it in the next test''s words, as a time that is not UTC, and no longer as one that does not parse' }
    @{ key = 'NOZONE'; line = 'captured_at'; value = [DateTime]::UtcNow.AddSeconds(-60).ToString('yyyy-MM-ddTHH:mm:ss.fffffff', [System.Globalization.CultureInfo]::InvariantCulture); what = 'its captured_at line then rewritten to the UTC wall time a minute before these rows began WITH NO ZONE (the Z left off)'; says = 'its captured_at is not a UTC time'; wrong = $c1apC5Reuse }
    @{ key = 'FUTURE'; line = 'captured_at'; value = [DateTime]::UtcNow.AddHours(1).ToString('o'); what = 'its captured_at line then rewritten to AN HOUR AFTER these rows began'; says = 'its captured_at is in the future'; wrong = $c1apC5Reuse }
    @{ key = 'REDTREE'; red = $true; what = 'the stub flagged to exit 3 while it was taken -- a RED capture, nothing of it rewritten'; says = 'exited 3: a reading that is not exit 0 is never reused, it is re-measured (register row 412).'; wrong = 'a cure that put the figure''s admission ahead of the RED rule''s first half would reuse it AS RED, the instrument not run' }
)
foreach ($c1apC5 in $c1apC5Cases) {
    Clear-WnCaptures -Root $c1apRoot
    $c1apC5Head = Get-WnHead -Root $c1apRoot
    if ($c1apC5.red) { Set-WnStubFlag -Root $c1apRoot -Exit 3 }
    $c1apC5Cap = New-WnCapture -Tools tree -Root $c1apRoot -Key $c1apC5.key -Except @('other')
    Set-WnStubFlag -Root $c1apRoot
    $c1apC5Name = [string]$c1apC5.key + '.inst.stdout.txt'
    $c1apC5Sha = [string]$c1apC5Cap.sha256
    if ($c1apC5Cap.ok -and $c1apC5.line) {
        $c1apC5Text = [System.IO.File]::ReadAllText($c1apC5Cap.path)
        if ($c1apC5.drop) { $c1apC5Text = ([regex]('(?m)^' + $c1apC5.line + ': .*\r?\n')).Replace($c1apC5Text, '', 1) }
        else { $c1apC5Text = ([regex]('(?m)^' + $c1apC5.line + ': .*$')).Replace($c1apC5Text, ([string]$c1apC5.line + ': ' + ([string]$c1apC5.value).Replace('$', '$$')), 1) }
        [System.IO.File]::WriteAllText($c1apC5Cap.path, $c1apC5Text, (New-Object System.Text.UTF8Encoding($false)))
        $c1apC5Sha = Get-PwRawSha -Path $c1apC5Cap.path
    }
    $c1apC5New = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text ("not an input of the instrument, changed after the capture " + $c1apC5.key + "`n") -Message ('other/ alone changes, the capture ' + $c1apC5.key + ' standing')
    if (-not $c1apC5New) { throw ('FIXTURE SLIP: the commit under other/ ahead of (c5) ' + $c1apC5.key + ' did not land') }
    $c1apRc5 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
    $c1apC5Fig = [string]$c1apC5Cap.header['input_tree']
    $c1apC5Want = if ($c1apC5.red) { 'the newest capture that passes, ' + $c1apC5Name + ' sha256 ' + $c1apC5Sha + ', ' + $c1apC5.says } else { $c1apC5Name + ': ' + $c1apC5.says }
    Add-C1apRow -Label ('(c5) CONTROL WIDENED, NOT BRANCHED -- EVERY OTHER LATER CONDITION STILL APPLIES, ' + $c1apC5.key + ': a hand capture taken through this tree''s helper under [other] on a clean tree, ' + $c1apC5.what + ', HEAD then moved by a commit under other/ alone: its figure IS HEAD''s -- it is NOT declined for its head -- and the detail reads "' + $(if ($c1apC5Sha) { $c1apC5Want.Replace($c1apC5Sha, '<its sha256>') } else { $c1apC5Want }).Replace([string]$c1apM.scratch, '<root>\scratch') + '"; the stub RUNS, nothing REUSED, nothing matched; ' + [string]$c1apC5.wrong + ' (the builder''s own mutation sweep after the independent validator''s round 3)') `
        -Ok ($c1apC5Cap.ok -and ($c1apC5Cap.exit -eq $(if ($c1apC5.red) { 3 } else { 0 })) -and ([string]$c1apC5Cap.header['head'] -ceq $c1apC5Head) -and ([string]$c1apC5Cap.header['tree_clean'] -ceq 'True') -and ($c1apC5Fig -cmatch $c1apHex64) -and
             (Test-C1apOnly -List $c1apRc5.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apC5Fig)) -and ($c1apRc5.ran -eq 1) -and ($c1apRc5.verdict -ceq 'MET') -and (-not $c1apRc5.detail.Contains('REUSED')) -and
             $c1apRc5.detail.Contains($c1apC5Want) -and (-not $c1apRc5.detail.Contains($c1apC5Name + ': its head is')) -and ($null -ne $c1apRc5.matched) -and (@($c1apRc5.matched).Count -eq 0)) `
        -Said ($c1apRc5.said + '; the capture: ok ' + $c1apC5Cap.ok + ' [' + $c1apC5Cap.why + '], exit ' + $c1apC5Cap.exit + ', head ' + [string]$c1apC5Cap.header['head'] + ', input_tree [' + $c1apC5Fig + ']' + $(if ($c1apC5.line) { ', its ' + $c1apC5.line + ' line ' + $(if ($c1apC5.drop) { 'removed' } else { 'now [' + [string]$c1apC5.value + ']' }) } else { '' }) +
               '; HEAD ' + $c1apC5Head + ' -> ' + $c1apC5New + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRc5.matched) + '; detail: ' + $c1apRc5.detail)
}

# (d) NO KEY, BYTE-IDENTICAL: three stops, this tree's tools in one twin and the base's in the other.
Clear-WnCaptures -Root $c1apRoot
Clear-WnCaptures -Root $c1apRoot2
$c1apLiveNo = Join-Path $c1apM.runsDir 'G-WNAP-NOKEY.inst.stdout.txt'
$c1apLiveNo2 = Join-Path $c1apM2.runsDir 'G-WNAP-NOKEY.inst.stdout.txt'
$c1apDHead = Get-WnHead -Root $c1apRoot
$c1apDHead2 = Get-WnHead -Root $c1apRoot2
$c1apD1 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-NOKEY'
$c1apD1Cap = Read-WnCapture -Path $c1apLiveNo
$c1apD1b = Get-C1apReading -Tools base -Root $c1apRoot2 -GoalId 'G-WNAP-NOKEY'
$c1apD1bCap = Read-WnCapture -Path $c1apLiveNo2
$c1apD2 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-NOKEY'
$c1apD2Cap = Read-WnCapture -Path $c1apLiveNo
$c1apD2b = Get-C1apReading -Tools base -Root $c1apRoot2 -GoalId 'G-WNAP-NOKEY'
$c1apD2bCap = Read-WnCapture -Path $c1apLiveNo2
$c1apDNew = Invoke-WnCommit -Root $c1apRoot -Message 'HEAD moves, nothing staged' -AllowEmpty
$c1apDNew2 = Invoke-WnCommit -Root $c1apRoot2 -Message 'HEAD moves, nothing staged' -AllowEmpty
if ((-not $c1apDNew) -or (-not $c1apDNew2)) { throw 'FIXTURE SLIP: an empty commit did not land' }
$c1apD3 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-NOKEY'
$c1apD3Cap = Read-WnCapture -Path $c1apLiveNo
$c1apD3b = Get-C1apReading -Tools base -Root $c1apRoot2 -GoalId 'G-WNAP-NOKEY'
$c1apD3bCap = Read-WnCapture -Path $c1apLiveNo2
$c1apDStops = @(
    @{ n = 1; what = 'nothing on disk -- a fresh run'; ran = 1; t = $c1apD1; b = $c1apD1b; tc = $c1apD1Cap; bc = $c1apD1bCap; tSay = 'no capture of this instrument is on disk'; bSay = 'no capture of this instrument is on disk' },
    @{ n = 2; what = 'the next evaluation at the same HEAD -- REUSED, the stub not run'; ran = 0; t = $c1apD2; b = $c1apD2b; tc = $c1apD2Cap; bc = $c1apD2bCap; tSay = 'REUSED A FRESH READING'; bSay = 'REUSED A FRESH READING' },
    @{ n = 3; what = 'after one EMPTY commit -- declined by its head, in today''s words, and run'; ran = 1; t = $c1apD3; b = $c1apD3b; tc = $c1apD3Cap; bc = $c1apD3bCap
       tSay = ('its head is ' + $c1apDHead + ', and HEAD is ' + $c1apDNew + '.'); bSay = ('its head is ' + $c1apDHead2 + ', and HEAD is ' + $c1apDNew2 + '.') })
foreach ($c1apStop in $c1apDStops) {
    $c1apTwinA = Get-C1apTwinText -Text $c1apStop.t.text -Root $c1apRoot -Heads @($c1apDHead, $c1apDNew) -Sha $c1apD1Cap.sha256
    $c1apTwinA2 = Get-C1apTwinText -Text $c1apStop.b.text -Root $c1apRoot2 -Heads @($c1apDHead2, $c1apDNew2) -Sha $c1apD1bCap.sha256
    $c1apTwinC = Get-C1apTwinText -Text $c1apStop.tc.text -Root $c1apRoot -Heads @($c1apDHead, $c1apDNew) -Sha $c1apD1Cap.sha256
    $c1apTwinC2 = Get-C1apTwinText -Text $c1apStop.bc.text -Root $c1apRoot2 -Heads @($c1apDHead2, $c1apDNew2) -Sha $c1apD1bCap.sha256
    Add-C1apRow -Label ('(d) CONTROL, NO KEY -- a goal WITHOUT instrument_inputs_except, stop ' + $c1apStop.n + ' of 3, ' + $c1apStop.what + ': this tree''s artifact and live capture EQUAL the base''s in the twin fixture, but for the clock, the fixtures'' own paths and ids, and the kept-copies listing cut from both; neither artifact holds instrument_inputs_except: or instrument_input_tree_matched:') `
        -Ok ($wnBase.ok -and ($c1apStop.t.ran -eq $c1apStop.ran) -and ($c1apStop.b.ran -eq $c1apStop.ran) -and ($c1apStop.t.verdict -ceq 'MET') -and ($c1apStop.b.verdict -ceq 'MET') -and $c1apStop.t.detail.Contains($c1apStop.tSay) -and $c1apStop.b.detail.Contains($c1apStop.bSay) -and
             [bool]$c1apStop.t.text -and ($c1apTwinA -ceq $c1apTwinA2) -and $c1apStop.tc.ok -and $c1apStop.bc.ok -and ($c1apTwinC -ceq $c1apTwinC2) -and ((@($c1apStop.tc.headerKeys) -join ',') -ceq $c1apBaseKeys) -and
             ($null -eq $c1apStop.t.except) -and ($null -eq $c1apStop.t.matched) -and ($null -eq $c1apStop.b.except) -and ($null -eq $c1apStop.b.matched)) `
        -Said ($c1apStop.t.said + ' | ' + $c1apStop.b.said + ' | artifacts equal: ' + ($c1apTwinA -ceq $c1apTwinA2) + '; captures equal: ' + ($c1apTwinC -ceq $c1apTwinC2) + '; this tree''s artifact wrote instrument_captures_kept_on_disk: ' + ($null -ne $c1apStop.t.onDisk) +
               '; this tree''s entry, compared form: ' + (Get-PwDetector -Text $c1apTwinA -Type 'instrument_exit0').detail)
}

# (e) DETERMINISM (NOT SOUNDNESS): one head, two checkouts whose working bytes differ, one figure.
$c1apEHead = Get-WnHead -Root $c1apRoot
$c1apClone = Join-Path $c1apM.base 'clone'
$c1apCl = Invoke-PwGit -Root $c1apM.base -GitArgs @('-c', 'core.autocrlf=true', 'clone', '--quiet', '--no-hardlinks', $c1apRoot, $c1apClone)
$c1apClGd = Invoke-PwGit -Root $c1apClone -GitArgs @('rev-parse', '--absolute-git-dir')
if (($c1apCl.exit -ne 0) -or ($c1apClGd.exit -ne 0) -or ([System.IO.Path]::GetFullPath($c1apClGd.text.Trim().Replace('/', '\')) -ine [System.IO.Path]::GetFullPath((Join-Path $c1apClone '.git')))) {
    throw ('FIXTURE REFUSED: the second clone''s git dir is not exactly ' + (Join-Path $c1apClone '.git') + ' (clone exit ' + $c1apCl.exit + ': ' + ($c1apCl.text -replace '\s+', ' ') + '; rev-parse exit ' + $c1apClGd.exit + ': ' + $c1apClGd.text.Trim() + '); nothing further was run in it (the 2026-09-13 rule)')
}
$c1apCloneHead = Get-WnHead -Root $c1apClone
$c1apBytesHere = [System.IO.File]::ReadAllBytes($c1apM.inputsFile)
$c1apBytesThere = [System.IO.File]::ReadAllBytes((Join-Path $c1apClone 'inputs\a.txt'))
$c1apFigHere = Get-C1apFigure -WorkDir $c1apM.base -Root $c1apRoot -Head $c1apEHead -Except @('other')
$c1apFigThere = Get-C1apFigure -WorkDir $c1apM.base -Root $c1apClone -Head $c1apEHead -Except @('other')
Add-C1apRow -Label '(e) FALSIFIER DETERMINISM (not soundness): Get-LamInputTree, dot-sourced from this tree''s helper in a child, asked for ONE head less [other] in the fixture (inputs/a.txt on disk with LF) and in a second clone of it checked out under core.autocrlf=true (the same file with CR LF): the working bytes differ, both answers are ok, and the figure is one 64 hex' `
    -Ok (($c1apCloneHead -ceq $c1apEHead) -and (-not ($c1apBytesHere -contains 13)) -and ($c1apBytesThere -contains 13) -and $c1apFigHere.ok -and $c1apFigHere.fnOk -and ($c1apFigHere.figure -cmatch $c1apHex64) -and $c1apFigThere.ok -and $c1apFigThere.fnOk -and ($c1apFigThere.figure -ceq $c1apFigHere.figure)) `
    -Said ('head ' + $c1apEHead + ', the clone at ' + $c1apCloneHead + '; inputs/a.txt ' + $c1apBytesHere.Length + ' bytes here (CR: ' + ($c1apBytesHere -contains 13) + '), ' + $c1apBytesThere.Length + ' in the clone (CR: ' + ($c1apBytesThere -contains 13) + ') | fixture: ' + (Get-C1apFigureSaid -Figure $c1apFigHere) +
           ' | clone: ' + (Get-C1apFigureSaid -Figure $c1apFigThere))
$c1apFigAtH1 = Get-C1apFigure -WorkDir $c1apM.base -Root $c1apRoot -Head $c1apH1 -Except @('other')
$c1apOwnAtH1 = Get-C1apOwnFigure -Root $c1apRoot -Head $c1apH1 -Except @('other')
$c1apOwnHere = Get-C1apOwnFigure -Root $c1apRoot -Head $c1apEHead -Except @('other')
Add-C1apRow -Label '(e) FALSIFIER ... AND IT IS THE FIGURE THE RULE WORDS: for H1 the function''s answer is the input_tree the capture of (a) carries, and both are this member''s own derivation -- the sha256 of the root tree''s `git ls-tree` lines less `other`, sorted by path ordinally, each followed by LF, and then the list itself, one `except<TAB><path>` line for each exclusion --; for HEAD the function''s answer is the member''s again, and not H1''s (inputs/ moved since)' `
    -Ok (($c1apOwnAtH1 -cmatch $c1apHex64) -and ($c1apOwnHere -cmatch $c1apHex64) -and ($c1apOwnAtH1 -cne $c1apOwnHere) -and $c1apFigAtH1.fnOk -and ($c1apFigAtH1.figure -ceq $c1apOwnAtH1) -and ($c1apF1 -ceq $c1apOwnAtH1) -and $c1apFigHere.fnOk -and ($c1apFigHere.figure -ceq $c1apOwnHere)) `
    -Said ('H1: the function -- ' + (Get-C1apFigureSaid -Figure $c1apFigAtH1) + ' --, the capture of (a) [' + $c1apF1 + '], derived here [' + $c1apOwnAtH1 + '] | HEAD: the function [' + $c1apFigHere.figure + '], derived here [' + $c1apOwnHere + ']')

# (f) AN EXCLUSION THE HEAD DOES NOT HOLD: not derivable, said in the key and, after a commit, in the decline.
foreach ($c1apFx in @(
        @{ id = 'G-WNAP-F'; letter = '(f)'; item = 'nosuch'; what = 'a path neither the head nor the disk holds' },
        @{ id = 'G-WNAP-F2'; letter = '(f2)'; item = 'scratch'; what = 'a directory that IS on disk -- untracked, admitted -- and not in HEAD' },
        @{ id = 'G-WNAP-F3'; letter = '(f3)'; item = 'OTHER'; what = 'a CASE VARIANT of a path the head holds (other)' })) {
    Clear-WnCaptures -Root $c1apRoot
    $c1apFHead = Get-WnHead -Root $c1apRoot
    $c1apRf1 = Get-C1apReading -Root $c1apRoot -GoalId $c1apFx.id
    $c1apFItem = Get-C1apFirst -List $c1apRf1.except
    Add-C1apRow -Label ($c1apFx.letter + ' FALSIFIER AN EXCLUSION THE HEAD DOES NOT HOLD, `instrument_inputs_except: [' + $c1apFx.item + ']` -- ' + $c1apFx.what + ' --, a fresh run: the stub runs, MET, and the key''s one item reads `inst.ps1: except [' + $c1apFx.item + ']; input_tree at HEAD not derivable (` and names the path: "the excluded path ''' + $c1apFx.item + ''' is not a path of <HEAD>"') `
        -Ok (($c1apRf1.ran -eq 1) -and ($c1apRf1.verdict -ceq 'MET') -and $c1apFItem.StartsWith('inst.ps1: except [' + $c1apFx.item + ']; input_tree at HEAD not derivable (') -and $c1apFItem.Contains('the excluded path ''' + $c1apFx.item + ''' is not a path of ' + $c1apFHead)) `
        -Said ($c1apRf1.said + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRf1.except))
    $c1apFNew = Invoke-WnCommit -Root $c1apRoot -Message ('HEAD moves under ' + $c1apFx.id) -AllowEmpty
    if (-not $c1apFNew) { throw 'FIXTURE SLIP: an empty commit did not land' }
    $c1apRf2 = Get-C1apReading -Root $c1apRoot -GoalId $c1apFx.id
    Add-C1apRow -Label ($c1apFx.letter + ' FALSIFIER ... and after a commit NOTHING is reused by inputs: the stub runs, the detail reading "its head is <X>, and HEAD is <Y>; and HEAD''s input tree is not derivable (", naming ''' + $c1apFx.item + ''' again, and ", so nothing is reused by inputs (register row 412)"; nothing matched') `
        -Ok (($c1apRf2.ran -eq 1) -and ($c1apRf2.verdict -ceq 'MET') -and $c1apRf2.detail.Contains('its head is ' + $c1apFHead + ', and HEAD is ' + $c1apFNew + '; and HEAD''s input tree is not derivable (') -and $c1apRf2.detail.Contains('the excluded path ''' + $c1apFx.item + ''' is not a path of ' + $c1apFNew) -and
             $c1apRf2.detail.Contains(', so nothing is reused by inputs (register row 412)') -and ($null -ne $c1apRf2.matched) -and (@($c1apRf2.matched).Count -eq 0)) `
        -Said ($c1apRf2.said + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRf2.matched) + '; detail: ' + $c1apRf2.detail)
}

# (g) THE LIST CHANGED between the capture and the evaluation: the capture's figure is of another list.
Clear-WnCaptures -Root $c1apRoot
$c1apGHead = Get-WnHead -Root $c1apRoot
$c1apRg0 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apCapG = Read-WnCapture -Path $c1apLive
$c1apGNew = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text "not an input of the instrument, and changed again`n" -Message 'other/ alone changes again'
if (-not $c1apGNew) { throw 'FIXTURE SLIP: the second commit under other/ did not land' }
$c1apRg = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-G'
$c1apGm = [regex]::Match($c1apRg.detail, [regex]::Escape('its head is ' + $c1apGHead + ', and HEAD is ' + $c1apGNew + '; and its input_tree ') + '([0-9a-f]{64})' + [regex]::Escape(' is not HEAD''s ') + '([0-9a-f]{64})' + [regex]::Escape(' (register row 412)'))
Add-C1apRow -Label '(g) FALSIFIER THE LIST CHANGED: a capture taken under [other], HEAD then moved by a commit under other/ alone, evaluated by a goal whose list is [other, inputs/a.txt]: DECLINED, the stub runs -- "and its input_tree <the capture''s> is not HEAD''s <another> (register row 412)" --, the key naming the new list and HEAD''s figure under it' `
    -Ok (($c1apRg0.ran -eq 1) -and ($c1apRg.ran -eq 1) -and ($c1apRg.verdict -ceq 'MET') -and $c1apGm.Success -and ($c1apGm.Groups[1].Value -ceq [string]$c1apCapG.header['input_tree']) -and ($c1apGm.Groups[2].Value -cne $c1apGm.Groups[1].Value) -and
         (Test-C1apOnly -List $c1apRg.except -Item ('inst.ps1: except [other, inputs/a.txt]; input_tree at HEAD ' + $c1apGm.Groups[2].Value))) `
    -Said ($c1apRg.said + '; the capture''s input_tree [' + [string]$c1apCapG.header['input_tree'] + ']; instrument_inputs_except ' + (Get-C1apShown -List $c1apRg.except) + '; detail: ' + $c1apRg.detail)

# (g2) THE TWO DECLINE SENTENCES NO OTHER ROW DRIVES, each capture with ONE fault and no other. Two hand
#      captures are taken at HEAD by this tree's helper, nothing else on disk: one WITH a list whose figure is
#      not derivable ([nosuch]) -- its input_tree line then reads "not derivable (...)", which is no figure --
#      and one with NO list, which carries no input_tree at all (what every capture older than the key is).
#      HEAD moves by an empty commit; the goal with [other], whose figure at HEAD IS derivable, is evaluated:
#      neither is admitted, each says why, the stub runs. (Until the cure the helper has no such parameter:
#      the first capture is not taken, and the row says so.)
Clear-WnCaptures -Root $c1apRoot
$c1apG2Head = Get-WnHead -Root $c1apRoot
$c1apG2NoFig = New-WnCapture -Tools tree -Root $c1apRoot -Key 'NOFIGURE' -Except @('nosuch')
$c1apG2Hand = New-WnCapture -Tools tree -Root $c1apRoot -Key 'NOLIST'
$c1apG2NoFigName = if ($c1apG2NoFig.ok) { [System.IO.Path]::GetFileName([string]$c1apG2NoFig.path) } else { '(no capture under a list)' }
$c1apG2HandName = if ($c1apG2Hand.ok) { [System.IO.Path]::GetFileName([string]$c1apG2Hand.path) } else { '(no capture without a list)' }
$c1apG2NoFigLine = [string]$c1apG2NoFig.header['input_tree']
$c1apG2New = Invoke-WnCommit -Root $c1apRoot -Message 'HEAD moves, two hand captures standing' -AllowEmpty
if (-not $c1apG2New) { throw 'FIXTURE SLIP: the empty commit ahead of (g2) did not land' }
$c1apRg2 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
Add-C1apRow -Label '(g2) FALSIFIER THE TWO OTHER DECLINE SENTENCES: two hand captures by this tree''s helper at one head, nothing else on disk -- one given -InstrumentInputsExcept [nosuch], its input_tree line present and no figure; one given NO list, carrying no input_tree --, HEAD moved by an empty commit, the goal with [other] evaluated: the first is declined "; and its input_tree is not a figure (register row 412)", the second "; and it carries no input_tree: (it was not taken under the goal''s instrument_inputs_except) (register row 412)", each after its own "its head is <X>, and HEAD is <Y>"; the stub RUNS, nothing matched' `
    -Ok ($c1apG2NoFig.ok -and ([string]$c1apG2NoFig.header['head'] -ceq $c1apG2Head) -and (@($c1apG2NoFig.headerKeys) -ccontains 'input_tree') -and ($c1apG2NoFigLine -cnotmatch $c1apHex64) -and
         $c1apG2Hand.ok -and ([string]$c1apG2Hand.header['head'] -ceq $c1apG2Head) -and (-not (@($c1apG2Hand.headerKeys) -ccontains 'input_tree')) -and ($c1apRg2.ran -eq 1) -and ($c1apRg2.verdict -ceq 'MET') -and
         $c1apRg2.detail.Contains($c1apG2NoFigName + ': its head is ' + $c1apG2Head + ', and HEAD is ' + $c1apG2New + '; and its input_tree is not a figure (register row 412)') -and
         $c1apRg2.detail.Contains($c1apG2HandName + ': its head is ' + $c1apG2Head + ', and HEAD is ' + $c1apG2New + '; and it carries no input_tree: (it was not taken under the goal''s instrument_inputs_except) (register row 412)') -and
         ($null -ne $c1apRg2.matched) -and (@($c1apRg2.matched).Count -eq 0)) `
    -Said ($c1apRg2.said + '; taken at head ' + $c1apG2Head + ': ' + $c1apG2NoFigName + ' (ok ' + $c1apG2NoFig.ok + ' [' + $c1apG2NoFig.why + '], input_tree [' + $c1apG2NoFigLine + ']) and ' + $c1apG2HandName + ' (ok ' + $c1apG2Hand.ok + ' [' + $c1apG2Hand.why +
           '], an input_tree line: ' + (@($c1apG2Hand.headerKeys) -ccontains 'input_tree') + '); instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRg2.matched) + '; detail: ' + $c1apRg2.detail)

# (g3) THE FIGURE BINDS THE LIST IT WAS TAKEN UNDER (the builder-side review's finding). TWO goals over ONE
#      instrument: G-WNAP-WIDE excludes [other, extra], G-WNAP excludes [other] -- under the NARROWER list
#      extra/ IS an input. extra/ is added by one commit (H1); the WIDE goal is evaluated there, a fresh run,
#      and its capture carries the figure of H1's tree less other and extra. ONE commit more (H2) removes
#      extra/ and nothing else. H2's tree less `other` then holds exactly the entries H1's held less both: a
#      figure taken over the kept entries ALONE is the same number, and the capture -- a reading taken while
#      an input of the NARROW goal stood, at a head where it has since been removed -- would be REUSED for
#      it. The figure says which list it was taken under, so the two differ and the instrument runs.
Clear-WnCaptures -Root $c1apRoot
$c1apWideH1 = Invoke-WnCommit -Root $c1apRoot -Path 'extra/c.txt' -Text "excluded by the wider list only: under the narrower list it IS an input`n" -Message 'extra/ is added'
if (-not $c1apWideH1) { throw 'FIXTURE SLIP: the commit that adds extra/ did not land' }
$c1apWideFirst = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-WIDE'
$c1apWideCap = Read-WnCapture -Path (Join-Path $c1apM.runsDir 'G-WNAP-WIDE.inst.stdout.txt')
$c1apWideFig = [string]$c1apWideCap.header['input_tree']
$c1apWideRm = Invoke-PwGit -Root $c1apRoot -GitArgs @('rm', '-r', '--quiet', '--', 'extra')
$c1apWideH2 = Invoke-WnCommit -Root $c1apRoot -Message 'extra/ is removed, and nothing else'
if (($c1apWideRm.exit -ne 0) -or (-not $c1apWideH2)) { throw ('FIXTURE SLIP: extra/ was not removed by one commit (git rm exit ' + $c1apWideRm.exit + ': ' + ($c1apWideRm.text -replace '\s+', ' ') + ')') }
$c1apWideMoved = ((Invoke-PwGit -Root $c1apRoot -GitArgs @('diff', '--name-status', $c1apWideH1, $c1apWideH2)).text -replace "`r", '').Trim()
$c1apWidePorc = Get-WnPorcelain -Root $c1apRoot
$c1apWideRead = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apWideSaid = [regex]::Match($c1apWideRead.detail, [regex]::Escape('G-WNAP-WIDE.inst.stdout.txt: its head is ' + $c1apWideH1 + ', and HEAD is ' + $c1apWideH2 + '; and its input_tree ') + '([0-9a-f]{64})' + [regex]::Escape(' is not HEAD''s ') + '([0-9a-f]{64})' + [regex]::Escape(' (register row 412)'))
Add-C1apRow -Label '(g3) FALSIFIER THE FIGURE BINDS THE LIST IT WAS TAKEN UNDER: a capture taken under the WIDER list [other, extra] at H1, then ONE commit that removes extra/ and nothing else, then the goal whose list is [other] evaluated at H2 -- the kept entries of the two trees are the same, the lists are not: NOT reused, the stub RUNS, the detail reading "its head is <H1>, and HEAD is <H2>; and its input_tree <a> is not HEAD''s <b> (register row 412)" -- <a> the capture''s own figure, <b> another, the one the key then carries --, nothing matched' `
    -Ok (($c1apWideFirst.ran -eq 1) -and ($c1apWideFirst.verdict -ceq 'MET') -and $c1apWideCap.ok -and ([string]$c1apWideCap.header['head'] -ceq $c1apWideH1) -and ($c1apWideFig -cmatch $c1apHex64) -and
         (Test-C1apOnly -List $c1apWideFirst.except -Item ('inst.ps1: except [other, extra]; input_tree at HEAD ' + $c1apWideFig)) -and ($c1apWideMoved -ceq ("D`textra/c.txt")) -and ($c1apWidePorc -ceq '?? scratch/') -and
         ($c1apWideRead.ran -eq 1) -and ($c1apWideRead.verdict -ceq 'MET') -and (-not $c1apWideRead.detail.Contains('REUSED')) -and $c1apWideSaid.Success -and ($c1apWideSaid.Groups[1].Value -ceq $c1apWideFig) -and ($c1apWideSaid.Groups[2].Value -cne $c1apWideSaid.Groups[1].Value) -and
         (Test-C1apOnly -List $c1apWideRead.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apWideSaid.Groups[2].Value)) -and ($null -ne $c1apWideRead.matched) -and (@($c1apWideRead.matched).Count -eq 0)) `
    -Said ('H1 ' + $c1apWideH1 + ' (extra/ added), the WIDE goal there: ' + $c1apWideFirst.said + ', its capture''s input_tree [' + $c1apWideFig + ']; H2 ' + $c1apWideH2 + ', changed paths H1..H2 [' + ($c1apWideMoved -replace '\s+', ' ') + '], porcelain [' + $c1apWidePorc + ']; the goal with [other] at H2: ' + $c1apWideRead.said +
           '; instrument_inputs_except ' + (Get-C1apShown -List $c1apWideRead.except) + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apWideRead.matched) + '; detail: ' + $c1apWideRead.detail)

# (h) A FAULTY ITEM, OR A LIST THE LIST READER REFUSES, FAILS THE DETECTOR BY NAME (D1 (i)).
foreach ($c1apHx in $c1apFaulty) {
    Clear-WnCaptures -Root $c1apRoot
    $c1apRh = Get-C1apReading -Root $c1apRoot -GoalId $c1apHx.id
    $c1apHOnDisk = Get-C1apOnDisk -Root $c1apRoot
    $c1apHNamed = ((-not $c1apHx.item) -or $c1apRh.detail.Contains('instrument_exit0''s instrument_inputs_except item ''' + $c1apHx.item + ''' is not a repository-relative path this evaluator reads ('))
    # (The five items the builder's sweep added are CONTROLS: the evaluator read them ok when they were written.)
    Add-C1apRow -Label ('(h) ' + $(if ($c1apHx.sweep) { 'CONTROL' } else { 'FALSIFIER' }) + ' A FAULTY LIST FAILS THE DETECTOR, ' + $c1apHx.what + ': the instrument_exit0 entry is ok false, NOT_MET, exit 1, its detail holding "instrument_exit0''s instrument_inputs_except " and "the instrument was NOT run (register row 397)."' + $(if ($c1apHx.item) { ', the item named' } else { '' }) + '; the stub''s counter unmoved; nothing written under instrument-runs' +
                        $(if ($c1apHx.sweep) { '; an item rule narrowed to the characters and the segment kind the rows before this one drove would read this list (the builder''s own mutation sweep after the independent validator''s round 3)' } else { '' })) `
        -Ok ($c1apRh.found -and (-not $c1apRh.ok) -and ($c1apRh.verdict -ceq 'NOT_MET') -and ($c1apRh.exit -eq 1) -and $c1apRh.detail.Contains('instrument_exit0''s instrument_inputs_except ') -and $c1apRh.detail.Contains('the instrument was NOT run (register row 397).') -and $c1apHNamed -and
             ($c1apRh.ran -eq 0) -and ($c1apHOnDisk -eq 0)) `
        -Said ($c1apRh.said + '; entry ok ' + $c1apRh.ok + '; ' + $c1apHOnDisk + ' file(s) under instrument-runs; detail: ' + $c1apRh.detail)
}
# (h2) ... AND IT IS REFUSED BEFORE THE REUSE QUESTION (the independent validator's round 3; it
#      drove this shape itself). Every row of (h) runs over an EMPTY instrument-runs, so none of them tells a
#      list that is held to the item rule first from one that is held to it only when nothing can be reused.
#      Here ONE GREEN capture of the instrument, taken by hand at HEAD by this tree's helper, stands inside
#      the window: the goal WITHOUT the key reuses it (read after, as the proof that it was reusable), and
#      the goal whose list is [../x] must still FAIL by name, nothing reused and nothing run. A CONTROL: the
#      evaluator read it ok when it was written; no wrong cure of ours was driven against it.
Clear-WnCaptures -Root $c1apRoot
$c1apBqHead = Get-WnHead -Root $c1apRoot
$c1apBqCap = New-WnCapture -Tools tree -Root $c1apRoot -Key 'HAND'
$c1apBqBefore = Get-C1apOnDisk -Root $c1apRoot
$c1apRbq = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-H1'
$c1apBqAfter = Get-C1apOnDisk -Root $c1apRoot
$c1apBqReused = Get-WnList -Eval ([pscustomobject]@{ artifactText = $c1apRbq.text }) -Key 'instrument_captures_reused'
$c1apRbqCtl = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-NOKEY'
Add-C1apRow -Label '(h2) CONTROL A FAULTY LIST IS REFUSED BEFORE THE REUSE QUESTION: one GREEN capture of the instrument, taken by hand at HEAD, standing inside the window -- the goal WITHOUT the key, read after, REUSES it --, and the goal whose list is [../x]: the instrument_exit0 entry is ok false, NOT_MET, exit 1, the item named and "the instrument was NOT run (register row 397)."; the stub''s counter unmoved, NOTHING reused -- instrument_captures_reused and instrument_captures_kept name nothing -- and nothing written under instrument-runs; a cure that held the list to its item rule only where no capture can be reused would reuse here (the independent validator''s round 3)' `
    -Ok ($c1apBqCap.ok -and ($c1apBqCap.exit -eq 0) -and ([string]$c1apBqCap.header['head'] -ceq $c1apBqHead) -and ([string]$c1apBqCap.header['tree_clean'] -ceq 'True') -and $c1apRbq.found -and (-not $c1apRbq.ok) -and ($c1apRbq.verdict -ceq 'NOT_MET') -and ($c1apRbq.exit -eq 1) -and
         $c1apRbq.detail.Contains('instrument_exit0''s instrument_inputs_except item ''../x'' is not a repository-relative path this evaluator reads (') -and $c1apRbq.detail.Contains('the instrument was NOT run (register row 397).') -and ($c1apRbq.ran -eq 0) -and
         ($c1apBqBefore -gt 0) -and ($c1apBqAfter -eq $c1apBqBefore) -and (($null -eq $c1apBqReused) -or (@($c1apBqReused).Count -eq 0)) -and (($null -eq $c1apRbq.kept) -or (@($c1apRbq.kept).Count -eq 0)) -and
         ($c1apRbqCtl.ran -eq 0) -and ($c1apRbqCtl.verdict -ceq 'MET') -and $c1apRbqCtl.detail.Contains('REUSED A FRESH READING') -and $c1apRbqCtl.detail.Contains(': capture ' + $c1apBqCap.path + ' sha256 ' + $c1apBqCap.sha256 + ', captured_at ')) `
    -Said ($c1apRbq.said + '; entry ok ' + $c1apRbq.ok + '; under instrument-runs ' + $c1apBqBefore + ' -> ' + $c1apBqAfter + ' file(s); instrument_captures_reused ' + (Get-C1apShown -List $c1apBqReused) + '; instrument_captures_kept ' + (Get-C1apShown -List $c1apRbq.kept) + '; detail: ' + $c1apRbq.detail +
           ' | the goal without the key, after: ' + $c1apRbqCtl.said + '; reused: ' + $c1apRbqCtl.detail.Contains('REUSED A FRESH READING'))

# (i) THE HELPER WITH NO PARAMETER: this tree's Save-LamInstrumentRun writes the base's capture.
Clear-WnCaptures -Root $c1apRoot
$c1apHandT = New-WnCapture -Tools tree -Root $c1apRoot -Key 'HAND'
$c1apHandB = New-WnCapture -Tools base -Root $c1apRoot -Key 'HAND'
Add-C1apRow -Label '(i) CONTROL THE HELPER WITH NO PARAMETER: one hand capture by this tree''s Save-LamInstrumentRun and one by the base''s, neither given -InstrumentInputsExcept, the same fixture, HEAD and run key: each holds the EIGHTEEN keys in order and no other, no input_tree line, and the two texts are equal but for the clock; where the tree''s return object has an input_tree member it is the empty string' `
    -Ok ($wnBase.ok -and $c1apHandT.ok -and $c1apHandB.ok -and ((@($c1apHandT.headerKeys) -join ',') -ceq $c1apBaseKeys) -and ((@($c1apHandB.headerKeys) -join ',') -ceq $c1apBaseKeys) -and (-not [regex]::IsMatch($c1apHandT.text, '(?m)^input_tree:')) -and
         ((Get-WnComparable -Text $c1apHandT.text) -ceq (Get-WnComparable -Text $c1apHandB.text)) -and ((-not $c1apHandT.hasInputTree) -or ([string]$c1apHandT.inputTree -ceq ''))) `
    -Said ('tree: ok ' + $c1apHandT.ok + ' [' + $c1apHandT.why + '], keys: ' + (@($c1apHandT.headerKeys) -join ',') + ' | base: ok ' + $c1apHandB.ok + ' [' + $c1apHandB.why + '] | equal but for the clock: ' + ((Get-WnComparable -Text $c1apHandT.text) -ceq (Get-WnComparable -Text $c1apHandB.text)) +
           '; the tree''s return object has input_tree: ' + $c1apHandT.hasInputTree + ' [' + [string]$c1apHandT.inputTree + ']')

# (j) AN UNTRACKED FILE THAT IS NOT ADMITTED, under a path that is NOT excluded: the tree is not clean.
#     In each fixture a GREEN capture of its HEAD stands inside the window, taken on a clean tree -- here the
#     hand capture (i) left, in the base's fixture the one (d)'s last stop wrote: head equality would reuse it.
$c1apJHead = Get-WnHead -Root $c1apRoot
$c1apJHead2 = Get-WnHead -Root $c1apRoot2
$c1apStray = Join-Path $c1apRoot 'inputs\new.txt'
Write-Utf8 -Path $c1apStray -Text "untracked, not admitted, beside an input`n"
$c1apRj = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
Remove-Item -LiteralPath $c1apStray -Force
$c1apStray2 = Join-Path $c1apRoot2 'inputs\new.txt'
Write-Utf8 -Path $c1apStray2 -Text "untracked, not admitted, beside an input`n"
$c1apRjBase = Get-C1apReading -Tools base -Root $c1apRoot2 -GoalId 'G-WNAP'
Remove-Item -LiteralPath $c1apStray2 -Force
Add-C1apRow -Label '(j) CONTROL an untracked, UNADMITTED file under a path that is not excluded (inputs\new.txt), a GREEN capture of that HEAD standing inside the window -- on this tree''s tools and, in its own fixture, on the base''s: the tree is not clean, NOTHING is reused, the stub RUNS -- "the tree is not clean apart from the mission''s declared set" --; the file removed, porcelain reads "?? scratch/" again' `
    -Ok ($wnBase.ok -and $c1apHandB.ok -and ([string]$c1apHandB.header['head'] -ceq $c1apJHead) -and ([string]$c1apHandB.header['tree_clean'] -ceq 'True') -and ($c1apRj.ran -eq 1) -and ($c1apRj.verdict -ceq 'MET') -and (-not $c1apRj.detail.Contains('REUSED')) -and
         $c1apRj.detail.Contains('the tree is not clean apart from the mission''s declared set') -and ((Get-WnPorcelain -Root $c1apRoot) -ceq '?? scratch/') -and
         $c1apD3bCap.ok -and ([string]$c1apD3bCap.header['head'] -ceq $c1apJHead2) -and ([string]$c1apD3bCap.header['tree_clean'] -ceq 'True') -and ($c1apRjBase.ran -eq 1) -and ($c1apRjBase.verdict -ceq 'MET') -and (-not $c1apRjBase.detail.Contains('REUSED')) -and
         $c1apRjBase.detail.Contains('the tree is not clean apart from the mission''s declared set') -and ((Get-WnPorcelain -Root $c1apRoot2) -ceq '?? scratch/')) `
    -Said ($c1apRj.said + '; detail: ' + $c1apRj.detail + ' | ' + $c1apRjBase.said + '; detail: ' + $c1apRjBase.detail)

# (k) THE SECOND CALL CARRIES THE EXIT: the launch that passes the parameter hands back the instrument's code.
Clear-WnCaptures -Root $c1apRoot
Set-WnStubFlag -Root $c1apRoot -Exit 3
$c1apRk = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
Set-WnStubFlag -Root $c1apRoot
$c1apCapK = Read-WnCapture -Path $c1apLive
Clear-WnCaptures -Root $c1apRoot
Add-C1apRow -Label '(k) FALSIFIER THE SECOND CALL CARRIES THE EXIT: the goal with the key, the stub flagged to exit 3, nothing on disk: the stub runs, NOT_MET, exit 1, the detail opening "inst.ps1 exited 3 (require 0). Instrument output ", and the capture''s header holds exit_code: 3 AND, its last key, input_tree: <64 hex> -- the launch went through the call that passes the parameter' `
    -Ok (($c1apRk.ran -eq 1) -and ($c1apRk.verdict -ceq 'NOT_MET') -and ($c1apRk.exit -eq 1) -and $c1apRk.found -and (-not $c1apRk.ok) -and $c1apRk.detail.StartsWith('inst.ps1 exited 3 (require 0). Instrument output ') -and $c1apCapK.ok -and
         ([string]$c1apCapK.header['exit_code'] -ceq '3') -and ([string]$c1apCapK.header['input_tree'] -cmatch $c1apHex64) -and ((@($c1apCapK.headerKeys) -join ',') -ceq ($c1apBaseKeys + ',input_tree'))) `
    -Said ($c1apRk.said + '; the capture''s exit_code [' + [string]$c1apCapK.header['exit_code'] + '], input_tree [' + [string]$c1apCapK.header['input_tree'] + '], header keys: ' + (@($c1apCapK.headerKeys) -join ',') + '; detail: ' + $c1apRk.detail)

# (l) A CAPTURE WHOSE head: IS NOT A COMMIT ID, its input_tree HEAD's: the figure does not admit it.
$c1apLHead = Get-WnHead -Root $c1apRoot
$c1apRl0 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apCapL = Read-WnCapture -Path $c1apLive
$c1apLFig = [string]$c1apCapL.header['input_tree']
if ($c1apCapL.ok) { [System.IO.File]::WriteAllText($c1apLive, ([regex]'(?m)^head: .*$').Replace($c1apCapL.text, 'head: not-a-sha', 1), (New-Object System.Text.UTF8Encoding($false))) }
$c1apRl = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
Add-C1apRow -Label '(l) FALSIFIER a capture just taken at HEAD -- its input_tree HEAD''s own figure -- whose `head:` line is then rewritten to `not-a-sha`: DECLINED, the stub runs, the detail reading "its head is not-a-sha, and HEAD is <Y>; and its head is not a 40-hex commit id, so its input tree cannot admit it (register row 412)"' `
    -Ok (($c1apRl0.ran -eq 1) -and $c1apCapL.ok -and ([string]$c1apCapL.header['head'] -ceq $c1apLHead) -and ($c1apLFig -cmatch $c1apHex64) -and (Test-C1apOnly -List $c1apRl0.except -Item ('inst.ps1: except [other]; input_tree at HEAD ' + $c1apLFig)) -and ($c1apRl.ran -eq 1) -and ($c1apRl.verdict -ceq 'MET') -and
         $c1apRl.detail.Contains('its head is not-a-sha, and HEAD is ' + $c1apLHead + '; and its head is not a 40-hex commit id, so its input tree cannot admit it (register row 412)')) `
    -Said ($c1apRl.said + '; the capture as taken: head ' + [string]$c1apCapL.header['head'] + ', input_tree [' + $c1apLFig + ']; detail: ' + $c1apRl.detail)

# (m) THE FILES THAT DEFINE "CLEAN" ARE IN THE FIGURE. The capture (l)'s run just wrote stands at HEAD.
#     (Where it does not -- a cure that reused the rewritten capture in (l) -- this row takes one first, and
#     says so: it reads RED for its own reason or not at all.)
$c1apCapM0 = Read-WnCapture -Path $c1apLive
$c1apMOwn = $false
if ((-not $c1apCapM0.ok) -or ([string]$c1apCapM0.header['head'] -cne $c1apLHead)) {
    $c1apMOwn = $true
    Clear-WnCaptures -Root $c1apRoot
    $null = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
    $c1apCapM0 = Read-WnCapture -Path $c1apLive
}
$c1apM0Fig = [string]$c1apCapM0.header['input_tree']
$c1apMNew = Invoke-WnCommit -Root $c1apRoot -Path '.mission/mission.yaml' -Text "id: wn-fixture`nadmitted_porcelain: [`"?? scratch/`", `"?? scratch2/`"]`n" -Message 'mission.yaml admits one prefix more'
if (-not $c1apMNew) { throw 'FIXTURE SLIP: the commit to mission.yaml did not land' }
$c1apMPorc = Get-WnPorcelain -Root $c1apRoot
$c1apRm = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apMm = [regex]::Match($c1apRm.detail, [regex]::Escape('its head is ' + $c1apLHead + ', and HEAD is ' + $c1apMNew + '; and its input_tree ') + '([0-9a-f]{64})' + [regex]::Escape(' is not HEAD''s ') + '([0-9a-f]{64})' + [regex]::Escape(' (register row 412)'))
Add-C1apRow -Label '(m) FALSIFIER THE FILES THAT DEFINE "CLEAN" ARE IN THE FIGURE: after a fresh run, ONE commit that only adds an admitted prefix to .mission\mission.yaml (the tree still clean): the stub RUNS, the detail reading "and its input_tree <the capture''s> is not HEAD''s <another> (register row 412)"' `
    -Ok (($c1apMPorc -ceq '?? scratch/') -and ([string]$c1apCapM0.header['head'] -ceq $c1apLHead) -and ($c1apRm.ran -eq 1) -and ($c1apRm.verdict -ceq 'MET') -and $c1apMm.Success -and ($c1apMm.Groups[1].Value -ceq $c1apM0Fig) -and ($c1apMm.Groups[2].Value -cne $c1apMm.Groups[1].Value)) `
    -Said ($c1apRm.said + '; porcelain [' + $c1apMPorc + ']; the capture stood at head ' + [string]$c1apCapM0.header['head'] + ' with input_tree [' + $c1apM0Fig + ']' + $(if ($c1apMOwn) { ' (TAKEN FOR THIS ROW: (l) left none of its HEAD)' } else { '' }) + '; detail: ' + $c1apRm.detail)
Clear-WnCaptures -Root $c1apRoot
$c1apRm2 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-M'
$c1apMItem = Get-C1apFirst -List $c1apRm2.except
Add-C1apRow -Label '(m) FALSIFIER ... and `instrument_inputs_except: [.mission]` is NOT DERIVABLE: the key''s one item reads `inst.ps1: except [.mission]; input_tree at HEAD not derivable (` and says why -- "the exclusion ''.mission'' would take ''.mission/mission.yaml'' out of the figure"' `
    -Ok ($c1apMItem.StartsWith('inst.ps1: except [.mission]; input_tree at HEAD not derivable (') -and $c1apMItem.Contains('the exclusion ''.mission'' would take ''.mission/mission.yaml'' out of the figure')) `
    -Said ($c1apRm2.said + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRm2.except))
# (m3) ... IN ANY CASE (the builder-side review's finding). On a file system that folds case git reads its
#      ignore rules from a file TRACKED as `.GitIgnore`, and an exclusion spelled that way matches the head's
#      entry exactly: held to the three names case-sensitively, the guard lets the list take the ignore file
#      OUT of the figure. The head's ignore file is renamed by one commit (git mv), the goal whose list is
#      [.GitIgnore] is evaluated, and the file is renamed back by another, so the rows below stand on the
#      fixture they stood on. (Where the rename cannot be made the row reads MISMATCH and says what the head
#      tracks: it is never passed over.)
$c1apCaseMv = Invoke-PwGit -Root $c1apRoot -GitArgs @('mv', '--', '.gitignore', '.GitIgnore')
$c1apCaseHead = ''
if ($c1apCaseMv.exit -eq 0) { $c1apCaseHead = Invoke-WnCommit -Root $c1apRoot -Message 'the ignore file is tracked as .GitIgnore' }
$c1apCaseTracked = @(((Invoke-PwGit -Root $c1apRoot -GitArgs @('ls-tree', '--name-only', 'HEAD')).text -replace "`r", '') -split "`n" | Where-Object { $_ })
$c1apCaseRenamed = ([bool]$c1apCaseHead -and ($c1apCaseTracked -ccontains '.GitIgnore') -and (-not ($c1apCaseTracked -ccontains '.gitignore')))
$c1apCasePorc = Get-WnPorcelain -Root $c1apRoot
Clear-WnCaptures -Root $c1apRoot
$c1apCaseRead = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-CASE'
$c1apCaseItem = Get-C1apFirst -List $c1apCaseRead.except
Add-C1apRow -Label '(m3) FALSIFIER ... IN ANY CASE: the head''s ignore file renamed to `.GitIgnore` by one commit (git mv; the tree still clean), and `instrument_inputs_except: [.GitIgnore]`: NOT DERIVABLE -- the key''s one item reads `inst.ps1: except [.GitIgnore]; input_tree at HEAD not derivable (` and says "the exclusion ''.GitIgnore'' would take ''.gitignore'' out of the figure": a list does not take the ignore file out of the figure by spelling it in another case' `
    -Ok ($c1apCaseRenamed -and ($c1apCasePorc -ceq '?? scratch/') -and ($c1apCaseRead.ran -eq 1) -and ($c1apCaseRead.verdict -ceq 'MET') -and $c1apCaseItem.StartsWith('inst.ps1: except [.GitIgnore]; input_tree at HEAD not derivable (') -and
         $c1apCaseItem.Contains('the exclusion ''.GitIgnore'' would take ''.gitignore'' out of the figure')) `
    -Said ('git mv exit ' + $c1apCaseMv.exit + $(if ($c1apCaseMv.exit -ne 0) { ' [' + ($c1apCaseMv.text -replace '\s+', ' ') + ']' } else { '' }) + '; HEAD ' + $c1apCaseHead + ' tracks at its root [' + ($c1apCaseTracked -join ', ') + ']; porcelain [' + $c1apCasePorc + ']; ' + $c1apCaseRead.said +
           '; instrument_inputs_except ' + (Get-C1apShown -List $c1apCaseRead.except))
if ($c1apCaseRenamed) {
    $c1apCaseBack = Invoke-PwGit -Root $c1apRoot -GitArgs @('mv', '--', '.GitIgnore', '.gitignore')
    $c1apCaseBackHead = if ($c1apCaseBack.exit -eq 0) { Invoke-WnCommit -Root $c1apRoot -Message 'the ignore file is tracked as .gitignore again' } else { '' }
    if ((-not $c1apCaseBackHead) -or ((Get-WnPorcelain -Root $c1apRoot) -cne '?? scratch/')) { throw 'FIXTURE SLIP: the ignore file was not renamed back to .gitignore by one commit' }
} elseif ($c1apCaseMv.exit -eq 0) { throw 'FIXTURE SLIP: git mv ran, and the head does not track the ignore file as .GitIgnore alone -- the fixture is not what the rows below stand on' }

# (n) STATED, NOT CLAIMED: an ADMITTED untracked file, written between the capture and the evaluation, does
#     not stop a reuse by inputs -- the figure is of the head's tree, and the tree is clean apart from it.
Clear-WnCaptures -Root $c1apRoot
$c1apNHead = Get-WnHead -Root $c1apRoot
$c1apRn0 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apCapN = Read-WnCapture -Path $c1apLive
$c1apNFig = [string]$c1apCapN.header['input_tree']
$c1apAdmitted = Join-Path $c1apRoot 'scratch\x.txt'
Write-Utf8 -Path $c1apAdmitted -Text "untracked, under the one admitted prefix`n"
$c1apNNew = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.otherRel -Text "not an input of the instrument, and changed a third time`n" -Message 'other/ alone changes, an admitted file standing'
if (-not $c1apNNew) { throw 'FIXTURE SLIP: the third commit under other/ did not land' }
$c1apNPorc = Get-WnPorcelain -Root $c1apRoot
$c1apRn = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
Remove-Item -LiteralPath $c1apAdmitted -Force
Add-C1apRow -Label '(n) STATED, NOT CLAIMED: (RED at this tree until the cure, as (b) is) an ADMITTED untracked file (scratch\x.txt) written between the capture and the evaluation, HEAD moved by a commit under other/ alone: it does NOT stop a reuse by inputs -- the stub not run, MET, "REUSED A FRESH READING, " and "ADMITTED BY ITS INPUT TREE", the capture''s head and figure named' `
    -Ok (($c1apRn0.ran -eq 1) -and ($c1apNFig -cmatch $c1apHex64) -and ($c1apNPorc -ceq '?? scratch/') -and ($c1apRn.ran -eq 0) -and ($c1apRn.verdict -ceq 'MET') -and $c1apRn.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and
         $c1apRn.detail.Contains(', HEAD ' + $c1apNNew + ' (the capture''s head is ' + $c1apNHead + '; ADMITTED BY ITS INPUT TREE: input_tree ' + $c1apNFig + ' over the head''s tree less the goal''s 1 instrument_inputs_except path(s) equals HEAD''s -- register row 412)')) `
    -Said ($c1apRn.said + '; porcelain [' + $c1apNPorc + ']; detail: ' + $c1apRn.detail)

# (o) STATED, NOT CLAIMED (D14: no history condition): a change and its revert, both committed, nothing
#     evaluated between -- the two ends have one figure, and the capture of the first is reused at the second.
Clear-WnCaptures -Root $c1apRoot
$c1apOHead = Get-WnHead -Root $c1apRoot
$c1apOText = [System.IO.File]::ReadAllText($c1apM.inputsFile)
$c1apRo0 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
$c1apCapO = Read-WnCapture -Path $c1apLive
$c1apOFig = [string]$c1apCapO.header['input_tree']
$c1apOMid = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.inputsRel -Text ($c1apOText + "and one line more`n") -Message 'inputs/ changes'
$c1apOEnd = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.inputsRel -Text $c1apOText -Message 'inputs/ is put back'
if ((-not $c1apOMid) -or (-not $c1apOEnd)) { throw 'FIXTURE SLIP: the change under inputs/ or its revert did not land' }
$c1apOwnO = Get-C1apOwnFigure -Root $c1apRoot -Head $c1apOHead -Except @('other')
$c1apOwnOMid = Get-C1apOwnFigure -Root $c1apRoot -Head $c1apOMid -Except @('other')
$c1apOwnOEnd = Get-C1apOwnFigure -Root $c1apRoot -Head $c1apOEnd -Except @('other')
$c1apRo = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP'
Add-C1apRow -Label '(o) STATED, NOT CLAIMED: (ruling D14: no history condition; RED at this tree until the cure, as (b) is) a change to inputs/a.txt and its revert, BOTH committed, no evaluation between: the two ends have one figure (the one between them another, derived here), and the capture of the first end is REUSED at the second by inputs -- the stub not run, the match listed with both heads' `
    -Ok (($c1apRo0.ran -eq 1) -and ($c1apOFig -cmatch $c1apHex64) -and ($c1apOwnO -cmatch $c1apHex64) -and ($c1apOwnOEnd -ceq $c1apOwnO) -and ($c1apOwnOMid -cne $c1apOwnO) -and ($c1apRo.ran -eq 0) -and ($c1apRo.verdict -ceq 'MET') -and
         $c1apRo.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and
         $c1apRo.detail.Contains(', HEAD ' + $c1apOEnd + ' (the capture''s head is ' + $c1apOHead + '; ADMITTED BY ITS INPUT TREE: input_tree ' + $c1apOFig + ' over the head''s tree less the goal''s 1 instrument_inputs_except path(s) equals HEAD''s -- register row 412)') -and
         (Test-C1apOnly -List $c1apRo.matched -Item ($c1apLive + ' input_tree ' + $c1apOFig + ' capture_head ' + $c1apOHead + ' head ' + $c1apOEnd))) `
    -Said ($c1apRo.said + '; derived here: first end [' + $c1apOwnO + '], between [' + $c1apOwnOMid + '], second end [' + $c1apOwnOEnd + ']; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRo.matched) + '; detail: ' + $c1apRo.detail)

# (p) A NESTED EXCLUSION TAKES OUT ITS ONE PATH, NOT ITS DIRECTORY (the builder's own mutation sweep after the
#     independent validator's round 3). Of the lists a figure is DERIVED under above, every one names
#     entries of the head's ROOT tree but one, [other, inputs/a.txt] -- and (g) reads that one only as
#     "another list". For an item with a separator the helper OPENS the directory, drops the one path and
#     keeps the directory's other entries one by one. A figure that dropped the opened directory WHOLE read
#     every row ok, and under it a change to a SIBLING of the excluded path -- an input -- moves nothing.
#     LAST, because it leaves a second file under inputs/. One commit adds inputs/c.txt beside inputs/a.txt; the goal whose list is
#     [other, inputs/a.txt] is evaluated there, a fresh run; then ONE commit to inputs/a.txt alone -- the
#     excluded path: REUSED by inputs --; then ONE commit to inputs/c.txt alone -- its sibling: NOT reused,
#     the stub RUNS. Two CONTROLS: the evaluator read them ok when they were written, and no RED of record
#     over a wrong cure of ours stands behind them -- the sweep's one-line mutant of the helper does.
Clear-WnCaptures -Root $c1apRoot
$c1apPLive = Join-Path $c1apM.runsDir 'G-WNAP-G.inst.stdout.txt'
$c1apPH0 = Invoke-WnCommit -Root $c1apRoot -Path 'inputs/c.txt' -Text "a second input of the instrument, beside the excluded one`n" -Message 'inputs/c.txt is added beside inputs/a.txt'
if (-not $c1apPH0) { throw 'FIXTURE SLIP: the commit that adds inputs/c.txt did not land' }
$c1apPUnder = @(((Invoke-PwGit -Root $c1apRoot -GitArgs @('ls-tree', '--name-only', ($c1apPH0 + ':inputs'))).text -replace "`r", '') -split "`n" | Where-Object { $_ })
$c1apRp0 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-G'
$c1apCapP = Read-WnCapture -Path $c1apPLive
$c1apPFig = [string]$c1apCapP.header['input_tree']
$c1apPH1 = Invoke-WnCommit -Root $c1apRoot -Path $c1apM.inputsRel -Text "an input of the instrument that this goal's list excludes, and changed`n" -Message 'inputs/a.txt alone changes'
if (-not $c1apPH1) { throw 'FIXTURE SLIP: the commit to inputs/a.txt alone did not land' }
$c1apPMoved1 = ((Invoke-PwGit -Root $c1apRoot -GitArgs @('diff', '--name-status', $c1apPH0, $c1apPH1)).text -replace "`r", '').Trim()
$c1apRp1 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-G'
Add-C1apRow -Label '(p) CONTROL A NESTED EXCLUSION TAKES OUT ITS ONE PATH: inputs/ holding a.txt and c.txt, the goal whose list is [other, inputs/a.txt] evaluated (a fresh run), then ONE commit to inputs/a.txt alone -- the excluded path: REUSED by inputs -- the stub not run, MET, "REUSED A FRESH READING, " and "ADMITTED BY ITS INPUT TREE", the capture''s head and figure named, the match listed with both heads (the exclusion form of ruling D2, for an item with a separator; the control of the row under it)' `
    -Ok ((($c1apPUnder -join ',') -ceq 'a.txt,c.txt') -and ($c1apRp0.ran -eq 1) -and ($c1apRp0.verdict -ceq 'MET') -and $c1apCapP.ok -and ([string]$c1apCapP.header['head'] -ceq $c1apPH0) -and ($c1apPFig -cmatch $c1apHex64) -and
         (Test-C1apOnly -List $c1apRp0.except -Item ('inst.ps1: except [other, inputs/a.txt]; input_tree at HEAD ' + $c1apPFig)) -and ($c1apPMoved1 -ceq ("M`tinputs/a.txt")) -and ($c1apRp1.ran -eq 0) -and ($c1apRp1.verdict -ceq 'MET') -and
         $c1apRp1.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and
         $c1apRp1.detail.Contains(', HEAD ' + $c1apPH1 + ' (the capture''s head is ' + $c1apPH0 + '; ADMITTED BY ITS INPUT TREE: input_tree ' + $c1apPFig + ' over the head''s tree less the goal''s 2 instrument_inputs_except path(s) equals HEAD''s -- register row 412)') -and
         (Test-C1apOnly -List $c1apRp1.matched -Item ($c1apPLive + ' input_tree ' + $c1apPFig + ' capture_head ' + $c1apPH0 + ' head ' + $c1apPH1))) `
    -Said ('H0 ' + $c1apPH0 + ', inputs/ holds [' + ($c1apPUnder -join ', ') + ']; the goal there: ' + $c1apRp0.said + ', its capture''s input_tree [' + $c1apPFig + ']; H1 ' + $c1apPH1 + ', changed paths H0..H1 [' + ($c1apPMoved1 -replace '\s+', ' ') + ']; the goal at H1: ' + $c1apRp1.said +
           '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRp1.matched) + '; detail: ' + $c1apRp1.detail)
$c1apPH2 = Invoke-WnCommit -Root $c1apRoot -Path 'inputs/c.txt' -Text "a second input of the instrument, beside the excluded one, and changed`n" -Message 'inputs/c.txt alone changes'
if (-not $c1apPH2) { throw 'FIXTURE SLIP: the commit to inputs/c.txt alone did not land' }
$c1apPMoved2 = ((Invoke-PwGit -Root $c1apRoot -GitArgs @('diff', '--name-status', $c1apPH1, $c1apPH2)).text -replace "`r", '').Trim()
$c1apRp2 = Get-C1apReading -Root $c1apRoot -GoalId 'G-WNAP-G'
$c1apPSaid = [regex]::Match($c1apRp2.detail, [regex]::Escape('G-WNAP-G.inst.stdout.txt: its head is ' + $c1apPH0 + ', and HEAD is ' + $c1apPH2 + '; and its input_tree ') + '([0-9a-f]{64})' + [regex]::Escape(' is not HEAD''s ') + '([0-9a-f]{64})' + [regex]::Escape(' (register row 412)'))
Add-C1apRow -Label '(p) CONTROL ... AND NOT ITS DIRECTORY: then ONE commit to inputs/c.txt alone -- the SIBLING of the excluded path, an input of the goal: NOT reused, the stub RUNS, the detail reading "its head is <H0>, and HEAD is <H2>; and its input_tree <the capture''s> is not HEAD''s <another> (register row 412)", the key carrying HEAD''s figure, nothing matched; a figure that dropped the directory it opened for the nested exclusion WHOLE would reuse the capture (the builder''s own mutation sweep after the independent validator''s round 3)' `
    -Ok (($c1apPMoved2 -ceq ("M`tinputs/c.txt")) -and ($c1apRp2.ran -eq 1) -and ($c1apRp2.verdict -ceq 'MET') -and (-not $c1apRp2.detail.Contains('REUSED')) -and $c1apPSaid.Success -and ($c1apPSaid.Groups[1].Value -ceq $c1apPFig) -and ($c1apPSaid.Groups[2].Value -cne $c1apPSaid.Groups[1].Value) -and
         (Test-C1apOnly -List $c1apRp2.except -Item ('inst.ps1: except [other, inputs/a.txt]; input_tree at HEAD ' + $c1apPSaid.Groups[2].Value)) -and ($null -ne $c1apRp2.matched) -and (@($c1apRp2.matched).Count -eq 0)) `
    -Said ('H2 ' + $c1apPH2 + ', changed paths H1..H2 [' + ($c1apPMoved2 -replace '\s+', ' ') + ']; the goal at H2: ' + $c1apRp2.said + '; instrument_inputs_except ' + (Get-C1apShown -List $c1apRp2.except) + '; instrument_input_tree_matched ' + (Get-C1apShown -List $c1apRp2.matched) + '; detail: ' + $c1apRp2.detail)
}
catch {
    $c1apOk = $false
    $c1apRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1apRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1apM2) { Remove-PwTreeAsWritten -Base $c1apM2.base }
if ($null -ne $c1apM) { Remove-PwTreeAsWritten -Base $c1apM.base }
Check -Id 'C-1ap' -Title 'THE INPUT TREE A CAPTURE STOOD ON (the first member; the operator''s rulings D1 (i), D2, D3 and D14 of 2026-10-11): the base stores instrument_inputs_except and reads it nowhere -- its capture holds eighteen header keys and no input_tree, and after a commit that touches only the excluded path it declines the capture by its head alone and runs the instrument again; at this tree a fresh run under `instrument_inputs_except: [other]` writes a capture whose nineteenth and last header key is input_tree, 64 hex, and the artifact carries instrument_inputs_except (the list and the figure at HEAD) and instrument_input_tree_matched; after a commit under other/ alone that capture is REUSED -- the stub not run -- the detail naming the capture''s own head and ADMITTED BY ITS INPUT TREE, the match listed with both heads, the cited bytes kept; one byte moved under inputs/ and committed, the instrument runs and the detail names the two figures; the head condition is WIDENED and not branched -- a capture the figure admits whose instrument has since changed its bytes is still declined by its instrument_sha256, and run, and so is one taken while a tracked input held uncommitted bytes (declined for its tree_clean: False) and one forty minutes old under a window of 30 (declined for its age) -- the independent validator''s round 3 --, and so is one for each other condition of the chain (no instrument_resolved, another file''s, ran: False, an exit_code that is no number, a captured_at that does not parse, is not UTC, is in the future), and a RED capture the figure admits is re-measured by the RED rule (eight rows from the builder''s own mutation sweep after that round); a NESTED exclusion takes out its one path and not the directory opened for it -- under [other, inputs/a.txt] a commit to inputs/a.txt alone is reused over, and a commit to its sibling inputs/c.txt alone is not (two rows from the same sweep); a goal WITHOUT the key writes, at three stops (fresh, reused at HEAD, declined after an empty commit), the artifact and the capture the base writes in a twin fixture, but for the clock, the fixtures'' own paths and ids and the kept-copies listing; Get-LamInputTree gives one figure for one head whatever line endings the checkout has, the figure the capture carries and the one the rule words; an exclusion the head does not hold -- absent, on disk and untracked, a case variant -- is not derivable, says so in the key, and reuses nothing by inputs; a list changed since the capture, a capture that carries no input_tree, one whose input_tree is not a figure, one whose head is not a commit id, and a commit to mission.yaml each decline in their own words; THE FIGURE BINDS THE LIST IT WAS TAKEN UNDER (the builder-side review''s finding) -- a capture taken under a WIDER list is not reused under a narrower one once a commit has removed the path the narrower list did not exclude, though the two trees keep the same entries; an exclusion that would take a file that defines "clean" out of the figure is not derivable, in whatever case the list spells it (a review finding: `.GitIgnore`, the head tracking the ignore file under that name); a faulty item, an empty list and a block list each FAIL the detector by name, the instrument not run and nothing written -- each of the six characters the item rule names ([ ] \ : * ?) and each of its three segment kinds (empty, ., ..) driven by an item of its own (the builder''s own mutation sweep after the independent validator''s round 3) -- and a faulty item does so BEFORE the reuse question, a reusable capture standing inside the window (the independent validator''s round 3); the helper without the parameter writes the base''s eighteen keys; an untracked file that is not admitted still stops every reuse; the launch that passes the parameter carries the instrument''s exit code; and, STATED and not claimed, an admitted untracked file does not stop a reuse by inputs, and a change reverted between two commits is reused, the figure being of the two ends (no history condition)' `
      -Ok $c1apOk -Detail ("      THE $(@($c1apRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1apRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument every goal here names:`n" + (Get-WlIndented -Text $wnStubText))

# =============================================================================================
# C-1aq -- A RED IS NEVER REUSED AND NEVER STEPPED OVER (the second member): a reading
#          that is not exit 0 is re-measured, and so is an older GREEN one that a later RED follows
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: of the captures that pass,
# the base reuses the one with the latest captured_at, RED OR GREEN (C-1ai (i) and (q)) --
# one RED reading inside the window is handed back as RED, the instrument not run, for as long as the window
# lasts, and a content-addressed copy of it is kept; and a capture the base declines --
# for its head, say -- is never read for its exit code at all.
# THE RULE (the operator's ruling 5 of 2026-10-11), applied after the newest capture that passes is chosen
# and BEFORE anything is kept: (1) the chosen capture did not exit 0 -> nothing is reused, nothing is kept,
# the instrument RUNS, and the detail names the capture and says a reading that is not exit 0 is never
# reused; (2) a WHOLE capture of the same instrument, taken AFTER the chosen one, did not exit 0 -- whatever
# its head, its input tree, its tree_clean -> the same, and the detail says a RED is never stepped over.
# Row (c) is where (2) meets the input tree of the first member (C-1ap): a GREEN capture
# admitted at a moved HEAD by its input_tree, and a later RED that carries none and is declined for its
# head -- and still stops the reuse.
# THE CONTROLS, each a row: the base, kept, beside every falsifier (it reuses the RED as RED and keeps a copy
# of it; at the moved HEAD it runs the instrument for the head and names no RED rule); a GREEN capture alone
# is REUSED by both tools, the two entries equal but for the clock; and a newer GREEN after an OLDER RED is
# reused at this tree as it always was -- a RED before the capture that passes is not one stepped over.
# STATED, NOT CLAIMED (the independent validator's round 1; row (g)): the rule's (2) remembers a
# later RED only where that capture is WHOLE -- it reads, it names this instrument's own file, ran: True, a
# numeric exit_code, and a captured_at that parses, is UTC and is not in the future. A newer RED capture
# whose captured_at line does not parse is not whole: the RED rule does not remember it. RE-ASSERTED BY
# BATCH-6 WP-Q (ruled 2026-10-16 07:2x local, lean accepted): such a capture is UNDATABLE,
# and an undatable capture of the instrument among the candidates refuses the reuse -- the older GREEN behind
# it is NOT reused and the stub runs (C-1ay drives the rule; this row now reads it). It read REUSED until then.
# WHATEVER THE CHAIN DECLINES IT FOR (the builder's own mutation sweep after the independent validator's
# round 3; rows (h)): a later WHOLE RED is remembered though the chain declines it for its tree_clean or for
# its instrument_sha256, as row (c) holds for its head. Two CONTROL rows; no RED of record over a wrong cure
# of ours stands behind them -- the sweep's two one-line mutants of the rule's second half are what they hold.
# HOW IT IS DRIVEN: the stub turns RED by a flag file, its bytes untouched, so a GREEN and a RED capture of
# ONE instrument stand side by side. Every capture here is a hand capture under a run key of its own (RED,
# GREEN), taken in a child by the helper of the tools the row drives, and the stub is GREEN again before
# every evaluation -- so a re-measurement reads exit 0 where the capture read 3, and "the instrument ran" is
# read off the stub's own counter, never off the evaluator's word. Each sequence starts from an empty
# instrument-runs (Clear-WnCaptures): the base's and the tree's never see each other's captures.
$c1aqOk = $true
$c1aqRows = New-Object System.Collections.Generic.List[string]
function Add-C1aqRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1aqOk = $false }
    $script:c1aqRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1aqRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1aqReading {
    # One hand evaluation of G-WNAQ at -Root by -Tools (tree|base): how many times the stub RAN during it (its
    # own counter's delta), the instrument_exit0 entry, and the two reuse keys -- each $null where the key is
    # not written, an empty array where it is written `[]`.
    param([string]$Tools, [string]$Root)
    $c1aqRdBefore = Get-WnRuns -Root $Root
    $c1aqRdEval = Invoke-WnEval -Tools $Tools -Root $Root -GoalId 'G-WNAQ'
    $c1aqRdEntry = Get-WnInst -Eval $c1aqRdEval
    return [pscustomobject]@{ exit = $c1aqRdEval.exit; verdict = $c1aqRdEval.verdict; ran = ((Get-WnRuns -Root $Root) - $c1aqRdBefore); found = $c1aqRdEntry.found; ok = $c1aqRdEntry.ok; detail = [string]$c1aqRdEntry.detail
                              reused = (Get-WnList -Eval $c1aqRdEval -Key 'instrument_captures_reused'); kept = (Get-WnList -Eval $c1aqRdEval -Key 'instrument_captures_kept') }
}
function Get-C1aqSha8 {
    # The first eight hex of a hand capture's sha256; 'xxxxxxxx' where the capture was not taken.
    param($Capture)
    if ([string]$Capture.sha256 -cmatch '\A[0-9a-f]{64}\z') { return ([string]$Capture.sha256).Substring(0, 8) }
    return 'xxxxxxxx'
}
function Get-C1aqKeptPath {
    # The name a reuse keeps a hand capture under: the live name, the first eight hex of the
    # capture's sha256 before its tail. '' where the capture was not taken.
    param($Capture)
    $c1aqKpLive = [string]$Capture.path
    if ((-not $Capture.ok) -or ([string]$Capture.sha256 -cnotmatch '\A[0-9a-f]{64}\z') -or (-not $c1aqKpLive.EndsWith('.stdout.txt'))) { return '' }
    return ($c1aqKpLive.Substring(0, $c1aqKpLive.Length - '.stdout.txt'.Length) + '.' + (Get-C1aqSha8 -Capture $Capture) + '.stdout.txt')
}
function Get-C1aqKeptNames {
    # Every name under a fixture's instrument-runs that is a kept copy's of this stub -- <key>.inst.<eight
    # hex>.stdout.txt, a file or a directory alike -- sorted; none where the directory does not stand.
    param([string]$RunsDir)
    if (-not (Test-Path -LiteralPath $RunsDir -PathType Container)) { return @() }
    return @(Get-ChildItem -LiteralPath $RunsDir -Force | Where-Object { $_.Name -cmatch '\A.+\.inst\.[0-9a-f]{8}\.stdout\.txt\z' } | ForEach-Object { $_.Name } | Sort-Object)
}
function Get-C1aqFileSha {
    # The sha256 of a file's bytes, or '(absent)' where no file stands at -Path (or no path was given).
    param([string]$Path)
    if ((-not $Path) -or (-not (Test-Path -LiteralPath $Path -PathType Leaf))) { return '(absent)' }
    return (Get-PwRawSha -Path $Path)
}
function Get-C1aqCaptureSaid {
    # One hand capture in one line, for a row's -Said: its file name, exit code, head, tree_clean, input_tree
    # and sha256 -- or that it was NOT TAKEN, and the helper's own reason.
    param($Capture)
    if (-not $Capture.ok) { return ('NOT TAKEN -- ' + [string]$Capture.why) }
    return ([System.IO.Path]::GetFileName([string]$Capture.path) + ' exit_code ' + [string]$Capture.header['exit_code'] + ', head ' + [string]$Capture.header['head'] + ', tree_clean ' + [string]$Capture.header['tree_clean'] +
            $(if ($Capture.header.ContainsKey('input_tree')) { ', input_tree ' + [string]$Capture.header['input_tree'] } else { ', no input_tree' }) + ', sha256 ' + [string]$Capture.sha256)
}
function Test-C1aqNamed {
    # Does -Detail hold -Lead and then, AT ONCE, the capture's file name -Name with -Tail right after it? The
    # ruling's two sentences name a capture by "<file name>": the bare LEAF name, as the sentence beside them
    # prints it (the "could not be kept" sentence). Case is held; nothing may stand between the lead and
    # the name -- a full path there is a MISMATCH.
    param([string]$Detail, [string]$Lead, [string]$Name, [string]$Tail)
    if ((-not $Detail) -or (-not $Lead) -or (-not $Name)) { return $false }
    return $Detail.Contains($Lead + $Name + $Tail)
}
function Get-C1aqListSaid {
    # A verdict list key as Get-WnList read it, in one line: not written, written empty, or its items.
    param($List)
    if ($null -eq $List) { return '(the key is not written)' }
    if (@($List).Count -eq 0) { return '[]' }
    return ('[' + (@($List) -join ' ; ') + ']')
}
$c1aqM = $null
$c1aqM2 = $null
try {
$c1aqGoal = @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30')
$c1aqM = New-WnMission -Tag 'c1aq' -Goals ([ordered]@{ 'G-WNAQ' = $c1aqGoal })
if (-not $c1aqM.ok) { throw ('FIXTURE REFUSED: ' + $c1aqM.why) }
$c1aqRoot = $c1aqM.root
$null = Write-WnStub -Root $c1aqRoot
$c1aqM2 = New-WnMission -Tag 'c1aq2' -Goals ([ordered]@{ 'G-WNAQ' = ($c1aqGoal + @('    instrument_inputs_except: [other]')) })
if (-not $c1aqM2.ok) { throw ('SECOND FIXTURE REFUSED: ' + $c1aqM2.why) }
$c1aqRoot2 = $c1aqM2.root
$null = Write-WnStub -Root $c1aqRoot2
$c1aqGoal2Text = [System.IO.File]::ReadAllText((Join-Path $c1aqM2.goalsDir 'G-WNAQ.yaml'))
Add-C1aqRow -Label 'FIXTURE two git repositories under %TEMP%, the base tools pinned; in each .gitignore, mission.yaml (admitted_porcelain: "?? scratch/"), inputs/, other/ and the goal G-WNAQ committed -- instrument_exit0 over scratch/inst.ps1, reuse_within_minutes: 30; in the SECOND also instrument_inputs_except: [other] -- and porcelain reads exactly "?? scratch/"' `
    -Ok ($wnBase.ok -and ((Get-WnPorcelain -Root $c1aqRoot) -ceq '?? scratch/') -and ((Get-WnPorcelain -Root $c1aqRoot2) -ceq '?? scratch/') -and ($c1aqM.head -cmatch '\A[0-9a-f]{40}\z') -and ($c1aqM2.head -cmatch '\A[0-9a-f]{40}\z') -and
         $c1aqGoal2Text.Contains("`n    reuse_within_minutes: 30`n    instrument_inputs_except: [other]`n") -and (-not [System.IO.File]::ReadAllText((Join-Path $c1aqM.goalsDir 'G-WNAQ.yaml')).Contains('instrument_inputs_except'))) `
    -Said ('HEAD ' + $c1aqM.head + ' and, the second, ' + $c1aqM2.head + '; ' + $wnBase.said)

# (a) THE RED, KEPT, FIRST: one RED capture at HEAD inside the window, the stub GREEN again -- at the base.
#     What stands under instrument-runs after each evaluation is read here and asserted by row (d).
Clear-WnCaptures -Root $c1aqRoot
Set-WnStubFlag -Root $c1aqRoot -Exit 3
$c1aqABCap = New-WnCapture -Tools base -Root $c1aqRoot -Key 'RED'
Set-WnStubFlag -Root $c1aqRoot
$c1aqAB = Get-C1aqReading -Tools base -Root $c1aqRoot
$c1aqABKept = Get-C1aqKeptPath -Capture $c1aqABCap
$c1aqABKeptSha = Get-C1aqFileSha -Path $c1aqABKept
$c1aqABNames = @(Get-C1aqKeptNames -RunsDir $c1aqM.runsDir)
Add-C1aqRow -Label '(a) BASE CONTROL: one RED capture (exit 3) of the stub at HEAD, seconds old, the window 30, the stub GREEN again: the base REUSES it AS RED -- the detail opens "inst.ps1 exited 3 (require 0). REUSED A FRESH READING, " and cites the capture by path and sha256 --, the stub NOT run (its counter unmoved), ok false, NOT_MET, exit 1' `
    -Ok ($c1aqABCap.ok -and ($c1aqABCap.exit -eq 3) -and ([string]$c1aqABCap.header['head'] -ceq $c1aqM.head) -and ($c1aqAB.ran -eq 0) -and $c1aqAB.found -and (-not $c1aqAB.ok) -and ($c1aqAB.verdict -ceq 'NOT_MET') -and ($c1aqAB.exit -eq 1) -and
         $c1aqAB.detail.StartsWith('inst.ps1 exited 3 (require 0). REUSED A FRESH READING, ') -and $c1aqAB.detail.Contains(': capture ' + $c1aqABCap.path + ' sha256 ' + $c1aqABCap.sha256 + ', captured_at ')) `
    -Said ('the capture: ' + (Get-C1aqCaptureSaid -Capture $c1aqABCap) + ' | base: ran ' + $c1aqAB.ran + ', exit ' + $c1aqAB.exit + ', ' + $c1aqAB.verdict + '; detail: ' + $c1aqAB.detail)
# (a) THE RULING's FALSIFIER, AT THIS TREE: the same sequence, its own capture.
Clear-WnCaptures -Root $c1aqRoot
Set-WnStubFlag -Root $c1aqRoot -Exit 3
$c1aqATCap = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'RED'
Set-WnStubFlag -Root $c1aqRoot
$c1aqAT = Get-C1aqReading -Tools tree -Root $c1aqRoot
$c1aqATKept = Get-C1aqKeptPath -Capture $c1aqATCap
$c1aqATKeptSha = Get-C1aqFileSha -Path $c1aqATKept
$c1aqATNames = @(Get-C1aqKeptNames -RunsDir $c1aqM.runsDir)
Add-C1aqRow -Label '(a) FALSIFIER one RED capture (exit 3) of the stub at HEAD, seconds old, the window 30, the stub GREEN again: the stub RUNS (its counter +1) -- the RED is not reused, it is re-measured, and the verdict is the re-measurement''s: MET, exit 0, "inst.ps1 exited 0 (require 0). Instrument output " -- and the detail, after the lead "NOT reused, the instrument was run (register row 368) -- ", names the newest capture that passes by file name and sha256 and says "exited 3: a reading that is not exit 0 is never reused, it is re-measured (register row 412)."; nothing is named as reused' `
    -Ok ($c1aqATCap.ok -and ($c1aqATCap.exit -eq 3) -and ([string]$c1aqATCap.header['head'] -ceq $c1aqM.head) -and ($c1aqAT.ran -eq 1) -and $c1aqAT.ok -and ($c1aqAT.verdict -ceq 'MET') -and ($c1aqAT.exit -eq 0) -and
         $c1aqAT.detail.StartsWith('inst.ps1 exited 0 (require 0). Instrument output ') -and $c1aqAT.detail.Contains(' reuse_within_minutes 30: NOT reused, the instrument was run (register row 368) -- ') -and
         (Test-C1aqNamed -Detail $c1aqAT.detail -Lead 'the newest capture that passes, ' -Name 'RED.inst.stdout.txt' -Tail (' sha256 ' + $c1aqATCap.sha256)) -and $c1aqAT.detail.Contains('exited 3: a reading that is not exit 0 is never reused, it is re-measured (register row 412).') -and
         ($null -ne $c1aqAT.reused) -and ($c1aqAT.reused.Count -eq 0)) `
    -Said ('the capture: ' + (Get-C1aqCaptureSaid -Capture $c1aqATCap) + ' | tree: ran ' + $c1aqAT.ran + ', exit ' + $c1aqAT.exit + ', ' + $c1aqAT.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqAT.reused) + '; detail: ' + $c1aqAT.detail)

# (b) AN OLDER GREEN AND A NEWER RED AT THE SAME HEAD: the RED is the newest capture that passes -- the base
#     hands it back (C-1ai (q)'s first half), the tree re-measures; the GREEN is cited by neither.
Clear-WnCaptures -Root $c1aqRoot
$c1aqBBGreen = New-WnCapture -Tools base -Root $c1aqRoot -Key 'GREEN' -AgeSeconds 600
Set-WnStubFlag -Root $c1aqRoot -Exit 3
$c1aqBBRed = New-WnCapture -Tools base -Root $c1aqRoot -Key 'RED' -AgeSeconds 60
Set-WnStubFlag -Root $c1aqRoot
$c1aqBB = Get-C1aqReading -Tools base -Root $c1aqRoot
Add-C1aqRow -Label '(b) BASE CONTROL: an OLDER GREEN capture (10 minutes) and a NEWER RED one (1 minute) at the same HEAD, the stub GREEN again: the base REUSES THE RED, AS RED -- "inst.ps1 exited 3 (require 0). REUSED A FRESH READING, ", the RED capture cited by path and sha256 in the detail and in instrument_captures_reused --, the stub NOT run, NOT_MET, exit 1' `
    -Ok ($c1aqBBGreen.ok -and ($c1aqBBGreen.exit -eq 0) -and $c1aqBBRed.ok -and ($c1aqBBRed.exit -eq 3) -and ($c1aqBB.ran -eq 0) -and (-not $c1aqBB.ok) -and ($c1aqBB.verdict -ceq 'NOT_MET') -and ($c1aqBB.exit -eq 1) -and
         $c1aqBB.detail.StartsWith('inst.ps1 exited 3 (require 0). REUSED A FRESH READING, ') -and $c1aqBB.detail.Contains(': capture ' + $c1aqBBRed.path + ' sha256 ' + $c1aqBBRed.sha256 + ', captured_at ') -and
         ($null -ne $c1aqBB.reused) -and ($c1aqBB.reused.Count -eq 1) -and ($c1aqBB.reused[0] -ceq ($c1aqBBRed.path + ' sha256 ' + $c1aqBBRed.sha256))) `
    -Said ('GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqBBGreen) + ' | RED: ' + (Get-C1aqCaptureSaid -Capture $c1aqBBRed) + ' | base: ran ' + $c1aqBB.ran + ', exit ' + $c1aqBB.exit + ', ' + $c1aqBB.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqBB.reused) + '; detail: ' + $c1aqBB.detail)
Clear-WnCaptures -Root $c1aqRoot
$c1aqBTGreen = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'GREEN' -AgeSeconds 600
Set-WnStubFlag -Root $c1aqRoot -Exit 3
$c1aqBTRed = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'RED' -AgeSeconds 60
Set-WnStubFlag -Root $c1aqRoot
$c1aqBT = Get-C1aqReading -Tools tree -Root $c1aqRoot
$c1aqBTGreenCited = @($c1aqBT.reused | Where-Object { $_ -and (([string]$_).Contains('GREEN.inst.stdout.txt') -or ($c1aqBTGreen.sha256 -and ([string]$_).Contains([string]$c1aqBTGreen.sha256))) }).Count
Add-C1aqRow -Label '(b) FALSIFIER an OLDER GREEN capture (10 minutes) and a NEWER RED one (1 minute) at the same HEAD, the stub GREEN again: the stub RUNS -- the RED is the newest capture that passes, named by file name and sha256, and the detail says "a reading that is not exit 0 is never reused" --, MET, exit 0; and the older GREEN is NOT fallen back on: instrument_captures_reused is written and names no capture' `
    -Ok ($c1aqBTGreen.ok -and ($c1aqBTGreen.exit -eq 0) -and $c1aqBTRed.ok -and ($c1aqBTRed.exit -eq 3) -and ($c1aqBT.ran -eq 1) -and $c1aqBT.ok -and ($c1aqBT.verdict -ceq 'MET') -and ($c1aqBT.exit -eq 0) -and
         $c1aqBT.detail.Contains('a reading that is not exit 0 is never reused') -and (Test-C1aqNamed -Detail $c1aqBT.detail -Lead 'the newest capture that passes, ' -Name 'RED.inst.stdout.txt' -Tail (' sha256 ' + $c1aqBTRed.sha256)) -and
         ($null -ne $c1aqBT.reused) -and ($c1aqBTGreenCited -eq 0) -and ($c1aqBT.reused.Count -eq 0)) `
    -Said ('GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqBTGreen) + ' | RED: ' + (Get-C1aqCaptureSaid -Capture $c1aqBTRed) + ' | tree: ran ' + $c1aqBT.ran + ', exit ' + $c1aqBT.exit + ', ' + $c1aqBT.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqBT.reused) + '; detail: ' + $c1aqBT.detail)

# (c) THE ROW THAT TIES THE INPUT TREE TO THIS RULE, in the SECOND fixture, whose goal declares
#     instrument_inputs_except: [other]. The base's sequence first -- its helper has no input tree to give a
#     capture -- HEAD moving H1 -> H2; then the tree's, over captures taken at H2, HEAD moving H2 -> H3. Each
#     commit touches other/b.txt alone: the excluded path, so the figure over the head's tree less `other` is
#     the same at both ends, and the GREEN capture that carries it passes at the moved HEAD.
$c1aqH1 = $c1aqM2.head
Clear-WnCaptures -Root $c1aqRoot2
$c1aqCBGreen = New-WnCapture -Tools base -Root $c1aqRoot2 -Key 'GREEN' -AgeSeconds 600
Set-WnStubFlag -Root $c1aqRoot2 -Exit 3
$c1aqCBRed = New-WnCapture -Tools base -Root $c1aqRoot2 -Key 'RED' -AgeSeconds 60
Set-WnStubFlag -Root $c1aqRoot2
$c1aqH2 = Invoke-WnCommit -Root $c1aqRoot2 -Path $c1aqM2.otherRel -Text "not an input of the instrument, changed once`n" -Message 'other changes'
$c1aqCB = Get-C1aqReading -Tools base -Root $c1aqRoot2
Add-C1aqRow -Label '(c) BASE CONTROL: an older GREEN and a newer RED capture taken at H1 (the base''s helper gives neither an input_tree), HEAD then moved to H2 by a commit under other\ alone: the stub RUNS at the base too -- FOR ITS HEAD: "2 capture(s) of this instrument considered, none passes", each "its head is <H1>, and HEAD is <H2>" -- and the detail names no register row 412: no capture''s exit code was read' `
    -Ok ($c1aqCBGreen.ok -and ($c1aqCBGreen.exit -eq 0) -and ([string]$c1aqCBGreen.header['head'] -ceq $c1aqH1) -and (-not $c1aqCBGreen.header.ContainsKey('input_tree')) -and $c1aqCBRed.ok -and ($c1aqCBRed.exit -eq 3) -and ([string]$c1aqCBRed.header['head'] -ceq $c1aqH1) -and
         ($c1aqH2 -cmatch '\A[0-9a-f]{40}\z') -and ($c1aqH2 -cne $c1aqH1) -and ($c1aqCB.ran -eq 1) -and ($c1aqCB.verdict -ceq 'MET') -and $c1aqCB.detail.Contains('2 capture(s) of this instrument considered, none passes: ') -and
         $c1aqCB.detail.Contains('RED.inst.stdout.txt: its head is ' + $c1aqH1 + ', and HEAD is ' + $c1aqH2) -and $c1aqCB.detail.Contains('GREEN.inst.stdout.txt: its head is ' + $c1aqH1 + ', and HEAD is ' + $c1aqH2) -and (-not $c1aqCB.detail.Contains('register row 412'))) `
    -Said ('GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqCBGreen) + ' | RED: ' + (Get-C1aqCaptureSaid -Capture $c1aqCBRed) + ' | HEAD ' + $c1aqH1 + ' -> ' + $c1aqH2 + ' | base: ran ' + $c1aqCB.ran + ', exit ' + $c1aqCB.exit + ', ' + $c1aqCB.verdict + '; detail: ' + $c1aqCB.detail)
Clear-WnCaptures -Root $c1aqRoot2
$c1aqCTGreen = New-WnCapture -Tools tree -Root $c1aqRoot2 -Key 'GREEN' -Except @('other') -AgeSeconds 600
Set-WnStubFlag -Root $c1aqRoot2 -Exit 3
$c1aqCTRed = New-WnCapture -Tools tree -Root $c1aqRoot2 -Key 'RED' -AgeSeconds 60
Set-WnStubFlag -Root $c1aqRoot2
$c1aqH3 = Invoke-WnCommit -Root $c1aqRoot2 -Path $c1aqM2.otherRel -Text "not an input of the instrument, changed twice`n" -Message 'other changes again'
$c1aqCT = Get-C1aqReading -Tools tree -Root $c1aqRoot2
$c1aqCTNames = @(Get-C1aqKeptNames -RunsDir $c1aqM2.runsDir)
Add-C1aqRow -Label '(c) FALSIFIER a GREEN capture CARRYING input_tree taken at H2 (the helper called with -InstrumentInputsExcept other), a NEWER RED capture WITHOUT input_tree at H2 (the helper called with no such parameter), HEAD then moved to H3 by a commit under other\ alone: the stub RUNS -- the GREEN passes by its input tree and the RED, declined for its head, still stands after it: the detail names the RED capture by file name and sha256 as "a later reading of this instrument", says it "exited 3 after the capture that passes (" -- GREEN.inst.stdout.txt, named in that bracket -- and says "a RED is never stepped over, it is re-measured (register row 412)."; nothing is named as reused and no copy of the GREEN is kept' `
    -Ok ($c1aqCTGreen.ok -and ($c1aqCTGreen.exit -eq 0) -and ([string]$c1aqCTGreen.header['head'] -ceq $c1aqH2) -and ([string]$c1aqCTGreen.header['tree_clean'] -ceq 'True') -and ([string]$c1aqCTGreen.header['input_tree'] -cmatch '\A[0-9a-f]{64}\z') -and
         $c1aqCTRed.ok -and ($c1aqCTRed.exit -eq 3) -and ([string]$c1aqCTRed.header['head'] -ceq $c1aqH2) -and (-not $c1aqCTRed.header.ContainsKey('input_tree')) -and ($c1aqH3 -cmatch '\A[0-9a-f]{40}\z') -and ($c1aqH3 -cne $c1aqH2) -and
         ($c1aqCT.ran -eq 1) -and ($c1aqCT.verdict -ceq 'MET') -and $c1aqCT.detail.Contains('a RED is never stepped over, it is re-measured (register row 412).') -and
         (Test-C1aqNamed -Detail $c1aqCT.detail -Lead 'a later reading of this instrument, ' -Name 'RED.inst.stdout.txt' -Tail (' sha256 ' + $c1aqCTRed.sha256)) -and (Test-C1aqNamed -Detail $c1aqCT.detail -Lead 'exited 3 after the capture that passes (' -Name 'GREEN.inst.stdout.txt' -Tail ')') -and
         ($null -ne $c1aqCT.reused) -and ($c1aqCT.reused.Count -eq 0) -and ($c1aqCTNames.Count -eq 0)) `
    -Said ('GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqCTGreen) + ' | RED: ' + (Get-C1aqCaptureSaid -Capture $c1aqCTRed) + ' | HEAD ' + $c1aqH2 + ' -> ' + $c1aqH3 + ' | tree: ran ' + $c1aqCT.ran + ', exit ' + $c1aqCT.exit + ', ' + $c1aqCT.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqCT.reused) + '; kept names: ' + $c1aqCTNames.Count + '; detail: ' + $c1aqCT.detail)

# (d) NO COPY IS KEPT OF A RED CAPTURE: what stood under instrument-runs after row (a)'s two evaluations.
Add-C1aqRow -Label '(d) BASE CONTROL: after row (a)''s evaluation at the base: the reuse of the RED capture KEPT A COPY of it -- RED.inst.<sha8>.stdout.txt stands beside it, hashes to the RED capture''s sha256, and is the one kept-copy name on disk; the detail ends naming it "(written now; register row 391)." and instrument_captures_kept holds it' `
    -Ok ($c1aqABCap.ok -and [bool]$c1aqABKept -and ($c1aqABKeptSha -ceq $c1aqABCap.sha256) -and ($c1aqABNames.Count -eq 1) -and ($c1aqABNames[0] -ceq ('RED.inst.' + (Get-C1aqSha8 -Capture $c1aqABCap) + '.stdout.txt')) -and
         $c1aqAB.detail.EndsWith(' THE CAPTURE CITED IS KEPT at ' + $c1aqABKept + ' (written now; register row 391).') -and ($null -ne $c1aqAB.kept) -and ($c1aqAB.kept.Count -eq 1) -and ($c1aqAB.kept[0] -ceq ($c1aqABKept + ' sha256 ' + $c1aqABCap.sha256))) `
    -Said ('the RED capture sha256 ' + $c1aqABCap.sha256 + '; kept-copy names under instrument-runs: [' + ($c1aqABNames -join ', ') + ']; ' + $c1aqABKept + ' sha256 ' + $c1aqABKeptSha + '; instrument_captures_kept ' + (Get-C1aqListSaid -List $c1aqAB.kept))
Add-C1aqRow -Label '(d) FALSIFIER after row (a)''s evaluation at this tree -- the stub ran and the detail says "a reading that is not exit 0 is never reused", so the RED capture WAS the one chosen --: NO <key>.inst.<8 hex>.stdout.txt stands for the RED capture''s sha256 -- no kept-copy name stands under instrument-runs at all -- and instrument_captures_kept is written and names nothing: a RED capture is read for its exit code before anything is kept' `
    -Ok ($c1aqATCap.ok -and [bool]$c1aqATKept -and $c1aqAT.found -and ($c1aqAT.ran -eq 1) -and $c1aqAT.detail.Contains('a reading that is not exit 0 is never reused') -and
         ($c1aqATKeptSha -ceq '(absent)') -and ($c1aqATNames.Count -eq 0) -and ($null -ne $c1aqAT.kept) -and ($c1aqAT.kept.Count -eq 0)) `
    -Said ('the RED capture sha256 ' + $c1aqATCap.sha256 + '; tree: ran ' + $c1aqAT.ran + ', the detail says "a reading that is not exit 0 is never reused": ' + $c1aqAT.detail.Contains('a reading that is not exit 0 is never reused') + '; kept-copy names under instrument-runs: [' + ($c1aqATNames -join ', ') + ']; ' + $c1aqATKept + ' sha256 ' + $c1aqATKeptSha + '; instrument_captures_kept ' + (Get-C1aqListSaid -List $c1aqAT.kept))

# (e) CONTROL, BOTH TOOLS: a GREEN capture alone is reused as it was. The same sequence twice in the first
#     fixture, each from an empty instrument-runs, so each reuse keeps its copy "written now"; the two captures
#     differ in their clock and so in their sha256, which is named to Get-WnComparable with its first eight.
Clear-WnCaptures -Root $c1aqRoot
$c1aqEBCap = New-WnCapture -Tools base -Root $c1aqRoot -Key 'GREEN'
$c1aqEB = Get-C1aqReading -Tools base -Root $c1aqRoot
Clear-WnCaptures -Root $c1aqRoot
$c1aqETCap = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'GREEN'
$c1aqET = Get-C1aqReading -Tools tree -Root $c1aqRoot
$c1aqEBCmp = Get-WnComparable -Text $c1aqEB.detail -Mask @([string]$c1aqEBCap.sha256, (Get-C1aqSha8 -Capture $c1aqEBCap))
$c1aqETCmp = Get-WnComparable -Text $c1aqET.detail -Mask @([string]$c1aqETCap.sha256, (Get-C1aqSha8 -Capture $c1aqETCap))
Add-C1aqRow -Label '(e) CONTROL a GREEN capture alone, at HEAD, seconds old: REUSED on BOTH tools -- the stub not run, MET, exit 0, "inst.ps1 exited 0 (require 0). REUSED A FRESH READING, " to "(written now; register row 391)." -- each naming its own capture in instrument_captures_reused, and the two details EQUAL but for the clock (captured_at, the age, and the capture''s sha256 with the eight of it in the kept copy''s name)' `
    -Ok ($c1aqEBCap.ok -and ($c1aqEBCap.exit -eq 0) -and $c1aqETCap.ok -and ($c1aqETCap.exit -eq 0) -and ($c1aqEB.ran -eq 0) -and ($c1aqET.ran -eq 0) -and $c1aqEB.ok -and $c1aqET.ok -and ($c1aqEB.verdict -ceq 'MET') -and ($c1aqET.verdict -ceq 'MET') -and
         ($c1aqEB.exit -eq 0) -and ($c1aqET.exit -eq 0) -and $c1aqEB.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and $c1aqET.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and
         $c1aqEB.detail.EndsWith(' (written now; register row 391).') -and $c1aqET.detail.EndsWith(' (written now; register row 391).') -and ($c1aqEBCmp -ceq $c1aqETCmp) -and $c1aqETCmp.Contains('<MASK1>') -and $c1aqETCmp.Contains('.inst.<MASK2>.stdout.txt') -and
         ($null -ne $c1aqEB.reused) -and ($c1aqEB.reused.Count -eq 1) -and ($c1aqEB.reused[0] -ceq ($c1aqEBCap.path + ' sha256 ' + $c1aqEBCap.sha256)) -and ($null -ne $c1aqET.reused) -and ($c1aqET.reused.Count -eq 1) -and ($c1aqET.reused[0] -ceq ($c1aqETCap.path + ' sha256 ' + $c1aqETCap.sha256))) `
    -Said ('base: ran ' + $c1aqEB.ran + ', exit ' + $c1aqEB.exit + ', ' + $c1aqEB.verdict + ' | tree: ran ' + $c1aqET.ran + ', exit ' + $c1aqET.exit + ', ' + $c1aqET.verdict + ' | details equal but for the clock: ' + ($c1aqEBCmp -ceq $c1aqETCmp) + ' | the tree''s, compared form: ' + $c1aqETCmp)

# (f) CONTROL, AT THIS TREE: "STEPPED OVER" IS A MATTER OF ORDER. Row (b) turned round -- an OLDER RED and a
#     NEWER GREEN at the same HEAD. The GREEN is the newest capture that passes and no reading of the instrument
#     was taken after it, so it is reused as it always was: a rule that let ANY RED capture of the instrument
#     stop a reuse, whenever it was captured, would run the stub here, and no other row of this member would
#     see it. (At the base the answer is the same; C-1ai (q)'s second half keeps it in the old fixture.)
Clear-WnCaptures -Root $c1aqRoot
Set-WnStubFlag -Root $c1aqRoot -Exit 3
$c1aqFRed = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'RED' -AgeSeconds 600
Set-WnStubFlag -Root $c1aqRoot
$c1aqFGreen = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'GREEN' -AgeSeconds 60
$c1aqF = Get-C1aqReading -Tools tree -Root $c1aqRoot
Add-C1aqRow -Label '(f) CONTROL an OLDER RED capture (10 minutes) and a NEWER GREEN one (1 minute) at the same HEAD, at this tree: the GREEN is REUSED -- the stub NOT run, MET, exit 0, "inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ", the GREEN capture cited by path and sha256 in the detail and alone in instrument_captures_reused --: a RED captured BEFORE the capture that passes is no later reading, nothing is stepped over, and the detail names no register row 412' `
    -Ok ($c1aqFRed.ok -and ($c1aqFRed.exit -eq 3) -and $c1aqFGreen.ok -and ($c1aqFGreen.exit -eq 0) -and ($c1aqF.ran -eq 0) -and $c1aqF.ok -and ($c1aqF.verdict -ceq 'MET') -and ($c1aqF.exit -eq 0) -and
         $c1aqF.detail.StartsWith('inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ') -and $c1aqF.detail.Contains(': capture ' + $c1aqFGreen.path + ' sha256 ' + $c1aqFGreen.sha256 + ', captured_at ') -and (-not $c1aqF.detail.Contains('register row 412')) -and
         ($null -ne $c1aqF.reused) -and ($c1aqF.reused.Count -eq 1) -and ($c1aqF.reused[0] -ceq ($c1aqFGreen.path + ' sha256 ' + $c1aqFGreen.sha256))) `
    -Said ('RED: ' + (Get-C1aqCaptureSaid -Capture $c1aqFRed) + ' | GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqFGreen) + ' | tree: ran ' + $c1aqF.ran + ', exit ' + $c1aqF.exit + ', ' + $c1aqF.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqF.reused) + '; detail: ' + $c1aqF.detail)

# (g) STATED, NOT CLAIMED (the independent validator's round 1): WHAT "A LATER RED" IS NOT. Row (b)
#     again -- an OLDER GREEN and a NEWER RED at the same HEAD, the RED taken seconds ago -- and then the RED
#     capture's `captured_at:` line is rewritten on disk to `not-a-time`, every other line of it as the helper
#     wrote it (exit_code: 3, ran: True, this instrument's own path). The chain declines that capture for the
#     line, so the GREEN is the newest capture that passes; and the rule's second half does not remember it
#     either: a RED is remembered only where it is WHOLE, a captured_at that parses among the conditions. The
#     residual this row measured until BATCH-6 -- the GREEN reused, the detail saying nothing of the RED: one line
#     of a capture decided whether its RED counted -- IS CLOSED (BATCH-6 WP-Q; ruled
#     2026-10-16 07:2x local, lean accepted), AND THE ROW IS RE-ASSERTED TO IT: the undatable capture refuses the
#     reuse, the stub runs, nothing is reused, and the note names the RED capture as undatable.
Clear-WnCaptures -Root $c1aqRoot
$c1aqGGreen = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'GREEN' -AgeSeconds 600
Set-WnStubFlag -Root $c1aqRoot -Exit 3
$c1aqGRed = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'RED'
Set-WnStubFlag -Root $c1aqRoot
$c1aqGRedNow = $c1aqGRed
if ($c1aqGRed.ok) {
    [System.IO.File]::WriteAllText($c1aqGRed.path, ([regex]'(?m)^captured_at: .*$').Replace($c1aqGRed.text, 'captured_at: not-a-time', 1), (New-Object System.Text.UTF8Encoding($false)))
    $c1aqGRedNow = Read-WnCapture -Path $c1aqGRed.path
}
$c1aqG = Get-C1aqReading -Tools tree -Root $c1aqRoot
Add-C1aqRow -Label '(g) RE-ASSERTED BY BATCH-6 WP-Q: an OLDER GREEN capture (10 minutes) and a NEWER RED one (exit 3, seconds old) at the same HEAD, and the RED capture''s `captured_at:` line then rewritten to `not-a-time` -- its exit_code: 3, its ran: True and its instrument path left as written: the RED rule does not remember it (it is not WHOLE), and it is UNDATABLE, so NOTHING IS REUSED -- the stub RUN once, MET, exit 0, instrument_captures_reused written EMPTY, the note naming RED.inst.stdout.txt by sha256, "its captured_at does not parse (not-a-time)" and the GREEN capture that passes, under register row 423 and not register row 412' `
    -Ok ($c1aqGGreen.ok -and ($c1aqGGreen.exit -eq 0) -and ([string]$c1aqGGreen.header['head'] -ceq $c1aqM.head) -and $c1aqGRed.ok -and ($c1aqGRed.exit -eq 3) -and ([string]$c1aqGRed.header['head'] -ceq $c1aqM.head) -and
         $c1aqGRedNow.ok -and ($c1aqGRedNow.sha256 -cne $c1aqGRed.sha256) -and ([string]$c1aqGRedNow.header['captured_at'] -ceq 'not-a-time') -and ([string]$c1aqGRedNow.header['exit_code'] -ceq '3') -and ([string]$c1aqGRedNow.header['ran'] -ceq 'True') -and
         ($c1aqG.ran -eq 1) -and $c1aqG.ok -and ($c1aqG.verdict -ceq 'MET') -and ($c1aqG.exit -eq 0) -and $c1aqG.detail.StartsWith('inst.ps1 exited 0 (require 0). Instrument output ') -and
         $c1aqG.detail.Contains(' reuse_within_minutes 30: NOT reused, the instrument was run (register row 368) -- an undatable capture of this instrument stands among the candidates, RED.inst.stdout.txt sha256 ' + $c1aqGRedNow.sha256 + ': its captured_at does not parse (not-a-time) -- it cannot be placed before or after the capture that passes, GREEN.inst.stdout.txt, so it is never stepped over; the instrument is re-measured (register row 423).') -and
         (-not $c1aqG.detail.Contains('register row 412')) -and ($null -ne $c1aqG.reused) -and ($c1aqG.reused.Count -eq 0)) `
    -Said ('GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqGGreen) + ' | RED, as the helper wrote it: ' + (Get-C1aqCaptureSaid -Capture $c1aqGRed) + ' | RED, as it then stands on disk: captured_at [' + [string]$c1aqGRedNow.header['captured_at'] + '], exit_code ' + [string]$c1aqGRedNow.header['exit_code'] + ', ran ' + [string]$c1aqGRedNow.header['ran'] + ', sha256 ' + [string]$c1aqGRedNow.sha256 +
           ' | tree: ran ' + $c1aqG.ran + ', exit ' + $c1aqG.exit + ', ' + $c1aqG.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqG.reused) + '; detail: ' + $c1aqG.detail)

# (h) A LATER RED IS REMEMBERED WHATEVER THE CHAIN DECLINES IT FOR (the builder's own mutation sweep after the
#     independent validator's round 3). The rule's (2) is read off EVERY candidate, apart from the chain: a
#     WHOLE RED capture counts though the chain declines it -- for its head (row (c) is that), and as much for
#     its tree_clean or its instrument_sha256. No row held those two: a second half that remembered a RED only
#     where its tree had been clean, or only where its instrument's bytes are the bytes now, read every row
#     ok. Two sequences in the first fixture, each an OLDER GREEN and a NEWER RED at the same HEAD:
#       tree_clean          the RED taken while the tracked inputs/a.txt held uncommitted bytes, then put back
#       instrument_sha256   the RED taken while the stub held one line more, then put back
#     The chain declines that RED for the one thing -- the detail names the GREEN, not the RED, as the capture
#     that passes -- and the RED after it still stops the reuse. CONTROLS: the evaluator read them ok when
#     they were written; no wrong cure of ours is of record behind them, the sweep's two mutants are.
$c1aqHStub = Join-Path $c1aqRoot 'scratch\inst.ps1'
foreach ($c1aqHCase in @(
        @{ key = 'tree_clean'; what = 'taken while the tracked inputs/a.txt held UNCOMMITTED bytes (its header: tree_clean: False), the file then put back' },
        @{ key = 'instrument_sha256'; what = 'taken while the stub held ONE LINE MORE (its header: another instrument_sha256), the stub''s bytes then put back' })) {
    Clear-WnCaptures -Root $c1aqRoot
    Set-WnStubFlag -Root $c1aqRoot
    $c1aqHGreen = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'GREEN' -AgeSeconds 600
    $c1aqHInput = [System.IO.File]::ReadAllBytes($c1aqM.inputsFile)
    if ($c1aqHCase.key -ceq 'tree_clean') { [System.IO.File]::WriteAllBytes($c1aqM.inputsFile, $pwUtf8.GetBytes("an input of the instrument, EDITED AND NOT COMMITTED`n")) }
    else { Write-Utf8 -Path $c1aqHStub -Text (($wnStubText -replace "`r", '') + "`n# one line more: these are not the bytes the goal's instrument holds`n") }
    Set-WnStubFlag -Root $c1aqRoot -Exit 3
    $c1aqHRed = New-WnCapture -Tools tree -Root $c1aqRoot -Key 'RED' -AgeSeconds 60
    Set-WnStubFlag -Root $c1aqRoot
    [System.IO.File]::WriteAllBytes($c1aqM.inputsFile, $c1aqHInput)
    $null = Write-WnStub -Root $c1aqRoot
    if ((Get-WnPorcelain -Root $c1aqRoot) -cne '?? scratch/') { throw ('FIXTURE SLIP: the fixture was not put back after (h)''s RED capture (' + $c1aqHCase.key + ')') }
    $c1aqH = Get-C1aqReading -Tools tree -Root $c1aqRoot
    $c1aqHDiffers = ([string]$c1aqHRed.header[$c1aqHCase.key] -cne [string]$c1aqHGreen.header[$c1aqHCase.key])
    Add-C1aqRow -Label ('(h) CONTROL A LATER RED IS REMEMBERED WHATEVER THE CHAIN DECLINES IT FOR, its ' + $c1aqHCase.key + ': an OLDER GREEN capture (10 minutes) and a NEWER RED one (1 minute, exit 3) at the same HEAD, the RED ' + $c1aqHCase.what + ': the GREEN is the newest capture that passes and it is NOT reused -- the stub RUNS, MET --, the detail naming the RED capture by file name and sha256 as "a later reading of this instrument", "exited 3 after the capture that passes (" GREEN.inst.stdout.txt ")", and "a RED is never stepped over, it is re-measured (register row 412)."; nothing is named as reused; a second half that remembered a RED only where the chain would pass its ' + $c1aqHCase.key + ' would reuse the GREEN (the builder''s own mutation sweep after the independent validator''s round 3)') `
        -Ok ($c1aqHGreen.ok -and ($c1aqHGreen.exit -eq 0) -and $c1aqHRed.ok -and ($c1aqHRed.exit -eq 3) -and ([string]$c1aqHRed.header['head'] -ceq $c1aqM.head) -and $c1aqHDiffers -and
             (($c1aqHCase.key -cne 'tree_clean') -or ([string]$c1aqHRed.header['tree_clean'] -ceq 'False')) -and ($c1aqH.ran -eq 1) -and ($c1aqH.verdict -ceq 'MET') -and
             $c1aqH.detail.Contains('a RED is never stepped over, it is re-measured (register row 412).') -and
             (Test-C1aqNamed -Detail $c1aqH.detail -Lead 'a later reading of this instrument, ' -Name 'RED.inst.stdout.txt' -Tail (' sha256 ' + $c1aqHRed.sha256)) -and (Test-C1aqNamed -Detail $c1aqH.detail -Lead 'exited 3 after the capture that passes (' -Name 'GREEN.inst.stdout.txt' -Tail ')') -and
             ($null -ne $c1aqH.reused) -and ($c1aqH.reused.Count -eq 0)) `
        -Said ('GREEN: ' + (Get-C1aqCaptureSaid -Capture $c1aqHGreen) + ' | RED: ' + (Get-C1aqCaptureSaid -Capture $c1aqHRed) + ', its ' + $c1aqHCase.key + ' [' + [string]$c1aqHRed.header[$c1aqHCase.key] + '] against the GREEN''s [' + [string]$c1aqHGreen.header[$c1aqHCase.key] + ']' +
               ' | tree: ran ' + $c1aqH.ran + ', exit ' + $c1aqH.exit + ', ' + $c1aqH.verdict + '; instrument_captures_reused ' + (Get-C1aqListSaid -List $c1aqH.reused) + '; detail: ' + $c1aqH.detail)
}
}
catch {
    $c1aqOk = $false
    $c1aqRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1aqRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1aqM2) { Remove-PwTreeAsWritten -Base $c1aqM2.base }
if ($null -ne $c1aqM) { Remove-PwTreeAsWritten -Base $c1aqM.base }
Check -Id 'C-1aq' -Title 'A RED IS NEVER REUSED AND NEVER STEPPED OVER (the second member; the operator''s ruling 5 of 2026-10-11): at the base evaluator one RED capture of the instrument at HEAD inside the window is REUSED AS RED -- "exited 3 (require 0). REUSED A FRESH READING", the instrument not run, NOT_MET, exit 1 -- and so is the newer RED of an older GREEN and a newer RED, and the reuse keeps a content-addressed copy of the RED capture; at this tree the capture chosen is read for its exit code BEFORE anything is kept: a capture that did not exit 0 is never reused -- the instrument RUNS, read off the counter the stub itself appends to, the detail names the capture by file name and sha256 and says "a reading that is not exit 0 is never reused, it is re-measured (register row 412).", the verdict is the re-measurement''s, the older GREEN is not fallen back on, nothing is named as reused and NO copy of the RED capture is kept; and a RED is never stepped over -- a GREEN capture carrying input_tree, passing at a moved HEAD by its input tree (instrument_inputs_except: [other], the exclusion form of ruling D2; the commit under other\ alone), is NOT reused where a later whole capture of the same instrument exited 3, though that RED carries no input_tree and is itself declined for its head: the instrument runs and the detail names the RED capture and says "a RED is never stepped over, it is re-measured (register row 412)." -- where the base, kept as the control, runs the instrument for its head and names no RED rule; and a GREEN capture alone is REUSED by both tools, the two entries equal but for the clock; and "stepped over" is a matter of order -- a newer GREEN capture after an OLDER RED one is REUSED as it always was; and, stated and not claimed (the independent validator''s round 1), a later RED is remembered only where the capture is WHOLE -- a newer RED capture whose captured_at line was rewritten to not-a-time is not remembered as a RED, and -- re-asserted by BATCH-6 WP-Q -- is UNDATABLE and refuses the reuse: the older GREEN behind it is NOT reused, the stub runs, and the note names the RED capture as undatable; and a later whole RED is remembered WHATEVER the chain declines it for -- taken while a tracked input held uncommitted bytes (tree_clean: False), or while the instrument held other bytes (another instrument_sha256), it still stops the reuse of the older GREEN and is named (two CONTROL rows from the builder''s own mutation sweep after the independent validator''s round 3)' `
      -Ok $c1aqOk -Detail ("      THE $(@($c1aqRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1aqRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument the goal names; a flag file beside its counter turns it RED, its bytes untouched:`n" + (Get-WlIndented -Text $wnStubText))

# =============================================================================================
# C-1ar -- THE ENGINE READ, DOWN: an instrument_exit0 detector that declares
#          `engine_read` is NOT LAUNCHED into an engine that is down -- "<leaf> NOT RUN: engine down"
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: the base stores
# `engine_read:` and `engine_read_fault:` as it stores any key and reads neither -- the instrument is launched
# whatever the engine's state (with the engine stopped the product instrument's suite did not
# finish inside its wall). THE RULE: both keys are validated at the head of the arm, ahead of the reuse
# question -- a value the evaluator does not make, the empty one among them, a fault without a read, a fault
# it does not inject, a fault that does not apply to the read each FAIL the detector by name, nothing reused
# and nothing launched --; the read itself is made only when the instrument is about to be launched, and
# where it answers DOWN the detector fails "<leaf> NOT RUN: engine down -- <the read's words> (engine_read
# <value>; <the rule's tag>)", no capture is written and the helper is not called; the key
# instrument_engine_reads carries one item per read made. `engine_read_fault` is the fixture's seam
# (pipe_absent, version_exit, version_silent): a detector carrying it asks NO reuse question at all, and its
# detail and its item say FAULT INJECTED BY THE GOAL's engine_read_fault KEY. THE CONTROLS, each a row: a
# goal with no `engine_read` writes the artifact and the capture the base writes, but for the clock; as the
# Stop hook, behind an arm that admits the stop, the detector is not evaluated and nothing is read or run.
# RE-ASSERTED BY BATCH-6 WP-Q (a) (the operator's ruling (b) of 21:49 local): `engine_read`
# ALONE beside a window is READ FIRST, before any reuse decision, and the outcome follows the read -- the pipe
# present, the reuse as before, its read an item; ABSENT, NOT RUN and nothing reused. (Until then it asked
# the reuse question first and a reuse made no read: a goal that declared the key read MET by reuse whatever
# the engine's state -- STATED here, not claimed, and closed by that ruling.)
# NO ROW HERE CAUSES A docker COMMAND: under docker_pipe_then_version every goal but the two of (j) carries
# a version_* fault, so a stand-in child runs in place of docker; the unknown fault value is driven under
# docker_pipe, which makes no docker version read even where its validation is missing. The UP reading is
# C-1aw's.
# (j) AN UNFAULTED DOWN, AND ITS TAIL (the independent validator's round 1, driven as its probe
# p-engine drove it). Every DOWN above goes through the seam, and a detector carrying the fault key asks no
# reuse question: so no row above reads a DOWN the engine itself gave, and none reads what a detector says
# when it asked the reuse question, was answered no, and was then NOT LAUNCHED. The two goals of (j) declare
# docker_pipe_then_version and NO fault key, and are evaluated ONLY by a child whose PATH this member builds
# -- the system directory, the Windows directory, Windows PowerShell's own and git's, and no other -- so the
# evaluator's bounded launch of `docker version` CANNOT START: the read answers DOWN at the pipe (the host's
# engine is down) or at the version step ("it could not be started"); no docker process runs and the host's
# engine is not touched. THE MEMBER EVALUATES NEITHER GOAL where a docker executable can be reached from
# that child (Get-C1arDockerless): the three rows then read MISMATCH and say so. THE RULE (j1) AND (j3) HOLD
# THE DETAIL TO: the reuse note of a detector that was not launched says "and the instrument was not
# launched", never "the instrument was run" beside "NOT RUN". RE-ASSERTED BY BATCH-6 WP-Q:
# the read now comes BEFORE the reuse question, so (j1)'s goal is asked none -- its detail says so in the
# ruling's words, and still never "the instrument was run" beside "NOT RUN".
# (k) THE KEYS ARE REFUSED BEFORE THE REUSE QUESTION (the independent validator's round 3): the
# goals of (e) and (f) declare no window, so two CONTROL rows stand one refusal of each beside a reusable
# GREEN capture inside a window -- a value that is no read, a fault with no read -- and each still fails by
# name with nothing reused and nothing run. (The goal that shows the capture IS reusable declares the window
# and NO engine key: a goal that declares engine_read now reads the engine first.)
# (l) AN EXIT OF 0 ALONE IS NO ANSWER (the builder's own mutation sweep after that round): the bounded-launch
# routine, lifted alone from this tree's evaluator and handed three stand-in children of this member's own,
# answers only for the one that exits 0 AND prints a line -- the seam stands no child that exits 0 in silence.
# THE FIXTURE is the batch's (New-WnMission): the stub under the admitted prefix, every goal committed first.
$c1arOk = $true
$c1arRows = New-Object System.Collections.Generic.List[string]
function Add-C1arRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1arOk = $false }
    $script:c1arRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1arRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1arRunNames {
    # Every name under the fixture's instrument-runs, sorted; none where the directory does not stand.
    if (-not (Test-Path -LiteralPath $script:c1arRunsDir -PathType Container)) { return ,@() }
    return ,@(Get-ChildItem -LiteralPath $script:c1arRunsDir -Force | ForEach-Object { $_.Name } | Sort-Object)
}
function Get-C1arKeySaid {
    # A list key as a row prints it: NOT WRITTEN where Get-WnList read no such key, [] where it is written empty.
    param($Items)
    if ($null -eq $Items) { return 'NOT WRITTEN' }
    return ('[' + (@($Items) -join ' | ') + ']')
}
function Get-C1arOpening {
    # How many items of a list key open with -Opening (ordinal): 0 where the key is not written or is empty.
    param($Items, [string]$Opening)
    if ($null -eq $Items) { return 0 }
    return @(@($Items) | Where-Object { ([string]$_).StartsWith($Opening, [System.StringComparison]::Ordinal) }).Count
}
function Get-C1arReading {
    # ONE EVALUATION of -GoalId at this member's fixture, by -Tools, by hand or as the Stop hook, the stub's
    # start marker removed first. What the evaluator SAID: exit, verdict, seconds, decision and reason (the
    # hook's; '' by hand), the instrument_exit0 entry, the artifact, and two keys as Get-WnList reads them
    # ($null where the key is NOT WRITTEN, an empty array where it is written empty). And what the DISK says
    # of the instrument: how many times the stub RAN during it, its start marker, every name under
    # instrument-runs afterwards, and the captures (<...>.stdout.txt) that were not there before.
    # -Env is handed to Invoke-WnEval as it is: variables set for the evaluator's child alone (row (j)'s PATH).
    # TWO CLOCKS. `seconds` is Invoke-WnEval's own figure, and that clock stops when the evaluator's PROCESS
    # ends. `drained` is this function's clock around the same call, which comes back only once the
    # evaluator's stdout and stderr have been READ TO THEIR END -- and a child the evaluator started and left
    # alive inherits both and holds them open until it ends. So a child that was NOT killed shows in
    # `drained` and not in `seconds`.
    param([string]$Tools = 'tree', [string]$GoalId, [switch]$AsStopHook, [hashtable]$Env)
    Clear-WnMarker -Root $script:c1arRoot
    $c1arRanBefore = Get-WnRuns -Root $script:c1arRoot
    $c1arNamesBefore = Get-C1arRunNames
    $c1arEvalArgs = @{ Tools = $Tools; Root = $script:c1arRoot; GoalId = $GoalId }
    if ($AsStopHook) { $c1arEvalArgs['AsStopHook'] = $true }
    if ($null -ne $Env) { $c1arEvalArgs['Env'] = $Env }
    $c1arWallClock = [System.Diagnostics.Stopwatch]::StartNew()
    $c1arEval = Invoke-WnEval @c1arEvalArgs
    $c1arWallClock.Stop()
    $c1arEntry = Get-WnInst -Eval $c1arEval
    $c1arReadsKey = Get-WnList -Eval $c1arEval -Key 'instrument_engine_reads'
    $c1arReusedKey = Get-WnList -Eval $c1arEval -Key 'instrument_captures_reused'
    $c1arNamesAfter = Get-C1arRunNames
    $c1arNewCaptures = @($c1arNamesAfter | Where-Object { ($_ -cmatch '\.stdout\.txt\z') -and ($c1arNamesBefore -cnotcontains $_) })
    return [pscustomobject]@{ tools = $Tools; goal = $GoalId; exit = $c1arEval.exit; verdict = $c1arEval.verdict; seconds = $c1arEval.seconds; drained = [Math]::Round($c1arWallClock.Elapsed.TotalSeconds, 3); decision = $c1arEval.decision; reason = [string]$c1arEval.reason; stdout = $c1arEval.stdout; text = $c1arEval.artifactText
                              found = $c1arEntry.found; ok = $c1arEntry.ok; detail = [string]$c1arEntry.detail; reads = $c1arReadsKey; reused = $c1arReusedKey
                              ran = ((Get-WnRuns -Root $script:c1arRoot) - $c1arRanBefore); marker = (Get-WnMarker -Root $script:c1arRoot); names = $c1arNamesAfter; newCaptures = $c1arNewCaptures }
}
function Get-C1arSaid {
    # What one reading read, as one line for a row's -Said, so a red row explains itself.
    param($Reading)
    return ($Reading.tools + ' ' + $Reading.goal + ': exit ' + $Reading.exit + ', ' + $Reading.verdict + ', ' + $Reading.seconds + ' s; the stub ran ' + $Reading.ran + ', marker [' + $Reading.marker + ']; under instrument-runs [' + (@($Reading.names) -join ', ') +
            ']; instrument_engine_reads ' + (Get-C1arKeySaid -Items $Reading.reads) + '; detail: ' + $Reading.detail)
}
function Get-C1arDockerless {
    # THE PATH ROW (j) GIVES THE EVALUATOR's CHILD, AND WHETHER docker CAN BE REACHED FROM THAT CHILD. It
    # starts no process and changes nothing: this instrument's own environment is not touched.
    # path: four directories and no other -- the system directory, the Windows directory, Windows
    # PowerShell's own, and the one this instrument's `git` is run from -- which is what the evaluator needs
    # to read HEAD and the tree.
    # searched: every directory the process API looks in when that child starts `docker` by its bare name,
    # in its order -- the directory its own powershell.exe was loaded from, its working directory (this
    # instrument's location: Invoke-WnEval hands it on), the system directory, the 16-bit system directory,
    # the Windows directory, and then the PATH above.
    # reachable: every FILE found in one of them under a name a launch of `docker` resolves to (docker.exe)
    # or that a shell would run for it (docker.com, docker.cmd, docker.bat, and the bare name) -- wider than
    # the process API's own search, on purpose. THE CALLER EVALUATES NOTHING WHERE THIS HOLDS ONE.
    $c1arSys = [Environment]::SystemDirectory
    $c1arWin = Split-Path -Parent $c1arSys
    $c1arPsDir = Join-Path $c1arSys 'WindowsPowerShell\v1.0'
    $c1arGitDir = Split-Path -Parent ([string]@(Get-Command git -CommandType Application)[0].Source)
    $c1arPathDirs = @($c1arSys, $c1arWin, $c1arPsDir, $c1arGitDir)
    $c1arSearched = New-Object System.Collections.Generic.List[string]
    foreach ($c1arDir in (@([string]$PSHOME, (Get-Location).ProviderPath, $c1arSys, (Join-Path $c1arWin 'System'), $c1arWin) + $c1arPathDirs)) {
        if ($c1arDir -and (-not $c1arSearched.Contains($c1arDir))) { $c1arSearched.Add($c1arDir) }
    }
    $c1arReachable = New-Object System.Collections.Generic.List[string]
    foreach ($c1arDir in $c1arSearched) {
        foreach ($c1arName in @('docker.exe', 'docker.com', 'docker.cmd', 'docker.bat', 'docker')) {
            $c1arCandidate = Join-Path $c1arDir $c1arName
            if (Test-Path -LiteralPath $c1arCandidate -PathType Leaf) { $c1arReachable.Add($c1arCandidate) }
        }
    }
    return [pscustomobject]@{ path = ($c1arPathDirs -join ';'); searched = $c1arSearched.ToArray(); reachable = $c1arReachable.ToArray() }
}
$c1arM = $null
try {
$c1arInstLines = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
$c1arGoals = [ordered]@{
    'G-WNAR'    = ($c1arInstLines + @('    engine_read: docker_pipe', '    engine_read_fault: pipe_absent'))
    'G-WNAR-B'  = ($c1arInstLines + @('    engine_read: docker_pipe_then_version', '    engine_read_fault: version_exit'))
    'G-WNAR-C'  = ($c1arInstLines + @('    engine_read: docker_pipe_then_version', '    engine_read_fault: version_silent'))
    'G-WNAR-D'  = $c1arInstLines
    'G-WNAR-E1' = ($c1arInstLines + @('    engine_read: docker'))
    'G-WNAR-E2' = ($c1arInstLines + @('    engine_read:'))
    'G-WNAR-F1' = ($c1arInstLines + @('    engine_read_fault: pipe_absent'))
    'G-WNAR-F2' = ($c1arInstLines + @('    engine_read: docker_pipe', '    engine_read_fault: pipe_gone'))
    'G-WNAR-F3' = ($c1arInstLines + @('    engine_read: docker_pipe', '    engine_read_fault: version_exit'))
    'G-WNAR-G'  = ($c1arInstLines + @('    reuse_within_minutes: 30', '    engine_read: docker_pipe', '    engine_read_fault: pipe_absent'))
    'G-WNAR-H'  = ($c1arInstLines + @('    reuse_within_minutes: 30', '    engine_read: docker_pipe'))
    'G-WNAR-I'  = ($c1arInstLines + @('    engine_read: docker_pipe', '    engine_read_fault: pipe_absent', ('  - type: ' + $pwType)))
    # (j) THE TWO GOALS WITH NO FAULT KEY UNDER docker_pipe_then_version: evaluated by row (j)'s child alone.
    'G-WNAR-J1' = ($c1arInstLines + @('    reuse_within_minutes: 30', '    engine_read: docker_pipe_then_version'))
    'G-WNAR-J2' = ($c1arInstLines + @('    engine_read: docker_pipe_then_version'))
    # (k) TWO OF THE REFUSALS OF (e) AND (f), EACH BESIDE A REUSE WINDOW: a value that is no read; a fault with no read.
    'G-WNAR-K1' = ($c1arInstLines + @('    reuse_within_minutes: 30', '    engine_read: nonsense'))
    'G-WNAR-K2' = ($c1arInstLines + @('    reuse_within_minutes: 30', '    engine_read_fault: pipe_absent'))
    # (k) ... AND THE GOAL THAT REUSES BESIDE THEM (BATCH-6 WP-Q): the same window, NO engine key --
    #     G-WNAR-H read the engine first since then, so its outcome followed the host's engine.
    'G-WNAR-K0' = ($c1arInstLines + @('    reuse_within_minutes: 30'))
}
$c1arM = New-WnMission -Tag 'c1ar' -Goals $c1arGoals
if (-not $c1arM.ok) { throw ('FIXTURE REFUSED: ' + $c1arM.why) }
$c1arRoot = $c1arM.root
$c1arRunsDir = $c1arM.runsDir
$c1arInst = Write-WnStub -Root $c1arRoot
Add-C1arRow -Label 'FIXTURE a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/"), inputs/, other/ and the seventeen goals of this member committed in one commit; the stub at scratch\inst.ps1; porcelain reads exactly "?? scratch/"' `
    -Ok ($wnBase.ok -and ((Get-WnPorcelain -Root $c1arRoot) -ceq '?? scratch/') -and ($c1arM.head -cmatch '\A[0-9a-f]{40}\z') -and ($c1arGoals.Count -eq 17) -and (Test-Path -LiteralPath $c1arInst -PathType Leaf)) -Said ('HEAD ' + $c1arM.head + '; ' + $c1arGoals.Count + ' goals; ' + $wnBase.said)
$c1arNotRunLead = 'inst.ps1 NOT RUN: engine down -- '
$c1arNotRun = 'the instrument was NOT run (register row 264).'
$c1arRan0 = 'inst.ps1 exited 0 (require 0). Instrument output kept at '
$c1arReusedLead = 'inst.ps1 exited 0 (require 0). REUSED A FRESH READING, '
$c1arOrdinal = [System.StringComparison]::Ordinal

# (a) THE FALSIFIER: the seam's first fault under the first read. The stub is flagged to sleep 2 s and writes
#     its marker when it STARTS, so a launch cannot be missed -- by the marker, by the counter, by the clock.
Clear-WnCaptures -Root $c1arRoot
Set-WnStubFlag -Root $c1arRoot -Sleep 2
$c1arA = Get-C1arReading -Tools tree -GoalId 'G-WNAR'
Add-C1arRow -Label '(a) FALSIFIER engine_read: docker_pipe + engine_read_fault: pipe_absent, the stub flagged to sleep 2 s: the instrument is NOT LAUNCHED -- its marker ABSENT, its counter unmoved, no capture written --; the entry FAILS, NOT_MET, its detail opening "inst.ps1 NOT RUN: engine down -- FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (pipe_absent): the named pipe \\.\pipe\dockerDesktopLinuxEngine is reported absent" and holding "(engine_read docker_pipe; register row 264)."' `
    -Ok ($c1arA.found -and (-not $c1arA.ok) -and ($c1arA.verdict -ceq 'NOT_MET') -and ($c1arA.marker -ceq '') -and ($c1arA.ran -eq 0) -and ($c1arA.newCaptures.Count -eq 0) -and
         $c1arA.detail.StartsWith('inst.ps1 NOT RUN: engine down -- FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (pipe_absent): the named pipe \\.\pipe\dockerDesktopLinuxEngine is reported absent', $c1arOrdinal) -and
         $c1arA.detail.Contains('(engine_read docker_pipe; register row 264).')) `
    -Said (Get-C1arSaid -Reading $c1arA)
Add-C1arRow -Label '(a) FALSIFIER ... and the artifact says which read was made: instrument_engine_reads holds ONE item, opening "inst.ps1: FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (pipe_absent): "' `
    -Ok (($null -ne $c1arA.reads) -and ($c1arA.reads.Count -eq 1) -and ((Get-C1arOpening -Items $c1arA.reads -Opening 'inst.ps1: FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (pipe_absent): ') -eq 1)) `
    -Said ('tree G-WNAR: instrument_engine_reads ' + (Get-C1arKeySaid -Items $c1arA.reads))
Clear-WnCaptures -Root $c1arRoot
$c1arABase = Get-C1arReading -Tools base -GoalId 'G-WNAR'
Set-WnStubFlag -Root $c1arRoot
Add-C1arRow -Label '(a) BASE CONTROL: the base stores both keys and reads neither -- the stub is LAUNCHED (its marker written, its counter +1, its 2 s slept, its capture on disk): MET, exit 0, the entry "inst.ps1 exited 0", and no instrument_engine_reads key' `
    -Ok (($c1arABase.verdict -ceq 'MET') -and ($c1arABase.exit -eq 0) -and $c1arABase.ok -and ($c1arABase.ran -eq 1) -and [bool]$c1arABase.marker -and ($c1arABase.seconds -ge 2) -and ($c1arABase.newCaptures -ccontains 'G-WNAR.inst.stdout.txt') -and
         $c1arABase.detail.StartsWith($c1arRan0, $c1arOrdinal) -and ($null -eq $c1arABase.reads)) `
    -Said (Get-C1arSaid -Reading $c1arABase)

# (b) THE SECOND READ, ITS CHILD EXITING 1: a stand-in child, never docker -- the fault key says so in the detail.
Clear-WnCaptures -Root $c1arRoot
$c1arB = Get-C1arReading -Tools tree -GoalId 'G-WNAR-B'
Add-C1arRow -Label '(b) FALSIFIER engine_read: docker_pipe_then_version + engine_read_fault: version_exit: NOT RUN -- the stub not launched, no capture written, NOT_MET --; the detail opens "inst.ps1 NOT RUN: engine down -- FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (version_exit): ", holds "a stand-in child ran in place of docker version and did not answer (exit 1)" and "(engine_read docker_pipe_then_version; register row 264)."; an item of instrument_engine_reads opens with the same fault words' `
    -Ok ($c1arB.found -and (-not $c1arB.ok) -and ($c1arB.verdict -ceq 'NOT_MET') -and ($c1arB.marker -ceq '') -and ($c1arB.ran -eq 0) -and ($c1arB.newCaptures.Count -eq 0) -and
         $c1arB.detail.StartsWith($c1arNotRunLead + 'FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (version_exit): ', $c1arOrdinal) -and
         $c1arB.detail.Contains('a stand-in child ran in place of docker version and did not answer (exit 1)') -and $c1arB.detail.Contains('(engine_read docker_pipe_then_version; register row 264).') -and
         ((Get-C1arOpening -Items $c1arB.reads -Opening 'inst.ps1: FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (version_exit): ') -ge 1)) `
    -Said (Get-C1arSaid -Reading $c1arB)

# (c) ... AND ITS CHILD SAYING NOTHING: the bound is the evaluator's own, ten seconds, and the child's tree is killed.
#     THE BOUND IS READ OFF ONE CLOCK AND THE KILL OFF ANOTHER (Get-C1arReading): the evaluator's process lived
#     9 s or more -- it waited its bound --, and its output was read to the end in under 30 s. The stand-in
#     child sleeps 30 s and inherits the evaluator's stdout and stderr: left alive, it holds them open past
#     the thirtieth second, whatever the detail says of its tree.
Clear-WnCaptures -Root $c1arRoot
$c1arC = Get-C1arReading -Tools tree -GoalId 'G-WNAR-C'
Add-C1arRow -Label '(c) FALSIFIER engine_read: docker_pipe_then_version + engine_read_fault: version_silent: NOT RUN -- the stub not launched, no capture written, NOT_MET --; the detail opens with the fault words (version_silent) and holds "a stand-in child ran in place of docker version and did not answer (no answer inside 10 s, its process tree killed)"; the evaluation took 9 s or more, and under 30 s with its output read to the end -- which a stand-in child left alive holds open for its 30 s' `
    -Ok ($c1arC.found -and (-not $c1arC.ok) -and ($c1arC.verdict -ceq 'NOT_MET') -and ($c1arC.marker -ceq '') -and ($c1arC.ran -eq 0) -and ($c1arC.newCaptures.Count -eq 0) -and
         $c1arC.detail.StartsWith($c1arNotRunLead + 'FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (version_silent): ', $c1arOrdinal) -and
         $c1arC.detail.Contains('a stand-in child ran in place of docker version and did not answer (no answer inside 10 s, its process tree killed)') -and $c1arC.detail.Contains('(engine_read docker_pipe_then_version; register row 264).') -and
         ((Get-C1arOpening -Items $c1arC.reads -Opening 'inst.ps1: FAULT INJECTED BY THE GOAL''s engine_read_fault KEY (version_silent): ') -ge 1) -and ($c1arC.seconds -ge 9) -and ($c1arC.drained -lt 30)) `
    -Said ((Get-C1arSaid -Reading $c1arC) + ' | the evaluator''s process lived ' + $c1arC.seconds + ' s; its output was read to the end after ' + $c1arC.drained + ' s')

# (d) THE CONTROL OF WHAT DOES NOT MOVE: no engine_read, no window -- this tree's tools, then the base's, one fixture.
$c1arDCapPath = Join-Path $c1arRunsDir 'G-WNAR-D.inst.stdout.txt'
Clear-WnCaptures -Root $c1arRoot
$c1arD = Get-C1arReading -Tools tree -GoalId 'G-WNAR-D'
$c1arDCap = Read-WnCapture -Path $c1arDCapPath
Clear-WnCaptures -Root $c1arRoot
$c1arDBase = Get-C1arReading -Tools base -GoalId 'G-WNAR-D'
$c1arDBaseCap = Read-WnCapture -Path $c1arDCapPath
$c1arDArtifactsEqual = ([bool]$c1arD.text -and ((Get-WnComparable -Text (Remove-WrProvenanceLine -Text $c1arD.text)) -ceq (Get-WnComparable -Text $c1arDBase.text)))
$c1arDCapturesEqual = ($c1arDCap.ok -and $c1arDBaseCap.ok -and ((Get-WnComparable -Text $c1arDCap.text) -ceq (Get-WnComparable -Text $c1arDBaseCap.text)))
$c1arDStdoutEqual = ($c1arD.stdout.Contains('mission-goal-check: G-WNAR-D -> MET') -and ((Get-WnComparable -Text $c1arD.stdout) -ceq (Get-WnComparable -Text $c1arDBase.stdout)))
Add-C1arRow -Label '(d) CONTROL a goal with NO engine_read (and no window), on this tree''s tools and on the base''s: the stub runs once on each, MET; the two artifacts are equal but for the clock, the two captures are equal but for the clock, the two hand-run stdouts are equal, and neither artifact holds instrument_engine_reads:' `
    -Ok (($c1arD.verdict -ceq 'MET') -and ($c1arDBase.verdict -ceq 'MET') -and ($c1arD.ran -eq 1) -and ($c1arDBase.ran -eq 1) -and $c1arD.detail.StartsWith($c1arRan0, $c1arOrdinal) -and $c1arDArtifactsEqual -and $c1arDCapturesEqual -and $c1arDStdoutEqual -and
         ($null -eq $c1arD.reads) -and ($null -eq $c1arDBase.reads) -and (-not $c1arD.text.Contains('instrument_engine_reads')) -and (-not $c1arDBase.text.Contains('instrument_engine_reads'))) `
    -Said ('artifacts equal: ' + $c1arDArtifactsEqual + '; captures equal: ' + $c1arDCapturesEqual + ' (' + @($c1arDCap.headerKeys).Count + ' and ' + @($c1arDBaseCap.headerKeys).Count + ' header keys); stdouts equal: ' + $c1arDStdoutEqual + ' | ' + (Get-C1arSaid -Reading $c1arD) + ' | ' + (Get-C1arSaid -Reading $c1arDBase))

# (e)/(f) THE TWO KEYS ARE VALIDATED BEFORE ANYTHING IS ASKED OR RUN: five goals, each failing by name.
#     The unknown fault stands beside docker_pipe, never beside docker_pipe_then_version (this member's own rule,
#     above: no row causes a docker command); the spec lists that refusal ahead of "does not apply", and so it is read.
$c1arRefusals = @(
    @{ row = '(e)'; goal = 'G-WNAR-E1'; what = 'an UNKNOWN value, engine_read: docker'; want = @('is not a read this evaluator makes (docker_pipe, docker_pipe_then_version): the instrument was NOT run (register row 264).', "'docker'") }
    @{ row = '(e)'; goal = 'G-WNAR-E2'; what = 'an EMPTY value, engine_read: with nothing after the colon'; want = @('is not a read this evaluator makes (docker_pipe, docker_pipe_then_version): the instrument was NOT run (register row 264).') }
    @{ row = '(f)'; goal = 'G-WNAR-F1'; what = 'engine_read_fault: pipe_absent WITHOUT engine_read'; want = @('declares engine_read_fault without engine_read', $c1arNotRun) }
    @{ row = '(f)'; goal = 'G-WNAR-F2'; what = 'an UNKNOWN fault, engine_read: docker_pipe + engine_read_fault: pipe_gone (a value that is none of the three is refused as UNKNOWN, ahead of the question whether it applies to the read)'; want = @('is not a fault this evaluator injects', "'pipe_gone'", $c1arNotRun) }
    @{ row = '(f)'; goal = 'G-WNAR-F3'; what = 'a fault that does not apply, engine_read: docker_pipe + engine_read_fault: version_exit'; want = @('does not apply to engine_read docker_pipe', "'version_exit'", $c1arNotRun) }
)
foreach ($c1arCase in $c1arRefusals) {
    Clear-WnCaptures -Root $c1arRoot
    $c1arR = Get-C1arReading -Tools tree -GoalId $c1arCase.goal
    $c1arMissing = @($c1arCase.want | Where-Object { -not $c1arR.detail.Contains($_) })
    Add-C1arRow -Label ($c1arCase.row + ' FALSIFIER ' + $c1arCase.what + ': the detector FAILS BY NAME, NOT_MET, the stub NOT run (its marker absent, its counter unmoved); the detail holds "' + ($c1arCase.want -join '" and "') + '"') `
        -Ok ($c1arR.found -and (-not $c1arR.ok) -and ($c1arR.verdict -ceq 'NOT_MET') -and ($c1arR.marker -ceq '') -and ($c1arR.ran -eq 0) -and ($c1arMissing.Count -eq 0)) `
        -Said ((Get-C1arSaid -Reading $c1arR) + $(if ($c1arMissing.Count -gt 0) { ' | NOT in the detail: "' + ($c1arMissing -join '" and "') + '"' } else { '' }))
}

# (g)/(h) ONE GREEN CAPTURE, TAKEN BY HAND AT HEAD WITH THE BASE's HELPER, stands alone under instrument-runs:
#     every condition of a reuse holds for it inside a 30-minute window.
Clear-WnCaptures -Root $c1arRoot
Set-WnStubFlag -Root $c1arRoot
$c1arHand = New-WnCapture -Tools base -Root $c1arRoot -Key 'HAND'
$c1arHandCited = $c1arHand.path + ' sha256 ' + $c1arHand.sha256
Add-C1arRow -Label 'FIXTURE for (g) and (h): one capture of the stub taken by hand (the base''s Save-LamInstrumentRun, run key HAND) -- exit 0, head HEAD, tree_clean True, seconds old; the tree still reads "?? scratch/"' `
    -Ok ($c1arHand.ok -and ($c1arHand.exit -eq 0) -and ($c1arHand.header['exit_code'] -ceq '0') -and ($c1arHand.header['head'] -ceq $c1arM.head) -and ($c1arHand.header['tree_clean'] -ceq 'True') -and ((Get-WnHead -Root $c1arRoot) -ceq $c1arM.head) -and ((Get-WnPorcelain -Root $c1arRoot) -ceq '?? scratch/')) `
    -Said ('ok ' + $c1arHand.ok + ' [' + $c1arHand.why + ']; ' + $c1arHandCited + '; captured_at ' + [string]$c1arHand.header['captured_at'])
# (g) A FAULT KEY ASKS NO REUSE QUESTION.
$c1arG = Get-C1arReading -Tools tree -GoalId 'G-WNAR-G'
$c1arGHandNow = Read-WnCapture -Path $c1arHand.path
$c1arGHandSame = ($c1arGHandNow.ok -and ($c1arGHandNow.sha256 -ceq $c1arHand.sha256))
Add-C1arRow -Label '(g) FALSIFIER reuse_within_minutes: 30 + engine_read: docker_pipe + engine_read_fault: pipe_absent, that capture reusable: NO reuse question is asked -- NOT reused and NOT RUN: the entry FAILS, its detail opening "inst.ps1 NOT RUN: engine down -- ", NOT_MET, instrument_captures_reused written EMPTY, the stub not launched, no capture written, the hand capture as it was' `
    -Ok ($c1arG.found -and (-not $c1arG.ok) -and ($c1arG.verdict -ceq 'NOT_MET') -and ($c1arG.marker -ceq '') -and ($c1arG.ran -eq 0) -and ($c1arG.newCaptures.Count -eq 0) -and $c1arG.detail.StartsWith($c1arNotRunLead, $c1arOrdinal) -and
         ($null -ne $c1arG.reused) -and ($c1arG.reused.Count -eq 0) -and $c1arGHandSame) `
    -Said ((Get-C1arSaid -Reading $c1arG) + ' | instrument_captures_reused ' + (Get-C1arKeySaid -Items $c1arG.reused) + '; new captures [' + (@($c1arG.newCaptures) -join ', ') + ']; the hand capture unchanged: ' + $c1arGHandSame + ' (sha256 ' + $c1arGHandNow.sha256 + ')')
# WHATEVER THAT READING ADDED under instrument-runs IS REMOVED before the base is asked: the base control and
# (h) stand on the hand capture ALONE, whatever this tree did. (Before the cure the tree reuses and adds the
# kept copy, which the base then writes again; after it nothing is added. A tree that RAN the stub there would
# leave a newer capture, and the base would reuse that one -- a control gone red for what the tree did.)
foreach ($c1arLeft in @($c1arG.newCaptures)) { Remove-Item -LiteralPath (Join-Path $c1arRunsDir $c1arLeft) -Force }
$c1arGBase = Get-C1arReading -Tools base -GoalId 'G-WNAR-G'
Add-C1arRow -Label '(g) BASE CONTROL: the base reads neither key and asks its reuse question -- the capture is REUSED: MET, exit 0, the stub not run, the detail opening "inst.ps1 exited 0 (require 0). REUSED A FRESH READING, ", instrument_captures_reused naming the hand capture by path and sha256' `
    -Ok (($c1arGBase.verdict -ceq 'MET') -and ($c1arGBase.exit -eq 0) -and $c1arGBase.ok -and ($c1arGBase.ran -eq 0) -and ($c1arGBase.marker -ceq '') -and $c1arGBase.detail.StartsWith($c1arReusedLead, $c1arOrdinal) -and
         ($null -ne $c1arGBase.reused) -and ($c1arGBase.reused.Count -eq 1) -and ($c1arGBase.reused[0] -ceq $c1arHandCited)) `
    -Said ((Get-C1arSaid -Reading $c1arGBase) + ' | instrument_captures_reused ' + (Get-C1arKeySaid -Items $c1arGBase.reused))
# (h) engine_read ALONE. Until BATCH-6 WP-Q the reuse question came first and a reuse made no read (both
#     rows STATED so, the second a FALSIFIER: instrument_engine_reads present and EMPTY). RE-ASSERTED
#     (BATCH-6 WP-Q (a); the operator's ruling (b) of 21:49 local): the read is made FIRST, before any reuse
#     decision, and the outcome follows it -- this tree's one item says which way it went, and the row holds the
#     outcome to that item: the pipe present, the capture REUSED as at the base; ABSENT, NOT RUN, nothing reused.
#     The base reads no engine key and reuses, as it did.
$c1arH = Get-C1arReading -Tools tree -GoalId 'G-WNAR-H'
$c1arHBase = Get-C1arReading -Tools base -GoalId 'G-WNAR-H'
$c1arHPipe = ''
if (($null -ne $c1arH.reads) -and (@($c1arH.reads).Count -eq 1)) {
    $c1arHPipeM = [regex]::Match([string]@($c1arH.reads)[0], '^inst\.ps1: docker_pipe \\\\\.\\pipe\\dockerDesktopLinuxEngine (present|ABSENT) \(\d+ named pipes, [0-9.]+ s\)$')
    if ($c1arHPipeM.Success) { $c1arHPipe = $c1arHPipeM.Groups[1].Value }
}
$c1arHTreeOk = $false
if ($c1arHPipe -ceq 'present') {
    $c1arHTreeOk = (($c1arH.verdict -ceq 'MET') -and $c1arH.ok -and ($c1arH.ran -eq 0) -and ($c1arH.marker -ceq '') -and $c1arH.detail.StartsWith($c1arReusedLead, $c1arOrdinal) -and ($null -ne $c1arH.reused) -and ($c1arH.reused.Count -eq 1) -and ($c1arH.reused[0] -ceq $c1arHandCited))
} elseif ($c1arHPipe -ceq 'ABSENT') {
    $c1arHTreeOk = (($c1arH.verdict -ceq 'NOT_MET') -and (-not $c1arH.ok) -and ($c1arH.ran -eq 0) -and ($c1arH.marker -ceq '') -and $c1arH.detail.StartsWith($c1arNotRunLead, $c1arOrdinal) -and ($null -ne $c1arH.reused) -and ($c1arH.reused.Count -eq 0))
}
Add-C1arRow -Label '(h) RE-ASSERTED BY BATCH-6 WP-Q: engine_read: docker_pipe ALONE beside reuse_within_minutes: 30 and that capture: at the base the reuse question is asked and the capture REUSED -- MET, the stub not run, the capture named by path and sha256 --; at this tree THE READ IS MADE FIRST, before any reuse decision, and the outcome follows it: the pipe present, the capture REUSED as at the base; the pipe ABSENT, NOT RUN and nothing reused -- the stub not run either way' `
    -Ok ($c1arHTreeOk -and ($c1arHBase.verdict -ceq 'MET') -and $c1arHBase.ok -and ($c1arHBase.ran -eq 0) -and $c1arHBase.detail.StartsWith($c1arReusedLead, $c1arOrdinal) -and ($null -ne $c1arHBase.reused) -and ($c1arHBase.reused.Count -eq 1) -and ($c1arHBase.reused[0] -ceq $c1arHandCited)) `
    -Said ('the pipe, as this tree''s one item has it: ' + $(if ($c1arHPipe) { $c1arHPipe } else { '(no such item)' }) + ' | ' + (Get-C1arSaid -Reading $c1arH) + ' | ' + (Get-C1arSaid -Reading $c1arHBase))
Add-C1arRow -Label '(h) RE-ASSERTED BY BATCH-6 WP-Q ... and this tree''s artifact carries instrument_engine_reads with EXACTLY ONE item, the read made before the reuse question: "inst.ps1: docker_pipe \\.\pipe\dockerDesktopLinuxEngine present|ABSENT (<n> named pipes, <s> s)" (until then: present and EMPTY, a reuse making no read)' `
    -Ok (($c1arHPipe -ceq 'present') -or ($c1arHPipe -ceq 'ABSENT')) `
    -Said ('tree G-WNAR-H: ' + $c1arH.verdict + ', the stub ran ' + $c1arH.ran + '; instrument_engine_reads ' + (Get-C1arKeySaid -Items $c1arH.reads))

# (i) HOOK MODE, the detector listed ahead of an arm that admits the stop (the form of C-1x (i) and C-1af (h)):
#     the arm is evaluated first, the instrument_exit0 detector is never invoked -- nothing is validated, read or run.
Clear-WnCaptures -Root $c1arRoot
$c1arPlaced = Join-Path $c1arRoot '.mission\amendments\AM-964-c1ar.yaml'
Write-Utf8 -Path $c1arPlaced -Text "id: AM-964-c1ar`nnote: placed by WP-3 C-1ar -- untracked, awaiting its gate`n"
$c1arI = Get-C1arReading -Tools tree -GoalId 'G-WNAR-I' -AsStopHook
$c1arIBase = Get-C1arReading -Tools base -GoalId 'G-WNAR-I' -AsStopHook
Remove-Item -LiteralPath $c1arPlaced -Force
$c1arITypes = @(Get-PwDetectorTypes -Text $c1arI.text)
$c1arIBaseTypes = @(Get-PwDetectorTypes -Text $c1arIBase.text)
Add-C1arRow -Label ('(i) CONTROL as the Stop hook, engine_read: docker_pipe + the pipe_absent fault on a detector listed AHEAD of the ' + $pwType + ' arm, which admits the stop: the arm is listed FIRST and the hook APPROVES (' + $pwVerdict + '), short_circuited 1; the instrument_exit0 entry reads "NOT EVALUATED -- hook-mode short-circuit", the stub''s marker absent, its counter unmoved, no capture written -- on this tree''s tools as on the base''s') `
    -Ok (($c1arI.decision -ceq 'approve') -and ($c1arI.exit -eq 0) -and ($c1arI.verdict -ceq $pwVerdict) -and ($c1arITypes.Count -eq 2) -and ($c1arITypes[0] -ceq $pwType) -and ($c1arI.text -cmatch '(?m)^short_circuited: 1\b') -and $c1arI.found -and (-not $c1arI.ok) -and
         $c1arI.detail.StartsWith('NOT EVALUATED -- hook-mode short-circuit', $c1arOrdinal) -and ($c1arI.marker -ceq '') -and ($c1arI.ran -eq 0) -and ($c1arI.newCaptures.Count -eq 0) -and
         ($c1arIBase.decision -ceq 'approve') -and ($c1arIBase.exit -eq 0) -and ($c1arIBase.verdict -ceq $pwVerdict) -and ($c1arIBaseTypes.Count -eq 2) -and ($c1arIBaseTypes[0] -ceq $pwType) -and ($c1arIBase.text -cmatch '(?m)^short_circuited: 1\b') -and $c1arIBase.found -and (-not $c1arIBase.ok) -and
         $c1arIBase.detail.StartsWith('NOT EVALUATED -- hook-mode short-circuit', $c1arOrdinal) -and ($c1arIBase.marker -ceq '') -and ($c1arIBase.ran -eq 0) -and ($c1arIBase.newCaptures.Count -eq 0)) `
    -Said ('tree: decision ' + $c1arI.decision + ', artifact order [' + ($c1arITypes -join ', ') + '] | ' + (Get-C1arSaid -Reading $c1arI) + ' | base: decision ' + $c1arIBase.decision + ', artifact order [' + ($c1arIBaseTypes -join ', ') + '] | ' + (Get-C1arSaid -Reading $c1arIBase))

# (j) AN UNFAULTED DOWN, AND ITS TAIL (the independent validator's round 1). Two goals with no fault
#     key under docker_pipe_then_version, each evaluated by a child on the PATH of Get-C1arDockerless and by
#     no other: `docker version` cannot be started there, so the read answers DOWN -- at the pipe where the
#     host's engine is down, at the version step where it is up -- and no docker process runs either way.
#     NOTHING IS EVALUATED where a docker executable can be reached from that child: the three rows read
#     MISMATCH and say what was found. instrument-runs is emptied before each reading and the stub is GREEN
#     and prompt, so nothing is reusable and a launch would show in its marker and its counter.
#     (j1) the goal with a window: until BATCH-6 WP-Q the reuse question was asked FIRST and answered no
#          -- no capture on disk -- and the instrument then NOT launched, the detail's tail saying so in the
#          decision's own reason. RE-ASSERTED (BATCH-6 WP-Q): the read comes first and answers
#          DOWN, so NO reuse question is asked -- the tail says that, in the ruling's words, and neither the
#          decision's lead nor its reason -- and the detail still must not say "the instrument was run".
#     (j2) the goal without one: THE UNFAULTED DOWN ITSELF, the first row of this batch to read one -- the
#          detail ends at the engine read's closing tag and the reads are the engine's own, no fault named.
#     (j3) (j1)'s goal as the Stop hook: the block reason carries the detail.
$c1arJ1Label = '(j) FALSIFIER (j1) RE-ASSERTED BY BATCH-6 WP-Q: AN UNFAULTED DOWN BESIDE A WINDOW: reuse_within_minutes: 30 + engine_read: docker_pipe_then_version, NO fault key, nothing reusable on disk, the evaluator''s child on a PATH from which no docker executable is reached: the read is made FIRST and answers DOWN, so NO reuse question is asked and the instrument is NOT LAUNCHED -- the entry FAILS, NOT_MET, the stub''s counter unmoved, its marker absent, no capture written --; the detail opens "inst.ps1 NOT RUN: engine down -- " and DOES NOT HOLD "the instrument was run"; it ENDS "(engine_read docker_pipe_then_version; register row 264). reuse_within_minutes 30: no reuse question was asked -- the engine read answered down before any reuse decision (register row 438)." and holds neither "NOT reused, and the instrument was not launched" nor the decision''s reason "no capture of this instrument is on disk under"'
$c1arJ2Label = '(j) CONTROL (j2) THE UNFAULTED DOWN ITSELF, the same goal WITHOUT a window (engine_read: docker_pipe_then_version alone, NO fault key), the same child: NOT RUN -- the entry FAILS, NOT_MET, the stub not launched, no capture written --; the detail opens "inst.ps1 NOT RUN: engine down -- ", ENDS "(engine_read docker_pipe_then_version; register row 264)." and holds no "reuse_within_minutes"; instrument_engine_reads holds the read as it was made -- the pipe item, and where the pipe is present a second item opening "inst.ps1: docker version did not answer: it could not be started: " -- and neither the detail nor an item names a FAULT INJECTED'
$c1arJ3Label = '(j) FALSIFIER (j3) AS THE STOP HOOK, the goal of (j1), the same child: the hook BLOCKS, exit 0, NOT_MET, the stub not launched, no capture written; the reason carries "inst.ps1 NOT RUN: engine down -- " and DOES NOT HOLD "the instrument was run"'
$c1arJ = Get-C1arDockerless
if ($c1arJ.reachable.Count -gt 0) {
    $c1arJRefused = 'REFUSED, NOTHING EVALUATED: a docker executable can be reached from the child this row would start -- ' + ($c1arJ.reachable -join ', ') + ' -- so no evaluation was made and no docker command was run | the PATH built: ' + $c1arJ.path + ' | searched: ' + ($c1arJ.searched -join ', ')
    foreach ($c1arJLabel in @($c1arJ1Label, $c1arJ2Label, $c1arJ3Label)) { Add-C1arRow -Label $c1arJLabel -Ok $false -Said $c1arJRefused }
} else {
    $c1arJEnv = @{ PATH = $c1arJ.path }
    $c1arJRunWords = 'the instrument was run'
    $c1arJNotLaunched = 'reuse_within_minutes 30: NOT reused, and the instrument was not launched (register row 368) -- '
    $c1arJNoCapture = 'no capture of this instrument is on disk under '
    $c1arJClose = '(engine_read docker_pipe_then_version; register row 264).'
    $c1arJPipeItem = 'inst.ps1: docker_pipe \\.\pipe\dockerDesktopLinuxEngine '
    Clear-WnCaptures -Root $c1arRoot
    Set-WnStubFlag -Root $c1arRoot
    $c1arJ1 = Get-C1arReading -Tools tree -GoalId 'G-WNAR-J1' -Env $c1arJEnv
    # THE TAIL, IN ITS ORDER: the read's closing words, then the ruling's words, and nothing after
    # them -- neither the decision's lead nor its reason, for no reuse question was asked.
    $c1arJNoQuestion = ' reuse_within_minutes 30: no reuse question was asked -- the engine read answered down before any reuse decision (register row 438).'
    $c1arJ1CloseAt = $c1arJ1.detail.IndexOf($c1arJClose, $c1arOrdinal)
    $c1arJ1NoteAt = if ($c1arJ1CloseAt -ge 0) { $c1arJ1.detail.IndexOf($c1arJNotLaunched, $c1arJ1CloseAt, $c1arOrdinal) } else { -1 }
    $c1arJ1WhyAt = $c1arJ1.detail.IndexOf($c1arJNoCapture, $c1arOrdinal)
    Add-C1arRow -Label $c1arJ1Label `
        -Ok ($c1arJ1.found -and (-not $c1arJ1.ok) -and ($c1arJ1.verdict -ceq 'NOT_MET') -and ($c1arJ1.marker -ceq '') -and ($c1arJ1.ran -eq 0) -and ($c1arJ1.newCaptures.Count -eq 0) -and
             $c1arJ1.detail.StartsWith($c1arNotRunLead, $c1arOrdinal) -and (-not $c1arJ1.detail.Contains('FAULT INJECTED')) -and (-not $c1arJ1.detail.Contains($c1arJRunWords)) -and
             ($c1arJ1CloseAt -ge 0) -and $c1arJ1.detail.EndsWith($c1arJClose + $c1arJNoQuestion, $c1arOrdinal) -and ($c1arJ1NoteAt -lt 0) -and ($c1arJ1WhyAt -lt 0)) `
        -Said ((Get-C1arSaid -Reading $c1arJ1) + ' | "' + $c1arJRunWords + '" in the detail: ' + $c1arJ1.detail.Contains($c1arJRunWords) + ' | the child''s PATH: ' + $c1arJ.path + ' | docker executables reached from it: ' + $c1arJ.reachable.Count + ', in ' + $c1arJ.searched.Count + ' directories searched')
    Clear-WnCaptures -Root $c1arRoot
    $c1arJ2 = Get-C1arReading -Tools tree -GoalId 'G-WNAR-J2' -Env $c1arJEnv
    # THE READ AS IT WAS MADE, by what its first item says of the pipe: present -- a second item, the launch
    # that could not be started --; ABSENT -- that item alone, and the launch was never tried.
    $c1arJ2Items = @()
    if ($null -ne $c1arJ2.reads) { $c1arJ2Items = @($c1arJ2.reads) }
    $c1arJ2PipeSaid = if (($c1arJ2Items.Count -ge 1) -and ([string]$c1arJ2Items[0]).StartsWith($c1arJPipeItem, $c1arOrdinal)) { ([string]$c1arJ2Items[0]).Substring($c1arJPipeItem.Length) } else { '' }
    $c1arJ2Read = $false
    if ($c1arJ2PipeSaid.StartsWith('present (', $c1arOrdinal)) {
        $c1arJ2Read = (($c1arJ2Items.Count -eq 2) -and ([string]$c1arJ2Items[1]).StartsWith('inst.ps1: docker version did not answer: it could not be started: ', $c1arOrdinal) -and
                       $c1arJ2.detail.Contains('the named pipe \\.\pipe\dockerDesktopLinuxEngine is present and docker version did not answer (it could not be started: '))
    } elseif ($c1arJ2PipeSaid.StartsWith('ABSENT (', $c1arOrdinal)) {
        $c1arJ2Read = (($c1arJ2Items.Count -eq 1) -and $c1arJ2.detail.Contains('the named pipe \\.\pipe\dockerDesktopLinuxEngine is not among the '))
    }
    Add-C1arRow -Label $c1arJ2Label `
        -Ok ($c1arJ2.found -and (-not $c1arJ2.ok) -and ($c1arJ2.verdict -ceq 'NOT_MET') -and ($c1arJ2.marker -ceq '') -and ($c1arJ2.ran -eq 0) -and ($c1arJ2.newCaptures.Count -eq 0) -and
             $c1arJ2.detail.StartsWith($c1arNotRunLead, $c1arOrdinal) -and $c1arJ2.detail.EndsWith($c1arJClose, $c1arOrdinal) -and (-not $c1arJ2.detail.Contains('reuse_within_minutes')) -and (-not $c1arJ2.detail.Contains('FAULT INJECTED')) -and
             $c1arJ2Read -and (@($c1arJ2Items | Where-Object { ([string]$_).Contains('FAULT INJECTED') }).Count -eq 0)) `
        -Said ((Get-C1arSaid -Reading $c1arJ2) + ' | the pipe, as the first item has it: ' + $(if ($c1arJ2PipeSaid) { $c1arJ2PipeSaid } else { '(no pipe item)' }))
    Clear-WnCaptures -Root $c1arRoot
    $c1arJ3 = Get-C1arReading -Tools tree -GoalId 'G-WNAR-J1' -AsStopHook -Env $c1arJEnv
    Add-C1arRow -Label $c1arJ3Label `
        -Ok (($c1arJ3.decision -ceq 'block') -and ($c1arJ3.exit -eq 0) -and ($c1arJ3.verdict -ceq 'NOT_MET') -and ($c1arJ3.marker -ceq '') -and ($c1arJ3.ran -eq 0) -and ($c1arJ3.newCaptures.Count -eq 0) -and
             $c1arJ3.reason.Contains($c1arNotRunLead) -and (-not $c1arJ3.reason.Contains($c1arJRunWords))) `
        -Said ((Get-C1arSaid -Reading $c1arJ3) + ' | the hook says ' + $(if ($c1arJ3.decision) { $c1arJ3.decision } else { '(no decision)' }) + ' | "' + $c1arJRunWords + '" in the reason: ' + $c1arJ3.reason.Contains($c1arJRunWords) + ' | reason: ' + $c1arJ3.reason)
}

# (k) THE ENGINE's KEYS ARE REFUSED BEFORE THE REUSE QUESTION (the independent validator's round 3).
#     The goals of (e) and (f) declare no window, so none of their rows tells keys that are held to their
#     rule at the head of the arm from keys held to it only where nothing is asked of a capture. Here ONE
#     GREEN capture of the stub, taken by hand at HEAD by this tree's helper, stands alone inside a 30-minute
#     window, and it IS reusable: G-WNAR-K0 -- the same window and NO engine key (formerly
#     G-WNAR-H, `engine_read: docker_pipe` spelled right; RE-POINTED BY BATCH-6 WP-Q, since a goal that declares
#     engine_read now reads the engine first and its reuse follows the host's engine) -- reuses it, read AFTER
#     the two goals below so that no kept copy stands before them. Beside that capture
#     `engine_read: nonsense` and a fault key with no engine_read must each still FAIL by name: nothing
#     reused, nothing kept, nothing run. CONTROLS BOTH: the evaluator read them ok when they were written.
#     The wrong cure the first holds was driven by the validator's mutation run, not by us -- engine_read
#     held to its two values only where no window is declared -- and every row then standing read ok over
#     it; the second shape the validator drove by hand beside a reusable capture. No row here causes a docker
#     command: `nonsense` is refused before any read, and where it were not, a reuse makes none.
Clear-WnCaptures -Root $c1arRoot
Set-WnStubFlag -Root $c1arRoot
$c1arKHand = New-WnCapture -Tools tree -Root $c1arRoot -Key 'HAND'
$c1arKCited = [string]$c1arKHand.path + ' sha256 ' + [string]$c1arKHand.sha256
$c1arKCases = @(
    @{ goal = 'G-WNAR-K1'; what = 'engine_read: nonsense -- a value that is no read this evaluator makes'; want = @('instrument_exit0''s engine_read ''nonsense'' is not a read this evaluator makes (docker_pipe, docker_pipe_then_version): the instrument was NOT run (register row 264).')
       cure = 'a cure that held engine_read to its two values only where no window is declared would reuse the capture here' }
    @{ goal = 'G-WNAR-K2'; what = 'engine_read_fault: pipe_absent with NO engine_read beside it'; want = @('instrument_exit0 declares engine_read_fault without engine_read: the instrument was NOT run (register row 264).')
       cure = 'a cure that refused a fault key without its read only where no window is declared would launch here' }
)
foreach ($c1arKCase in $c1arKCases) {
    $c1arKCase.before = (Get-C1arRunNames) -join ', '
    $c1arKCase.reading = Get-C1arReading -Tools tree -GoalId $c1arKCase.goal
    $c1arKCase.after = (@($c1arKCase.reading.names) -join ', ')
    $c1arKCase.handNow = Read-WnCapture -Path $c1arKHand.path
}
$c1arKCtl = Get-C1arReading -Tools tree -GoalId 'G-WNAR-K0'
$c1arKReusable = ($c1arKHand.ok -and ($c1arKHand.exit -eq 0) -and ($c1arKCtl.verdict -ceq 'MET') -and $c1arKCtl.ok -and ($c1arKCtl.ran -eq 0) -and $c1arKCtl.detail.StartsWith($c1arReusedLead, $c1arOrdinal) -and
                  ($null -ne $c1arKCtl.reused) -and ($c1arKCtl.reused.Count -eq 1) -and ($c1arKCtl.reused[0] -ceq $c1arKCited))
foreach ($c1arKCase in $c1arKCases) {
    $c1arK = $c1arKCase.reading
    $c1arKMissing = @($c1arKCase.want | Where-Object { -not $c1arK.detail.Contains($_) })
    Add-C1arRow -Label ('(k) CONTROL REFUSED BEFORE THE REUSE QUESTION, reuse_within_minutes: 30 + ' + $c1arKCase.what + ', ONE reusable GREEN capture of the stub standing alone inside the window (G-WNAR-K0 -- the same window, no engine key; re-pointed from G-WNAR-H by BATCH-6 WP-Q -- read after, REUSES it): the detector FAILS BY NAME, NOT_MET -- the detail holds "' + ($c1arKCase.want -join '" and "') + '" --, the stub NOT run (its marker absent, its counter unmoved), NOTHING reused -- instrument_captures_reused names no capture, no kept copy is written, the names under instrument-runs and the capture''s bytes what they were; ' + $c1arKCase.cure + ' (the independent validator''s round 3)') `
        -Ok ($c1arKReusable -and $c1arK.found -and (-not $c1arK.ok) -and ($c1arK.verdict -ceq 'NOT_MET') -and ($c1arK.marker -ceq '') -and ($c1arK.ran -eq 0) -and ($c1arK.newCaptures.Count -eq 0) -and ($c1arKMissing.Count -eq 0) -and
             (($null -eq $c1arK.reused) -or ($c1arK.reused.Count -eq 0)) -and ($c1arKCase.after -ceq $c1arKCase.before) -and $c1arKCase.handNow.ok -and ($c1arKCase.handNow.sha256 -ceq $c1arKHand.sha256)) `
        -Said ((Get-C1arSaid -Reading $c1arK) + ' | instrument_captures_reused ' + (Get-C1arKeySaid -Items $c1arK.reused) + '; names before [' + $c1arKCase.before + ']; the hand capture unchanged: ' + ($c1arKCase.handNow.sha256 -ceq $c1arKHand.sha256) +
               $(if ($c1arKMissing.Count -gt 0) { ' | NOT in the detail: "' + ($c1arKMissing -join '" and "') + '"' } else { '' }) + ' | the capture was reusable: ' + $c1arKReusable + ' -- ' + (Get-C1arSaid -Reading $c1arKCtl) + '; instrument_captures_reused ' + (Get-C1arKeySaid -Items $c1arKCtl.reused))
}

# (l) THE BOUNDED LAUNCH's ANSWER, THE ROUTINE LIFTED ALONE (the form of C-1ah (m) and C-1as (d): one function
#     taken from this tree's evaluator by its AST and run by itself, nothing else of the file). Under
#     docker_pipe_then_version the engine is UP only where the child EXITS 0 AND ITS FIRST LINE IS NOT EMPTY.
#     The seam's two stand-ins exit 1 or outlive the bound, and rows (j) cannot start a child at all: so no
#     row above hands the routine a child that exits 0 and says nothing, and a cure that took an exit of 0
#     for an answer read every one of them ok -- found by the builder's own mutation sweep after the
#     independent validator's round 3, and held here. The child is a stand-in of this member's own,
#     `powershell -Command "<one statement>"`, never docker. A CONTROL: the evaluator read it ok when it was
#     written. (At the base there is no such routine: nothing to lift, and no base control.)
$c1arLTok = $null
$c1arLErr = $null
$c1arLAst = [System.Management.Automation.Language.Parser]::ParseFile($goalCheck, [ref]$c1arLTok, [ref]$c1arLErr)
$c1arLFns = @($c1arLAst.FindAll({ param($c1arLNode) ($c1arLNode -is [System.Management.Automation.Language.FunctionDefinitionAst]) -and ($c1arLNode.Name -ceq 'Invoke-InstrumentEngineChild') }, $true))
$c1arLCases = @(
    @{ what = 'exits 0 and prints NOTHING'; command = 'exit 0'; answered = $false; text = ''; why = 'it printed nothing' }
    @{ what = 'prints a line and exits 3'; command = 'Write-Output 29.5.2; exit 3'; answered = $false; text = ''; why = 'exit 3' }
    @{ what = 'prints a line and exits 0'; command = 'Write-Output 29.5.2'; answered = $true; text = '29.5.2'; why = '' }
)
$c1arLSaid = New-Object System.Collections.Generic.List[string]
$c1arLGood = ($c1arLFns.Count -eq 1)
if ($c1arLFns.Count -eq 1) {
    $c1arLBlock = [scriptblock]::Create('param($c1arLArgs)' + "`n" + $c1arLFns[0].Extent.Text + "`n" + 'Invoke-InstrumentEngineChild @c1arLArgs')
    foreach ($c1arLCase in $c1arLCases) {
        $c1arLOut = $null
        $c1arLThrew = ''
        try { $c1arLOut = @(& $c1arLBlock @{ FileName = 'powershell'; Arguments = ('-NoProfile -NonInteractive -Command "' + $c1arLCase.command + '"') })[0] }
        catch { $c1arLOut = $null; $c1arLThrew = (([string]$_.Exception.Message) -replace '[\r\n]+', ' ') }
        if (($null -eq $c1arLOut) -or ([bool]$c1arLOut.answered -ne $c1arLCase.answered) -or ([string]$c1arLOut.text -cne $c1arLCase.text) -or ([string]$c1arLOut.why -cne $c1arLCase.why)) { $c1arLGood = $false }
        $c1arLSaid.Add('a child that ' + $c1arLCase.what + ' (' + $c1arLCase.command + '): ' + $(if ($null -eq $c1arLOut) { 'THE ROUTINE THREW: ' + $c1arLThrew } else { 'answered ' + [bool]$c1arLOut.answered + ', text [' + [string]$c1arLOut.text + '], why [' + [string]$c1arLOut.why + ']' }))
    }
}
Add-C1arRow -Label '(l) CONTROL THE BOUNDED LAUNCH''s ANSWER, the routine Invoke-InstrumentEngineChild LIFTED ALONE from this tree''s evaluator by its AST and handed a stand-in child of this member''s own (powershell, never docker): a child that exits 0 and prints NOTHING has NOT answered -- "it printed nothing" --; one that prints a line and exits 3 has not -- "exit 3" --; one that prints a line and exits 0 HAS, its first line the text; an exit of 0 ALONE is no answer -- a cure that took it for one would launch the instrument into an engine that said nothing, and no seam fault stands such a child (the builder''s own mutation sweep after the independent validator''s round 3)' `
    -Ok $c1arLGood -Said ('Invoke-InstrumentEngineChild defined ' + $c1arLFns.Count + ' time(s) in this tree''s evaluator | ' + ($c1arLSaid -join ' | '))
}
catch {
    $c1arOk = $false
    $c1arRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1arRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1arM) { Remove-PwTreeAsWritten -Base $c1arM.base }
Check -Id 'C-1ar' -Title 'THE ENGINE READ, DOWN (the operator''s ruling 10 and rulings D5 and D6 of 2026-10-11): at the base evaluator an instrument_exit0 detector that declares engine_read and engine_read_fault has both keys stored and neither read -- the instrument is launched, MET; at this tree, the goal''s own seam reporting the engine down, the instrument is NOT LAUNCHED -- its marker absent, its counter unmoved, no capture written -- and the detector fails "inst.ps1 NOT RUN: engine down -- ..." naming the read and the fault, instrument_engine_reads listing the read that was made: under docker_pipe the named pipe reported absent; under docker_pipe_then_version a stand-in child in place of docker version that exits 1, and one that says nothing and is killed with its tree at the 10 s bound; an engine_read value this evaluator does not make, the empty one among them, a fault with no read beside it, a fault it does not inject and a fault that does not apply to the read each FAIL the detector by name, and nothing is launched; a detector carrying the fault key asks no reuse question -- a reusable GREEN capture inside the window is not reused, where the base reuses it; engine_read alone beside a window -- RE-ASSERTED by BATCH-6 WP-Q, where it reused that capture and made no read -- is READ FIRST, before any reuse decision, instrument_engine_reads holding that one read, and the outcome follows it: the pipe present, the capture reused as at the base; absent, NOT RUN and nothing reused; as the Stop hook, behind an arm that admits the stop, the detector is not evaluated and the instrument is not run; and a goal that declares no engine_read writes the artifact and the capture the base writes, byte for byte but for the clock; and (the independent validator''s round 1) an UNFAULTED DOWN -- no fault key, the evaluator''s child on a PATH from which docker cannot be started -- reads NOT RUN in the read''s own words with no fault named, and where a reuse window is declared the detail -- RE-ASSERTED by BATCH-6 WP-Q, where the window was asked first and answered no and the detail said "NOT reused, and the instrument was not launched" -- ends "no reuse question was asked -- the engine read answered down before any reuse decision (register row 438)." and never says "the instrument was run", by hand and in the Stop hook''s block reason; and (the independent validator''s round 3) the engine''s keys are refused BEFORE the reuse question -- beside a reusable GREEN capture inside a 30-minute window, engine_read: nonsense and a fault key with no engine_read each still FAIL the detector by name, nothing reused, nothing kept, nothing run; and the bounded launch, lifted alone and handed stand-in children of this member''s own, answers only for a child that exits 0 AND prints a line -- an exit of 0 in silence is "it printed nothing", a line with exit 3 is "exit 3" (the builder''s own mutation sweep after that round). No row here causes a docker command; the UP reading is C-1aw''s' `
      -Ok $c1arOk -Detail ("      THE $(@($c1arRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1arRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument every goal here names (its exit code and its sleep read from two flag files, its bytes never changed):`n" + (Get-WlIndented -Text $wnStubText))

# =============================================================================================
# C-1as -- THE READER's GRAMMAR: a key that does not touch its colon is a goal that
#          does not parse, and a `patterns` item is one file-name pattern
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: Read-GoalDetectors stores a
# key only where the key TOUCHES its colon -- its two patterns, the item opener's and the key's under it, ask
# for `<key>:`. `count : 4` is a line it skips: the key is then ABSENT and the type's default is read, in
# silence -- `reuse_within_minutes : 30` reads no window and the instrument runs at every stop, `count : 4`
# asks for ONE result and passes on one, `engine_read : docker_pipe` is stored nowhere, an opener written
# `- type : <t>` opens no item and hands the keys under it to the item before it, and a
# `legacy_answered_allowlist : <HALT>@<sha256>` answers nothing -- the HALT reads OPEN, the verdict is HALT
# and the Stop hook APPROVES. (An earlier member recorded this grammar as a residual; this member is that residual.)
# THE RULE. RULE 1: inside the `detectors:` list a line the
# reader does not store and that reads `<key> :` -- a key, blanks, a colon -- is a FAULT, and the goal does
# not parse: NOT_MET, ONE failing goal_parse entry naming the line, the line as written and the key, and NO
# detector run -- for each of the twenty declared keys (twenty-one since BATCH-6 WP-Q:
# reuse_tree_within_minutes; twenty-two since BATCH-7 WP-R: require_owned), and for the item
# opener. IT IS BY SHAPE AND HOLDS NO
# TABLE OF KEYS: a key no type reads, written so, is the same fault, as a key line and as an opener (rows
# (h); the independent validator's round 3). D15: on a HALT-SCOPE key of
# a halt_absent item (dir, legacy_answered_allowlist) the fault OUTRANKS the HALT label -- the scope as read
# is not the scope as written -- so the verdict is NOT_MET with a HALT open and the hook blocks; on any other
# key the base's ladder stands and an open HALT still reads HALT, the refusal on the artifact beside it --
# and the HALT scope is the scope AS READ: a dir the goal's halt_absent declares is still scanned, though no
# detector of a goal that does not parse is run. WHICH ITEM IS A halt_absent ITEM IS ASKED OF THE GOAL AS
# WRITTEN (the builder-side review's finding, rows (f3); the independent validator's round 1,
# rows (f5)): an item runs from its opener line, stored or mis-spaced, to the next opener or the list's end;
# it is a halt_absent item where ANY `type` line in it -- stored or mis-spaced, the opener or a key line --
# reads halt_absent; and a fault on `dir` or `legacy_answered_allowlist` anywhere inside such an item
# outranks the HALT label, whatever the reader made of the item. A fault on the key `type` ALONE sets
# nothing (rows (f4), stated and not claimed). AND FOR A FAULTED KEY LINE THE ITEM AS THE READER READ IT IS
# STILL ASKED AS WELL, the older test kept beside the newer -- either reading is enough -- so that no goal
# the older test refused is let through by the newer (rows (f6): a HALT-scope key line under a mis-spaced
# opener of its own, which the reader puts in the halt_absent item above it). AND THE EXCEPTION ENDS WHERE
# THE RULING ENDS IT, "UNDER halt_absent": `dir` is a key of validator_pass_count too, and a `dir` that does
# not touch its colon in an item that is a validator_pass_count as written AND as read is a fault on
# another key -- beside a halt_absent spelled right the open HALT still reads HALT (rows (f7); the
# independent validator's round 2: no row held that boundary).
# RULE 2: a `patterns` item holding a bracket or a path separator FAILS validator_pass_count by name.
# THE CONTROLS, each a row: AN EARLIER RULE STANDS -- a free-text line, a hyphenated key, a bare list item and
# a quoted key inside the list are skipped and are no parse error, the artifact the base's but for its clock
# [RE-ASSERTED BY BATCH-6 WP-Q: each now a goal that does not parse; row (c), and the
# quoted opener of row (g), read so];
# Read-GoalDetectors is NOT EDITED and returns what the base's returns for every goal this tree tracks; the
# rule faults none of them; and, STATED AND NOT CLAIMED (D1 (ii), recorded, not built): a misspelled key still
# reads the default, a key-shaped line at column 0 still ends the list, and a quoted opener still hands its
# keys to the item before it.
# THE FIXTURE: one git repository under %TEMP% (New-WnMission), fifty-one goals committed. EVERY GOAL's `id:`
# is line 1 and `detectors:` line 2, so its first detector line is line 3: the lines the rows name are counted
# from that. NO ROW HERE CAUSES A docker COMMAND -- no goal declares docker_pipe_then_version, and each key of
# the engine read stands mis-spaced, read by neither tool. No verify_pass_or_dib item is left to its default
# path: each names a verify that is not on disk, so the tool that skips the key runs nothing in its place.
$c1asOk = $true
$c1asRows = New-Object System.Collections.Generic.List[string]
function Add-C1asRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1asOk = $false }
    $script:c1asRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1asRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1asEntries {
    # EVERY entry of a verdict artifact's detectors block, in the order written: type, ok and detail, quotes
    # un-doubled. (Get-PwDetector reads the FIRST entry of one type; a row that says "one entry, and it is
    # goal_parse" reads them all.)
    param([string]$Text)
    return ,@([regex]::Matches(([string]$Text), '(?m)^  - type: (\S+)\r?\n    ok: (\S+)\r?\n    detail: ''(.*)''\r?$') |
              ForEach-Object { [pscustomobject]@{ type = $_.Groups[1].Value; ok = ($_.Groups[2].Value -ceq 'true'); detail = $_.Groups[3].Value.Replace("''", "'") } })
}
function Get-C1asReading {
    # ONE EVALUATION OF -GoalId AT THE FIXTURE, through Invoke-WnEval -- this tree's tools or the base's, by
    # hand or as the Stop hook -- and what the rows read of it: the exit, the verdict, the hook's decision and
    # reason, every entry of the artifact, the goal_parse entries among them (parseCount; parse is the first
    # one's detail), the artifact's goal_parse_error key (parseKey; parseKeyText its value, quotes un-doubled),
    # and how many times the stub RAN across the call, read off its own counter.
    param([string]$Tools = 'tree', [string]$GoalId, [switch]$Hook)
    $c1asBefore = Get-WnRuns -Root $script:c1asRoot
    $c1asCall = @{ Tools = $Tools; Root = $script:c1asRoot; GoalId = $GoalId }
    if ($Hook) { $c1asCall['AsStopHook'] = $true }
    $c1asEv = Invoke-WnEval @c1asCall
    $c1asEntries = Get-C1asEntries -Text $c1asEv.artifactText
    $c1asParses = @($c1asEntries | Where-Object { $_.type -ceq 'goal_parse' })
    $c1asKeyLine = [regex]::Match([string]$c1asEv.artifactText, '(?m)^goal_parse_error: ''(.*)''\r?$')
    return [pscustomobject]@{ tools = $Tools; exit = $c1asEv.exit; verdict = $c1asEv.verdict; decision = $c1asEv.decision; reason = $c1asEv.reason; text = [string]$c1asEv.artifactText
                              entries = $c1asEntries; types = @($c1asEntries | ForEach-Object { $_.type }); parseCount = $c1asParses.Count
                              parse = $(if ($c1asParses.Count -gt 0) { [string]$c1asParses[0].detail } else { '' })
                              parseKey = $c1asKeyLine.Success; parseKeyText = $(if ($c1asKeyLine.Success) { $c1asKeyLine.Groups[1].Value.Replace("''", "'") } else { '' })
                              ran = ((Get-WnRuns -Root $script:c1asRoot) - $c1asBefore) }
}
function Get-C1asEntry {
    # The LAST entry of one type in a reading (found, ok, detail): the item a row wrote second, where the
    # goal's first item is of the same type.
    param($Reading, [string]$Type)
    $c1asOfType = @($Reading.entries | Where-Object { $_.type -ceq $Type })
    if ($c1asOfType.Count -eq 0) { return [pscustomobject]@{ found = $false; ok = $false; detail = '(no ' + $Type + ' entry in the artifact)' } }
    return [pscustomobject]@{ found = $true; ok = [bool]$c1asOfType[$c1asOfType.Count - 1].ok; detail = [string]$c1asOfType[$c1asOfType.Count - 1].detail }
}
function Get-C1asSaid {
    # What a row prints of one reading: who was asked, the exit, the verdict, the hook's decision where there
    # is one, every entry's type, the stub's runs, and the parse sentence -- or, where the goal PARSED, the
    # last entry as it reads, so a red row shows what was evaluated in the key's place.
    param($Reading)
    $c1asTail = 'no entry at all'
    if ($Reading.parseCount -gt 0) { $c1asTail = 'goal_parse: ' + $Reading.parse }
    elseif ($Reading.entries.Count -gt 0) { $c1asTail = 'NO goal_parse entry -- the last entry, ' + $Reading.entries[$Reading.entries.Count - 1].type + ': ' + $Reading.entries[$Reading.entries.Count - 1].detail }
    return ($Reading.tools + ': exit ' + $Reading.exit + ', ' + $Reading.verdict + $(if ($Reading.decision) { ', the hook says ' + $Reading.decision } else { '' }) + '; entries [' + ($Reading.types -join ', ') + ']; the stub ran ' + $Reading.ran + '; ' + $c1asTail)
}
function Test-C1asNamed {
    # DOES A PARSE SENTENCE NAME ONE FAULT AS THE RULE PRINTS IT? Three parts, in this order: "line <N>: ",
    # the line as the goal file holds it (its leading blanks apart: whether the scrub keeps them is the
    # cure's), and the key's clause, word for word.
    param([string]$Sentence, [int]$Line, [string]$Raw, [string]$Key)
    $c1asAtLine = $Sentence.IndexOf(('line ' + $Line + ': '), [System.StringComparison]::Ordinal)
    if ($c1asAtLine -lt 0) { return $false }
    $c1asAtRaw = $Sentence.IndexOf($Raw.Trim(), $c1asAtLine, [System.StringComparison]::Ordinal)
    if ($c1asAtRaw -lt 0) { return $false }
    return ($Sentence.IndexOf(('-- the key ' + $Key + ' does not touch its colon (register row 397)'), $c1asAtRaw, [System.StringComparison]::Ordinal) -ge 0)
}
function Get-C1asFunctions {
    # EVERY FUNCTION AN EVALUATOR FILE DEFINES, by its AST and in file order: the name, the definition's own
    # text (CR dropped) and the names of its parameters. Nothing of the file is run.
    param([string]$Path)
    $c1asTok = $null; $c1asErr = $null
    $c1asAst = [System.Management.Automation.Language.Parser]::ParseFile($Path, [ref]$c1asTok, [ref]$c1asErr)
    $c1asFound = New-Object System.Collections.Generic.List[object]
    foreach ($c1asFn in @($c1asAst.FindAll({ param($c1asNode) $c1asNode -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true))) {
        $c1asParams = @()
        if ($null -ne $c1asFn.Body.ParamBlock) { $c1asParams = @($c1asFn.Body.ParamBlock.Parameters | ForEach-Object { [string]$_.Name.VariablePath.UserPath }) }
        elseif ($null -ne $c1asFn.Parameters) { $c1asParams = @($c1asFn.Parameters | ForEach-Object { [string]$_.Name.VariablePath.UserPath }) }
        $c1asFound.Add([pscustomobject]@{ name = [string]$c1asFn.Name; text = ($c1asFn.Extent.Text -replace "`r", ''); params = $c1asParams })
    }
    return ,$c1asFound.ToArray()
}
function Invoke-C1asLifted {
    # ONE FUNCTION LIFTED FROM AN EVALUATOR, RUN ALONE (the form of C-1ah (m)): -Definition is the function's
    # own text and nothing else of its file. It is defined inside a script block's own scope and called
    # there by -Name, so this tree's reader and the base's never stand under one name and neither outlives
    # the call. Returns ok, why (what it threw, on one line) and out (everything it returned).
    param([string]$Definition, [string]$Name, [hashtable]$Arguments)
    $c1asLift = [pscustomobject]@{ ok = $false; why = ''; out = @() }
    try {
        $c1asLiftBlock = [scriptblock]::Create('param($c1asLiftName, $c1asLiftArgs)' + "`n" + $Definition + "`n" + '& $c1asLiftName @c1asLiftArgs')
        $c1asLift.out = @(& $c1asLiftBlock $Name $Arguments)
        $c1asLift.ok = $true
    } catch { $c1asLift.why = (([string]$_.Exception.Message) -replace '[\r\n]+', ' ') }
    return $c1asLift
}
$c1asM = $null
try {
# THE TWENTY DECLARED KEYS, in the order the contract lists them (standing 19), each under a type that reads
# it and written `<key> : <a plausible value>`. `item` is the goal's SECOND item; its first is a valid
# file_exists. The line that holds the fault is found in `item` by the rule's own pattern, never counted by hand.
# TWENTY-ONE SINCE BATCH-6 WP-Q (a): reuse_tree_within_minutes was declared after them, the
# twenty-first. TWENTY-TWO SINCE BATCH-7 WP-R (a): require_owned, a key sidecar_present reads, is
# declared after those and listed LAST in the literal below -- its name kept -- and in the list after it, so every
# key before it keeps its goal id (G-WNAS-A19 stays engine_read) and it is G-WNAS-A22.
$c1asTwenty = 'type, path, reuse_within_minutes, against, dispatch_kind, dir, count, pattern, patterns, kind, id, legacy_answered_allowlist, cap, minutes, since_file, session, allow_gaps, instrument_inputs_except, engine_read, engine_read_fault, reuse_tree_within_minutes, require_owned'
$c1asHaltBytes = $pwUtf8.GetBytes("# HALT-WNAS-01`n`n**Status:** ANSWERED`n")
$c1asHaltMember = 'HALT-WNAS-01.md@' + (Get-PwSha256 -Bytes $c1asHaltBytes)
$c1asFirst = @('  - type: file_exists', '    path: inputs/a.txt')
$c1asInstItem = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
$c1asRosterItem = @('  - type: validator_pass_count', '    dir: scratch/results')
$c1asVerifyItem = @('  - type: verify_pass_or_dib', '    path: scratch/no-verify.ps1')
$c1asKeys = @(
    @{ key = 'type';                      under = 'file_exists';          item = @('  - type : file_exists', '    path: other/b.txt') }
    @{ key = 'path';                      under = 'file_exists';          item = @('  - type: file_exists', '    path : other/b.txt') }
    @{ key = 'reuse_within_minutes';      under = 'instrument_exit0';     item = ($c1asInstItem + @('    reuse_within_minutes : 30')) }
    @{ key = 'against';                   under = 'verify_pass_or_dib';   item = ($c1asVerifyItem + @('    against : .mission/dispatches/D-WN-S1.anchors.yaml')) }
    @{ key = 'dispatch_kind';             under = 'verify_pass_or_dib';   item = ($c1asVerifyItem + @('    dispatch_kind : build')) }
    @{ key = 'dir';                       under = 'validator_pass_count'; item = @('  - type: validator_pass_count', '    dir : scratch/results') }
    @{ key = 'count';                     under = 'validator_pass_count'; item = ($c1asRosterItem + @('    count : 4')) }
    @{ key = 'pattern';                   under = 'validator_pass_count'; item = ($c1asRosterItem + @('    pattern : validator-A-9??.result.yaml')) }
    @{ key = 'patterns';                  under = 'validator_pass_count'; item = ($c1asRosterItem + @('    patterns : [validator-A-8??.result.yaml, validator-A-9??.result.yaml]')) }
    @{ key = 'kind';                      under = 'gate_present';         item = @('  - type: gate_present', '    kind : amendment-material', '    id: am-900') }
    @{ key = 'id';                        under = 'gate_present';         item = @('  - type: gate_present', '    kind: amendment-material', '    id : am-900') }
    @{ key = 'legacy_answered_allowlist'; under = 'halt_absent';          item = @('  - type: halt_absent', ('    legacy_answered_allowlist : ' + $c1asHaltMember)) }
    @{ key = 'cap';                       under = 'turn_cap';             item = @('  - type: turn_cap', '    cap : 5') }
    @{ key = 'minutes';                   under = 'time_cap';             item = @('  - type: time_cap', '    minutes : 10', '    since_file: inputs/a.txt') }
    @{ key = 'since_file';                under = 'time_cap';             item = @('  - type: time_cap', '    minutes: 10', '    since_file : inputs/a.txt') }
    @{ key = 'session';                   under = 'sidecar_present';      item = @('  - type: sidecar_present', '    session : session-D-WN-S1') }
    @{ key = 'allow_gaps';                under = 'sidecar_present';      item = @('  - type: sidecar_present', '    session: session-D-WN-S1', '    allow_gaps : true') }
    @{ key = 'instrument_inputs_except';  under = 'instrument_exit0';     item = ($c1asInstItem + @('    instrument_inputs_except : [other]')) }
    @{ key = 'engine_read';               under = 'instrument_exit0';     item = ($c1asInstItem + @('    engine_read : docker_pipe')) }
    @{ key = 'engine_read_fault';         under = 'instrument_exit0';     item = ($c1asInstItem + @('    engine_read_fault : pipe_absent')) }
    @{ key = 'reuse_tree_within_minutes'; under = 'instrument_exit0';     item = ($c1asInstItem + @('    reuse_tree_within_minutes : 180')) }
    @{ key = 'require_owned';             under = 'sidecar_present';      item = @('  - type: sidecar_present', '    session: session-D-WN-S1', '    require_owned : true') }
)
$c1asGoals = [ordered]@{}
$c1asKeyAt = 0
$c1asKeysWellFormed = $true
foreach ($c1asK in $c1asKeys) {
    $c1asKeyAt++
    $c1asK.id = 'G-WNAS-A' + $c1asKeyAt.ToString('00')
    $c1asFaulty = @($c1asK.item | Where-Object { $_ -cmatch ('^\s*(?:-\s*)?' + [regex]::Escape($c1asK.key) + '\s+:') })
    if ($c1asFaulty.Count -ne 1) { $c1asKeysWellFormed = $false; $c1asK.raw = ''; $c1asK.line = 0 }
    else { $c1asK.raw = [string]$c1asFaulty[0]; $c1asK.line = 5 + [array]::IndexOf([string[]]$c1asK.item, [string]$c1asFaulty[0]) }
    $c1asGoals[$c1asK.id] = ($c1asFirst + $c1asK.item)
}
# (b) THE ITEM OPENER: alone, and after a valid item.
$c1asGoals['G-WNAS-B1'] = @('  - type : file_exists', '    path: inputs/a.txt')
$c1asGoals['G-WNAS-B2'] = ($c1asFirst + @('  - type : instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30'))
# (c) THE EARLIER RULE's FOUR SHAPES, inside the first item of two.
$c1asGoals['G-WNAS-C'] = @('  - type: file_exists', '    path: inputs/a.txt', '    this is a note about the goal', '    dispatch-kind: build', '    - just words', '    "kind": a quoted key', '  - type: file_exists', '    path: other/b.txt')
# (e) RULE 2: an item holding both brackets, one holding a slash, one holding a backslash, and -- the contract
#     names FOUR characters, so each is driven ALONE as well -- one holding only `[` and one holding only `]`;
#     each beside a good item. (The list reader splits at commas and nowhere else: `[[a, b]` is the items `[a`
#     and `b`, and `[a], b]` is `a]` and `b`.)
$c1asGoals['G-WNAS-E1'] = ($c1asRosterItem + @('    patterns: [[a], validator-A-9??.result.yaml]'))
$c1asGoals['G-WNAS-E2'] = ($c1asRosterItem + @('    patterns: [sub/x.yaml, validator-A-9??.result.yaml]'))
$c1asGoals['G-WNAS-E3'] = ($c1asRosterItem + @('    patterns: [sub\x.yaml, validator-A-9??.result.yaml]'))
$c1asGoals['G-WNAS-E4'] = ($c1asRosterItem + @('    patterns: [[a, validator-A-9??.result.yaml]'))
$c1asGoals['G-WNAS-E5'] = ($c1asRosterItem + @('    patterns: [a], validator-A-9??.result.yaml]'))
# (f) D15: the fault on a HALT-scope key (the allowlist; the dir), and on another key beside a halt_absent.
$c1asF1Line = '    legacy_answered_allowlist : ' + $c1asHaltMember
$c1asGoals['G-WNAS-F1']  = @('  - type: halt_absent', $c1asF1Line, '  - type: file_exists', '    path: inputs/a.txt')
$c1asGoals['G-WNAS-F1D'] = @('  - type: halt_absent', '    dir : custom-halts', '  - type: file_exists', '    path: inputs/a.txt')
$c1asGoals['G-WNAS-F2']  = (@('  - type: halt_absent') + $c1asRosterItem + @('    count : 4'))
#     ... and the same fault where the halt_absent DECLARES a dir, spelled right: the scope as read.
$c1asGoals['G-WNAS-F2S'] = (@('  - type: halt_absent', '    dir: scratch/halts-declared') + $c1asRosterItem + @('    count : 4'))
# (f3) D15 WHERE THE HALT-SCOPE KEY OPENS ITS ITEM (the builder-side review's finding): `- <key> : <value>`
#     and `type: halt_absent` under it, each key as the goal's FIRST item and after an unrelated valid item.
#     `before` is what stands ahead of the faulted line, so the line's number is 3 plus its count.
$c1asF3 = @(
    @{ id = 'G-WNAS-F3A1'; key = 'legacy_answered_allowlist'; raw = ('  - legacy_answered_allowlist : ' + $c1asHaltMember); shown = '- legacy_answered_allowlist : <the HALT>@<sha256>'; where = 'the goal''s FIRST item'; before = @() }
    @{ id = 'G-WNAS-F3A2'; key = 'legacy_answered_allowlist'; raw = ('  - legacy_answered_allowlist : ' + $c1asHaltMember); shown = '- legacy_answered_allowlist : <the HALT>@<sha256>'; where = 'the item AFTER an unrelated valid file_exists item'; before = $c1asFirst }
    @{ id = 'G-WNAS-F3D1'; key = 'dir'; raw = '  - dir : custom-halts'; shown = '- dir : custom-halts'; where = 'the goal''s FIRST item'; before = @() }
    @{ id = 'G-WNAS-F3D2'; key = 'dir'; raw = '  - dir : custom-halts'; shown = '- dir : custom-halts'; where = 'the item AFTER an unrelated valid file_exists item'; before = $c1asFirst }
)
foreach ($c1asF3One in $c1asF3) {
    $c1asF3One.line = 3 + @($c1asF3One.before).Count
    $c1asGoals[$c1asF3One.id] = (@($c1asF3One.before) + @($c1asF3One.raw, '    type: halt_absent'))
}
# (f4) ... AND THE OTHER HALF, STATED: the fault on the key `type` of an item whose HALT-scope key touches its colon.
$c1asGoals['G-WNAS-F4A'] = @('  - type : halt_absent', ('    legacy_answered_allowlist: ' + $c1asHaltMember))
$c1asGoals['G-WNAS-F4B'] = @(('  - legacy_answered_allowlist: ' + $c1asHaltMember), '    type : halt_absent')
# (f5) D15, THE ITEM AS WRITTEN, FOR A FAULTED KEY LINE TOO (the independent validator's round 1; the
#     four forms its goals G-D1 to G-D4 drove): an item that AS WRITTEN is a halt_absent and AS READ is not,
#     with a HALT-scope KEY LINE mis-spaced inside it. `item` is the item's lines, `before` what stands ahead
#     of it and `after` what follows it. The HALT-scope line that holds the fault is found in `item` by the
#     rule's own pattern, never counted by hand: its number is 3, plus what stands before, plus its place
#     (line 0 where an item does not hold exactly one such line: the row then names no line and reads red).
$c1asF5Allow = '    legacy_answered_allowlist : ' + $c1asHaltMember
$c1asF5 = @(
    @{ id = 'G-WNAS-F5A'; key = 'legacy_answered_allowlist'; item = @('  - type : halt_absent', $c1asF5Allow); before = @(); after = $c1asFirst
       shown = 'the opener `- type : halt_absent` and `legacy_answered_allowlist : <the HALT>@<sha256>` under it, BOTH mis-spaced'; where = 'the goal''s FIRST item, a valid file_exists item after it' }
    @{ id = 'G-WNAS-F5B'; key = 'legacy_answered_allowlist'; item = @('  - type : halt_absent', $c1asF5Allow); before = $c1asFirst; after = @()
       shown = 'the opener `- type : halt_absent` and `legacy_answered_allowlist : <the HALT>@<sha256>` under it, BOTH mis-spaced'; where = 'the item AFTER an unrelated valid file_exists item' }
    @{ id = 'G-WNAS-F5C'; key = 'legacy_answered_allowlist'; item = @('  - dir: custom-halts', $c1asF5Allow, '    type : halt_absent'); before = @(); after = $c1asFirst
       shown = 'a well-spelled opener `- dir: custom-halts`, then `legacy_answered_allowlist : <the HALT>@<sha256>` and `type : halt_absent`, both mis-spaced'; where = 'the goal''s FIRST item, a valid file_exists item after it' }
    @{ id = 'G-WNAS-F5D'; key = 'dir'; item = @(('  - legacy_answered_allowlist: ' + $c1asHaltMember), '    dir : custom-halts', '    type : halt_absent'); before = @(); after = $c1asFirst
       shown = 'a well-spelled opener `- legacy_answered_allowlist: <the HALT>@<sha256>`, then `dir : custom-halts` and `type : halt_absent`, both mis-spaced'; where = 'the goal''s FIRST item, a valid file_exists item after it' }
)
foreach ($c1asF5One in $c1asF5) {
    $c1asF5Faulty = @($c1asF5One.item | Where-Object { $_ -cmatch ('^\s*' + [regex]::Escape($c1asF5One.key) + '\s+:') })
    if ($c1asF5Faulty.Count -ne 1) { $c1asF5One.raw = ''; $c1asF5One.line = 0 }
    else { $c1asF5One.raw = [string]$c1asF5Faulty[0]; $c1asF5One.line = 3 + @($c1asF5One.before).Count + [array]::IndexOf([string[]]$c1asF5One.item, [string]$c1asF5Faulty[0]) }
    $c1asGoals[$c1asF5One.id] = (@($c1asF5One.before) + @($c1asF5One.item) + @($c1asF5One.after))
}
# (f6) D15, THE ITEM AS READ, KEPT FOR A FAULTED KEY LINE: a halt_absent spelled right; then an opener that is
#     itself mis-spaced, `- path : inputs/a.txt`, and under it `dir : custom-halts`, the line the row names;
#     then a valid item. As written the dir line stands in an item with no `type` line; as the reader reads
#     it -- it takes no opener from the mis-spaced one -- it falls in the halt_absent above.
$c1asF6Dir = '    dir : custom-halts'
$c1asF6Goal = (@('  - type: halt_absent', '  - path : inputs/a.txt', $c1asF6Dir) + $c1asFirst)
$c1asF6DirAt = 3 + [array]::IndexOf([string[]]$c1asF6Goal, $c1asF6Dir)
$c1asGoals['G-WNAS-F6'] = $c1asF6Goal
# (f7) D15's OTHER BOUNDARY, "UNDER halt_absent": a halt_absent spelled right; then a validator_pass_count item
#     spelled right but for its `dir`, which does not touch its colon -- its count and its pattern do. The
#     faulted key is NAMED dir and is no HALT-scope key: the item it stands in is a validator_pass_count as
#     written and as the reader reads it.
$c1asF7Dir = '    dir : scratch/results'
$c1asF7Goal = @('  - type: halt_absent', '  - type: validator_pass_count', $c1asF7Dir, '    count: 1', '    pattern: validator-A-9??.result.yaml')
$c1asF7DirAt = 3 + [array]::IndexOf([string[]]$c1asF7Goal, $c1asF7Dir)
$c1asGoals['G-WNAS-F7'] = $c1asF7Goal
# (g) STATED, NOT CLAIMED: a misspelled key; a key-shaped line at column 0; a quoted opener.
$c1asGoals['G-WNAS-G1'] = ($c1asRosterItem + @('    pattern: validator-A-9??.result.yaml', '    cuont: 4'))
$c1asGoals['G-WNAS-G2'] = ($c1asFirst + @('note: x') + $c1asInstItem)
$c1asGoals['G-WNAS-G3'] = @('  - type: file_exists', '    path: evidence/absent.txt', '  - "type": file_exists', '    path: inputs/a.txt')
# (h) RULE 1 IS BY SHAPE (the independent validator's round 3): a key NO type reads and no table
#     holds, written key, blank, colon -- once as a KEY LINE (the goal of (g)'s first row, `cuont: 4`, but for
#     that one blank) and once as an item's OPENER, after a valid item. `raw` is the faulted line, `line` its
#     number, found in the goal's lines and never counted by hand.
$c1asByShape = @(
    @{ id = 'G-WNAS-H1'; key = 'cuont'; raw = '    cuont : 4'; lines = ($c1asRosterItem + @('    pattern: validator-A-9??.result.yaml', '    cuont : 4'))
       shown = 'a KEY LINE under a validator_pass_count, `cuont : 4` -- the misspelled key of (g)''s first row, with a blank before its colon'
       base = 'the base skips the line in silence, as it skips `cuont: 4` -- the roster needs the default ONE, "1 of 1 required", MET, exit 0' }
    @{ id = 'G-WNAS-H2'; key = 'zzz_new_key'; raw = '  - zzz_new_key : 1'; lines = ($c1asFirst + @('  - zzz_new_key : 1'))
       shown = 'an item''s OPENER after a valid file_exists item, `- zzz_new_key : 1`'
       base = 'the base skips the opener in silence and reads ONE item, the file_exists -- MET, exit 0' }
)
foreach ($c1asByShapeOne in $c1asByShape) {
    $c1asByShapeOne.line = 3 + [array]::IndexOf([string[]]$c1asByShapeOne.lines, [string]$c1asByShapeOne.raw)
    $c1asGoals[$c1asByShapeOne.id] = $c1asByShapeOne.lines
}
$c1asM = New-WnMission -Tag 'c1as' -Goals $c1asGoals
if (-not $c1asM.ok) { throw ('FIXTURE REFUSED: ' + $c1asM.why) }
$c1asRoot = $c1asM.root
$c1asInst = Write-WnStub -Root $c1asRoot
# THE ROSTER DATA (C-1ao's form): ONE result with a column-0 verdict: PASS under scratch\results -- untracked,
# under the one admitted prefix -- and a SECOND one level down, scratch\results\sub\x.yaml, each bound in the
# FIXTURE's own spawn ledger by a hand-written `complete` line carrying its sha256. Literal fixture data: no
# composer is run, and the live ledger is not opened.
$c1asResultName = 'validator-A-900.result.yaml'
$c1asResultBytes = $pwUtf8.GetBytes("verdict: PASS`n")
$c1asSubBytes = $pwUtf8.GetBytes("# one directory below the roster's own`nverdict: PASS`n")
Set-PwBytes -Path (Join-Path $c1asRoot ('scratch\results\' + $c1asResultName)) -Bytes $c1asResultBytes
Set-PwBytes -Path (Join-Path $c1asRoot 'scratch\results\sub\x.yaml') -Bytes $c1asSubBytes
$c1asLedgerText = '{"seq":1,"event":"complete","dispatch_id":"D-WN-FIXTURE-1","result_path":"scratch/results/' + $c1asResultName + '","result_sha256":"' + (Get-PwSha256 -Bytes $c1asResultBytes) + '","composed_by":"WP-3 C-1as, by hand: literal fixture data, no composer run"}' + "`n" +
                  '{"seq":2,"event":"complete","dispatch_id":"D-WN-FIXTURE-2","result_path":"scratch/results/sub/x.yaml","result_sha256":"' + (Get-PwSha256 -Bytes $c1asSubBytes) + '","composed_by":"WP-3 C-1as, by hand: literal fixture data, no composer run"}' + "`n"
Write-Utf8 -Path (Join-Path $c1asRoot '.mission-runtime\lam\spawn-ledger.jsonl') -Text $c1asLedgerText
$c1asHaltsDir = Join-Path $c1asRoot '.mission-runtime\halts'
$c1asKeyList = (@($c1asKeys | ForEach-Object { $_.key }) -join ', ')
Add-C1asRow -Label 'FIXTURE a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/"), inputs/, other/ and fifty-one goals committed, porcelain exactly "?? scratch/"; the twenty-two keys driven are the contract''s twenty-two (reuse_tree_within_minutes the twenty-first; require_owned last), in its order, each written once with a blank before its colon; no HALT on disk yet' `
    -Ok ($wnBase.ok -and ((Get-WnPorcelain -Root $c1asRoot) -ceq '?? scratch/') -and ($c1asM.head -cmatch '\A[0-9a-f]{40}\z') -and ($c1asGoals.Count -eq 51) -and ($c1asKeys.Count -eq 22) -and ($c1asKeyList -ceq $c1asTwenty) -and $c1asKeysWellFormed -and
         (-not (Test-Path -LiteralPath $c1asHaltsDir)) -and (Test-Path -LiteralPath $c1asInst -PathType Leaf) -and (-not (Test-Path -LiteralPath (Join-Path $c1asRoot 'scratch\no-verify.ps1')))) `
    -Said ('HEAD ' + $c1asM.head + '; ' + $c1asGoals.Count + ' goals; keys [' + $c1asKeyList + ']; ' + $wnBase.said)
# THE TWO EVALUATORS' FUNCTIONS, READ ONCE, by AST -- nothing of either file is run: this tree's and the
# base's. The reader of each is lifted from these, in an (a) control and in (d).
$c1asTreeFns = Get-C1asFunctions -Path $goalCheck
$c1asBaseFns = Get-C1asFunctions -Path (Get-WnBaseOrThrow).path
$c1asTreeReader = @($c1asTreeFns | Where-Object { $_.name -ceq 'Read-GoalDetectors' })
$c1asBaseReader = @($c1asBaseFns | Where-Object { $_.name -ceq 'Read-GoalDetectors' })

# (a) THE TWENTY-TWO DECLARED KEYS, one goal each, at THIS TREE: the goal does not parse.
foreach ($c1asK in $c1asKeys) {
    $c1asA = Get-C1asReading -GoalId $c1asK.id
    $c1asShown = $c1asK.raw.Trim()
    if ($c1asShown.Length -gt 64) { $c1asShown = $c1asShown.Substring(0, 61) + '...' }
    Add-C1asRow -Label ('(a) FALSIFIER `' + $c1asShown + '` under ' + $c1asK.under + ', goal line ' + $c1asK.line + ': NOT_MET, exit 1, ONE entry and it is goal_parse, failing, naming line ' + $c1asK.line + ', the line as written and "the key ' + $c1asK.key + ' does not touch its colon (register row 397)"; no detector ran, the stub not run') `
        -Ok (($c1asA.verdict -ceq 'NOT_MET') -and ($c1asA.exit -eq 1) -and ($c1asA.types.Count -eq 1) -and ($c1asA.parseCount -eq 1) -and (-not $c1asA.entries[0].ok) -and
             (Test-C1asNamed -Sentence $c1asA.parse -Line $c1asK.line -Raw $c1asK.raw -Key $c1asK.key) -and ($c1asA.ran -eq 0)) `
        -Said (Get-C1asSaid -Reading $c1asA)
}
# (a) THE RED, KEPT, for three of them: the base skips the line and reads the type's default.
$c1asAB1 = Get-C1asReading -Tools base -GoalId 'G-WNAS-A03'
$c1asAB1Inst = Get-C1asEntry -Reading $c1asAB1 -Type 'instrument_exit0'
Add-C1asRow -Label '(a) BASE CONTROL: `reuse_within_minutes : 30`: the base skips the line -- NO window is read: MET, no goal_parse entry, the stub RUNS, the artifact holds no instrument_captures_reused: key and the entry says nothing of a window' `
    -Ok (($c1asAB1.verdict -ceq 'MET') -and ($c1asAB1.exit -eq 0) -and ($c1asAB1.parseCount -eq 0) -and (-not $c1asAB1.parseKey) -and ($c1asAB1.ran -eq 1) -and (($c1asAB1.types -join ',') -ceq 'file_exists,instrument_exit0') -and
         (-not [regex]::IsMatch($c1asAB1.text, '(?m)^instrument_captures_reused:')) -and $c1asAB1Inst.detail.StartsWith('inst.ps1 exited 0 (require 0). Instrument output kept at ') -and (-not $c1asAB1Inst.detail.Contains('reuse_within_minutes'))) `
    -Said ((Get-C1asSaid -Reading $c1asAB1) + ' | reuse key in the artifact: ' + [regex]::IsMatch($c1asAB1.text, '(?m)^instrument_captures_reused:'))
$c1asAB2 = Get-C1asReading -Tools base -GoalId 'G-WNAS-A07'
$c1asAB2Roster = Get-C1asEntry -Reading $c1asAB2 -Type 'validator_pass_count'
Add-C1asRow -Label '(a) BASE CONTROL: `count : 4`: the base skips the line -- the roster needs ONE: "1 of 1 required", the detector PASSES on the one result where four were asked for, MET, no goal_parse entry' `
    -Ok (($c1asAB2.verdict -ceq 'MET') -and ($c1asAB2.exit -eq 0) -and ($c1asAB2.parseCount -eq 0) -and (-not $c1asAB2.parseKey) -and $c1asAB2Roster.ok -and $c1asAB2Roster.detail.StartsWith('1 of 1 required validator result(s) are COMPLETE') -and
         $c1asAB2Roster.detail.EndsWith(' [' + $c1asResultName + '=PASS]')) `
    -Said (Get-C1asSaid -Reading $c1asAB2)
$c1asAB3 = Get-C1asReading -Tools base -GoalId 'G-WNAS-A19'
# "STORED NOWHERE" IS READ OFF THE BASE's OWN READER, lifted alone and asked for that goal file: the keys of
# each item it returns. (The artifact not holding the word says little by itself -- the base evaluator
# prints no key it does not read, spelled right or not.)
$c1asAB3Read = Invoke-C1asLifted -Definition $(if ($c1asBaseReader.Count -eq 1) { $c1asBaseReader[0].text } else { '' }) -Name 'Read-GoalDetectors' -Arguments @{ Path = (Join-Path $c1asM.goalsDir 'G-WNAS-A19.yaml') }
$c1asAB3Keys = (@($c1asAB3Read.out | ForEach-Object { (@($_.Keys | Sort-Object) -join '+') }) -join ' | ')
Add-C1asRow -Label '(a) BASE CONTROL: `engine_read : docker_pipe`: the base skips the line -- the key is STORED NOWHERE: the base''s reader, lifted alone and asked for that goal file, returns two items holding the keys path and type and no other, and the artifact does not hold the word; the stub RUNS, MET, no goal_parse entry' `
    -Ok (($c1asAB3.verdict -ceq 'MET') -and ($c1asAB3.exit -eq 0) -and ($c1asAB3.parseCount -eq 0) -and (-not $c1asAB3.parseKey) -and ($c1asAB3.ran -eq 1) -and (-not $c1asAB3.text.Contains('engine_read')) -and
         $c1asAB3Read.ok -and ($c1asAB3Keys -ceq 'path+type | path+type') -and
         (Get-C1asEntry -Reading $c1asAB3 -Type 'instrument_exit0').detail.StartsWith('inst.ps1 exited 0 (require 0). Instrument output kept at ')) `
    -Said ((Get-C1asSaid -Reading $c1asAB3) + ' | the base''s reader, lifted: ' + $(if ($c1asAB3Read.ok) { 'item keys [' + $c1asAB3Keys + ']' } else { 'THREW: ' + $c1asAB3Read.why }) + ' | "engine_read" in the artifact: ' + $c1asAB3.text.Contains('engine_read'))

# (b) THE ITEM OPENER. (b1) the goal's ONLY item; (b2) after a valid item, with an instrument's keys under it.
$c1asB1 = Get-C1asReading -GoalId 'G-WNAS-B1'
Add-C1asRow -Label '(b) FALSIFIER (b1) a goal whose ONLY item opens `- type : file_exists` (goal line 3): NOT_MET, exit 1, ONE goal_parse entry naming line 3, the line as written and the key type' `
    -Ok (($c1asB1.verdict -ceq 'NOT_MET') -and ($c1asB1.exit -eq 1) -and ($c1asB1.types.Count -eq 1) -and ($c1asB1.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asB1.parse -Line 3 -Raw '- type : file_exists' -Key 'type')) `
    -Said (Get-C1asSaid -Reading $c1asB1)
$c1asB1B = Get-C1asReading -Tools base -GoalId 'G-WNAS-B1'
Add-C1asRow -Label '(b) BASE CONTROL: (b1) the same goal: the base reads NO item -- NOT_MET, goal_parse saying "it declares no detectors", and NO line named' `
    -Ok (($c1asB1B.verdict -ceq 'NOT_MET') -and ($c1asB1B.exit -eq 1) -and ($c1asB1B.types.Count -eq 1) -and ($c1asB1B.parseCount -eq 1) -and $c1asB1B.parse.Contains('it declares no detectors (a column-0 detectors: line with no ''- <key>:'' item under it)') -and
         (-not [regex]::IsMatch($c1asB1B.parse, 'line \d+: ')) -and (-not $c1asB1B.parse.Contains('does not touch its colon'))) `
    -Said (Get-C1asSaid -Reading $c1asB1B)
$c1asB2 = Get-C1asReading -GoalId 'G-WNAS-B2'
Add-C1asRow -Label '(b) FALSIFIER (b2) a valid file_exists item, then `- type : instrument_exit0` (goal line 5) with path: and reuse_within_minutes: under it: NOT_MET, exit 1, ONE goal_parse entry naming line 5 and the key type; the stub not run' `
    -Ok (($c1asB2.verdict -ceq 'NOT_MET') -and ($c1asB2.exit -eq 1) -and ($c1asB2.types.Count -eq 1) -and ($c1asB2.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asB2.parse -Line 5 -Raw '- type : instrument_exit0' -Key 'type') -and ($c1asB2.ran -eq 0)) `
    -Said (Get-C1asSaid -Reading $c1asB2)
$c1asB2B = Get-C1asReading -Tools base -GoalId 'G-WNAS-B2'
Add-C1asRow -Label '(b) BASE CONTROL: (b2) the same goal: no goal_parse -- the opener is skipped and its keys LAND ON THE ITEM BEFORE IT: ONE entry, of type file_exists, answering on the instrument''s path; no instrument_exit0 entry, the stub not run, MET' `
    -Ok (($c1asB2B.verdict -ceq 'MET') -and ($c1asB2B.exit -eq 0) -and ($c1asB2B.parseCount -eq 0) -and (-not $c1asB2B.parseKey) -and (($c1asB2B.types -join ',') -ceq 'file_exists') -and $c1asB2B.entries[0].detail.StartsWith('scratch/inst.ps1 exists=True ') -and ($c1asB2B.ran -eq 0)) `
    -Said (Get-C1asSaid -Reading $c1asB2B)

# (c) THE EARLIER RULE AS IT STOOD: four shapes the reader skips inside the list, none of them a `<key> :`. RE-ASSERTED
#     BY BATCH-6 WP-Q (ruled 2026-10-16 07:2x local, lean accepted): each
#     is no key, no list opener, no blank and no comment, so the goal does NOT PARSE -- the base still skips them.
$c1asC = Get-C1asReading -GoalId 'G-WNAS-C'
$c1asCB = Get-C1asReading -Tools base -GoalId 'G-WNAS-C'
Add-C1asRow -Label '(c) RE-ASSERTED BY BATCH-6 WP-Q: a free-text line, a hyphenated key (dispatch-kind: build), a bare `- just words` and a quoted key, inside the list: the goal DOES NOT PARSE at this tree -- NOT_MET, exit 1, ONE goal_parse entry naming lines 5, 6 and 7 as written and "and 1 more", under register row 424, no detector run -- where the base skips all four and reads MET' `
    -Ok (($c1asC.verdict -ceq 'NOT_MET') -and ($c1asC.exit -eq 1) -and ($c1asC.parseCount -eq 1) -and (@($c1asC.types | Where-Object { $_ -ceq 'file_exists' }).Count -eq 0) -and
         $c1asC.parse.Contains('a line inside its detectors list is no key, no list opener, no blank and no comment -- line 5: `    this is a note about the goal`; line 6: `    dispatch-kind: build`; line 7: `    - just words`; and 1 more -- ') -and
         $c1asC.parse.Contains('(register row 424)') -and ($c1asCB.verdict -ceq 'MET') -and ($c1asCB.parseCount -eq 0)) `
    -Said ((Get-C1asSaid -Reading $c1asC) + ' | base: ' + $c1asCB.verdict)

# (d) THE READER IS NOT EDITED, AND THE RULE IS A FUNCTION OF ITS OWN. Read-GoalDetectors lifted ALONE by its
#     AST (the form of C-1ah (m)) from this tree's evaluator and from the base's, and run over every goal file
#     git tracks here, read-only: the same definition, the same items. No goal is evaluated in this row.
#     (The two function lists were read under the FIXTURE row.)
$c1asTracked = @((Get-LamTrackedGoals).files)
$c1asShape = { param($c1asItems) (@($c1asItems | ForEach-Object { $c1asIt = $_; (@($c1asIt.Keys | Sort-Object) | ForEach-Object { [string]$_ + '=' + [string]$c1asIt[$_] }) -join '|' }) -join "`n") }
$c1asReadCount = 0
$c1asItemCount = 0
$c1asAbsent = 0
$c1asDiffer = New-Object System.Collections.Generic.List[string]
if (($c1asTreeReader.Count -eq 1) -and ($c1asBaseReader.Count -eq 1)) {
    foreach ($c1asRel in $c1asTracked) {
        $c1asGoalFile = Join-Path $repoRoot ($c1asRel -replace '/', '\')
        # A goal git tracks and this checkout does not hold is not read (as C-1al (k) has it); it is counted and said.
        if (-not (Test-Path -LiteralPath $c1asGoalFile -PathType Leaf)) { $c1asAbsent++; continue }
        $c1asFromTree = Invoke-C1asLifted -Definition $c1asTreeReader[0].text -Name 'Read-GoalDetectors' -Arguments @{ Path = $c1asGoalFile }
        $c1asFromBase = Invoke-C1asLifted -Definition $c1asBaseReader[0].text -Name 'Read-GoalDetectors' -Arguments @{ Path = $c1asGoalFile }
        if ((-not $c1asFromTree.ok) -or (-not $c1asFromBase.ok)) { $c1asDiffer.Add($c1asRel + ' (the lifted reader threw: ' + $c1asFromTree.why + $c1asFromBase.why + ')'); continue }
        $c1asReadCount++
        $c1asItemCount += $c1asFromTree.out.Count
        if (($c1asFromTree.out.Count -eq 0) -or ((& $c1asShape $c1asFromTree.out) -cne (& $c1asShape $c1asFromBase.out))) { $c1asDiffer.Add($c1asRel + ' (' + $c1asFromTree.out.Count + ' item(s) from the tree''s reader, ' + $c1asFromBase.out.Count + ' from the base''s)') }
    }
}
$c1asReaderSame = (($c1asTreeReader.Count -eq 1) -and ($c1asBaseReader.Count -eq 1) -and ($c1asTreeReader[0].text -ceq $c1asBaseReader[0].text))
Add-C1asRow -Label ('(d) CONTROL Read-GoalDetectors, LIFTED ALONE by its AST from this tree''s evaluator and from the base''s: defined once in each, the two definitions EQUAL (the reader is not edited), and over the ' + $c1asTracked.Count + ' goal file(s) git tracks here, read-only, the same items, key for key') `
    -Ok ($c1asReaderSame -and ($c1asReadCount -gt 0) -and (($c1asReadCount + $c1asAbsent) -eq $c1asTracked.Count) -and ($c1asItemCount -gt 0) -and ($c1asDiffer.Count -eq 0)) `
    -Said ('definitions: tree ' + $c1asTreeReader.Count + ', base ' + $c1asBaseReader.Count + ', equal: ' + $c1asReaderSame + '; goal files read ' + $c1asReadCount + ' of ' + $c1asTracked.Count + ' (' + $c1asAbsent + ' tracked and not on disk), ' + $c1asItemCount + ' item(s); differing [' + ($c1asDiffer -join ' ; ') + ']')
# (d) ... THE RULE's OWN FUNCTION. Its name, its parameters and what it returns are the cure's -- the contract
#     fixes none of them, and not where the fault's sentence is composed either -- so it is FOUND by its own
#     text, its name and parameters printed, and NOT CALLED: what it says of the tracked goals is read in the
#     row under this one, through the evaluator that calls it. TWO MARKS, EITHER ONE: the rule's clause, the
#     words the goal_parse sentence ends each fault on ("does not touch its colon") -- a function that
#     composes the sentence holds it -- or the rule's own test as the contract writes its pattern, a key and
#     then `\s+:` -- a function that only FINDS the faults, as Get-GoalNumericFaults only finds the numbers
#     and leaves the sentence to the step under it, holds that. (At the base neither stands in any function:
#     the clause stands once, in the comment that records the residual above ConvertTo-GoalWholeNumber,
#     outside every function, and the pattern nowhere in the file.) A rule written inline, in no function,
#     or into the reader, leaves this row RED.
$c1asRuleClause = 'does not touch its colon'
$c1asRulePattern = '\s+:'
$c1asRuleFns = @($c1asTreeFns | Where-Object { $_.text.Contains($c1asRuleClause) -or $_.text.Contains($c1asRulePattern) })
$c1asRuleShown = @($c1asRuleFns | ForEach-Object { $_.name + '(' + ($_.params -join ', ') + ')' + $(if ($_.text.Contains($c1asRuleClause)) { ' [the clause]' } else { '' }) + $(if ($_.text.Contains($c1asRulePattern)) { ' [the pattern]' } else { '' }) })
$c1asReaderHolds = @($c1asRuleFns | Where-Object { $_.name -ceq 'Read-GoalDetectors' }).Count
$c1asBaseHolds = @($c1asBaseFns | Where-Object { $_.text.Contains($c1asRuleClause) -or $_.text.Contains($c1asRulePattern) }).Count
Add-C1asRow -Label '(d) FALSIFIER THE RULE IS A FUNCTION OF ITS OWN BESIDE THE READER: at least one function of this tree''s evaluator holds in its own text the rule''s clause "does not touch its colon" or the rule''s pattern for a key that does not (`\s+:`), and Read-GoalDetectors -- not edited -- is not one of them (the base has none)' `
    -Ok (($c1asRuleFns.Count -ge 1) -and ($c1asReaderHolds -eq 0) -and $c1asReaderSame) `
    -Said ('functions of the tree''s evaluator holding the clause or the pattern: ' + $c1asRuleFns.Count + ' [' + ($c1asRuleShown -join ', ') + '] of ' + $c1asTreeFns.Count + ' defined; of the base''s: ' + $c1asBaseHolds + ' of ' + $c1asBaseFns.Count + '; the reader among them: ' + $c1asReaderHolds + '; the reader unedited: ' + $c1asReaderSame)
# (d) ... AND IT FAULTS NO GOAL THIS TREE TRACKS. Each tracked goal file, as it stands, is COPIED into the
#     fixture under a G-WNAS id with ONE failing file_exists item written first in its list, and evaluated
#     there AS THE STOP HOOK: that item fails, so every detector of the live goal is recorded NOT EVALUATED
#     (the three admitted-stop arms apart, which read the fixture) -- no instrument, no verify, nothing of
#     the live goal is run -- and the one question left is whether the goal PARSED. The copies are removed.
$c1asProbe = @('  - type: file_exists', '    path: scratch/no-such-file.txt')
$c1asArmTypes = @('ungated_placement_absent', 'ungated_manifest_absent', 'handoff_brief_present')
$c1asTrackedAt = 0
$c1asTrackedAsked = 0
$c1asTrackedParsed = 0
$c1asTrackedSaid = New-Object System.Collections.Generic.List[string]
foreach ($c1asRel in $c1asTracked) {
    $c1asTrackedAt++
    $c1asLeaf = [System.IO.Path]::GetFileName($c1asRel)
    $c1asGoalFile = Join-Path $repoRoot ($c1asRel -replace '/', '\')
    if (-not (Test-Path -LiteralPath $c1asGoalFile -PathType Leaf)) { $c1asTrackedSaid.Add($c1asLeaf + ': tracked and not on disk, not asked'); continue }
    $c1asSource = @([System.IO.File]::ReadAllLines($c1asGoalFile))
    $c1asOpens = -1
    for ($c1asI = 0; $c1asI -lt $c1asSource.Count; $c1asI++) { if (($c1asSource[$c1asI] -replace "`t", '    ') -match '^detectors:\s*$') { $c1asOpens = $c1asI; break } }
    # A file with no column-0 detectors: line holds no list, so there is no line in it the rule could fault.
    if ($c1asOpens -lt 0) { $c1asTrackedSaid.Add($c1asLeaf + ': no column-0 detectors: line, so no list to fault -- not asked'); continue }
    $c1asTrackedAsked++
    $c1asCopy = @($c1asSource[0..$c1asOpens]) + $c1asProbe
    if (($c1asOpens + 1) -lt $c1asSource.Count) { $c1asCopy += @($c1asSource[($c1asOpens + 1)..($c1asSource.Count - 1)]) }
    $c1asCopyId = 'G-WNAS-T' + $c1asTrackedAt
    $c1asCopyPath = Join-Path $c1asM.goalsDir ($c1asCopyId + '.yaml')
    Write-Utf8 -Path $c1asCopyPath -Text (($c1asCopy -join "`n") + "`n")
    $c1asT = Get-C1asReading -GoalId $c1asCopyId -Hook
    Remove-Item -LiteralPath $c1asCopyPath -Force
    Remove-Item -LiteralPath (Join-Path $c1asM.goalsDir ($c1asCopyId + '.verdict.yaml')) -Force -ErrorAction SilentlyContinue
    $c1asProbed = @($c1asT.entries | Where-Object { ($_.type -ceq 'file_exists') -and $_.detail.StartsWith('scratch/no-such-file.txt exists=False ') })
    $c1asEvaluated = @($c1asT.entries | Where-Object { ($c1asArmTypes -cnotcontains $_.type) -and (-not $_.detail.StartsWith('NOT EVALUATED -- hook-mode short-circuit')) })
    $c1asTrackedGood = (($c1asT.parseCount -eq 0) -and (-not $c1asT.parseKey) -and ($c1asProbed.Count -eq 1) -and ($c1asEvaluated.Count -eq 1) -and ($c1asT.ran -eq 0) -and ($c1asT.decision -ceq 'block'))
    if ($c1asTrackedGood) { $c1asTrackedParsed++; $c1asTrackedSaid.Add($c1asLeaf + ': parsed, ' + $c1asT.types.Count + ' entries') }
    else { $c1asTrackedSaid.Add($c1asLeaf + ': ' + (Get-C1asSaid -Reading $c1asT) + ' (a line this names is the file''s own line plus 2)') }
}
Add-C1asRow -Label ('(d) CONTROL THE RULE FAULTS NO TRACKED GOAL: each of the ' + $c1asTrackedAsked + ' goal file(s) git tracks here and this checkout holds, copied into the fixture behind one failing file_exists item and evaluated by this tree''s evaluator as the Stop hook, PARSES -- no goal_parse entry, no goal_parse_error: key, that one item the only detector evaluated, nothing of the live goal run') `
    -Ok (($c1asTrackedAsked -gt 0) -and ($c1asTrackedParsed -eq $c1asTrackedAsked) -and ((Get-WnPorcelain -Root $c1asRoot) -ceq '?? scratch/')) `
    -Said ('parsed ' + $c1asTrackedParsed + ' of ' + $c1asTrackedAsked + ' asked (' + $c1asTracked.Count + ' tracked): ' + ($c1asTrackedSaid -join ' | '))

# (e) RULE 2: a `patterns` item is ONE FILE-NAME PATTERN. An item holding a bracket -- both, then each of the
#     two alone -- a slash or a backslash, each beside a good item that matches the one result in the
#     roster's directory. THE BASE reads two items and answers on what they match: the bracket item matches
#     nothing, in silence; and an item with a separator is FOLLOWED OUT OF THE ROSTER's DIRECTORY --
#     sub\x.yaml, one level down, is counted.
foreach ($c1asE in @(@{ id = 'G-WNAS-E1'; item = '[a]'; what = 'a bracket -- patterns: [[a], validator-A-9??.result.yaml]'; counted = 1
                        base = 'the bracket item matches nothing and nothing says so -- "1 of 1 required", the detector PASSES on the other item, MET' },
                     @{ id = 'G-WNAS-E4'; item = '[a'; what = 'the opening bracket ALONE -- patterns: [[a, validator-A-9??.result.yaml], the items `[a` and the good one'; counted = 1
                        base = 'the bracket item matches nothing and nothing says so -- "1 of 1 required", the detector PASSES on the other item, MET' },
                     @{ id = 'G-WNAS-E5'; item = 'a]'; what = 'the closing bracket ALONE -- patterns: [a], validator-A-9??.result.yaml], the items `a]` and the good one'; counted = 1
                        base = 'the bracket item matches nothing and nothing says so -- "1 of 1 required", the detector PASSES on the other item, MET' },
                     @{ id = 'G-WNAS-E2'; item = 'sub/x.yaml'; what = 'a path separator -- patterns: [sub/x.yaml, validator-A-9??.result.yaml]'; counted = 2
                        base = 'the base FOLLOWS THE SEPARATOR out of the roster''s directory -- sub\x.yaml, one level down, is COUNTED: "2 of 1 required", x.yaml=PASS beside the roster''s own result, MET' },
                     @{ id = 'G-WNAS-E3'; item = 'sub\x.yaml'; what = 'the other path separator -- patterns: [sub\x.yaml, validator-A-9??.result.yaml]'; counted = 2
                        base = 'the base FOLLOWS THE SEPARATOR out of the roster''s directory -- sub\x.yaml, one level down, is COUNTED: "2 of 1 required", x.yaml=PASS beside the roster''s own result, MET' })) {
    $c1asET = Get-C1asReading -GoalId $c1asE.id
    $c1asETRoster = Get-C1asEntry -Reading $c1asET -Type 'validator_pass_count'
    Add-C1asRow -Label ('(e) FALSIFIER RULE 2, an item holding ' + $c1asE.what + ': validator_pass_count FAILS BY NAME, naming the item -- "holds a bracket or a path separator: an item is one file-name pattern (register row 397)." -- NOT_MET, exit 1; no result is counted') `
        -Ok (($c1asET.verdict -ceq 'NOT_MET') -and ($c1asET.exit -eq 1) -and $c1asETRoster.found -and (-not $c1asETRoster.ok) -and $c1asETRoster.detail.Contains('validator_pass_count''s patterns item ''' + $c1asE.item + ''' ') -and
             $c1asETRoster.detail.Contains('holds a bracket or a path separator: an item is one file-name pattern (register row 397).') -and (-not $c1asETRoster.detail.Contains('=PASS'))) `
        -Said (Get-C1asSaid -Reading $c1asET)
    $c1asEB = Get-C1asReading -Tools base -GoalId $c1asE.id
    $c1asEBRoster = Get-C1asEntry -Reading $c1asEB -Type 'validator_pass_count'
    Add-C1asRow -Label ('(e) BASE CONTROL: the same goal -- ' + $c1asE.base + '; no word that an item was no pattern') `
        -Ok (($c1asEB.verdict -ceq 'MET') -and ($c1asEB.exit -eq 0) -and $c1asEBRoster.ok -and $c1asEBRoster.detail.StartsWith([string]$c1asE.counted + ' of 1 required validator result(s) are COMPLETE') -and $c1asEBRoster.detail.Contains($c1asResultName + '=PASS') -and
             ($c1asEBRoster.detail.Contains('[x.yaml=PASS, ') -eq ($c1asE.counted -eq 2)) -and (-not $c1asEBRoster.detail.Contains('register row 397'))) `
        -Said (Get-C1asSaid -Reading $c1asEB)
}

# (f) D15, BOTH HALVES, with a HALT on disk. THE HALT: <root>\.mission-runtime\halts\HALT-WNAS-01.md, its seat
#     marker ANSWERED and no halt-ruling gate over it -- the kind of HALT a goal's legacy_answered_allowlist
#     exists to answer, and the entry names it at its bytes. It is a FIXTURE HALT and no member of the
#     evaluator's frozen census: these members run this tree's evaluator and the base's AS THEY STAND, never a
#     copy with a census line added (C-1al (m)'s form), so spelled right the entry would be REPORTED and not
#     honoured. The rows measure the LADDER, which does not ask: with the key mis-spaced the base reads no
#     entry at all -- legacy_allowlist_report is [] -- and labels the stop HALT.
Set-PwBytes -Path (Join-Path $c1asHaltsDir 'HALT-WNAS-01.md') -Bytes $c1asHaltBytes
# (f1) THE FAULT IS ON A HALT-SCOPE KEY: legacy_answered_allowlist, then dir.
$c1asF1 = Get-C1asReading -GoalId 'G-WNAS-F1'
$c1asF1H = Get-C1asReading -GoalId 'G-WNAS-F1' -Hook
Add-C1asRow -Label '(f) FALSIFIER (f1) D15, THE FAULT ON A HALT-SCOPE KEY: halt_absent with `legacy_answered_allowlist : <the HALT>@<sha256>` (goal line 4), that HALT on disk: the fault OUTRANKS the HALT label -- by hand NOT_MET (not HALT), exit 1, ONE goal_parse entry naming line 4 and the key; as the Stop hook BLOCK, exit 0' `
    -Ok (($c1asF1.verdict -ceq 'NOT_MET') -and ($c1asF1.exit -eq 1) -and ($c1asF1.types.Count -eq 1) -and ($c1asF1.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asF1.parse -Line 4 -Raw $c1asF1Line -Key 'legacy_answered_allowlist') -and
         ($c1asF1H.decision -ceq 'block') -and ($c1asF1H.exit -eq 0) -and ($c1asF1H.verdict -ceq 'NOT_MET')) `
    -Said ((Get-C1asSaid -Reading $c1asF1) + ' | as the hook: ' + $c1asF1H.decision + ', exit ' + $c1asF1H.exit + ', ' + $c1asF1H.verdict + ' -- ' + $c1asF1H.reason)
$c1asF1B = Get-C1asReading -Tools base -GoalId 'G-WNAS-F1' -Hook
Add-C1asRow -Label '(f) BASE CONTROL: (f1) the same goal and HALT: the base skips the line, reads NO allowlist entry (legacy_allowlist_report: []), finds the HALT OPEN -- verdict HALT, and as the Stop hook it APPROVES, naming the HALT; no goal_parse entry, no goal_parse_error: key' `
    -Ok (($c1asF1B.verdict -ceq 'HALT') -and ($c1asF1B.decision -ceq 'approve') -and ($c1asF1B.exit -eq 0) -and $c1asF1B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and ($c1asF1B.parseCount -eq 0) -and (-not $c1asF1B.parseKey) -and
         [regex]::IsMatch($c1asF1B.text, '(?m)^legacy_allowlist_report: \[\]') -and [regex]::IsMatch($c1asF1B.text, '(?m)^halts_answered_by_legacy_allowlist: \[\]')) `
    -Said ((Get-C1asSaid -Reading $c1asF1B) + ' | reason: ' + $c1asF1B.reason)
$c1asF1D = Get-C1asReading -GoalId 'G-WNAS-F1D' -Hook
Add-C1asRow -Label '(f) FALSIFIER (f1) ... AND THE OTHER HALT-SCOPE KEY: halt_absent with `dir : custom-halts` (goal line 4), the same HALT on disk: as the Stop hook BLOCK, exit 0, verdict NOT_MET (not HALT), ONE goal_parse entry naming line 4 and the key dir' `
    -Ok (($c1asF1D.decision -ceq 'block') -and ($c1asF1D.exit -eq 0) -and ($c1asF1D.verdict -ceq 'NOT_MET') -and ($c1asF1D.types.Count -eq 1) -and ($c1asF1D.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asF1D.parse -Line 4 -Raw 'dir : custom-halts' -Key 'dir')) `
    -Said (Get-C1asSaid -Reading $c1asF1D)
$c1asF1DB = Get-C1asReading -Tools base -GoalId 'G-WNAS-F1D' -Hook
# THE DIR WAS NOT READ: halt_scan_roots names every root the scan read, one that is not on disk included, and
# the name the goal wrote stands nowhere in the artifact.
$c1asF1DBRoots = @(Get-PwListKey -Text $c1asF1DB.text -Key 'halt_scan_roots')
Add-C1asRow -Label '(f) BASE CONTROL: (f1) ... the same goal and HALT: the base skips the line -- the dir is NOT READ (halt_scan_roots names the two default planes and no custom-halts; the name stands nowhere in the artifact), verdict HALT, the Stop hook APPROVES; no goal_parse entry' `
    -Ok (($c1asF1DB.verdict -ceq 'HALT') -and ($c1asF1DB.decision -ceq 'approve') -and ($c1asF1DB.exit -eq 0) -and ($c1asF1DB.parseCount -eq 0) -and (-not $c1asF1DB.parseKey) -and
         ($c1asF1DBRoots.Count -eq 2) -and (-not $c1asF1DB.text.Contains('custom-halts'))) `
    -Said ((Get-C1asSaid -Reading $c1asF1DB) + ' | halt_scan_roots: ' + ($c1asF1DBRoots -join ' ; '))
# (f2) THE FAULT IS ON ANOTHER KEY: the base's ladder stands.
$c1asF2 = Get-C1asReading -GoalId 'G-WNAS-F2' -Hook
Add-C1asRow -Label '(f) FALSIFIER (f2) D15, THE FAULT ON ANOTHER KEY: a halt_absent spelled right, the same HALT open, and `count : 4` under validator_pass_count (goal line 6): verdict HALT STILL, the Stop hook APPROVES naming the HALT -- AND the artifact carries goal_parse_error: naming line 6 and the key count, the goal_parse entry beside it' `
    -Ok (($c1asF2.verdict -ceq 'HALT') -and ($c1asF2.decision -ceq 'approve') -and ($c1asF2.exit -eq 0) -and $c1asF2.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and $c1asF2.parseKey -and
         (Test-C1asNamed -Sentence $c1asF2.parseKeyText -Line 6 -Raw 'count : 4' -Key 'count') -and ($c1asF2.parseCount -eq 1)) `
    -Said ((Get-C1asSaid -Reading $c1asF2) + ' | goal_parse_error: ' + $(if ($c1asF2.parseKey) { $c1asF2.parseKeyText } else { '(no such key in the artifact)' }))
$c1asF2B = Get-C1asReading -Tools base -GoalId 'G-WNAS-F2' -Hook
Add-C1asRow -Label '(f) BASE CONTROL: (f2) the same goal and HALT: verdict HALT, the Stop hook APPROVES naming the HALT -- and NO goal_parse_error: key, no goal_parse entry: the dropped count is said nowhere' `
    -Ok (($c1asF2B.verdict -ceq 'HALT') -and ($c1asF2B.decision -ceq 'approve') -and ($c1asF2B.exit -eq 0) -and $c1asF2B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and (-not $c1asF2B.parseKey) -and ($c1asF2B.parseCount -eq 0)) `
    -Said (Get-C1asSaid -Reading $c1asF2B)
# (f3) THE FAULT IS ON A HALT-SCOPE KEY THAT OPENS ITS ITEM (the builder-side review's finding), the same
#     HALT still open in the default plane. `- legacy_answered_allowlist : <HALT>@<sha256>` -- or `- dir :
#     <dir>` -- with `type: halt_absent` on the line under it is a halt_absent item AS WRITTEN whose HALT-scope
#     key does not touch its colon. The reader takes no opener from it, so WHAT IT READS depends on what
#     stands above: nothing (the `type:` line is then stored nowhere and the goal has no item at all), or
#     another item (the `type:` line then lands on THAT item and renames it). The rule must not: in both
#     places the fault is on a HALT-scope key of a halt_absent item, and it outranks the HALT label.
foreach ($c1asF3One in $c1asF3) {
    $c1asF3T = Get-C1asReading -GoalId $c1asF3One.id -Hook
    Add-C1asRow -Label ('(f) FALSIFIER (f3) D15, THE FAULT ON A HALT-SCOPE KEY THAT OPENS ITS ITEM: `' + $c1asF3One.shown + '` with `type: halt_absent` under it, ' + $c1asF3One.where + ' (goal line ' + $c1asF3One.line + '), the same HALT open: as the Stop hook BLOCK, exit 0, verdict NOT_MET (not HALT), ONE goal_parse entry naming line ' + $c1asF3One.line + ' and the key ' + $c1asF3One.key) `
        -Ok (($c1asF3T.decision -ceq 'block') -and ($c1asF3T.exit -eq 0) -and ($c1asF3T.verdict -ceq 'NOT_MET') -and ($c1asF3T.types.Count -eq 1) -and ($c1asF3T.parseCount -eq 1) -and
             (Test-C1asNamed -Sentence $c1asF3T.parse -Line $c1asF3One.line -Raw $c1asF3One.raw -Key $c1asF3One.key)) `
        -Said (Get-C1asSaid -Reading $c1asF3T)
    $c1asF3B = Get-C1asReading -Tools base -GoalId $c1asF3One.id -Hook
    Add-C1asRow -Label ('(f) BASE CONTROL: (f3) the same goal and HALT at the base: the line is skipped and no line is named -- verdict HALT, the Stop hook APPROVES naming the HALT') `
        -Ok (($c1asF3B.verdict -ceq 'HALT') -and ($c1asF3B.decision -ceq 'approve') -and ($c1asF3B.exit -eq 0) -and $c1asF3B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and
             (-not $c1asF3B.parse.Contains('does not touch its colon')) -and (-not [regex]::IsMatch($c1asF3B.parse, 'line \d+: '))) `
        -Said ((Get-C1asSaid -Reading $c1asF3B) + ' | reason: ' + $c1asF3B.reason)
}
# (f4) STATED, NOT CLAIMED -- THE HALT-SCOPE RULING's OTHER HALF. The operator's ruling speaks of a fault ON `dir` or
#     `legacy_answered_allowlist`. Where the HALT-scope key touches its colon and it is the item's `type` that
#     does not -- the opener `- type : halt_absent`, or `type : halt_absent` under a well-spelled opener --
#     the fault is on the key `type`: it is named, the goal does not parse, and the base's ladder stands. The
#     item is then no halt_absent item to the reader, its allowlist answers nothing, the HALT reads OPEN and
#     the hook APPROVES. Recorded, not built.
$c1asF4A = Get-C1asReading -GoalId 'G-WNAS-F4A' -Hook
Add-C1asRow -Label '(f) STATED, NOT CLAIMED (f4) THE HALT-SCOPE RULING''s OTHER HALF: the opener `- type : halt_absent` (goal line 3) with `legacy_answered_allowlist: <the HALT>@<sha256>` spelled right under it, the same HALT open -- the fault is on the key type, not on a HALT-scope key: verdict HALT, the Stop hook APPROVES naming the HALT, goal_parse_error: naming line 3 and the key type, the goal_parse entry beside it' `
    -Ok (($c1asF4A.verdict -ceq 'HALT') -and ($c1asF4A.decision -ceq 'approve') -and ($c1asF4A.exit -eq 0) -and $c1asF4A.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and $c1asF4A.parseKey -and
         (Test-C1asNamed -Sentence $c1asF4A.parseKeyText -Line 3 -Raw '- type : halt_absent' -Key 'type') -and ($c1asF4A.parseCount -eq 1)) `
    -Said ((Get-C1asSaid -Reading $c1asF4A) + ' | goal_parse_error: ' + $(if ($c1asF4A.parseKey) { $c1asF4A.parseKeyText } else { '(no such key in the artifact)' }))
$c1asF4B = Get-C1asReading -GoalId 'G-WNAS-F4B' -Hook
Add-C1asRow -Label '(f) STATED, NOT CLAIMED (f4) ... and the opener `- legacy_answered_allowlist: <the HALT>@<sha256>` spelled right, with `type : halt_absent` under it (goal line 4), the same HALT open -- again the fault is on the key type: verdict HALT, the Stop hook APPROVES naming the HALT, goal_parse_error: naming line 4 and the key type, the goal_parse entry beside it' `
    -Ok (($c1asF4B.verdict -ceq 'HALT') -and ($c1asF4B.decision -ceq 'approve') -and ($c1asF4B.exit -eq 0) -and $c1asF4B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and $c1asF4B.parseKey -and
         (Test-C1asNamed -Sentence $c1asF4B.parseKeyText -Line 4 -Raw 'type : halt_absent' -Key 'type') -and ($c1asF4B.parseCount -eq 1)) `
    -Said ((Get-C1asSaid -Reading $c1asF4B) + ' | goal_parse_error: ' + $(if ($c1asF4B.parseKey) { $c1asF4B.parseKeyText } else { '(no such key in the artifact)' }))
# (f5) D15, THE ITEM AS WRITTEN, FOR A FAULTED KEY LINE TOO (the independent validator's round 1),
#     the same HALT still open in the default plane. (f3) is the fault on the item's own OPENER; here it is on
#     a HALT-scope KEY LINE, inside an item that as written is a halt_absent and as the reader reads it is not
#     -- its `type` line is mis-spaced too, as the opener or as a key line, so the reader takes no
#     halt_absent from it: the HALT-scope line then falls in no item, in the unrelated item above, or in an
#     item the reader gave no type. The ruling's words reach all four: the fault IS on `dir` or
#     `legacy_answered_allowlist`, under an item the goal wrote as halt_absent, and a HALT label would be
#     derived from a scope the goal did not write. THE RULE THE ROWS HOLD THE EVALUATOR TO: the item is the
#     one AS WRITTEN -- from an opener line, stored or mis-spaced, to the next opener or the list's end --
#     and it is a halt_absent item where any `type` line in it, stored or mis-spaced, reads halt_absent.
#     WHAT SEPARATES THESE FROM (f4): there the ONLY fault is on the key `type` -- the HALT-scope key touches
#     its colon -- and the ladder stands; here a HALT-scope key is faulted too.
foreach ($c1asF5One in $c1asF5) {
    $c1asF5T = Get-C1asReading -GoalId $c1asF5One.id
    $c1asF5H = Get-C1asReading -GoalId $c1asF5One.id -Hook
    Add-C1asRow -Label ('(f) FALSIFIER (f5) D15, THE ITEM AS WRITTEN, THE FAULT ON A HALT-SCOPE KEY LINE: ' + $c1asF5One.shown + ', ' + $c1asF5One.where + ', the same HALT open: the fault on ' + $c1asF5One.key + ' (goal line ' + $c1asF5One.line + ') OUTRANKS the HALT label -- by hand NOT_MET (not HALT), exit 1, ONE entry and it is goal_parse, naming line ' + $c1asF5One.line + ' and the key ' + $c1asF5One.key + '; as the Stop hook BLOCK, exit 0, NOT_MET, the same line named') `
        -Ok (($c1asF5T.verdict -ceq 'NOT_MET') -and ($c1asF5T.exit -eq 1) -and ($c1asF5T.types.Count -eq 1) -and ($c1asF5T.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asF5T.parse -Line $c1asF5One.line -Raw $c1asF5One.raw -Key $c1asF5One.key) -and
             ($c1asF5H.decision -ceq 'block') -and ($c1asF5H.exit -eq 0) -and ($c1asF5H.verdict -ceq 'NOT_MET') -and ($c1asF5H.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asF5H.parse -Line $c1asF5One.line -Raw $c1asF5One.raw -Key $c1asF5One.key)) `
        -Said ((Get-C1asSaid -Reading $c1asF5T) + ' | as the hook: ' + $(if ($c1asF5H.decision) { $c1asF5H.decision } else { '(no decision)' }) + ', exit ' + $c1asF5H.exit + ', ' + $c1asF5H.verdict + ' -- ' + $c1asF5H.reason)
    $c1asF5B = Get-C1asReading -Tools base -GoalId $c1asF5One.id -Hook
    Add-C1asRow -Label ('(f) BASE CONTROL: (f5) the same goal and HALT at the base: the mis-spaced lines are skipped and no line is named -- verdict HALT, the Stop hook APPROVES naming the HALT') `
        -Ok (($c1asF5B.verdict -ceq 'HALT') -and ($c1asF5B.decision -ceq 'approve') -and ($c1asF5B.exit -eq 0) -and $c1asF5B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and (-not $c1asF5B.parseKey) -and
             (-not $c1asF5B.parse.Contains('does not touch its colon')) -and (-not [regex]::IsMatch($c1asF5B.parse, 'line \d+: '))) `
        -Said ((Get-C1asSaid -Reading $c1asF5B) + ' | reason: ' + $c1asF5B.reason)
}
# (f6) CONTROL -- THE ITEM AS READ IS STILL ASKED, FOR A FAULTED KEY LINE, the same HALT still open in the
#     default plane. The rows of (f5) are what the item AS WRITTEN adds; this row is what it must not take
#     away. `dir : custom-halts` stands under a mis-spaced opener of its own, `- path : inputs/a.txt`: as
#     written, in an item with no `type` line; as the reader reads it, in the halt_absent above -- the fault
#     is on a HALT-scope key of an item the reader reads as halt_absent, and the goal was refused before
#     (f5)'s cure. IT HAS NO RED OF ITS OWN: the evaluator as it was committed before that cure
#     blocks it too. Its reason to exist is the cure's first form, which judged a faulted key line by the
#     item as written ALONE and APPROVED this goal under the HALT -- measured by a probe over that form,
#     not by this instrument -- an allow-side move the cure of a finding must not make. The base, which
#     faults no line, reads HALT and approves.
$c1asF6T = Get-C1asReading -GoalId 'G-WNAS-F6' -Hook
Add-C1asRow -Label ('(f) CONTROL (f6) D15, THE ITEM AS READ, KEPT FOR A FAULTED KEY LINE: a halt_absent spelled right, then a MIS-SPACED opener `- path : inputs/a.txt` with `dir : custom-halts` under it (goal line ' + $c1asF6DirAt + '), a valid file_exists item after it, the same HALT open -- as written the dir line stands in an item with no type line, as the reader reads it it falls in the halt_absent: as the Stop hook BLOCK, exit 0, verdict NOT_MET (not HALT), ONE goal_parse entry naming line ' + $c1asF6DirAt + ' and the key dir -- as before (f5)''s cure; a cure that judged a faulted key line by the item as written ALONE approved it under the HALT') `
    -Ok (($c1asF6T.decision -ceq 'block') -and ($c1asF6T.exit -eq 0) -and ($c1asF6T.verdict -ceq 'NOT_MET') -and ($c1asF6T.types.Count -eq 1) -and ($c1asF6T.parseCount -eq 1) -and
         (Test-C1asNamed -Sentence $c1asF6T.parse -Line $c1asF6DirAt -Raw $c1asF6Dir -Key 'dir')) `
    -Said (Get-C1asSaid -Reading $c1asF6T)
$c1asF6B = Get-C1asReading -Tools base -GoalId 'G-WNAS-F6' -Hook
Add-C1asRow -Label '(f) BASE CONTROL: (f6) the same goal and HALT at the base: the two mis-spaced lines are skipped and no line is named -- verdict HALT, the Stop hook APPROVES naming the HALT' `
    -Ok (($c1asF6B.verdict -ceq 'HALT') -and ($c1asF6B.decision -ceq 'approve') -and ($c1asF6B.exit -eq 0) -and $c1asF6B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and (-not $c1asF6B.parseKey) -and
         (-not $c1asF6B.parse.Contains('does not touch its colon')) -and (-not [regex]::IsMatch($c1asF6B.parse, 'line \d+: '))) `
    -Said ((Get-C1asSaid -Reading $c1asF6B) + ' | reason: ' + $c1asF6B.reason)
# (f7) CONTROL -- THE EXCEPTION's OTHER BOUNDARY (the independent validator's round 2), the same HALT
#     still open in the default plane. The operator's ruling lets a fault outrank the HALT label "ONLY where the fault
#     is ON a halt-scope key (dir, legacy_answered_allowlist under halt_absent)" -- and `dir` is a key of
#     validator_pass_count as well. Here the goal's halt_absent is spelled right, and the `dir` that does not
#     touch its colon stands in a validator_pass_count item: as written and as the reader reads it, that
#     item is no halt_absent, the scope a HALT is derived over is the scope the goal wrote, and the label
#     stands -- HALT, the hook approves, the fault named on the artifact beside it. Until this row no row
#     held that boundary: (f2) faults `count`, and (a)'s row for `dir`, under a validator_pass_count, is
#     read with no HALT on disk. A cure that set the flag on ANY fault whose key is NAMED dir or
#     legacy_answered_allowlist would block here a stop the ruling still admits -- and, as that finding
#     has it, would read every other row ok. IT HAS NO RED OF RECORD AND NEEDS NONE: the evaluator reads
#     it ok as committed, and so it is a CONTROL. The base, which faults no line, reads HALT
#     and approves.
$c1asF7T = Get-C1asReading -GoalId 'G-WNAS-F7' -Hook
Add-C1asRow -Label ('(f) CONTROL (f7) D15''s OTHER BOUNDARY, A KEY NAMED dir THAT IS NO HALT-SCOPE KEY: a halt_absent spelled right, then a validator_pass_count item spelled right but for `dir : scratch/results` (goal line ' + $c1asF7DirAt + '), its count and its pattern touching their colons, the same HALT open -- the fault is on a key NAMED dir, in an item that is a validator_pass_count as written AND as read, so the ruling''s exception does not reach it: verdict HALT STILL, the Stop hook APPROVES naming the HALT -- AND the artifact carries goal_parse_error: naming line ' + $c1asF7DirAt + ' and the key dir, the goal_parse entry beside it; a cure that set the flag on any fault whose key is named dir would block this stop') `
    -Ok (($c1asF7T.verdict -ceq 'HALT') -and ($c1asF7T.decision -ceq 'approve') -and ($c1asF7T.exit -eq 0) -and $c1asF7T.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and $c1asF7T.parseKey -and
         (Test-C1asNamed -Sentence $c1asF7T.parseKeyText -Line $c1asF7DirAt -Raw $c1asF7Dir -Key 'dir') -and ($c1asF7T.parseCount -eq 1) -and (Test-C1asNamed -Sentence $c1asF7T.parse -Line $c1asF7DirAt -Raw $c1asF7Dir -Key 'dir')) `
    -Said ((Get-C1asSaid -Reading $c1asF7T) + ' | goal_parse_error: ' + $(if ($c1asF7T.parseKey) { $c1asF7T.parseKeyText } else { '(no such key in the artifact)' }) + ' | reason: ' + $c1asF7T.reason)
$c1asF7B = Get-C1asReading -Tools base -GoalId 'G-WNAS-F7' -Hook
Add-C1asRow -Label '(f) BASE CONTROL: (f7) the same goal and HALT at the base: the mis-spaced line is skipped and no line is named -- verdict HALT, the Stop hook APPROVES naming the HALT' `
    -Ok (($c1asF7B.verdict -ceq 'HALT') -and ($c1asF7B.decision -ceq 'approve') -and ($c1asF7B.exit -eq 0) -and $c1asF7B.reason.Contains('derives HALT: unanswered HALT-WNAS-01.md') -and (-not $c1asF7B.parseKey) -and
         (-not $c1asF7B.parse.Contains('does not touch its colon')) -and (-not [regex]::IsMatch($c1asF7B.parse, 'line \d+: '))) `
    -Said ((Get-C1asSaid -Reading $c1asF7B) + ' | reason: ' + $c1asF7B.reason)
Remove-Item -LiteralPath $c1asHaltsDir -Recurse -Force
# (f2) ... AND "THE HALT SCOPE AS READ" (D15's own words), measured where it can be lost. The default plane's
#     HALT is gone; the ONE HALT now on disk, HALT-WNAS-02.md (OPEN, no marker to answer it), lives in a
#     directory only the goal names -- its halt_absent declares `dir: scratch/halts-declared`, spelled right
#     -- and the fault is again `count : 4`, on another item. A goal that does not parse runs no detector,
#     and its declared dir is STILL where the scan looks: the HALT reads OPEN, the verdict is HALT, the hook
#     approves, the refusal on the artifact beside it. (The rule runs ahead of the line that keeps the
#     detectors as read for the scope; a cure that emptied them first would scan the default planes alone,
#     find nothing, read NOT_MET and BLOCK a stop only the operator can settle. The (f2) row above cannot
#     see that: its HALT stands in a default plane.)
$c1asDeclaredDir = Join-Path $c1asRoot 'scratch\halts-declared'
Set-PwBytes -Path (Join-Path $c1asDeclaredDir 'HALT-WNAS-02.md') -Bytes ($pwUtf8.GetBytes("# HALT-WNAS-02`n`n**Status:** OPEN`n"))
$c1asScopeFixture = ((-not (Test-Path -LiteralPath $c1asHaltsDir)) -and ((Get-WnPorcelain -Root $c1asRoot) -ceq '?? scratch/'))
$c1asF2S = Get-C1asReading -GoalId 'G-WNAS-F2S' -Hook
Add-C1asRow -Label '(f) FALSIFIER (f2) ... AND THE HALT SCOPE IS THE SCOPE AS READ: the default plane now holds no HALT; halt_absent declares `dir: scratch/halts-declared` (spelled right), the one HALT on disk lives there, and `count : 4` stands under validator_pass_count (goal line 7): the declared dir is STILL scanned -- verdict HALT, the Stop hook APPROVES naming HALT-WNAS-02.md -- AND the artifact carries goal_parse_error: naming line 7 and the key count, the goal_parse entry beside it' `
    -Ok ($c1asScopeFixture -and ($c1asF2S.verdict -ceq 'HALT') -and ($c1asF2S.decision -ceq 'approve') -and ($c1asF2S.exit -eq 0) -and $c1asF2S.reason.Contains('derives HALT: unanswered HALT-WNAS-02.md') -and $c1asF2S.parseKey -and
         (Test-C1asNamed -Sentence $c1asF2S.parseKeyText -Line 7 -Raw 'count : 4' -Key 'count') -and ($c1asF2S.parseCount -eq 1)) `
    -Said ((Get-C1asSaid -Reading $c1asF2S) + ' | goal_parse_error: ' + $(if ($c1asF2S.parseKey) { $c1asF2S.parseKeyText } else { '(no such key in the artifact)' }) + ' | halt_scan_roots: ' + (@(Get-PwListKey -Text $c1asF2S.text -Key 'halt_scan_roots') -join ' ; '))
$c1asF2SB = Get-C1asReading -Tools base -GoalId 'G-WNAS-F2S' -Hook
$c1asF2SBRoots = @(Get-PwListKey -Text $c1asF2SB.text -Key 'halt_scan_roots')
Add-C1asRow -Label '(f) BASE CONTROL: (f2) ... the same goal, the same one HALT in the declared dir: the base reads the dir (halt_scan_roots names it, third, after the two default planes), finds the HALT there -- verdict HALT, the Stop hook APPROVES naming HALT-WNAS-02.md -- and NO goal_parse_error: key, no goal_parse entry' `
    -Ok ($c1asScopeFixture -and ($c1asF2SB.verdict -ceq 'HALT') -and ($c1asF2SB.decision -ceq 'approve') -and ($c1asF2SB.exit -eq 0) -and $c1asF2SB.reason.Contains('derives HALT: unanswered HALT-WNAS-02.md') -and (-not $c1asF2SB.parseKey) -and ($c1asF2SB.parseCount -eq 0) -and
         ($c1asF2SBRoots.Count -eq 3) -and ([string]$c1asF2SBRoots[2]).EndsWith('\scratch\halts-declared')) `
    -Said ((Get-C1asSaid -Reading $c1asF2SB) + ' | reason: ' + $c1asF2SB.reason + ' | halt_scan_roots: ' + ($c1asF2SBRoots -join ' ; '))
Remove-Item -LiteralPath $c1asDeclaredDir -Recurse -Force

# (g) STATED, NOT CLAIMED (D1 (ii)): three shapes the rule does NOT reach, each as the base has it.
$c1asG1 = Get-C1asReading -GoalId 'G-WNAS-G1'
$c1asG1B = Get-C1asReading -Tools base -GoalId 'G-WNAS-G1'
$c1asG1Roster = Get-C1asEntry -Reading $c1asG1 -Type 'validator_pass_count'
$c1asG1Same = ((Get-WnComparable -Text (Remove-WrProvenanceLine -Text $c1asG1.text)) -ceq (Get-WnComparable -Text $c1asG1B.text))
Add-C1asRow -Label '(g) STATED, NOT CLAIMED: a MISSPELLED key, `cuont: 4`: stored and read by nobody -- the roster needs the default ONE, "1 of 1 required", MET on one result where four were meant; no goal_parse entry; the artifact EQUAL to the base''s but for the clock' `
    -Ok (($c1asG1.verdict -ceq 'MET') -and ($c1asG1.parseCount -eq 0) -and (-not $c1asG1.parseKey) -and $c1asG1Roster.ok -and $c1asG1Roster.detail.StartsWith('1 of 1 required validator result(s) are COMPLETE') -and ($c1asG1B.verdict -ceq 'MET') -and $c1asG1Same) `
    -Said ((Get-C1asSaid -Reading $c1asG1) + ' | base: ' + $c1asG1B.verdict + '; artifacts equal: ' + $c1asG1Same)
$c1asG2 = Get-C1asReading -GoalId 'G-WNAS-G2'
$c1asG2B = Get-C1asReading -Tools base -GoalId 'G-WNAS-G2'
$c1asG2Same = ((Get-WnComparable -Text (Remove-WrProvenanceLine -Text $c1asG2.text)) -ceq (Get-WnComparable -Text $c1asG2B.text))
Add-C1asRow -Label '(g) STATED, NOT CLAIMED: a key-shaped line at COLUMN 0 (`note: x`) between two items: it ENDS the list -- the instrument_exit0 item after it is not read and not run (ONE entry, file_exists; the stub''s counter unmoved), MET; no goal_parse entry; the artifact EQUAL to the base''s but for the clock' `
    -Ok (($c1asG2.verdict -ceq 'MET') -and ($c1asG2.parseCount -eq 0) -and (-not $c1asG2.parseKey) -and (($c1asG2.types -join ',') -ceq 'file_exists') -and ($c1asG2.ran -eq 0) -and ($c1asG2B.ran -eq 0) -and ($c1asG2B.verdict -ceq 'MET') -and $c1asG2Same) `
    -Said ((Get-C1asSaid -Reading $c1asG2) + ' | base: ' + $c1asG2B.verdict + ', the stub ran ' + $c1asG2B.ran + '; artifacts equal: ' + $c1asG2Same)
$c1asG3 = Get-C1asReading -GoalId 'G-WNAS-G3'
$c1asG3B = Get-C1asReading -Tools base -GoalId 'G-WNAS-G3'
$c1asG3Same = ((Get-WnComparable -Text $c1asG3.text) -ceq (Get-WnComparable -Text $c1asG3B.text))
Add-C1asRow -Label '(g) RE-ASSERTED BY BATCH-6 WP-Q: a QUOTED opener, `- "type": file_exists`, after an item whose file is ABSENT: the base skips it and the path under it LANDS ON THE ITEM BEFORE IT -- ONE entry, MET where the first item was meant to fail; at this tree the line is no key and no list opener, and the goal DOES NOT PARSE -- NOT_MET, ONE goal_parse entry naming line 5 as written' `
    -Ok (($c1asG3.verdict -ceq 'NOT_MET') -and ($c1asG3.parseCount -eq 1) -and (@($c1asG3.types | Where-Object { $_ -ceq 'file_exists' }).Count -eq 0) -and
         $c1asG3.parse.Contains('a line inside its detectors list is no key, no list opener, no blank and no comment -- line 5: `  - "type": file_exists` -- ') -and $c1asG3.parse.Contains('(register row 424)') -and
         ($c1asG3B.verdict -ceq 'MET') -and ($c1asG3B.parseCount -eq 0) -and (($c1asG3B.types -join ',') -ceq 'file_exists') -and $c1asG3B.entries[0].detail.StartsWith('inputs/a.txt exists=True ')) `
    -Said ((Get-C1asSaid -Reading $c1asG3) + ' | base: ' + $c1asG3B.verdict + '; the base''s entry: ' + [string]$c1asG3B.entries[0].detail)

# (h) RULE 1 IS BY SHAPE, AND ASKS FOR NO TABLE OF KEYS (the independent validator's round 3).
#     Every mis-spaced key the rows above write is one the contract declares (twenty then; twenty-two since
#     BATCH-7 WP-R), so a finder that faulted only those BY NAME read every one of them ok -- the
#     validator's mutation run drove that
#     wrong cure, not us, and no row then standing saw it. Here the key is one NO type reads and no table
#     holds: `cuont`, the misspelled key of (g)'s first row -- that row, `cuont: 4` touching its colon, is
#     this one's control: stored, read by nobody, no fault -- and `zzz_new_key` as an item's opener. Written
#     key, blank, colon, each is a goal that does not parse, the line and the key named; at the base each
#     line is skipped in silence. FALSIFIERS as (a)'s and (b)'s are -- RED at the base, kept beside each --
#     and they read ok at this tree when they were written: the rule was by shape already.
foreach ($c1asByShapeOne in $c1asByShape) {
    $c1asHT = Get-C1asReading -GoalId $c1asByShapeOne.id
    Add-C1asRow -Label ('(h) FALSIFIER RULE 1 IS BY SHAPE, A KEY NO TYPE READS: ' + $c1asByShapeOne.shown + ' (goal line ' + $c1asByShapeOne.line + '): NOT_MET, exit 1, ONE entry and it is goal_parse, failing, naming line ' + $c1asByShapeOne.line + ', the line as written and "the key ' + $c1asByShapeOne.key + ' does not touch its colon"; no detector ran; a finder that faulted only the declared keys by name (twenty-two since BATCH-7 WP-R) would read this goal as the base does (the independent validator''s round 3)') `
        -Ok (($c1asHT.verdict -ceq 'NOT_MET') -and ($c1asHT.exit -eq 1) -and ($c1asHT.types.Count -eq 1) -and ($c1asHT.parseCount -eq 1) -and (-not $c1asHT.entries[0].ok) -and
             (Test-C1asNamed -Sentence $c1asHT.parse -Line $c1asByShapeOne.line -Raw $c1asByShapeOne.raw -Key $c1asByShapeOne.key) -and ($c1asHT.ran -eq 0)) `
        -Said (Get-C1asSaid -Reading $c1asHT)
    $c1asHB = Get-C1asReading -Tools base -GoalId $c1asByShapeOne.id
    Add-C1asRow -Label ('(h) BASE CONTROL: the same goal: ' + $c1asByShapeOne.base + ', no goal_parse entry, no goal_parse_error: key, no line named') `
        -Ok (($c1asHB.verdict -ceq 'MET') -and ($c1asHB.exit -eq 0) -and ($c1asHB.parseCount -eq 0) -and (-not $c1asHB.parseKey) -and (-not $c1asHB.text.Contains('does not touch its colon')) -and
             $(if ($c1asByShapeOne.key -ceq 'cuont') { (($c1asHB.types -join ',') -ceq 'validator_pass_count') -and (Get-C1asEntry -Reading $c1asHB -Type 'validator_pass_count').detail.StartsWith('1 of 1 required validator result(s) are COMPLETE') }
               else { (($c1asHB.types -join ',') -ceq 'file_exists') -and $c1asHB.entries[0].detail.StartsWith('inputs/a.txt exists=True ') })) `
        -Said (Get-C1asSaid -Reading $c1asHB)
}
}
catch {
    $c1asOk = $false
    $c1asRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1asRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1asM) { Remove-PwTreeAsWritten -Base $c1asM.base }
Check -Id 'C-1as' -Title 'THE READER''s GRAMMAR (the BATCH-5 charter; the operator''s rulings D1 and D15 of 2026-10-11): at the base evaluator a key that does not touch its colon is a line the reader skips, the key then absent and the type''s default read in silence -- `reuse_within_minutes : 30` reads no window and the instrument runs, `count : 4` asks for one result and passes on one, `engine_read : docker_pipe` is stored nowhere, an opener written `- type : <t>` opens no item (alone, "it declares no detectors" with no line named; after an item, its keys land on that item), and a halt_absent''s `legacy_answered_allowlist : <HALT>@<sha256>` or `dir : <d>` is not read, the HALT reads OPEN and the Stop hook approves; at this tree each of the twenty-two declared keys written so (reuse_tree_within_minutes the twenty-first, since BATCH-6 WP-Q; require_owned the twenty-second, since BATCH-7 WP-R), and the opener, is a goal that DOES NOT PARSE -- NOT_MET, exit 1, one failing goal_parse entry naming the line, the line as written and the key, no detector run, the instrument included; on a HALT-scope key of a halt_absent item the fault outranks the HALT label -- NOT_MET with the HALT open, the hook blocks -- also where that key OPENS its item (`- dir : <d>` or `- legacy_answered_allowlist : <e>` with `type: halt_absent` under it), as the goal''s first item or after another one (the builder-side review''s finding), and where it is a KEY LINE of an item that is a halt_absent only AS WRITTEN, the item''s `type` line mis-spaced too -- as its opener, or under a well-spelled opener on `dir` or the allowlist (the independent validator''s round 1), the item as the reader read it STILL asked as well for a faulted key line, so that a `dir` line under a mis-spaced opener of its own, which the reader puts in the halt_absent above it, blocks as it did before that cure -- while on any other key an open HALT still reads HALT and the hook approves -- one that lives in a dir the goal declares among them, the HALT scope being the scope as read, and a key NAMED dir that is a validator_pass_count''s own among them, mis-spaced beside a halt_absent spelled right: the exception ends where the ruling ends it, under halt_absent (the independent validator''s round 2); and, stated and not built, the key `type` of a halt_absent item among them, its HALT-scope key spelled right -- goal_parse_error on the artifact naming the line; a patterns item holding a bracket or a path separator fails validator_pass_count by name, where the base read two items and passed on what they matched; the earlier rule as it stood -- a free-text line, a hyphenated key, a bare list item and a quoted key inside the list skipped -- is re-asserted by BATCH-6 WP-Q: the goal does not parse at this tree, one goal_parse entry naming the lines, where the base skips them; Read-GoalDetectors is not edited and returns the base''s items for every tracked goal, the rule is a function of its own beside it, and no tracked goal is faulted by it; the rule is BY SHAPE and holds no table of keys -- a key no type reads, `cuont : 4` as a key line and `- zzz_new_key : 1` as an opener, is each a goal that does not parse, the line and the key named, where the base skips each in silence (the independent validator''s round 3); and, stated and not claimed, a misspelled key still reads the default, a key-shaped line at column 0 still ends the list, and a quoted opener -- which the base still hands its keys to the item before it -- is, at this tree, re-asserted by BATCH-6 WP-Q, a goal that does not parse' `
      -Ok $c1asOk -Detail ("      THE $(@($c1asRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1asRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument every instrument_exit0 item here names:`n" + (Get-WlIndented -Text $wnStubText))

# =============================================================================================
# C-1at -- THE KEPT COPIES, LISTED: a MET verdict under a reuse window lists every kept
#          copy that stands under instrument-runs -- by leaf, under every run key -- and says of each
#          whether its bytes still hash to its name: instrument_captures_kept_on_disk
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a verdict that reuses a
# capture names the ONE copy it kept (instrument_captures_kept) and says nothing of what
# else stands under instrument-runs at a kept name -- an earlier copy, one whose bytes were changed under
# its name, one that cannot be read, a directory, a copy under another run key. The kept copies only grow
# (Save-InstrumentReusedCapture says so), and no verdict says which of them still hash to their names.
# THE RULE: where the verdict is MET and some instrument_exit0 declares a window above 0, the artifact
# carries one more top-level key, instrument_captures_kept_on_disk, directly after instrument_captures_kept:
# for each instrument_exit0 detector's instrument EVERY name under instrument-runs that matches
# ^.+\.<token(leaf)>\.[0-9a-f]{8}\.stdout\.txt$ -- BY LEAF, UNDER EVERY RUN KEY, directories included, and
# read WITHOUT REGARD TO CASE (the paragraphs on the leaf and on every other part, below, say why) --
# sorted by name ordinally, each examined in its own try, one item each:
#   <full path> sha256 <64 hex>                                      its bytes hash to its name
#   <full path> sha256 <64 hex> -- MISMATCH: the name says <8 hex>   they do not
#   <full path> -- UNREADABLE: <why, one line>                       it could not be read
#   <full path> -- NOT A FILE                                        a directory stands there
# and `[]` when there is none. THE LISTING NEVER THROWS and never changes the verdict.
# THE CONTROLS, each a row: over the same directory the base writes no such key; a verdict that is NOT MET
# does not carry it; a goal that declares no window writes the artifact the base writes, byte for byte but
# for the clock; a goal that declares the window 0 writes none of the reuse keys. AND WHAT IS STATED, NOT
# CLAIMED: the listing reads a name and a digest, never a capture -- a file of other bytes standing at a kept
# name that is THEIR OWN sha8 lists clean.
# AND THE LEAF IS MATCHED AS A REUSE FINDS ITS CANDIDATES, CASE FOLDED (the independent validator's round 3,
# row (f)): a capture is named after its instrument's leaf AS THE PATH WAS GIVEN to the helper, and
# a reuse finds it whatever the case of that leaf -- so the listing holds the copy a verdict kept and cites
# where the capture was taken with the instrument's path spelled in another case. Row (f) is a falsifier of
# its own: it read RED over the listing as it was first built, which matched the leaf case-sensitively.
# AND SO IS EVERY OTHER PART OF THE NAME (rows (g), two CONTROLS with no RED of record): the evaluator asks
# whether a kept name is taken with File.Exists, which folds case, so the listing reads the whole form
# without regard to case -- the item still the name as the directory holds it, the sha8 still held to the
# eight hex AS WRITTEN. A name with its hex in upper case is listed and reads MISMATCH, never clean; a name
# with its tail in upper case, its hex lower-case and true, lists clean; and a file standing at the kept
# copy's own name with upper-case hex, which the verdict cites as already kept, has its item.
# THE SCENE OF ROW (a) IS BUILT SO THAT A LISTING WRONG IN ONE WAY READS RED: the copy that cannot be read is
# never the last name (one try round the whole loop would lose the names after it); a directory stands
# between two files; a lower-case run key sorts last by an ordinal comparer and by no other; and two files
# that are NOT kept names of this leaf -- another leaf's, and eight characters that are not hex -- stand
# beside the six and must be listed nowhere.
# THE FIXTURE is the batch's (New-WnMission): the stub under the one admitted prefix, the goals committed.
# G-WNAT declares the instrument with reuse_within_minutes 30 and, after it, a file_exists detector over an
# untracked file under that same prefix -- removing the file turns the verdict NOT_MET with the tree still
# clean and the instrument still reused; G-WNOTHER declares the instrument with no window; G-WNAT-ZERO, an
# id of this member's own beginning G-WN, declares it with reuse_within_minutes 0. Every capture here is
# taken by Save-LamInstrumentRun over the stub (New-WnCapture) and EVERY ONE IS GREEN: no row of this member
# stands a RED capture on disk, so the rule that a RED is never stepped over never fires here.
$c1atOk = $true
$c1atRows = New-Object System.Collections.Generic.List[string]
function Add-C1atRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1atOk = $false }
    $script:c1atRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1atRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function New-C1atCapture {
    # One hand capture of the stub by THIS TREE's helper (New-WnCapture), GREEN -- or a throw that says which
    # one was not taken: every row below stands on these. -Age rewrites its captured_at to that many seconds ago.
    param([string]$RunKey, [string]$GoalId = '', [int]$Age = 0)
    $c1atNcArgs = @{ Tools = 'tree'; Root = $script:c1atRoot; Key = $RunKey }
    if ($GoalId) { $c1atNcArgs['Goal'] = $GoalId }
    if ($Age -gt 0) { $c1atNcArgs['AgeSeconds'] = $Age }
    $c1atNc = New-WnCapture @c1atNcArgs
    if ((-not $c1atNc.ok) -or ($c1atNc.exit -ne 0)) { throw ('FIXTURE REFUSED: the hand capture under run key ' + $RunKey + ' was not taken GREEN: ok ' + $c1atNc.ok + ', exit ' + $c1atNc.exit + ' [' + $c1atNc.why + ']') }
    return $c1atNc
}
function Copy-C1atKept {
    # A KEPT COPY MADE BY HAND, as the evaluator's own keep names one: the bytes that stand
    # at -Live, a <key>.<leaf>.stdout.txt capture, written beside it as <key>.<leaf>.<first eight hex of THEIR
    # sha256>.stdout.txt. Returns name, path, sha256 (of the bytes copied) and said8 (the eight hex in the name).
    param([string]$Live)
    $c1atCkBytes = [System.IO.File]::ReadAllBytes($Live)
    $c1atCkSha = Get-PwSha256 -Bytes $c1atCkBytes
    $c1atCkLeaf = [System.IO.Path]::GetFileName($Live)
    $c1atCkName = $c1atCkLeaf.Substring(0, $c1atCkLeaf.Length - '.stdout.txt'.Length) + '.' + $c1atCkSha.Substring(0, 8) + '.stdout.txt'
    $c1atCkPath = Join-Path ([System.IO.Path]::GetDirectoryName($Live)) $c1atCkName
    [System.IO.File]::WriteAllBytes($c1atCkPath, $c1atCkBytes)
    return [pscustomobject]@{ name = $c1atCkName; path = $c1atCkPath; sha256 = $c1atCkSha; said8 = $c1atCkSha.Substring(0, 8) }
}
function Get-C1atKeptNames {
    # Every NAME under -Dir that is a kept copy's of the stub's leaf, A FILE OR A DIRECTORY:
    # <run key>.inst.<eight hex>.stdout.txt -- in ORDINAL order. Never wrap the call in @( ).
    param([string]$Dir)
    $c1atKn = [string[]]@()
    if (Test-Path -LiteralPath $Dir -PathType Container) {
        $c1atKn = [string[]]@(Get-ChildItem -LiteralPath $Dir -Force | Where-Object { $_.Name -cmatch '\A.+\.inst\.[0-9a-f]{8}\.stdout\.txt\z' } | ForEach-Object { $_.Name })
    }
    [Array]::Sort($c1atKn, [System.StringComparer]::Ordinal)
    return ,$c1atKn
}
function Get-C1atItem {
    # The item of a kept-copies listing that opens with -ItemPath and a space; '' where the listing holds
    # none, or where there is no listing at all (-Listing is what Get-WnList returned: $null for an absent key).
    param($Listing, [string]$ItemPath)
    if ($null -eq $Listing) { return '' }
    foreach ($c1atGi in $Listing) { if (([string]$c1atGi).StartsWith(($ItemPath + ' '), [System.StringComparison]::Ordinal)) { return [string]$c1atGi } }
    return ''
}
function Get-C1atShown {
    # A list key as a row says it: ABSENT where the artifact carries no such key, [] where it is written
    # empty, else its items -- the instrument-runs directory written <runs>, so the row can be read.
    param($Listing, [string]$Runs)
    if ($null -eq $Listing) { return 'ABSENT (no such key in the artifact)' }
    if ($Listing.Count -eq 0) { return '[] (written, empty)' }
    return ([string]$Listing.Count + ' item(s): [' + ((@($Listing) | ForEach-Object { ([string]$_).Replace($Runs, '<runs>') }) -join ' ; ') + ']')
}
function Test-C1atAfterKept {
    # Is instrument_captures_kept_on_disk written DIRECTLY AFTER instrument_captures_kept -- that key's own
    # line, its items where it has any, and then this key's line, nothing between?
    param([string]$Artifact)
    return [regex]::IsMatch($Artifact, '(?m)^instrument_captures_kept:(?: \[\])?\r?\n(?:  - .*\r?\n)*instrument_captures_kept_on_disk:')
}
function Get-C1atNotMet {
    # ONE evaluation of G-WNAT with its file_exists detector FAILING, read as row (c) reads it: by hand exit
    # 1, NOT_MET, the file_exists entry not ok, the instrument entry STILL ok by a REUSE whose copy
    # instrument_captures_kept names (-KeptItem) -- and NO instrument_captures_kept_on_disk key. ok and said.
    param($Reading, [string]$KeptItem, [string]$Runs)
    $c1atNmInst = Get-WnInst -Eval $Reading
    $c1atNmFile = Get-PwDetector -Text ([string]$Reading.artifactText) -Type 'file_exists'
    $c1atNmKept = Get-WnList -Eval $Reading -Key 'instrument_captures_kept'
    $c1atNmList = Get-WnList -Eval $Reading -Key 'instrument_captures_kept_on_disk'
    $c1atNmOk = (($Reading.exit -eq 1) -and ($Reading.verdict -ceq 'NOT_MET') -and $c1atNmFile.found -and (-not $c1atNmFile.ok) -and $c1atNmInst.found -and $c1atNmInst.ok -and $c1atNmInst.detail.Contains('REUSED A FRESH READING') -and
                 ($null -ne $c1atNmKept) -and ($c1atNmKept.Count -eq 1) -and ($c1atNmKept[0] -ceq $KeptItem) -and ($null -eq $c1atNmList))
    return [pscustomobject]@{ ok = $c1atNmOk; said = ($Reading.tools + ': exit ' + $Reading.exit + ', ' + $Reading.verdict + '; file_exists ok ' + $c1atNmFile.ok + '; instrument_exit0 ok ' + $c1atNmInst.ok + ', reused ' + $c1atNmInst.detail.Contains('REUSED A FRESH READING') +
                                                         '; instrument_captures_kept ' + (Get-C1atShown -Listing $c1atNmKept -Runs $Runs) + '; instrument_captures_kept_on_disk ' + (Get-C1atShown -Listing $c1atNmList -Runs $Runs)) }
}
$c1atM = $null
$c1atHeld = $null
try {
$c1atGoals = [ordered]@{
    'G-WNAT'      = @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30', '  - type: file_exists', '    path: scratch/switch.txt')
    'G-WNOTHER'   = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
    'G-WNAT-ZERO' = @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 0')
}
$c1atM = New-WnMission -Tag 'c1at' -Goals $c1atGoals
if (-not $c1atM.ok) { throw ('FIXTURE REFUSED: ' + $c1atM.why) }
$c1atRoot = $c1atM.root
$c1atRunsDir = $c1atM.runsDir
$c1atInst = Write-WnStub -Root $c1atRoot
$c1atSwitch = Join-Path $c1atM.scratch 'switch.txt'
$c1atSwitchText = "the file the goal's file_exists detector reads: while it stands the goal can be MET`n"
Write-Utf8 -Path $c1atSwitch -Text $c1atSwitchText
$c1atPorc = Get-WnPorcelain -Root $c1atRoot
Add-C1atRow -Label 'FIXTURE a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/") and three goals committed -- G-WNAT: instrument_exit0 over the stub with reuse_within_minutes 30, then file_exists scratch/switch.txt; G-WNOTHER: the instrument, no window; G-WNAT-ZERO: the instrument, reuse_within_minutes 0 --; the stub and the switch file untracked under scratch/; porcelain reads exactly "?? scratch/"' `
    -Ok ($wnBase.ok -and ($c1atPorc -ceq '?? scratch/') -and ($c1atM.head -cmatch '\A[0-9a-f]{40}\z') -and (Test-Path -LiteralPath $c1atInst -PathType Leaf) -and (Test-Path -LiteralPath $c1atSwitch -PathType Leaf)) `
    -Said ('HEAD ' + $c1atM.head + '; porcelain [' + $c1atPorc + ']; ' + $wnBase.said)

# (a) SIX KEPT NAMES OF THE STUB's LEAF, AND ONE REUSE. Five are stood here before the evaluation, the sixth
#     is the copy the evaluation itself keeps:
#       G-WNAT.inst.<sha8>.stdout.txt     a capture under the goal's own run key, 25 minutes old, copied to its
#                                         kept name -- and then ONE BYTE of the copy changed under that name
#       G-WNAT.inst.<sha8>.stdout.txt     the next capture under that key, 15 minutes old, copied likewise -- and
#                                         HELD OPEN here with FileShare None for as long as both evaluations run.
#                                         IT IS NEVER THE LAST NAME: OTHERKEY's and hand's sort after it, so a
#                                         listing that stops at the first name it cannot read loses them
#       G-WNAT.inst.<8 hex>.stdout.txt    a DIRECTORY, its eight hex one above the lowest of the goal's three, so
#                                         by name it stands BETWEEN two files (a listing that takes the files and
#                                         the directories apart would put it first, or last)
#       OTHERKEY.inst.<sha8>.stdout.txt   a hand run under another run key, 10 minutes old, copied likewise: GOOD
#       hand.inst.<sha8>.stdout.txt       a hand run under a LOWER-CASE run key, 20 minutes old, copied likewise:
#                                         GOOD. An ordinal comparer puts it LAST, after OTHERKEY's; case-folded,
#                                         and as the file system lists the directory, it stands before OTHERKEY's.
#     Then the goal's own run key is captured once more, NOW: the newest capture that passes, so the reuse cites
#     it and keeps it as G-WNAT.inst.<its sha8>.stdout.txt -- the sixth name.
#     AND TWO NAMES THAT ARE NOT KEPT NAMES OF THIS LEAF, files both, which the listing must hold no item for:
#       G-WNAT.two.<sha8>.stdout.txt      a kept copy's name of ANOTHER leaf (a capture's bytes under their own sha8)
#       G-WNAT.inst.nothex00.stdout.txt   the leaf's own shape with eight characters that are not hex
$c1atCap0 = New-C1atCapture -RunKey 'G-WNAT' -GoalId 'G-WNAT' -Age 1500
$c1atChanged = Copy-C1atKept -Live $c1atCap0.path
$c1atChangedBytes = [System.IO.File]::ReadAllBytes($c1atChanged.path)
$c1atChangedBytes[$c1atChangedBytes.Length - 2] = [byte]($c1atChangedBytes[$c1atChangedBytes.Length - 2] -bxor 1)
[System.IO.File]::WriteAllBytes($c1atChanged.path, $c1atChangedBytes)
$c1atChangedSha = Get-PwRawSha -Path $c1atChanged.path
$c1atCap1 = New-C1atCapture -RunKey 'G-WNAT' -GoalId 'G-WNAT' -Age 900
$c1atHeldCopy = Copy-C1atKept -Live $c1atCap1.path
$c1atHand = New-C1atCapture -RunKey 'hand' -Age 1200
$c1atGood = Copy-C1atKept -Live $c1atHand.path
$c1atOther = New-C1atCapture -RunKey 'OTHERKEY' -Age 600
$c1atOtherCopy = Copy-C1atKept -Live $c1atOther.path
$c1atCap2 = New-C1atCapture -RunKey 'G-WNAT' -GoalId 'G-WNAT'
$c1atLive = $c1atCap2.path
$c1atLiveSha = $c1atCap2.sha256
$c1atKeptNowName = 'G-WNAT.inst.' + $c1atLiveSha.Substring(0, 8) + '.stdout.txt'
$c1atKeptNow = Join-Path $c1atRunsDir $c1atKeptNowName
$c1atHex = [string[]]@($c1atChanged.said8, $c1atHeldCopy.said8, $c1atLiveSha.Substring(0, 8))
[Array]::Sort($c1atHex, [System.StringComparer]::Ordinal)
$c1atDirNum = [Convert]::ToInt64($c1atHex[0], 16) + 1
while ($c1atHex -ccontains $c1atDirNum.ToString('x8')) { $c1atDirNum++ }
$c1atDirName = 'G-WNAT.inst.' + $c1atDirNum.ToString('x8') + '.stdout.txt'
$c1atDirPath = Join-Path $c1atRunsDir $c1atDirName
New-Item -ItemType Directory -Path $c1atDirPath | Out-Null
$c1atNotLeafName = 'G-WNAT.two.' + $c1atGood.said8 + '.stdout.txt'
$c1atNotHexName = 'G-WNAT.inst.nothex00.stdout.txt'
$c1atNotKept = [string[]]@((Join-Path $c1atRunsDir $c1atNotLeafName), (Join-Path $c1atRunsDir $c1atNotHexName))
foreach ($c1atNotKeptPath in $c1atNotKept) { [System.IO.File]::WriteAllBytes($c1atNotKeptPath, [System.IO.File]::ReadAllBytes($c1atGood.path)) }
$c1atNames = [string[]]@($c1atChanged.name, $c1atHeldCopy.name, $c1atKeptNowName, $c1atDirName, $c1atOtherCopy.name, $c1atGood.name)
[Array]::Sort($c1atNames, [System.StringComparer]::Ordinal)
$c1atFolded = [string[]]$c1atNames.Clone()
[Array]::Sort($c1atFolded, [System.StringComparer]::OrdinalIgnoreCase)
$c1atPlanted = [string[]]@($c1atNames | Where-Object { $_ -cne $c1atKeptNowName })
$c1atBefore = Get-C1atKeptNames -Dir $c1atRunsDir
$c1atDirAt = [Array]::IndexOf($c1atNames, $c1atDirName)
$c1atHeldAt = [Array]::IndexOf($c1atNames, $c1atHeldCopy.name)
Add-C1atRow -Label '(a) FIXTURE before the evaluation FIVE kept names of the leaf inst stand under instrument-runs: under the goal''s own run key a copy with ONE BYTE CHANGED under its name, a copy still GOOD that this member will HOLD -- never the last name -- and a DIRECTORY whose name sorts between two files; a GOOD copy under OTHERKEY; a GOOD copy under the lower-case key hand -- LAST by an ordinal comparer, not last case-folded; the live capture of the goal''s own key is the newest, and its kept name is still free; and TWO FILES THAT ARE NOT KEPT NAMES OF THIS LEAF stand beside them -- another leaf''s, and eight characters that are not hex' `
    -Ok (($c1atBefore.Count -eq 5) -and (($c1atBefore -join '|') -ceq ($c1atPlanted -join '|')) -and ((Get-PwRawSha -Path $c1atGood.path) -ceq $c1atGood.sha256) -and ((Get-PwRawSha -Path $c1atOtherCopy.path) -ceq $c1atOtherCopy.sha256) -and
         ((Get-PwRawSha -Path $c1atHeldCopy.path) -ceq $c1atHeldCopy.sha256) -and ($c1atChangedSha -cne $c1atChanged.sha256) -and ($c1atChangedSha.Substring(0, 8) -cne $c1atChanged.said8) -and (Test-Path -LiteralPath $c1atDirPath -PathType Container) -and
         ($c1atDirName -cmatch '\AG-WNAT\.inst\.[0-9a-f]{8}\.stdout\.txt\z') -and ($c1atDirAt -gt 0) -and ($c1atDirAt -lt ($c1atNames.Count - 1)) -and ($c1atNames.Count -eq 6) -and ($c1atNames[5] -ceq $c1atGood.name) -and ($c1atFolded[5] -cne $c1atGood.name) -and
         ($c1atHeldAt -ge 0) -and ($c1atHeldAt -lt 4) -and $c1atOtherCopy.name.StartsWith('OTHERKEY.inst.') -and $c1atGood.name.StartsWith('hand.inst.') -and $c1atHeldCopy.name.StartsWith('G-WNAT.inst.') -and $c1atChanged.name.StartsWith('G-WNAT.inst.') -and
         (Test-Path -LiteralPath $c1atNotKept[0] -PathType Leaf) -and (Test-Path -LiteralPath $c1atNotKept[1] -PathType Leaf) -and ($c1atNotLeafName -cmatch '\AG-WNAT\.two\.[0-9a-f]{8}\.stdout\.txt\z') -and
         (-not (Test-Path -LiteralPath $c1atKeptNow)) -and ($c1atLive -ceq (Join-Path $c1atRunsDir 'G-WNAT.inst.stdout.txt')) -and ((Get-PwRawSha -Path $c1atLive) -ceq $c1atLiveSha)) `
    -Said ('on disk, ordinal: ' + ($c1atBefore -join ', ') + ' | changed: the name says ' + $c1atChanged.said8 + ', its bytes now hash to ' + $c1atChangedSha + ' | the copy to be held will be item ' + ($c1atHeldAt + 1) + ' of 6, the directory item ' + ($c1atDirAt + 1) + ' | case-folded the six would read: ' + ($c1atFolded -join ', ') +
           ' | not kept names of this leaf: ' + $c1atNotLeafName + ', ' + $c1atNotHexName + ' | live ' + $c1atLive.Replace($c1atRunsDir, '<runs>') + ' sha256 ' + $c1atLiveSha)
$c1atHeldSaid = 'not tried'
$c1atHeld = [System.IO.File]::Open($c1atHeldCopy.path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
try {
    try { $null = [System.IO.File]::ReadAllBytes($c1atHeldCopy.path); $c1atHeldSaid = 'READ' } catch { $c1atHeldSaid = 'refused' }
    # THE FALSIFIER's EVALUATION, at this tree; then THE BASE's, over the same directory, the file still held.
    $c1atRunsWas = Get-WnRuns -Root $c1atRoot
    $c1atA = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
    $c1atARan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
    $c1atAAfter = Get-C1atKeptNames -Dir $c1atRunsDir
    $c1atRunsWas = Get-WnRuns -Root $c1atRoot
    $c1atAB = Invoke-WnEval -Tools base -Root $c1atRoot -GoalId 'G-WNAT'
    $c1atABRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
    $c1atABAfter = Get-C1atKeptNames -Dir $c1atRunsDir
    try { $null = [System.IO.File]::ReadAllBytes($c1atHeldCopy.path); $c1atHeldSaid += ', then READ' } catch { $c1atHeldSaid += ', then refused' }
} finally { $c1atHeld.Dispose(); $c1atHeld = $null }
$c1atHeldBack = Get-PwRawSha -Path $c1atHeldCopy.path
$c1atAInst = Get-WnInst -Eval $c1atA
$c1atAKept = Get-WnList -Eval $c1atA -Key 'instrument_captures_kept'
$c1atAList = Get-WnList -Eval $c1atA -Key 'instrument_captures_kept_on_disk'
$c1atAShown = Get-C1atShown -Listing $c1atAList -Runs $c1atRunsDir
# (The four item rows print the whole key only where there is none to read an item from: the row above them prints it.)
$c1atANoKey = if ($null -eq $c1atAList) { ' | the key: ' + $c1atAShown } else { '' }
$c1atKeptItem = $c1atKeptNow + ' sha256 ' + $c1atLiveSha
Add-C1atRow -Label '(a) FIXTURE ... and the evaluation at this tree is the one the row names: MET by a REUSE of the goal''s own newest capture, the stub NOT run, the copy KEPT NOW beside it and named by instrument_captures_kept; SIX kept names then stand; the held copy was refused to a second reader before and after both evaluations and, released, still hashes to its name' `
    -Ok (($c1atA.verdict -ceq 'MET') -and ($c1atARan -eq 0) -and $c1atAInst.ok -and $c1atAInst.detail.Contains('REUSED A FRESH READING') -and $c1atAInst.detail.Contains(': capture ' + $c1atLive + ' sha256 ' + $c1atLiveSha + ', captured_at ') -and
         $c1atAInst.detail.EndsWith(' THE CAPTURE CITED IS KEPT at ' + $c1atKeptNow + ' (written now; register row 391).') -and ($null -ne $c1atAKept) -and ($c1atAKept.Count -eq 1) -and ($c1atAKept[0] -ceq $c1atKeptItem) -and
         (($c1atAAfter -join '|') -ceq ($c1atNames -join '|')) -and (Test-Path -LiteralPath $c1atKeptNow -PathType Leaf) -and ((Get-PwRawSha -Path $c1atKeptNow) -ceq $c1atLiveSha) -and ($c1atHeldSaid -ceq 'refused, then refused') -and ($c1atHeldBack -ceq $c1atHeldCopy.sha256)) `
    -Said ('tree: exit ' + $c1atA.exit + ', ' + $c1atA.verdict + ', the stub ran ' + $c1atARan + '; a second reader of the held copy: ' + $c1atHeldSaid + '; released it reads sha256 ' + $c1atHeldBack + '; kept names: ' + ($c1atAAfter -join ', ') + ' | detail: ' + $c1atAInst.detail.Replace($c1atRunsDir, '<runs>'))
$c1atAOrder = $false
if (($null -ne $c1atAList) -and ($c1atAList.Count -eq $c1atNames.Count)) {
    $c1atAOrder = $true
    for ($c1atI = 0; $c1atI -lt $c1atNames.Count; $c1atI++) {
        if (-not ([string]$c1atAList[$c1atI]).StartsWith(((Join-Path $c1atRunsDir $c1atNames[$c1atI]) + ' '), [System.StringComparison]::Ordinal)) { $c1atAOrder = $false }
    }
}
$c1atAStray = 0
if ($null -ne $c1atAList) { foreach ($c1atNotKeptPath in $c1atNotKept) { if (Get-C1atItem -Listing $c1atAList -ItemPath $c1atNotKeptPath) { $c1atAStray++ } } }
Add-C1atRow -Label '(a) FALSIFIER a MET verdict by a reuse that keeps a copy, six kept names of the leaf on disk, one of them unreadable and one a directory: the verdict is MET, exit 0, NOTHING on stderr -- and instrument_captures_kept_on_disk is WRITTEN, directly after instrument_captures_kept: ONE ITEM PER NAME, SIX AND NO MORE -- none for the two files that are not kept names of this leaf --, IN THE NAMES'' ORDINAL ORDER: the directory between two files, the names after the unreadable copy still there, the copy under hand last' `
    -Ok (($c1atA.exit -eq 0) -and ($c1atA.verdict -ceq 'MET') -and ($c1atA.stderr -ceq '') -and $c1atA.stdout.Contains('mission-goal-check: G-WNAT -> MET') -and ($null -ne $c1atAList) -and ($c1atAList.Count -eq 6) -and ($c1atAStray -eq 0) -and $c1atAOrder -and (Test-C1atAfterKept -Artifact $c1atA.artifactText)) `
    -Said ('tree: exit ' + $c1atA.exit + ', ' + $c1atA.verdict + ', stderr [' + $c1atA.stderr.Trim() + ']; wanted, in order: ' + ($c1atNames -join ', ') + ' | instrument_captures_kept_on_disk: ' + $c1atAShown + ' | items for a name that is not a kept name of this leaf (' + $c1atNotLeafName + ', ' + $c1atNotHexName + '): ' + $c1atAStray +
           ' | directly after instrument_captures_kept: ' + (Test-C1atAfterKept -Artifact $c1atA.artifactText))
$c1atWantGood = @(($c1atGood.path + ' sha256 ' + $c1atGood.sha256), $c1atKeptItem, ($c1atOtherCopy.path + ' sha256 ' + $c1atOtherCopy.sha256))
$c1atGotGood = @((Get-C1atItem -Listing $c1atAList -ItemPath $c1atGood.path), (Get-C1atItem -Listing $c1atAList -ItemPath $c1atKeptNow), (Get-C1atItem -Listing $c1atAList -ItemPath $c1atOtherCopy.path))
Add-C1atRow -Label '(a) FALSIFIER ... THE THREE COPIES WHOSE BYTES HASH TO THEIR NAMES each read "<full path> sha256 <64 hex>" and nothing more: the copy THIS verdict kept (the very item instrument_captures_kept holds), and the two whose names sort AFTER the unreadable copy''s -- the copy under OTHERKEY and the earlier copy under the lower-case key hand: by leaf, under every run key, each examined on its own' `
    -Ok (($c1atGotGood[0] -ceq $c1atWantGood[0]) -and ($c1atGotGood[1] -ceq $c1atWantGood[1]) -and ($c1atGotGood[2] -ceq $c1atWantGood[2])) `
    -Said ('wanted: ' + (($c1atWantGood -join ' ; ').Replace($c1atRunsDir, '<runs>')) + ' | read: [' + (($c1atGotGood -join '] ; [').Replace($c1atRunsDir, '<runs>')) + ']' + $c1atANoKey)
$c1atWantChanged = $c1atChanged.path + ' sha256 ' + $c1atChangedSha + ' -- MISMATCH: the name says ' + $c1atChanged.said8
$c1atGotChanged = Get-C1atItem -Listing $c1atAList -ItemPath $c1atChanged.path
Add-C1atRow -Label '(a) FALSIFIER ... THE COPY WHOSE BYTES WERE CHANGED UNDER ITS NAME reads "<full path> sha256 <the sha256 of the bytes that stand there> -- MISMATCH: the name says <the eight hex of its name>"' `
    -Ok ($c1atGotChanged -ceq $c1atWantChanged) -Said ('wanted: ' + $c1atWantChanged.Replace($c1atRunsDir, '<runs>') + ' | read: [' + $c1atGotChanged.Replace($c1atRunsDir, '<runs>') + ']' + $c1atANoKey)
$c1atWantHeld = $c1atHeldCopy.path + ' -- UNREADABLE: '
$c1atGotHeld = Get-C1atItem -Listing $c1atAList -ItemPath $c1atHeldCopy.path
Add-C1atRow -Label '(a) FALSIFIER ... THE COPY ANOTHER PROCESS HOLDS WITH NO SHARING reads "<full path> -- UNREADABLE: <why>" -- a reason follows, no sha256 is claimed for bytes that were not read, and the evaluation did not throw over it' `
    -Ok ($c1atGotHeld.StartsWith($c1atWantHeld, [System.StringComparison]::Ordinal) -and ($c1atGotHeld.Substring($c1atWantHeld.Length).Trim().Length -gt 0)) -Said ('wanted an item opening: ' + $c1atWantHeld.Replace($c1atRunsDir, '<runs>') + ' | read: [' + $c1atGotHeld.Replace($c1atRunsDir, '<runs>') + ']' + $c1atANoKey)
$c1atWantDir = $c1atDirPath + ' -- NOT A FILE'
$c1atGotDir = Get-C1atItem -Listing $c1atAList -ItemPath $c1atDirPath
Add-C1atRow -Label '(a) FALSIFIER ... THE DIRECTORY AT A KEPT NAME reads "<full path> -- NOT A FILE" -- directories included' `
    -Ok ($c1atGotDir -ceq $c1atWantDir) -Said ('wanted: ' + $c1atWantDir.Replace($c1atRunsDir, '<runs>') + ' | read: [' + $c1atGotDir.Replace($c1atRunsDir, '<runs>') + ']' + $c1atANoKey)
$c1atABInst = Get-WnInst -Eval $c1atAB
$c1atABKept = Get-WnList -Eval $c1atAB -Key 'instrument_captures_kept'
$c1atABList = Get-WnList -Eval $c1atAB -Key 'instrument_captures_kept_on_disk'
Add-C1atRow -Label '(a) BASE CONTROL: the base over the same directory, the same six kept names, the same file still held: MET by the same reuse, the stub not run, the copy already kept and named by instrument_captures_kept -- and NO instrument_captures_kept_on_disk key in its artifact: of the other five names it says nothing' `
    -Ok (($c1atAB.exit -eq 0) -and ($c1atAB.verdict -ceq 'MET') -and ($c1atAB.stderr -ceq '') -and ($c1atABRan -eq 0) -and $c1atABInst.ok -and $c1atABInst.detail.Contains('REUSED A FRESH READING') -and
         $c1atABInst.detail.EndsWith(' THE CAPTURE CITED IS KEPT at ' + $c1atKeptNow + ' (already kept, the same bytes; register row 391).') -and ($null -ne $c1atABKept) -and ($c1atABKept.Count -eq 1) -and ($c1atABKept[0] -ceq $c1atKeptItem) -and
         ($null -eq $c1atABList) -and (-not $c1atAB.artifactText.Contains('instrument_captures_kept_on_disk')) -and (($c1atABAfter -join '|') -ceq ($c1atNames -join '|'))) `
    -Said ('base: exit ' + $c1atAB.exit + ', ' + $c1atAB.verdict + ', the stub ran ' + $c1atABRan + '; instrument_captures_kept ' + (Get-C1atShown -Listing $c1atABKept -Runs $c1atRunsDir) + '; instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atABList -Runs $c1atRunsDir) + '; kept names on disk: ' + $c1atABAfter.Count)

# (b) THE COPY THIS VERDICT CITES UNDER ANOTHER KEY IS LISTED. instrument-runs emptied; ONE hand run under
#     OTHERKEY, taken now, is the only capture -- so it is the one reused, and its copy is kept under ITS key.
Clear-WnCaptures -Root $c1atRoot
$c1atHandB = New-C1atCapture -RunKey 'OTHERKEY'
$c1atBKept = Join-Path $c1atRunsDir ('OTHERKEY.inst.' + $c1atHandB.sha256.Substring(0, 8) + '.stdout.txt')
$c1atBItem = $c1atBKept + ' sha256 ' + $c1atHandB.sha256
$c1atBWas = Test-Path -LiteralPath $c1atBKept
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atB = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atBRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atBNames = Get-C1atKeptNames -Dir $c1atRunsDir
$c1atBReused = Get-WnList -Eval $c1atB -Key 'instrument_captures_reused'
$c1atBKeptKey = Get-WnList -Eval $c1atB -Key 'instrument_captures_kept'
$c1atBList = Get-WnList -Eval $c1atB -Key 'instrument_captures_kept_on_disk'
Add-C1atRow -Label '(b) FALSIFIER THE COPY THIS VERDICT CITES UNDER ANOTHER KEY IS LISTED: the only capture on disk is a hand run''s, OTHERKEY.inst.stdout.txt -- the goal G-WNAT reuses it, MET, and instrument_captures_kept names OTHERKEY.inst.<sha8>.stdout.txt, written now; THAT VERY ITEM stands in instrument_captures_kept_on_disk, the one kept name on disk' `
    -Ok ((-not $c1atBWas) -and ($c1atB.exit -eq 0) -and ($c1atB.verdict -ceq 'MET') -and ($c1atBRan -eq 0) -and ($null -ne $c1atBReused) -and ($c1atBReused.Count -eq 1) -and ($c1atBReused[0] -ceq ($c1atHandB.path + ' sha256 ' + $c1atHandB.sha256)) -and
         ($c1atHandB.path -ceq (Join-Path $c1atRunsDir 'OTHERKEY.inst.stdout.txt')) -and ($null -ne $c1atBKeptKey) -and ($c1atBKeptKey.Count -eq 1) -and ($c1atBKeptKey[0] -ceq $c1atBItem) -and (Test-Path -LiteralPath $c1atBKept -PathType Leaf) -and
         ($c1atBNames.Count -eq 1) -and ($null -ne $c1atBList) -and ($c1atBList.Count -eq 1) -and ($c1atBList -ccontains $c1atBItem)) `
    -Said ('tree: exit ' + $c1atB.exit + ', ' + $c1atB.verdict + ', the stub ran ' + $c1atBRan + '; kept names on disk: ' + ($c1atBNames -join ', ') + ' | instrument_captures_kept ' + (Get-C1atShown -Listing $c1atBKeptKey -Runs $c1atRunsDir) + ' | instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atBList -Runs $c1atRunsDir))

# (c) THE THREE VERDICTS THAT DO NOT CARRY THE KEY, the kept copy of row (b) standing on disk through all of them.
#     NOT_MET: the switch file removed -- the tree is still clean (scratch/ is the admitted prefix), the
#     instrument is still reused and its copy still named, and the file_exists detector fails.
Remove-Item -LiteralPath $c1atSwitch -Force
$c1atC = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atCB = Invoke-WnEval -Tools base -Root $c1atRoot -GoalId 'G-WNAT'
Write-Utf8 -Path $c1atSwitch -Text $c1atSwitchText
$c1atCRead = Get-C1atNotMet -Reading $c1atC -KeptItem $c1atBItem -Runs $c1atRunsDir
$c1atCBRead = Get-C1atNotMet -Reading $c1atCB -KeptItem $c1atBItem -Runs $c1atRunsDir
Add-C1atRow -Label '(c) CONTROL NOT_MET, the file_exists detector failing: by hand exit 1, the instrument still REUSED and its kept copy still named by instrument_captures_kept, a kept copy on disk -- and NO instrument_captures_kept_on_disk key: at this tree and at the base alike' `
    -Ok ($c1atCRead.ok -and $c1atCBRead.ok -and (Test-Path -LiteralPath $c1atBKept -PathType Leaf)) -Said ($c1atCRead.said + ' | ' + $c1atCBRead.said)
#     NO WINDOW: G-WNOTHER runs the instrument, at this tree and then at the base.
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atN = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNOTHER'
$c1atNRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atNB = Invoke-WnEval -Tools base -Root $c1atRoot -GoalId 'G-WNOTHER'
$c1atNBRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atNEqual = ((Get-WnComparable -Text (Remove-WrProvenanceLine -Text $c1atN.artifactText)) -ceq (Get-WnComparable -Text $c1atNB.artifactText))
$c1atNList = Get-WnList -Eval $c1atN -Key 'instrument_captures_kept_on_disk'
Add-C1atRow -Label '(c) CONTROL a goal that declares NO window, the same kept copy on disk: MET, the instrument RUNS, none of the three reuse keys is written -- no instrument_captures_kept_on_disk --, and the artifact is the base''s byte for byte but for the clock' `
    -Ok (($c1atN.exit -eq 0) -and ($c1atN.verdict -ceq 'MET') -and ($c1atNRan -eq 1) -and ($c1atNB.exit -eq 0) -and ($c1atNB.verdict -ceq 'MET') -and ($c1atNBRan -eq 1) -and [bool]$c1atN.artifactText -and $c1atNEqual -and ($null -eq $c1atNList) -and
         ($null -eq (Get-WnList -Eval $c1atN -Key 'instrument_captures_kept')) -and ($null -eq (Get-WnList -Eval $c1atN -Key 'instrument_captures_reused')) -and (Test-Path -LiteralPath $c1atBKept -PathType Leaf)) `
    -Said ('tree: exit ' + $c1atN.exit + ', ' + $c1atN.verdict + ', the stub ran ' + $c1atNRan + '; base: exit ' + $c1atNB.exit + ', ' + $c1atNB.verdict + ', ran ' + $c1atNBRan + '; artifacts equal but for the clock: ' + $c1atNEqual + '; instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atNList -Runs $c1atRunsDir))
#     THE WINDOW DECLARED 0: G-WNAT-ZERO carries the key reuse_within_minutes with the value 0 -- the reuse
#     question is asked and answered "never", and no window ABOVE 0 is declared. Only the keys are asserted.
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atZ = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT-ZERO'
$c1atZRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atZB = Invoke-WnEval -Tools base -Root $c1atRoot -GoalId 'G-WNAT-ZERO'
$c1atZBRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atZKeys = @('instrument_captures_reused', 'instrument_captures_kept', 'instrument_captures_kept_on_disk')
$c1atZWritten = @($c1atZKeys | Where-Object { $null -ne (Get-WnList -Eval $c1atZ -Key $_) })
$c1atZBWritten = @($c1atZKeys | Where-Object { $null -ne (Get-WnList -Eval $c1atZB -Key $_) })
Add-C1atRow -Label '(c) CONTROL a goal that declares the window 0 (reuse_within_minutes: 0 -- the key, and no window above 0), the same kept copy on disk: MET, the instrument RUNS, and none of the three reuse keys is written -- no instrument_captures_kept_on_disk: at this tree and at the base alike' `
    -Ok (($c1atZ.exit -eq 0) -and ($c1atZ.verdict -ceq 'MET') -and ($c1atZRan -eq 1) -and ($c1atZB.exit -eq 0) -and ($c1atZB.verdict -ceq 'MET') -and ($c1atZBRan -eq 1) -and [bool]$c1atZ.artifactText -and [bool]$c1atZB.artifactText -and
         ($c1atZWritten.Count -eq 0) -and ($c1atZBWritten.Count -eq 0) -and (Test-Path -LiteralPath $c1atBKept -PathType Leaf)) `
    -Said ('tree: exit ' + $c1atZ.exit + ', ' + $c1atZ.verdict + ', the stub ran ' + $c1atZRan + ', reuse keys written: [' + ($c1atZWritten -join ', ') + ']; base: exit ' + $c1atZB.exit + ', ' + $c1atZB.verdict + ', ran ' + $c1atZBRan + ', reuse keys written: [' + ($c1atZBWritten -join ', ') + ']')

# (d) NO KEPT COPY AT ALL: instrument-runs emptied, so the goal's instrument runs -- MET by a fresh run, the
#     window declared, nothing reused and nothing kept. The key is still written: `[]`.
Clear-WnCaptures -Root $c1atRoot
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atD = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atDRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atDNames = Get-C1atKeptNames -Dir $c1atRunsDir
$c1atDReused = Get-WnList -Eval $c1atD -Key 'instrument_captures_reused'
$c1atDKept = Get-WnList -Eval $c1atD -Key 'instrument_captures_kept'
$c1atDList = Get-WnList -Eval $c1atD -Key 'instrument_captures_kept_on_disk'
Add-C1atRow -Label '(d) FALSIFIER no kept copy at all: MET by a FRESH run, the window declared, nothing reused, nothing kept, no kept name on disk -- instrument_captures_kept_on_disk is PRESENT and written "[]", directly after instrument_captures_kept' `
    -Ok (($c1atD.exit -eq 0) -and ($c1atD.verdict -ceq 'MET') -and ($c1atDRan -eq 1) -and ($c1atDNames.Count -eq 0) -and ($null -ne $c1atDReused) -and ($c1atDReused.Count -eq 0) -and ($null -ne $c1atDKept) -and ($c1atDKept.Count -eq 0) -and
         ($null -ne $c1atDList) -and ($c1atDList.Count -eq 0) -and [regex]::IsMatch($c1atD.artifactText, '(?m)^instrument_captures_kept_on_disk: \[\]\r?$') -and (Test-C1atAfterKept -Artifact $c1atD.artifactText)) `
    -Said ('tree: exit ' + $c1atD.exit + ', ' + $c1atD.verdict + ', the stub ran ' + $c1atDRan + '; kept names on disk: ' + $c1atDNames.Count + '; instrument_captures_kept ' + (Get-C1atShown -Listing $c1atDKept -Runs $c1atRunsDir) + '; instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atDList -Runs $c1atRunsDir))

# (e) STATED, NOT CLAIMED. The capture row (d) just wrote is reused once, so the evaluator keeps a copy of it;
#     that copy is then REPLACED by other bytes -- no capture at all -- AND RENAMED to the first eight hex of
#     THEIR sha256. The next verdict keeps the capture again, and lists the replaced file as it lists a copy.
$c1atE1 = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atELive = Join-Path $c1atRunsDir 'G-WNAT.inst.stdout.txt'
$c1atELiveSha = if (Test-Path -LiteralPath $c1atELive -PathType Leaf) { Get-PwRawSha -Path $c1atELive } else { '' }
$c1atEKept = Join-Path $c1atRunsDir ('G-WNAT.inst.' + $(if ($c1atELiveSha.Length -eq 64) { $c1atELiveSha.Substring(0, 8) } else { 'xxxxxxxx' }) + '.stdout.txt')
$c1atEKeptWas = Test-Path -LiteralPath $c1atEKept -PathType Leaf
$c1atEOther = $pwUtf8.GetBytes("not a capture: the bytes a kept copy was replaced by`n")
$c1atEOtherSha = Get-PwSha256 -Bytes $c1atEOther
$c1atEForged = Join-Path $c1atRunsDir ('G-WNAT.inst.' + $c1atEOtherSha.Substring(0, 8) + '.stdout.txt')
if ($c1atEKeptWas) { [System.IO.File]::WriteAllBytes($c1atEKept, $c1atEOther); [System.IO.File]::Move($c1atEKept, $c1atEForged) }
else { [System.IO.File]::WriteAllBytes($c1atEForged, $c1atEOther) }
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atE = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atERan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atEList = Get-WnList -Eval $c1atE -Key 'instrument_captures_kept_on_disk'
$c1atEItem = $c1atEForged + ' sha256 ' + $c1atEOtherSha
Add-C1atRow -Label '(e) STATED, NOT CLAIMED: a kept copy REPLACED by other bytes AND RENAMED to their own sha8 LISTS CLEAN -- "<full path> sha256 <64 hex>", no MISMATCH -- beside the copy the verdict keeps: the listing reads a name and a digest, it does not say the bytes are a capture, or one any verdict cited (RED until the cure: the base writes no such key)' `
    -Ok (($c1atE1.verdict -ceq 'MET') -and $c1atEKeptWas -and ($c1atE.exit -eq 0) -and ($c1atE.verdict -ceq 'MET') -and ($c1atERan -eq 0) -and (Test-Path -LiteralPath $c1atEForged -PathType Leaf) -and ((Get-PwRawSha -Path $c1atEForged) -ceq $c1atEOtherSha) -and
         ($c1atEOtherSha -cne $c1atELiveSha) -and ($null -ne $c1atEList) -and ($c1atEList -ccontains $c1atEItem)) `
    -Said ('the copy the first reuse kept was there: ' + $c1atEKeptWas + '; replaced by ' + $c1atEOther.Length + ' bytes, sha256 ' + $c1atEOtherSha + ', and renamed ' + [System.IO.Path]::GetFileName($c1atEForged) + ' | tree: exit ' + $c1atE.exit + ', ' + $c1atE.verdict + ', the stub ran ' + $c1atERan + '; instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atEList -Runs $c1atRunsDir))

# (f) THE COPY THIS VERDICT KEPT IS LISTED WHATEVER THE CASE OF ITS LEAF (the independent validator's round 3,
#     in the shape it drove). A capture is named after the instrument's leaf AS THE PATH WAS GIVEN
#     to the helper; the reuse finds its candidates through a filter that folds case; and the listing matched
#     the leaf case-sensitively. So a hand capture taken with the goal's own instrument spelled
#     <root>\scratch\INST.ps1 -- the same file -- is HAND.INST.stdout.txt: the goal (path: scratch/inst.ps1)
#     reuses it, keeps HAND.INST.<sha8>.stdout.txt, cites that copy in instrument_captures_kept -- and the
#     listing, which the rule makes the close entry's list, must hold that very copy. instrument-runs is
#     emptied first, so it is the one kept name on disk. ROWS (a) AND (b) ARE THIS ROW's CONTROLS: the leaf as
#     the goal spells it, under the goal's own run key and under another -- each lists the copy its verdict
#     kept. THIS ROW IS A FALSIFIER AND READ RED WHEN IT WAS WRITTEN: the listing was `[]`.
Clear-WnCaptures -Root $c1atRoot
$c1atCsCap = New-WnCapture -Tools tree -Root $c1atRoot -Key 'HAND' -Name 'INST.ps1'
$c1atCsLeaf = if ($c1atCsCap.ok) { [System.IO.Path]::GetFileName([string]$c1atCsCap.path) } else { '(the capture was not taken: ' + [string]$c1atCsCap.why + ')' }
$c1atCsSha8 = if ([string]$c1atCsCap.sha256 -cmatch '\A[0-9a-f]{64}\z') { ([string]$c1atCsCap.sha256).Substring(0, 8) } else { 'xxxxxxxx' }
$c1atCsKept = Join-Path $c1atRunsDir ('HAND.INST.' + $c1atCsSha8 + '.stdout.txt')
$c1atCsItem = $c1atCsKept + ' sha256 ' + [string]$c1atCsCap.sha256
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atCs = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atCsRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atCsOnDisk = @(Get-ChildItem -LiteralPath $c1atRunsDir -Force | ForEach-Object { $_.Name } | Sort-Object)
$c1atCsKeptSha = if (Test-Path -LiteralPath $c1atCsKept -PathType Leaf) { Get-PwRawSha -Path $c1atCsKept } else { '(no kept copy on disk)' }
$c1atCsReused = Get-WnList -Eval $c1atCs -Key 'instrument_captures_reused'
$c1atCsKeptKey = Get-WnList -Eval $c1atCs -Key 'instrument_captures_kept'
$c1atCsList = Get-WnList -Eval $c1atCs -Key 'instrument_captures_kept_on_disk'
Add-C1atRow -Label '(f) FALSIFIER THE COPY THIS VERDICT KEPT IS LISTED WHATEVER THE CASE OF ITS LEAF: the only capture on disk is a hand run''s taken through this tree''s helper with -InstrumentPath <root>\scratch\INST.ps1 -- the goal''s own instrument, its leaf spelled in another case --, HAND.INST.stdout.txt; the goal G-WNAT (path: scratch/inst.ps1) REUSES it, MET, the stub not run, and instrument_captures_kept names HAND.INST.<sha8>.stdout.txt, written now and hashing to its name: THAT VERY ITEM -- the same full path, the same sha256, no MISMATCH -- stands in instrument_captures_kept_on_disk, the one kept name on disk (rows (a) and (b) are its controls: the leaf as the goal spells it, under the goal''s own run key and under another); the independent validator''s round 3' `
    -Ok ($c1atCsCap.ok -and ($c1atCsCap.exit -eq 0) -and ($c1atCsLeaf -ceq 'HAND.INST.stdout.txt') -and ($c1atCs.exit -eq 0) -and ($c1atCs.verdict -ceq 'MET') -and ($c1atCsRan -eq 0) -and
         ($null -ne $c1atCsReused) -and ($c1atCsReused.Count -eq 1) -and ($c1atCsReused[0] -ceq ([string]$c1atCsCap.path + ' sha256 ' + [string]$c1atCsCap.sha256)) -and
         ($null -ne $c1atCsKeptKey) -and ($c1atCsKeptKey.Count -eq 1) -and ($c1atCsKeptKey[0] -ceq $c1atCsItem) -and ($c1atCsKeptSha -ceq [string]$c1atCsCap.sha256) -and
         ($null -ne $c1atCsList) -and ($c1atCsList.Count -eq 1) -and ($c1atCsList -ccontains $c1atCsItem)) `
    -Said ('the hand capture: ok ' + $c1atCsCap.ok + ', ' + $c1atCsLeaf + ' sha256 ' + [string]$c1atCsCap.sha256 + ' | tree: exit ' + $c1atCs.exit + ', ' + $c1atCs.verdict + ', the stub ran ' + $c1atCsRan + '; under instrument-runs: ' + ($c1atCsOnDisk -join ', ') + '; the kept copy''s sha256: ' + $c1atCsKeptSha +
           ' | instrument_captures_reused ' + (Get-C1atShown -Listing $c1atCsReused -Runs $c1atRunsDir) + ' | instrument_captures_kept ' + (Get-C1atShown -Listing $c1atCsKeptKey -Runs $c1atRunsDir) + ' | instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atCsList -Runs $c1atRunsDir))

# (g) THE LISTER SEES A NAME AS THE FILE SYSTEM SEES IT (the cure of that finding as the coordinator ruled it:
#     the WHOLE name's case is folded. These two rows REPLACE the first form of this cure's row, which held
#     the fold to the leaf alone and was never committed). The evaluator asks whether a kept name is taken
#     with File.Exists, which folds case: a file standing at a kept name with its hex or its tail in another
#     case IS the kept name to it -- and a listing strict on those parts would omit a copy a verdict cites.
#     So the listing matches the whole form without regard to case, and holds its other rules as they were:
#     the item is the name AS THE DIRECTORY HOLDS IT, and the sha8 is held to the name's eight hex AS
#     WRITTEN -- a name that says its hex in upper case is LISTED and reads MISMATCH, never clean, while a
#     name whose tail alone is in upper case, its hex lower-case and true, lists clean.
#     THE SCENE OF THE FIRST ROW: instrument-runs emptied; one hand capture of the goal's instrument, the
#     leaf as the goal spells it; and TWO FILES THIS ROW WRITES, the same bytes in both -- no capture,
#     chosen so that the first eight hex of their sha256 hold a letter --, named OLDHEX.inst.<THOSE EIGHT
#     HEX IN UPPER CASE>.stdout.txt and OLDTAIL.inst.<those eight hex>.STDOUT.TXT. THREE ITEMS, in the names'
#     ordinal order, each asserted whole. CONTROLS BOTH, WITH NO RED OF RECORD: they are written with the
#     cure they hold, and what they are run against is that cure's mutants.
Clear-WnCaptures -Root $c1atRoot
$c1atFdCap = New-C1atCapture -RunKey 'HAND'
$c1atFdN = 0
do {
    $c1atFdN++
    $c1atFdBytes = $pwUtf8.GetBytes("not a capture: bytes under a name that is a kept copy's but for its case, " + $c1atFdN + "`n")
    $c1atFdSha = Get-PwSha256 -Bytes $c1atFdBytes
} while (($c1atFdSha.Substring(0, 8) -cnotmatch '[a-f]') -and ($c1atFdN -lt 64))
$c1atFdHexName = 'OLDHEX.inst.' + $c1atFdSha.Substring(0, 8).ToUpperInvariant() + '.stdout.txt'
$c1atFdTailName = 'OLDTAIL.inst.' + $c1atFdSha.Substring(0, 8) + '.STDOUT.TXT'
$c1atFdPlanted = [string[]]@((Join-Path $c1atRunsDir $c1atFdHexName), (Join-Path $c1atRunsDir $c1atFdTailName))
foreach ($c1atFdPath in $c1atFdPlanted) { [System.IO.File]::WriteAllBytes($c1atFdPath, $c1atFdBytes) }
$c1atFdKept = Join-Path $c1atRunsDir ('HAND.inst.' + ([string]$c1atFdCap.sha256).Substring(0, 8) + '.stdout.txt')
$c1atFdItem = $c1atFdKept + ' sha256 ' + [string]$c1atFdCap.sha256
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atFd = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atFdRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atFdOnDisk = @(Get-ChildItem -LiteralPath $c1atRunsDir -Force | ForEach-Object { $_.Name } | Sort-Object)
$c1atFdKeptKey = Get-WnList -Eval $c1atFd -Key 'instrument_captures_kept'
$c1atFdList = Get-WnList -Eval $c1atFd -Key 'instrument_captures_kept_on_disk'
$c1atFdWant = [string[]]@(
    $c1atFdItem,
    ($c1atFdPlanted[0] + ' sha256 ' + $c1atFdSha + ' -- MISMATCH: the name says ' + $c1atFdSha.Substring(0, 8).ToUpperInvariant()),
    ($c1atFdPlanted[1] + ' sha256 ' + $c1atFdSha))
$c1atFdSame = (($null -ne $c1atFdList) -and ($c1atFdList.Count -eq 3) -and ([string]$c1atFdList[0] -ceq $c1atFdWant[0]) -and ([string]$c1atFdList[1] -ceq $c1atFdWant[1]) -and ([string]$c1atFdList[2] -ceq $c1atFdWant[2]))
Add-C1atRow -Label '(g) CONTROL THE LISTER SEES A NAME AS THE FILE SYSTEM SEES IT: beside one hand capture of the goal''s instrument stand TWO FILES OF THIS ROW''s OWN whose names are a kept copy''s BUT FOR THE CASE of one part -- OLDHEX.inst.<EIGHT HEX IN UPPER CASE>.stdout.txt and OLDTAIL.inst.<the same eight hex>.STDOUT.TXT, each holding bytes whose sha256 begins with those eight hex --; the goal REUSES the capture, MET, the stub not run, and instrument_captures_kept_on_disk holds THREE items in the names'' ordinal order, each whole: the copy this verdict kept, "<full path> sha256 <64 hex>"; OLDHEX''s, its path as the directory holds it, "<full path> sha256 <64 hex> -- MISMATCH: the name says <THE EIGHT HEX AS WRITTEN>" -- listed, and never clean --; and OLDTAIL''s, as the directory holds it, "<full path> sha256 <64 hex>" -- clean (the cure of the independent validator''s round 3, as ruled: the whole name''s case is folded; a CONTROL with no RED of record, replacing the first form of this row, which was not committed)' `
    -Ok (($c1atFdSha.Substring(0, 8) -cmatch '[a-f]') -and ($c1atFdOnDisk -ccontains $c1atFdHexName) -and ($c1atFdOnDisk -ccontains $c1atFdTailName) -and ((Get-PwRawSha -Path $c1atFdPlanted[0]) -ceq $c1atFdSha) -and ((Get-PwRawSha -Path $c1atFdPlanted[1]) -ceq $c1atFdSha) -and
         ($c1atFd.exit -eq 0) -and ($c1atFd.verdict -ceq 'MET') -and ($c1atFdRan -eq 0) -and ($null -ne $c1atFdKeptKey) -and ($c1atFdKeptKey.Count -eq 1) -and ($c1atFdKeptKey[0] -ceq $c1atFdItem) -and $c1atFdSame) `
    -Said ('the two names, as they stand on disk: ' + $c1atFdHexName + ', ' + $c1atFdTailName + ' -- ' + $c1atFdBytes.Length + ' bytes each, sha256 ' + $c1atFdSha + ' (try ' + $c1atFdN + ') | tree: exit ' + $c1atFd.exit + ', ' + $c1atFd.verdict + ', the stub ran ' + $c1atFdRan + '; under instrument-runs: ' + ($c1atFdOnDisk -join ', ') +
           ' | instrument_captures_kept ' + (Get-C1atShown -Listing $c1atFdKeptKey -Runs $c1atRunsDir) + ' | instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atFdList -Runs $c1atRunsDir) + ' | wanted, in order: ' + (($c1atFdWant | ForEach-Object { $_.Replace($c1atRunsDir, '<runs>') }) -join ' ; '))

# (g) ... AND THE CASE THAT MATTERS MOST: THE COPY THE VERDICT CITES. instrument-runs emptied; one hand capture
#     whose sha256 holds a letter in its first eight hex (taken again until it does); and, BEFORE the goal is
#     read, a file of THE CAPTURE's OWN BYTES at the kept copy's own name with those eight hex in UPPER case,
#     HAND.inst.<EIGHT HEX>.stdout.txt. Expected of the evaluator, and held here: File.Exists of the kept
#     name is true, so the copy is "already kept, the same bytes" -- cited under the kept name as the
#     evaluator derives it, lower-case hex, and NO second file written --; and the listing holds an item for
#     that file under the name the directory holds, upper-case hex, which the unmoved sha8 test reads
#     MISMATCH. So the verdict's citation and the listing's item spell the one file in two cases: the
#     listing does not omit the copy the verdict cites, and it does not call a name no tool writes clean.
Clear-WnCaptures -Root $c1atRoot
$c1atUpN = 0
do { $c1atUpN++; $c1atUpCap = New-C1atCapture -RunKey 'HAND' } while ((([string]$c1atUpCap.sha256).Substring(0, 8) -cnotmatch '[a-f]') -and ($c1atUpN -lt 16))
$c1atUpSha = [string]$c1atUpCap.sha256
$c1atUpHex = $c1atUpSha.Substring(0, 8)
$c1atUpName = 'HAND.inst.' + $c1atUpHex.ToUpperInvariant() + '.stdout.txt'
$c1atUpPath = Join-Path $c1atRunsDir $c1atUpName
$c1atUpCited = Join-Path $c1atRunsDir ('HAND.inst.' + $c1atUpHex + '.stdout.txt')
[System.IO.File]::WriteAllBytes($c1atUpPath, [System.IO.File]::ReadAllBytes([string]$c1atUpCap.path))
$c1atUpBefore = @(Get-ChildItem -LiteralPath $c1atRunsDir -Force | ForEach-Object { $_.Name } | Sort-Object)
$c1atRunsWas = Get-WnRuns -Root $c1atRoot
$c1atUp = Invoke-WnEval -Tools tree -Root $c1atRoot -GoalId 'G-WNAT'
$c1atUpRan = (Get-WnRuns -Root $c1atRoot) - $c1atRunsWas
$c1atUpAfter = @(Get-ChildItem -LiteralPath $c1atRunsDir -Force | ForEach-Object { $_.Name } | Sort-Object)
$c1atUpInst = Get-WnInst -Eval $c1atUp
$c1atUpKeptKey = Get-WnList -Eval $c1atUp -Key 'instrument_captures_kept'
$c1atUpList = Get-WnList -Eval $c1atUp -Key 'instrument_captures_kept_on_disk'
$c1atUpCitedItem = $c1atUpCited + ' sha256 ' + $c1atUpSha
$c1atUpListedItem = $c1atUpPath + ' sha256 ' + $c1atUpSha + ' -- MISMATCH: the name says ' + $c1atUpHex.ToUpperInvariant()
Add-C1atRow -Label '(g) CONTROL ... AND THE COPY THE VERDICT CITES IS NEVER OMITTED: BEFORE the goal is read a file of the capture''s own bytes stands at the kept copy''s OWN name with its eight hex in UPPER case, HAND.inst.<EIGHT HEX>.stdout.txt; the goal REUSES the capture, MET, the stub not run; to the evaluator that file IS the kept name -- the detail says "THE CAPTURE CITED IS KEPT at <the kept name, lower-case hex> (already kept, the same bytes).", instrument_captures_kept cites "<the kept name, lower-case hex> sha256 <64 hex>", and NO second file is written: the names under instrument-runs are what they were --; and instrument_captures_kept_on_disk HOLDS ONE ITEM, FOR THAT FILE, under the name the directory holds: "<full path, UPPER-case hex> sha256 <the same 64 hex> -- MISMATCH: the name says <THE EIGHT HEX AS WRITTEN>" -- the copy the verdict cites is listed, and a name no tool writes is never called clean (a CONTROL with no RED of record)' `
    -Ok (($c1atUpHex -cmatch '[a-f]') -and ($c1atUpBefore -ccontains $c1atUpName) -and (($c1atUpAfter -join '|') -ceq ($c1atUpBefore -join '|')) -and ((Get-PwRawSha -Path $c1atUpPath) -ceq $c1atUpSha) -and
         ($c1atUp.exit -eq 0) -and ($c1atUp.verdict -ceq 'MET') -and ($c1atUpRan -eq 0) -and $c1atUpInst.found -and $c1atUpInst.ok -and
         $c1atUpInst.detail.Contains(' THE CAPTURE CITED IS KEPT at ' + $c1atUpCited + ' (already kept, the same bytes; register row 391).') -and
         ($null -ne $c1atUpKeptKey) -and ($c1atUpKeptKey.Count -eq 1) -and ([string]$c1atUpKeptKey[0] -ceq $c1atUpCitedItem) -and
         ($null -ne $c1atUpList) -and ($c1atUpList.Count -eq 1) -and ([string]$c1atUpList[0] -ceq $c1atUpListedItem)) `
    -Said ('the capture: HAND.inst.stdout.txt sha256 ' + $c1atUpSha + ' (try ' + $c1atUpN + '); the file written before the goal was read: ' + $c1atUpName + ' | under instrument-runs before: ' + ($c1atUpBefore -join ', ') + ' | after: ' + ($c1atUpAfter -join ', ') +
           ' | tree: exit ' + $c1atUp.exit + ', ' + $c1atUp.verdict + ', the stub ran ' + $c1atUpRan + ' | instrument_captures_kept ' + (Get-C1atShown -Listing $c1atUpKeptKey -Runs $c1atRunsDir) + ' | instrument_captures_kept_on_disk: ' + (Get-C1atShown -Listing $c1atUpList -Runs $c1atRunsDir) + ' | detail: ' + $c1atUpInst.detail)
}
catch {
    $c1atOk = $false
    $c1atRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1atRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1atHeld) { try { $c1atHeld.Dispose() } catch { } }
if ($null -ne $c1atM) { Remove-PwTreeAsWritten -Base $c1atM.base }
Check -Id 'C-1at' -Title 'THE KEPT COPIES, LISTED (the BATCH-5 charter, REC-A WP-N; the operator''s ruling D11 of 2026-10-11): at the base evaluator a MET verdict by a reuse names the one copy it kept and says nothing of what else stands under instrument-runs at a kept name -- over six such names its artifact carries no instrument_captures_kept_on_disk key; at this tree, where the verdict is MET and an instrument_exit0 declares a window above 0, the artifact carries that key directly after instrument_captures_kept: every name under instrument-runs that is a kept copy''s of the instrument''s leaf and no other name -- not another leaf''s, not one whose eight characters are not hex --, UNDER EVERY RUN KEY, a file or a directory, one item each, sorted by name with an ordinal comparer -- "<full path> sha256 <64 hex>" for a copy whose bytes hash to its name, the copy this verdict kept among them, the same with " -- MISMATCH: the name says <8 hex>" for one whose bytes were changed under its name, "<full path> -- UNREADABLE: <why>" for one another process holds with no sharing, the names after it listed all the same, "<full path> -- NOT A FILE" for a directory -- and the listing neither throws nor moves the verdict: MET, exit 0, nothing on stderr; where the capture reused is a hand run''s under another run key, the copy the verdict cites under that key stands in the listing, and so does the copy a verdict kept of a capture taken with the instrument''s leaf spelled in ANOTHER CASE (HAND.INST.stdout.txt for scratch/inst.ps1: the reuse finds it case-folded, and the listing must -- the independent validator''s round 3) -- and the WHOLE name is read without regard to case, as File.Exists reads it, the item being the name as the directory holds it and the sha8 held to the eight hex as written: beside a hand capture, a name that is a kept copy''s but for eight hex in UPPER case is listed with " -- MISMATCH: the name says <the hex as written>", never clean, and one but for a tail in upper case is listed clean; and a file of the capture''s own bytes standing at the kept copy''s OWN name with upper-case hex is found already kept, cited by the verdict under the lower-case name with nothing written beside it, and HAS ITS ITEM in the listing under the name the directory holds, reading MISMATCH -- the copy a verdict cites is never omitted (two CONTROLS with no RED of record); with no kept copy on disk the key is written []; a verdict that is NOT_MET does not carry the key, at this tree and at the base alike, a goal that declares no window writes the artifact the base writes, byte for byte but for the clock, and a goal that declares the window 0 writes none of the reuse keys; STATED, NOT CLAIMED: a kept copy replaced by other bytes and renamed to their own sha8 lists clean -- the listing reads a name and a digest, not a capture' `
      -Ok $c1atOk -Detail ("      THE $(@($c1atRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1atRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument both goals name (every capture of it here is GREEN):`n" + (Get-WlIndented -Text $wnStubText))

# =============================================================================================
# C-1au -- TWO PATH CLASSES REFUSED AS A BRIEF BY NAME: a HANDOFF head that names another
#          goal's verdict artifact, or any file under instrument-runs, is refused BY ITS NAME, not its identity
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: an older rule refused the goal's
# OWN verdict artifact and left every OTHER file a run rewrites -- "another goal's artifact, an instrument
# capture this evaluation tees" -- "a brief like any other ... A residual, not cured" (the evaluator's own
# words above its own-artifact test). So a head naming .mission\goals\<another goal>.verdict.yaml, or the live
# capture under .mission-runtime\lam\instrument-runs, with that file's own digests, is ADMITTED and a line
# is appended to the admissions record -- on a file the next evaluation rewrites, the loop of the two older refusals
# through a third and a fourth file. THE RULE: after the own-artifact refusal and before the brief is
# read, BY NAME, a file whose name ends .verdict.yaml in a goals directory, and any file under
# instrument-runs, is refused in a sentence of its own -- the head refused as the two older refusals refuse
# it: handoff_refused exactly one entry, the admissions record not appended, its bytes what they were.
# "A goals directory" is one of THREE -- .mission\goals, .mission-runtime\lam\goals, and the goal file's own
# directory where -GoalFile names one -- and each is driven; each class is driven under four more spellings.
# THE CONTROLS, each a row: an ORDINARY brief is admitted exactly as the base admits it, and so is a brief
# in a sibling directory whose name only begins "instrument-runs"; the admissions record and the goal's
# OWN artifact keep their own sentences, never the new one; and what the rule does not
# reach is measured, not claimed -- a COPY of the other goal's artifact and a HARD LINK to the live
# capture, each placed under scratch\, and the other goal's GOAL FILE in the goals directory, are still
# briefs like any other (the rule reads a name, the whole of it, never a file's identity).
# EVERY ONE OF THOSE SEVEN CONTROLS IS READ TWICE, by this tree and then by
# the base over the same head and the same record, and the two readings must be ONE: the same outcome, the
# two verdict artifacts equal but for the clock, the two hook stdouts equal (G-WNAU declares no window and
# no instrument, so nothing of this batch is written into its artifact).
# AND ONE MORE NAME THE RULE DOES NOT REACH, STATED AND DRIVEN WHERE THE HOST LETS IT BE (the independent
# validator's round 1): the live capture named by a UNC spelling of this host,
# \\localhost\<drive>$\<the rest of its absolute path> -- the same file, under a name that is not under
# this mission's instrument-runs as the rule spells the root -- is ADMITTED, and a line is appended to the
# admissions record. THE REFUSAL IS BY NAME, NOT BY IDENTITY: a capture is refused under the spellings driven,
# not under every name a host gives a file. That row is read by this tree alone and is not one of the seven;
# where \\localhost\<drive>$ does not answer on the host it says so and asserts no admission.
# THE ADMISSIONS RECORD IS SEEDED ONCE -- one line, the base admitting an ordinary brief -- AND PUT BACK TO
# THOSE BYTES BEFORE EVERY STOP BELOW (Invoke-C1auStop), so no row reads another row's admission: at the
# base every head here is admitted, and a head admitted by one row would read "already admitted" in the next.
$c1auOk = $true
$c1auRows = New-Object System.Collections.Generic.List[string]
function Add-C1auRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1auOk = $false }
    $script:c1auRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1auRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Invoke-C1auStop {
    # ONE STOP over G-WNAU, as the hook, by this tree's evaluator or the base's (-Tools): the admissions
    # record put back to its seeded bytes FIRST; then STATUS.md's head written naming -PathAsWritten, both
    # digests the sha256 of -Target's bytes as they then stand; the record's sha256 and line count read
    # before and after. -KeepArtifact leaves G-WNAU's own verdict artifact where it is (a row names it).
    # -AltGoalFile <path> evaluates G-WNAU from THAT goal file (the evaluator's -GoalFile): the evaluator
    # then writes the verdict artifact BESIDE that file, where Invoke-WnEval does not look, so the artifact
    # there is removed first and read back here.
    # Returns the hook's reading, the handoff arm's entry (detail), handoff_refused (refusedCount is -1
    # where the key is not written; refusedFirst its first entry), the record before and after, lastBrief
    # (brief_path of the record's last line), targetSha (the digest the head was written with), admitted --
    # approve, exit 0, HANDOFF_ADMITTED AND one line appended that names the path as the head wrote it --
    # and said, one line for a row's face.
    param([string]$Tools = 'tree', [string]$PathAsWritten, [string]$Target, [switch]$KeepArtifact, [string]$AltGoalFile = '')
    [System.IO.File]::WriteAllBytes($script:c1auRec, $script:c1auSeedBytes)
    $c1auTargetSha = Get-PwRawSha -Path $Target
    Write-EsStatus -Root $script:c1auRoot -Head (Get-EsHead -Ctx '60' -Lf $c1auTargetSha -Raw $c1auTargetSha -Path $PathAsWritten)
    $c1auRecBefore = Get-EsRecord -Root $script:c1auRoot
    $c1auShaBefore = Get-PwRawSha -Path $script:c1auRec
    $c1auEv = $null
    $c1auText = ''
    if ($AltGoalFile) {
        $c1auAltVerdict = Join-Path (Split-Path -Parent $AltGoalFile) 'G-WNAU.verdict.yaml'
        if (Test-Path -LiteralPath $c1auAltVerdict -PathType Leaf) { Remove-Item -LiteralPath $c1auAltVerdict -Force }
        $c1auEv = Invoke-WnEval -Tools $Tools -Root $script:c1auRoot -GoalId 'G-WNAU' -AsStopHook -GoalFile $AltGoalFile
        if (Test-Path -LiteralPath $c1auAltVerdict -PathType Leaf) { $c1auText = [System.IO.File]::ReadAllText($c1auAltVerdict) }
    } else {
        $c1auEv = Invoke-WnEval -Tools $Tools -Root $script:c1auRoot -GoalId 'G-WNAU' -AsStopHook -KeepArtifact:$KeepArtifact
        $c1auText = [string]$c1auEv.artifactText
    }
    $c1auVerdict = ''
    $c1auVerdictAt = [regex]::Match($c1auText, '(?m)^verdict:[ \t]*(\S+)')
    if ($c1auVerdictAt.Success) { $c1auVerdict = $c1auVerdictAt.Groups[1].Value }
    $c1auRecAfter = Get-EsRecord -Root $script:c1auRoot
    $c1auShaAfter = if ($c1auRecAfter.exists) { Get-PwRawSha -Path $script:c1auRec } else { '(no record)' }
    $c1auEntry = Get-PwDetector -Text $c1auText -Type $script:esHoType
    $c1auRefused = Get-WnList -Eval ([pscustomobject]@{ artifactText = $c1auText }) -Key 'handoff_refused'
    $c1auRefusedCount = if ($null -eq $c1auRefused) { -1 } else { $c1auRefused.Count }
    $c1auRefusedFirst = if ($c1auRefusedCount -gt 0) { [string]$c1auRefused[0] } else { '' }
    $c1auLastBrief = ''
    if ($c1auRecAfter.count -gt 0) {
        $c1auLastLine = @($c1auRecAfter.objects)[$c1auRecAfter.count - 1]
        if ($null -ne $c1auLastLine) { $c1auLastBrief = [string]$c1auLastLine.brief_path }
    }
    $c1auAdmitted = (($c1auEv.decision -ceq 'approve') -and ($c1auEv.exit -eq 0) -and ($c1auVerdict -ceq $script:esHoVerdict) -and ($c1auRecAfter.count -eq ($c1auRecBefore.count + 1)) -and
                     ($c1auShaAfter -cne $c1auShaBefore) -and ($c1auLastBrief -ceq $PathAsWritten))
    $c1auSaid = $Tools + ': exit ' + $c1auEv.exit + ', ' + $(if ($c1auEv.decision) { $c1auEv.decision } else { '(no decision)' }) + ', ' + $(if ($c1auVerdict) { $c1auVerdict } else { '(no verdict)' }) +
                '; record ' + $c1auRecBefore.count + ' -> ' + $c1auRecAfter.count + ' line(s), sha256 ' + $c1auShaBefore.Substring(0, 8) + ' -> ' + $c1auShaAfter.Substring(0, 8) +
                '; handoff_refused: ' + $(if ($c1auRefusedCount -lt 0) { 'NOT WRITTEN' } else { [string]$c1auRefusedCount + ' entr' + $(if ($c1auRefusedCount -eq 1) { 'y' } else { 'ies' }) }) + '; the handoff entry: ' + [string]$c1auEntry.detail
    return [pscustomobject]@{ tools = $Tools; exit = $c1auEv.exit; decision = $c1auEv.decision; verdict = $c1auVerdict; reason = $c1auEv.reason; stdout = $c1auEv.stdout; stderr = $c1auEv.stderr; text = $c1auText
                              detail = [string]$c1auEntry.detail; refusedCount = $c1auRefusedCount; refusedFirst = $c1auRefusedFirst
                              linesBefore = $c1auRecBefore.count; linesAfter = $c1auRecAfter.count; shaBefore = $c1auShaBefore; shaAfter = $c1auShaAfter; lastBrief = $c1auLastBrief
                              targetSha = $c1auTargetSha; admitted = $c1auAdmitted; said = $c1auSaid }
}
function Test-C1auRefused {
    # A REFUSED HEAD, IN THE SHAPE OF THE TWO OLDER REFUSALS: the hook blocks, exit 0, NOT_MET (G-WNAU's other
    # detector fails, so a refused head admits nothing); the handoff arm's entry holds -Opens and -Closes;
    # handoff_refused holds exactly ONE entry, and it holds -Closes; THE ADMISSIONS RECORD IS UNCHANGED --
    # its sha256 and its line count, before and after.
    param($Reading, [string]$Opens, [string]$Closes)
    return (($Reading.decision -ceq 'block') -and ($Reading.exit -eq 0) -and ($Reading.verdict -ceq 'NOT_MET') -and $Reading.detail.Contains($Opens) -and $Reading.detail.Contains($Closes) -and
            ($Reading.refusedCount -eq 1) -and $Reading.refusedFirst.Contains($Closes) -and ($Reading.shaAfter -ceq $Reading.shaBefore) -and ($Reading.linesAfter -eq $Reading.linesBefore))
}
function Test-C1auAsBase {
    # THIS TREE's READING OF ONE HEAD (-Reading) AND THE BASE's OF THE SAME HEAD (-Control), EQUAL BUT FOR THE
    # CLOCK: the two verdict artifacts under Get-WnComparable and the two hook stdouts as they are -- but for the
    # one sentence C-1ba adds to a NOT_MET block (BATCH-6 WP-Q; Remove-WqAdmittedSentence). G-WNAU
    # declares no window and no instrument, so no key of this batch is written into either artifact.
    # -MaskDigest is for the one head whose named file a Stop REWRITES (the goal's own artifact): the digest
    # that head was written with is the fixture's, not the evaluator's, differs between the two Stops, and
    # is masked in each artifact before the two are compared; nothing else is.
    param($Reading, $Control, [switch]$MaskDigest)
    if ((-not [string]$Reading.text) -or (-not [string]$Control.text)) { return $false }
    $c1auMineText = if ($MaskDigest) { Get-WnComparable -Text (Remove-WrProvenanceLine -Text $Reading.text) -Mask @($Reading.targetSha) } else { Get-WnComparable -Text (Remove-WrProvenanceLine -Text $Reading.text) }
    $c1auBaseText = if ($MaskDigest) { Get-WnComparable -Text $Control.text -Mask @($Control.targetSha) } else { Get-WnComparable -Text $Control.text }
    return (($c1auMineText -ceq $c1auBaseText) -and ((Remove-WqAdmittedSentence -Text $Reading.stdout) -ceq $Control.stdout))
}
function Get-C1auShortDir {
    # THE 8.3 (SHORT) SPELLING OF A DIRECTORY's FULL PATH, as the file system itself gives it
    # (Scripting.FileSystemObject's ShortPath: every segment that has a short name spelled by it). '' where
    # the object cannot be made or the directory cannot be asked. Where the volume keeps no short names the
    # answer is the long path again, and the caller says so.
    param([string]$Dir)
    try { return [string](New-Object -ComObject Scripting.FileSystemObject).GetFolder($Dir).ShortPath } catch { return '' }
}
$c1auM = $null
try {
$c1auM = New-WnMission -Tag 'c1au' -Goals ([ordered]@{
    'G-WNOTHER' = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
    'G-WNAU'    = @('  - type: file_exists', '    path: evidence/absent.txt', ('  - type: ' + $esHoType))
})
if (-not $c1auM.ok) { throw ('FIXTURE REFUSED: ' + $c1auM.why) }
$c1auRoot = $c1auM.root
$c1auInst = Write-WnStub -Root $c1auRoot
$c1auOtherArt = Join-Path $c1auRoot '.mission\goals\G-WNOTHER.verdict.yaml'
$c1auOwnArt = Join-Path $c1auRoot '.mission\goals\G-WNAU.verdict.yaml'
$c1auCapture = Join-Path $c1auM.runsDir 'G-WNOTHER.inst.stdout.txt'
$c1auRecRel = '.mission-runtime/lam/handoff-admissions.jsonl'
$c1auRec = Join-Path $c1auRoot '.mission-runtime\lam\handoff-admissions.jsonl'
# THE TWO SENTENCES OF THE RULE, each as the handoff arm's entry opens it and as it closes (BUILD-SPEC section
# 6): what stands between -- the path, as the evaluator shows it -- is not asserted.
$c1auArtOpens = 'HANDOFF head NOT admitted -- the head names another goal''s verdict artifact as the brief ('
$c1auArtCloses = 'a file a goal''s evaluation rewrites is never a brief (register row 399)'
$c1auRunOpens = 'HANDOFF head NOT admitted -- the head names a file under instrument-runs as the brief ('
$c1auRunCloses = 'a capture a run rewrites is never a brief (register row 399)'

# THE FIXTURE's TWO FILES AND ITS RECORD. G-WNOTHER is evaluated ONCE, by hand, by this tree: that evaluation
# writes its verdict artifact beside its goal file and tees the stub's output to the live capture under
# instrument-runs -- the two files the rows below name. Then the base admits one ordinary brief as the
# hook, so the admissions record exists, one line long, written by the arm itself.
$c1auRuns = Get-WnRuns -Root $c1auRoot
$c1auOther = Invoke-WnEval -Tools tree -Root $c1auRoot -GoalId 'G-WNOTHER'
$c1auOtherRan = (Get-WnRuns -Root $c1auRoot) - $c1auRuns
$c1auOtherOnDisk = ((Test-Path -LiteralPath $c1auOtherArt -PathType Leaf) -and (Test-Path -LiteralPath $c1auCapture -PathType Leaf))
$c1auSeedBrief = Write-EsBytes -Root $c1auRoot -Rel '.mission-runtime/lam/handoff/brief-seed.md' -Bytes ($pwUtf8.GetBytes("the brief that seeds the admissions record`n"))
$c1auSeedSha = Get-PwRawSha -Path $c1auSeedBrief
Write-EsStatus -Root $c1auRoot -Head (Get-EsHead -Ctx '60' -Lf $c1auSeedSha -Raw $c1auSeedSha -Path '.mission-runtime/lam/handoff/brief-seed.md')
$c1auSeed = Invoke-WnEval -Tools base -Root $c1auRoot -GoalId 'G-WNAU' -AsStopHook
$c1auSeedRec = Get-EsRecord -Root $c1auRoot
$c1auSeedBytes = if ($c1auSeedRec.exists) { [System.IO.File]::ReadAllBytes($c1auRec) } else { $null }
Add-C1auRow -Label 'FIXTURE a git repository under %TEMP%, the base tools pinned; two goals committed -- G-WNOTHER (instrument_exit0 over the stub, no window) and G-WNAU (a failing file_exists and the handoff arm); porcelain exactly "?? scratch/"; G-WNOTHER EVALUATED ONCE by this tree, MET, the stub run once: its verdict artifact and its live capture stand on disk, the capture named by the entry; THE ADMISSIONS RECORD SEEDED by the base admitting an ordinary brief -- one line -- and put back to those bytes before every Stop below' `
    -Ok ($wnBase.ok -and ((Get-WnPorcelain -Root $c1auRoot) -ceq '?? scratch/') -and ($c1auM.head -cmatch '\A[0-9a-f]{40}\z') -and (Test-Path -LiteralPath $c1auInst -PathType Leaf) -and ($c1auOther.exit -eq 0) -and ($c1auOther.verdict -ceq 'MET') -and
         ($c1auOtherRan -eq 1) -and $c1auOtherOnDisk -and (Get-WnInst -Eval $c1auOther).detail.Contains($c1auCapture) -and ($c1auSeed.decision -ceq 'approve') -and ($c1auSeed.exit -eq 0) -and ($c1auSeed.verdict -ceq $esHoVerdict) -and ($c1auSeedRec.count -eq 1)) `
    -Said ('HEAD ' + $c1auM.head + '; G-WNOTHER: exit ' + $c1auOther.exit + ', ' + $c1auOther.verdict + ', the stub ran ' + $c1auOtherRan + '; artifact and capture on disk: ' + $c1auOtherOnDisk + ' (' + $c1auCapture + '); the seed stop: exit ' + $c1auSeed.exit + ', ' + $c1auSeed.decision + ', ' + $c1auSeed.verdict +
           '; the record: ' + $c1auSeedRec.count + ' line(s); ' + $wnBase.said)
if (-not $c1auOtherOnDisk) { throw 'FIXTURE REFUSED: the evaluation of G-WNOTHER left no verdict artifact, or no live capture, on disk -- there is no file of either class for a head to name' }
if ($null -eq $c1auSeedBytes) { throw 'FIXTURE REFUSED: the base admitted no seed brief, so there is no admissions record to read before and after a Stop' }

# (a) ANOTHER GOAL's VERDICT ARTIFACT, named as the evaluator writes it beside the goal file. THE RED, KEPT: the base.
$c1auAB = Invoke-C1auStop -Tools base -PathAsWritten '.mission\goals\G-WNOTHER.verdict.yaml' -Target $c1auOtherArt
Add-C1auRow -Label '(a) BASE CONTROL: the head names ANOTHER goal''s verdict artifact -- .mission\goals\G-WNOTHER.verdict.yaml, a real artifact, its digests the artifact''s own: the base ADMITS it -- HANDOFF_ADMITTED, approve, exit 0 -- and APPENDS ONE LINE to the admissions record, naming it' `
    -Ok $c1auAB.admitted -Said $c1auAB.said
$c1auAT = Invoke-C1auStop -Tools tree -PathAsWritten '.mission\goals\G-WNOTHER.verdict.yaml' -Target $c1auOtherArt
Add-C1auRow -Label '(a) FALSIFIER the same head at this tree: NOT admitted -- the hook blocks, NOT_MET; the handoff entry reads "HANDOFF head NOT admitted -- the head names another goal''s verdict artifact as the brief (" ... "a file a goal''s evaluation rewrites is never a brief"; handoff_refused holds exactly ONE entry; THE ADMISSIONS RECORD UNCHANGED, its sha256 and its line count' `
    -Ok (Test-C1auRefused -Reading $c1auAT -Opens $c1auArtOpens -Closes $c1auArtCloses) -Said $c1auAT.said
# ... THE CLASS's OTHER TWO DIRECTORIES (BUILD-SPEC section 6 names three). The evaluator looks for a goal file
#     under .mission\goals, then under .mission-runtime\lam\goals, and -GoalFile names one anywhere; the
#     verdict artifact is written BESIDE the goal file, wherever that is. The rule reads a NAME, so the file
#     each head names here is a file of that name in that directory -- its bytes a copy of G-WNOTHER's
#     artifact, its digests its own.
$c1auRtArt = Write-EsBytes -Root $c1auRoot -Rel '.mission-runtime/lam/goals/G-WNOTHER.verdict.yaml' -Bytes ([System.IO.File]::ReadAllBytes($c1auOtherArt))
$c1auAR = Invoke-C1auStop -Tools tree -PathAsWritten '.mission-runtime\lam\goals\G-WNOTHER.verdict.yaml' -Target $c1auRtArt
Add-C1auRow -Label '(a) FALSIFIER DIRECTORIES a file named as a goal''s verdict artifact in THE RUNTIME PLANE''s goals directory, .mission-runtime\lam\goals\G-WNOTHER.verdict.yaml (the second place the evaluator looks for a goal): refused the same way -- the hook blocks, NOT_MET, "the head names another goal''s verdict artifact as the brief (" ... "a file a goal''s evaluation rewrites is never a brief", handoff_refused exactly ONE entry -- THE ADMISSIONS RECORD UNCHANGED' `
    -Ok (Test-C1auRefused -Reading $c1auAR -Opens $c1auArtOpens -Closes $c1auArtCloses) -Said $c1auAR.said
$c1auAltGoal = Write-EsBytes -Root $c1auRoot -Rel 'scratch/alt/G-WNAU.yaml' -Bytes ([System.IO.File]::ReadAllBytes((Join-Path $c1auRoot '.mission\goals\G-WNAU.yaml')))
$c1auAltArt = Write-EsBytes -Root $c1auRoot -Rel 'scratch/alt/G-WNOTHER.verdict.yaml' -Bytes ([System.IO.File]::ReadAllBytes($c1auOtherArt))
$c1auAG = Invoke-C1auStop -Tools tree -PathAsWritten 'scratch\alt\G-WNOTHER.verdict.yaml' -Target $c1auAltArt -AltGoalFile $c1auAltGoal
Add-C1auRow -Label '(a) FALSIFIER DIRECTORIES a file named as a goal''s verdict artifact in THE GOAL FILE''s OWN DIRECTORY -- G-WNAU evaluated with -GoalFile <root>\scratch\alt\G-WNAU.yaml (a copy of its goal file), so its artifact is written to scratch\alt, and the head names scratch\alt\G-WNOTHER.verdict.yaml beside it: refused the same way -- the hook blocks, NOT_MET, the same sentence, handoff_refused exactly ONE entry -- THE ADMISSIONS RECORD UNCHANGED' `
    -Ok (Test-C1auRefused -Reading $c1auAG -Opens $c1auArtOpens -Closes $c1auArtCloses) -Said $c1auAG.said

# (b) THE LIVE CAPTURE UNDER instrument-runs, named by its absolute path, as the instrument_exit0 entry prints it.
$c1auBB = Invoke-C1auStop -Tools base -PathAsWritten $c1auCapture -Target $c1auCapture
Add-C1auRow -Label '(b) BASE CONTROL: the head names THE LIVE CAPTURE under instrument-runs -- <root>\.mission-runtime\lam\instrument-runs\G-WNOTHER.inst.stdout.txt, its digests the capture''s own: the base ADMITS it -- HANDOFF_ADMITTED, approve, exit 0 -- and APPENDS ONE LINE to the admissions record, naming it' `
    -Ok $c1auBB.admitted -Said $c1auBB.said
$c1auBT = Invoke-C1auStop -Tools tree -PathAsWritten $c1auCapture -Target $c1auCapture
Add-C1auRow -Label '(b) FALSIFIER the same head at this tree: NOT admitted -- the hook blocks, NOT_MET; the handoff entry reads "HANDOFF head NOT admitted -- the head names a file under instrument-runs as the brief (" ... "a capture a run rewrites is never a brief"; handoff_refused holds exactly ONE entry; THE ADMISSIONS RECORD UNCHANGED, its sha256 and its line count' `
    -Ok (Test-C1auRefused -Reading $c1auBT -Opens $c1auRunOpens -Closes $c1auRunCloses) -Said $c1auBT.said

# (c) THE SPELLINGS: each class under four more names of the same file. The rule is by NAME, both sides taken
#     to one spelling first, every comparison case folded -- so no spelling of the path walks past it.
$c1auSpellings = @(
    [pscustomobject]@{ what = 'ANOTHER goal''s verdict artifact'; label = 'in UPPER CASE (.MISSION\GOALS\G-WNOTHER.VERDICT.YAML)'; path = '.MISSION\GOALS\G-WNOTHER.VERDICT.YAML'; file = $c1auOtherArt; opens = $c1auArtOpens; closes = $c1auArtCloses },
    [pscustomobject]@{ what = 'ANOTHER goal''s verdict artifact'; label = 'by a \\?\ extended-length spelling of its absolute path (\\?\<root>\.mission\goals\G-WNOTHER.verdict.yaml)'; path = ('\\?\' + $c1auOtherArt); file = $c1auOtherArt; opens = $c1auArtOpens; closes = $c1auArtCloses },
    [pscustomobject]@{ what = 'ANOTHER goal''s verdict artifact'; label = 'by a dot-segment spelling (.mission\goals\..\goals\G-WNOTHER.verdict.yaml)'; path = '.mission\goals\..\goals\G-WNOTHER.verdict.yaml'; file = $c1auOtherArt; opens = $c1auArtOpens; closes = $c1auArtCloses },
    [pscustomobject]@{ what = 'ANOTHER goal''s verdict artifact'; label = 'by a forward-slash spelling (.mission/goals/G-WNOTHER.verdict.yaml)'; path = '.mission/goals/G-WNOTHER.verdict.yaml'; file = $c1auOtherArt; opens = $c1auArtOpens; closes = $c1auArtCloses },
    [pscustomobject]@{ what = 'THE LIVE CAPTURE under instrument-runs'; label = 'in UPPER CASE (.MISSION-RUNTIME\LAM\INSTRUMENT-RUNS\G-WNOTHER.INST.STDOUT.TXT)'; path = '.MISSION-RUNTIME\LAM\INSTRUMENT-RUNS\G-WNOTHER.INST.STDOUT.TXT'; file = $c1auCapture; opens = $c1auRunOpens; closes = $c1auRunCloses },
    [pscustomobject]@{ what = 'THE LIVE CAPTURE under instrument-runs'; label = 'by a \\?\ extended-length spelling of its absolute path (\\?\<root>\.mission-runtime\lam\instrument-runs\G-WNOTHER.inst.stdout.txt)'; path = ('\\?\' + $c1auCapture); file = $c1auCapture; opens = $c1auRunOpens; closes = $c1auRunCloses },
    [pscustomobject]@{ what = 'THE LIVE CAPTURE under instrument-runs'; label = 'by a dot-segment spelling (.mission-runtime\lam\instrument-runs\..\instrument-runs\G-WNOTHER.inst.stdout.txt)'; path = '.mission-runtime\lam\instrument-runs\..\instrument-runs\G-WNOTHER.inst.stdout.txt'; file = $c1auCapture; opens = $c1auRunOpens; closes = $c1auRunCloses },
    [pscustomobject]@{ what = 'THE LIVE CAPTURE under instrument-runs'; label = 'by a forward-slash spelling (.mission-runtime/lam/instrument-runs/G-WNOTHER.inst.stdout.txt)'; path = '.mission-runtime/lam/instrument-runs/G-WNOTHER.inst.stdout.txt'; file = $c1auCapture; opens = $c1auRunOpens; closes = $c1auRunCloses })
foreach ($c1auSp in $c1auSpellings) {
    $c1auC = Invoke-C1auStop -Tools tree -PathAsWritten $c1auSp.path -Target $c1auSp.file
    Add-C1auRow -Label ('(c) FALSIFIER SPELLINGS ' + $c1auSp.what + ', named ' + $c1auSp.label + ': refused the same way -- the hook blocks, NOT_MET, the class''s own sentence in the handoff entry, handoff_refused exactly ONE entry -- THE ADMISSIONS RECORD UNCHANGED') `
        -Ok (Test-C1auRefused -Reading $c1auC -Opens $c1auSp.opens -Closes $c1auSp.closes) -Said $c1auC.said
}
# (c) ... AND TWO SPELLINGS THAT WALKED PAST THE RULE AS IT WAS FIRST BUILT (the builder-side review's finding
#     ). Behind a \\?\ prefix the full-path call normalises NOTHING, so with the prefix taken off a name
#     could still be spelled another way. ONE: the 8.3 (short) spelling of the file's DIRECTORY, as this
#     volume gives it (Get-C1auShortDir) -- each class. Where the volume gives no short name that differs
#     the row says so and asserts on the long spelling. TWO, class 1 only: the file's default data stream,
#     `::$DATA` -- the name then ends on that and not on .verdict.yaml (under instrument-runs the prefix
#     test already holds it).
foreach ($c1auShort in @(
        [pscustomobject]@{ what = 'ANOTHER goal''s verdict artifact'; file = $c1auOtherArt; opens = $c1auArtOpens; closes = $c1auArtCloses },
        [pscustomobject]@{ what = 'THE LIVE CAPTURE under instrument-runs'; file = $c1auCapture; opens = $c1auRunOpens; closes = $c1auRunCloses })) {
    $c1auLongDir = Split-Path -Parent $c1auShort.file
    $c1auShortDir = Get-C1auShortDir -Dir $c1auLongDir
    $c1auHasShort = ([bool]$c1auShortDir -and (-not [string]::Equals($c1auShortDir, $c1auLongDir, [System.StringComparison]::OrdinalIgnoreCase)))
    $c1auShortPath = '\\?\' + $(if ($c1auHasShort) { $c1auShortDir } else { $c1auLongDir }) + '\' + (Split-Path -Leaf $c1auShort.file)
    $c1auCShort = Invoke-C1auStop -Tools tree -PathAsWritten $c1auShortPath -Target $c1auShort.file
    Add-C1auRow -Label ('(c) FALSIFIER SPELLINGS ' + $c1auShort.what + ', named by \\?\ and the 8.3 (SHORT) spelling of its directory, taken from the file system: refused the same way -- the hook blocks, NOT_MET, the class''s own sentence in the handoff entry, handoff_refused exactly ONE entry -- THE ADMISSIONS RECORD UNCHANGED') `
        -Ok (Test-C1auRefused -Reading $c1auCShort -Opens $c1auShort.opens -Closes $c1auShort.closes) `
        -Said ($(if ($c1auHasShort) { 'the head names ' + $c1auShortPath } else { 'THIS VOLUME GIVES NO SHORT NAME THAT DIFFERS for ' + $c1auLongDir + ' -- the row asserts on the long spelling, ' + $c1auShortPath }) + ' | ' + $c1auCShort.said)
}
$c1auStreamPath = '\\?\' + $c1auOtherArt + '::$DATA'
$c1auCStream = Invoke-C1auStop -Tools tree -PathAsWritten $c1auStreamPath -Target $c1auOtherArt
Add-C1auRow -Label '(c) FALSIFIER SPELLINGS ANOTHER goal''s verdict artifact, named by \\?\ and its default data stream (\\?\<root>\.mission\goals\G-WNOTHER.verdict.yaml::$DATA): the head is REFUSED, never admitted -- the hook blocks, NOT_MET, the handoff entry opens "HANDOFF head NOT admitted -- ", handoff_refused exactly ONE entry -- THE ADMISSIONS RECORD UNCHANGED (a name that has no full form once its prefix is off is refused in the arm''s own sentence for a head it could not establish, not in the class''s)' `
    -Ok (($c1auCStream.decision -ceq 'block') -and ($c1auCStream.exit -eq 0) -and ($c1auCStream.verdict -ceq 'NOT_MET') -and (-not $c1auCStream.admitted) -and $c1auCStream.detail.StartsWith('HANDOFF head NOT admitted -- ') -and
         ($c1auCStream.refusedCount -eq 1) -and ($c1auCStream.shaAfter -ceq $c1auCStream.shaBefore) -and ($c1auCStream.linesAfter -eq $c1auCStream.linesBefore)) `
    -Said ('the head names ' + $c1auStreamPath + ' | ' + $c1auCStream.said)

# (d) WHAT DOES NOT MOVE. An ordinary brief -- in the runtime plane, BESIDE instrument-runs and not under it --
#     is admitted by this tree as the base admits it: the same head over the same record, one evaluator
#     after the other, and the two verdict artifacts are equal but for the clock (G-WNAU declares no window
#     and no instrument, so no key of this batch is written into either).
$c1auBriefA = Write-EsBytes -Root $c1auRoot -Rel '.mission-runtime/lam/handoff/brief-a.md' -Bytes ($pwUtf8.GetBytes("an ordinary brief`n"))
$c1auDT = Invoke-C1auStop -Tools tree -PathAsWritten '.mission-runtime/lam/handoff/brief-a.md' -Target $c1auBriefA
$c1auDB = Invoke-C1auStop -Tools base -PathAsWritten '.mission-runtime/lam/handoff/brief-a.md' -Target $c1auBriefA
$c1auDSame = ([bool]$c1auDT.text -and ((Get-WnComparable -Text (Remove-WrProvenanceLine -Text $c1auDT.text)) -ceq (Get-WnComparable -Text $c1auDB.text)))
Add-C1auRow -Label '(d) CONTROL an ORDINARY brief, .mission-runtime/lam/handoff/brief-a.md (beside instrument-runs, not under it): ADMITTED by this tree -- HANDOFF_ADMITTED, approve, exit 0, one line appended naming it -- as the base admits the same head over the same record; the two verdict artifacts EQUAL but for the clock, the two hook stdouts equal' `
    -Ok ($c1auDT.admitted -and $c1auDB.admitted -and $c1auDSame -and ($c1auDT.stdout -ceq $c1auDB.stdout) -and ($c1auDT.stderr -ceq '') -and ($c1auDT.refusedCount -eq 0)) `
    -Said ($c1auDT.said + ' | ' + $c1auDB.said + ' | artifacts equal but for the clock: ' + $c1auDSame + '; stdouts equal: ' + ($c1auDT.stdout -ceq $c1auDB.stdout))
# ... A NAME THAT ONLY BEGINS LIKE THE CLASS's: a brief in a SIBLING of instrument-runs whose own name begins
#     "instrument-runs". The class is the files UNDER <root>\.mission-runtime\lam\instrument-runs\ -- the
#     separator is part of the name -- so this one is a brief like any other.
$c1auBriefN = Write-EsBytes -Root $c1auRoot -Rel '.mission-runtime/lam/instrument-runs-notes/brief-n.md' -Bytes ($pwUtf8.GetBytes("an ordinary brief, in a directory beside instrument-runs`n"))
$c1auDN = Invoke-C1auStop -Tools tree -PathAsWritten '.mission-runtime/lam/instrument-runs-notes/brief-n.md' -Target $c1auBriefN
$c1auDNB = Invoke-C1auStop -Tools base -PathAsWritten '.mission-runtime/lam/instrument-runs-notes/brief-n.md' -Target $c1auBriefN
$c1auDNSame = Test-C1auAsBase -Reading $c1auDN -Control $c1auDNB
Add-C1auRow -Label '(d) CONTROL a brief in a SIBLING directory whose name BEGINS "instrument-runs", .mission-runtime/lam/instrument-runs-notes/brief-n.md, is not a file under instrument-runs: ADMITTED -- HANDOFF_ADMITTED, approve, exit 0, one line appended naming it -- by this tree as by the base; the two verdict artifacts EQUAL but for the clock, the two hook stdouts equal' `
    -Ok ($c1auDN.admitted -and $c1auDNB.admitted -and $c1auDNSame) `
    -Said ($c1auDN.said + ' | ' + $c1auDNB.said + ' | artifacts equal but for the clock and stdouts equal: ' + $c1auDNSame)
# ... THE ADMISSIONS RECORD NAMED AS THE BRIEF: refused in the RECORD's sentence,
#     by this tree as by the base -- the same head over the same record, one evaluator after the other.
$c1auRecOpens = 'HANDOFF head NOT admitted -- the head names the admissions record itself as the brief ('
$c1auRecCloses = 'it is never a brief (register row 360 member (1))'
$c1auDR = Invoke-C1auStop -Tools tree -PathAsWritten $c1auRecRel -Target $c1auRec
$c1auDRB = Invoke-C1auStop -Tools base -PathAsWritten $c1auRecRel -Target $c1auRec
$c1auDRSame = Test-C1auAsBase -Reading $c1auDR -Control $c1auDRB
Add-C1auRow -Label '(d) CONTROL the admissions record itself named as the brief: refused in ITS OWN sentence -- "the head names the admissions record itself as the brief (" ... "it is never a brief" -- and not in the new rule''s, by this tree as by the base; handoff_refused one entry; the record unchanged; the two verdict artifacts EQUAL but for the clock, the two hook stdouts equal' `
    -Ok ((Test-C1auRefused -Reading $c1auDR -Opens $c1auRecOpens -Closes $c1auRecCloses) -and (-not $c1auDR.detail.Contains('register row 399')) -and (Test-C1auRefused -Reading $c1auDRB -Opens $c1auRecOpens -Closes $c1auRecCloses) -and $c1auDRSame) `
    -Said ($c1auDR.said + ' | ' + $c1auDRB.said + ' | artifacts equal but for the clock and stdouts equal: ' + $c1auDRSame)
# ... THE GOAL's OWN VERDICT ARTIFACT (the Stop above left it on disk; -KeepArtifact leaves it there to be
#     named). It IS a file whose name ends .verdict.yaml in the goals directory, and it is still refused in
#     ITS OWN sentence: the older refusal stands AHEAD of the new one. By this tree, then by the base --
#     each Stop rewrites the artifact, so each head carries the digest of the bytes that Stop found, and that
#     digest (in the entry's "-- head:" tail, nowhere else) is the one thing masked before the two artifacts
#     are compared.
$c1auOwnOpens = 'HANDOFF head NOT admitted -- the head names the goal''s own verdict artifact as the brief ('
$c1auOwnCloses = 'it is never a brief (register row 377)'
$c1auDOLabel = '(d) CONTROL the goal''s OWN verdict artifact, .mission/goals/G-WNAU.verdict.yaml, named as the brief: refused in ITS OWN sentence -- "the head names the goal''s own verdict artifact as the brief (" ... "it is never a brief" -- NOT as "another goal''s verdict artifact", though its name ends .verdict.yaml in the goals directory -- by this tree as by the base; handoff_refused one entry; the record unchanged; the two verdict artifacts EQUAL but for the clock and the digest each head carries, the two hook stdouts equal'
if (Test-Path -LiteralPath $c1auOwnArt -PathType Leaf) {
    $c1auDO = Invoke-C1auStop -Tools tree -PathAsWritten '.mission/goals/G-WNAU.verdict.yaml' -Target $c1auOwnArt -KeepArtifact
    $c1auDOB = $null
    if (Test-Path -LiteralPath $c1auOwnArt -PathType Leaf) { $c1auDOB = Invoke-C1auStop -Tools base -PathAsWritten '.mission/goals/G-WNAU.verdict.yaml' -Target $c1auOwnArt -KeepArtifact }
    $c1auDOSame = (($null -ne $c1auDOB) -and (Test-C1auAsBase -Reading $c1auDO -Control $c1auDOB -MaskDigest))
    Add-C1auRow -Label $c1auDOLabel `
        -Ok ((Test-C1auRefused -Reading $c1auDO -Opens $c1auOwnOpens -Closes $c1auOwnCloses) -and (-not $c1auDO.detail.Contains('another goal''s verdict artifact')) -and (-not $c1auDO.detail.Contains('register row 399')) -and
             ($null -ne $c1auDOB) -and (Test-C1auRefused -Reading $c1auDOB -Opens $c1auOwnOpens -Closes $c1auOwnCloses) -and $c1auDOSame) `
        -Said ($c1auDO.said + ' | ' + $(if ($null -ne $c1auDOB) { $c1auDOB.said } else { 'base: UNMEASURED, the tree''s Stop left no verdict artifact of G-WNAU on disk' }) + ' | artifacts equal but for the clock and the head''s digest, and stdouts equal: ' + $c1auDOSame)
} else { Add-C1auRow -Label $c1auDOLabel -Ok $false -Said 'UNMEASURED: the Stop above left no verdict artifact of G-WNAU on disk, so there is no file of that name for a head to name' }

# (e) STATED, NOT CLAIMED -- WHAT THE RULE DOES NOT REACH. It reads a NAME: a copy of the other goal's artifact
#     under scratch\ carries the same leaf name in another directory and is another file; a hard link to
#     the live capture under scratch\ is THE SAME FILE under a name that is not under instrument-runs. Each
#     is admitted like any brief. (By identity is how the two older refusals reach a hard link; this rule does not.)
#     Each head is read by this tree and then by the base, over the same record: the two readings are one.
$c1auCopy = Write-EsBytes -Root $c1auRoot -Rel 'scratch/G-WNOTHER.verdict.yaml' -Bytes ([System.IO.File]::ReadAllBytes($c1auOtherArt))
$c1auEC = Invoke-C1auStop -Tools tree -PathAsWritten 'scratch/G-WNOTHER.verdict.yaml' -Target $c1auCopy
$c1auECB = Invoke-C1auStop -Tools base -PathAsWritten 'scratch/G-WNOTHER.verdict.yaml' -Target $c1auCopy
$c1auECSame = Test-C1auAsBase -Reading $c1auEC -Control $c1auECB
Add-C1auRow -Label '(e) STATED, NOT CLAIMED: a COPY of the other goal''s artifact placed under scratch\ -- the same bytes and the same leaf name, G-WNOTHER.verdict.yaml, in a directory that is no goals directory: ADMITTED like any brief -- HANDOFF_ADMITTED, approve, exit 0, one line appended naming it -- by this tree as by the base, the two verdict artifacts EQUAL but for the clock, the two hook stdouts equal' `
    -Ok ($c1auEC.admitted -and $c1auECB.admitted -and $c1auECSame -and ((Get-PwRawSha -Path $c1auCopy) -ceq (Get-PwRawSha -Path $c1auOtherArt))) `
    -Said ($c1auEC.said + ' | ' + $c1auECB.said + ' | artifacts equal but for the clock and stdouts equal: ' + $c1auECSame)
# ... AND THE OTHER HALF OF THAT NAME: the right directory, another name. The other goal's GOAL FILE stands in
#     the goals directory and its name does not end .verdict.yaml -- no evaluation rewrites it -- so it too
#     is a brief like any other.
$c1auGoalFile = Join-Path $c1auRoot '.mission\goals\G-WNOTHER.yaml'
$c1auEG = Invoke-C1auStop -Tools tree -PathAsWritten '.mission/goals/G-WNOTHER.yaml' -Target $c1auGoalFile
$c1auEGB = Invoke-C1auStop -Tools base -PathAsWritten '.mission/goals/G-WNOTHER.yaml' -Target $c1auGoalFile
$c1auEGSame = Test-C1auAsBase -Reading $c1auEG -Control $c1auEGB
Add-C1auRow -Label '(e) STATED, NOT CLAIMED: the other goal''s GOAL FILE, .mission/goals/G-WNOTHER.yaml -- in the goals directory, its name NOT ending .verdict.yaml, a file no evaluation rewrites: ADMITTED like any brief -- HANDOFF_ADMITTED, approve, exit 0, one line appended naming it -- by this tree as by the base, the two verdict artifacts EQUAL but for the clock, the two hook stdouts equal' `
    -Ok ($c1auEG.admitted -and $c1auEGB.admitted -and $c1auEGSame) `
    -Said ($c1auEG.said + ' | ' + $c1auEGB.said + ' | artifacts equal but for the clock and stdouts equal: ' + $c1auEGSame)
$c1auLink = Join-Path $c1auM.scratch 'capture-link.txt'
$null = New-Item -ItemType HardLink -Path $c1auLink -Target $c1auCapture
$c1auLinkType = [string](Get-Item -LiteralPath $c1auLink -Force).LinkType
$c1auEL = Invoke-C1auStop -Tools tree -PathAsWritten 'scratch/capture-link.txt' -Target $c1auLink
$c1auELB = Invoke-C1auStop -Tools base -PathAsWritten 'scratch/capture-link.txt' -Target $c1auLink
$c1auELSame = Test-C1auAsBase -Reading $c1auEL -Control $c1auELB
Add-C1auRow -Label '(e) STATED, NOT CLAIMED: a HARD LINK to the live capture placed under scratch\ -- the same file, under a name that is not under instrument-runs: ADMITTED like any brief -- HANDOFF_ADMITTED, approve, exit 0, one line appended naming it -- by this tree as by the base, the two verdict artifacts EQUAL but for the clock, the two hook stdouts equal; the rule reads the name, never the file''s identity' `
    -Ok ($c1auEL.admitted -and $c1auELB.admitted -and $c1auELSame -and ($c1auLinkType -ceq 'HardLink')) `
    -Said ('scratch\capture-link.txt is a ' + $c1auLinkType + ' | ' + $c1auEL.said + ' | ' + $c1auELB.said + ' | artifacts equal but for the clock and stdouts equal: ' + $c1auELSame)
# ... AND A NAME THE HOST ITSELF GIVES THE LIVE CAPTURE (the independent validator's round 1): the UNC
#     spelling \\localhost\<drive>$\<the rest of its absolute path>, through the drive's administrative share.
#     It is the capture ITSELF -- no copy, no link -- and its name does not open with this mission's
#     instrument-runs as the rule spells that root, so the rule, which reads a name, does not see it: the head
#     is ADMITTED and a line appended, where the plain spelling of the same file is refused (row (b)). STATED,
#     NOT CLAIMED, and read by this tree alone. WHETHER IT CAN BE DRIVEN IS THE HOST's: where the spelled
#     directory does not answer (no such share, or no right to it) no Stop is made, the row says so and reads
#     ok -- it then states the residual and measures nothing.
$c1auUncDir = '\\localhost\' + $c1auCapture.Substring(0, 1) + '$' + (Split-Path -Parent $c1auCapture).Substring(2)
$c1auUncPath = $c1auUncDir + '\' + (Split-Path -Leaf $c1auCapture)
$c1auUncLabel = '(e) STATED, NOT CLAIMED: THE LIVE CAPTURE named by a UNC spelling of this host, \\localhost\<drive>$\<the rest of its absolute path> -- the same file, under a name that is not under <root>\.mission-runtime\lam\instrument-runs\ as the rule spells it: ADMITTED like any brief -- HANDOFF_ADMITTED, approve, exit 0, one line appended naming it, handoff_refused empty -- at this tree (read by this tree alone; where \\localhost\<drive>$ does not answer on the host the row says so and asserts no admission): the rule is BY NAME ONLY -- a capture is refused under the spellings driven, not under every name the host gives it'
$c1auUncAnswers = $false
try { $c1auUncAnswers = [bool](Test-Path -LiteralPath $c1auUncDir -PathType Container) } catch { $c1auUncAnswers = $false }
if ($c1auUncAnswers) {
    $c1auEU = Invoke-C1auStop -Tools tree -PathAsWritten $c1auUncPath -Target $c1auCapture
    Add-C1auRow -Label $c1auUncLabel -Ok ($c1auEU.admitted -and ($c1auEU.refusedCount -eq 0)) -Said ('the head names ' + $c1auUncPath + ' | ' + $c1auEU.said)
} else {
    Add-C1auRow -Label $c1auUncLabel -Ok $true -Said ('NOT DRIVEN ON THIS HOST: ' + $c1auUncDir + ' does not answer (Test-Path of that directory is false), so no Stop was made and no admission is asserted -- the residual stands as stated, unmeasured here')
}
}
catch {
    $c1auOk = $false
    $c1auRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1auRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1auM) { Remove-PwTreeAsWritten -Base $c1auM.base }
Check -Id 'C-1au' -Title 'TWO PATH CLASSES REFUSED AS A BRIEF BY NAME (the BATCH-5 charter, REC-A WP-N (e), as the operator''s rulings of 2026-10-11 left it): a HANDOFF head naming ANOTHER goal''s verdict artifact in the goals directory, or the live capture under instrument-runs, with that file''s own digests, is ADMITTED by the base evaluator and a line is appended to the admissions record -- the own-artifact rule left both as its residual, files a run rewrites that were still briefs -- and this tree REFUSES each BY ITS NAME: the hook blocks, NOT_MET, the handoff arm''s entry reads "the head names another goal''s verdict artifact as the brief ... a file a goal''s evaluation rewrites is never a brief" or "the head names a file under instrument-runs as the brief ... a capture a run rewrites is never a brief", handoff_refused holds exactly one entry, and THE ADMISSIONS RECORD IS UNCHANGED, its sha256 and its line count the same before and after; a file named as a verdict artifact is refused the same way in the class''s two other directories -- the runtime plane''s goals directory, and the goal file''s own directory where -GoalFile names one; each class is refused the same way under four more spellings of the file''s name -- UPPER CASE, a \\?\ extended-length path, a dot-segment path, forward slashes -- and under \\?\ with the 8.3 (short) spelling of its directory, and a head naming the other goal''s artifact by \\?\ and its default data stream (::$DATA) is refused too, in the arm''s own sentence (the builder-side review''s finding: both walked past the rule as it was first built); an ORDINARY brief is admitted by this tree as by the base, and so is a brief in a sibling directory whose name only BEGINS "instrument-runs"; the admissions record itself and the goal''s OWN verdict artifact are still refused in their own sentences and never in the new one, by this tree as by the base; and what the rule does not reach is measured, not claimed -- a COPY of the other goal''s artifact under scratch\ (the name without the directory), the other goal''s GOAL FILE in the goals directory (the directory without the name) and a HARD LINK to the live capture under scratch\ are each admitted like any brief, by this tree as by the base, because the rule reads a name, the whole of it, and never a file''s identity -- and so, stated and not claimed, is the live capture ITSELF under a UNC spelling of this host (\\localhost\<drive>$\...), at this tree, wherever the host answers that spelling: refused as a brief BY NAME, not by identity (the independent validator''s round 1); in each of those seven controls the tree''s verdict artifact and the base''s are equal but for the clock (and, where the head names the goal''s own artifact, the digest that head carries) and the two hook stdouts are equal' `
      -Ok $c1auOk -Detail ("      THE $(@($c1auRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1auRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument G-WNOTHER names; it is run ONCE, by the fixture's evaluation of that goal, and the capture of that run is the file rows (b), (c) and (e) name:`n" + (Get-WlIndented -Text $wnStubText) + "`n      G-WNAU, the goal every Stop here evaluates, is one failing file_exists detector and the handoff arm, and the head a row writes is`n          | HANDOFF AT 60% <sha256 of the named file's bytes>; <the same sha256> <the path under test>")

# =============================================================================================
# C-1av -- A MISSION ROOT THAT IS NO DIRECTORY BLOCKS: as the Stop hook, a
#          -MissionRoot that names no directory -- a path that does not exist, a file, the empty string --
#          REFUSES the stop it used to admit
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: the hook launched with a
# -MissionRoot that does not exist prints {"decision":"approve","reason":"goal-check: mission root not found:
# <root> -- not blocking."} and exits 0. A hook whose root is misspelt, moved or deleted reads no goal, writes
# no verdict and ADMITS EVERY STOP -- measured "not reached" by C-2f (j). And
# the EMPTY root never reaches the file at all: PowerShell's binder refuses '' for a mandatory string --
# exit 1, nothing on stdout, no decision.
# THE RULE: AS THE HOOK a mission root that is no
# directory BLOCKS, in the form NOT_MET blocks in -- the reason one line on STDERR behind `goal-check: `, and
# {"decision":"block","reason":...} ALONE on stdout, exit 0. The empty string is among them: -MissionRoot
# admits it, and emptiness is tested before the path is.
# THE CONTROLS, each a row: BY HAND a non-directory is the base's one line and exit 2, byte for byte (the
# empty root now takes that branch, where the binder's exit 1 was); THE WORKER GUARD STAYS ABOVE IT -- with
# LAM_DISPATCH set the hook approves, whatever the root; and WHAT IS NOT CURED IS STATED: with no
# -MissionRoot argument at all the binder still fails under -NonInteractive, and as the house launches a hook
# the prompt for the mandatory parameter reads the Stop payload for the root -- which now blocks too, AFTER
# the echoed payload, so that stdout is not one JSON object.
# THIS MEMBER HAS NO MISSION, NO GOAL FILE AND NO STUB: every launch names a root that is no directory, or
# none, so nothing is evaluated and nothing is added to the list the plane row reads.
$c1avOk = $true
$c1avRows = New-Object System.Collections.Generic.List[string]
function Add-C1avRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1avOk = $false }
    $script:c1avRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1avRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1avLines {
    # The non-blank lines of one stream, CR dropped: an array, also of none and of one.
    param([string]$Text)
    return ,@(($Text -replace "`r", '') -split "`n" | Where-Object { $_.Trim() })
}
function Get-C1avSaid {
    # One reading of Invoke-WnEval, said whole: whose tools, the exit, the decision read off stdout, and the
    # two streams APART.
    param([string]$Who, $Reading)
    return ($Who + ': exit ' + $Reading.exit + ', decision [' + $Reading.decision + ']; stdout: [' + ([string]$Reading.stdout).Trim() + '] | stderr: [' + ([string]$Reading.stderr).Trim() + ']')
}
function Test-C1avBlock {
    # ONE hook reading held to the FORM the rule gives a block: exit 0; stdout ONE line and that line one JSON
    # object whose decision is block; STDERR one line, `goal-check: ` and then that same reason. What the
    # reason must SAY is the row's own.
    param($Reading)
    $c1avOut = Get-C1avLines -Text ([string]$Reading.stdout)
    $c1avErr = Get-C1avLines -Text ([string]$Reading.stderr)
    return (($Reading.exit -eq 0) -and ($Reading.decision -ceq 'block') -and ($c1avOut.Count -eq 1) -and $c1avOut[0].Trim().StartsWith('{') -and $c1avOut[0].Trim().EndsWith('}') -and
            [bool]$Reading.reason -and ($c1avErr.Count -eq 1) -and (([string]$Reading.stderr).Trim() -ceq ('goal-check: ' + $Reading.reason)))
}
function Get-C1avAfterPayload {
    # WHERE THE STOP PAYLOAD IS ECHOED AHEAD OF THE DECISION ON ONE STDOUT LINE -- the prompt for a missing
    # mandatory -MissionRoot read it off stdin -- that line is not one JSON object and Invoke-WnEval's
    # decision is ''. This reads what FOLLOWS the payload: echoed (stdout opens with the payload, byte for
    # byte), rest (what follows it, trimmed), and rest's decision and reason where rest is one JSON object
    # ('' where it is not).
    param($Reading)
    $c1avStd = [string]$Reading.stdout
    $c1avAfter = [pscustomobject]@{ echoed = $false; rest = ''; decision = ''; reason = '' }
    if (-not $c1avStd.StartsWith($script:wnStopPayload, [System.StringComparison]::Ordinal)) { return $c1avAfter }
    $c1avAfter.echoed = $true
    $c1avAfter.rest = $c1avStd.Substring($script:wnStopPayload.Length).Trim()
    if ($c1avAfter.rest.StartsWith('{')) {
        try { $c1avJson = $c1avAfter.rest | ConvertFrom-Json; $c1avAfter.decision = [string]$c1avJson.decision; $c1avAfter.reason = [string]$c1avJson.reason } catch { }
    }
    return $c1avAfter
}
# THE WORDS THE RULE FIXES, each copied from the batch's build contract; '<shown>' -- how the root is
# written between the two -- is not fixed there and is not asserted here. For the EMPTY root the contract
# fixes the middle of the reason and not how it opens or closes: two pieces of that middle are asserted,
# apart -- that the root is the empty string, and the clause that carries the register row.
$c1avOpens     = "Goal 'G-WNAV' is NOT_MET: the mission root '"
$c1avNotDir    = 'is not a directory, so no goal can be read and no verdict written (register row 401).'
$c1avEmptyRoot = 'the mission root is the empty string'
$c1avNoVerdict = 'so no goal can be read and no verdict written (register row 401).'
$c1avHandLine  = 'mission-goal-check: mission root not found: '
$c1avDir = ''
try {
$c1avDir = Join-Path $env:TEMP ('lam-wp3-c1av-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
New-Item -ItemType Directory -Path $c1avDir -Force | Out-Null
$c1avMissing = Join-Path $c1avDir 'no-such-root'
$c1avFile = Join-Path $c1avDir 'a-file-not-a-directory'
Write-Utf8 -Path $c1avFile -Text "a FILE where a mission root was named`n"
$c1avFileSha = Get-PwRawSha -Path $c1avFile
Add-C1avRow -Label 'FIXTURE no mission, no goal file, no stub: a directory of this member''s own under %TEMP% holding ONE FILE, and beside the file a name nothing stands at; the base tools pinned; LAM_DISPATCH is out of every child''s environment but rows (d) and (d2)''s' `
    -Ok ($wnBase.ok -and [System.IO.Path]::GetFullPath($c1avDir).StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase) -and [System.IO.Directory]::Exists($c1avDir) -and (Test-Path -LiteralPath $c1avFile -PathType Leaf) -and (-not (Test-Path -LiteralPath $c1avMissing))) `
    -Said ('the file ' + $c1avFile + ' sha256 ' + $c1avFileSha.Substring(0, 8) + '; the root that does not exist ' + $c1avMissing + '; ' + $wnBase.said)

# (a) THE RULING's FALSIFIER: a -MissionRoot that does not exist, as the Stop hook -- then THE RED, KEPT.
$c1avA = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -MissionRootArg $c1avMissing
Add-C1avRow -Label '(a) FALSIFIER -MissionRoot <a path that does not exist>, as the Stop hook: the stop is BLOCKED -- exit 0, stdout ONE JSON object, decision block, its reason opening "Goal ''G-WNAV'' is NOT_MET: the mission root ''" and saying it "is not a directory, so no goal can be read and no verdict written."; STDERR one line, "goal-check: " and that same reason; nothing is created at the path' `
    -Ok ((Test-C1avBlock -Reading $c1avA) -and $c1avA.reason.StartsWith($c1avOpens) -and $c1avA.reason.Contains($c1avNotDir) -and (-not (Test-Path -LiteralPath $c1avMissing))) -Said (Get-C1avSaid -Who 'tree' -Reading $c1avA)
$c1avAB = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -MissionRootArg $c1avMissing
Add-C1avRow -Label '(a) BASE CONTROL: the same launch at the base -- APPROVE, exit 0 -- "goal-check: mission root not found: <the path> -- not blocking." -- and STDERR EMPTY: a hook whose root does not exist admits the stop, nothing read and nothing written' `
    -Ok (($c1avAB.decision -ceq 'approve') -and ($c1avAB.exit -eq 0) -and ($c1avAB.reason -ceq ('goal-check: mission root not found: ' + $c1avMissing + ' -- not blocking.')) -and ($c1avAB.stderr -ceq '') -and (-not (Test-Path -LiteralPath $c1avMissing))) `
    -Said (Get-C1avSaid -Who 'base' -Reading $c1avAB)

# (a2) THE SAME FOR A PATH THAT IS A FILE: something stands there, and it is no directory.
$c1avA2 = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -MissionRootArg $c1avFile
Add-C1avRow -Label '(a2) FALSIFIER -MissionRoot <a path that is a FILE>, as the Stop hook: BLOCKED in the same form and the same words -- exit 0, one JSON object, decision block, "... is not a directory, so no goal can be read and no verdict written."; STDERR one "goal-check: " line with that reason; the file is byte for byte what it was' `
    -Ok ((Test-C1avBlock -Reading $c1avA2) -and $c1avA2.reason.StartsWith($c1avOpens) -and $c1avA2.reason.Contains($c1avNotDir) -and (Test-Path -LiteralPath $c1avFile -PathType Leaf) -and ((Get-PwRawSha -Path $c1avFile) -ceq $c1avFileSha)) -Said (Get-C1avSaid -Who 'tree' -Reading $c1avA2)
$c1avA2B = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -MissionRootArg $c1avFile
Add-C1avRow -Label '(a2) BASE CONTROL: the same launch at the base -- APPROVE, exit 0, "mission root not found: <the file> -- not blocking.", STDERR EMPTY' `
    -Ok (($c1avA2B.decision -ceq 'approve') -and ($c1avA2B.exit -eq 0) -and ($c1avA2B.reason -ceq ('goal-check: mission root not found: ' + $c1avFile + ' -- not blocking.')) -and ($c1avA2B.stderr -ceq '') -and ((Get-PwRawSha -Path $c1avFile) -ceq $c1avFileSha)) `
    -Said (Get-C1avSaid -Who 'base' -Reading $c1avA2B)

# (b) THE EMPTY ROOT: the child's line carries -MissionRoot "" and the child receives ''.
$c1avB = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -MissionRootArg ''
Add-C1avRow -Label '(b) FALSIFIER THE EMPTY ROOT (D9 (ii)) -MissionRoot "" as the Stop hook: the parameter ADMITS the empty string and the stop is BLOCKED -- exit 0, one JSON object, decision block, the reason saying "the mission root is the empty string" and "so no goal can be read and no verdict written."; STDERR one "goal-check: " line with that reason' `
    -Ok ((Test-C1avBlock -Reading $c1avB) -and $c1avB.reason.Contains($c1avEmptyRoot) -and $c1avB.reason.Contains($c1avNoVerdict) -and $c1avB.commandLine.Contains(' -MissionRoot "" -AsStopHook')) -Said (Get-C1avSaid -Who 'tree' -Reading $c1avB)
$c1avBB = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -MissionRootArg ''
Add-C1avRow -Label '(b) BASE CONTROL: the same launch at the base -- PowerShell''s own binder refuses the empty string before a line of the file runs -- EXIT 1, STDOUT EMPTY, no decision; stderr names MissionRoot' `
    -Ok (($c1avBB.exit -eq 1) -and ($c1avBB.stdout -ceq '') -and ($c1avBB.decision -ceq '') -and $c1avBB.stderr.Contains('MissionRoot') -and $c1avBB.commandLine.Contains(' -MissionRoot "" -AsStopHook')) -Said (Get-C1avSaid -Who 'base' -Reading $c1avBB)

# (c) BY HAND, A NON-DIRECTORY: what a human reads is what it was -- the path that does not exist, then the file.
$c1avC = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -MissionRootArg $c1avMissing
$c1avCB = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -MissionRootArg $c1avMissing
$c1avCF = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -MissionRootArg $c1avFile
$c1avCFB = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -MissionRootArg $c1avFile
Add-C1avRow -Label '(c) CONTROL BY HAND, a non-directory -- the path that does not exist, then the file: EXIT 2 and the ONE line "mission-goal-check: mission root not found: <the path>", stderr empty, ON BOTH TOOLS -- this tree''s stdout the base''s byte for byte, both times' `
    -Ok (($c1avC.exit -eq 2) -and ($c1avCB.exit -eq 2) -and ($c1avCF.exit -eq 2) -and ($c1avCFB.exit -eq 2) -and ($c1avCB.stdout.Trim() -ceq ($c1avHandLine + $c1avMissing)) -and ($c1avCFB.stdout.Trim() -ceq ($c1avHandLine + $c1avFile)) -and
         ($c1avC.stdout -ceq $c1avCB.stdout) -and ($c1avCF.stdout -ceq $c1avCFB.stdout) -and ($c1avC.stderr -ceq '') -and ($c1avCB.stderr -ceq '') -and ($c1avCF.stderr -ceq '') -and ($c1avCFB.stderr -ceq '')) `
    -Said ((Get-C1avSaid -Who 'tree, missing' -Reading $c1avC) + ' || ' + (Get-C1avSaid -Who 'base, missing' -Reading $c1avCB) + ' || ' + (Get-C1avSaid -Who 'tree, file' -Reading $c1avCF) + ' || ' + (Get-C1avSaid -Who 'base, file' -Reading $c1avCFB))

# (c2) BY HAND, THE EMPTY ROOT: it takes that same branch now. The line is read TRIMMED: with nothing to name
#      it ends on the blank after its colon, and whether that one blank reaches the pipe is not what is ruled.
$c1avC2 = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -MissionRootArg ''
$c1avC2Lines = Get-C1avLines -Text ([string]$c1avC2.stdout)
Add-C1avRow -Label '(c2) FALSIFIER BY HAND, the empty root -MissionRoot "": it takes the non-directory''s branch -- EXIT 2 and ONE line on stdout, opening "mission-goal-check: mission root not found:" -- where the binder used to end it' `
    -Ok (($c1avC2.exit -eq 2) -and ($c1avC2Lines.Count -eq 1) -and $c1avC2Lines[0].Trim().StartsWith($c1avHandLine.TrimEnd(), [System.StringComparison]::Ordinal) -and $c1avC2.commandLine.EndsWith(' -MissionRoot ""')) -Said (Get-C1avSaid -Who 'tree' -Reading $c1avC2)
$c1avC2B = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -MissionRootArg ''
Add-C1avRow -Label '(c2) BASE CONTROL: the same launch at the base -- the binder''s EXIT 1, stdout empty, stderr naming MissionRoot -- PowerShell''s own failure, not the evaluator''s exit 2' `
    -Ok (($c1avC2B.exit -eq 1) -and ($c1avC2B.stdout -ceq '') -and $c1avC2B.stderr.Contains('MissionRoot') -and $c1avC2B.commandLine.EndsWith(' -MissionRoot ""')) -Said (Get-C1avSaid -Who 'base' -Reading $c1avC2B)

# (d) THE WORKER GUARD STAYS ABOVE IT: a dispatched worker is never held to the orchestrator's hook, whatever its root.
$c1avEnv = @{ LAM_DISPATCH = 'D-C1AV' }
$c1avD = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -MissionRootArg $c1avMissing -Env $c1avEnv
$c1avDB = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -MissionRootArg $c1avMissing -Env $c1avEnv
Add-C1avRow -Label '(d) CONTROL THE WORKER GUARD STAYS ABOVE IT: LAM_DISPATCH set in the child''s environment, the root that does not exist, as the Stop hook -- APPROVE, exit 0, the reason naming the dispatched worker, stderr empty, ON BOTH TOOLS; this tree''s stdout the base''s byte for byte' `
    -Ok (($c1avD.decision -ceq 'approve') -and ($c1avD.exit -eq 0) -and $c1avD.reason.Contains("dispatched worker 'D-C1AV'") -and ($c1avD.stderr -ceq '') -and
         ($c1avDB.decision -ceq 'approve') -and ($c1avDB.exit -eq 0) -and $c1avDB.reason.Contains("dispatched worker 'D-C1AV'") -and ($c1avDB.stderr -ceq '') -and ($c1avD.stdout -ceq $c1avDB.stdout)) `
    -Said ((Get-C1avSaid -Who 'tree' -Reading $c1avD) + ' || base: exit ' + $c1avDB.exit + ', decision [' + $c1avDB.decision + '], stdout equal: ' + ($c1avD.stdout -ceq $c1avDB.stdout))
# (d2) ... AND ABOVE THE TEST FOR EMPTINESS TOO: the two sentences of the rule read together -- the parameter
#      admits '', and the guard stands above the root's test. A cure that tested emptiness ahead of the guard
#      would BLOCK a worker whose hook was handed an empty root: the trap the guard exists to keep it out of.
$c1avD2 = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -MissionRootArg '' -Env $c1avEnv
Add-C1avRow -Label '(d2) FALSIFIER ... THE EMPTY ROOT under LAM_DISPATCH, as the Stop hook: the parameter admits it and the worker guard answers FIRST -- APPROVE, exit 0, the reason naming the dispatched worker, stderr empty: never a block' `
    -Ok (($c1avD2.decision -ceq 'approve') -and ($c1avD2.exit -eq 0) -and $c1avD2.reason.Contains("dispatched worker 'D-C1AV'") -and ($c1avD2.stderr -ceq '')) -Said (Get-C1avSaid -Who 'tree' -Reading $c1avD2)
$c1avD2B = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -MissionRootArg '' -Env $c1avEnv
Add-C1avRow -Label '(d2) BASE CONTROL: the same launch at the base -- the binder''s EXIT 1, stdout empty -- no decision, and so no block: a worker was not held then either' `
    -Ok (($c1avD2B.exit -eq 1) -and ($c1avD2B.stdout -ceq '') -and ($c1avD2B.decision -ceq '') -and $c1avD2B.stderr.Contains('MissionRoot')) -Said (Get-C1avSaid -Who 'base' -Reading $c1avD2B)

# (e) STATED, NOT CLAIMED: NO -MissionRoot ARGUMENT AT ALL. A parameter that is not there cannot be tested by the file.
# (e1) with -NonInteractive the binder fails, as it did.
$c1avE1 = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -NoMissionRootArg -NonInteractive -TimeoutSeconds 60
$c1avE1B = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -NoMissionRootArg -NonInteractive -TimeoutSeconds 60
Add-C1avRow -Label '(e1) STATED, NOT CLAIMED: no -MissionRoot argument at all, the child launched -NonInteractive, as the Stop hook: the binder fails for the missing mandatory parameter -- EXIT 1, STDOUT EMPTY, no decision, stderr naming MissionRoot -- ON BOTH TOOLS: not cured' `
    -Ok (($c1avE1.exit -eq 1) -and ($c1avE1.stdout -ceq '') -and $c1avE1.stderr.Contains('MissionRoot') -and (-not $c1avE1.timedOut) -and (-not $c1avE1.commandLine.Contains('-MissionRoot')) -and
         ($c1avE1B.exit -eq 1) -and ($c1avE1B.stdout -ceq '') -and $c1avE1B.stderr.Contains('MissionRoot') -and (-not $c1avE1B.timedOut) -and (-not $c1avE1B.commandLine.Contains('-MissionRoot'))) `
    -Said ((Get-C1avSaid -Who 'tree' -Reading $c1avE1) + ' || ' + (Get-C1avSaid -Who 'base' -Reading $c1avE1B))
# (e2) as the house launches a hook -- no -NonInteractive, the Stop payload on stdin -- PowerShell PROMPTS for
#      the mandatory parameter and the prompt reads the payload: the payload is the mission root.
$c1avE2 = Invoke-WnEval -Tools tree -GoalId 'G-WNAV' -AsStopHook -NoMissionRootArg -TimeoutSeconds 60
$c1avE2P = Get-C1avAfterPayload -Reading $c1avE2
Add-C1avRow -Label '(e2) STATED, NOT CLAIMED: ... and launched as the house launches a hook (no -NonInteractive, the Stop payload on stdin): the prompt reads the PAYLOAD for the root, and that root is no directory -- exit 0, stdout the payload echoed and THEN "decision":"block", its reason saying the root "is not a directory, so no goal can be read and no verdict written."; the stdout is then NOT one JSON object, which is not cured' `
    -Ok (($c1avE2.exit -eq 0) -and (-not $c1avE2.timedOut) -and $c1avE2P.echoed -and $c1avE2P.rest.Contains('"decision":"block"') -and ($c1avE2P.decision -ceq 'block') -and $c1avE2P.reason.Contains($c1avNotDir) -and (-not $c1avE2.commandLine.Contains('-MissionRoot'))) `
    -Said ((Get-C1avSaid -Who 'tree' -Reading $c1avE2) + ' || after the payload: decision [' + $c1avE2P.decision + ']')
$c1avE2B = Invoke-WnEval -Tools base -GoalId 'G-WNAV' -AsStopHook -NoMissionRootArg -TimeoutSeconds 60
$c1avE2BP = Get-C1avAfterPayload -Reading $c1avE2B
Add-C1avRow -Label '(e2) BASE CONTROL: the same launch at the base -- exit 0, stdout the payload echoed and THEN "decision":"approve" -- "mission root not found: <the payload> -- not blocking." --, stderr empty: the stop is admitted on a root that was never given' `
    -Ok (($c1avE2B.exit -eq 0) -and (-not $c1avE2B.timedOut) -and $c1avE2BP.echoed -and $c1avE2BP.rest.Contains('"decision":"approve"') -and ($c1avE2BP.decision -ceq 'approve') -and
         ($c1avE2BP.reason -ceq ('goal-check: mission root not found: ' + $wnStopPayload + ' -- not blocking.')) -and ($c1avE2B.stderr -ceq '')) `
    -Said ((Get-C1avSaid -Who 'base' -Reading $c1avE2B) + ' || after the payload: decision [' + $c1avE2BP.decision + ']')
}
catch {
    $c1avOk = $false
    $c1avRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1avRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($c1avDir) { Remove-PwTreeAsWritten -Base $c1avDir }
Check -Id 'C-1av' -Title 'A MISSION ROOT THAT IS NO DIRECTORY BLOCKS (the operator''s ruling 1 and ruling D9 of 2026-10-11): as the Stop hook the base evaluator, handed a -MissionRoot that names no directory, printed approve -- "mission root not found ... not blocking" -- and exited 0 with no goal read and no verdict written, and handed the EMPTY string it never ran at all: the binder''s exit 1 and no decision; this tree BLOCKS each of the three -- a path that does not exist, a path that is a file, the empty string -- with {"decision":"block","reason":...} ALONE on stdout and exit 0, the form NOT_MET blocks in, its reason for a path opening "Goal ''<id>'' is NOT_MET: the mission root" and saying it is not a directory, and for the empty string saying that the mission root is the empty string -- either way "so no goal can be read and no verdict written." --, and the same reason stands one line on STDERR behind "goal-check: ", the streams read apart; nothing is created where nothing stood and the file is what it was; by hand a non-directory is the base''s one line and exit 2, byte for byte, and the empty root now takes that branch where the binder''s exit 1 was; the worker guard stays above all of it -- with LAM_DISPATCH set the hook approves, its stdout the base''s, and approves the empty root too; and what is NOT cured is stated -- with no -MissionRoot argument at all the binder still fails under -NonInteractive, exit 1 and no decision, on both tools, and as the house launches a hook the prompt reads the Stop payload for the root, which approved at the base and now BLOCKS, after the echoed payload, on a stdout that is not one JSON object' `
      -Ok $c1avOk -Detail ("      THE $(@($c1avRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1avRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- this member has no stub script, no goal file and no mission: every launch names a -MissionRoot that is no directory`n          | <its own directory under %TEMP%>\no-such-root   (nothing stands there)`n          | <its own directory under %TEMP%>\a-file-not-a-directory   (a FILE)`n          | `"`"   (the empty string, received as such)`n      or names none, and as the hook sends this Stop payload on stdin, reading the child's stdout and stderr apart:`n          | " + $wnStopPayload)

# =============================================================================================
# C-1aw -- THE ENGINE READ, UP: with the engine's named pipe on this host the read is
#          made, the verdict says what it read, and the instrument is launched exactly as it was
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: over a goal whose
# instrument_exit0 declares `engine_read: docker_pipe` the base STORES the key and reads nothing -- the
# instrument runs, MET, and the artifact carries no word of the engine: no `instrument_engine_reads` key.
# With the engine up, nothing on disk says the question was ever asked; with it down, the same evaluator
# launches the instrument all the same (C-1ar; the engine-down experiment).
# THE RULE: the read is made ONLY WHEN THE
# INSTRUMENT IS ABOUT TO BE LAUNCHED -- the names of this host's named pipes, no pipe opened, and under
# `docker_pipe_then_version`, where the pipe is there, one `docker version` bounded to 10 s -- and EVERY READ
# MADE IS ONE ITEM of the top-level key `instrument_engine_reads`. UP, the instrument is launched and its
# detail is what it is without the key.
# THE CONTROLS, each a row: the keyed goal's detail is, but for the clock, the detail of the same goal with
# the key taken out -- under docker_pipe, and under docker_pipe_then_version (a second row, nothing more
# driven for it); the base over the keyed goal runs the instrument and writes no such key; and THE PLANE
# ROW OF THE BATCH -- every evaluation by C-1ap..C-1aw at a root under %TEMP%, both live planes' sentinel
# paths as the banner of this batch read them.
# A MEMBER OF ITS OWN BECAUSE W3 SKIPS BY MEMBER. The engine-DOWN rows (C-1ar) need no engine: every one is
# driven through the goal's engine_read_fault seam. THESE NEED ONE. So this member FIRST lists the host's
# named pipes itself -- [System.IO.Directory]::GetFiles('\\.\pipe\'), names only -- and where
# dockerDesktopLinuxEngine is not among them rows (a) to (d) cannot be MEASURED here: the member is SKIPPED,
# loudly, the listing its reason (C-1k's form), and never reported as a pass.
# THE PLANE ROW NEEDS NO ENGINE and is measured either way: a measured failure outranks an unmeasurable
# clause (C-2c's rule), so where it reads MISMATCH the member FAILS and is not skipped.
# THIS MEMBER RUNS NO docker COMMAND. Row (b) is the one row of the whole batch at which the EVALUATOR, once
# cured, runs a real `docker version`; at the base, and at this tree before the cure, nothing does.
$c1awOk = $true
$c1awRows = New-Object System.Collections.Generic.List[string]
function Add-C1awRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1awOk = $false }
    $script:c1awRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1awRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1awReadsSaid {
    # The key instrument_engine_reads as a row prints it. -Items is what Get-WnList returned: $null where the
    # key is NOT WRITTEN, an empty array where it is written with nothing under it, else its items.
    param($Items)
    if ($null -eq $Items) { return 'NOT WRITTEN (no such key in the artifact)' }
    $c1awShown = @($Items | ForEach-Object { '[' + [string]$_ + ']' })
    if ($c1awShown.Count -eq 0) { return 'written, EMPTY' }
    return ([string]$c1awShown.Count + ' item(s): ' + ($c1awShown -join ' '))
}
# WHAT THE ROWS READ, each string as the contract fixes it: the engine's pipe by its leaf name, the opening
# of an instrument_exit0 detail whose instrument RAN (byte-stable: another tool classifies by it), and the
# two items of instrument_engine_reads -- the count of pipes, the seconds and docker's answer left open.
$c1awPipeLeaf = 'dockerDesktopLinuxEngine'
$c1awPipeName = '\\.\pipe\' + $c1awPipeLeaf
$c1awOpening = 'inst.ps1 exited 0 (require 0). Instrument output '
$c1awPipeItemRx = '^inst\.ps1: docker_pipe \\\\\.\\pipe\\dockerDesktopLinuxEngine present \(\d+ named pipes, [0-9.]+ s\)$'
$c1awVersionItemRx = '^inst\.ps1: docker version answered .+ \([0-9.]+ s\)$'
$c1awGoalHead = @('  - type: instrument_exit0', '    path: scratch/inst.ps1')
# THE MEMBER's OWN LISTING, BEFORE ANYTHING ELSE: names only -- no pipe is opened, no process is started.
# A leaf name is what follows the last backslash, compared OrdinalIgnoreCase, as the rule compares it. A
# listing that THROWS is a host this member cannot read the engine on: SKIPPED too, the throw its reason.
# THE ENGINE IS UNREACHABLE TO ROW (b) IN TWO MORE WAYS, AND EACH IS A SKIP BY NAME, NOT A FAILURE: row (b)'s
# evaluator runs `docker version`, which goes where DOCKER_HOST says -- a npipe DOCKER_HOST naming a pipe that
# is not among this host's named pipes answers nothing, wherever Docker Desktop's own pipe stands -- and which
# cannot start at all where no docker executable is on this process's PATH. Both are read the way the pipe
# is, by name and by listing, so this member still runs no docker command. The probe is a function so the
# CONTROL row below can hand it a dead pipe on every run and show the skip path without stopping Docker.
# AND AN ENDPOINT THE PROBE CANNOT LIST IS NOT READ AS UP: a DOCKER_HOST of another scheme (tcp, unix, ssh) or a
# DOCKER_CONTEXT other than default sends row (b)'s docker version somewhere no listing of named pipes can see, so
# whether the engine there answers is not known without running docker -- the member SKIPs and names it.
# AND THE ENDPOINT IS THE ONE THE CLI WILL USE, RESOLVED AS THE CLI RESOLVES IT: DOCKER_HOST; else DOCKER_CONTEXT; else
# the currentContext of config.json (in DOCKER_CONFIG, else %USERPROFILE%\.docker -- what `docker context use` writes);
# else the default context. A context other than default is read from its meta.json; its docker endpoint is measurable
# only as a named pipe this host lists, and the default context's is the CLI's own default, npipe docker_engine.
function Get-C1awEngineProbe {
    param([string]$DockerHost, [string]$DockerContext, [string]$DockerConfig)
    $pr = [pscustomobject]@{ skip = ''; pipeCount = 0; there = $false }
    try {
        $leaves = @([System.IO.Directory]::GetFiles('\\.\pipe\') | ForEach-Object { ([string]$_).Substring(([string]$_).LastIndexOf('\') + 1) })
        $pr.pipeCount = $leaves.Count
        $pr.there = (@($leaves | Where-Object { [string]::Equals([string]$_, $c1awPipeLeaf, [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0)
        if (-not $pr.there) {
            $dockerNamed = @($leaves | Where-Object { ([string]$_).IndexOf('docker', [System.StringComparison]::OrdinalIgnoreCase) -ge 0 } | Sort-Object -Unique)
            $pr.skip = 'the named pipe ' + $c1awPipeName + ' is not among the ' + $pr.pipeCount + ' named pipe(s) of this host (' +
                       $(if ($dockerNamed.Count -gt 0) { 'the ' + $dockerNamed.Count + ' whose name holds "docker": ' + ($dockerNamed -join ', ') } else { 'not one of them holds "docker" in its name' }) +
                       '), so the read with the engine UP cannot be measured here -- rows (a) to (d) were NOT driven, no fixture was built, no evaluator was run; with Docker Desktop''s Linux engine running, one more run of this instrument measures them'
        } else {
            $notMeasured = ' -- whether the engine there answers row (b)''s docker version is not known without running docker, so the read with the engine UP cannot be measured here: rows (a) to (d) were NOT driven, no fixture was built, no evaluator was run'
            # THE ENDPOINT, AND WHERE IT WAS READ.
            $endpoint = ''; $endpointFrom = ''
            if ($DockerHost) { $endpoint = $DockerHost; $endpointFrom = 'DOCKER_HOST' }
            else {
                $cfgDir = $(if ($DockerConfig) { $DockerConfig } elseif ($env:DOCKER_CONFIG) { $env:DOCKER_CONFIG } else { Join-Path $env:USERPROFILE '.docker' })
                $ctx = $DockerContext; $ctxFrom = 'DOCKER_CONTEXT'
                if (-not $ctx) {
                    $ctxFrom = 'currentContext of ' + (Join-Path $cfgDir 'config.json')
                    try { $ctx = [string]([System.IO.File]::ReadAllText((Join-Path $cfgDir 'config.json')) | ConvertFrom-Json).currentContext } catch { $ctx = '' }
                }
                if ((-not $ctx) -or ($ctx -ieq 'default')) { $endpoint = 'npipe:////./pipe/docker_engine'; $endpointFrom = 'the default context' }
                else {
                    $metaHit = $null
                    foreach ($mf in @(Get-ChildItem -LiteralPath (Join-Path $cfgDir 'contexts\meta') -Recurse -File -Filter 'meta.json' -ErrorAction SilentlyContinue)) {
                        try { $mj = [System.IO.File]::ReadAllText($mf.FullName) | ConvertFrom-Json } catch { continue }
                        if ([string]$mj.Name -ceq $ctx) { $metaHit = $mj; break }
                    }
                    if ($null -eq $metaHit) { $pr.skip = 'the docker context ' + $ctx + ' (' + $ctxFrom + ') is not among the contexts under ' + $cfgDir + $notMeasured }
                    else { $endpoint = [string]$metaHit.Endpoints.docker.Host; $endpointFrom = 'the docker context ' + $ctx + ' (' + $ctxFrom + ')' }
                }
            }
            if ((-not $pr.skip) -and ($endpoint -match '^(?i)npipe:/+\./pipe/(?<leaf>[^/\\]+)$')) {
                $hostLeaf = $Matches['leaf']
                if (@($leaves | Where-Object { [string]::Equals([string]$_, $hostLeaf, [System.StringComparison]::OrdinalIgnoreCase) }).Count -eq 0) {
                    $pr.skip = $endpointFrom + ' names ' + $endpoint + ', and the pipe it names, ' + $hostLeaf + ', is not among the ' + $pr.pipeCount + ' named pipe(s) of this host -- the engine is unreachable for row (b)''s docker version, so the read with the engine UP cannot be measured here: rows (a) to (d) were NOT driven, no fixture was built, no evaluator was run'
                }
            } elseif (-not $pr.skip) {
                $pr.skip = $endpointFrom + ' names ' + $(if ($endpoint) { $endpoint } else { 'no docker endpoint' }) + ', an endpoint no listing of this host''s named pipes can see' + $notMeasured
            }
            if ((-not $pr.skip) -and (@(Get-Command docker -CommandType Application -ErrorAction SilentlyContinue).Count -eq 0)) {
                $pr.skip = 'no docker executable is on this process''s PATH, so row (b)''s docker version could not be started -- the read with the engine UP cannot be measured here: rows (a) to (d) were NOT driven, no fixture was built, no evaluator was run'
            }
        }
    }
    catch {
        $pr.skip = 'the named pipes of this host could not be listed -- [System.IO.Directory]::GetFiles(''\\.\pipe\'') threw ' + $_.Exception.GetType().Name + ': ' + (([string]$_.Exception.Message) -replace '[\r\n]+', ' ') +
                   ' -- so whether ' + $c1awPipeName + ' is there was not read, and the read with the engine UP cannot be measured here: rows (a) to (d) were NOT driven, no fixture was built, no evaluator was run'
    }
    return $pr
}
$c1awProbe = Get-C1awEngineProbe -DockerHost ([Environment]::GetEnvironmentVariable('DOCKER_HOST')) -DockerContext ([Environment]::GetEnvironmentVariable('DOCKER_CONTEXT')) -DockerConfig ([Environment]::GetEnvironmentVariable('DOCKER_CONFIG'))
$c1awSkip = $c1awProbe.skip
$c1awPipeCount = $c1awProbe.pipeCount
$c1awEngineThere = $c1awProbe.there
# THE SKIP PATH, SHOWN ON EVERY RUN: the same probe handed a DOCKER_HOST naming a pipe that cannot exist. Where
# the engine's own pipe is listed it must answer SKIP naming that pipe; where it is not, the listing skip comes
# first, which is the skip path as well. No engine is needed and none is stopped.
$c1awDead = 'npipe:////./pipe/lam-wp3-c1aw-dead-' + [guid]::NewGuid().ToString('N').Substring(0, 12)
$c1awDeadProbe = Get-C1awEngineProbe -DockerHost $c1awDead
Add-C1awRow -Label 'CONTROL the probe, handed DOCKER_HOST at a named pipe that does not exist, answers SKIP: the engine is unreachable for this member, and it says so by name' `
    -Ok ([bool]$c1awDeadProbe.skip -and ((-not $c1awDeadProbe.there) -or $c1awDeadProbe.skip.Contains(($c1awDead -replace '^npipe:/+\./pipe/', '')))) `
    -Said ('DOCKER_HOST ' + $c1awDead + ' -> ' + $(if ($c1awDeadProbe.skip) { 'SKIP: ' + $c1awDeadProbe.skip } else { 'NO SKIP' }))
# ... and the same for an endpoint of another scheme: a tcp DOCKER_HOST on a port nothing listens on.
$c1awDeadTcp = 'tcp://127.0.0.1:1'
$c1awDeadTcpProbe = Get-C1awEngineProbe -DockerHost $c1awDeadTcp
Add-C1awRow -Label 'CONTROL the probe, handed DOCKER_HOST at a tcp endpoint, answers SKIP and names it: an endpoint no listing can see is never read as up' `
    -Ok ([bool]$c1awDeadTcpProbe.skip -and ((-not $c1awDeadTcpProbe.there) -or $c1awDeadTcpProbe.skip.Contains($c1awDeadTcp))) `
    -Said ('DOCKER_HOST ' + $c1awDeadTcp + ' -> ' + $(if ($c1awDeadTcpProbe.skip) { 'SKIP: ' + $c1awDeadTcpProbe.skip } else { 'NO SKIP' }))
# ... and for the route `docker context use` takes: a docker configuration, planted in this member's own folder, whose
# currentContext is a context at a tcp endpoint -- no environment variable set.
$c1awCfg = Join-Path $env:TEMP ('lam-wp3-c1aw-cfg-' + [guid]::NewGuid().ToString('N').Substring(0, 12))
$c1awCfgProbe = $null
try {
    $null = New-Item -ItemType Directory -Force -Path (Join-Path $c1awCfg 'contexts\meta\c1aw-dead')
    [System.IO.File]::WriteAllText((Join-Path $c1awCfg 'config.json'), '{"currentContext":"lam-wp3-c1aw-dead"}')
    [System.IO.File]::WriteAllText((Join-Path $c1awCfg 'contexts\meta\c1aw-dead\meta.json'), '{"Name":"lam-wp3-c1aw-dead","Metadata":{},"Endpoints":{"docker":{"Host":"tcp://127.0.0.1:1","SkipTLSVerify":false}}}')
    $c1awCfgProbe = Get-C1awEngineProbe -DockerConfig $c1awCfg
} finally { Remove-Item -LiteralPath $c1awCfg -Recurse -Force -ErrorAction SilentlyContinue }
Add-C1awRow -Label 'CONTROL the probe, handed a docker configuration whose currentContext is a context at a tcp endpoint, answers SKIP and names the context: the context the CLI would use is the one read' `
    -Ok (($null -ne $c1awCfgProbe) -and [bool]$c1awCfgProbe.skip -and ((-not $c1awCfgProbe.there) -or $c1awCfgProbe.skip.Contains('lam-wp3-c1aw-dead'))) `
    -Said ('DOCKER_CONFIG plant -> ' + $(if ($c1awCfgProbe -and $c1awCfgProbe.skip) { 'SKIP: ' + $c1awCfgProbe.skip } else { 'NO SKIP' }))
$c1awM = $null
try {
if (-not $c1awSkip) {
$c1awM = New-WnMission -Tag 'c1aw' -Goals ([ordered]@{ 'G-WNAW' = ($c1awGoalHead + @('    engine_read: docker_pipe')) })
if (-not $c1awM.ok) { throw ('FIXTURE REFUSED: ' + $c1awM.why) }
$c1awRoot = $c1awM.root
$null = Write-WnStub -Root $c1awRoot
Add-C1awRow -Label 'FIXTURE the engine''s named pipe \\.\pipe\dockerDesktopLinuxEngine IS among this host''s named pipes (listed by this member: names only, no pipe opened, no docker command run); a git repository under %TEMP%, the base tools pinned; .gitignore, mission.yaml (admitted_porcelain: "?? scratch/"), inputs/, other/ and the goal G-WNAW -- instrument_exit0, path scratch/inst.ps1, engine_read: docker_pipe, NO window -- committed; porcelain reads exactly "?? scratch/"' `
    -Ok ($wnBase.ok -and $c1awEngineThere -and ((Get-WnPorcelain -Root $c1awRoot) -ceq '?? scratch/') -and ($c1awM.head -cmatch '\A[0-9a-f]{40}\z')) `
    -Said ('named pipes listed: ' + $c1awPipeCount + ', ' + $c1awPipeName + ' among them: ' + $c1awEngineThere + '; HEAD ' + $c1awM.head + '; ' + $wnBase.said)

# (a) THE FALSIFIER, AT THIS TREE: the read is made, and said.
$c1awRuns = Get-WnRuns -Root $c1awRoot
$c1awA = Invoke-WnEval -Tools tree -Root $c1awRoot -GoalId 'G-WNAW'
$c1awARan = (Get-WnRuns -Root $c1awRoot) - $c1awRuns
$c1awAInst = Get-WnInst -Eval $c1awA
$c1awAReads = Get-WnList -Eval $c1awA -Key 'instrument_engine_reads'
Add-C1awRow -Label '(a) FALSIFIER engine_read: docker_pipe with the engine up: THE READ IS MADE AND SAID -- instrument_engine_reads holds exactly ONE item, "inst.ps1: docker_pipe \\.\pipe\dockerDesktopLinuxEngine present (<n> named pipes, <s> s)" -- and the instrument is launched as it was: the stub ran once, MET, the detail opens "inst.ps1 exited 0 (require 0). Instrument output "' `
    -Ok (($c1awA.verdict -ceq 'MET') -and ($c1awARan -eq 1) -and $c1awAInst.found -and $c1awAInst.ok -and $c1awAInst.detail.StartsWith($c1awOpening, [System.StringComparison]::Ordinal) -and
         ($null -ne $c1awAReads) -and ($c1awAReads.Count -eq 1) -and ([string]$c1awAReads[0] -cmatch $c1awPipeItemRx)) `
    -Said ('tree: exit ' + $c1awA.exit + ', ' + $c1awA.verdict + ', ' + $c1awA.seconds + ' s; the stub ran ' + $c1awARan + '; instrument_engine_reads: ' + (Get-C1awReadsSaid -Items $c1awAReads) + '; detail: ' + $c1awAInst.detail)
# (d) THE RED, KEPT -- driven HERE, while the goal of (a) stands on disk; its row is added at its letter.
$c1awRuns = Get-WnRuns -Root $c1awRoot
$c1awD = Invoke-WnEval -Tools base -Root $c1awRoot -GoalId 'G-WNAW'
$c1awDRan = (Get-WnRuns -Root $c1awRoot) - $c1awRuns
