if (-not (Invoke-WnCommit -Root $c1awRoot -Message 'G-WNAW: engine_read docker_pipe_then_version' -Add @('.mission/goals'))) { throw 'FIXTURE REFUSED: the goal G-WNAW rewritten with engine_read: docker_pipe_then_version was not committed' }
$c1awRuns = Get-WnRuns -Root $c1awRoot
$c1awB = Invoke-WnEval -Tools tree -Root $c1awRoot -GoalId 'G-WNAW'
$c1awBRan = (Get-WnRuns -Root $c1awRoot) - $c1awRuns
$c1awBInst = Get-WnInst -Eval $c1awB
$c1awBReads = Get-WnList -Eval $c1awB -Key 'instrument_engine_reads'
Add-C1awRow -Label '(b) FALSIFIER engine_read: docker_pipe_then_version: TWO READS, TWO ITEMS -- the pipe present, then "inst.ps1: docker version answered <text> (<s> s)" -- the stub ran once, MET (once cured, the one row of the batch at which the EVALUATOR runs a real docker version, bounded to 10 s; this member runs no docker command)' `
    -Ok (($c1awB.verdict -ceq 'MET') -and ($c1awBRan -eq 1) -and $c1awBInst.found -and $c1awBInst.ok -and ($null -ne $c1awBReads) -and ($c1awBReads.Count -eq 2) -and
         ([string]$c1awBReads[0] -cmatch $c1awPipeItemRx) -and ([string]$c1awBReads[1] -cmatch $c1awVersionItemRx)) `
    -Said ('tree: exit ' + $c1awB.exit + ', ' + $c1awB.verdict + ', ' + $c1awB.seconds + ' s; the stub ran ' + $c1awBRan + '; instrument_engine_reads: ' + (Get-C1awReadsSaid -Items $c1awBReads) + '; detail: ' + $c1awBInst.detail)

# (c) THE SAME GOAL WITHOUT THE KEY: what the entry says is what (a)'s says.
Write-PwGoal -Root $c1awRoot -GoalId 'G-WNAW' -DetectorLines $c1awGoalHead
if (-not (Invoke-WnCommit -Root $c1awRoot -Message 'G-WNAW: no engine_read' -Add @('.mission/goals'))) { throw 'FIXTURE REFUSED: the goal G-WNAW rewritten without engine_read was not committed' }
$c1awRuns = Get-WnRuns -Root $c1awRoot
$c1awC = Invoke-WnEval -Tools tree -Root $c1awRoot -GoalId 'G-WNAW'
$c1awCRan = (Get-WnRuns -Root $c1awRoot) - $c1awRuns
$c1awCInst = Get-WnInst -Eval $c1awC
$c1awCSame = ((Get-WnComparable -Text $c1awAInst.detail) -ceq (Get-WnComparable -Text $c1awCInst.detail))
Add-C1awRow -Label '(c) CONTROL the detail of (a) equals, but for the clock, the detail of the SAME GOAL WITH ITS engine_read LINE TAKEN OUT (the stub ran once, MET): an engine that is up changes nothing the entry says' `
    -Ok ($c1awAInst.found -and $c1awCInst.found -and ($c1awC.verdict -ceq 'MET') -and ($c1awCRan -eq 1) -and $c1awCSame) `
    -Said ('tree, no key: exit ' + $c1awC.exit + ', ' + $c1awC.verdict + '; the stub ran ' + $c1awCRan + '; details equal: ' + $c1awCSame + '; without the key: ' + $c1awCInst.detail + ' | with it, (a): ' + $c1awAInst.detail)
# (c), THE OTHER VALUE: the rule says of the READ, not of one value of the key, that with the engine up the
