    -Said ('base: exit ' + $c1awD.exit + ', ' + $c1awD.verdict + ', ' + $c1awD.seconds + ' s; the stub ran ' + $c1awDRan + '; instrument_engine_reads: ' + (Get-C1awReadsSaid -Items $c1awDReads) + '; detail: ' + $c1awDInst.detail)
}

# (e) THE PLANE ROW, over C-1ap..C-1aw: every evaluation since this batch's banner at a root under %TEMP%, and
