          -Ok $c1awOk -Detail ("      THE $(@($c1awRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1awRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument the goal names:`n" + (Get-WlIndented -Text $wnStubText))
}

