$wnBase = $null
try { $wnBase = New-WnBaseTools -Dir (Join-Path $wnBaseDir 'base-tools') }
catch { $wnBase = [pscustomobject]@{ ok = $false; path = ''; helper = ''; dir = ''; said = ('New-WnBaseTools threw: ' + ($_.Exception.Message -replace '[\r\n]+', ' ')) } }
$esGoalIds += @('G-WNQAX', 'G-WNQAX-P', 'G-WNQAX-W', 'G-WNQAX-N', 'G-WNQAY', 'G-WNQAZ-F1', 'G-WNQAZ-F2', 'G-WNQAZ-F3', 'G-WNQAZ-F4', 'G-WNQAZ-F5', 'G-WNQAZ-F6',
                'G-WNQAZ-C1', 'G-WNQAZ-C2', 'G-WNQAZ-C3', 'G-WNQBA', 'G-WNQBA-H', 'G-WNQBA-M', 'G-WNQBA-OK',
                'G-WNQBB', 'G-WNQBB-N', 'G-WNQBB-S', 'G-WNQBB-R1', 'G-WNQBB-R2', 'G-WNQBB-R3', 'G-WNQBB-X', 'G-WNQBC', 'G-WNQBC-S', 'G-WNQBC-C', 'G-WNQBC-V', 'G-WNQBD')
function Get-WqPlaneRow {
    # ONE MEMBER's PLANE ROW: every evaluation since -EvalsBefore at a root under %TEMP%, and both live planes'
    # sentinel paths as -PlaneBefore read them. Returns ok and said.
    param([int]$EvalsBefore, [string]$PlaneBefore)
    $wqPlaneAfter = Get-EsPlaneSnapshot
    $wqEvals = $esEvalRoots.Count - $EvalsBefore
    $wqOutside = @($esEvalRoots | Select-Object -Skip $EvalsBefore | Where-Object { -not $_.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase) })
    return [pscustomobject]@{ ok = (($wqEvals -gt 0) -and ($wqOutside.Count -eq 0) -and ($wqPlaneAfter -ceq $PlaneBefore)); evals = $wqEvals
                              said = ('evaluations ' + $wqEvals + '; outside %TEMP%: ' + $wqOutside.Count + '; snapshot equal: ' + ($wqPlaneAfter -ceq $PlaneBefore)) }
}

# =============================================================================================
# C-1ax -- gate_present AND THE amendment-material KIND: CONSUMPTION IS NOT READ; REVOCATION AND
#          DISQUALIFICATION ARE, FROM THE GATE's OWN FIELDS (the ruling of 05:58)
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base: a goal whose gate_present asks
# for kind amendment-material, over a gate of that kind whose consumed_at is stamped -- as WP-P's settle -Kind
# amendment-material will stamp it -- reads FAILED (unconsumed=False) and the goal NOT_MET; as the Stop hook it
# BLOCKS. Every live goal carries such a detector (eight of eight).
# THE RULE: for kind amendment-material -- the kind the detector asks for AND the kind the artifact declares --
# consumption decides nothing: a consumed gate of that kind is present where it is neither revoked nor
# disqualified, and revocation and disqualification are then read from the gate's OWN FIELDS (Get-LamGateState's
# revoked and disqualified), never from its state, in which CONSUMED outranks both (lam-gate-class.ps1:404): a
# gate both consumed and revoked reports state CONSUMED, and a state-read revocation would release it. The detail
# says so in a sentence of its own. An unconsumed gate reads byte for byte as it did, and so does every other kind.
# THE CONTROLS, each a row: an unconsumed gate (base and tree equal); a consumed push gate, a consumed
# witness-attested gate, and a goal that names the consumed amendment-material gate by path: with no kind -- each
# FAILED at both, the details equal; and the plane row. THE GATES are New-PwGate's: the line set and order of a
# real amendment-material mint, CR LF, consumed in the four-field form a settle appends, revoked in revoke's form;
# witness expiry is one more line.
$c1axOk = $true
$c1axRows = New-Object System.Collections.Generic.List[string]
function Add-C1axRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1axOk = $false }
    $script:c1axRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1axRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Get-C1axReading {
    # One evaluation of -GoalId at -Root by -Tools (tree|base), by hand or as the Stop hook: the verdict, the exit,
    # the hook's decision, and the gate_present entry (found, ok, detail).
    param([string]$Tools, [string]$Root, [string]$GoalId, [switch]$AsStopHook)
    $c1axRdEval = Invoke-WnEval -Tools $Tools -Root $Root -GoalId $GoalId -AsStopHook:$AsStopHook
    $c1axRdEntry = Get-PwDetector -Text ([string]$c1axRdEval.artifactText) -Type 'gate_present'
    return [pscustomobject]@{ exit = $c1axRdEval.exit; verdict = $c1axRdEval.verdict; decision = $c1axRdEval.decision; found = $c1axRdEntry.found; ok = $c1axRdEntry.ok; detail = [string]$c1axRdEntry.detail }
}
function Get-C1axSaid {
    param([string]$Tools, $Reading)
    return ($Tools + ': ' + $Reading.verdict + ', exit ' + $Reading.exit + $(if ($Reading.decision) { ', decision ' + $Reading.decision } else { '' }) + ', entry ' +
            $(if (-not $Reading.found) { 'NOT FOUND' } elseif ($Reading.ok) { 'ok' } else { 'FAILED' }) + ' -- ' + $Reading.detail)
}
$c1axTail = '. CONSUMED, AND NOT READ: for kind amendment-material consumption decides nothing; revocation and disqualification alone disqualify the gate (register rows 285 and 440)'
$c1axSha = 'a' * 64
$c1axPlaneBefore = Get-EsPlaneSnapshot
$c1axEvalsBefore = $esEvalRoots.Count
$c1axM = $null
$c1axShown = ''
try {
$c1axM = New-WnMission -Tag 'c1ax' -Goals ([ordered]@{
    'G-WNQAX'   = @('  - type: gate_present', '    kind: amendment-material', '    id: am-901')
    'G-WNQAX-P' = @('  - type: gate_present', '    kind: push', '    id: p-901')
    'G-WNQAX-W' = @('  - type: gate_present', '    kind: witness-attested', '    id: w-901')
    'G-WNQAX-N' = @('  - type: gate_present', '    path: .mission/gates/amendment-material-am-901.yaml') })
