$c1axRoot = $c1axM.root
$c1axAm = Join-Path $c1axRoot '.mission\gates\amendment-material-am-901.yaml'
function Write-C1axGate {
    # The amendment-material gate am-901 in one of four states: live, consumed, consumed-revoked or
    # consumed-disqualified. Returns the gate's text as written.
    param([string]$State)
    $c1axWgConsumed = if ($State -ceq 'live') { '' } else { '2026-10-16T05:58:00.000Z' }
    $c1axWgRevoked = if ($State -ceq 'consumed-revoked') { '2026-10-16T06:10:00.000Z' } else { '' }
    New-PwGate -Path $script:c1axAm -Id 'am-901' -BindsRel 'inputs/a.txt' -Sha $script:c1axSha -ConsumedAt $c1axWgConsumed -RevokedAt $c1axWgRevoked
    if ($State -ceq 'consumed-disqualified') { [System.IO.File]::AppendAllText($script:c1axAm, "witness_expired_at: 2026-10-16T06:20:00.000Z`r`n") }
    return [System.IO.File]::ReadAllText($script:c1axAm)
}
