# (c) THE SAME GATE CONSUMED AND REVOKED: FAILED at both; at this tree revoked=True, read from the field.
$null = Write-C1axGate -State 'consumed-revoked'
$c1axRB = Get-C1axReading -Tools base -Root $c1axRoot -GoalId 'G-WNQAX'
$c1axRT = Get-C1axReading -Tools tree -Root $c1axRoot -GoalId 'G-WNQAX'
Add-C1axRow -Label '(c) FALSIFIER the same gate CONSUMED AND REVOKED: FAILED and NOT_MET at both -- at the base for its consumption (revoked=False: the state reads CONSUMED), at this tree for its revocation, read from the gate''s own field (revoked=True, state=CONSUMED)' `
    -Ok ($c1axRB.found -and (-not $c1axRB.ok) -and ($c1axRB.verdict -ceq 'NOT_MET') -and $c1axRB.detail.Contains(' unconsumed=False revoked=False disqualified=False state=CONSUMED') -and
         $c1axRT.found -and (-not $c1axRT.ok) -and ($c1axRT.verdict -ceq 'NOT_MET') -and $c1axRT.detail.Contains(' unconsumed=False revoked=True disqualified=False state=CONSUMED') -and $c1axRT.detail.EndsWith($c1axTail)) `
    -Said ((Get-C1axSaid -Tools 'base' -Reading $c1axRB) + ' | ' + (Get-C1axSaid -Tools 'tree' -Reading $c1axRT))

# (d) THE SAME GATE CONSUMED AND DISQUALIFIED (witness_expired_at): FAILED at both; at this tree disqualified=True.
$null = Write-C1axGate -State 'consumed-disqualified'
$c1axDB = Get-C1axReading -Tools base -Root $c1axRoot -GoalId 'G-WNQAX'
$c1axDT = Get-C1axReading -Tools tree -Root $c1axRoot -GoalId 'G-WNQAX'
Add-C1axRow -Label '(d) FALSIFIER the same gate CONSUMED AND DISQUALIFIED (a witness_expired_at line): FAILED and NOT_MET at both -- at this tree for the disqualification, read from the field (disqualified=True, state=CONSUMED)' `
    -Ok ($c1axDB.found -and (-not $c1axDB.ok) -and ($c1axDB.verdict -ceq 'NOT_MET') -and
         $c1axDT.found -and (-not $c1axDT.ok) -and ($c1axDT.verdict -ceq 'NOT_MET') -and $c1axDT.detail.Contains(' unconsumed=False revoked=False disqualified=True state=CONSUMED') -and $c1axDT.detail.EndsWith($c1axTail)) `
    -Said ((Get-C1axSaid -Tools 'base' -Reading $c1axDB) + ' | ' + (Get-C1axSaid -Tools 'tree' -Reading $c1axDT))

# (e) CONTROLS: OTHER KINDS, AND NO KIND -- each consumed, each FAILED at both, the details equal.
$null = Write-C1axGate -State 'consumed'
New-PwGate -Path (Join-Path $c1axRoot '.mission\gates\push-p-901.yaml') -Id 'p-901' -BindsRel 'inputs/a.txt' -Sha $c1axSha -ConsumedAt '2026-10-16T05:58:00.000Z' -Kind 'push'
New-PwGate -Path (Join-Path $c1axRoot '.mission\gates\witness-attested-w-901.yaml') -Id 'w-901' -BindsRel 'inputs/a.txt' -Sha $c1axSha -ConsumedAt '2026-10-16T05:58:00.000Z' -Kind 'witness-attested'
foreach ($c1axCase in @(@{ goal = 'G-WNQAX-P'; what = 'a CONSUMED push gate' }, @{ goal = 'G-WNQAX-W'; what = 'a CONSUMED witness-attested gate' },
                        @{ goal = 'G-WNQAX-N'; what = 'the CONSUMED amendment-material gate named by path: with NO kind: line on the detector' })) {
    $c1axOB = Get-C1axReading -Tools base -Root $c1axRoot -GoalId $c1axCase.goal
    $c1axOT = Get-C1axReading -Tools tree -Root $c1axRoot -GoalId $c1axCase.goal
    Add-C1axRow -Label ('(e) CONTROL ' + $c1axCase.what + ' (' + $c1axCase.goal + '): FAILED and NOT_MET at the base and at this tree, the details EQUAL -- consumption still fails it, and no CONSUMED-AND-NOT-READ sentence') `
        -Ok ($c1axOB.found -and (-not $c1axOB.ok) -and ($c1axOB.verdict -ceq 'NOT_MET') -and $c1axOT.found -and (-not $c1axOT.ok) -and ($c1axOT.verdict -ceq 'NOT_MET') -and
