$c1bdEvalsBefore = $esEvalRoots.Count
$c1bdM = $null
try {
if (-not $c1bdSkip) {
$c1bdM = New-WnMission -Tag 'c1bd' -Goals ([ordered]@{ 'G-WNQBD' = @('  - type: instrument_exit0', '    path: scratch/inst.ps1', '    reuse_within_minutes: 30', '    engine_read: docker_pipe') })
if (-not $c1bdM.ok) { throw ('FIXTURE REFUSED: ' + $c1bdM.why) }
$c1bdRoot = $c1bdM.root
$null = Write-WnStub -Root $c1bdRoot
Clear-WnCaptures -Root $c1bdRoot
$c1bdFive = New-WnCapture -Tools tree -Root $c1bdRoot -Key 'FIVE' -AgeSeconds 300
$c1bdFiveCited = $c1bdFive.path + ' sha256 ' + $c1bdFive.sha256
Add-C1bdRow -Label 'FIXTURE the engine''s named pipe \\.\pipe\dockerDesktopLinuxEngine is NOT among this host''s named pipes (listed by this member: names only); a git repository under %TEMP%, the base tools pinned; the goal G-WNQBD -- reuse_within_minutes: 30, engine_read: docker_pipe -- committed; the stub written; ONE GREEN capture of it at HEAD, five minutes old (FIVE)' `
    -Ok ($wnBase.ok -and ((Get-WnPorcelain -Root $c1bdRoot) -ceq '?? scratch/') -and $c1bdFive.ok -and ($c1bdFive.exit -eq 0) -and ([string]$c1bdFive.header['head'] -ceq $c1bdM.head)) `
    -Said ('named pipes listed: ' + $c1bdPipeCount + '; HEAD ' + $c1bdM.head + '; ' + $c1bdFiveCited + '; ' + $wnBase.said)
$c1bdB = Get-C1bbReading -Tools base -Root $c1bdRoot -GoalId 'G-WNQBD'
$c1bdT = Get-C1bbReading -Tools tree -Root $c1bdRoot -GoalId 'G-WNQBD'
$c1bdFiveNow = Read-WnCapture -Path $c1bdFive.path
Add-C1bdRow -Label '(g3) BASE with the engine REALLY down: the base asks the reuse question first and REUSES FIVE -- MET, the stub not run -- making NO read: instrument_engine_reads written EMPTY (the RED, kept)' `
    -Ok (($c1bdB.ran -eq 0) -and ($c1bdB.verdict -ceq 'MET') -and $c1bdB.ok -and (Test-C1apOnly -List $c1bdB.reused -Item $c1bdFiveCited) -and ($null -ne $c1bdB.reads) -and (@($c1bdB.reads).Count -eq 0)) `
    -Said (Get-C1bcSaid -Reading $c1bdB)
Add-C1bdRow -Label '(g3) FALSIFIER the same at this tree: the read is made FIRST and finds the pipe ABSENT -- one item, "inst.ps1: docker_pipe \\.\pipe\dockerDesktopLinuxEngine ABSENT (<n> named pipes, <s> s)" -- and the detector is NOT RUN: NOT_MET, the stub not run, NOTHING reused, FIVE as it was, the detail ending "(engine_read docker_pipe; register row 264). reuse_within_minutes 30: no reuse question was asked -- the engine read answered down before any reuse decision (register row 438)."' `
    -Ok (($c1bdT.ran -eq 0) -and ($c1bdT.verdict -ceq 'NOT_MET') -and (-not $c1bdT.ok) -and $c1bdT.detail.StartsWith('inst.ps1 NOT RUN: engine down -- ', [System.StringComparison]::Ordinal) -and
         $c1bdT.detail.EndsWith('(engine_read docker_pipe; register row 264). reuse_within_minutes 30: no reuse question was asked -- the engine read answered down before any reuse decision (register row 438).', [System.StringComparison]::Ordinal) -and
         ($null -ne $c1bdT.reused) -and (@($c1bdT.reused).Count -eq 0) -and ($null -ne $c1bdT.reads) -and (@($c1bdT.reads).Count -eq 1) -and
         ([string]@($c1bdT.reads)[0] -cmatch '^inst\.ps1: docker_pipe \\\\\.\\pipe\\dockerDesktopLinuxEngine ABSENT \(\d+ named pipes, [0-9.]+ s\)$') -and $c1bdFiveNow.ok -and ($c1bdFiveNow.sha256 -ceq $c1bdFive.sha256)) `
    -Said (Get-C1bcSaid -Reading $c1bdT)
}

# THE PLANE ROW, MEASURED EITHER WAY: where this member was skipped it made no evaluation, and the count is printed
# and not required to be above zero.
$c1bdPlaneAfter = Get-EsPlaneSnapshot
$c1bdEvals = $esEvalRoots.Count - $c1bdEvalsBefore
$c1bdOutside = @($esEvalRoots | Select-Object -Skip $c1bdEvalsBefore | Where-Object { -not $_.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase) })
Add-C1bdRow -Label ('PLANE ' + $c1bdEvals + ' evaluations by C-1bd, every one at a root under %TEMP%; both live planes'' sentinel paths unchanged since this member began') `
    -Ok ((($c1bdEvals -gt 0) -or [bool]$c1bdSkip) -and ($c1bdOutside.Count -eq 0) -and ($c1bdPlaneAfter -ceq $c1bdPlaneBefore)) -Said ('outside %TEMP%: ' + $c1bdOutside.Count + '; snapshot equal: ' + ($c1bdPlaneAfter -ceq $c1bdPlaneBefore))
}
catch {
    $c1bdOk = $false
    $c1bdRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1bdRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if ($null -ne $c1bdM) { Remove-PwTreeAsWritten -Base $c1bdM.base }
$c1bdCite = 'THE ENGINE FALSIFIER''s OWN RED, THE REAL DOWN (the operator''s ruling (b) of 21:49 local; ruled 2026-10-16 07:2x local, lean accepted, Q1 among them)'
if ($c1bdSkip -and $c1bdOk) {
    # NOT MEASURED, AND SAID SO: [SKIP] on the face, the reason first in the detail, the summary line refusing the word
    # "all". The plane row, which was measured and reads ok, is shown under it.
    Check -Id 'C-1bd' -Title ($c1bdCite + ': the engine is not down on this host -- or its named pipes could not be read --, so what a goal declaring engine_read and a window reads with the engine REALLY down was NOT MEASURED here; the plane row was') `
          -Ok $true -Skipped -Detail ('    SKIPPED: ' + $c1bdSkip + "`n      THE PLANE ROW NEEDS NO ENGINE AND WAS MEASURED ALL THE SAME:`n" + ($c1bdRows -join "`n"))
} elseif ($c1bdSkip) {
    # A MEASURED FAILURE OUTRANKS AN UNMEASURABLE CLAUSE.
    Check -Id 'C-1bd' -Title ($c1bdCite + ': the real DOWN could not be measured here -- and the plane row, which needs no engine, DID NOT HOLD') `
          -Ok $false -Detail ('      THE REAL DOWN NOT MEASURED: ' + $c1bdSkip + "`n      THE ROW THAT WAS MEASURED:`n" + ($c1bdRows -join "`n"))
} else {
    Check -Id 'C-1bd' -Title ($c1bdCite + ': with the engine''s named pipe \\.\pipe\dockerDesktopLinuxEngine NOT among this host''s named pipes -- the member lists them itself first, names only, and is SKIPPED where it is there -- over a GREEN capture at HEAD five minutes old and a goal declaring reuse_within_minutes: 30 and engine_read: docker_pipe, the base evaluator REUSES the capture with no read made, instrument_engine_reads written empty; at this tree the read is made first, finds the pipe ABSENT -- its one item says so -- and the detector is NOT RUN, nothing reused, the capture as it was, the detail ending in C-1bc''s words; and every evaluation by C-1bd ran at a root under %TEMP%, both live planes'' sentinel paths unchanged') `
          -Ok $c1bdOk -Detail ("      THE $(@($c1bdRows | Where-Object { $_ -match ' (ok|MISMATCH)$' }).Count) ROWS:`n" + ($c1bdRows -join "`n") + "`n      THE STUB, SHOWN BEFORE THE FIRST RED -- scratch\inst.ps1, the instrument the goal names:`n" + (Get-WlIndented -Text $wnStubText))
}

# =============================================================================================
# C-1be -- -KeepPytestOutput <path> ON THE PRODUCT INSTRUMENT: PYTEST's OWN OUTPUT KEPT BESIDE A HAND RUN, AND THE
#          BLOCKING TEST NAMED (Q2, Q11 and Q13 as ruled)
# =============================================================================================
# THE FALSIFIER, RED at the tree before the cure and KEPT at the base (the synthetic suite instrument at
# that version): a suite whose one test sleeps past the wall is killed at the wall and the instrument says so (C4,
# pytest_exit=124) -- but pytest's own output, the one place the blocking test can be named, goes with the run:
# the instrument prints its TALLY and FAILED lines and nothing else of it. The base has no parameter to keep it,
# and refuses the argument.
# THE RULE (the product instrument ALONE; the shared helper is held to a pinned blob, WP-2 R-57 row (8)): `-KeepPytestOutput <path>`.
# EMPTY -- the default, and the no-argument form the helper, the runner and the evaluator use -- takes NO branch:
# stdout, exit code and the pytest line are what they were. GIVEN: the path is GUARDED before anything runs -- one
# that ends .stdout.txt or .tally.txt, or stands under instrument-runs, is refused, `FAIL M2 -- -KeepPytestOutput
# names <path>, which the reuse candidates and the census read; nothing was run`, exit non-zero --; the pytest
# line gains ` -o faulthandler_timeout=60` (Q2: a test past 60 s has every thread's stack dumped to stderr, its
# file and function among the frames); after the run the whole ordered buffer is written to the path, UTF-8
# without a mark; and ONE line after the WALL notes says so, `KEPT pytest's own output (diagnostic, not a
# measurement): <path> <bytes> B sha256 <hex>`, beginning with none of the words a capture's readers classify by.
# No TALLY field is added and no verdict moves.
# THE FIXTURE is C-1k's: a scratch root under %TEMP% laid out as the instrument expects -- a BYTE COPY of this
# tree's instrument (the base's bytes written over it for the base rows, read from the installed synthetic suite
# version and held to their pin), a manifest with stored_floor 1, the mirror's exact LF bytes, and src\ holding a one-test pytest project --
# run DIRECTLY, not through the helper and not under the evaluator (the flag reaches a hand run only: the helper
# launches the instrument with no argument), with UV_PROJECT_ENVIRONMENT naming this tree's own src\.venv,
# UV_NO_SYNC=1 and UV_OFFLINE=1 set for the child alone. The faulthandler's T is 60 s and a 20 s wall would kill
# the suite before it: so (c1)'s wall is 80 s and its test sleeps past both; (c2) runs a test that passes at once
# under -WallSeconds 20, C-1k's.
# THE ROWS: (c1) the falsifier and its base; (c2) the control, flag off, base and tree; (c3) the KEPT line and the
# TALLY's fields; (c4) the guard over three paths, nothing run; and the plane row. (c1)-(c3) need this tree's
# product venv and SKIP by C-1k's words where it is absent; (c4) and the plane row need none and
# are measured either way -- a measured failure outranks an unmeasurable clause.
$c1beOk = $true
$c1beRows = New-Object System.Collections.Generic.List[string]
$c1beLive = New-Object System.Collections.Generic.List[object]
function Add-C1beRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:c1beOk = $false }
    $script:c1beRows.Add(('      {0,-100} {1}' -f $Label, $(if ($Ok) { 'ok' } else { 'MISMATCH' })))
    if ($Said) { $script:c1beRows.Add('          ' + (($Said -replace '\s+', ' ').Trim())) }
}
function Invoke-C1beRun {
    # ONE DIRECT RUN of the fixture's instrument: `powershell -NoProfile -ExecutionPolicy Bypass -File <the copy>
    # <-Arguments>` in the scratch root, the three uv variables set for the child alone, stdout and stderr read apart,
    # waited for -TimeoutSeconds and no longer (its tree killed past it). Returns exit, out, err, seconds, timedOut.
    param([string]$Arguments, [int]$TimeoutSeconds = 240)
    $c1beRnPsi = New-Object System.Diagnostics.ProcessStartInfo
    $c1beRnPsi.FileName = 'powershell.exe'
    $c1beRnPsi.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + $script:c1beInst + '" ' + $Arguments
    $c1beRnPsi.WorkingDirectory = $script:c1beRoot
    $c1beRnPsi.UseShellExecute = $false
    $c1beRnPsi.CreateNoWindow = $true
    $c1beRnPsi.RedirectStandardOutput = $true
    $c1beRnPsi.RedirectStandardError = $true
    $c1beRnPsi.EnvironmentVariables['UV_PROJECT_ENVIRONMENT'] = $script:c1beVenv
    $c1beRnPsi.EnvironmentVariables['UV_NO_SYNC'] = '1'
    $c1beRnPsi.EnvironmentVariables['UV_OFFLINE'] = '1'
    $c1beRnClock = [System.Diagnostics.Stopwatch]::StartNew()
    $c1beRnProc = [System.Diagnostics.Process]::Start($c1beRnPsi)
    $script:c1beLive.Add($c1beRnProc)
    $c1beRnOut = $c1beRnProc.StandardOutput.ReadToEndAsync()
    $c1beRnErr = $c1beRnProc.StandardError.ReadToEndAsync()
    $c1beRnTimedOut = -not $c1beRnProc.WaitForExit($TimeoutSeconds * 1000)
    if ($c1beRnTimedOut) { Stop-C1KTree -Proc $c1beRnProc } else { $c1beRnProc.WaitForExit() }
    $c1beRnO = ''; $c1beRnE = ''
    try { if ($c1beRnOut.Wait(15000)) { $c1beRnO = [string]$c1beRnOut.Result } } catch { }
    try { if ($c1beRnErr.Wait(5000)) { $c1beRnE = [string]$c1beRnErr.Result } } catch { }
    $c1beRnExit = $null
    try { if ($c1beRnProc.HasExited) { $c1beRnExit = $c1beRnProc.ExitCode } } catch { }
    return [pscustomobject]@{ exit = $c1beRnExit; out = $c1beRnO; err = $c1beRnE; seconds = [Math]::Round($c1beRnClock.Elapsed.TotalSeconds, 1); timedOut = $c1beRnTimedOut }
}
function Get-C1beMasked {
    # A run's output "but for the clock and the elapsed seconds": the TALLY's elapsed_seconds and pytest's own
    # "in <s>s". Nothing else is masked.
    param([string]$Text)
    return (([string]$Text -replace 'elapsed_seconds=\d+', 'elapsed_seconds=MASKED') -replace '\bin \d+(\.\d+)?s\b', 'in MASKEDs')
}
function Get-C1beKept {
    # The kept file as it stands: exists, bytes, sha256 (lower hex) and its text.
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return [pscustomobject]@{ exists = $false; bytes = 0; sha256 = ''; text = '' } }
    $c1beKpB = [System.IO.File]::ReadAllBytes($Path)
    return [pscustomobject]@{ exists = $true; bytes = $c1beKpB.Length; sha256 = (Get-PwSha256 -Bytes $c1beKpB); text = $pwUtf8.GetString($c1beKpB) }
}
function Get-C1beSaid {
    param([string]$Tools, $Run)
    $c1beSdLines = @(([string]$Run.out -replace "`r", '') -split "`n" | Where-Object { $_ -match '^(TALLY|WALL|KEPT|PASS|FAIL|EXIT)\b' })
    return ($Tools + ': exit ' + $Run.exit + ', ' + $Run.seconds + ' s' + $(if ($Run.timedOut) { ', TIMED OUT' } else { '' }) + '; lines [' + ($c1beSdLines -join ' | ') + ']' +
            $(if ([string]$Run.err) { '; stderr: ' + ((([string]$Run.err) -replace '\s+', ' ').Trim()) } else { '' }))
}
# The instrument and the venv as C-1k reads them (Get-LamArcInstrument, Get-LamPytestVenv).
$c1beArc        = Get-LamArcInstrument
$c1beInstrument = $c1beArc.path
$c1beNoSubject  = (-not $c1beInstrument)
$c1beVenvPick   = Get-LamPytestVenv
$c1beVenv       = $c1beVenvPick.path
$c1beVenvPython = if ($c1beVenv) { Join-Path $c1beVenv 'Scripts\python.exe' } else { '' }
$c1beBaseSha    = '700e19e5-s04'
$c1beBaseSha256 = $lamSuitePins[$c1beBaseSha]
$c1beRoot       = [System.IO.Path]::GetFullPath((Join-Path $env:TEMP ('c1be-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))))
$c1beInst       = Join-Path $c1beRoot 'tests\lam\instrument-sample-suite.ps1'
$c1beTest       = Join-Path $c1beRoot 'src\test_c1be.py'
$c1beMarker     = Join-Path $c1beRoot 'src\sleep.pid'
$c1beReserved   = @('FAILED', 'TALLY', 'ERROR', 'WALL', 'NO-TALLY', 'CHECKS', 'BOUND', 'EXIT')
$c1beSkip       = ''
if ($c1beNoSubject) {
    $c1beSkip = 'the instrument under test: ' + $c1beArc.from + ', so it is absent and nothing was built'
} elseif (-not $c1beVenv) {
    $c1beSkip = "no venv to run the fixture's pytest under: none of $($c1beVenvPick.tried) has a Scripts\python.exe"
} else {
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $null = (& $c1beVenvPython -c 'import pytest' 2>&1); $c1bePyExit = $LASTEXITCODE } finally { $ErrorActionPreference = $prevEap }
    if ($c1bePyExit -ne 0) { $c1beSkip = "the venv at $c1beVenv cannot import pytest (exit $c1bePyExit)" }
}
$c1bePlaneBefore = Get-EsPlaneSnapshot
$c1beEvalsBefore = $esEvalRoots.Count
try {
  if ($c1beNoSubject) { $c1beRows.Add('      NOTHING WAS BUILT: ' + $c1beArc.from) } else {
    # THE FIXTURE, built whether or not the venv stands: (c4) and the plane row need none.
    $null = New-Item -ItemType Directory -Path (Join-Path $c1beRoot 'tests\lam') -Force
    Copy-Item -LiteralPath $c1beInstrument -Destination $c1beInst -Force
    $c1beTreeBytes = [System.IO.File]::ReadAllBytes($c1beInst)
    $c1beShaTree = (Get-FileHash -Algorithm SHA256 -LiteralPath $c1beInstrument).Hash.ToLowerInvariant()
    $c1beShaCopy = Get-PwSha256 -Bytes $c1beTreeBytes
    Write-Utf8 -Path (Join-Path $c1beRoot '.mission\green-gate\product.json') -Text "{`n  `"stored_floor`": 1,`n  `"expected_failure_test_ids`": []`n}`n"
    Write-Utf8 -Path (Join-Path $c1beRoot 'tools\mission-cli\config\expected-failures.yaml') `
               -Text ('# DERIVED MIRROR of .mission/green-gate/product.json `expected_failure_test_ids` (the GOVERNING home).' + "`n" +
                      '# Re-derived at every close; tests/lam/instrument-sample-suite.ps1 FAILS on any byte difference.' + "`n" +
                      'expected_failures:' + "`n")
    Write-Utf8 -Path (Join-Path $c1beRoot 'src\pyproject.toml') -Text "[project]`nname = `"c1be-fixture`"`nversion = `"0.0.0`"`nrequires-python = `">=3.13`"`n`n[tool.pytest.ini_options]`n"
    $c1beSleepTest = "import os`nimport time`n`n`ndef test_sleeps_past_the_wall_and_t():`n    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'sleep.pid'), 'w') as f:`n        f.write(str(os.getpid()))`n    time.sleep(3600)`n"
    $c1bePassTest = "def test_passes_at_once():`n    assert True`n"
    Write-Utf8 -Path $c1beTest -Text $c1bePassTest
    # THE BASE's BYTES, read through Get-LamSuiteBytes and held to their pin (C-1k's CONTROL 2 form).
    $c1beBaseRead = Get-LamSuiteBytes -Version $c1beBaseSha
    $c1beBaseBytes = $c1beBaseRead.bytes
    $c1beBaseGot = $c1beBaseRead.sha
    $c1beBaseOk = ($c1beBaseRead.ok -and ($c1beBaseGot -ceq $c1beBaseSha256))
    Add-C1beRow -Label 'FIXTURE a scratch root under %TEMP% laid out as the instrument expects (C-1k''s): the instrument a BYTE COPY of the one read; the base''s bytes read at their pin; stored_floor 1, no expected failures, the mirror''s exact LF bytes; src\ a one-test pytest project' `
        -Ok (($c1beShaTree -ceq $c1beShaCopy) -and $c1beBaseOk -and $c1beRoot.StartsWith($esTempRoot, [System.StringComparison]::OrdinalIgnoreCase)) `
        -Said ('root ' + $c1beRoot + '; instrument read from ' + $c1beArc.from + ', sha256 ' + $c1beShaTree + ', copy ' + $c1beShaCopy + '; base read from ' + $c1beBaseRead.from + ', sha256 ' + $c1beBaseGot + '; venv: ' + $(if ($c1beSkip) { 'NOT USABLE -- ' + $c1beSkip } else { $c1beVenv }))

    if (-not $c1beSkip) {
        # (c1) THE FALSIFIER: one test sleeps past T and past the wall; the flag given, the kept file under the
        #      ignored runtime plane, as the REC-B form puts it.
        Write-Utf8 -Path $c1beTest -Text $c1beSleepTest
        $c1beKeep1 = Join-Path $c1beRoot '.mission-runtime\keep\c1.pytest-output.txt'
        if (Test-Path -LiteralPath $c1beMarker) { Remove-Item -LiteralPath $c1beMarker -Force }
        [System.IO.File]::WriteAllBytes($c1beInst, $c1beBaseBytes)
        $c1beB1 = Invoke-C1beRun -Arguments ('-Member M2 -WallSeconds 80 -KeepPytestOutput "' + (Join-Path $c1beRoot '.mission-runtime\keep\c1-base.pytest-output.txt') + '"') -TimeoutSeconds 120
        $c1beB1Kept = Get-C1beKept -Path (Join-Path $c1beRoot '.mission-runtime\keep\c1-base.pytest-output.txt')
        $c1beB1Ran = (Test-Path -LiteralPath $c1beMarker)
        Add-C1beRow -Label '(c1) BASE the base instrument handed -KeepPytestOutput: NO SUCH PARAMETER -- it refuses the argument and runs nothing: exit non-zero, the binder naming KeepPytestOutput, no banner, no TALLY, the test never started, no kept file (the RED, kept)' `
            -Ok (($null -ne $c1beB1.exit) -and ($c1beB1.exit -ne 0) -and (([string]$c1beB1.out + [string]$c1beB1.err).Contains('KeepPytestOutput')) -and (-not ([string]$c1beB1.out).Contains('SAMPLE-SUITE INSTRUMENT')) -and
                 (-not ([string]$c1beB1.out).Contains('TALLY ')) -and (-not $c1beB1Ran) -and (-not $c1beB1Kept.exists)) `
            -Said (Get-C1beSaid -Tools 'base' -Run $c1beB1)
        [System.IO.File]::WriteAllBytes($c1beInst, $c1beTreeBytes)
        $c1beT1 = Invoke-C1beRun -Arguments ('-Member M2 -WallSeconds 80 -KeepPytestOutput "' + $c1beKeep1 + '"') -TimeoutSeconds 240
        $c1beT1Kept = Get-C1beKept -Path $c1beKeep1
        $c1beT1Alive = Test-C1KMarkerAlive -Marker $c1beMarker
        $c1beT1Out = ([string]$c1beT1.out -replace "`r", '')
        Add-C1beRow -Label '(c1) FALSIFIER the same at this tree: the suite is killed at the 80 s wall as before -- TALLY pytest_exit=124, the C4 wall-guard FAIL, exit non-zero, the sleeping interpreter dead --; and pytest''s own output is KEPT at the path: the file stands, and holds the faulthandler''s dump past T ("Timeout (0:01:00)!") whose frames name the sleeping test, test_c1be.py and test_sleeps_past_the_wall_and_t' `
            -Ok (($null -ne $c1beT1.exit) -and ($c1beT1.exit -ne 0) -and (-not $c1beT1.timedOut) -and [regex]::IsMatch($c1beT1Out, '(?m)^TALLY .*\bpytest_exit=124\b') -and
                 $c1beT1Out.Contains('FAIL M2 -- the product green gate is RED: C4 wall-guard [pytest killed after') -and (Test-Path -LiteralPath $c1beMarker) -and (-not $c1beT1Alive) -and
                 $c1beT1Kept.exists -and ($c1beT1Kept.bytes -gt 0) -and $c1beT1Kept.text.Contains('Timeout (0:01:00)!') -and $c1beT1Kept.text.Contains('test_c1be.py') -and $c1beT1Kept.text.Contains('test_sleeps_past_the_wall_and_t')) `
            -Said ((Get-C1beSaid -Tools 'tree' -Run $c1beT1) + ' | kept: exists ' + $c1beT1Kept.exists + ', ' + $c1beT1Kept.bytes + ' B, sha256 ' + $c1beT1Kept.sha256 + '; the sleeping interpreter alive after: ' + $c1beT1Alive +
                   ' | the kept file, its lines naming the test or the timeout: [' + (@(($c1beT1Kept.text -replace "`r", '') -split "`n" | Where-Object { $_ -match 'Timeout \(|test_sleeps_past_the_wall_and_t|test_c1be\.py' } | Select-Object -First 4) -join ' | ') + ']')

        # (c3) THE KEPT LINE AND THE TALLY's FIELDS, read off (c1)'s stdout at this tree.
        $c1beT1Lines = @($c1beT1Out -split "`n")
        $c1beKeptAt = @(for ($c1beI = 0; $c1beI -lt $c1beT1Lines.Count; $c1beI++) { if ($c1beT1Lines[$c1beI].StartsWith('KEPT ', [System.StringComparison]::Ordinal)) { $c1beI } })
        $c1beWallAt = @(for ($c1beI = 0; $c1beI -lt $c1beT1Lines.Count; $c1beI++) { if ($c1beT1Lines[$c1beI].StartsWith('WALL ', [System.StringComparison]::Ordinal)) { $c1beI } })
        $c1beKeptWant = "KEPT pytest's own output (diagnostic, not a measurement): " + $c1beKeep1 + ' ' + $c1beT1Kept.bytes + ' B sha256 ' + $c1beT1Kept.sha256
        $c1beKeptLine = if ($c1beKeptAt.Count -eq 1) { $c1beT1Lines[$c1beKeptAt[0]] } else { '' }
        $c1beKeptFirst = if ($c1beKeptLine) { ($c1beKeptLine -split ' ')[0] } else { '' }
        $c1beTallyKeys = { param($Out) $c1beTk = [regex]::Match(([string]$Out -replace "`r", ''), '(?m)^TALLY (.*)$'); if (-not $c1beTk.Success) { return '' }; return ((@([regex]::Matches($c1beTk.Groups[1].Value, '(\w+)=') | ForEach-Object { $_.Groups[1].Value })) -join ' ') }

        # (c2) THE CONTROL, flag off, a test that passes at once: the base's stdout and this tree's, byte for byte but
        #      for the clock and the elapsed seconds.
        Write-Utf8 -Path $c1beTest -Text $c1bePassTest
        [System.IO.File]::WriteAllBytes($c1beInst, $c1beBaseBytes)
        $c1beB2 = Invoke-C1beRun -Arguments '-Member M2 -WallSeconds 20' -TimeoutSeconds 120
        [System.IO.File]::WriteAllBytes($c1beInst, $c1beTreeBytes)
        $c1beT2 = Invoke-C1beRun -Arguments '-Member M2 -WallSeconds 20' -TimeoutSeconds 120
        $c1beC2Same = ((Get-C1beMasked -Text $c1beB2.out) -ceq (Get-C1beMasked -Text $c1beT2.out)) -and ((Get-C1beMasked -Text $c1beB2.err) -ceq (Get-C1beMasked -Text $c1beT2.err))
        Add-C1beRow -Label '(c2) CONTROL NO FLAG, a test that passes at once, -WallSeconds 20: the base''s run and this tree''s -- exit 0 at both, TALLY pytest_exit=0 passed=1, PASS M2 -- stdout and stderr EQUAL byte for byte but for the clock and the elapsed seconds; no KEPT line and no faulthandler at this tree' `
            -Ok (($c1beB2.exit -eq 0) -and ($c1beT2.exit -eq 0) -and $c1beC2Same -and [regex]::IsMatch(([string]$c1beT2.out -replace "`r", ''), '(?m)^TALLY passed=1 .*\bpytest_exit=0\b') -and ([string]$c1beT2.out).Contains('PASS M2 --') -and
                 (-not ([string]$c1beT2.out).Contains('KEPT ')) -and (-not ([string]$c1beT2.out + [string]$c1beT2.err).Contains('faulthandler'))) `
            -Said ((Get-C1beSaid -Tools 'base' -Run $c1beB2) + ' | ' + (Get-C1beSaid -Tools 'tree' -Run $c1beT2) + ' | equal but for the clock: ' + $c1beC2Same)
        Add-C1beRow -Label '(c3) FALSIFIER (c1)''s stdout at this tree carries EXACTLY ONE KEPT line, AFTER the WALL notes, reading "KEPT pytest''s own output (diagnostic, not a measurement): <path> <bytes> B sha256 <hex>" with the kept file''s own bytes and sha256 -- its first word none of FAILED, TALLY, ERROR, WALL, NO-TALLY, CHECKS, BOUND, EXIT -- and its TALLY line carries the fields the flag-off TALLY carries, no more and no fewer' `
            -Ok (($c1beKeptAt.Count -eq 1) -and ($c1beWallAt.Count -ge 1) -and ($c1beKeptAt[0] -gt $c1beWallAt[-1]) -and ($c1beKeptLine -ceq $c1beKeptWant) -and ($c1beReserved -cnotcontains $c1beKeptFirst) -and
                 ((& $c1beTallyKeys $c1beT1.out) -ceq 'passed failed skipped deselected runnable stored_floor collection_error pytest_exit elapsed_seconds') -and ((& $c1beTallyKeys $c1beT1.out) -ceq (& $c1beTallyKeys $c1beT2.out)) -and
                 ((& $c1beTallyKeys $c1beT2.out) -ceq (& $c1beTallyKeys $c1beB2.out))) `
            -Said ('KEPT lines ' + $c1beKeptAt.Count + ' at [' + ($c1beKeptAt -join ',') + '], WALL lines at [' + ($c1beWallAt -join ',') + ']; the line: ' + $c1beKeptLine + ' | TALLY fields with the flag: ' + (& $c1beTallyKeys $c1beT1.out) + ' | without: ' + (& $c1beTallyKeys $c1beT2.out))
    }

    # (c4) THE GUARD, which needs no venv: three paths, each refused before anything runs.
    [System.IO.File]::WriteAllBytes($c1beInst, $c1beTreeBytes)
    Write-Utf8 -Path $c1beTest -Text $c1bePassTest
    foreach ($c1beBad in @((Join-Path $c1beRoot '.mission-runtime\keep\c4.stdout.txt'), (Join-Path $c1beRoot '.mission-runtime\keep\c4.tally.txt'), (Join-Path $c1beRoot '.mission-runtime\lam\instrument-runs\c4-keep.txt'))) {
        $c1beR = Invoke-C1beRun -Arguments ('-Member all -WallSeconds 20 -KeepPytestOutput "' + $c1beBad + '"') -TimeoutSeconds 120
        $c1beROut = ([string]$c1beR.out -replace "`r", '')
        $c1beRWant = 'FAIL M2 -- -KeepPytestOutput names ' + $c1beBad + ', which the reuse candidates and the census read; nothing was run'
        Add-C1beRow -Label ('(c4) FALSIFIER -KeepPytestOutput ' + (Split-Path -Leaf (Split-Path -Parent $c1beBad)) + '\' + (Split-Path -Leaf $c1beBad) + ': REFUSED before anything runs -- the line "FAIL M2 -- -KeepPytestOutput names <path>, which the reuse candidates and the census read; nothing was run", exit non-zero, no member run (no M1 line, no TALLY), the path not written') `
            -Ok (($null -ne $c1beR.exit) -and ($c1beR.exit -ne 0) -and [regex]::IsMatch($c1beROut, '(?m)^' + [regex]::Escape($c1beRWant) + '$') -and (-not $c1beROut.Contains(' M1 -- ')) -and (-not $c1beROut.Contains('TALLY ')) -and
                 (-not (Test-Path -LiteralPath $c1beBad))) `
            -Said (Get-C1beSaid -Tools 'tree' -Run $c1beR)
    }
  }
}
catch {
    $c1beOk = $false
    $c1beRows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $c1beRows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
finally {
    foreach ($c1beProc in $c1beLive) { try { Stop-C1KTree -Proc $c1beProc } catch { } }
